var ZhuConcisedWords = {"一下子":[["ㄧ ㄒㄧㄚˋ ˙ㄗ","1.一次、一回。[例]他的謊言被拆穿了，這一下子看他怎麼向大家解釋。\n\t\n2.比喻極短的時間。[例]他一下子就把工作做完了。\n\t\n3.附於動詞後面，有略微的意思。[例]他不是故意的，你就忍耐一下子吧。"]],"一些":[["ㄧ ㄒㄧㄝ","表示不定數量的用語：(1) 數量少、一點點。[例]這杯咖啡再加一些糖會更好喝。　(2) 有許多，不是唯一的。[例]在當老師前，我做過一些其他工作。"]],"一切":[["ㄧ ㄑㄧㄝˋ","全部、所有。[例]你儘管放手去做，一切有我負責。"]],"一剎那":[["ㄧ ㄔㄚˋ ㄋㄚˋ","佛經說人的一個念頭之中含有九十個剎那。一剎那指極短的時間。[例]他跑得真快，一剎那就不見了。"]],"一半":[["ㄧ ㄅㄢˋ","二分之一。[例]她把一半獎金捐給育幼院，幫助孤苦無依的兒童。"]],"一命嗚呼":[["ㄧ ㄇㄧㄥˋ ㄨ ㄏㄨ","嗚呼，悲哀的感嘆詞。一命嗚呼指死亡。[例]他病情嚴重，沒多久就一命嗚呼了。"]],"一哄而散":[["ㄧ ㄏㄨㄥ ㄦˊ ㄙㄢˋ","人群在吵鬧中各自散去。[例]警察一到，打架滋事的人便一哄而散。"]],"一塊":[["ㄧ ㄎㄨㄞˋ","一同、一起。[例]他是常和我一塊登山的同伴。"]],"一塵不染":[["ㄧ ㄔㄣˊ ㄅㄨˋ ㄖㄢˇ","非常乾淨，一點灰塵都沒有。[例]她很愛乾淨，家裡總是打掃得一塵不染。"]],"一定":[["ㄧ ㄉㄧㄥˋ","1.肯定、必然。[例]明天上午我一定會準時出席。\n\t\n2.相當的。[例]只要努力，必有一定的成效。"]],"一年半載":[["ㄧ ㄋㄧㄢˊ ㄅㄢˋ ㄗㄞˇ","一年或半年。指一段不短的時間。[例]這艘遠洋漁船每次出海，都得要個一年半載才能回來。"]],"一探究竟":[["ㄧ ㄊㄢˋ ㄐㄧㄡˋ ㄐㄧㄥˋ","看清楚、弄明白。[例]聽到門外一聲巨響，爸爸立刻起身出去一探究竟。"]],"一日千里":[["ㄧ ㄖˋ ㄑㄧㄢ ㄌㄧˇ","形容良馬跑得很快。後比喻進步神速或事業發展得很快。語本《莊子．秋水》。[例]因為覓得好老師，使他的英文程度一日千里，大有進步。"]],"一旦":[["ㄧ ㄉㄢˋ","1.一個早上。[例]一旦一夕\n\t\n2.有一天。表示假設的語氣。[例]我們一旦步入社會，就會知道賺錢的辛苦。\n\t\n3.形容極短暫的時間。[例]他多年來的心血，都因這場火災而毀於一旦。"]],"一會兒":[["ㄧ ㄏㄨㄟˇㄦ","片刻，短暫時間。[例]我猶豫了一會兒，才答應他的請求。"]],"一望無際":[["ㄧ ㄨㄤˋ ㄨˊ ㄐㄧˋ","一眼望去看不著邊際。形容寬廣、遼闊。[例]登上樓頂，是一望無際的藍天白雲，頓時感覺神清氣爽。"]],"一模一樣":[["ㄧ ㄇㄛˊ ㄧ ㄧㄤˋ","完全一樣，好像同一個模子印出來的。[例]這對雙胞胎長得一模一樣，分不清誰是姊姊，誰是妹妹。"]],"一樣":[["ㄧ ㄧㄤˋ","1.相同、相似。[例]一模一樣\n\t\n2.一種。[例]他準備了一樣禮物，要送給媽媽。\n\t\n3.一般。[例]發生這麼嚴重的事，他竟然還像個沒事人一樣，安如泰山。"]],"一決雌雄":[["ㄧ ㄐㄩㄝˊ ㄘ ㄒㄩㄥˊ","比喻互相較量以決定勝敗、高下。語本《史記．卷七．項羽本紀》。[例]他們兩人實力相當，將在這場比賽中一決雌雄。"]],"一目十行":[["ㄧ ㄇㄨˋ ㄕˊ ㄏㄤˊ","形容人閱讀的速度很快。[例]小華學過速讀，所以看書可以一目十行。"]],"一直":[["ㄧ ㄓˊ","1.正朝著某方向。[例]往前一直走，就可以到達你要去的地方。\n\t\n2.持久不變、連續不斷。[例]這場雨從昨天一直下到現在，沒有停過。"]],"一瞬間":[["ㄧ ㄕㄨㄣˋ ㄐㄧㄢ","比喻很短的時間。[例]在風勢的助長下，那棟木造的房子在一瞬間就被大火吞噬了。"]],"一舉兩得":[["ㄧ ㄐㄩˇ ㄌㄧㄤˇ ㄉㄜˊ","比喻一種舉動同時兼收兩利。[例]種花既可美化環境，又可怡情養性，真是一舉兩得。"]],"一般":[["ㄧ ㄅㄢ","1.同樣、同等。[例]他們兩人年紀相同，長得也一般高。\n2.普通、通常。[例]這種道理說來簡單，可是一般人卻都做不到。"]],"一起":[["ㄧ ㄑㄧˇ","1.一塊兒。[例]這是兩碼子事，請不要混在一起。\n\t\n2.案件一宗。[例]警方昨天偵破一起殺人棄屍案，將凶手繩之以法。"]],"一趟":[["ㄧ ㄊㄤˋ","從甲地到乙地一次。[例]這件事很緊急，我必須親自跑一趟。"]],"一輩子":[["ㄧ ㄅㄟˋ ˙ㄗ","一生、一世。[例]他將一輩子都奉獻教育，培育了許多傑出的人才。"]],"一邊":[["ㄧ ㄅㄧㄢ","1.事物的某一面。[例]這個梨子已經爛了一邊。\n\t\n2.一面。表示一個動作與另一個動作同時進行。[例]小明一邊吃飯，一邊看電視。\n\t\n3.一旁。[例]他把公事丟在一邊，自顧聊天去了。"]],"一陣":[["ㄧ ㄓㄣˋ","一段時間的連續動作或狀況。[例]夏天的午後下了一陣大雨，頓時感覺清涼。"]],"一頭":[["ㄧ ㄊㄡˊ","1.頭部突然向下扎或向下倒的動作。[例]潛水夫剛下水，就一頭鑽到水裡去了。\n\t\n2.比喻完全。[例]當她一頭栽進文學領域後便樂此不疲了。\n\t\n3.一端、一方。[例]他們家住在路的那一頭，順著往前走就可以找到了。"]],"一點":[["ㄧ ㄉㄧㄢˇ","1.形容極小或些許。[例]喝咖啡時，我喜歡加一點奶精。\n\t\n2.事物的某一問題或某一方面。[例]這一點是全文的重心，大家可要特別注意。\n\t\n3.輕微的接觸或提示。[例]他的頭腦很好，事情只要稍微一點就明白了。\n\t\n4.一天中的第一時與第十三時。[例]我們搭下午一點的火車北上。"]],"一齊":[["ㄧ ㄑㄧˊ","一同、同時。[例]他與好友約好一齊出遊。"]],"丁字褲":[["ㄉㄧㄥ ㄗˋ ㄎㄨˋ","形狀如丁字的褲子。為特定地區或特定習俗的穿著。如臺灣蘭嶼人民或日本相撲人士等所穿。"]],"七嘴八舌":[["ㄑㄧ ㄗㄨㄟˇ ㄅㄚ ㄕㄜˊ","形容人多口雜，議論紛紜的樣子。[例]一確定出遊日期，眾人便七嘴八舌的開始討論細節。"]],"七彩繽紛":[["ㄑㄧ ㄘㄞˇ ㄅㄧㄣ ㄈㄣ","形容色彩繁多，華麗耀眼。[例]在這歡樂的慶典裡，七彩繽紛的氣球將天空點綴得更加亮麗。"]],"七拼八湊":[["ㄑㄧ ㄆㄧㄣ ㄅㄚ ㄘㄡˋ","隨便胡亂湊合。[例]這份企劃提案七拼八湊，了無新意。"]],"丈夫":[["ㄓㄤˋ ㄈㄨ","1.成年男子的通稱。[例]大丈夫_x000D_\n2.婦人稱與自己有婚姻關係的男子。[例]她與丈夫情感深厚，相知相伴。"]],"丈量":[["ㄓㄤˋ ㄌㄧㄤˊ","以尺或其他工具測量、計算。[例]這塊土地經過丈量後，才發現面積與地政事務所的記載不符。"]],"三振":[["ㄙㄢ ㄓㄣˋ","1.棒壘球比賽時，二好球後，投手再投出好球而打擊者未揮棒，或投手投球後，打擊者揮棒落空，球被捕手捕接，此時，打擊手遭出局判決。[例]這位當家投手功力果然可觀，目前他已三振了十名打者。\n2.比喻被取消參與事務的權力。[例]這件工程他已被三振，無法再參與了。"]],"三明治":[["ㄙㄢ ㄇㄧㄥˊ ㄓˋ","一種西方簡餐。即在數片土司麵包間夾以肉類、蔬菜、沙拉等配料而成。相傳十八世紀時，英國第四代Sandwich伯爵為了通宵賭博而創，現已普遍當作早餐或點心食用。[例]以三明治當早點，既營養又方便。§英sandwich　△三味治、三文治"]],"三更半夜":[["ㄙㄢ ㄍㄥ ㄅㄢˋ ㄧㄝˋ","指深夜。[例]小明精力旺盛，經常玩到三更半夜還不去睡覺。　△半夜三更"]],"三角板":[["ㄙㄢ ㄐㄧㄠˇ ㄅㄢˇ","繪圖用具。通常兩片為一組，一片為等腰直角三角形，另一片為六十度、三十度與九十度的直角三角形。 　△三角尺"]],"三足鼎立":[["ㄙㄢ ㄗㄨˊ ㄉㄧㄥˇ ㄌㄧˋ","三方的勢力如鼎足般對峙而立。[例]因為這家電信公司的加入，打破了原本通訊市場三足鼎立的局面。"]],"三餐不繼":[["ㄙㄢ ㄘㄢ ㄅㄨˋ ㄐㄧˋ","形容生活貧困，連吃飯都有一餐沒一餐的。[例]他因生意失敗，導致全家三餐不繼。"]],"上午":[["ㄕㄤˋ ㄨˇ","夜半一時至正午十二時。一般則以清晨至正午十二時為上午。[例]明天上午，爸爸將帶我們去動物園玩。"]],"上吐下瀉":[["ㄕㄤˋ ㄊㄨˋ ㄒㄧㄚˋ ㄒㄧㄝˋ","同時出現嘔吐及腹瀉的症狀。[例]他因吃了不潔的東西而上吐下瀉。"]],"上妝":[["ㄕㄤˋ ㄓㄨㄤ","化妝打扮。[例]她這次演一位六十歲老人，每天光是上妝就得花上一、兩個小時。"]],"上學":[["ㄕㄤˋ ㄒㄩㄝˊ","到校上課或入學念書。[例]小弟弟每天都快快樂樂的去上學。"]],"上岸":[["ㄕㄤˋ ㄢˋ","登上岸邊。[例]海水已開始漲潮了，趕快上岸吧！"]],"上帝":[["ㄕㄤˋ ㄉㄧˋ","基督教徒對所信仰、崇拜的神的稱呼。[例]他向上帝禱告，希望母親的病能早日痊癒。　△天主"]],"上揚":[["ㄕㄤˋ ㄧㄤˊ","上漲、往上攀升。[例]颱風過後，菜價又再度上揚。"]],"上方":[["ㄕㄤˋ ㄈㄤ","相對位置較高的地方。[例]他在書桌上方掛了一盞護目燈。"]],"上映":[["ㄕㄤˋ ㄧㄥˋ","在銀幕上放映。[例]這部電影上映後，賣座鼎盛，打破了國片的票房紀錄。"]],"上桌":[["ㄕㄤˋ ㄓㄨㄛ","1.把食物端上桌子。[例]菜已經上桌了，快趁熱吃吧！\n2.就位進食。[例]孩子們！快上桌，吃飽了好去做功課。"]],"上漲":[["ㄕㄤˋ ㄓㄤˇ","水位或物價升高。[例]颱風過境，蔬果的價格又要上漲了。"]],"上班":[["ㄕㄤˋ ㄅㄢ","在規定的時間，到固定的場所工作。[例]他畢業後就到這家公司上班，一直到現在。"]],"上當":[["ㄕㄤˋ ㄉㄤˋ","吃虧、受騙。[例]他常信口雌黃，你千萬別上當。"]],"上網":[["ㄕㄤˋ ㄨㄤˇ","指使用者透過連線模式，將個人電腦連接上網站。"]],"上街":[["ㄕㄤˋ ㄐㄧㄝ","到街上去。[例]年關將至，市區裡擠滿了上街採購的人群。"]],"上課":[["ㄕㄤˋ ㄎㄜˋ","老師到教室授課或學生到教室學習課業。[例]上課時要專心聽講。"]],"下令":[["ㄒㄧㄚˋ ㄌㄧㄥˋ","下達命令。[例]指揮官下令全體官兵取消休假，回艦待命。"]],"下午":[["ㄒㄧㄚˋ ㄨˇ","中午以後到黃昏以前的一段時間。[例]那天下午我有事，所以沒有去參加同學會。"]],"下午茶":[["ㄒㄧㄚˋ ㄨˇ ㄔㄚˊ","本指下午四點至五點時，所吃的茶點。為流行於西洋社會的正規活動。後比喻午後的社交活動或休息時間。[例]公司決定推動下午茶，以提振工作士氣。"]],"下去":[["ㄒㄧㄚˋ ㄑㄩˋ","1.用在動詞後，強調由高處往低處。[例]因為電梯故障，大家只好從樓梯走下去。\n2.用在動詞後，表示事情繼續進行。[例]只要他持之以恆的做下去，一定會成功！\n3.用在形容詞後，表示程度漸漸增加。[例]天氣要是再熱下去，真的會把人烤焦！"]],"下屬":[["ㄒㄧㄚˋ ㄕㄨˇ","手下、部屬。[例]他為人認真負責，下屬都很尊敬他。"]],"下次":[["ㄒㄧㄚˋ ㄘˋ","下回，緊接本次以後的一次。[例]有了這次慘痛的教訓，我相信他下次再也不敢開快車了。"]],"下沉":[["ㄒㄧㄚˋ ㄔㄣˊ","往下陷落。[例]這艘船的船底破了一個大洞，水不斷湧入，船身逐漸下沉。"]],"下落":[["ㄒㄧㄚˋ ㄌㄨㄛˋ","1.自上向下掉落。[例]雪花片片下落，不一會兒窗外就變成一片銀色世界。\n2.著落、去處、蹤跡。[例]他失蹤一個月了，至今依然下落不明。"]],"下襬":[["ㄒㄧㄚˋ ㄅㄞˇ","上衣、長袍和裙子等的下緣部分。[例]騎車時要小心，千萬別讓下襬被捲到車輪裡。"]],"下課":[["ㄒㄧㄚˋ ㄎㄜˋ","教學活動結束。[例]由於颱風來襲，今天各級學校都提早下課。"]],"下跌":[["ㄒㄧㄚˋ ㄉㄧㄝˊ","下降、滑落。[例]近來蔬菜生產過剩，價格大幅下跌。"]],"下降":[["ㄒㄧㄚˋ ㄐㄧㄤˋ","自高到低、從多到少。[例]這幾天寒流來襲，氣溫突然下降。"]],"下雨":[["ㄒㄧㄚˋ ㄩˇ","水滴自大氣中掉落到地球表面。[例]連續幾個月沒有下雨，河川都快乾涸了。"]],"下雪":[["ㄒㄧㄚˋ ㄒㄩㄝˇ","雪花飄落。[例]合歡山下雪時，總是吸引許多遊客上山賞玩。"]],"不一樣":[["ㄅㄨˋ ㄧ ㄧㄤˋ","1.樣式不同。[例]這兩套衣服花色相近，但不一樣。\n\t\n2.不同樣式。"]],"不久":[["ㄅㄨˋ ㄐㄧㄡˇ","短暫的時間。[例]他躺到床上不久就睡著了。"]],"不乖":[["ㄅㄨˋ ㄍㄨㄞ","不聽話、不守規矩。[例]小孩子不乖，父母、老師們要分析不乖的原因，耐心教導。"]],"不但":[["ㄅㄨˋ ㄉㄢˋ","不僅、不只。[例]對於我的魯莽舉動，他不但不生氣，反而還好言相勸。"]],"不偏不倚":[["ㄅㄨˋ ㄆㄧㄢ ㄅㄨˋ ㄧˇ","一點也沒有偏差。[例]他一箭射出，不偏不倚的正中紅心。"]],"不停":[["ㄅㄨˋ ㄊㄧㄥˊ","持續、繼續。[例]做為一個現代知識分子要不停的吸取新知。"]],"不僅":[["ㄅㄨˋ ㄐㄧㄣˇ","1.不止、不單。[例]這不僅是他個人的意思，也是全體同學的想法。\n2.不但。[例]艱困的處境不僅沒讓他退縮，反而使他愈戰愈勇。"]],"不准":[["ㄅㄨˋ ㄓㄨㄣˇ","禁止、不允許。[例]此處不准張貼廣告，違者罰款。"]],"不凡":[["ㄅㄨˋ ㄈㄢˊ","出色、與眾不同。[例]他的能力不錯，剛起步就表現不凡。"]],"不切實際":[["ㄅㄨˋ ㄑㄧㄝˋ ㄕˊ ㄐㄧˋ","不符合現實狀況或需要。[例]他腦子裡想的都是些不切實際的怪點子。"]],"不勝枚舉":[["ㄅㄨˋ ㄕㄥ ㄇㄟˊ ㄐㄩˇ","不能一一列舉出來。形容數量太多。[例]他為人忠厚老實，多才多藝，優點多得不勝枚舉。"]],"不可能":[["ㄅㄨˋ ㄎㄜˇ ㄋㄥˊ","不會有可能。[例]天無絕人之路，事情不可能完全沒有轉機。"]],"不同":[["ㄅㄨˋ ㄊㄨㄥˊ","不一樣。[例]迥然不同、方法不同"]],"不吝賜教":[["ㄅㄨˋ ㄌㄧㄣˋ ㄙˋ ㄐㄧㄠˋ","請人多加指教的客套話。[例]有什麼需要改進的地方，敬請不吝賜教。"]],"不在":[["ㄅㄨˋ ㄗㄞˋ","1.在的相反語，專指不在家或泛指不在某處。[例]他現在人不在，可能到學校去了。\n2.去世。[例]等他獲得家人音訊時，才知雙親都已不在多年了。\n3.不在於、不著重於。[例]山不在高，有仙則名；水不在深，有龍則靈。（唐．劉禹錫〈陋室銘〉）"]],"不夠":[["ㄅㄨˋ ㄍㄡˋ","不足，未達到所需求的標準。[例]這次活動因經費不夠而被迫取消。"]],"不妥":[["ㄅㄨˋ ㄊㄨㄛˇ","不恰當、不宜。[例]當初雙方雖是口頭約定，但中途毀約恐怕不妥。"]],"不妨":[["ㄅㄨˋ ㄈㄤˊ","1.可以。[例]如果有空，不妨到舍下坐坐。\n2.沒關係、不礙事。[例]不妨，這只是一點小傷。"]],"不得已":[["ㄅㄨˋ ㄉㄜˊ ㄧˇ","無可奈何、必須如此。[例]他因家遭變故，不得已只好中途休學了。"]],"不慎":[["ㄅㄨˋ ㄕㄣˋ","不小心、不留意、疏忽。[例]這個案子由於他處理不慎，使得公司損失慘重。"]],"不懂":[["ㄅㄨˋ ㄉㄨㄥˇ","不明白、不了解。[例]你若有不懂的地方，可以向其他人請教。"]],"不懷好意":[["ㄅㄨˋ ㄏㄨㄞˊ ㄏㄠˇ ㄧˋ","心裡面有不好的念頭。[例]那個人不懷好意，你可得當心點兒！"]],"不拘小節":[["ㄅㄨˋ ㄐㄩ ㄒㄧㄠˇ ㄐㄧㄝˊ","不被生活上的小規矩所拘束。[例]他個性豪爽，不拘小節。"]],"不敢":[["ㄅㄨˋ ㄍㄢˇ","1.沒有勇氣、沒有膽量。[例]他一直站在門外，不敢進來。\n2.謙虛之詞，表示承擔不起。[例]不敢！不敢！是您過獎了。"]],"不斷":[["ㄅㄨˋ ㄉㄨㄢˋ","1.不能截斷。[例]愁緒有如亂髮，剪不斷，理還亂。\n2.持續不停。[例]連綿不斷、笑聲不斷"]],"不易":[["ㄅㄨˋ ㄧˋ","1.困難、不容易。[例]這件差事非常棘手，恐怕不易如期完成。\n2.不變。[例]百年不易、古今不易"]],"不是":[["ㄅㄨˋ ㄕˋ","1.錯誤、過失。[例]他年紀小不懂事，假使有什麼不是，您就原諒他吧！\n2.不然。[例]其實不是，你別誤會他！\n3.助詞，表示反問的語氣。[例]他是你的高中老師不是？"]],"不曾":[["ㄅㄨˋ ㄘㄥˊ","從不。[例]雖然責任相當重，但他卻不曾埋怨過。"]],"不朽":[["ㄅㄨˋ ㄒㄧㄡˇ","不會磨滅，比喻永存。[例]不朽名言、永垂不朽"]],"不止":[["ㄅㄨˋ ㄓˇ","1.不停，繼續不斷。[例]流血不止\n2.超出某一範圍或數目。[例]他說謊已經不止一次了，你可別輕易相信他的話。"]],"不深":[["ㄅㄨˋ ㄕㄣ","淺、薄、淡。[例]水不深、交情不深、顏色不深"]],"不理":[["ㄅㄨˋ ㄌㄧˇ","1.不理會。[例]他正在氣頭上，不理他就沒事了。\n2.不處理。[例]不理公務、不理家事"]],"不甘示弱":[["ㄅㄨˋ ㄍㄢ ㄕˋ ㄖㄨㄛˋ","不甘心表現得比別人差。[例]面對對手頻頻得分，我們也不甘示弱，予以反擊，最後終於贏了這場比賽。"]],"不知所措":[["ㄅㄨˋ ㄓ ㄙㄨㄛˇ ㄘㄨㄛˋ","不知道怎麼辦才好。[例]火警發生時，許多人都慌亂不已，不知所措。"]],"不禁":[["ㄅㄨˋ ㄐㄧㄣ","1.控制不住、不由自主。[例]在熱天中走得滿身汗，一進冷氣房就不禁打了個哆嗦。\n2.承受不住、經受不起。[例]老年人不禁摔，要特別留意安全。"]],"不管":[["ㄅㄨˋ ㄍㄨㄢˇ","1.不看顧。[例]為人子女拋下年邁的父母不管，這種行為實在令人髮指。\n2.不理會。[例]他不管大家的勸告，仍一意孤行。\n3.不論。[例]不管遇到什麼挫折，不要輕言放棄理想。\n4.不顧忌、不理會。[例]瞧他也不管令尊還站在一旁，竟然就教訓起你來了。"]],"不置可否":[["ㄅㄨˋ ㄓˋ ㄎㄜˇ ㄈㄡˇ","不表示同意，也不表示反對。[例]每當我們徵詢他的意見，他總是不置可否。"]],"不肯":[["ㄅㄨˋ ㄎㄣˇ","不願意。[例]不肯就範、執意不肯"]],"不能":[["ㄅㄨˋ ㄋㄥˊ","1.無法、不能夠。[例]他家裡有事，今天不能來了。\n2.能力不足、沒有能力。[例]這事情沒做好的關鍵不是不能，只是做的人根本沒有用心。"]],"不著邊際":[["ㄅㄨˋ ㄓㄨㄛˊ ㄅㄧㄢ ㄐㄧˋ","說話、做事不切實際或離題太遠。[例]他說話一向天馬行空，不著邊際。"]],"不行":[["ㄅㄨˋ ㄒㄧㄥˊ","1.不可、不允許。[例]明天就要考試了，今晚只可看書，看電視可不行。\n2.病情嚴重，將近死亡。[例]他已經臥病三年，快要不行了。\n3.不好、不中用。[例]我的英文不行，千萬別找我去和外國人交談。\n4.不推行。[例]法令不行，公理不彰。"]],"不見":[["ㄅㄨˋ ㄐㄧㄢˋ","1.沒看見。[例]前不見古人，後不見來者。（唐．陳子昂〈登幽州臺歌〉）\n2.消失。[例]彩虹不見了！\n3.不願見面。[例]像他那種不守信用的人，我不見！"]],"不該":[["ㄅㄨˋ ㄍㄞ","不應當。[例]做人要惜福，不該浪費。"]],"不詳":[["ㄅㄨˋ ㄒㄧㄤˊ","1.不詳細、不清楚。[例]姓名不詳、父母不詳、數目不詳\n2.書信用語，用於文末，表示不細說。[例]言不盡意，餘刪，不詳。"]],"不論":[["ㄅㄨˋ ㄌㄨㄣˋ","1.不管。[例]不論遇到什麼困難，不要輕易畏怯退縮。\n2.不說、不議論。[例]姑且不論誰對誰錯，出了這種差錯大家都有責任。\n3.不計較、不講求。[例]她只要有電影可看，至於是國片或洋片就不論了。"]],"不遺餘力":[["ㄅㄨˋ ㄧˊ ㄩˊ ㄌㄧˋ","不保留剩餘的力氣，即竭盡全力。[例]王先生對於社會公益總是熱心參與，不遺餘力。"]],"不錯":[["ㄅㄨˋ ㄘㄨㄛˋ","1.對、正確。[例]天助自助，這句話說得一點也不錯。\n2.好、不壞。[例]今天天氣很不錯！"]],"不鏽鋼":[["ㄅㄨˋ ㄒㄧㄡˋ ㄍㄤ","含鉻百分之十二至十八、鎳百分之七至十、碳百分之零點二以下的鋼，因具耐蝕、不易生鏽的特性，故稱為「不鏽鋼」。"]],"丑角":[["ㄔㄡˇ ㄐㄩㄝˊ","戲劇中表演滑稽逗趣的腳色。[例]丑角的表演方式往往較為誇張逗趣。　△丑兒、丑腳兒"]],"且慢":[["ㄑㄧㄝˇ ㄇㄢˋ","暫且慢著，不用著急。[例]且慢出門，先檢查東西是否帶齊了。"]],"世仇":[["ㄕˋ ㄔㄡˊ","歷代有仇恨的人或家族。[例]這兩家是世仇，中間存有的怨恨、誤會一時之間恐難化解。"]],"世界":[["ㄕˋ ㄐㄧㄝˋ","1.世上、人間。[例]大千世界、浮華世界\n2.地球上所有的國家、地方。[例]世界觀、環遊世界、世界大戰\n3.自成體系的組織、現象。[例]科學世界、兒童世界\n4.佛教上指：(1) 以須彌山為中心，同一個日、月所照的四天下。　(2) 一尊佛所教化的國土。[例]華嚴世界"]],"世紀":[["ㄕˋ ㄐㄧˋ","計算年代的單位。西方各國以耶穌誕生那年做為紀元，每經一百年為一世紀。[例]蒸氣機的發明，引發了十八世紀末西方的工業革命。"]],"世襲":[["ㄕˋ ㄒㄧˊ","封建時代，爵位可以世代傳給子孫的制度。[例]夏禹將王位傳給兒子啟，開了君主世襲的先例。"]],"丘陵":[["ㄑㄧㄡ ㄌㄧㄥˊ","1.土山。泛指高低不平的地形。[例]我的家鄉四周丘陵環繞，宛如與世隔絕的世外桃源。\n2.地理學上指高度次於山岳的起伏地形。[例]地表的高低形態，大致可分為高原、山岳、丘陵、盆地和平原五種。"]],"丞相":[["ㄔㄥˊ ㄒㄧㄤˋ","古時輔佐天子處理國事的最高行政官員。多由一人擔任，有時亦由二人或多人共同掌政。秦漢以後設置，明洪武十三年後廢置。[例]唐太宗任用房玄齡、杜如晦來擔任丞相，因此締造了清明的政治。"]],"丟三落四":[["ㄉㄧㄡ ㄙㄢ ㄌㄚˋ ㄙˋ","形容人因為馬虎或健忘，不是忘了這個，就是忘了那個。[例]他總是丟三落四、忘東忘西的，真拿他沒辦法！"]],"丟掉":[["ㄉㄧㄡ ㄉㄧㄠˋ","1.丟棄。[例]請把這些雜物拿去丟掉。\n2.遺失。[例]為了找尋丟掉的錢包，他已在路上來回走了好幾趟。"]],"丟臉":[["ㄉㄧㄡ ㄌㄧㄢˇ","出醜、失面子。[例]如果怕失敗丟臉而不敢嘗試，就永無成功的機會。"]],"並且":[["ㄅㄧㄥˋ ㄑㄧㄝˇ","而且。通常連接兩個句子，是用以表示平列或進一層意義的連詞。[例]對於教導學生，家長和老師要建立共識，並且隨時保持聯絡。"]],"並列":[["ㄅㄧㄥˋ ㄌㄧㄝˋ","1.並排齊列，位置不分前後或主次。[例]每隔一段距離，就派兩位士兵並列守衛。_x000D_\n2.同時存在。引申有地位相當、勢力相等的意義。[例]這次考試，他們兩人並列榜首。"]],"並駕齊驅":[["ㄅㄧㄥˋ ㄐㄧㄚˋ ㄑㄧˊ ㄑㄩ","1.車駕不分前後，同列而行。[例]那兩輛車正並駕齊驅的在高速公路上奔馳著。\n2.比喻雙方實力相當，不分上下。[例]我國整體工業水準將邁入先進國家之列，和各國並駕齊驅。"]],"丫鬟":[["ㄧㄚ ㄏㄨㄢˊ","婢女。因其頭髮梳成兩個髻，就像分叉的樹枝，故得名。[例]古時清寒的家庭，常將女兒送至大戶人家當丫鬟。"]],"中午":[["ㄓㄨㄥ ㄨˇ","白天十二點左右的時間。[例]這所小學的全體師生每天中午都在校中共進營養午餐。"]],"中型":[["ㄓㄨㄥ ㄒㄧㄥˊ","中等規格、規模。[例]中型電腦、中型貨櫃"]],"中央":[["ㄓㄨㄥ ㄧㄤ","1.中間或中心地方。[例]水面中央一群白鷺鷥正鼓翼飛起。\n2.國家或團體的最高指導機關。[例]黨中央、中央集權"]],"中心":[["ㄓㄨㄥ ㄒㄧㄣ","1.正中央的位置。[例]車站位於本鎮的中心。\n2.核心，事物的主體。[例]中心思想\n3.泛指某一具有特定性質或樞紐地位的地點。[例]地方圖書館是一般鄉鎮的文化中心。"]],"中意":[["ㄓㄨㄥˋ ㄧˋ","滿意，合自己的心意。[例]這輛車在款式和顏色上，我都很中意。"]],"中斷":[["ㄓㄨㄥ ㄉㄨㄢˋ","中途停止或斷絕。[例]颱風直撲臺灣東部，風狂雨橫，花東地區對外交通因而中斷。"]],"中暑":[["ㄓㄨㄥˋ ㄕㄨˇ","長時間暴露於太陽下，或因身體感受暑氣，無法排解而引起的病症。患者會出現痙攣、昏睡、體溫升高等症狀。[例]夏天氣溫高，站在大太陽底下太久，就很容易中暑。"]],"中毒":[["ㄓㄨㄥˋ ㄉㄨˊ","因食物不潔或某些有害物質進入人體，導致生理機能發生障礙或死亡的現象。患者一般會有噁心、嘔吐、腹瀉、頭痛、暈眩等症狀。[例]熱水器不可安置在室內，以免瓦斯外漏發生一氧化碳中毒。"]],"中獎":[["ㄓㄨㄥˋ ㄐㄧㄤˇ","持有的票券、統一發票等號碼與開獎號碼相同，而獲得獎金或獎品。[例]購物索取統一發票，既可防止商家逃漏稅又有機會中獎，真是一舉兩得。"]],"中等":[["ㄓㄨㄥ ㄉㄥˇ","1.介於上等和下等、高等和初等之間的等級。[例]中等貨色、中等材質\n2.形容身材不高不矮。[例]他的相貌平凡，個兒中等，算不上俊男。"]],"中肯":[["ㄓㄨㄥˋ ㄎㄣˇ","言詞切中要點，恰到好處。[例]他所提出的看法十分中肯，博得與會人士一致讚賞。"]],"中途":[["ㄓㄨㄥ ㄊㄨˊ","1.半路。[例]她決定中途下車去拜訪多年不見的老友。\n2.指人生或事情在進行的過程中。[例]他在會議中途接到一通電話之後就匆忙離開，不知 發生了什麼事？"]],"中選":[["ㄓㄨㄥˋ ㄒㄩㄢˇ","被選上。[例]好幾位同事競爭業務經理，結果小王中選了。"]],"中間":[["ㄓㄨㄥ ㄐㄧㄢ","1.中央，居中的位置。[例]地球運行到太陽和月球中間就會產生月食。\n2.裡面。[例]這個遊行隊伍中間，不乏高級知識分子。"]],"主人":[["ㄓㄨˇ ㄖㄣˊ","1.擁有主權的人。[例]他雖貴為主人，但對待僕人卻如親人一般。\n2.作東款待賓客的人。相對於賓客而言。[例]小孩子嘴饞，等不及主人開席就先吃了起來。"]],"主人翁":[["ㄓㄨˇ ㄖㄣˊ ㄨㄥ","1.主人。[例]兒童是國家未來的主人翁。\n2.主要人物。[例]這部小說中的主人翁是一位年邁六十的老人，以及他的小孫女。"]],"主動":[["ㄓㄨˇ ㄉㄨㄥˋ","自動自發，照自己的意思進行。[例]姊姊時常主動幫忙家務，減輕母親的負擔。"]],"主婦":[["ㄓㄨˇ ㄈㄨˋ","操持家務的婦女。[例]家庭主婦"]],"主意":[["ㄓㄨˇ ㄧˋ","想法、念頭。[例]她已經打定主意要在近日北上謀職。"]],"主持":[["ㄓㄨˇ ㄔˊ","1.主導、管理。[例]公司業務在總經理主持之下已逐漸好轉。\n2.主張、維護。[例]主持正義、主持公道"]],"主播":[["ㄓㄨˇ ㄅㄛˋ","最主要的播報員。多指電視新聞而言。[例]她口齒清晰，而且頗具親和力，因此不到三年便成了新聞主播。"]],"主管":[["ㄓㄨˇ ㄍㄨㄢˇ","1.負責管理。[例]他在公司裡主管貨物的進出口和產品銷售等事宜。\n2.主持事務，負責管理某一單位的人。[例]李先生是本公司生產部門的主管。"]],"主要":[["ㄓㄨˇ ㄧㄠˋ","最重要的。[例]主要原因、主要任務、主要目的"]],"主角":[["ㄓㄨˇ ㄐㄩㄝˊ","1.文藝作品或戲劇、電影等表演中的主要角色。[例]這部電影起用了許多新人來擔任主角。\n\t\n2.主要人物。[例]她打扮得相當豔麗，儼然成為今晚宴會的主角。"]],"主講":[["ㄓㄨˇ ㄐㄧㄤˇ","1.擔任講授或講演。[例]陳教授在大學中主講中國文學史的課程。\n2.講演或講授的人。[例]林教授受邀擔任這場文化講座的主講。"]],"主題":[["ㄓㄨˇ ㄊㄧˊ","文藝作品、會議、談話等的主要內容、中心思想。[例]今天開會所要討論的主題是畢業旅行。"]],"乍然":[["ㄓㄚˋ ㄖㄢˊ","突然。[例]午後乍然下起雷陣雨，讓路上的行人措手不及。"]],"乍現":[["ㄓㄚˋ ㄒㄧㄢˋ","突然出現、顯現。[例]乍隱乍現"]],"乍看":[["ㄓㄚˋ ㄎㄢˋ","突然看見或第一眼見到。[例]這些蠟像乍看之下與真人無異。"]],"乏人問津":[["ㄈㄚˊ ㄖㄣˊ ㄨㄣˋ ㄐㄧㄣ","沒有人洽詢或探問。[例]這棟預售屋已經推出多時，但一直乏人問津。"]],"乖乖":[["ㄍㄨㄞ ㄍㄨㄞ","1.安靜、順從。_x000D_\n2.表親暱的稱呼。_x000D_"],["ㄍㄨㄞ ˙ㄍㄨㄞ","助詞。表示驚嘆。[例]乖乖！這師傅的手藝還真不賴！"]],"乖巧":[["ㄍㄨㄞ ㄑㄧㄠˇ","懂事聽話而又聰明機伶。[例]他是一個乖巧的孩子，很討人喜歡。"]],"乖謬":[["ㄍㄨㄞ ㄇㄧㄡˋ","荒謬反常，違背情理。[例]這個人一向行事乖謬，所以大家都不敢跟他共事。"]],"乘人之危":[["ㄔㄥˊ ㄖㄣˊ ㄓ ㄨㄟˊ","趁人有危難時加以要挾、迫害。[例]這種乘人之危以謀取利益的行為，真令人不齒。"]],"乘客":[["ㄔㄥˊ ㄎㄜˋ","委付駕駛的交通工具使用人。[例]公車來了，乘客依序上車。"]],"乘法":[["ㄔㄥˊ ㄈㄚˇ","一種數學運算方式。求一數為某數的若干倍。如 5×6＝30。"]],"乞丐":[["ㄑㄧˇ ㄍㄞˋ","以索求食物、錢財維生的人。[例]那名乞丐經過社會局的救助之後，已有固定的工作與住所了。"]],"乞求":[["ㄑㄧˇ ㄑㄧㄡˊ","懇求、請求。[例]他為遲到一事再三的乞求朋友諒解。"]],"乞討":[["ㄑㄧˇ ㄊㄠˇ","向人乞求索討。[例]這名街友平日居無定所，只靠乞討維生。"]],"乳白色":[["ㄖㄨˇ ㄅㄞˊ ㄙㄜˋ","像乳汁般的白顏色。[例]這件乳白色的襯衫沾了一處油漬，很難清洗。"]],"乾咳":[["ㄍㄢ ㄎㄜˊ","咳嗽而無痰唾，往往有聲無力。[例]圖書館中安靜無聲，只偶爾聽到幾聲乾咳的聲音。"]],"乾嚎":[["ㄍㄢ ㄏㄠˊ","哭時有聲而無淚。[例]乾嚎不已"]],"乾坤":[["ㄑㄧㄢˊ ㄎㄨㄣ","《易經》上的兩個卦名，象徵天地、陰陽、日月等。[例]乾坤萬象、扭轉乾坤"]],"乾旱":[["ㄍㄢ ㄏㄢˋ","因長期不下雨或水源不足，導致土壤、氣候太過乾燥的現象。[例]由於連續乾旱，農作物的收成大受影響。"]],"乾枯":[["ㄍㄢ ㄎㄨ","1.草木缺少水分或營養而枯黃的樣子。[例]冬天來臨時，樹上的葉子會漸漸乾枯而掉落。\n2.水一點也不剩。[例]這條河因上游水源遭到破壞而呈現乾枯的現象。"]],"乾淨":[["ㄍㄢ ㄐㄧㄥˋ","1.清潔。[例]這間房子打掃得非常乾淨。\n2.沒有剩餘。[例]他餓得將所有的菜都吃乾淨了。\n3.形容人長相清秀。[例]她長得蠻乾淨，笑起來頗迷人。\n4.形容事情處理圓滿。[例]他的手段高明，把這件棘手的事處理得很乾淨。\n5.清白。[例]他的手腳一向不乾淨，你最好防著他點。\n6.了結、完結。[例]如果大家不能同心協力，倒不如拆夥乾淨。"]],"乾燥":[["ㄍㄢ ㄗㄠˋ","缺乏水分。[例]冬天時空氣乾燥，容易發生火災，所以要特別小心。"]],"乾瞪眼":[["ㄍㄢ ㄉㄥˋ ㄧㄢˇ","形容在一旁焦急，卻又幫不上忙。[例]妻子生產時，他在產房外急得乾瞪眼。"]],"乾脆":[["ㄍㄢ ㄘㄨㄟˋ","1.爽快、簡捷。[例]他的個性豪爽，不論說話、做事都很乾脆。\n2.索性。[例]如果他一直沒有消息，你乾脆直接去找他。"]],"了不起":[["ㄌㄧㄠˇ ㄅㄨˋ ㄑㄧˇ","1.非常傑出。[例]貝多芬真是一位了不起的作曲家。\n2.頂多、至多也不過。表示極限之意。[例]一次失敗不足為懼，了不起下次加倍努力就是了。"]],"了結":[["ㄌㄧㄠˇ ㄐㄧㄝˊ","完結、解決。[例]經過多次的折中協調，事情終於圓滿的了結。"]],"了解":[["ㄌㄧㄠˇ ㄐㄧㄝˇ","1.明白、知曉。[例]老師講得很清楚，所以每位學生都能澈底了解。　△瞭解\n\t\n2.打聽、調查。[例]這件事究竟怎麼一回事？可否請你去了解一下。"]],"事實":[["ㄕˋ ㄕˊ","事情的真實情形。[例]此案外面的傳言很多，事實並非如此。"]],"事必躬親":[["ㄕˋ ㄅㄧˋ ㄍㄨㄥ ㄑㄧㄣ","凡事一定親自去做。[例]他細心謹慎，做事一向事必躬親。"]],"事情":[["ㄕˋ ㄑㄧㄥˊ","事物的實際情形，包括人類一切行為及自然界所有的現象或活動。[例]只要是正當的事情，都可以大膽去做。"]],"事蹟":[["ㄕˋ ㄐㄧ","個人或團體曾經做過的事情。[例]偉人的事蹟，足為後人典範。"]],"互助":[["ㄏㄨˋ ㄓㄨˋ","互相幫助。[例]互助合作"]],"互換":[["ㄏㄨˋ ㄏㄨㄢˋ","互相交換、調換。[例]畢業前夕，同學們彼此互換紀念品。"]],"互相":[["ㄏㄨˋ ㄒㄧㄤ","指彼此平等對待的關係。[例]互相尊重、互相照顧、互相猜忌"]],"五彩繽紛":[["ㄨˇ ㄘㄞˇ ㄅㄧㄣ ㄈㄣ","形容色彩繁多，鮮豔絢麗。[例]天空中五彩繽紛的煙火，令人目不暇給。"]],"五線譜":[["ㄨˇ ㄒㄧㄢˋ ㄆㄨˇ","在五條等距平行橫線上標記音符，以表示旋律高低、節奏等性質的樂譜。[例]老師在音樂課上教小朋友認識五線譜，以奠定基礎樂理。　◎"]],"五臟":[["ㄨˇ ㄗㄤˋ","心、肝、脾、肺、腎五種器官。亦泛指各種內臟。[例]麻雀雖小，五臟俱全。"]],"井井有條":[["ㄐㄧㄥˇ ㄐㄧㄥˇ ㄧㄡˇ ㄊㄧㄠˊ","形容整齊有秩序的樣子。[例]他的藏書很多，但都分門別類，整理得井井有條。"]],"井然有序":[["ㄐㄧㄥˇ ㄖㄢˊ ㄧㄡˇ ㄒㄩˋ","條理分明而有秩序。[例]他精明能幹，凡事都能料理得井然有序。"]],"些微":[["ㄒㄧㄝ ㄨㄟˊ","1.少許。[例]他以些微分數之差落榜，實在讓人覺得可惜。\n2.稍微、略微。[例]只感到些微的不適，難怪他直說不礙事。"]],"亡魂":[["ㄨㄤˊ ㄏㄨㄣˊ","1.死者的靈魂。[例]超渡亡魂\n2.失魂落魄。比喻非常驚駭。[例]亡魂失魄、亡魂喪膽"]],"交往":[["ㄐㄧㄠ ㄨㄤˇ","交際往來。[例]經過三年的交往，他們倆已經決定在今年元旦舉行婚禮。"]],"交換":[["ㄐㄧㄠ ㄏㄨㄢˋ","相互調換。[例]交換學生、交換心得"]],"交流":[["ㄐㄧㄠ ㄌㄧㄡˊ","1.江河匯合而流。[例]新店溪在江子翠與大漢溪交流後，形成淡水河主流。\n2.比喻相互來往。[例]現代通訊設備發達，全球各地的交流愈趨頻繁密集。"]],"交織":[["ㄐㄧㄠ ㄓ","縱橫交錯。[例]各式各樣的煙火在空中交織成美麗的圖案。"]],"交談":[["ㄐㄧㄠ ㄊㄢˊ","互相談話。[例]我們一路交談著，不知不覺中已經到達目的地了。"]],"交通":[["ㄐㄧㄠ ㄊㄨㄥ","汽車、船舶、飛機等各種運輸工具在陸地、海上或空中的往來。亦指郵電信函等來往。[例]交通的發達，使得世界各國之間的往來，日益便捷。"]],"亦然":[["ㄧˋ ㄖㄢˊ","也是如此。[例]要了解一個人必須知道他的過去，要了解一個國家亦然。"]],"享受":[["ㄒㄧㄤˇ ㄕㄡˋ","享有、受用。[例]年紀大的長輩，最需要子女適度地關懷，最欣慰的則是享受天倫之樂。"]],"京城":[["ㄐㄧㄥ ㄔㄥˊ","首都、國都。[例]長安的地理位置優異，因而成為中國很多朝代的京城所在。"]],"亮光":[["ㄌㄧㄤˋ ㄍㄨㄤ","明亮的光線。[例]黑暗的夜空，偶而見到一道亮光飛越而下，那便是流星的殞落。"]],"亮晶晶":[["ㄌㄧㄤˋ ㄐㄧㄥ ㄐㄧㄥ","閃亮耀眼的樣子。[例]晴朗的夜空裡，布滿了亮晶晶的小星星。"]],"亮麗":[["ㄌㄧㄤˋ ㄌㄧˋ","光亮美麗。[例]她穿的衣服色彩鮮明，看起來十分亮麗。"]],"人偶":[["ㄖㄣˊ ㄡˇ","以各種材質製成的人形玩偶。[例]我朋友喜歡收集各式各樣的人偶。"]],"人品":[["ㄖㄣˊ ㄆㄧㄣˇ","人的品格。[例]他的人品高潔，令人景仰。"]],"人員":[["ㄖㄣˊ ㄩㄢˊ","從事某種特定事務的人。[例]大會工作人員一律獲頒獎金，以示慰勞。"]],"人才":[["ㄖㄣˊ ㄘㄞˊ","1.有才能學識的人。[例]他的學問廣博，思慮縝密，是一個不可多得的人才。\n2.人的品貌、才學。[例]他精通琴棋書畫，在同輩中算是人才。"]],"人才濟濟":[["ㄖㄣˊ ㄘㄞˊ ㄐㄧˇ ㄐㄧˇ","形容人才眾多。[例]本次研討會人才濟濟，成果非凡。"]],"人數":[["ㄖㄣˊ ㄕㄨˋ","人員的數量。[例]班長調查參加郊遊的人數，以便預購車票。"]],"人民":[["ㄖㄣˊ ㄇㄧㄣˊ","百姓。[例]警察是人民的保姆、社會治安的維護者。"]],"人禍":[["ㄖㄣˊ ㄏㄨㄛˋ","人為的災禍。[例]這場災難並非天災，而是人禍。"]],"人群":[["ㄖㄣˊ ㄑㄩㄣˊ","人類、群眾。[例]造福人群、服務人群"]],"人質":[["ㄖㄣˊ ㄓˋ","被對方所拘留，或為了取信對方而作為抵押的人。[例]經過多方交涉，被敵方俘虜的人質，終獲安全釋放。"]],"人際":[["ㄖㄣˊ ㄐㄧˋ","人與人之間的關係。[例]建立有效的人際網路，可以拓展我們的生活領域。"]],"人際關係":[["ㄖㄣˊ ㄐㄧˋ ㄍㄨㄢ ㄒㄧˋ","社會裡人與人之間的關係。即自我對他人的看法、想法、說法及彼此對待的態度和影響等。[例]他學識淵博，又熱心公益，所以人際關係良好。"]],"人類":[["ㄖㄣˊ ㄌㄟˋ","人的總稱。[例]狗是人類最忠實的朋友。"]],"什物":[["ㄕˊ ㄨˋ","各種常用的器具。[例]我開了家雜貨鋪，賣一些日常所需什物。"]],"什錦":[["ㄕˊ ㄐㄧㄣˇ","由多種原料製成或多種花樣拼成的。[例]什錦麵、素什錦、什錦火鍋"]],"什麼":[["ㄕㄣˊ ˙ㄇㄜ","1.疑問代詞，代不特定的人、事、物等。[例]他在做什麼？　△甚麼_x000D_\n2.疑問形容詞。[例]什麼人、什麼事　△甚麼_x000D_\n3.無定疑問詞。[例]這套衣服什麼才兩千元？光是上衣就要五千元。　△甚麼"]],"仁德":[["ㄖㄣˊ ㄉㄜˊ","仁民愛物的德澤。[例]我們現在能享受安和樂利的生活，應該感謝政府的仁德施政。"]],"仁政":[["ㄖㄣˊ ㄓㄥˋ","仁德的政治。[例]執政者唯有施以仁政，才能真正使國家太平、人民安樂。"]],"仇敵":[["ㄔㄡˊ ㄉㄧˊ","彼此間含有深刻怨恨而成敵對狀態的人。[例]自從交惡後，他們一直視對方為仇敵。"]],"今天":[["ㄐㄧㄣ ㄊㄧㄢ","1.說話時的當天。[例]今天我們要到育幼院當義工。\n2.現在、目前。[例]今天是個講求效率的時代，如果不懂得如何使用電腦，就會趕不上時代。"]],"今日":[["ㄐㄧㄣ ㄖˋ","1.今天。[例]奧運代表團預定今日返抵國門。\n2.目前、現在。[例]今日國家社會的安定繁榮得來不易，大家要珍惜啊！"]],"介入":[["ㄐㄧㄝˋ ㄖㄨˋ","參與並干預某事。[例]這是他們兩人的事，旁人介入只會使事情變得更複雜。"]],"介紹":[["ㄐㄧㄝˋ ㄕㄠˋ","1.居間接洽，牽合雙方，使彼此認識。[例]他們是經王老師介紹而相識的。\n2.為人引進或帶入新的事物。[例]他在這家公司擔任的工作是為客戶介紹新產品。"]],"仍然":[["ㄖㄥˊ ㄖㄢˊ","和往常一樣未曾改變的。[例]他雖遭遇許多挫折，但對人生仍然充滿希望。"]],"仍舊":[["ㄖㄥˊ ㄐㄧㄡˋ","和往常一樣未曾改變的、依照原有的模式進行。[例]他雖然生病了，但仍舊抱病上課。"]],"仔細":[["ㄗˇ ㄒㄧˋ","1.詳細、周密。[例]他仔細檢查每個實驗步驟，找出誤差所在。\n2.小心、謹慎。[例]答題時仔細點！別看錯題目了。"]],"他人":[["ㄊㄚ ㄖㄣˊ","別人。[例]能自力完成的事，就不要假手他人。"]],"他們":[["ㄊㄚ ˙ㄇㄣ","第三人稱的多數，指自己和對方以外的若干人。[例]他們喜歡結伴去逛街、看電影。"]],"他日":[["ㄊㄚ ㄖˋ","1.異日、別日。[例]今天時間倉促，他日相聚再詳談吧！\n2.未來。[例]別小看他！說不定他日成就不在你我之下。"]],"仗勢":[["ㄓㄤˋ ㄕˋ","倚靠權勢。[例]雖然他位高權重，但從不仗勢欺人。"]],"仗勢欺人":[["ㄓㄤˋ ㄕˋ ㄑㄧ ㄖㄣˊ","憑著權勢，欺侮壓榨他人。[例]他仗勢欺人的行為，已引起許多人不滿。"]],"付出":[["ㄈㄨˋ ㄔㄨ","支出、交出。[例]為了完成這部書，大家都付出了很多心血。"]],"付帳":[["ㄈㄨˋ ㄓㄤˋ","付錢。[例]這頓飯我來作東，由我付帳。"]],"付諸實行":[["ㄈㄨˋ ㄓㄨ ㄕˊ ㄒㄧㄥˊ","將想法、計畫用具體行動實現。[例]再完美的計畫，都必須付諸實行，才能成功。"]],"仙境":[["ㄒㄧㄢ ㄐㄧㄥˋ","神仙居住的地方。亦用來比喻景致優美的地方。[例]這裡湖光山色，美景天成，真是人間仙境。"]],"仙子":[["ㄒㄧㄢ ㄗˇ","1.仙人。亦用以尊稱修道的人。[例]據說這座高山上曾住著一位仙子。\n2.比喻美女。[例]她氣質清新，是個美麗的仙子。"]],"代替":[["ㄉㄞˋ ㄊㄧˋ","替換、取代。[例]杯子用完了，暫時拿碗代替吧！"]],"代表":[["ㄉㄞˋ ㄅㄧㄠˇ","1.由機關、團體選舉出來或受委託、指派以代替眾人辦事或表達意見的人。[例]鄉民代表、會員代表\n2.象徵、代替。[例]國旗代表國家，所以我們要尊敬它。"]],"以前":[["ㄧˇ ㄑㄧㄢˊ","1.從前。[例]以前這裡是一片荒蕪，沒想到三十年後卻發展成本市最繁榮的地區了。\n2.在特定的某時間或事件之前。[例]在出國以前，我們必須把手邊的事情安排妥當。"]],"以寡擊眾":[["ㄧˇ ㄍㄨㄚˇ ㄐㄧˊ ㄓㄨㄥˋ","以少數薄弱的力量攻擊眾多強盛的對手。[例]我空軍飛行員訓練精良，常以寡擊眾，逼退敵人。"]],"以後":[["ㄧˇ ㄏㄡˋ","在特定的某時間或事件之後。[例]自從那次車禍以後，他再也不敢開快車了。"]],"以為":[["ㄧˇ ㄨㄟˊ","認為、當作。[例]我以為這項方案尚未規劃妥當，應該暫緩實施。"]],"以致":[["ㄧˇ ㄓˋ","由於某種原因而導致某種結果。是表示結果的連詞。[例]本縣防颱工作做得不夠切實，以致強烈颱風過境之後，低窪地區的民眾損失慘重。"]],"仰仗":[["ㄧㄤˇ ㄓㄤˋ","依賴、憑仗。[例]他的交際廣，關係好，這件事還須仰仗他大力相助。"]],"仰望":[["ㄧㄤˇ ㄨㄤˋ","抬頭向上看。[例]他仰望長空，思念遠方的故鄉。"]],"任何":[["ㄖㄣˋ ㄏㄜˊ","無論什麼。[例]任何原因、任何理由"]],"任免":[["ㄖㄣˋ ㄇㄧㄢˇ","任用與罷免。[例]高級的政務官員，是由總統親自任免的。"]],"任務":[["ㄖㄣˋ ㄨˋ","擔任的職務或使命。[例]經由大家不斷的努力，終於達成上級交代的任務。"]],"任勞任怨":[["ㄖㄣˋ ㄌㄠˊ ㄖㄣˋ ㄩㄢˋ","形容人做事熱心負責，不辭勞苦、不怕嫌怨。[例]他做事一向任勞任怨，從不與人計較。"]],"任意":[["ㄖㄣˋ ㄧˋ","隨意而為，不受拘束。[例]圖書館內開放式書架上的書是供人任意取閱的。"]],"任教":[["ㄖㄣˋ ㄐㄧㄠˋ","擔任教學的工作。[例]她大學畢業後就到國小任教，至今已經十年了。"]],"任由":[["ㄖㄣˋ ㄧㄡˊ","任憑、聽由。[例]本餐廳的沙拉吧，任由各位取用。"]],"任職":[["ㄖㄣˋ ㄓˊ","擔任職務。[例]他在公家機關任職已有五年的時間。"]],"仿冒":[["ㄈㄤˇ ㄇㄠˋ","將一種產品做完全相同的重製，以假亂真，用以圖利。[例]我們應該尊重智慧財產權，不可隨便仿冒他人的產品。"]],"仿製":[["ㄈㄤˇ ㄓˋ","模仿製造。[例]仿製他人產品，可能會觸犯著作權法。"]],"企業":[["ㄑㄧˋ ㄧㄝˋ","從事生產、運輸、貿易等經濟活動的營利事業，由本身提供產品及服務，經由市場機制換取營利。如工廠、礦業、鐵路、貿易公司等。依出資來源不同，可分為公營企業及私人企業。[例]現代企業大多已走向多角化經營的發展趨勢。"]],"企盼":[["ㄑㄧˋ ㄆㄢˋ","非常盼望。[例]父母總是企盼兒女能夠早日成家立業。"]],"休克":[["ㄒㄧㄡ ㄎㄜˋ","醫學上指末梢循環急性衰竭的情況。其特徵為皮膚蒼白溼冷，血壓降低，情緒不安，嚴重時會導致意識不清。§英shock[例]他因心臟病復發而引起休克，被人送往醫院急救。"]],"休息":[["ㄒㄧㄡ ㄒㄧˊ","暫時停止工作或活動。常帶有放鬆身心，以待復原的意思。[例]他今天因病請假，在家休息。"]],"休止":[["ㄒㄧㄡ ㄓˇ","停止。[例]休止符、永無休止"]],"休閒":[["ㄒㄧㄡ ㄒㄧㄢˊ","休息閒暇。[例]看書、看電影是正當的休閒娛樂。"]],"伯樂":[["ㄅㄛˊ ㄌㄜˋ","指周代善於相馬的人孫伯樂。後用來比喻善於發掘人才的人。[例]好人才還是得靠伯樂來發掘，才不會被埋沒。"]],"估計":[["ㄍㄨ ㄐㄧˋ","大約計算、推測。[例]這場演唱會盛況空前，估計有三萬人參加。"]],"伴奏":[["ㄅㄢˋ ㄗㄡˋ","以一種樂器或人聲為主體，而以其他樂器配合演奏。[例]聲樂家獨唱時，喜歡用鋼琴來伴奏。"]],"伴娘":[["ㄅㄢˋ ㄋㄧㄤˊ","婚禮中陪伴新娘，輔助行禮的女子。[例]大姊結婚時，找了她最親近的同學做她的伴娘。　△女儐相"]],"伴舞":[["ㄅㄢˋ ㄨˇ","1.當舞伴，陪人跳舞。[例]為了家計，她只好到舞廳伴舞。\n2.歌唱或跳舞時，用來陪襯主角的舞蹈表演。[例]這次的康樂晚會，由本班負責伴舞。"]],"伴郎":[["ㄅㄢˋ ㄌㄤˊ","婚禮中伴隨新郎，輔助行禮的男子。[例]今天的伴郎是新郎的弟弟，也很出色吧！　△男儐相"]],"伴隨":[["ㄅㄢˋ ㄙㄨㄟˊ","跟隨、隨同。[例]戰爭過後，饑荒伴隨而來。"]],"伸懶腰":[["ㄕㄣ ㄌㄢˇ ㄧㄠ","疲倦困乏時伸展腰身。[例]在座位上坐久了，站起來伸懶腰，全身舒暢不少。"]],"伸長":[["ㄕㄣ ㄔㄤˊ","延伸使更長。[例]他伸長了脖子左右張望，不知在找些什麼？"]],"似乎":[["ㄙˋ ㄏㄨ","好像。[例]義大利人愛好音樂，似乎每個人都是天生的音樂迷。"]],"但是":[["ㄉㄢˋ ㄕˋ","不過、可是。[例]這花很美，但是花期太短了。"]],"佇立":[["ㄓㄨˋ ㄌㄧˋ","長時間站著。[例]一群人佇立在站牌下，等候公車。"]],"佇足":[["ㄓㄨˋ ㄗㄨˊ","停下腳步。[例]街頭藝人的表演，吸引許多路人佇足觀看。"]],"位子":[["ㄨㄟˋ ˙ㄗ","座位。[例]搭車時，我總是選擇靠窗的位子。"]],"位置":[["ㄨㄟˋ ㄓˋ","1.所在的地方。[例]老家的位置，是在日月潭附近。\n2.比喻地位、職位。[例]請你在公司裡安插一個位置給他。"]],"低吟":[["ㄉㄧ ㄧㄣˊ","低聲吟唱。[例]優美的詩詞總引人再三低吟。"]],"低窪":[["ㄉㄧ ㄨㄚ","地勢凹陷，比四周低下。[例]颱風來襲後，低窪地區要嚴防豪雨成災。"]],"低頭":[["ㄉㄧ ㄊㄡˊ","1.低下頭。[例]她低頭不語，不知道在想些什麼？\n2.屈服、妥協。[例]雖然遇到無數困難險阻，他也不肯向命運低頭。"]],"住手":[["ㄓㄨˋ ㄕㄡˇ","1.停止手的動作。[例]媽媽要小弟住手，不要再攪動魚缸裡的水。\n2.停止做某件事。[例]這件事不成功，他是不會住手的。"]],"住處":[["ㄓㄨˋ ㄔㄨˋ","居住的地方。[例]明天要到高雄出差，晚上的住處，你要如何安排？"]],"何妨":[["ㄏㄜˊ ㄈㄤˊ","有什麼妨礙呢？用反問的語氣，表示沒關係、不礙事。[例]事到如今，紙已包不住火，說出真相又何妨?"]],"何時":[["ㄏㄜˊ ㄕˊ","什麼時候。[例]你何時有空能和我下一盤棋？"]],"何況":[["ㄏㄜˊ ㄎㄨㄤˋ","比較或更進一層推論。[例]這條山路天氣好的時候就很難走了，何況天氣不好的時候？"]],"何處":[["ㄏㄜˊ ㄔㄨˋ","哪裡、哪兒。疑問之詞。[例]這條小溪曲折蜿蜒，不知終將流向何處？"]],"佛寺":[["ㄈㄛˊ ㄙˋ","供佛的寺廟、寺院。[例]他篤信佛教，經常到各地的佛寺朝拜。"]],"佛教":[["ㄈㄛˊ ㄐㄧㄠˋ","世界主要宗教之一，為釋迦牟尼所創，漢明帝時由西域傳入中國。主張生命是痛苦的，一切是無常的，只有息滅貪、瞋、痴，證得圓滿智慧，才能得究竟解脫。佛教信徒分布世界各地，但主要以亞洲為主。對中國文學、哲學、藝術及習俗有很大的影響。"]],"作品":[["ㄗㄨㄛˋ ㄆㄧㄣˇ","文學、藝術方面創作的成品。[例]他是文壇新崛起的作家，作品常刊載在各大報章雜誌上。"]],"作惡多端":[["ㄗㄨㄛˋ ㄜˋ ㄉㄨㄛ ㄉㄨㄢ","壞事做得極多。[例]這批匪徒作惡多端，難逃法律制裁。"]],"作戰":[["ㄗㄨㄛˋ ㄓㄢˋ","戰鬥、打仗等一切軍事活動。[例]國軍為保衛家園，不惜犧牲生命與敵軍奮勇作戰。"]],"作文":[["ㄗㄨㄛˋ ㄨㄣˊ","練習寫作文章。[例]作文能力的培養，可從多看、多讀、多寫三方面著手。"]],"作料":[["ㄗㄨㄛˊ ㄌㄧㄠˋ","烹調食物所加的調味材料。如鹽、醋、醬油等。也指主要食材以外的配料。[例]這道菜可能在烹調時忘了添加作料，所以嚐起來沒有任何味道。"]],"作業":[["ㄗㄨㄛˋ ㄧㄝˋ","1.處理、操作。[例]內部作業、黑箱作業\n2.由教師指定給學生所作的各種課程練習。[例]家庭作業的目的是希望學生能對所學習的課程內容作一番複習。"]],"作者":[["ㄗㄨㄛˋ ㄓㄜˇ","創作詩歌、文章或其他藝術品的人。[例]這本書的作者，近日正在各大書店舉辦新書簽名活動。"]],"作證":[["ㄗㄨㄛˋ ㄓㄥˋ","證明某件事或當保證人以證明某事。[例]由於他出面作證，我才得以洗刷冤屈。"]],"你們":[["ㄋㄧˇ ˙ㄇㄣ","第二人稱的多數代詞。[例]我明天要去博物館參觀，你們要一起去嗎？"]],"你我":[["ㄋㄧˇ ㄨㄛˇ","咱們、我們。[例]社會的和諧與進步，你我都有責任。"]],"佩服":[["ㄆㄟˋ ㄈㄨˊ","敬仰欽服。[例]你那未卜先知的本事，可真叫人佩服。"]],"佳偶":[["ㄐㄧㄚ ㄡˇ","美滿幸福的夫妻。[例]佳偶天成"]],"佳績":[["ㄐㄧㄚ ㄐㄧ","好成績。[例]他期盼能在這次比賽中再創佳績。"]],"佳麗":[["ㄐㄧㄚ ㄌㄧˋ","美女、美人。[例]後宮佳麗三千人，三千寵愛在一身。（唐．白居易〈長恨歌〉）"]],"併吞":[["ㄅㄧㄥˋ ㄊㄨㄣ","侵占他人的財物或土地。[例]弱小的國家容易被大國併吞。"]],"使勁":[["ㄕˇ ㄐㄧㄥˋ","用力。[例]他使勁把門踢開，衝進屋內滅火救人。"]],"使用":[["ㄕˇ ㄩㄥˋ","運用、利用。[例]這次新車發表會，公司準備了充裕的資金及人力供他調度使用。"]],"來不及":[["ㄌㄞˊ ㄅㄨˋ ㄐㄧˊ","無法趕上。[例]由於塞車非常嚴重，害我來不及參加會議的開幕儀式。"]],"來來往往":[["ㄌㄞˊ ㄌㄞˊ ㄨㄤˇ ㄨㄤˇ","不斷的來去。[例]火車站前人潮來來往往，想要找人可不簡單。"]],"來往":[["ㄌㄞˊ ㄨㄤˇ","1.往還。[例]一到假日，高速公路上來往的車流量十分驚人。\n\t\n2.交際往來。[例]這種人你還跟他來往？小心吃虧上當。"]],"來源":[["ㄌㄞˊ ㄩㄢˊ","根源、出處。[例]典故來源、姓氏來源"]],"來臨":[["ㄌㄞˊ ㄌㄧㄣˊ","來到、降臨。[例]樹上枝頭吐出新芽，暖和的春天已經來臨。"]],"來賓":[["ㄌㄞˊ ㄅㄧㄣ","蒞臨的賓客。[例]來賓致辭、來賓止步"]],"來龍去脈":[["ㄌㄞˊ ㄌㄨㄥˊ ㄑㄩˋ ㄇㄞˋ","堪輿學上稱山脈的起伏為「龍」，稱其主峰為「來龍」；稱山谷中的溪流為「脈」，稱其主流為「去脈」。今借指事情的由來和變化。[例]他把事情的來龍去脈說了一遍，我才知道原來是一場誤會。"]],"例如":[["ㄌㄧˋ ㄖㄨˊ","舉例時的用語。置於所舉的例子前面，表示下面就是例子。[例]我的興趣很廣泛，例如集郵、運動、爬山、唱歌等。"]],"例子":[["ㄌㄧˋ ˙ㄗ","用來佐證或輔助說明的事物。[例]老師用龜兔賽跑的例子說明「驕者必敗」的道理。"]],"侍從":[["ㄕˋ ㄗㄨㄥˋ","隨從侍奉的人。[例]古代帝王的侍從如同現今的安全人員，負責警戒、護衛的任務。"]],"侍者":[["ㄕˋ ㄓㄜˇ","服務生或陪侍左右的人。[例]顧客一進餐廳，侍者即以親切的笑容接待。"]],"侍衛":[["ㄕˋ ㄨㄟˋ","1.隨側侍奉、護衛的人。[例]國家元首有隨身侍衛全天候的保護。\n2.古代的職官。宋代有侍衛司，是天子的禁兵。清代置侍衛官，選用王公勛舊的子弟及武進士。如御前侍衛、乾清門侍衛等。"]],"供佛":[["ㄍㄨㄥˋ ㄈㄛˊ","1.信徒迎請佛像闢室膜拜。[例]母親在家闢了一個佛堂供佛。\n2.取花果、香水、時饈等供品獻給佛祖。[例]她是個虔誠的佛教徒，每天以花果、清茶供佛。"]],"供品":[["ㄍㄨㄥˋ ㄆㄧㄣˇ","用來祭拜祖先、神明的物品。[例]拜拜時，鮮花水果是最佳的供品。"]],"供應":[["ㄍㄨㄥ ㄧㄥˋ","供給需要的錢財或物品。[例]這次的研習活動，主辦單位將免費供應午餐。"]],"供求":[["ㄍㄨㄥ ㄑㄧㄡˊ","供給和需求。[例]市場的供求失調，使得商品的價格顯得很混亂。"]],"供給":[["ㄍㄨㄥ ㄐㄧˇ","提供、給予。[例]她的薪水除了維持自己的生活之外，還得供給妹妹求學所需的費用。"]],"供認":[["ㄍㄨㄥ ㄖㄣˋ","罪犯承認所做的事情。[例]經過警方多方的舉證，嫌犯終於供認罪行。"]],"供述":[["ㄍㄨㄥ ㄕㄨˋ","供認自述。[例]根據涉嫌人的供述，本案的主謀另有其人。"]],"供需":[["ㄍㄨㄥ ㄒㄩ","供給與需求。[例]商品的價格決定於市場的供需狀況。"]],"供養":[["ㄍㄨㄥˋ ㄧㄤˋ","1.用供品祭祀祖先或神佛。[例]以香花、明燈來供養佛祖是常見的民間習俗。\n2.提供父母生活上所需要的物品、金錢。[例]子女供養父母是天經地義的事。"]],"依依不捨":[["ㄧ ㄧ ㄅㄨˋ ㄕㄜˇ","非常留戀、捨不得。[例]直到寒假結束，我們才依依不捨的辭別外婆，回家準備開學。"]],"依傍":[["ㄧ ㄅㄤˋ","1.依靠。[例]互相依傍、無可依傍_x000D_\n2.參照、仿效。[例]依傍前人、一空依傍"]],"依序":[["ㄧ ㄒㄩˋ","按照次序。[例]公車來了，乘客依序上下車，秩序井然。"]],"依據":[["ㄧ ㄐㄩˋ","根據。[例]記者撰寫新聞稿必須依據事實真相，不可向壁虛造。"]],"依照":[["ㄧ ㄓㄠˋ","按照。[例]他依照食譜做了幾道菜請朋友嘗一嘗。"]],"依稀":[["ㄧ ㄒㄧ","1.彷彿，不清楚的樣子。[例]午夜夢迴，夢中景象依稀猶在眼前。\n2.些許、稍微。[例]靠著微弱的燭光照映，身旁的事物依稀可辨。"]],"依舊":[["ㄧ ㄐㄧㄡˋ","1.延續舊有的樣子。[例]景物依舊，人事已非。\n2.仍然、依然。[例]雖一再被指責，他依舊我行我素。"]],"依靠":[["ㄧ ㄎㄠˋ","1.靠著。[例]坐火車時依靠在車門旁站立，是非常危險的事。_x000D_\n2.依賴、憑藉。[例]革命烈士不畏犧牲，救國救民，所依靠的是深識遠慮和浩然正氣。_x000D_\n3.可供憑藉的人或事物。[例]慈善團體呼籲大家以實際的行動，給孩子溫暖的依靠。"]],"侮辱":[["ㄨˇ ㄖㄨˋ","1.欺侮羞辱。[例]不可隨意出言侮辱他人。\n2.傷害或羞辱他人人格、尊嚴等行為。[例]他自尊心很強，無法忍受任何侮辱。"]],"侵占":[["ㄑㄧㄣ ㄓㄢˋ","法律上指未經授權而占有他人財物的行為。[例]將公有地做為私人停車位，是一種侵占的行為。"]],"侵襲":[["ㄑㄧㄣ ㄒㄧˊ","侵犯襲擊。[例]北部地區連續遭受颱風侵襲，損失慘重。"]],"侷促":[["ㄐㄩˊ ㄘㄨˋ","1.狹小。[例]這個房子太侷促，已容納不下多餘的雜物了。\n2.拘謹不自然的樣子。[例]侷促不安\n3.時間短促。[例]合約上訂的時間十分侷促，很難如期完成。"]],"侷限":[["ㄐㄩˊ ㄒㄧㄢˋ","限制於固定的範圍內。[例]敞開胸懷，接納不同的想法，才不會侷限在個人的象牙塔中。 △局限"]],"便利":[["ㄅㄧㄢˋ ㄌㄧˋ","1.方便順利。[例]交通便利\n2.使方便順利。[例]稅捐處決定本週日照常辦公，便利民眾報稅。"]],"便宜":[["ㄅㄧㄢˋ ㄧˊ","方便合宜。[例]便宜行事"],["ㄆㄧㄢˊ ㄧˊ","1.物價低廉。[例]這件衣服的價錢真便宜。\n2.不應該得到或額外的利益。[例]為人處世應盡責守分，不要想占人便宜。"]],"便條":[["ㄅㄧㄢˋ ㄊㄧㄠˊ","沒有正式規格，隨意書寫的簡便紙條。[例]他把偶發的靈感，順手寫在便條上。"]],"促進":[["ㄘㄨˋ ㄐㄧㄣˋ","促發增進。[例]飯前的開胃菜可以促進食慾。"]],"俐落":[["ㄌㄧˋ ㄌㄨㄛˋ","言語或動作簡潔明快。[例]他年事雖高，但一點都沒有老化現象，依然行動敏捷，身手俐落。"]],"俗套":[["ㄙㄨˊ ㄊㄠˋ","通俗流行的作法、說法或禮節。[例]這場喜宴辦得別緻有趣，不落俗套。"]],"俗氣":[["ㄙㄨˊ ㄑㄧˋ","庸俗、土氣。[例]把所有珍貴的擺飾毫無章法的堆在客廳裡，不但毫無美感，而且顯得俗氣。"]],"俗話":[["ㄙㄨˊ ㄏㄨㄚˋ","流行通俗的語句。[例]俗話說：「萬事起頭難。」創業之初，辛苦一點是必然的。"]],"俗諺俚語":[["ㄙㄨˊ ㄧㄢˋ ㄌㄧˇ ㄩˇ","流傳於地方的通俗語詞。[例]俗諺俚語是人類累積了長期的生活經驗，創造出來的智慧。"]],"保佑":[["ㄅㄠˇ ㄧㄡˋ","保護庇佑。[例]感謝老天爺保佑，讓我逢凶化吉。"]],"保密":[["ㄅㄠˇ ㄇㄧˋ","保守機密。[例]保密防諜，人人有責。"]],"保持":[["ㄅㄠˇ ㄔˊ","維持相同的狀態。[例]保持現狀、保持身材"]],"保母":[["ㄅㄠˇ ㄇㄨˇ","1.替人照顧小孩的人，過去多由女性擔任。[例]因為父母是上班族，他從小是由保母帶大的。　△保姆_x000D_\n2.負責保護、守衛工作的人。[例]警察是人民的保母。　△保姆"]],"保留":[["ㄅㄠˇ ㄌㄧㄡˊ","1.保存、留下。[例]老師毫無保留的將知識傳授給學生。\n2.暫時擱置不做處理。[例]對於這個敏感問題，許多人都持保留態度。"]],"保護":[["ㄅㄠˇ ㄏㄨˋ","保衛、照顧。[例]保護人民生命財產的安全，是警察的責任。"]],"保障":[["ㄅㄠˇ ㄓㄤˋ","保護、保衛、屏障。[例]勞動基準法的設立是為了保障勞工的權益。"]],"保養":[["ㄅㄠˇ ㄧㄤˇ","1.機械的修理、維護。[例]車輛應定期保養，以維護行車安全。\n2.身心的調養、保健。[例]保養身體"]],"保麗龍":[["ㄅㄠˇ ㄌㄧˋ ㄌㄨㄥˊ","一種以聚苯乙烯為主要原料，再加入發泡劑製成的塑膠產品。可作為隔熱材料、緩衝包裝器材、免洗餐具及美工材料等。§英polystyrene[例]現在電器的包裝，都用保麗龍作為保護的外殼。_x000D_"]],"俠客":[["ㄒㄧㄚˊ ㄎㄜˋ","古代指身懷武藝、見義勇為、扶弱抑強而肯捨己為人的人。[例]他常常路見不平就挺身相助，頗有俠客的風範。"]],"俠義":[["ㄒㄧㄚˊ ㄧˋ","見義勇為、濟弱抑強的胸襟或行為。[例]俠義心腸、俠義之士"]],"信任":[["ㄒㄧㄣˋ ㄖㄣˋ","相信而敢於托付。[例]夫妻相處，貴在能彼此信任。"]],"信封":[["ㄒㄧㄣˋ ㄈㄥ","書信的封套。[例]信封上，收件人地址應書寫清晰，使能容易辨識。"]],"信手拈來":[["ㄒㄧㄣˋ ㄕㄡˇ ㄋㄧㄢˊ ㄌㄞˊ","不假思索的隨手拿來。用以比喻寫文章時取材、下筆時不需多加思索，就可以順手寫出來。[例]老師博學多才，且文筆極佳，信手拈來便能成為佳作。"]],"信賴":[["ㄒㄧㄣˋ ㄌㄞˋ","信任依賴。[例]他公私分明、辦事快速，是一個值得信賴的助手。"]],"修剪":[["ㄒㄧㄡ ㄐㄧㄢˇ","1.用剪刀修裁。[例]修剪指甲、修剪頭髮\n2.修改剪接。[例]這部片子經修剪後，許多恐怖的鏡頭都不見了。\n3.園藝上指將枝條之尖端剪短，或將一部分枝條完全從基部剪去的作業。[例]父親固定每個月都會修剪庭園裡的花木。"]],"修改":[["ㄒㄧㄡ ㄍㄞˇ","修正更改。[例]這件衣服只要稍作修改，便能合身了。"]],"修理":[["ㄒㄧㄡ ㄌㄧˇ","1.整修壞掉或故障的器具。[例]只要汰換幾個零件，就能把電視機修理好了。_x000D_\n2.教訓、處罰。"]],"修行":[["ㄒㄧㄡ ㄒㄧㄥˊ","修習實踐，多指學佛或學道等宗教方面。[例]他是一位在家修行的居士。"]],"修補":[["ㄒㄧㄡ ㄅㄨˇ","修理與補好。[例]這扇紗窗破了，需要找人來修補。"]],"修身養性":[["ㄒㄧㄡ ㄕㄣ ㄧㄤˇ ㄒㄧㄥˋ","涵養品德，陶冶性情。[例]他常利用空閒時寫書法或畫國畫來修身養性。"]],"修養":[["ㄒㄧㄡ ㄧㄤˇ","品德、風度。[例]他是一位很有修養的人。"]],"俯瞰":[["ㄈㄨˇ ㄎㄢˋ","由高處向下看。[例]從高空俯瞰，所有的景物都變得非常渺小。"]],"俯衝":[["ㄈㄨˇ ㄔㄨㄥ","飛鳥或飛行物從空中迅速飛降。[例]老鷹自高崖俯衝而下，掠奪地面的獵物。"]],"俯視":[["ㄈㄨˇ ㄕˋ","從高處往下看。[例]她喜歡登上高山俯視山谷中的清幽景致。"]],"俯首":[["ㄈㄨˇ ㄕㄡˇ","1.低頭。[例]俯首不語\n2.比喻聽命順從。[例]俯首稱臣"]],"俸給":[["ㄈㄥˋ ㄐㄧˇ","公務人員每月所得的薪資。[例]他們僅靠父親微薄的俸給度日。"]],"倉促":[["ㄘㄤ ㄘㄨˋ","急促匆忙。[例]這件事關係重大，不可倉促做決定。"]],"倉皇":[["ㄘㄤ ㄏㄨㄤˊ","慌張匆忙的樣子。[例]歹徒一見警察便倉皇而逃。"]],"個人":[["ㄍㄜˋ ㄖㄣˊ","1.單獨一人。[例]這次學校的桌球比賽只供個人報名參加，團體比賽暫停舉行。\n2.自己、本人。[例]這是我個人的淺見，提供給大家作為參考。"]],"個子":[["ㄍㄜˋ ˙ㄗ","人的身材、身高。[例]他個子高大，加上動作靈活，是我們籃球隊上的得分主力。　△個兒。"]],"倍增":[["ㄅㄟˋ ㄗㄥ","增加一倍以上。[例]經過老師的鼓勵後，小明的勇氣頓時倍增。"]],"倒塌":[["ㄉㄠˇ ㄊㄚ","傾倒、塌下來。[例]大地震後，災區到處可見倒塌房屋的慘狀。"]],"倒影":[["ㄉㄠˋ ㄧㄥˇ","倒映在水中，上下方向顛倒的影子。[例]夜晚的水面上映著月亮的倒影，別有一番風情。"]],"倒掛":[["ㄉㄠˋ ㄍㄨㄚˋ","頭尾顛倒掛著。[例]蝙蝠習慣倒掛在高處休息。"]],"倒數":[["ㄉㄠˋ ㄕㄨˇ","逆數，由後往前數。[例]距離大考已經進入倒數第十天了，你還這樣漫不經心？"]],"倒灌":[["ㄉㄠˋ ㄍㄨㄢˋ","海水因颱風或潮汐關係從河口倒流至陸地。[例]養殖魚塭超抽地下水，導致地層下陷，容易引發海水倒灌。"]],"倒立":[["ㄉㄠˋ ㄌㄧˋ","以兩手支撐身體，頭朝下，兩腿向上豎起。[例]他的功夫了得，可以倒立走一、二十公尺的路。　◎"]],"倒車":[["ㄉㄠˋ ㄔㄜ","使車輛向後退。[例]倒車時要注意車後有沒有行人。"]],"倒退":[["ㄉㄠˋ ㄊㄨㄟˋ","1.後退。[例]巷口突然跑出一隻凶猛的狗，嚇得她連連倒退好幾步。\n2.追溯、回到從前。[例]走進這家復古風格的餐廳，時光好像倒退幾十年，讓人猶如置身昔日的臺灣農村。"]],"倔強":[["ㄐㄩㄝˊ ㄐㄧㄤˋ","強硬不肯屈服的樣子。[例]她的個性倔強，實在很難說服。"]],"倘若":[["ㄊㄤˇ ㄖㄨㄛˋ","表示假設語氣的連接詞，即如果、假使。[例]倘若這件事不是你做的，為什麼見了我就跑？"]],"候鳥":[["ㄏㄡˋ ㄋㄧㄠˇ","隨季節變更而遷移的鳥類。可分為冬候鳥和夏候鳥兩種。冬候鳥有家燕、野鴨等，夏候鳥有大慈悲心鳥和八色鳥等。[例]每當秋天來臨時，候鳥群集河口，非常壯觀。　△信鳥"]],"借助":[["ㄐㄧㄝˋ ㄓㄨˋ","依靠他人或他物的幫助。[例]這位新人之所以有這麼高的知名度，完全是借助傳播媒體的宣傳。"]],"借款":[["ㄐㄧㄝˋ ㄎㄨㄢˇ","1.向人借錢。[例]王伯伯為了讓兒子出國留學，決定向銀行借款。\n2.借用的錢。[例]這筆借款我一定會還清，請你再寬限幾天吧！"]],"借用":[["ㄐㄧㄝˋ ㄩㄥˋ","借物品或空間使用。[例]為了準備下星期的舞蹈比賽，班長向學校借用場地加強練習。"]],"借貸":[["ㄐㄧㄝˋ ㄉㄞˋ","1.向人借用財物。[例]他為了籌湊返鄉探親的旅費，已向幾位朋友借貸。\n2.會計上指簿記或資產表上的借方與貸方。"]],"倨傲":[["ㄐㄩˋ ㄠˋ","態度傲慢無禮。[例]他老是一副高高在上的樣子，態度倨傲得讓人難以忍受。"]],"值得":[["ㄓˊ ˙ㄉㄜ","1.價值相當、合算。[例]他用極低的價錢買到所需的東西，十分值得。\n2.有價值、意義。[例]《論語》是一本值得一讀再讀的好書。"]],"值班":[["ㄓˊ ㄅㄢ","輪流在規定的時間內擔任工作。[例]今天由我值班，負責管理社團圖書的工作。"]],"假使":[["ㄐㄧㄚˇ ㄕˇ","如果。[例]假使你能虛心接受朋友的忠告，今日也就不會淪落到如此地步。"]],"假如":[["ㄐㄧㄚˇ ㄖㄨˊ","如果。[例]假如行程有改變，請務必通知我。"]],"假扮":[["ㄐㄧㄚˇ ㄅㄢˋ","喬裝。[例]他假扮成聖誕老公公，為院童們帶來了許多歡笑。"]],"假日":[["ㄐㄧㄚˋ ㄖˋ","放假或休假的日子。[例]國定假日、連續假日、星期假日"]],"假若":[["ㄐㄧㄚˇ ㄖㄨㄛˋ","如果。[例]假若這種事發生在你身上，你會作何感想？"]],"假面具":[["ㄐㄧㄚˇ ㄇㄧㄢˋ ㄐㄩˋ","1.用厚紙或塑膠壓製，做成人臉或其他各種形像的面具。初時用於舞臺化妝，後多用做玩具。[例]化妝舞會上各式各樣的假面具令人目不暇給。\n2.比喻偽裝的外表。[例]人與人應真誠相處，不宜以假面具互相欺矇。"]],"假髮":[["ㄐㄧㄚˇ ㄈㄚˇ","用尼龍絲線或真髮加工製成的人造頭髮。[例]她利用假髮把自己裝扮成一個老太婆，以符合劇情的需要。"]],"偉人":[["ㄨㄟˇ ㄖㄣˊ","品格高超或功業不凡的人。[例]孔子是我國歷史上的偉人。"]],"偉大":[["ㄨㄟˇ ㄉㄚˋ","形容成就卓越非凡，影響極大。[例]印刷術的發明對人類文明具有偉大的貢獻。_x000D_"]],"偏偏":[["ㄆㄧㄢ ㄆㄧㄢ","1.故意，與要求相反。[例]我說往東，你偏偏往西，這不是存心與我作對嗎？\n2.與事實或願望相反。[例]時間已經很趕了，偏偏又遇上塞車，真是令人心急。"]],"偏僻":[["ㄆㄧㄢ ㄆㄧˋ","偏離中心或離主要部分較遠。[例]偏僻地區"]],"偏勞":[["ㄆㄧㄢ ㄌㄠˊ","請人幫忙或謝人代替自己做事的謙詞。[例]這事就請你多偏勞了。"]],"偏心":[["ㄆㄧㄢ ㄒㄧㄣ","偏袒一方，對某一方存私心。[例]有教無類的老師對每位同學都是一視同仁，絲毫沒有偏心。"]],"偏方":[["ㄆㄧㄢ ㄈㄤ","流傳於民間，不見於醫藥書籍記載的藥方。[例]生病要看醫生，千萬不可亂服偏方。"]],"偏旁":[["ㄆㄧㄢ ㄆㄤˊ","泛指漢字合體字的上下左右任一部分。[例]江字的右偏旁是個「工」字。"]],"偏遠":[["ㄆㄧㄢ ㄩㄢˇ","偏僻遙遠。[例]偏遠地區"]],"做夢":[["ㄗㄨㄛˋ ㄇㄥˋ","1.睡眠時腦細胞活動所產生的幻象。[例]有的人每天晚上睡覺都會做夢。　△作夢_x000D_\n2.比喻夢想、幻想。[例]沒有付出努力就想得到好成績，簡直是做夢。　△作夢"]],"停住":[["ㄊㄧㄥˊ ㄓㄨˋ","停留止住。[例]他不時停住腳步，依依不捨的回頭望著送行的家人。"]],"停止":[["ㄊㄧㄥˊ ㄓˇ","不繼續，不進行。[例]因颱風來襲，臺北市今天各機關學校停止上班及上課。"]],"停滯":[["ㄊㄧㄥˊ ㄓˋ","停止不動。[例]因為勞工不足，工程進度一直停滯不前。"]],"停留":[["ㄊㄧㄥˊ ㄌㄧㄡˊ","停住不前進。[例]因為山路遙遠，我們不妨在中途稍做停留，休息一番，再繼續前進。"]],"停車":[["ㄊㄧㄥˊ ㄔㄜ","1.停止車輛的行駛。[例]行車時如果碰到警方臨檢，應自動停車受驗。\n2.停放車輛。[例]路邊劃有紅線的地方，嚴禁停車。"]],"健全":[["ㄐㄧㄢˋ ㄑㄩㄢˊ","1.生理及心理健康正常無異狀。[例]他們努力給孩子良好的生長環境，使他身心發展健全。\n2.使事物完善、完備而沒有缺陷。[例]健全基金會的組織，才能充分發揮它的功用。"]],"健將":[["ㄐㄧㄢˋ ㄐㄧㄤˋ","運動或其他活動的能手。[例]游泳健將、足球健將、運動健將"]],"健康":[["ㄐㄧㄢˋ ㄎㄤ","生理及心理機能正常，強壯安適，沒有缺陷和疾病。[例]健康就是人生最大的財富。"]],"健行":[["ㄐㄧㄢˋ ㄒㄧㄥˊ","以徒步方式到郊外旅遊。此種活動起源於西元1901年德國費施爾中學，後流行於世界各地。[例]公司每年都會舉辦一次健行活動，藉以聯絡員工之間的感情。"]],"側影":[["ㄘㄜˋ ㄧㄥˇ","側面的身影。[例]前面那個人的側影很像小楊。"]],"側目":[["ㄘㄜˋ ㄇㄨˋ","斜眼看人。有敬畏、奇怪、戒懼、憤怒、輕蔑等不同的含意。[例]他的奇裝異服，引來路人側目。"]],"側面":[["ㄘㄜˋ ㄇㄧㄢˋ","1.身體面部的側邊。[例]請轉身，現在拍攝側面。\n2.物體旁邊的一面。[例]這棟大樓的逃生口位於電梯間側面。"]],"偵探":[["ㄓㄣ ㄊㄢˋ","1.暗中探察。[例]他混進敵方陣營偵探敵情。\n2.從事暗中探察工作的幹員。[例]私家偵探"]],"偶然":[["ㄡˇ ㄖㄢˊ","1.碰巧、未曾料想到。[例]他和多年不見的好友在路上偶然相遇，彼此驚喜萬分。\n2.有時候，不定時。[例]她偶然會到花市買幾朵玫瑰，裝飾自己的房間。"]],"偶爾":[["ㄡˇ ㄦˇ","偶然，有時候。[例]自從到外地唸書後，因為課業繁重，他只能偶爾回家一趟。"]],"偶發":[["ㄡˇ ㄈㄚ","偶然發生。[例]偶發事件、偶發狀況"]],"偷渡":[["ㄊㄡ ㄉㄨˋ","非法出境或入境。[例]為了防止偷渡事件日漸增加，政府已大力加強查緝工作。"]],"偷襲":[["ㄊㄡ ㄒㄧˊ","趁對方防備鬆懈或疏失時，突然發動攻擊。[例]我方趁著黑夜的掩護，偷襲敵軍陣地。"]],"偽裝":[["ㄨㄟˋ ㄓㄨㄤ","假裝，改裝掩飾真正的面目或身分。[例]警方派出便衣人員偽裝成賭客，破獲此一大賭場。"]],"傍晚":[["ㄅㄤ ㄨㄢˇ","黃昏時分。[例]每天傍晚，爺爺都會到公園散步。"]],"傑作":[["ㄐㄧㄝˊ ㄗㄨㄛˋ","優秀而特出的作品。[例]這棟建築物是他從業以來精心設計的得意傑作。"]],"備受好評":[["ㄅㄟˋ ㄕㄡˋ ㄏㄠˇ ㄆㄧㄥˊ","受到特別好的評價。[例]這次推出的新產品，備受好評。"]],"備胎":[["ㄅㄟˋ ㄊㄞ","備用的車胎。置於車上，以防原胎爆破或損壞，可以就地換裝。[例]一般汽車都配有備胎，以備不時之需。"]],"傢伙":[["ㄐㄧㄚ ㄏㄨㄛˇ","1.舊稱家具雜物。[例]他在搬到新居前，把家中的傢伙變賣或分送親友。\n\t\n2.指工具、武器。[例]忍一時風平浪靜，千萬別動不動就抄傢伙打架。\n\t\n3.對人親暱、戲謔或輕蔑的稱呼。[例]你這傢伙總算遇到剋星了吧！"]],"催生":[["ㄘㄨㄟ ㄕㄥ","1.用藥物或其他方法，使胎兒提早出生。[例]產婦若羊水已破，需立即催生。\n2.比喻盡力使某種事物能順利進行或提前產生。[例]那套書能提早問世，是編輯部門大力催生的結果。"]],"傲慢":[["ㄠˋ ㄇㄢˋ","態度驕傲無禮。[例]傲慢無禮的態度，最易引起別人的反感。"]],"傲骨":[["ㄠˋ ㄍㄨˇ","高傲不屈的氣骨。[例]他生來一付傲骨，絕不與世同流合汙。"]],"傳單":[["ㄔㄨㄢˊ ㄉㄢ","印成單張散發給人的宣傳品。[例]廣告傳單"]],"傳承":[["ㄔㄨㄢˊ ㄔㄥˊ","傳接繼承。[例]歷史的傳承須靠世代子孫的努力。"]],"傳授":[["ㄔㄨㄢˊ ㄕㄡˋ","將知識、技能教給他人。[例]好老師總是不惜將他所知道的一切傳授給學生們。"]],"傳教士":[["ㄔㄨㄢˊ ㄐㄧㄠˋ ㄕˋ","傳布宗教教義的人。[例]滿清末年，有許多傳教士來到中國，弘揚教義，傳遞新知。"]],"傳染":[["ㄔㄨㄢˊ ㄖㄢˇ","病原從病體侵入另一個生物體內的過程。[例]出入公共場所應注意衛生，以免受到病媒的傳染。"]],"傳神":[["ㄔㄨㄢˊ ㄕㄣˊ","形容用圖畫、文字描繪人物，生動逼真，能充分表現出其神情意態。[例]這幅畫像將童稚純真的笑容描繪得十分傳神。"]],"傳統":[["ㄔㄨㄢˊ ㄊㄨㄥˇ","1.世代相傳，有傳承延續性質的社會因素，如風俗、道德、習慣、信仰、思想、方法等。[例]勤儉是我國的優良傳統之一。_x000D_\n2.屬於舊式的。[例]三合院是臺灣傳統的建築模式。"]],"傳記":[["ㄓㄨㄢˋ ㄐㄧˋ","記述個人生平事蹟的作品。[例]多讀偉人傳記有勵志的作用。"]],"傳誦":[["ㄔㄨㄢˊ ㄙㄨㄥˋ","輾轉傳布、誦讀或稱道。[例]書禁解除後，原本許多禁讀的文學作品，一時間人人競相傳誦。"]],"傳輸":[["ㄔㄨㄢˊ ㄕㄨ","傳導輸送。[例]此地設備落伍，傳輸緩慢，因此所能取得的資訊有限。"]],"傳達":[["ㄔㄨㄢˊ ㄉㄚˊ","轉達，將一方的意思轉告給另一方。[例]除言語之外，手語也可以傳達內心的意思。"]],"傷口":[["ㄕㄤ ㄎㄡˇ","1.肢體受傷而破裂的地方。[例]傷口要確實消毒、包紮才不致受到感染。\n2.心理因受到打擊而留下的創傷。[例]這個打擊使她心中留下難以抹滅的傷口。"]],"傷心":[["ㄕㄤ ㄒㄧㄣ","心中悲痛。[例]事已至此，再傷心也無補於事。"]],"傷痕":[["ㄕㄤ ㄏㄣˊ","受傷後所留下的痕跡。[例]上次的意外事故使她的小腿留下一道傷痕。"]],"傷痕累累":[["ㄕㄤ ㄏㄣˊ ㄌㄟˇ ㄌㄟˇ","形容受傷後所留下的傷痕很多。[例]此次意外使他全身傷痕累累，見了真教人難過。"]],"傷痛":[["ㄕㄤ ㄊㄨㄥˋ","1.悲傷哀痛。[例]父親突然去世，令他十分傷痛。\n2.因受傷而疼痛。[例]戰地醫院內傷痛之聲不絕於耳，使人不由得感嘆戰爭的殘酷。"]],"傷神":[["ㄕㄤ ㄕㄣˊ","1.損耗精神。[例]此書印刷不良、字體模糊，閱讀起來頗為傷神。\n2.傷心。[例]勸她別再為此傷神，好好振作才是上策。"]],"傷腦筋":[["ㄕㄤ ㄋㄠˇ ㄐㄧㄣ","事情不易解決，費心思。[例]他惹出了這種大麻煩，真是傷腦筋。"]],"傻瓜":[["ㄕㄚˇ ㄍㄨㄚ","指愚笨的人。多用來罵人或開玩笑。有時帶有憐惜的意味。[例]別老罵他傻瓜，他其實並不傻。"]],"傾倒":[["ㄑㄧㄥ ㄉㄠˇ","1.倒塌。[例]由於施工不當，屋牆突然傾倒。\n2.十分讚賞、愛慕或佩服。[例]她風華絕代，任誰見了都會傾倒。"],["ㄑㄧㄥ ㄉㄠˋ","全部倒出。[例]許多人缺乏公德心，隨處傾倒垃圾，造成環境汙染。　◎"]],"傾吐":[["ㄑㄧㄥ ㄊㄨˇ","將心中的話全部說出。[例]他滿懷心事，卻不肯向人傾吐。"]],"傾慕":[["ㄑㄧㄥ ㄇㄨˋ","傾心愛慕。[例]他們彼此傾慕已久，卻始終不敢向對方開口。"]],"傾斜":[["ㄑㄧㄥ ㄒㄧㄝˊ","歪斜。[例]強烈地震過後，許多房屋都傾斜了，十分危險。"]],"傾瀉":[["ㄑㄧㄥ ㄒㄧㄝˋ","液體大量從高處傾倒流瀉。[例]從斷崖上傾瀉而下的瀑布，猶如一條橫飛的白練。"]],"傾盆":[["ㄑㄧㄥ ㄆㄣˊ","形容雨勢大且急。[例]大雨突然傾盆而下，路上的行人走避不及，都成了落湯雞。"]],"傾盆大雨":[["ㄑㄧㄥ ㄆㄣˊ ㄉㄚˋ ㄩˇ","雨就像把水從盆子裡倒出來一樣大。形容雨勢又大又急。[例]一陣突如其來的傾盆大雨，讓路人都成了落湯雞。"]],"僅僅":[["ㄐㄧㄣˇ ㄐㄧㄣˇ","僅只、只有。[例]這棟大廈前後僅僅一年就完工了。"]],"僵局":[["ㄐㄧㄤ ㄐㄩˊ","相持不下，停滯而無法開展的局勢。[例]經過長時間的冷戰以後，我決定先打破僵局，主動向對方展現友好的態度。"]],"僵持":[["ㄐㄧㄤ ㄔˊ","相持不讓而無所進展。[例]與會雙方因各持己見，僵持不下，以致議程進行得相當不順利。"]],"僵硬":[["ㄐㄧㄤ ㄧㄥˋ","1.肢體不能靈活轉動。[例]他的雙手凍得僵硬，幾乎不聽使喚。\n2.呆板、生硬、不靈活。[例]他的想法太過僵硬，很難溝通。"]],"價值":[["ㄐㄧㄚˋ ㄓˊ","1.泛稱物品的價格、代價。[例]這幅名畫雖然價值不菲，卻是收藏家的最愛。\n2.意義、作用。[例]這批老照片對於考察臺灣過去的社會生活型態，具有很大的參考價值。"]],"儀式":[["ㄧˊ ㄕˋ","典禮的秩序、形式等。[例]他們的婚禮在簡單隆重的儀式中完成。"]],"儀態":[["ㄧˊ ㄊㄞˋ","儀表、姿態。[例]儀態高雅、儀態萬千"]],"億萬":[["ㄧˋ ㄨㄢˋ","比喻極大的數目。[例]他少年時白手起家，如今已是億萬富翁了。"]],"儘管":[["ㄐㄧㄣˇ ㄍㄨㄢˇ","1.不用考慮其他因素或加以節制，隨意去做。[例]大家儘管吃，別客氣。\n2.即使、雖然。[例]儘管他不來，我們還是會幫他保留一個位置。"]],"優待":[["ㄧㄡ ㄉㄞˋ","給予優厚的對待。[例]他一次購買了許多東西，因而老闆特別在價格上給予優待。"]],"優美":[["ㄧㄡ ㄇㄟˇ","良好、美妙。[例]此地山明水秀，風景優美，值得一遊。"]],"優雅":[["ㄧㄡ ㄧㄚˇ","優美高雅。[例]她的舉止優雅大方，氣質脫俗。"]],"儲存":[["ㄔㄨˊ ㄘㄨㄣˊ","1.積聚存放。[例]他儲存了一大筆錢，準備做為留學的費用。\n2.電腦將資料存於記憶體或記錄器。[例]資料輸入電腦後，要記得儲存。"]],"儲藏":[["ㄔㄨˊ ㄘㄤˊ","收存、貯藏。[例]仙人掌耐旱，是因為它的氣孔少，儲藏的水分不易蒸發。"]],"儼如":[["ㄧㄢˇ ㄖㄨˊ","好像。[例]遠遠望去，瀑布儼如一條白練，懸掛於山間。"]],"儼然":[["ㄧㄢˇ ㄖㄢˊ","1.莊重、恭敬的樣子。[例]他一改平日嬉鬧模樣，儼然端坐著，不發一語。\n2.整齊的樣子。[例]土地平曠，屋舍儼然。（晉．陶淵明〈桃花源記〉）\n3.彷彿、好像。[例]他年紀雖小，但言行舉止儼然大人一般。"]],"兀坐":[["ㄨˋ ㄗㄨㄛˋ","獨自端坐不動。[例]他一個人兀坐在窗戶邊，不知在沉思些什麼。"]],"兀自":[["ㄨˋ ㄗˋ","尚自、還是。[例]雖然聽到媽媽叫喚，他仍兀自賴在床上不肯起來。"]],"元寶":[["ㄩㄢˊ ㄅㄠˇ","1.中國古代用金或銀鑄造而成的貨幣。形似餃子。[例]金元寶、天福元寶　◎\n2.借指大年除夕吃的餃子。因為餃子形似元寶，象徵富裕吉祥。[例]我們家除夕夜一定要吃元寶，以討個吉祥。"]],"元氣":[["ㄩㄢˊ ㄑㄧˋ","人的精氣。[例]元氣大傷"]],"元素":[["ㄩㄢˊ ㄙㄨˋ","構成物質的基本原料，即用普通化學方法不能再分解的物質。分金屬、非金屬兩類。[例]所有化學物質都是由元素或數種元素化合而成的。　△化學元素"]],"兄嫂":[["ㄒㄩㄥ ㄙㄠˇ","哥哥和嫂嫂。[例]他北上求學期間，全蒙兄嫂照顧。"]],"兄弟":[["ㄒㄩㄥ ㄉㄧˋ","1.男子同胞先出生的為兄，後出生的為弟。[例]他們兄弟從小都是由外婆撫養長大的。\n\t\n2.泛指意氣相投的男性之間的朋友。[例]他們倆一直是同甘共苦的好兄弟。"],["ㄒㄩㄥ ˙ㄉㄧ","男子自謙之詞。[例]兄弟今天能有這個地位，全靠大家幫忙。"]],"充塞":[["ㄔㄨㄥ ㄙㄜˋ","充滿、塞滿。[例]每到晚上，夜來香濃郁的香氣，便充塞了整個房間。"]],"充沛":[["ㄔㄨㄥ ㄆㄟˋ","充足旺盛。[例]體力充沛、精力充沛"]],"充滿":[["ㄔㄨㄥ ㄇㄢˇ","1.填滿、裝滿。[例]小朋友可愛的表演，使得歡樂的氣氛充滿了整個會場。\n2.充分具備。[例]我們對國家未來的前途充滿信心。"]],"充裕":[["ㄔㄨㄥ ㄩˋ","充足豐裕。[例]資金充裕、時間充裕"]],"充電":[["ㄔㄨㄥ ㄉㄧㄢˋ","1.儲蓄電能。[例]無線電話機的話筒需要充電一段時間，才能離開主機單獨使用。\n2.比喻補充精力或充實實力。[例]工作了幾年，她打算重回校園再好好充電一番。"]],"充飢":[["ㄔㄨㄥ ㄐㄧ","吃東西以解除飢餓。[例]離中飯時間尚久，暫且吃些餅乾充飢吧！"]],"先後":[["ㄒㄧㄢ ㄏㄡˋ","前後相繼。[例]她們姊妹倆先後考上同一所大學。"]],"先生":[["ㄒㄧㄢ ㄕㄥ","1.對男子的尊稱。[例]李先生留美多年，對美國文化非常熟悉。\n2.對老師的尊稱。[例]在學校裡一定要聽先生的話，並遵守校規。\n3.對年長有道德、有學問或有專業技能者的尊稱。[例]錢穆先生是當代國學大師。\n4.妻子對他人稱自己的丈夫。[例]他跟我先生是多年的好友。"]],"先睹為快":[["ㄒㄧㄢ ㄉㄨˇ ㄨㄟˊ ㄎㄨㄞˋ","以優先看到而引以為樂。[例]新的影片即將上演，我要先睹為快。"]],"先覺":[["ㄒㄧㄢ ㄐㄩㄝˊ","知識、見解優於一般人的人。[例]他在政治思想方面的創見，被視為近代史上的先覺。"]],"先驅":[["ㄒㄧㄢ ㄑㄩ","在前面領導或開創事業的人。[例]孔子是開創平民教育的先驅。"]],"光怪陸離":[["ㄍㄨㄤ ㄍㄨㄞˋ ㄌㄨˋ ㄌㄧˊ","光怪，怪異的光景。陸離，色彩紛雜的樣子。光怪陸離形容事物現象奇異。[例]現代社會複雜多變，各種光怪陸離的事物，屢見不鮮。"]],"光明磊落":[["ㄍㄨㄤ ㄇㄧㄥˊ ㄌㄟˇ ㄌㄨㄛˋ","形容心地坦蕩、清白無私。[例]他為人光明磊落，從不做見不得人的事。"]],"光榮":[["ㄍㄨㄤ ㄖㄨㄥˊ","光彩、榮耀。[例]子女的任何成就，父母都會覺得很光榮。"]],"光澤":[["ㄍㄨㄤ ㄗㄜˊ","物體表面所反射出來的光輝。[例]這件銅雕作品，閃耀著動人的金屬光澤。"]],"光禿禿":[["ㄍㄨㄤ ㄊㄨ ㄊㄨ","空蕩、裸露的樣子。[例]濫墾濫伐的結果，往往使山頭光禿禿的一片。"]],"光線":[["ㄍㄨㄤ ㄒㄧㄢˋ","光。因為光在同介質中行進的途徑為一直線，故稱為「光線」。[例]在光線昏暗的地方看書，會傷害視力。"]],"光芒":[["ㄍㄨㄤ ㄇㄤˊ","四散射出的光線。[例]光芒萬丈"]],"光輝":[["ㄍㄨㄤ ㄏㄨㄟ","光芒、光彩。[例]她抱著嬰兒餵奶，臉上洋溢著母性的光輝。"]],"光陰":[["ㄍㄨㄤ ㄧㄣ","時間。[例]一寸光陰一寸金，寸金難買寸光陰。"]],"光陰似箭":[["ㄍㄨㄤ ㄧㄣ ㄙˋ ㄐㄧㄢˋ","形容時間消逝如飛箭般迅速。[例]光陰似箭，歲月如梭，轉眼又過了一年。"]],"克勤克儉":[["ㄎㄜˋ ㄑㄧㄣˊ ㄎㄜˋ ㄐㄧㄢˇ","既能勤勞，又能節儉。語本《書經‧大禹謨》。[例]這些年來他省吃儉用，過著克勤克儉的日子，就是希望能實現出國留學的夢想。"]],"克服":[["ㄎㄜˋ ㄈㄨˊ","制服、解決困難。[例]這件事不管有多困難，我們都要想辦法去克服它。"]],"免得":[["ㄇㄧㄢˇ ˙ㄉㄜ","避免。[例]出外旅遊要注意安全，免得父母擔心。"]],"免疫":[["ㄇㄧㄢˇ ㄧˋ","1.生物對某病原體或毒素自然產生抵抗力的現象。[例]得過麻疹後，通常可以終身免疫。\n2.比喻不受某人、事或物的干擾或影響。[例]我對你的冷嘲熱諷早已免疫了。"]],"免費":[["ㄇㄧㄢˇ ㄈㄟˋ","不用繳交應付的費用。[例]這家小吃店新開張，特地舉辦免費試吃，吸引了許多顧客上門。"]],"兒子":[["ㄦˊ ˙ㄗ","稱謂。父母對所生男孩的稱呼。[例]他是李媽媽唯一的兒子。　◎"]],"兒孫":[["ㄦˊ ㄙㄨㄣ","後代，即子孫。[例]兒孫自有兒孫福。"]],"兒童":[["ㄦˊ ㄊㄨㄥˊ","指年紀小，未成年的男女。[例]天才兒童"]],"兔子":[["ㄊㄨˋ ˙ㄗ","→兔"]],"入侵":[["ㄖㄨˋ ㄑㄧㄣ","侵略國境。[例]我方軍容壯盛，敵人不敢輕易入侵。"]],"入口":[["ㄖㄨˋ ㄎㄡˇ","1.進入口中。[例]入口即化_x000D_\n2.進入建築物或特定場地所經過的門或關卡。[例]體育館入口、停車場入口_x000D_\n3.外國或外地的貨物輸入本國或本地。[例]入口貿易_x000D_"]],"入場券":[["ㄖㄨˋ ㄔㄤˇ ㄑㄩㄢˋ","1.進入某場所時，持有許可進入的票券。[例]今晚職棒賽的入場券，一票難求。\n2.借指為參加某種比賽的資格。[例]決賽獲得冠亞軍的隊伍才有資格獲得參加奧運的入場券。"]],"入座":[["ㄖㄨˋ ㄗㄨㄛˋ","於會議筵席或其他場所各就座位。[例]會議即將開始，請各位同仁趕快入座。"]],"入迷":[["ㄖㄨˋ ㄇㄧˊ","專注於某種事物而到了沉迷的程度。[例]他看偵探小說看得入迷了，沒有聽到媽媽的叫喚。"]],"入選":[["ㄖㄨˋ ㄒㄩㄢˇ","中選，被選上。[例]這次英文朗誦比賽，共有三位同學入選，將代表本校對外參賽。"]],"內容":[["ㄋㄟˋ ㄖㄨㄥˊ","1.事物內部所包含的實質或意義。[例]本次活動內容有抽獎、親子遊戲等。\n2.文學或藝術作品中所含的意義或精神。[例]一首好詩，應該具備優美的意境、充實的內容及深刻的思想。"]],"內心":[["ㄋㄟˋ ㄒㄧㄣ","1.泛指思想或感情。因為心是思想的主體，二者又都在身體內，故稱為「內心」。[例]他經過不斷的努力，終於考上理想的學校，因此內心充滿喜悅。\n2.三角形內切圓的圓心。由三角形三內角的三條平分線相交於一點，此點即為三角形內切圓的圓心。[例]三角形內心至各邊的距離相等。"]],"內涵":[["ㄋㄟˋ ㄏㄢˊ","1.內在的涵養。[例]他學問廣博，是個很有內涵的人。\n2.邏輯學上指概念的內容，相對於外延而言。即構成概念的要素總和，多為抽象性的本質。如有理性，是「人」的內涵。"]],"內省":[["ㄋㄟˋ ㄒㄧㄥˇ","自我觀察與反省。[例]寫日記可以使我們有內省的機會。"]],"內臟":[["ㄋㄟˋ ㄗㄤˋ","人或動物的體腔內的各種器官。如心、肺、胃、腸、肝、腎等。[例]隨著醫學常識的增進，國人越來越少吃動物的內臟。"]],"內部":[["ㄋㄟˋ ㄅㄨˋ","裡面的部分。[例]房子內部的裝潢工程已經開始進行，月底即可完成。"]],"全力以赴":[["ㄑㄩㄢˊ ㄌㄧˋ ㄧˇ ㄈㄨˋ","投入全部的心力以達成目的。[例]國家籃球代表隊誓言將全力以赴爭取最高榮譽。"]],"全壘打":[["ㄑㄩㄢˊ ㄌㄟˇ ㄉㄚˇ","棒球、壘球比賽中，打擊手擊出越過全壘打線的球，依規則可安全的經由一、二、三壘回到本壘得分。[例]我隊在打擊手擊出一支滿貫全壘打得到四分後，已將比數明顯拉開，勝利在望。"]],"全家":[["ㄑㄩㄢˊ ㄐㄧㄚ","一家人。[例]春節期間，我們全家打算出國旅遊。"]],"全數":[["ㄑㄩㄢˊ ㄕㄨˋ","全部、所有。[例]警方將查緝到的違禁品全數銷毀。"]],"全球":[["ㄑㄩㄢˊ ㄑㄧㄡˊ","全世界，整個地球。[例]由於人類任意砍伐林木，全球熱帶雨林的面積正急速縮小。"]],"全神貫注":[["ㄑㄩㄢˊ ㄕㄣˊ ㄍㄨㄢˋ ㄓㄨˋ","將心思和精神完全集中在某事物上。[例]他全神貫注的聆聽音樂，連門鈴響了也不知道。"]],"兩敗俱傷":[["ㄌㄧㄤˇ ㄅㄞˋ ㄐㄩˋ ㄕㄤ","雙方相爭，同受損害。[例]這麼做只會弄得兩敗俱傷，對雙方都沒有好處。"]],"兩端":[["ㄌㄧㄤˇ ㄉㄨㄢ","兩頭，事物的兩個端點。[例]她把繩子的兩端各打上一個結，以防串連在中間的珠子掉落。"]],"八卦":[["ㄅㄚ ㄍㄨㄚˋ","《易經》中的八種符號。相傳為伏羲氏所作，三爻成卦，爻有陰、陽之別，由陰、陽爻組成八種不同的形式，即為八卦，借以象徵自然現象及人事的變化。八卦為乾（☰）、坤（☷）、震（☳）、艮（☶）、離（☲）、坎（☵）、兌（☱）、巽（☴）。[例]傳統的算命方法，常以八卦​來​推算​命運​的​吉凶。"]],"八方":[["ㄅㄚ ㄈㄤ","東、南、西、北、東南、西南、東北、西北八個方向的總稱，一般泛指所有的方向。[例]四面八方"]],"公主":[["ㄍㄨㄥ ㄓㄨˇ","天子或國王的女兒。[例]童話世界裡的白雪公主是個善體人意的女孩，人見人愛。"]],"公休":[["ㄍㄨㄥ ㄒㄧㄡ","商店經同業公會決定，於每月的某一日集體停業休息，稱為「公休」。[例]本店於每個月的第二個星期日公休。"]],"公司":[["ㄍㄨㄥ ㄙ","依公司法登記成立的社團法人營利企業組織。可分無限公司、有限公司、股份有限公司、兩合公司、股份兩合公司等五類。[例]服裝公司、建設公司"]],"公園":[["ㄍㄨㄥ ㄩㄢˊ","經過造園處理或保留其自然狀態，以作為公眾戶外遊憩及享受大自然的特定場所。[例]陽明山國家公園的花季，每年都吸引大批的賞花人潮。"]],"公寓":[["ㄍㄨㄥ ㄩˋ","可供多戶人家居住的寓所，為多層或多排的住宅建築物。[例]放眼望去，這一帶盡是公寓住家。"]],"公尺":[["ㄍㄨㄥ ㄔˇ","量詞。計算長度的單位。公制一公尺等於100公分。"]],"公布":[["ㄍㄨㄥ ㄅㄨˋ","公開宣示。[例]本次徵才錄取名單將在明天公布。"]],"公平":[["ㄍㄨㄥ ㄆㄧㄥˊ","不偏私。[例]公平分配、公平交易"]],"公廁":[["ㄍㄨㄥ ㄘㄜˋ","供公眾使用的廁所。[例]使用公廁，應注意維護清潔。"]],"公斤":[["ㄍㄨㄥ ㄐㄧㄣ","量詞。計算重量的單位。公制一公斤等於1000公克。　△斤"]],"公正":[["ㄍㄨㄥ ㄓㄥˋ","公平正直，沒有偏私。[例]公正無私"]],"公物":[["ㄍㄨㄥ ㄨˋ","屬於公家或團體的東西或設施。[例]大家要愛惜公物。"]],"公筷":[["ㄍㄨㄥ ㄎㄨㄞˋ","用餐時，為了保持衛生，避免疾病傳染，而設置的公用不沾口的挾菜筷子。[例]宴客時使用公筷挾菜，能降低疾病傳染的機率。"]],"公約":[["ㄍㄨㄥ ㄩㄝ","多數國家或公私團體對於特定事項，所擬訂共同遵守的條約或章程。[例]華沙公約、學生生活公約、北大西洋公約"]],"公轉":[["ㄍㄨㄥ ㄓㄨㄢˋ","一個天體繞著另一個天體做週期性的轉動。如太陽系裡的行星繞著太陽旋轉、各行星的衛星繞著行星轉，皆稱為「公轉」。[例]地球繞著太陽公轉一周所需的時間為一年。"]],"公里":[["ㄍㄨㄥ ㄌㄧˇ","量詞。計算長度的單位。公制一公里等於一千公尺。　△里"]],"共享":[["ㄍㄨㄥˋ ㄒㄧㄤˇ","共同分享、一起擁有。[例]這次的工作成果將由大夥兒共享。"]],"共同":[["ㄍㄨㄥˋ ㄊㄨㄥˊ","1.一起、一同。[例]這件事情需要靠大家共同努力來完成。\n2.公有的。[例]那家工廠是他們兄弟共同的產業。"]],"共鳴":[["ㄍㄨㄥˋ ㄇㄧㄥˊ","1.發音體因受到與本身振動頻率相同的音波影響，也隨之產生發音的現象。如兩個頻率相同的音叉放在一起，敲擊其中一個使它發出聲音，另外一個音叉也會跟著發出聲音。[例]弦樂器的音箱如果製作精巧，使共鳴良好，將可發出美妙的聲響。\n2.共同的感受或情緒反應。[例]臺上演講者慷慨陳辭，引起廣大聽眾的共鳴。"]],"兵器":[["ㄅㄧㄥ ㄑㄧˋ","武器。[例]弓箭在古代是一種兵器。"]],"兵役":[["ㄅㄧㄥ ㄧˋ","國民依照法規對國家服一定期限的軍事義務。"]],"兵連禍結":[["ㄅㄧㄥ ㄌㄧㄢˊ ㄏㄨㄛˋ ㄐㄧㄝˊ","接連用兵，戰禍不絕。[例]今天仍有許多國家內戰難息，兵連禍結，害苦了百姓。"]],"兵馬俑":[["ㄅㄧㄥ ㄇㄚˇ ㄩㄥˇ","古代作成士兵及戰馬形狀用以殉葬的陶偶。特指西元1974年，陝西臨潼秦始皇陵出土的人馬形陶偶。"]],"其他":[["ㄑㄧˊ ㄊㄚ","除此之外、別的。[例]我的報告到此結束，大家還有其他的疑問嗎？"]],"具體":[["ㄐㄩˋ ㄊㄧˇ","有實體存在，或明確而非抽象、籠統的。[例]只有空想，而沒有具體行動，夢想是無法成真的。"]],"典型":[["ㄉㄧㄢˇ ㄒㄧㄥˊ","1.舊法、模範。[例]哲人日已遠，典型在夙昔。（宋．文天祥〈正氣歌〉）\n2.某一類人事物中有概括性或代表性意義的。[例]星際大戰正是科幻戰爭片的典型代表。"]],"典禮":[["ㄉㄧㄢˇ ㄌㄧˇ","公開且莊重的儀式。[例]每年元旦，總統府前都會舉行升旗典禮。"]],"典雅":[["ㄉㄧㄢˇ ㄧㄚˇ","優雅而不鄙俗。多形容文章。[例]她的文章用詞典雅，頗得老師賞識。"]],"兼具":[["ㄐㄧㄢ ㄐㄩˋ","同時具備。[例]這款產品不僅有新潮的款式，同時兼具實用的功能。"]],"兼職":[["ㄐㄧㄢ ㄓˊ","1.在本職外另兼任其他職務。[例]他除了在學校教書外，在行政方面尚有兼職。\n2.兼差性的職務。相對於專職而言。[例]他想找一份兼職，以增加收入。"]],"再見":[["ㄗㄞˋ ㄐㄧㄢˋ","再相見。亦為臨別時的客套語。[例]你這一去，不知何時才能再見？"]],"冒失":[["ㄇㄠˋ ㄕ","鹵莽、莽撞。[例]他做事一向冒失，從不考慮後果如何。"]],"冒煙":[["ㄇㄠˋ ㄧㄢ","1.煙向上升起。[例]那幢房子在冒煙，好像失火了。\n2.形容很生氣。[例]每次一提起那件糗事，他就氣得冒煙。"]],"冒犯":[["ㄇㄠˋ ㄈㄢˋ","衝撞、得罪。[例]若有冒犯之處，還請多包涵。"]],"冒險":[["ㄇㄠˋ ㄒㄧㄢˇ","不顧危險而從事某一活動。[例]他冒險突圍，令人捏一把冷汗。"]],"冠軍":[["ㄍㄨㄢˋ ㄐㄩㄣ","考試或比賽得第一名。[例]她在舞蹈比賽中脫穎而出，成為歷年最年輕的冠軍得主。"]],"冤枉":[["ㄩㄢ ㄨㄤˇ","1.誣賴、陷害。[例]在事情未查明之前，別隨便冤枉他人。\n2.形容白白浪費，無實質效益。[例]這筆錢花得有點冤枉。"]],"冥冥之中":[["ㄇㄧㄥˊ ㄇㄧㄥˊ ㄓ ㄓㄨㄥ","人無法預測、理解、控制的狀況。[例]我們的姻緣冥冥之中似乎早已注定。"]],"冬天":[["ㄉㄨㄥ ㄊㄧㄢ","一年中氣候最寒冷的一季。我國冬天約當農曆十月至十二月。[例]他們決定今年冬天到北歐賞雪。"]],"冬筍":[["ㄉㄨㄥ ㄙㄨㄣˇ","毛竹的筍。生長在向陽溫暖的地方，肉呈淺黃色，質脆味美。因產於冬日，故稱為「冬筍」。[例]涼拌冬筍"]],"冬至":[["ㄉㄨㄥ ㄓˋ","二十四節氣之一。約當國曆十二月二十二或二十三日，這天北半球夜最長、晝最短，南半球相反。民間習俗多在當日以湯圓祭祀祖先、神明。[例]冬至的日照最短，過了這一天，白晝就逐漸變長了。 △冬節、南至"]],"冰冷":[["ㄅㄧㄥ ㄌㄥˇ","1.天氣寒冷或物體冰涼。[例]你的手怎麼這麼冰冷呢？\n2.態度冷漠、不熱情。[例]他對我不理不睬，態度相當冰冷。"]],"冰棒":[["ㄅㄧㄥ ㄅㄤˋ","在模型中倒入果汁、糖水、紅豆湯或牛奶等，並插入竹條或木條，置於冷凍箱中，凍結而成的棒狀冰品。[例]炎炎夏日裡，吃一枝冰棒，真是清涼消暑。　△冰棍"]],"冰箱":[["ㄅㄧㄥ ㄒㄧㄤ","→電冰箱"]],"冷冽":[["ㄌㄥˇ ㄌㄧㄝˋ","寒冷、冰涼。[例]梅花在冷冽的寒風中依舊盛開。"]],"冷凍":[["ㄌㄥˇ ㄉㄨㄥˋ","將食物保存在低溫的狀態中，使食物凝固、凍結，以抑制細菌的繁殖、防止有機體的腐敗，達到保藏的效果。[例]冷凍的食物在解凍後，必須儘快處理，否則容易孳生細菌。"]],"冷媒":[["ㄌㄥˇ ㄇㄟˊ","飛機推進燃料、冰箱、冷氣系統等所使用的發冷劑。產生的原理是在原料不斷反覆循環、液化過程中，吸收周圍熱量以達到冷卻的效應。無毒、不燃燒、不爆炸、無侵蝕性、氣化熱大及容易液化的流體，如氨、氟、氯化物等，較適合做冷媒。　△氟氯烷"]],"冷氣":[["ㄌㄥˇ ㄑㄧˋ","1.冷的氣流。[例]一走進這個山洞，便有一股冷氣迎面襲來。_x000D_\n2.→冷氣機"]],"冷氣團":[["ㄌㄥˇ ㄑㄧˋ ㄊㄨㄢˊ","移動的大氣環流，如果本身溫度比所到區域的地面溫度低，便形成冷氣團，會使天氣變冷。[例]這次的大陸冷氣團南下，造成各地氣溫降至10度以下，創下今年入冬以來的最低溫。"]],"冷漠":[["ㄌㄥˇ ㄇㄛˋ","冷淡、不親熱、不關心。[例]他外表看似冷漠，其實內心熱情開朗。"]],"冷箭":[["ㄌㄥˇ ㄐㄧㄢˋ","原指趁人不備時，暗中射出冷箭。後比喻暗中害人的行為。[例]放冷箭"]],"冷酷":[["ㄌㄥˇ ㄎㄨˋ","對人冷漠、毫無感情。[例]面對親人的過世，他一點也不悲傷難過，真是個冷酷無情的人。"]],"冷靜":[["ㄌㄥˇ ㄐㄧㄥˋ","形容沉著、理智而不感情用事。[例]遇到重大事情時，頭腦必須保持冷靜，才能想出最適當的解決辦法。"]],"冷風":[["ㄌㄥˇ ㄈㄥ","寒涼陰冷的風。[例]冬夜的冷風，把街上的行人趕回溫暖的家。"]],"冷飲":[["ㄌㄥˇ ㄧㄣˇ","清涼的飲料。[例]炎炎夏日，大家都喜歡喝冷飲解渴。"]],"冽霜":[["ㄌㄧㄝˋ ㄕㄨㄤ","寒冷的霜雪。[例]牆角的臘梅冒著冽霜，開放出清雅芳潔的花朵。"]],"准許":[["ㄓㄨㄣˇ ㄒㄩˇ","許可。[例]小明感冒發燒，老師准許他請假回家休息。"]],"凋謝":[["ㄉㄧㄠ ㄒㄧㄝˋ","1.枯萎、零落。[例]在寒風的侵襲下，枝頭上的花兒都凋謝了。　◎\n2.比喻人衰老死亡。[例]人才凋謝"]],"凋零":[["ㄉㄧㄠ ㄌㄧㄥˊ","1.凋謝零落。[例]昨夜的一場狂風暴雨，使得院子裡的桂花紛紛凋零。\n2.衰敗、衰落。[例]他家本是當地望族，但經過多年的人事變遷後已漸漸凋零。"]],"凌亂":[["ㄌㄧㄥˊ ㄌㄨㄢˋ","雜亂沒有秩序。[例]她的書房總是整整齊齊的，從不凌亂。"]],"凌厲":[["ㄌㄧㄥˊ ㄌㄧˋ","形容氣勢猛烈，奮發直前。[例]在我方凌厲的攻勢下，敵軍節節敗退。"]],"凌晨":[["ㄌㄧㄥˊ ㄔㄣˊ","清晨、黎明。[例]爺爺習慣在凌晨四點起床，到附近的山上運動。"]],"凌空":[["ㄌㄧㄥˊ ㄎㄨㄥ","騰越於天空中。[例]季節交替之時，常可見成群的候鳥凌空而過。"]],"凌辱":[["ㄌㄧㄥˊ ㄖㄨˋ","欺負侮辱。"]],"凌駕":[["ㄌㄧㄥˊ ㄐㄧㄚˋ","超越、勝過。[例]我國在經濟方面的成就，早已凌駕世界上先進國家之上。"]],"凜冽":[["ㄌㄧㄣˇ ㄌㄧㄝˋ","形容天氣非常寒冷。[例]凜冽的寒風使人們不得不穿上厚重的大衣。"]],"凝結":[["ㄋㄧㄥˊ ㄐㄧㄝˊ","1.液體變成固體或氣體變成液體的現象。[例]南下的強烈寒流，把湖面的水凝結成一層薄冰。\n2.凝聚、集結。 [例]雖然門窗都已關緊，但屋內寒氣凝結，還是令人凍得直發抖。"]],"凝視":[["ㄋㄧㄥˊ ㄕˋ","目不轉睛的看著。[例]屏息凝視"]],"凝鍊":[["ㄋㄧㄥˊ ㄌㄧㄢˋ","形容文章簡潔精鍊、扼要有力。[例]文章寫作應力求凝鍊，切忌冗長蕪雜。"]],"凡事":[["ㄈㄢˊ ㄕˋ","無論什麼事情。[例]她心思縝密，凡事都能替人設想周到。"]],"凱旋":[["ㄎㄞˇ ㄒㄩㄢˊ","得勝歸來。[例]今年的世界少棒賽，我國代表隊大獲全勝，凱旋而歸。"]],"凶嫌":[["ㄒㄩㄥ ㄒㄧㄢˊ","有行凶嫌疑的人。[例]命案發生後，警方逮捕兩名凶嫌。"]],"凶悍":[["ㄒㄩㄥ ㄏㄢˋ","凶狠強悍。[例]他理虧還罵人，真是凶悍。"]],"凶狠":[["ㄒㄩㄥ ㄏㄣˇ","殘暴狠毒。[例]歹徒做案的手法非常凶狠，引起社會人士的同聲譴責。"]],"凶猛":[["ㄒㄩㄥ ㄇㄥˇ","凶惡猛烈。[例]獅子和老虎都是凶猛的動物。"]],"凶神惡煞":[["ㄒㄩㄥ ㄕㄣˊ ㄜˋ ㄕㄚˋ","凶惡的神魔。用以指凶惡的人。[例]這家人一個個都是凶神惡煞，鄰居們都不願意和他們來往。"]],"凸顯":[["ㄊㄨˊ ㄒㄧㄢˇ","凸出顯現。[例]他喜歡穿著奇裝異服來凸顯自己的與眾不同。"]],"凹凸不平":[["ㄠ ㄊㄨˊ ㄅㄨˋ ㄆㄧㄥˊ","物體表面有高有低不平整的。[例]這條山路凹凸不平，真是難以行走！"]],"凹癟":[["ㄠ ㄅㄧㄝˇ","凹下去、不飽滿。[例]牙齒脫落，嘴部就會凹癟。"]],"出來":[["ㄔㄨ ㄌㄞˊ","1.自內部來到外面。[例]上完洗手間出來時，記得洗手。_x000D_\n2.顯露、出現。[例]老師把學生作文上的錯字都圈出來，讓他們訂正。_x000D_\n3.出面、出頭。[例]眼見雙方發生衝突，他急忙出來打圓場。_x000D_\n4.行為的實現、完成。[例]這份報告他在兩天之內一定會整理出來。"]],"出借":[["ㄔㄨ ㄐㄧㄝˋ","借出，借給他人。[例]為保管書籍，期刊限在圖書館中閱讀，概不出借。"]],"出入":[["ㄔㄨ ㄖㄨˋ","1.出外與入內。[例]出入大樓請隨手關門，以確保居家安全。\n2.收入與支出。[例]本公司的金錢出入由出納負責管理。\n3.不一致。[例]關於此事，雙方說法頗有出入，最好再深入查證。"]],"出口":[["ㄔㄨ ㄎㄡˇ","1.出言、脫口而出。[例]無論多麼生氣，他也從不以穢言出口傷人。\n2.將本國貨物運到外國。[例]農產品是臺灣以往出口的大宗。\n3.供外出的門口。相對於入口而言。[例]同學們請自由參觀，兩個小時後在出口集合。"]],"出售":[["ㄔㄨ ㄕㄡˋ","販賣、銷售。[例]這家百年老店專門出售中式糕點。"]],"出奇制勝":[["ㄔㄨ ㄑㄧˊ ㄓˋ ㄕㄥˋ","發奇兵或用奇計制敵而獲勝。比喻以奇特、創新的方法獲勝。語本《孫子．勢》。[例]他有獨到的眼光和雄強的膽識，因而在商場上屢次出奇制勝，幾乎無往不利。"]],"出局":[["ㄔㄨ ㄐㄩˊ","1.棒球比賽中指球員因被三振、接殺、封殺等原因，而喪失打擊、跑壘等資格。[例]三振出局、接殺出局\n2.比喻喪失參與資格或權利。[例]董事會審查經理候選人的資格，小張因人品不佳而被判出局。"]],"出席":[["ㄔㄨ ㄒㄧˊ","到場參加。[例]這個活動要求與會者簽到，方可列入出席紀錄。"]],"出爐":[["ㄔㄨ ㄌㄨˊ","1.從烤爐中取出。[例]剛出爐的麵包，香酥鬆軟，特別可口。\n2.引申為產生、誕生。[例]她是今年新出爐的影后，備受矚目。"]],"出版":[["ㄔㄨ ㄅㄢˇ","將文稿、資料等編印成圖書報刊，以供出售或傳布。[例]這位作家的新作即將出版，預約可享八折優待。"]],"出現":[["ㄔㄨ ㄒㄧㄢˋ","產生、顯現。[例]雷雨初霽，天上出現一道彩虹。"]],"出言不遜":[["ㄔㄨ ㄧㄢˊ ㄅㄨˋ ㄒㄩㄣˋ","形容人講話傲慢無禮。[例]他經常恃才傲物，出言不遜，同事朋友都對他敬而遠之。"]],"出讓":[["ㄔㄨ ㄖㄤˋ","將財貨轉讓或出售。[例]他因為急需用錢，只好將房子廉價出讓。"]],"出門":[["ㄔㄨ ㄇㄣˊ","離家外出。[例]出門在外，凡事要自己當心。"]],"刀背":[["ㄉㄠ ㄅㄟˋ","刀上無刃的一邊。[例]做菜時通常用刀背來敲碎蒜頭。"]],"刀鋒":[["ㄉㄠ ㄈㄥ","刀刃、刀口。[例]這把刀的刀鋒非常銳利，我們得小心使用！"]],"刁鑽":[["ㄉㄧㄠ ㄗㄨㄢ","奸詐、狡猾。[例]刁鑽古怪"]],"分享":[["ㄈㄣ ㄒㄧㄤˇ","共同享受。[例]他將好消息告訴朋友，讓朋友分享他的喜悅。"]],"分割":[["ㄈㄣ ㄍㄜ","1.拿刀將原本相連的物體切開。[例]大夫明天將進行連體嬰分割手術。\n2.將有關連的事物分開。[例]人類情感中的愛與恨，常相伴而生，難以分割。"]],"分工合作":[["ㄈㄣ ㄍㄨㄥ ㄏㄜˊ ㄗㄨㄛˋ","將一件事分由眾人共同完成。[例]大家分工合作，事情較易完成。"]],"分心":[["ㄈㄣ ㄒㄧㄣ","1.用一部分精神兼顧別的事。[例]他工作相當忙碌，還要分心指導我，真是辛苦。\n2.分散注意力。[例]一邊看書，一邊看電視，容易分心。"]],"分數":[["ㄈㄣ ㄕㄨˋ","1.競賽或考試所得的成績。[例]他這一次月考各科的分數都還不錯。\n2.數學上指以除法表示的數。如 3/4即為分數，3為分子，4為分母。"]],"分毫":[["ㄈㄣ ㄏㄠˊ","比喻極細微。[例]分毫不差、分毫不取"]],"分組":[["ㄈㄣ ㄗㄨˇ","將團體分成若干小單位，每一單位稱為「一組」。[例]分組討論"]],"分裂":[["ㄈㄣ ㄌㄧㄝˋ","1.分開、割裂。[例]東、西德在二次大戰後分裂了幾十年，終於統一。\n2.特指細胞因增殖而分為兩體。[例]細胞分裂"]],"分辨":[["ㄈㄣ ㄅㄧㄢˋ","辨別。[例]這對雙胞胎長得實在太像了，很難分辨誰是誰。"]],"分配":[["ㄈㄣ ㄆㄟˋ","分攤、調配。[例]各種能源都應該合理分配運用。"]],"分量":[["ㄈㄣˋ ㄌㄧㄤˋ","1.事物的輕重、多寡。[例]他的工作分量很重，幾乎每天得加班。\n2.權力、地位的大小、高低。[例]在公司裡，他是個有分量的人。"]],"分針":[["ㄈㄣ ㄓㄣ","鐘錶上的指針有時針、分針、秒針，其長於時針，且指示以分為單位之時間者，稱為「分針」。[例]十二點整的時候，時鐘上的分針會與時針重疊。"]],"分鐘":[["ㄈㄣ ㄓㄨㄥ","量詞。計算時間的單位。六十分鐘為一小時。[例]她只花了十分鐘，就把事情做完了。"]],"分隔":[["ㄈㄣ ㄍㄜˊ","分離阻隔而不能相通。[例]分隔兩地、陰陽分隔"]],"分離":[["ㄈㄣ ㄌㄧˊ","1.分開、隔離。[例]濾網可以將水中的部分雜質分離。\n2.離別。[例]明天就要分離了，大家都覺得依依不捨。"]],"分類":[["ㄈㄣ ㄌㄟˋ","區分類別。[例]垃圾分類、檔案分類"]],"切割":[["ㄑㄧㄝ ㄍㄜ","切斷割開。[例]父母即便再生氣、失望，仍無法切割對子女的關心。"]],"切斷":[["ㄑㄧㄝ ㄉㄨㄢˋ","切割斷絕。[例]我軍成功的切斷敵人的補給線，促使敵人提早投降。"]],"切莫":[["ㄑㄧㄝˋ ㄇㄛˋ","千萬不要。[例]酒後切莫開車，以免發生危險。"]],"切記":[["ㄑㄧㄝˋ ㄐㄧˋ","務必記住、千萬牢記。[例]不管敵人如何叫囂，切記不可自亂陣腳。"]],"切身":[["ㄑㄧㄝˋ ㄕㄣ","1.與自身密切相關。[例]這個決定事關切身利害，請務必慎重考慮。\n2.親身、自身。[例]那一次切身體驗的教訓，令我終生難忘。"]],"切除":[["ㄑㄧㄝ ㄔㄨˊ","切割除掉。[例]李太太上星期到醫院動手術，把子宮肌瘤切除了。"]],"刊登":[["ㄎㄢ ㄉㄥ","在報刊上登載。[例]這本雜誌一向以刊登奇人軼事吸引讀者。"]],"刊載":[["ㄎㄢ ㄗㄞˋ","發表刊登。[例]報紙刊載了非洲難民的消息後，已獲得廣大的迴響，各界紛紛發起捐款活動。"]],"划槳":[["ㄏㄨㄚˊ ㄐㄧㄤˇ","1.划動船槳。[例]湖上風平浪靜，三五船夫划槳而過。_x000D_\n2.船槳。"]],"划算":[["ㄏㄨㄚˊ ㄙㄨㄢˋ","合算、值得。[例]在換季打折時買衣服比較划算。"]],"列印":[["ㄌㄧㄝˋ ㄧㄣˋ","依次印出。[例]他將電腦中的資料列印出來校對修正。"]],"列舉":[["ㄌㄧㄝˋ ㄐㄩˇ","逐一舉出。[例]店員列舉各項產品的優缺點，讓客戶能夠比較選購。"]],"列隊":[["ㄌㄧㄝˋ ㄉㄨㄟˋ","依次排成整齊的隊伍。[例]校慶時，同學們在校門口列隊歡迎嘉賓的蒞臨。"]],"初一":[["ㄔㄨ ㄧ","本指農曆每月的第一天。今亦指國曆每月的第一天。[例]本公司固定在每月初一發薪水。"]],"初戀":[["ㄔㄨ ㄌㄧㄢˋ","第一次的戀愛。[例]少年時期的初戀，是他一生美好的回憶。"]],"初級":[["ㄔㄨ ㄐㄧˊ","最低的層次。[例]他通過初級考試，取得了晉級資格。"]],"判斷":[["ㄆㄢˋ ㄉㄨㄢˋ","判別斷定。[例]事情還未全面了解前，難以判斷是非曲直。"]],"判斷力":[["ㄆㄢˋ ㄉㄨㄢˋ ㄌㄧˋ","判別斷定事物的能力。[例]他對商機的判斷力很強，所以做生意一直賺大錢。"]],"判決":[["ㄆㄢˋ ㄐㄩㄝˊ","法院依據法律對訴訟案件所做的裁斷。[例]他對法院的判決不服，打算提起上訴。"]],"別出心裁":[["ㄅㄧㄝˊ ㄔㄨ ㄒㄧㄣ ㄘㄞˊ","獨出巧思，與眾不同。[例]這是一場別出心裁的宴會。"]],"別管":[["ㄅㄧㄝˊ ㄍㄨㄢˇ","1.不要理睬、干涉。[例]別管閒事！\n2.無論。[例]別管是誰的案子，一律按規定辦理。"]],"別號":[["ㄅㄧㄝˊ ㄏㄠˋ","本名之外另取的稱號。如唐朝李白別號青蓮居士。"]],"別針":[["ㄅㄧㄝˊ ㄓㄣ","1.一種用來將物品暫時固定或密合的針。[例]我的裙扣掉了，暫時用別針別一下。　△繃針　◎\n2.別在衣領或胸襟上的裝飾品。[例]這件景泰藍的蝴蝶別針十分別緻。　△胸針　◎"]],"利潤":[["ㄌㄧˋ ㄖㄨㄣˋ","將營業所得扣除成本後所剩餘的利益。[例]他以賣竹筒飯的微薄利潤來維持一家大小的生活。"]],"利用":[["ㄌㄧˋ ㄩㄥˋ","1.發揮物資的功用。[例]廢物利用\n2.用人或事物做為憑藉來達到目的。[例]詐騙集團常利用人的貪念，來騙取錢財。"]],"利益":[["ㄌㄧˋ ㄧˋ","好處。[例]身為一個國家公僕，應該置個人利益於度外，全心全意為人民服務。"]],"利誘":[["ㄌㄧˋ ㄧㄡˋ","以財物利益引誘他人。[例]威脅利誘"]],"刪改":[["ㄕㄢ ㄍㄞˇ","刪除改正。[例]這篇文章經數次刪改，才正式定稿。"]],"刪節號":[["ㄕㄢ ㄐㄧㄝˊ ㄏㄠˋ","一種標點符號。用來表示節略原文或語句未完、意思未盡，其符號為「……」。[例]在小說寫作中常用刪節號來表示說話人的沉默或無言以對。"]],"刪除":[["ㄕㄢ ㄔㄨˊ","去掉、去除。[例]由於經費不足，上級決定刪除一些年度企劃案。"]],"刮傷":[["ㄍㄨㄚ ㄕㄤ","被銳利的東西磨擦或碰觸而損傷。[例]這輛新車在行經山路時，碰到山壁而刮傷了。"]],"到底":[["ㄉㄠˋ ㄉㄧˇ","1.到盡頭。[例]堅持到底\n2.究竟。[例]他到底那一點好，讓你這麼袒護他？\n3.終於。[例]等到開演前一分鐘，他們到底趕來了。"]],"到處":[["ㄉㄠˋ ㄔㄨˋ","處處、各處。[例]選舉期間到處都貼滿了競選標語。"]],"到達":[["ㄉㄠˋ ㄉㄚˊ","抵達某一地點或目的。[例]依目前的情形估計，我們大約下午三點鐘可到達目的地。"]],"制伏":[["ㄓˋ ㄈㄨˊ","用強力壓伏。[例]警察當場制伏了想要脫逃的歹徒。"]],"制度":[["ㄓˋ ㄉㄨˋ","制定的法度。[例]管理制度、人事制度"]],"制服":[["ㄓˋ ㄈㄨˊ","1.機關團體所規定式樣統一的服裝。[例]學生制服、警察制服_x000D_\n2.用力量使人屈服。[例]經過一番激烈的打鬥，警衛終於制服了小偷。"]],"制止":[["ㄓˋ ㄓˇ","強制禁止。[例]公園管理員到處巡邏以制止遊客踐踏園內的草坪。"]],"刷新":[["ㄕㄨㄚ ㄒㄧㄣ","改寫，突破以往的紀錄。[例]這次亞運，本國運動員表現優異，頻頻刷新紀錄。"]],"刷牙":[["ㄕㄨㄚ ㄧㄚˊ","用牙刷清潔牙齒。[例]餐後立即刷牙可以預防蛀牙。"]],"刺繡":[["ㄘˋ ㄒㄧㄡˋ","一種女紅。利用各種色線在紡織品或其他物品上，以不同的方法繡出各種圖案。繡法分直紋、短針兩類。[例]刺繡中的平繡、廣繡、蘇繡、湘繡號稱中國四大名繡，馳名中外。"]],"刺蝟":[["ㄘˋ ㄨㄟˋ","動物名。食蟲目蝟科。身上布滿長刺，遇危險時，會將頭縮進胸部，再將整個身子捲成團狀，以保護自己。晝伏夜出，以昆蟲、蝸牛、鳥等為食。分布在歐亞及非洲的低地和沙漠中。[例]刺蝟身上的棘刺，是用來嚇阻敵害的自衛工具。"]],"刻不容緩":[["ㄎㄜˋ ㄅㄨˋ ㄖㄨㄥˊ ㄏㄨㄢˇ","形容情勢十分緊迫，一刻也不容耽擱。[例]此處有人盜採砂石，嚴重影響環境保育，澈底取締改善，已到刻不容緩的地步。"]],"刻意":[["ㄎㄜˋ ㄧˋ","竭盡心思去做某件事情。[例]她刻意打扮得光鮮亮麗，希望引起別人對她的注意。"]],"削價":[["ㄒㄧㄠ ㄐㄧㄚˋ","減低價錢，一般是指低於成本的價錢。[例]因倉庫存貨過多，又苦無現金周轉，廠商只好削價求現。"]],"削弱":[["ㄒㄩㄝˋ ㄖㄨㄛˋ","減弱。[例]一連串的打擊，削弱了他一向目中無人的氣焰。"]],"削減":[["ㄒㄩㄝˋ ㄐㄧㄢˇ","刪削、減少。[例]這筆預算在議會審核時遭到大幅削減。"]],"削足適履":[["ㄒㄩㄝˋ ㄗㄨˊ ㄕˋ ㄌㄩˇ","將腳削小以適應鞋的尺寸。比喻勉強遷就，實非所宜。語本《淮南子．說林》。[例]待人處世要有原則，過分遷就現實，無異削足適履，事態未必改善，自身已受傷害。"]],"削髮":[["ㄒㄩㄝˋ ㄈㄚˇ","為出家而剃掉頭髮。[例]削髮為尼、削髮為僧　△落髮"]],"前仆後繼":[["ㄑㄧㄢˊ ㄆㄨ ㄏㄡˋ ㄐㄧˋ","比喻不怕犧牲，奮勇向前。[例]革命烈士為了拯救國家，前仆後繼的精神令人十分敬佩。"]],"前倨後恭":[["ㄑㄧㄢˊ ㄐㄩˋ ㄏㄡˋ ㄍㄨㄥ","先前傲慢無禮，後又謙卑恭敬。形容待人勢利，態度轉變迅速。語本《戰國策．秦策一》。[例]像他這種前倨後恭的勢利行徑，真令人不齒。"]],"前往":[["ㄑㄧㄢˊ ㄨㄤˇ","去。[例]這次的美食節展售各國佳餚，歡迎大家前往參觀品嚐。"]],"前方":[["ㄑㄧㄢˊ ㄈㄤ","1.前面。[例]前方有障礙物，開車時要特別小心謹慎。\n2.兩軍對峙或交戰時，距離敵營最近或較近的地帶。[例]前方戰況吃緊，急待緊急增援。"]],"前進":[["ㄑㄧㄢˊ ㄐㄧㄣˋ","向前行進。[例]我們休息一下再繼續前進吧！"]],"前面":[["ㄑㄧㄢˊ ㄇㄧㄢˋ","前方。[例]前面不遠有家商店，我們就在那兒稍做休息吧！"]],"前額":[["ㄑㄧㄢˊ ㄜˊ","額頭。[例]爸爸在烈日下修剪花木，前額早已布滿了汗珠。"]],"前驅":[["ㄑㄧㄢˊ ㄑㄩ","在前引導的人。[例]這次拂曉攻擊，我們這一連為前驅，帶大夥攻上山頂。"]],"剛健":[["ㄍㄤ ㄐㄧㄢˋ","剛堅強健。[例]剛健中正、剛健篤實"]],"剛剛":[["ㄍㄤ ㄍㄤ","方才。[例]老闆剛剛出去，麻煩你等一下再打電話來。"]],"剛好":[["ㄍㄤ ㄏㄠˇ","1.合適。[例]這件衣服穿在你身上，真是剛好不過了。\n2.正巧。[例]你來的剛好，我正有事找你呢！"]],"剛強":[["ㄍㄤ ㄑㄧㄤˊ","1.性情堅強。[例]他秉性剛強，是個有擔當的人。\n2.剛烈強勁。[例]青少年血氣剛強，容易衝動，需要好好開導。"]],"剛才":[["ㄍㄤ ㄘㄞˊ","方才、剛剛。[例]剛才說過，怎又忘了？"]],"剩下":[["ㄕㄥˋ ㄒㄧㄚˋ","剩餘、殘留。[例]放學後，同學都走光了，只剩下他一個人在教室裡。"]],"剩飯":[["ㄕㄥˋ ㄈㄢˋ","未吃完或多餘的飯。[例]他清掉桌上的剩飯剩菜。"]],"剩餘":[["ㄕㄥˋ ㄩˊ","1.剩下、多出來的。[例]這條桌巾是由裁製衣服剩餘的布料作成的。_x000D_\n2.數學上指甲數或甲式被乙數或乙式除了以後，所剩無法整除的部分。如23除以5，其商數為4，剩餘為3。"]],"剪刀":[["ㄐㄧㄢˇ ㄉㄠ","鉸斷布、紙、繩等東西的金屬器具。由一對金屬刀面組成，中間有鉚釘固定，可以開合夾剪。[例]他將剪刀、色紙放進書包，準備隔天美勞課用。　◎"]],"剪紙":[["ㄐㄧㄢˇ ㄓˇ","一種我國傳統民間藝術。運用不同的剪貼和摺疊方法，剪出各種花樣。多用作喜慶裝飾或窗花、燈花等，現代亦用作裝飾品。[例]他以剪紙製作了不少卡片寄送朋友。"]],"剪裁":[["ㄐㄧㄢˇ ㄘㄞˊ","1.縫製衣服或切割紙張時，按照一定的尺寸或式樣剪開。[例]這件設計簡單，剪裁合身的衣服，穿起來非常優雅。\n2.文學創作過程中，刪除繁蕪、留存精要的寫作技巧。[例]這篇文章枝蔓太多，必須加以剪裁刪修一番。"]],"剪貼":[["ㄐㄧㄢˇ ㄊㄧㄝ","1.從書報、雜誌上剪下文章、資料，貼在紙上或簿本上。[例]他每天收集報上有關業務的報導，剪貼保存於檔案中。\n2.將紙張剪成文字或圖案，貼在紙上或物體上。[例]老師教小朋友用色紙剪貼各種圖案。"]],"剪輯":[["ㄐㄧㄢˇ ㄐㄧˊ","將拍攝完成的影像帶或有聲帶，刪剪整理，編輯成一部結構完整的影片。[例]導演將影片剪輯成較短的版本，供院線放映。"]],"副作用":[["ㄈㄨˋ ㄗㄨㄛˋ ㄩㄥˋ","由主要功用附帶發生的不良作用。[例]生病時切忌亂服成藥，以免產生副作用。"]],"副手":[["ㄈㄨˋ ㄕㄡˇ","助手，協助處理事務的人。[例]陳先生辦事又細心又快捷，是老闆的得力副手。"]],"副本":[["ㄈㄨˋ ㄅㄣˇ","依照書籍或文件的正本謄錄或影印的複製本。在現行公文中，副本效力視同正本。[例]這份文件需要附上戶籍謄本的副本才算完整。"]],"割愛":[["ㄍㄜ ㄞˋ","將心愛的東西轉讓給別人。[例]經過多次央求，物主終於割愛，答應將這件古董轉賣給他。"]],"割捨":[["ㄍㄜ ㄕㄜˇ","斷絕、捨棄。[例]她嘴裡雖說要把孩子送人，但心裡著實割捨不下。"]],"割斷":[["ㄍㄜ ㄉㄨㄢˋ","切割使斷裂。[例]綑綁包裹的繩子打了死結，必須用刀割斷才能打開。"]],"創作":[["ㄔㄨㄤˋ ㄗㄨㄛˋ","出於己意而非模仿的文學或藝術作品的製作。[例]他年紀輕輕就能創作出這麼好的作品，真是難得。"]],"創傷":[["ㄔㄨㄤ ㄕㄤ","1.受外力造成的皮膚或其他組織損傷。[例]常見的創傷有割傷、刺傷和擦傷。\n2.傷口、傷害。[例]這件事對他的打擊很大，他需要時間來撫平心理所受的創傷。"]],"創口":[["ㄔㄨㄤ ㄎㄡˇ","傷口。[例]他不小心割到手，創口頗深。"]],"創意":[["ㄔㄨㄤˋ ㄧˋ","表現出新意與巧思。[例]他的設計獨具一格，頗富創意。"]],"創立":[["ㄔㄨㄤˋ ㄌㄧˋ","建立、設立。[例]這家公司是他一手創立的。"]],"創見":[["ㄔㄨㄤˋ ㄐㄧㄢˋ","前所未有、獨創的見解。[例]三民主義是國父的創見。"]],"創造":[["ㄔㄨㄤˋ ㄗㄠˋ","發明製造、建造。[例]如果沒有人民不斷的創造，社會將永遠沒有進步的動力。"]],"劃分":[["ㄏㄨㄚˋ ㄈㄣ","區別、分清界域。[例]行政管理首重權責劃分。"]],"劃座位":[["ㄏㄨㄚˋ ㄗㄨㄛˋ ㄨㄟˋ","辦理確認座次的手續。[例]搭乘飛機，須提前劃座位，辦妥登機手續。"]],"劃破":[["ㄏㄨㄚˊ ㄆㄛˋ","1.用尖銳的器具將物體割破。[例]扒手常趁人不注意時，用刀片劃破皮包行竊。_x000D_\n2.瞬間改變原來的樣子或景象。[例]一聲巨響劃破寧靜的夜晚，驚擾了睡夢中的民眾。"]],"劇場":[["ㄐㄩˋ ㄔㄤˇ","1.戲劇等表演藝術的演出場所。[例]這個劇團成立近二十年，足跡遍布全國各地劇場。\n2.表演藝術的單位或團體。[例]劇場成員在導演引導下，全心投入演出。"]],"劇情":[["ㄐㄩˋ ㄑㄧㄥˊ","戲劇中的情節內容。[例]這齣戲的劇情非常感人，使不少觀眾當場掉淚。"]],"劇本":[["ㄐㄩˋ ㄅㄣˇ","以人物對白、唱詞和戲劇指示為寫作形式的文學作品。可供演出戲劇用，或純粹供作閱讀。[例]這劇本是由世界文學名著改編而成的。"]],"劇烈":[["ㄐㄩˋ ㄌㄧㄝˋ","猛烈、強烈。[例]飯後應稍事休息，避免劇烈運動。"]],"劈啪":[["ㄆㄧ ㄆㄚ","狀聲詞。形容燃燒時爆裂或撞擊拍打的聲音。[例]木柴在壁爐裡劈啪劈啪的燒著，室內逐漸溫暖起來。"]],"劈柴":[["ㄆㄧ ㄔㄞˊ","用斧頭或劈刀等剖開木柴。[例]從荒野求生訓練課程中，我們學到了劈柴生火的技巧。"]],"劈頭":[["ㄆㄧ ㄊㄡˊ","1.當頭、正對著頭。[例]他被墜落的招牌劈頭一擊，當場昏倒。\n2.開頭、起始。[例]他見到我，劈頭第一句話便破口大罵，讓我不知所措。"]],"劍道":[["ㄐㄧㄢˋ ㄉㄠˋ","一種源自日本的擊劍運動。由兩人以竹刀互擊對方的一種武術。　◎"]],"力不從心":[["ㄌㄧˋ ㄅㄨˋ ㄘㄨㄥˊ ㄒㄧㄣ","心裡想做某事，力量卻無法達到。[例]意志消沉時，做起事來總覺得力不從心。"]],"力拚":[["ㄌㄧˋ ㄆㄢˋ","努力從事。[例]這次考試，他決定要力拚到底。"]],"力氣":[["ㄌㄧˋ ㄑㄧˋ","力量。[例]他使盡了所有的力氣，還是沒辦法把瓶蓋扭開。"]],"力量":[["ㄌㄧˋ ㄌㄧㄤˋ","1.力氣。[例]他的力量很大，一次可以扛起一大袋的米糧。\n2.能力。[例]社會上有許多善心人士，默默的貢獻自己的力量，為同胞服務。\n3.比喻作用、效力。[例]這種藥的力量很強，請遵醫囑服用。"]],"功勞":[["ㄍㄨㄥ ㄌㄠˊ","功績勛勞。[例]他對於臺灣早期經濟發展，有著難以抹滅的功勞。"]],"功能":[["ㄍㄨㄥ ㄋㄥˊ","1.功用效能。[例]這種機器經改良後，功能更多，效果更好了。\n\t\n2.功夫和本領。[例]他經常說中別人的心事，彷彿有透視人心的特異功能。"]],"功課":[["ㄍㄨㄥ ㄎㄜˋ","1.學生的課業。[例]每天吃完晚飯後，媽媽總是叮囑他趕快去做功課。\n\t\n2.佛教徒的早、晚課。內容包括唱讚、誦經、持咒等。[例]她信佛虔誠，每天早晚總是按時到佛堂做功課。"]],"加倍":[["ㄐㄧㄚ ㄅㄟˋ","1.照原數增加一倍。[例]廠方將機器更新之後，產量有加倍的成長。\n2.比原來程度更加深。[例]你要加倍練習，才能在比賽時締造佳績。"]],"加工":[["ㄐㄧㄚ ㄍㄨㄥ","1.增加工作的時間和速度。[例]為了趕明天出貨，工廠全體人員連夜加工。_x000D_\n2.將原料、半成品或成品再加以施工，使它成為新的或更精美的產品。[例]將食物加工製成罐頭後，可以延長保存期限。_x000D_"]],"加油":[["ㄐㄧㄚ ㄧㄡˊ","1.添加油料。[例]機車油箱裡的汽油快用完了，得先去加油才能繼續上路。\n2.比喻加強努力。為替人打氣、鼓勵時的用語。[例]球場上有許多觀眾揮舞著國旗，為中華隊選手加油！"]],"加法":[["ㄐㄧㄚ ㄈㄚˇ","一種數學運算方式。求兩個或兩個以上的數之總和。[例]根據研究，五、六歲的幼兒已能簡單的加法運算。"]],"加減":[["ㄐㄧㄚ ㄐㄧㄢˇ","增加或減少。[例]替人傳話，千萬不可任意加減。"]],"加熱":[["ㄐㄧㄚ ㄖㄜˋ","使溫度增高。[例]飯菜都涼了，你最好加熱後再食用。"]],"加緊":[["ㄐㄧㄚ ㄐㄧㄣˇ","加快速度或加強程度。[例]比賽即將展開，選手們都連夜加緊練習。"]],"助益":[["ㄓㄨˋ ㄧˋ","幫助。[例]這次的溝通協調，對於拉近彼此間的距離有很大的助益。"]],"努力":[["ㄋㄨˇ ㄌㄧˋ","盡量使出力來。[例]努力讀書、努力奮鬥"]],"勁敵":[["ㄐㄧㄥˋ ㄉㄧˊ","強而有力的敵人。也用來比喻厲害的對手。[例]他的實力堅強，是我在這次比賽中最大的勁敵。"]],"勃然大怒":[["ㄅㄛˊ ㄖㄢˊ ㄉㄚˋ ㄋㄨˋ","非常生氣。[例]得知兒子的荒唐行徑，父親勃然大怒，嚴加斥責。"]],"勇士":[["ㄩㄥˇ ㄕˋ","有勇氣膽量的人。[例]忠烈祠奉祀著為國捐軀的勇士們。"]],"勇敢":[["ㄩㄥˇ ㄍㄢˇ","有勇氣，敢於作為。[例]他為人正直，經常勇敢的站出來打抱不平。"]],"勇氣":[["ㄩㄥˇ ㄑㄧˋ","勇往直前、無所畏懼的氣魄。[例]他向來敢作敢當，是個有勇氣面對問題的人。"]],"勉強":[["ㄇㄧㄢˇ ㄑㄧㄤˇ","1.能力不夠或心中不願但仍盡力而為。[例]雖然他對商業沒有興趣，但仍勉強繼承了父親的事業。_x000D_\n2.強迫別人做不願意做的事。[例]他既然執意離去，又何必要勉強他留下來？_x000D_\n3.牽強、不自然。[例]他的理由很勉強，不太可信。"]],"勒死":[["ㄌㄟ ㄙˇ","用繩索等絞繞脖子，使窒息而死。[例]專家警告說：許多兒童因玩窗帘的繩子而被勒死。"]],"勒索":[["ㄌㄜˋ ㄙㄨㄛˇ","用威脅或暴力等非法手段強行索求他人財物。[例]警方對暴力勒索的犯罪行為，絕對追查到底。"]],"動作":[["ㄉㄨㄥˋ ㄗㄨㄛˋ","行為、態勢。[例]他動作迅速，做事乾淨俐落。"]],"動怒":[["ㄉㄨㄥˋ ㄋㄨˋ","發怒、生氣。[例]父親知道他荒唐的行為後，大為動怒。"]],"動植物":[["ㄉㄨㄥˋ ㄓˊ ㄨˋ","動物和植物的合稱。[例]有些細菌對動植物的危害極大，必須予以撲滅。"]],"動武":[["ㄉㄨㄥˋ ㄨˇ","打架或發起戰爭。[例]世界各國皆在謀求和平，避免以動武的方式來解決爭端。"]],"動物":[["ㄉㄨㄥˋ ㄨˋ","相對於植物的另一大類生物。多可自行攝食有機物以維生，有神經、感覺，並具運動能力。生存範圍遍及世界各處。[例]動物的細胞沒有細胞壁，是與植物最大不同之處。"]],"動物園":[["ㄉㄨㄥˋ ㄨˋ ㄩㄢˊ","畜養各種動物，供人觀賞、研究或教學的場所。[例]明天老師將帶我們去動物園寫生。"]],"動聽":[["ㄉㄨㄥˋ ㄊㄧㄥ","聽起來能使人感動、喜愛。[例]她的歌聲悅耳動聽。"]],"動脈":[["ㄉㄨㄥˋ ㄇㄞˋ","1.把由心臟壓出的新鮮血液，輸送到身體各部位的血管。[例]動脈的管壁厚而富彈性，每次心搏引起管壁擴張，即是脈搏。\n2.借指主要、重要的趨勢。[例]掌握住時代的動脈，才能跟得上潮流。"]],"勘誤":[["ㄎㄢ ㄨˋ","仔細校對後再訂正錯誤。[例]這本書已送交校訂組勘誤，近日便可製版付印。"]],"務必":[["ㄨˋ ㄅㄧˋ","一定、必須。[例]他來的時候，請務必告訴我。"]],"勝仗":[["ㄕㄥˋ ㄓㄤˋ","打仗獲勝。後泛指比賽獲勝。[例]這次的球賽，本校選手打了一場漂亮的勝仗。"]],"勝任":[["ㄕㄥ ㄖㄣˋ","能力足以擔當。[例]他的能力很強，足以勝任這項職務。"]],"勝利":[["ㄕㄥˋ ㄌㄧˋ","在戰場或競爭中打敗對手。[例]經過幾個星期的練習，這次大隊接力我們終於贏得勝利。"]],"勝券在握":[["ㄕㄥˋ ㄑㄩㄢˋ ㄗㄞˋ ㄨㄛˋ","比喻很有把握，相信自己可以成功勝利。[例]這次比賽我方的實力在所有參賽者之上，應該是勝券在握。"]],"勝地":[["ㄕㄥˋ ㄉㄧˋ","以風景優美而著名的地方。[例]太魯閣是臺灣東部的觀光勝地。"]],"勞心":[["ㄌㄠˊ ㄒㄧㄣ","費神處理事物。[例]他經常勞心苦思，熬夜撰文。"]],"勞碌":[["ㄌㄠˊ ㄌㄨˋ","辛勞忙碌。[例]我們能有個溫暖的家，都要感謝母親的操持勞碌。"]],"勞累":[["ㄌㄠˊ ㄌㄟˋ","勞動過度而覺得疲倦。[例]醫生一再囑咐他多休息，不可太過勞累，以免舊疾復發。"]],"勞軍":[["ㄌㄠˋ ㄐㄩㄣ","慰勞軍人。[例]演藝人員每年都會組團上前線勞軍。"]],"勞駕":[["ㄌㄠˊ ㄐㄧㄚˋ","煩請別人做事的客套話。[例]勞駕您風塵僕僕，遠來南部演講，真是由衷感謝。"]],"募集":[["ㄇㄨˋ ㄐㄧˊ","招募聚集。[例]災難發生後，有關單位立即募集人力及救濟品，以救助災民。"]],"勤勞":[["ㄑㄧㄣˊ ㄌㄠˊ","盡心盡力，辛勤勞動。[例]年輕時養成勤勞的習慣，對其一生會有很大助益。"]],"勤奮":[["ㄑㄧㄣˊ ㄈㄣˋ","勤勞奮發而不懈怠。[例]他工作勤奮，正一步步朝自己的理想前進。"]],"勤學":[["ㄑㄧㄣˊ ㄒㄩㄝˊ","努力求學。[例]在老師眼中，他是個勤學的好孩子。"]],"勵志":[["ㄌㄧˋ ㄓˋ","激勵奮發向上的心志。[例]勵志小品"]],"勸導":[["ㄑㄩㄢˋ ㄉㄠˇ","規勸、開導。[例]政府勸導機車騎士，在騎乘機車時，務必要戴安全帽。"]],"勸架":[["ㄑㄩㄢˋ ㄐㄧㄚˋ","勸阻別人不要爭吵或打架。[例]父親出面勸架後，才使這場紛爭平息。"]],"勸諫":[["ㄑㄩㄢˋ ㄐㄧㄢˋ","規勸諫過。[例]在大家的勸諫下，她終於打消退學的念頭。"]],"勾勒":[["ㄍㄡ ㄌㄜˋ","描畫輪廓，或簡單的描寫。[例]他擅長素描，隨手幾筆就能勾勒出人像的輪廓來。"]],"勾心鬥角":[["ㄍㄡ ㄒㄧㄣ ㄉㄡˋ ㄐㄧㄠˇ","比喻彼此明爭暗鬥，各用心機。[例]大家若再勾心鬥角，公司遲早會因人事不和而瓦解。"]],"勾當":[["ㄍㄡˋ ㄉㄤˋ","事情，通常指負面的事物。[例]他資質聰穎，卻從事不法勾當，真令人惋惜。　△句當"]],"勾銷":[["ㄍㄡ ㄒㄧㄠ","取消、抹煞。[例]新仇添舊恨，一筆難勾銷。"]],"包含":[["ㄅㄠ ㄏㄢˊ","包括。[例]這句話包含了多層意思。"]],"包圍":[["ㄅㄠ ㄨㄟˊ","由四面八方圍住。[例]警方將歹徒包圍，喝令投降。"]],"包容":[["ㄅㄠ ㄖㄨㄥˊ","寬恕接納。[例]愛就是擁有一顆包容的心。"]],"包廂":[["ㄅㄠ ㄒㄧㄤ","劇院等娛樂場所或長程火車上所設立的特別空間，不與他人共用，可不受干擾。[例]非假日期間，本劇院包廂五折優待。"]],"包括":[["ㄅㄠ ㄍㄨㄚ","包含、涵蓋。[例]包括五院院長在內，均出席了這次會議。"]],"包裝":[["ㄅㄠ ㄓㄨㄤ","1.包紮裝飾。[例]請你先將禮品包裝好再投遞。　◎_x000D_\n2.指包紮裝飾物品的材料。[例]這件商品的包裝用的是環保材質。_x000D_\n3.指一切外在形式上的修飾、塑造。[例]他的正義形象是被刻意包裝出來的。"]],"包裹":[["ㄅㄠ ㄍㄨㄛˇ","1.行李。[例]她收拾一下包裹，頭也不回的走了。\n2.包紮成件的東西。[例]郵寄包裹、限時包裹\n3.包紮起來。[例]他用紗布包裹傷口。"]],"包覆":[["ㄅㄠ ㄈㄨˋ","包裹覆蓋。[例]這家店的雞排包覆著起司內餡，極為美味，難怪門庭若市。"]],"匆促":[["ㄘㄨㄥ ㄘㄨˋ","匆忙、倉促。[例]時間非常匆促，不容許停留太久。"]],"匆忙":[["ㄘㄨㄥ ㄇㄤˊ","急忙。[例]適度的休閒，可以舒緩現代人既緊張又匆忙的生活。"]],"化學":[["ㄏㄨㄚˋ ㄒㄩㄝˊ","研究物質的結構、性質及變化反應的一門科學。包括有機化學、生物化學、核化學等。[例]歐洲中世紀的鍊金術成了日後化學發展的基礎。"]],"化緣":[["ㄏㄨㄚˋ ㄩㄢˊ","僧、尼、道士向人乞求布施。因布施者與仙佛結下善緣，故稱為「化緣」。[例]為籌措修繕古剎的經費，住持和尚到處化緣。"]],"北方":[["ㄅㄟˇ ㄈㄤ","北邊、北面。與「南方」相對。[例]要看北極星，得從北方星空裡去找。"]],"北緯":[["ㄅㄟˇ ㄨㄟˇ","地球表面以經緯度座標定位，位在赤道以北的緯度，稱為「北緯」。與「南緯」相對。[例]臺灣本島約位於北緯22度到25度之間。"]],"北邊":[["ㄅㄟˇ ㄅㄧㄢ","北方，與「南邊」相對。[例]新北市在桃園市的北邊。"]],"北面":[["ㄅㄟˇ ㄇㄧㄢˋ","北邊、北方。[例]這座公園的北面有一座網球場。"]],"北風":[["ㄅㄟˇ ㄈㄥ","北方吹來的風。[例]凜冽的北風陣陣襲來，翠綠的樹葉漸漸的枯萎了。"]],"匠心獨具":[["ㄐㄧㄤˋ ㄒㄧㄣ ㄉㄨˊ ㄐㄩˋ","別具巧妙的心思。[例]這幅畫不論是布局、用色、意境都是匠心獨具，堪稱佳作。"]],"匱乏":[["ㄎㄨㄟˋ ㄈㄚˊ","貧乏。[例]我國經濟發達，民生物質不虞匱乏。"]],"區分":[["ㄑㄩ ㄈㄣ","區別劃分。[例]這對雙胞胎姊妹長得實在太像了，連親戚朋友都無法區分。"]],"區區":[["ㄑㄩ ㄑㄩ","微小。[例]區區小事，何足掛齒！"]],"十分":[["ㄕˊ ㄈㄣ","1.很，非常。[例]臺灣南部夏天的天氣十分炎熱。\n2.圓滿、充足。[例]庭下金齡菊，花開已十分。（宋．孔平仲〈對菊有懷郎祖仁〉詩）"]],"十惡不赦":[["ㄕˊ ㄜˋ ㄅㄨˋ ㄕㄜˋ","形容罪大惡極，不可饒恕。[例]這個流氓壞事做盡，真是十惡不赦的罪人。"]],"十足":[["ㄕˊ ㄗㄨˊ","形容非常充足的程度。[例]信心十足、架勢十足"]],"千真萬確":[["ㄑㄧㄢ ㄓㄣ ㄨㄢˋ ㄑㄩㄝˋ","非常確實。[例]我已經查證過，這件事是千真萬確的。"]],"千篇一律":[["ㄑㄧㄢ ㄆㄧㄢ ㄧ ㄌㄩˋ","文章的形式或內容毫無變化。[例]為避免千人一面，千篇一律，他寫的小說總是別具巧思，風靡一時。"]],"千萬":[["ㄑㄧㄢ ㄨㄢˋ","1.數目的名稱。在百萬之上，億之下。[例]一千萬\n2.形容數目極多。[例]千萬家財，富甲一方。\n3.再三叮嚀，一定、務必的意思。[例]你獨自在外工作，千萬要保重。"]],"千載難逢":[["ㄑㄧㄢ ㄗㄞˇ ㄋㄢˊ ㄈㄥˊ","千年也難遇上一次。形容機會極為難得。[例]這是千載難逢的好機會，你可要好好把握！"]],"千金":[["ㄑㄧㄢ ㄐㄧㄣ","1.很多黃金。借指很多的錢財。[例]千金難買寸光陰_x000D_\n2.比喻非常珍貴。[例]一諾千金、千金之軀_x000D_\n3.尊稱他人的女兒。[例]您家千金乖巧懂事，又有人緣，當然受到大家歡迎。"]],"升旗":[["ㄕㄥ ㄑㄧˊ","將國旗等旗幟拉到旗杆頂端。通常皆為一種隆重的儀式。[例]每天早上，全校的師生都集合在操場上參加升旗典禮。"]],"升空":[["ㄕㄥ ㄎㄨㄥ","上升於天空。[例]成千上萬的氣球在剎那間全部升空，將天空點綴得五彩繽紛。"]],"升高":[["ㄕㄥ ㄍㄠ","提高、提升。[例]連日來的大雨使水庫的水位升高，解除了旱象。"]],"午餐":[["ㄨˇ ㄘㄢ","中午食用的餐點。[例]他正在減肥，所以午餐吃得較為精簡。"]],"半夜":[["ㄅㄢˋ ㄧㄝˋ","1.一夜的一半。[例]他已經習慣先在前半夜休息，然後再起身寫作。\n2.深夜。[例]半夜裡的一場地震，嚇得我睡意全消。"]],"半途":[["ㄅㄢˋ ㄊㄨˊ","半路。多用在文言文。[例]半途而廢、半途折返"]],"卓見":[["ㄓㄨㄛˊ ㄐㄧㄢˋ","高超的見解。[例]這種高論卓見，聽來令人佩服。"]],"卓越":[["ㄓㄨㄛˊ ㄩㄝˋ","非常優秀，超出常人。[例]他的公關才能卓越，頗受總經理重視。"]],"協力":[["ㄒㄧㄝˊ ㄌㄧˋ","共同努力。[例]這件工程在眾人齊心協力之下，終於如期完工了。"]],"協助":[["ㄒㄧㄝˊ ㄓㄨˋ","協力幫助。[例]經由他的協助，這件事終於順利完成了。"]],"協會":[["ㄒㄧㄝˊ ㄏㄨㄟˋ","為互相協助以期達成共同目標而結合的群眾團體。[例]防癆協會、登山協會"]],"協調":[["ㄒㄧㄝˊ ㄊㄧㄠˊ","協議調和，使意見一致。[例]經過一番溝通協調後，他們對這件事的處理終於有了共識。"]],"南瓜":[["ㄋㄢˊ ㄍㄨㄚ","植物名。葫蘆科南瓜屬，一年生草本。莖有卷鬚，葉圓心臟形，夏日開合瓣黃色單性花。果實亦稱為「南瓜」。　◎"]],"南美洲":[["ㄋㄢˊ ㄇㄟˇ ㄓㄡ","巴拿馬和哥倫比亞二國國界以南的美洲大陸。東瀕大西洋，西臨太平洋，北接加勒比海，南隔德雷克海峽與南極洲相望。面積約1800萬平方公里。綿亙著世界上流域面積最廣的亞馬遜河。[例]南美洲大多屬於熱帶雨林和熱帶草原型的氣候。　△南美"]],"南行":[["ㄋㄢˊ ㄒㄧㄥˊ","向南行進。[例]他這次南行，主要目的是在南部地區為公司建立業務新據點。"]],"博士":[["ㄅㄛˊ ㄕˋ","1.在大學或獨立學院研究所研讀的博士候選人，通過該校（院）學位考試，經教育部覆核無異後，所獲頒的學位，為現今最高的學位。獲得此學位的人也稱博士。[例]法學博 士、文學博士\n2.舊時對有特殊技能或專業人員的尊稱。如茶館煎茶的師傅稱為「煎茶博士」。\n3.職官名。起源於戰國，秦、漢時設置。掌通古今，以備諮詢，相當於學術顧問。[例]五經博士"]],"博學":[["ㄅㄛˊ ㄒㄩㄝˊ","1.廣泛的學習。[例]博學、審問、慎思、明辨是做學問的四大要領。\n2.學識豐富廣博。[例]博學之士"]],"博物館":[["ㄅㄛˊ ㄨˋ ㄍㄨㄢˇ","蒐集、陳列各式各樣物品，讓人觀賞，並永久保存及提供研究的場所。[例]一座典藏豐富的博物館就等於是一個知識寶庫。"]],"占夢":[["ㄓㄢ ㄇㄥˋ","占卜以判斷夢的吉凶。[例]這些只是相命先生占夢之言，別盡信。"]],"占為己有":[["ㄓㄢˋ ㄨㄟˊ ㄐㄧˇ ㄧㄡˇ","強占非個人財物以為己有。[例]將路邊的空地占為己有，當作私人的停車位，是不合法的行為。"]],"占領":[["ㄓㄢˋ ㄌㄧㄥˇ","侵略占有。"]],"卡片":[["ㄎㄚˇ ㄆㄧㄢˋ","1.內含文字、圖畫，用來贈送或邀約他人的硬紙片。如賀年卡、生日卡、邀請卡等。[例]母親節，他準備自製卡片送給母親，以表孝心。\n2.供一般登錄、處理資料時使用的硬紙片。[例]在電腦還沒普及前，資料通常記錄在卡片上，作為存檔之用。"]],"卡車":[["ㄎㄚˇ ㄔㄜ","供運貨用的大型汽車。車身為敞蓬的斗形平臺，底盤高，馬力強大。以總重量3500公斤為標準，超過者為大卡車，不及者為小卡車。§英car[例]高速公路上因卡車翻覆，使得南下車道受阻了近兩小時。　◎"]],"卡通":[["ㄎㄚˇ ㄊㄨㄥ","一種誇張、象徵性的美術畫法。本指以時事或一個特殊觀念為題材的諷刺畫。後指一種連環漫畫。通常由四幅畫構成，以敘述一段簡短的故事。也有用較多篇幅描繪長篇故事的。電影發達後更將漫畫拍製成連續動作的卡通影片。§英cartoon[例]這部卡通聲光效果十足，深受小朋友們的喜愛。"]],"印章":[["ㄧㄣˋ ㄓㄤ","圖章。[例]到銀行、郵局等金融機構提領存款，必須攜帶印章。"]],"印象":[["ㄧㄣˋ ㄒㄧㄤˋ","感官受外界事物刺激而留存於記憶中的意象。[例]印象深刻"]],"危害":[["ㄨㄟˊ ㄏㄞˋ","破壞、損害。[例]黑道猖獗已經嚴重危害社會安寧。"]],"危急":[["ㄨㄟˊ ㄐㄧˊ","危險急迫。[例]他的病況十分危急，須趕緊送醫急救。"]],"危樓":[["ㄨㄟˊ ㄌㄡˊ","隨時有坍塌危險的樓房。[例]受到強震的破壞，許多耐震性較差的建築，紛紛成了危樓。"]],"危險":[["ㄨㄟˊ ㄒㄧㄢˇ","不安全。[例]三更半夜一個人在外面遊蕩是很危險的事。"]],"即使":[["ㄐㄧˊ ㄕˇ","縱使、就算是。[例]如果不能活用，即使學得再多又有什麼用呢？"]],"即刻":[["ㄐㄧˊ ㄎㄜˋ","立刻、馬上。[例]一放假，她就恨不得即刻回家與家人團聚。"]],"即將":[["ㄐㄧˊ ㄐㄧㄤ","將要、就要。[例]她即將到國外留學，這幾日正忙著向親朋好友道別。"]],"卻是":[["ㄑㄩㄝˋ ㄕˋ","反倒是。[例]他雖然表情冷淡，但內心卻是熱情洋溢。"]],"原來":[["ㄩㄢˊ ㄌㄞˊ","1.本來，剛開始時。[例]他的頭髮修剪後，比原來的模樣好看多了。\n2.推究事情本源的口氣。[例]這本書我找了好久，原來在你這兒。"]],"原來如此":[["ㄩㄢˊ ㄌㄞˊ ㄖㄨˊ ㄘˇ","事實情況原本是這樣。[例]聽老師講解後，他才恍然大悟的說：「原來如此！」"]],"原因":[["ㄩㄢˊ ㄧㄣ","事情的起因。[例]你若想知道原因，就該問當事人才對。"]],"原故":[["ㄩㄢˊ ㄍㄨˋ","事情發生的因由。[例]警方正在調查這件意外發生的原故。"]],"原本":[["ㄩㄢˊ ㄅㄣˇ","1.原來、本來。[例]這本書原本是我的，後來轉贈給他。\n2.原來的版本或作者的底本。[例]若要細品這部小說的韻味，最好去閱讀英文原本。"]],"原狀":[["ㄩㄢˊ ㄓㄨㄤˋ","本來的形狀、狀態。[例]請把弄亂的書恢復原狀擺好。"]],"原諒":[["ㄩㄢˊ ㄌㄧㄤˋ","寬恕諒解。[例]老師原諒我的無禮，使我感激不已。"]],"原野":[["ㄩㄢˊ ㄧㄝˇ","平原曠野。[例]置身晚秋的原野中，令人有蒼茫之感。"]],"厭倦":[["ㄧㄢˋ ㄐㄩㄢˋ","不再喜歡或提不起興趣。[例]小弟弟對這個玩具已經感到厭倦了。"]],"厭惡":[["ㄧㄢˋ ㄨˋ","極度的反感或不喜歡。[例]沒有公德心的人常令人厭惡，有公德心的人常受人尊重。"]],"厲害":[["ㄌㄧˋ ㄏㄞˋ","1.猛烈、強烈。[例]他看了那幕驚險的鏡頭，心跳得很厲害。\n2.嚴重。[例]你燒得這麼厲害，應該趕緊去看醫生！\n3.高強。[例]他的劍法非常厲害，一般人根本不是他的對手。"]],"厲鬼":[["ㄌㄧˋ ㄍㄨㄟˇ","惡鬼。[例]弟弟被電視裡的厲鬼嚇得直做惡夢。"]],"參加":[["ㄘㄢ ㄐㄧㄚ","參與、加入。[例]老師決定提名他去參加作文比賽。"]],"參差":[["ㄘㄣ ㄘ","不整齊的樣子。[例]清澈的湖面映著參差交疊的山峰。"]],"參差不齊":[["ㄘㄣ ㄘ ㄅㄨˋ ㄑㄧˊ","雜亂不整齊。[例]庭園裡的花木參差不齊，已經很久沒有修剪了。"]],"參與":[["ㄘㄢ ㄩˋ","參加、加入。[例]他積極參與各項公益活動。"]],"參觀":[["ㄘㄢ ㄍㄨㄢ","實地觀覽。[例]今天老師帶領我們去參觀博物館。"]],"及時":[["ㄐㄧˊ ㄕˊ","1.適時趕上。[例]經驗的可貴之處，在於讓我們犯相同的錯誤之前，能及時改正。\n2.把握時機。[例]年輕時應及時努力，否則日後悔恨也無法彌補。"]],"及格":[["ㄐㄧˊ ㄍㄜˊ","達到所預定的標準。[例]老師規定此次的隨堂考必須達七十分才算及格。"]],"及第":[["ㄐㄧˊ ㄉㄧˋ","古代稱科舉考試中選為「及第」。[例]進士及第、狀元及第"]],"友情":[["ㄧㄡˇ ㄑㄧㄥˊ","朋友間的情誼、交情。[例]為善助人使他獲得更多的友情。"]],"友誼":[["ㄧㄡˇ ㄧˋ","朋友的交情、情誼。[例]他們靠著書信、電話維繫了多年的友誼。"]],"反射":[["ㄈㄢˇ ㄕㄜˋ","1.聲波或光線行進時，遇到阻礙而改變方向，稱為「反射」。[例]夕陽西下，金色的陽光灑在海面上，反射出一片波光粼粼。\n2.神經系統的反應作用。如瞳孔隨光刺激的強弱而改變大小、吃東西時分泌唾液等。[例]反射動作"]],"反對":[["ㄈㄢˇ ㄉㄨㄟˋ","不贊成。[例]這個提議因大家反對而遭否決。"]],"反彈":[["ㄈㄢˇ ㄊㄢˊ","1.物理學上指作用力施於物體的同一時間，必產生相等而相反的動量，稱為「反彈」。[例]壁球是利用反彈原理研發而成的運動項目。\n2.在極度壓迫的情況下突然反撲或突破困境。[例]由於公司不合理的要求加班，已引起部分員工情緒上的反彈。\n3.股票術語。在空頭市場裡，由於股價大幅下跌已有一段時日，由低檔暫時回升，稱為「反彈」。[例]股市低迷數日後，終於在今天開始反彈。"]],"反悔":[["ㄈㄢˇ ㄏㄨㄟˇ","對已決定的事心生悔意或中途變卦。[例]昨天和他約定好的事，他今天就反悔了，真是不守信用。"]],"反應":[["ㄈㄢˇ ㄧㄥˋ","由特定事物的刺激所引發的回響。[例]根據市場調查，消費者對這項產品的反應普遍不佳。"]],"反攻":[["ㄈㄢˇ ㄍㄨㄥ","戰爭或競賽時，劣勢或呈現敗象的一方重新整頓，再度出擊。[例]絕地大反攻"]],"反敗為勝":[["ㄈㄢˇ ㄅㄞˋ ㄨㄟˊ ㄕㄥˋ","扭轉即將落敗的劣勢而得到勝利。[例]我隊在終場前一分鐘投進關鍵的一球才反敗為勝。"]],"反映":[["ㄈㄢˇ ㄧㄥˋ","1.由某事物的一定狀態而產生和它相符或相關的現象，稱為「反映」。[例]夢境有時可反映出一個人的潛在意識。\n2.將客觀的情況或意見向上級陳述。[例]鄉長代表本鄉鄉民把果蔬產銷合一的計畫反映給縣政府。"]],"反正":[["ㄈㄢˇ ㄓㄥˋ","1.無論如何。[例]不管你怎麼說，反正他是不會答應的。\n2.由不正復歸於正。[例]撥亂反正\n3.敵對的一方向我方投降。[例]他率領部分弟兄，向中央軍反正。"]],"反求諸己":[["ㄈㄢˇ ㄑㄧㄡˊ ㄓㄨ ㄐㄧˇ","反過來檢討自己。[例]凡事要反求諸己，不要老是苛責別人。"]],"反省":[["ㄈㄢˇ ㄒㄧㄥˇ","省察自己的言行。[例]反省是一種勇氣的表現，也是提升道德修養的必要手段。"]],"反覆":[["ㄈㄢˇ ㄈㄨˋ","1.重複，一次又一次。形容詳細推求。[例]他為上臺表演做準備，不斷反覆練習，希望盡善盡美。\n2.顛倒變動、變化無常。[例]他的脾氣反覆無常，令人無法招架。"]],"反諷":[["ㄈㄢˇ ㄈㄥˋ","字面或言語上的意思與實際意念相反，藉以諷刺或增強語氣。[例]政治漫畫常以反諷的表現手法，來諷刺政治人物、事件等。"]],"反面":[["ㄈㄢˇ ㄇㄧㄢˋ","1.指物體跟正面相反的另一面。[例]這張紙的反面還可再使用。_x000D_\n2.事情顯示否定效益的一面。與「正面」相對。[例]反面意義、反面影響"]],"反駁":[["ㄈㄢˇ ㄅㄛˊ","提出反對的理由加以辯駁。[例]他提出理由反駁對方的指責。"]],"叔公":[["ㄕㄨˊ ㄍㄨㄥ","稱謂。稱父親的叔父。[例]我小時候常在叔公家玩耍，所以與他較親近。　△叔祖"]],"叔叔":[["ㄕㄨˊ ˙ㄕㄨ","稱謂：(1) 稱父親的弟弟。[例]爸爸與叔叔年齡相近，從小就比較親熱。　(2) 泛稱與父親同輩，年紀較小的男子。[例]陳叔叔和爸爸是好朋友。"]],"叔父":[["ㄕㄨˊ ㄈㄨˋ","稱謂。稱父親的弟弟。[例]下星期叔父全家將回國向奶奶拜壽。　△季父、仲父　◎"]],"取代":[["ㄑㄩˇ ㄉㄞˋ","以新的人或事物替代舊有的。[例]在他的心目中，老師崇高、莊嚴的地位是無可取代的。"]],"取得":[["ㄑㄩˇ ㄉㄜˊ","拿到、獲得。[例]他在半工半讀的情況之下取得博士學位。"]],"取笑":[["ㄑㄩˇ ㄒㄧㄠˋ","嘲弄、開玩笑。[例]對於同學們的取笑，他根本不放在心上。"]],"受傷":[["ㄕㄡˋ ㄕㄤ","受到傷害。[例]她上體育課時，不小心跌倒受傷了。"]],"受屈":[["ㄕㄡˋ ㄑㄩ","受到委屈。[例]他有不得已的苦衷，即使受屈含冤也不能把真相說出。"]],"受用":[["ㄕㄡˋ ㄩㄥˋ","得到益處。[例]經常聆聽高水準的演講，必將受用不盡。"]],"受邀":[["ㄕㄡˋ ㄧㄠ","接受邀請。[例]王老師受邀擔任國語文競賽的評審。"]],"受限":[["ㄕㄡˋ ㄒㄧㄢˋ","受到限制。[例]學生可任意取閱圖書館中的書報雜誌，從未受限。"]],"叢書":[["ㄘㄨㄥˊ ㄕㄨ","彙刊群書所成的套書。[例]兒童百科叢書、動物百科叢書"]],"口令":[["ㄎㄡˇ ㄌㄧㄥˋ","1.作戰、軍隊操練或做體操時，指揮人員以簡短的術語所下達的口頭號令。[例]每次上體育課，老師都會喊口令，帶我們先做十分鐘的熱身操。\n2.軍隊長官每日密發，用以識別敵我，防止敵人滲入的口頭暗號。[例]夜間出入營區，通常需要口令才能通行。"]],"口供":[["ㄎㄡˇ ㄍㄨㄥ","刑事訴訟關係人在受檢察官或治安機關訊問時，所說與案情有關的話。[例]警方根據犯人的口供，立刻逮捕到其他在逃的共犯。"]],"口吃":[["ㄎㄡˇ ㄐㄧˊ","說話不連貫，常有字音重複或詞句中斷的現象。[例]他情緒稍一緊張，說起話來就會有點口吃。"]],"口吻":[["ㄎㄡˇ ㄨㄣˇ","說話的語氣及措辭。[例]他年紀雖小，但說話的口吻卻像個大人。"]],"口味":[["ㄎㄡˇ ㄨㄟˋ","1.滋味。[例]這家小店的牛肉麵口味絕佳，每天都吸引許多客人上門品嚐。\n2.對事物的愛好。[例]這部電影由於合乎大眾口味，所以極為賣座。"]],"口哨":[["ㄎㄡˇ ㄕㄠˋ","聚合雙脣，中間留一小孔或將手指伸入口內，用力吹氣而發出像吹哨子的聲音。[例]眼前春風吹拂著柳浪，我不禁吹起口哨，應和著鶯啼燕語。"]],"口才":[["ㄎㄡˇ ㄘㄞˊ","說話的技巧。[例]他口才很好，常代表學校參加辯論比賽。"]],"口水":[["ㄎㄡˇ ㄕㄨㄟˇ","由口腔黏膜與唾腺分泌液混合而成的黏液。可滋潤口腔、浸潤食物、分解澱粉。[例]小孩子初長牙時，容易流口水。　△唾液"]],"口沫橫飛":[["ㄎㄡˇ ㄇㄛˋ ㄏㄥˊ ㄈㄟ","1.唾液四處飛散。[例]那位演說者唱作俱佳，總是口沫橫飛而不自知。\n2.形容人放情高論。[例]只要一談到自己的專業領域，他就口沫橫飛，滔滔不絕。"]],"口渴":[["ㄎㄡˇ ㄎㄜˇ","口乾想喝水。[例]在大太陽底下走了一天的路，他感到非常口渴。"]],"口碑":[["ㄎㄡˇ ㄅㄟ","舊時碑上的文字多為頌揚的話，故用碑比喻稱讚的話。口碑比喻眾人口頭的稱讚或評價。語本《五燈會元．卷十七．太平安禪師》。[例]這齣連續劇製作嚴謹，播出以來，口碑頗佳。"]],"口若懸河":[["ㄎㄡˇ ㄖㄨㄛˋ ㄒㄩㄢˊ ㄏㄜˊ","比喻能言善道，說話時有如流水傾瀉一般，滔滔不絕。[例]他很健談，發表高論時口若懸河，滔滔不絕。"]],"口袋":[["ㄎㄡˇ ㄉㄞˋ","縫在衣物上的袋子。[例]他喜歡穿有口袋的上衣，以便放置隨身物品。"]],"口訣":[["ㄎㄡˇ ㄐㄩㄝˊ","容易背誦上口的語句。[例]心算口訣、珠算口訣、九九乘法口訣"]],"古今中外":[["ㄍㄨˇ ㄐㄧㄣ ㄓㄨㄥ ㄨㄞˋ","指最廣泛的時間和空間。[例]古今中外，凡是立大功、做大事的人，都是先吃盡苦頭，最後才成功的。"]],"古怪":[["ㄍㄨˇ ㄍㄨㄞˋ","奇怪、怪異。[例]稀奇古怪"]],"古板":[["ㄍㄨˇ ㄅㄢˇ","固執守舊，一成不變，不合時代潮流。[例]他的思想古板，早已跟不上時代了。"]],"古色古香":[["ㄍㄨˇ ㄙㄜˋ ㄍㄨˇ ㄒㄧㄤ","高雅而富有古代的色彩與風味。[例]這座歷史悠久的城市，隨處可見古色古香的建築物。"]],"古董":[["ㄍㄨˇ ㄉㄨㄥˇ","1.古代遺留下來，具有古文化參考價值，並可供玩賞的器物。[例]這個明朝流傳下來的古董價值不菲，把玩時要特別小心！\n2.比喻不合時代潮流，頑固守舊的人。[例]我們要隨著時代的潮流調整自己的觀念，才不會成為不合時宜的古董。"]],"古蹟":[["ㄍㄨˇ ㄐㄧ","古代流傳下來的文化遺蹟。[例]臺南是個文化古城，大大小小的古蹟不下數十個。"]],"另外":[["ㄌㄧㄥˋ ㄨㄞˋ","除此以外。[例]對於這件事，你是否有另外的看法？"]],"另眼相看":[["ㄌㄧㄥˋ ㄧㄢˇ ㄒㄧㄤ ㄎㄢˋ","用特別的眼光或態度相待，以示重視或歧視。[例]在團體中我們應該一視同仁，不能因為他身分特殊而另眼相看。"]],"叨叨絮絮":[["ㄉㄠ ㄉㄠ ㄒㄩˋ ㄒㄩˋ","囉嗦、多話。[例]為了這點小事，他整日叨叨絮絮說個沒完，真令人受不了。"]],"叨擾":[["ㄊㄠ ㄖㄠˇ","打擾。感謝別人款待的客套用語。[例]在府上叨擾這麼多天，心裡真是過意不去。"]],"只好":[["ㄓˇ ㄏㄠˇ","只得、不得不。[例]因為身體不適，他只好請假在家休息。"]],"只是":[["ㄓˇ ㄕˋ","1.僅僅是、只不過是。[例]這只是件小事，你不需要掛在心上。\n2.但是。[例]我實在很想幫你的忙，只是力不從心。"]],"只欠東風":[["ㄓˇ ㄑㄧㄢˋ ㄉㄨㄥ ㄈㄥ","比喻只欠缺最後的關鍵性條件。[例]這件事我大致都準備好了，現在就只欠東風。"]],"只管":[["ㄓˇ ㄍㄨㄢˇ","1.只顧、只關心。[例]如果人人只管自己的事，不關心別人，那將是一個冷漠無情的社會。\n2.儘管。[例]你只管專心唸書，其餘的就不要操心了。"]],"只要":[["ㄓˇ ㄧㄠˋ","只須。[例]只要肯付出，就一定會有收穫。"]],"叫好":[["ㄐㄧㄠˋ ㄏㄠˇ","對於精彩的表演大聲喝采、喊「好」，表示讚賞。[例]他的口技表演真是唯妙唯肖，在場的觀眾莫不大聲叫好。"]],"叫屈":[["ㄐㄧㄠˋ ㄑㄩ","對於不合理的待遇感到委屈不平，或加以申訴表達。[例]他做事一向負責認真，上司卻對他百般刁難，實在讓人替他叫屈。"]],"叫醒":[["ㄐㄧㄠˋ ㄒㄧㄥˇ","叫喚使之甦醒。[例]早上幸虧爸爸及時叫醒我，上課才沒有遲到。"]],"召喚":[["ㄓㄠˋ ㄏㄨㄢˋ","呼喚。[例]昔日的雇主頻頻召喚他重回工作崗位，繼續為公司服務。"]],"召見":[["ㄓㄠˋ ㄐㄧㄢˋ","在上位者約見在下位的人。[例]他當選十大傑出青年時，曾蒙總統召見。"]],"召開":[["ㄓㄠˋ ㄎㄞ","召集舉行。[例]公司將於明日召開業務彙報，各部門主管都須列席報告。"]],"叮嚀":[["ㄉㄧㄥ ㄋㄧㄥˊ","囑咐。[例]再三叮嚀、鄭重叮嚀"]],"叮囑":[["ㄉㄧㄥ ㄓㄨˇ","再三叮嚀囑咐。[例]每次負笈北上，父母總是叮囑我別忘了要常寫信回家。"]],"可以":[["ㄎㄜˇ ㄧˇ","1.能夠。[例]生動有趣的教學，可以激發孩童的想像力。\n2.不壞、尚好。[例]這道菜的味道燒得還可以啦！\n3.甚、很。表示情況很嚴重。[例]你也粗心得可以了，連每天戴著的眼鏡都會找不到。"]],"可否":[["ㄎㄜˇ ㄈㄡˇ","可不可以、能不能。[例]不置可否"]],"可怕":[["ㄎㄜˇ ㄆㄚˋ","令人害怕。[例]這次颱風造成嚴重災情，讓人感受到大自然力量的可怕！"]],"可怖":[["ㄎㄜˇ ㄅㄨˋ","令人感到可怕恐怖。[例]傳說鐘樓怪人形狀可怖，沒有人敢靠近他。"]],"可惜":[["ㄎㄜˇ ㄒㄧˊ","令人惋惜。[例]他年紀輕輕的就誤入歧途，結交了一些壞朋友，斷送了自己的前程，實在可惜。"]],"可惡":[["ㄎㄜˇ ㄨˋ","令人厭惡。[例]他這種欺負弱小的行為，十分可惡。"]],"可愛":[["ㄎㄜˇ ㄞˋ","討人喜愛。[例]他自小就聰明活潑，十分可愛。"]],"可憐":[["ㄎㄜˇ ㄌㄧㄢˊ","令人憐憫、同情。[例]他在這次車禍中身受重傷，又失去了雙親，真是可憐。"]],"可是":[["ㄎㄜˇ ㄕˋ","1.但是。表示轉折的語氣。[例]他成績雖然不好，可是卻很努力，一點也不會自暴自棄。\n2.是。含有諷刺、強調的意思。[例]他可是老闆跟前的紅人，你千萬別惹火他。\n3.是不是。表示疑問的語氣。[例]這件洋裝可是你上個月在百貨公司看中的那件？"]],"可汗":[["ㄎㄜˋ ㄏㄢˊ","古代西域和北方各游牧民族對君王的稱呼。[例]游牧民族的可汗，即是草原上的王者，享有至高的權力和地位。"]],"可能":[["ㄎㄜˇ ㄋㄥˊ","1.或許、也許。[例]天空布滿了烏雲，等會兒可能會下雨。\n2.表示能成為事實的。[例]我們要掌握一切可能的機會。\n3.可能性。[例]據我判斷，發生這種事的可能不大。"]],"史料":[["ㄕˇ ㄌㄧㄠˋ","有關歷史的文獻資料。[例]故宮博物院典藏有大量明、清朝的檔案史料，可供研究明、清史的人士參考。"]],"右手":[["ㄧㄡˋ ㄕㄡˇ","右邊的手。[例]多數的人都用右手寫字。"]],"右方":[["ㄧㄡˋ ㄈㄤ","向右的方向。[例]駕駛在高速公路行經交流道時，請注意右方合流的車子。"]],"右邊":[["ㄧㄡˋ ㄅㄧㄢ","靠右手的一邊。[例]照片中，站在他右邊的是他的妹妹。"]],"司令":[["ㄙ ㄌㄧㄥˋ","軍隊中負責指揮、發號施令的高階軍官。[例]憲兵司令　△司令官"]],"司法":[["ㄙ ㄈㄚˇ","國家司法機關在法規之下為民事、刑事目的所作的一切作為。除狹義的審判權外，尚包括司法行政在內。[例]在民主國家中，司法是完全獨立的，與立法、行政互不相犯。"]],"吃力":[["ㄔ ㄌㄧˋ","用力、費力。[例]這口箱子很重，他搬得非常吃力。"]],"吃喝玩樂":[["ㄔ ㄏㄜ ㄨㄢˊ ㄌㄜˋ","泛指一般不正經或沒有節制的娛樂。[例]吃喝玩樂慣了的人，無法忍受平淡清苦的日子。"]],"吃虧":[["ㄔ ㄎㄨㄟ","1.遭受損失。[例]貨比三家不吃虧。_x000D_\n2.在某方面條件不利。[例]在不熟悉的場地比賽的一方，總是比較吃虧。"]],"吃飯":[["ㄔ ㄈㄢˋ","1.用餐。[例]既然你還有事要辦，我就不留你吃飯了！_x000D_\n2.維持生活。[例]靠天吃飯、吃飯傢伙"]],"吃驚":[["ㄔ ㄐㄧㄥ","受到驚嚇、嚇了一跳。[例]突如其來的地震，讓大家吃驚不已。"]],"各位":[["ㄍㄜˋ ㄨㄟˋ","諸位、每一位。[例]歡迎各位大駕光臨！"]],"各別":[["ㄍㄜˋ ㄅㄧㄝˊ","1.分別。[例]他將藥分裝在罐中，並各別貼上標籤，注明成分及用法。\n2.單獨、特別。[例]各別處理、各別指導"]],"各種":[["ㄍㄜˋ ㄓㄨㄥˇ","每種、每類。[例]春天的花園裡開滿各種花朵。"]],"各自":[["ㄍㄜˋ ㄗˋ","各人。[例]他們商量好計畫後，各自分頭進行。"]],"各行各業":[["ㄍㄜˋ ㄏㄤˊ ㄍㄜˋ ㄧㄝˋ","各種不同的行業。泛指所有行業。[例]政府設立職業學校的主旨，在於培養各行各業的專門人才。"]],"吆喝":[["ㄧㄠ ㄏㄜˋ","高聲喊叫。[例]小販們吆喝叫賣的聲音此起彼落，使整個市場顯得吵雜而熱鬧。"]],"合作":[["ㄏㄜˊ ㄗㄨㄛˋ","在共同的目的下，一起努力工作。[例]在大家通力合作下，這項艱鉅的工作終於完成了。"]],"合力":[["ㄏㄜˊ ㄌㄧˋ","協力、共同出力。[例]為迎接校慶，同學們合力將教室布置得煥然一新。"]],"合奏":[["ㄏㄜˊ ㄗㄡˋ","多種樂器按照不同的聲部，聯合起來演奏。可分成弦樂合奏、管樂合奏、管弦樂合奏三類。[例]今晚音樂會所安排的全為管弦樂合奏的曲子。"]],"合租":[["ㄏㄜˊ ㄗㄨ","共同租用。[例]大學生為了節省開銷，和同學合租房子是常有的事。"]],"合群":[["ㄏㄜˊ ㄑㄩㄣˊ","與人相處融洽，樂於與人合作。[例]班長天性善良、合群，剛入學不久就融入班上，人緣極佳。"]],"合適":[["ㄏㄜˊ ㄕˋ","適宜、恰當。[例]這種衣服給大一點的孩子穿著比較合適。"]],"吉祥":[["ㄐㄧˊ ㄒㄧㄤˊ","吉利祥瑞。[例]吉祥如意"]],"吊掛":[["ㄉㄧㄠˋ ㄍㄨㄚˋ","懸掛。[例]耶誕節將到，她在耶誕樹上吊掛許多應景的裝飾品。"]],"吊橋":[["ㄉㄧㄠˋ ㄑㄧㄠˊ","1.以大鋼索為主體，用許多鐵條把橋面吊在鋼索上而成的橋梁。[例]走在吊橋上搖搖晃晃的經驗真是令人難忘。\n2.橋面可隨時吊起、放下的便橋。古代多用於護城河，現也有用在通航的河道上。[例]美國舊金山的金門大橋是世界有名的吊橋。"]],"同仇敵愾":[["ㄊㄨㄥˊ ㄔㄡˊ ㄉㄧˊ ㄎㄞˋ","共同抱著憤恨的心情，齊心同力抵抗敵人。[例]八年艱苦抗日，全國同胞就是靠著一顆同仇敵愾的愛國心，終獲最後勝利。"]],"同伴":[["ㄊㄨㄥˊ ㄅㄢˋ","伙伴，共同行動的人。[例]登山時，最好能多邀幾個同伴一起去，彼此也好照應。"]],"同夥":[["ㄊㄨㄥˊ ㄏㄨㄛˇ","共同參加某種組織或活動的同伴。[例]同夥中，有幾個是我以前的老朋友。"]],"同學":[["ㄊㄨㄥˊ ㄒㄩㄝˊ","1.一起上課或學習的人。[例]他是我在班上最要好的同學。\n2.對學生的泛稱。[例]這位同學，請問圖書館在哪裡？"]],"同心協力":[["ㄊㄨㄥˊ ㄒㄧㄣ ㄒㄧㄝˊ ㄌㄧˋ","團結一致，共同努力。[例]這座唯一的聯外吊橋，是山區居民同心協力搭建完成的。"]],"同意":[["ㄊㄨㄥˊ ㄧˋ","贊成、允許。[例]借用別人的東西，要先得到對方的同意。"]],"同時":[["ㄊㄨㄥˊ ㄕˊ","1.同一時間。[例]他今天同時接到兩位好朋友寄來的賀年卡片。\n2.並且。[例]他不僅是我們的班長，同時也是畢業生輔導會的總幹事。"]],"同舟共濟":[["ㄊㄨㄥˊ ㄓㄡ ㄍㄨㄥˋ ㄐㄧˋ","比喻同心協力，戰勝困難。[例]情況愈是危急，我們愈應該同舟共濟，攜手共度難關。"]],"同袍":[["ㄊㄨㄥˊ ㄆㄠˊ","本指共穿一件衣服。後引申為軍人之間的互稱。[例]數年的軍旅生活，最讓我懷念的就是同袍間深厚的情誼。"]],"名人":[["ㄇㄧㄥˊ ㄖㄣˊ","具有盛名的人。[例]名人的一舉一動，常受到媒體的關注。"]],"名列前茅":[["ㄇㄧㄥˊ ㄌㄧㄝˋ ㄑㄧㄢˊ ㄇㄠˊ","前茅，古代行軍打仗時，前行兵士所拿作為旗幟的茅草。名列前茅比喻名次排在前面。[例]張同學非常優秀，各項成績在班上總是名列前茅。"]],"名副其實":[["ㄇㄧㄥˊ ㄈㄨˋ ㄑㄧˊ ㄕˊ","名聲或名稱與事實相符合。[例]他熱心公益，樂於助人，真是名副其實的大善人。"]],"名勝古蹟":[["ㄇㄧㄥˊ ㄕㄥˋ ㄍㄨˇ ㄐㄧ","風景優美、保有古文物遺蹟的地方。[例]林家花園是臺灣一處名勝古蹟。"]],"名句":[["ㄇㄧㄥˊ ㄐㄩˋ","著名的句子或短語。[例]「天生我材必有用」是千古名句。"]],"名單":[["ㄇㄧㄥˊ ㄉㄢ","記載人名的單子。[例]黑名單、開會名單"]],"名片":[["ㄇㄧㄥˊ ㄆㄧㄢˋ","1.印有個人姓名、地址、電話、職位等的紙片，用來自我介紹或與人聯絡。[例]他身兼數職，名片上印有許多頭銜。\n2.出名的、廣為人知的電影。[例]亂世佳人是部經典名片。\n3.應用文的一類。指利用現成名片作便條的使用，常用於薦介、留言等。"]],"名稱":[["ㄇㄧㄥˊ ㄔㄥ","名目稱謂。[例]每件事物均有一定的名稱。"]],"名著":[["ㄇㄧㄥˊ ㄓㄨˋ","有名的著作。[例]海明威的《老人與海》是一本世界名著。"]],"吐司":[["ㄊㄨˇ ㄙ","烤過的麵包片。亦指長條形可以切片的麵包。§英toast [例]吐司夾火腿　△土司"]],"吐氣":[["ㄊㄨˇ ㄑㄧˋ","1.呼氣。氣從肺部經由呼吸道吐出體外，與吸氣相反。[例]緊張時，做深呼吸再緩緩吐氣，可以緩和情緒。\n2.舒發心中憤懣鬱結的情緒。[例]揚眉吐氣"]],"吐痰":[["ㄊㄨˇ ㄊㄢˊ","使痰從口中吐出。[例]請勿隨地吐痰，以免破壞環境衛生。"]],"吐血":[["ㄊㄨˋ ㄒㄧㄝˇ","1.上消化道出血，並經口嘔出的現象。[例]他因胃潰瘍而吐血，現已送醫急救。\n2.情緒激動、生氣。[例]一想起他說的那些渾話，就讓人吐血。"]],"吐露":[["ㄊㄨˇ ㄌㄨˋ","1.說出、洩露。[例]經過我不斷的追問，他終於吐露出內心深處的祕密。\n2.顯露、散發。[例]院子裡的夜來香吐露出濃郁的芳香，沁人心脾。"]],"向日葵":[["ㄒㄧㄤˋ ㄖˋ ㄎㄨㄟˊ","植物名。菊科向日葵屬，一年生草本。葉卵形，夏日開黃色大花，頭狀花序，花常朝向太陽，子可食，並可榨油。[例]向日葵種子榨成的油，最受素食者歡迎。　△葵花、朝陽花　◎"]],"君王":[["ㄐㄩㄣ ㄨㄤˊ","世襲體制的王國對統治者的尊稱。[例]關心百姓的君王，總把民生的疾苦，當做自己的問題，去設法解決。"]],"吞噬":[["ㄊㄨㄣ ㄕˋ","1.侵略兼併。[例]吞噬天下\n2.醫學上指消滅、破壞細菌或其他異物的現象。[例]人體內白血球具有吞噬細菌的作用。"]],"吞沒":[["ㄊㄨㄣ ㄇㄛˋ","1.將別人的財物據為己有。[例]拾獲他人物品，如果私下吞沒，在法律上是屬於侵占罪。\n2.淹沒、籠罩。[例]清晨的濃霧幾乎吞沒了整個村莊。"]],"吟唱":[["ㄧㄣˊ ㄔㄤˋ","吟詠歌唱。[例]她藉由吟唱詩詞，更深刻體會到作品的韻律和美感。"]],"否則":[["ㄈㄡˇ ㄗㄜˊ","不然，假如不這樣。[例]天氣寒冷，出外要多穿件衣服，否則容易感冒。"]],"否定":[["ㄈㄡˇ ㄉㄧㄥˋ","不同意、不贊成。相對於肯定而言。[例]我們不能隨便否定一個人的看法。"]],"否極泰來":[["ㄆㄧˇ ㄐㄧˊ ㄊㄞˋ ㄌㄞˊ","否，表示陰陽不交，閉塞不通。泰，表示陰陽交感，萬象亨通。否、泰皆為《易經》卦名，否卦後接著就是泰卦。否極泰來比喻情況壞到極點後逐漸好轉。[例]面臨困境的時候千萬別氣餒，總有一天會否極泰來的。"]],"否決":[["ㄈㄡˇ ㄐㄩㄝˊ","對事物做不贊成的決定。[例]班上有一半人否決這個提案。"]],"否認":[["ㄈㄡˇ ㄖㄣˋ","不承認。[例]他否認將在近期內結婚。"]],"吧檯":[["ㄅㄚ ㄊㄞˊ","專供調酒、煮咖啡等的櫃檯。[例]吧檯服務生"]],"吩咐":[["ㄈㄣ ㄈㄨˋ","叮囑。多指長輩囑告晚輩，含有命令、派遣的語氣。[例]臨行前，父親再三吩咐要把交代的事辦好。"]],"含糊":[["ㄏㄢˊ ㄏㄨˊ","1.語意籠統，不清楚。[例]他言辭含糊，讓人摸不清他的意圖。\n2.做事不澈底，馬馬虎虎。[例]他做事認真負責，絕不含糊。"]],"含苞待放":[["ㄏㄢˊ ㄅㄠ ㄉㄞˋ ㄈㄤˋ","形容花朵將開而未開的樣子。[例]他最喜歡含苞待放的玫瑰花。"]],"含量":[["ㄏㄢˊ ㄌㄧㄤˋ","物質中包含某種成分的數量。[例]由於水氣含量不足，這波寒流並未使合歡山降下瑞雪。"]],"含飴弄孫":[["ㄏㄢˊ ㄧˊ ㄋㄨㄥˋ ㄙㄨㄣ","指老年人生活安適，以逗弄孫兒為樂。[例]王伯伯自退休後，就在家含飴弄孫，安享晚年。"]],"吱吱喳喳":[["ㄓ ㄓ ㄓㄚ ㄓㄚ","狀聲詞：(1) 形容鳥叫聲。[例]麻雀聚在電線桿上，吱吱喳喳叫個不停。　(2) 形容吵雜的說話聲。[例]為了決定去哪裡玩，小朋友們個個七嘴八舌，吱吱喳喳討論個不停。"]],"吵嘈":[["ㄔㄠˇ ㄘㄠˊ","聲音喧鬧雜亂。[例]天才剛亮，小鳥便在樹上吵嘈不已。"]],"吵架":[["ㄔㄠˇ ㄐㄧㄚˋ","以言語相爭執。[例]為了一點小事吵架，真是太不值得了！"]],"吵雜":[["ㄔㄠˇ ㄗㄚˊ","聲音吵鬧雜亂。[例]他住在人聲吵雜的夜市旁，每晚都無法入睡。"]],"吵鬧":[["ㄔㄠˇ ㄋㄠˋ","1.爭吵，發生口角。[例]大家坐下來好好談，何必為了小事吵鬧不休呢？\n2.吵雜、不安靜。[例]這幢房子位於市區，四周環境難免較為吵鬧。"]],"吶喊":[["ㄋㄚˋ ㄏㄢˇ","高聲叫喊。[例]那支遊行隊伍高聲吶喊著他們的行進口號。"]],"吸取":[["ㄒㄧ ㄑㄩˇ","吸收採取。[例]年輕人應該多吸取老年人的經驗，作為自己為人行事的參考。"]],"吸引":[["ㄒㄧ ㄧㄣˇ","吸收導引。[例]這家餐廳打算重新整修裝潢以吸引顧客上門。"]],"吸管":[["ㄒㄧ ㄍㄨㄢˇ","1.一種由塑膠作成，專供吸食飲料之用的管狀物。[例]他用吸管慢慢啜飲一杯牛奶。\n2.一種用以量取液體的器具。為兩端細，中間粗的玻璃管，上刻有容量度數。[例]他用吸管吸取少量碘酒滴到培養皿中。"]],"吹奏":[["ㄔㄨㄟ ㄗㄡˋ","演奏笛、簫等管樂器。後泛指演奏音樂。[例]爺爺將樹葉一捲，隨口吹奏出美妙的音樂。"]],"吹拂":[["ㄔㄨㄟ ㄈㄨˊ","空氣流動輕觸物體。[例]微風吹拂水面，引起陣陣漣漪。"]],"吹牛":[["ㄔㄨㄟ ㄋㄧㄡˊ","誇口、說大話。[例]他愛吹牛，所以朋友們總是不太相信他的話。"]],"吹風":[["ㄔㄨㄟ ㄈㄥ","1.讓風吹拂。[例]他把溼衣服放在窗口吹風，一會兒就乾了。\n2.用吹風機吹乾頭髮。[例]洗完頭的客人正等著美髮師幫她吹風。"]],"吼叫":[["ㄏㄡˇ ㄐㄧㄠˋ","大聲的呼喊。[例]動物園裡的獅子突然大聲吼叫，把參觀的遊客嚇了一跳。"]],"吼聲":[["ㄏㄡˇ ㄕㄥ","憤怒或情緒激動時的喊叫聲。[例]深山裡，不時傳來一陣陣老虎的吼聲。"]],"呆住":[["ㄉㄞ ㄓㄨˋ","因受驚嚇或突發情形而致使一時神志恍惚，未能立即有所反應。[例]他走進屋內，看到裡面一片凌亂，頓時呆住了。"]],"呆頭呆腦":[["ㄉㄞ ㄊㄡˊ ㄉㄞ ㄋㄠˇ","形容言行遲鈍，不靈活的樣子。[例]他一副呆頭呆腦的模樣，沒想到在這次段考中高居榜首。"]],"呈現":[["ㄔㄥˊ ㄒㄧㄢˋ","出現、顯現。[例]一剎那間，在他滿是皺紋的臉上，呈現出一絲笑容。"]],"告知":[["ㄍㄠˋ ㄓ","說出來，讓對方了解。[例]服藥後，如有不良反應，應隨時告知醫師，並做進一步檢驗。"]],"告訴":[["ㄍㄠˋ ㄙㄨˋ","1.被害人向高級長官或法政機關告發，稱為「告訴」。[例]他因為土地被侵占，而向法院提出告訴。\n\t\n2.通知。[例]老師要班長告訴大家，明天學校將舉行大掃除。"]],"告辭":[["ㄍㄠˋ ㄘˊ","向人辭別。[例]客人在談完話後，就起身告辭了。"]],"呢絨":[["ㄋㄧˊ ㄖㄨㄥˊ","用獸毛或人造毛等製成的毛織品的統稱。[例]呢絨帽"]],"周全":[["ㄓㄡ ㄑㄩㄢˊ","完備、齊全。[例]多虧他設想周全，提早出發，才使我們免於塞車之苦。"]],"周圍":[["ㄓㄡ ㄨㄟˊ","環繞在物體四周的部分。[例]監獄的周圍架設著高壓電線，是為了防止人犯逃脫。"]],"周詳":[["ㄓㄡ ㄒㄧㄤˊ","周到而詳盡。[例]他計劃周詳，所以事情進行得十分順利。"]],"周遭":[["ㄓㄡ ㄗㄠ","四周、周圍。[例]他十分注重居家周遭的環境整潔。"]],"呱呱":[["ㄍㄨ ㄍㄨ","狀聲詞。形容小兒的啼哭聲。[例]隨著小孩呱呱墜地，父親的肩上又多了一項負擔。"]],"呱呱墜地":[["ㄍㄨ ㄍㄨ ㄓㄨㄟˋ ㄉㄧˋ","呱呱，嬰兒的哭聲。呱呱墜地比喻誕生。[例]他自從呱呱墜地以後，便受到家人無微不至的呵護。"]],"味覺":[["ㄨㄟˋ ㄐㄩㄝˊ","食物進入口腔後，刺激味覺感受器，經由味覺神經傳到大腦所產生的知覺。如酸、甜、苦、鹹等。[例]生病會使味覺失去靈敏度。"]],"味道":[["ㄨㄟˋ ㄉㄠˋ","1.舌頭嚐東西所得到的感覺。[例]這碗湯的味道真好。\n2.鼻子聞東西所得到的感覺。[例]這朵花的味道真香。\n3.趣味、意味。[例]這本書讀起來很有味道。"]],"呻吟":[["ㄕㄣ ㄧㄣˊ","因病痛或哀傷而發出聲音。[例]他因受不了手術後的疼痛，躺在病床上呻吟個不停。"]],"呼吸":[["ㄏㄨ ㄒㄧ","生物體與外界環境進行氣體交換的過程。如低等動物靠皮膚呼吸；人和高等動物用肺呼吸，吸入新鮮的空氣，呼出體內的二氧化碳，植物則透過表面的組織進行氣體交換。[例]常到森林中呼吸新鮮的空氣，有益身心健康。"]],"呼喚":[["ㄏㄨ ㄏㄨㄢˋ","呼喊叫喚。[例]他雖臥病在床，口中仍不斷呼喚著孩子的名字。"]],"呼嘯":[["ㄏㄨ ㄒㄧㄠˋ","發出高而長的聲音。[例]家在大馬路旁，經常會在深夜聽到車子呼嘯而過的聲音。"]],"呼天搶地":[["ㄏㄨ ㄊㄧㄢ ㄑㄧㄤ ㄉㄧˋ","搶地，用頭撞地。呼天搶地形容極度的哀傷、悲痛。[例]她接獲兒子車禍死亡的消息後，呼天搶地，悲慟不已。"]],"呼朋引伴":[["ㄏㄨ ㄆㄥˊ ㄧㄣˇ ㄅㄢˋ","吆喝同類型的人參與某事。常有鄙視的意味。[例]老陳素來不務正業，天天呼朋引伴，四處遊蕩。"]],"呼號":[["ㄏㄨ ㄏㄠˊ","大聲哭喊。[例]當空難消息證實後，罹難者家屬呼號不斷，悲不能已。"],["ㄏㄨ ㄏㄠˋ","以一組字母、數字、或任何文字及發音詞的組合，識別一個通信設施、指揮所、機關，或部隊者，稱為「呼號」。主要用途為建立及保持通信。[例]救援隊收到遇難者求救的呼號，便馬上前往救援。"]],"呼風喚雨":[["ㄏㄨ ㄈㄥ ㄏㄨㄢˋ ㄩˇ","1.形容神仙或道士法力強大，能夠駕馭風雨。[例]民間傳說裡的道士既能呼風喚雨，又能驅邪除魔。\n2.比喻人神通廣大，深具影響力。[例]他在業界具有呼風喚雨的能力，讓人不得不佩服。"]],"命令":[["ㄇㄧㄥˋ ㄌㄧㄥˋ","1.下令、號令。[例]司令官命令全連的將士加強警戒。\n2.上對下的指示。[例]頒布命令"]],"咀嚼":[["ㄐㄩˇ ㄐㄩㄝˊ","1.用牙齒咬碎與磨細食物。[例]細細咀嚼食物，有助於腸胃消化。\n2.比喻反覆體會、玩味。[例]他說過的那些話，細細咀嚼起來，還真有點道理呢！"]],"和婉":[["ㄏㄜˊ ㄨㄢˇ","溫和委婉。[例]經過一番和婉的勸導，他們兩人之間的爭執終於順利解決了。"]],"和尚":[["ㄏㄜˊ ㄕㄤˋ","泛稱男性僧侶。[例]他晚年看破紅塵，出家當了和尚。　△沙門、僧人"]],"和局":[["ㄏㄜˊ ㄐㄩˊ","1.比賽的結果不分勝負。[例]他們兩個象棋棋力相當，比賽經常以和局收場。\n2.議和的局勢。[例]如今戰爭已呈和局，大家可以鬆一口氣了。"]],"和悅":[["ㄏㄜˊ ㄩㄝˋ","溫和喜悅。[例]不管心情好壞，他總是臉色和悅的對待別人。"]],"和氣":[["ㄏㄜˊ ㄑㄧˋ","1.態度和藹可親。[例]李奶奶待人相當和氣，村裡的人都很敬重她。\n2.和睦融洽的感情。[例]大家有緣齊聚一堂，千萬別為了一點小事而傷了和氣。"]],"和煦":[["ㄏㄜˊ ㄒㄩˇ","溫暖祥和的樣子。[例]冬日和煦的陽光照在身上，感覺真舒服。"]],"和藹":[["ㄏㄜˊ ㄞˇ","溫和的樣子。[例]和藹可親"]],"和解":[["ㄏㄜˊ ㄐㄧㄝˇ","1.停止爭端，重歸於好。[例]經過一個星期冷戰，他們倆夫妻昨晚終於和解了。\n2.法律上指當事人彼此約定，互相讓步，以終止爭執或防止爭執發生的作為。[例]這件訴訟案因雙方當事人願意庭外和解，而順利落幕。"]],"和諧":[["ㄏㄜˊ ㄒㄧㄝˊ","1.配合得適當、協調。[例]音調和諧\n2.和睦融洽。[例]厲行法治，遏止暴力，才能建立和諧的社會。"]],"咒語":[["ㄓㄡˋ ㄩˇ","宗教上稱具有特殊力量的語詞或語句。[例]法會上，法師口唸咒語，超渡亡魂。"]],"咖哩":[["ㄎㄚ ㄌㄧˇ","用胡椒、薑黃、番椒、茴香、陳皮等的粉末製成的調味品。色黃、味香而辛辣，以印度所產最為著名。§英curry[例]媽媽用咖哩做了一道色香味美的燴飯。　△咖喱"]],"咖啡":[["ㄎㄚ ㄈㄟ","植物名。茜草科咖啡樹屬，陰光性常綠灌木。原產於東非阿比西尼亞，現多栽培於熱帶地區。高約四至六公尺，花為白色。核果為橢圓形，成熟時呈黃紅色或紫紅色，果實內含有兩顆種子。種子為咖啡原料，焙乾後研成細末可沖泡為飲料，有興奮神經的效果。§英coffee[例]很多人常仰賴咖啡提神，然而不宜過量，以免傷身。"]],"咖啡因":[["ㄎㄚ ㄈㄟ ㄧㄣ","一種存在於茶葉、可可及咖啡中的植物鹼。結晶體呈柱狀，白色有光澤，且有苦味。具興奮中樞神經和利尿的功能。§英caffeine[例]茶葉、咖啡中含有咖啡因，被廣泛用來作為提神的飲料。　△咖啡鹼"]],"咚咚":[["ㄉㄨㄥ ㄉㄨㄥ","狀聲詞。摹擬碰撞或擊鼓的聲音。[例]廟會慶典時，舞獅跳躍翻滾，鑼鼓聲咚咚作響，非常熱鬧。"]],"咬文嚼字":[["ㄧㄠˇ ㄨㄣˊ ㄐㄧㄠˊ ㄗˋ","1.在詞句上斟酌推敲。[例]這篇文章過於咬文嚼字，反而使重心模糊。\n2.譏笑人迂腐固執而不知變通。[例]讀書是為了明白事理，不可過於咬文嚼字，不知變通。\n3.形容賣弄文才、裝腔作勢。[例]看他咬文嚼字，裝腔作勢的樣子，真令人厭惡。"]],"咬牙切齒":[["ㄧㄠˇ ㄧㄚˊ ㄑㄧㄝˋ ㄔˇ","形容非常憤恨的樣子。[例]他氣得咬牙切齒，連話都說不出來了。"]],"咬緊":[["ㄧㄠˇ ㄐㄧㄣˇ","緊緊的咬住。[例]狼犬咬緊小偷的褲管不放。"]],"咳嗽":[["ㄎㄜˊ ㄙㄡˋ","喉部或氣管的黏膜受痰或氣體的刺激，引起反射作用，把氣或痰用力排出。[例]他咳嗽不斷，八成是感冒了。"]],"哀傷":[["ㄞ ㄕㄤ","悲哀傷痛。[例]在海外的他，得知祖母逝世的消息，不禁哀傷欲絕。"]],"哀愁":[["ㄞ ㄔㄡˊ","哀傷悲愁。[例]家中突遭巨變，使他陷入一片哀愁之中。"]],"哀求":[["ㄞ ㄑㄧㄡˊ","苦苦請求。[例]他行竊時被逮個正著，跪地哀求店主給他一個改過自新的機會。"]],"哀號":[["ㄞ ㄏㄠˊ","悲痛號哭。[例]他因腿上傷口疼痛，哀號了一夜。"]],"品味":[["ㄆㄧㄣˇ ㄨㄟˋ","1.品嘗辨味。[例]這幅畫意境悠遠，值得再三品味。_x000D_\n2.引申為對事物具高度的品鑑能力。[例]從他的穿著打扮來看，他是一個相當有品味的人。"]],"品嘗":[["ㄆㄧㄣˇ ㄔㄤˊ","古代帝王進食前，先由人試嘗食物；也就是「品品必嘗而後進」的意思。後來引申為仔細品味。[例]品嘗食物、品嘗人生"]],"品牌":[["ㄆㄧㄣˇ ㄆㄞˊ","產品的名號，可藉以傳達企業形象與精神。[例]自從外匯開放以後，許多廠商引進不少國外品牌的產品。"]],"品茶":[["ㄆㄧㄣˇ ㄔㄚˊ","飲茶而細辨其滋味。[例]平心靜氣來品茶，才能識得茶中味。"]],"品行":[["ㄆㄧㄣˇ ㄒㄧㄥˋ","人的品格和德行。[例]讀書的目的是為了培養高尚的品行。"]],"品質":[["ㄆㄧㄣˇ ㄓˊ","物品的質地。[例]商品品質的好壞，直接影響市場的銷路。"]],"品鑑":[["ㄆㄧㄣˇ ㄐㄧㄢˋ","品評鑑別。[例]本公司向來以任事能力的優劣作為品鑑人才的標準。"]],"哄堂大笑":[["ㄏㄨㄥ ㄊㄤˊ ㄉㄚˋ ㄒㄧㄠˋ","眾人同時大笑。典出唐．趙璘（ㄌㄧㄣˊ）《因話錄．卷五．徵部》。[例]他突然做了一個滑稽的動作，惹得眾人哄堂大笑。"]],"哇哇叫":[["ㄨㄚ ㄨㄚ ㄐㄧㄠˋ","不斷的大叫。[例]有人在混亂中踩到他的腳，害他疼得哇哇叫。"]],"哈哈大笑":[["ㄏㄚ ㄏㄚ ㄉㄚˋ ㄒㄧㄠˋ","張口大聲笑。[例]他故意做出一副滑稽樣，逗得大家哈哈大笑。"]],"哈巴狗":[["ㄏㄚˇ ㄅㄚ ㄍㄡˇ","1.動物名。哺乳綱食肉目。體型小，腿短，毛長而密。個性溫馴，面部黝黑，額上有皺紋，討人喜歡。是有名的玩賞狗。[例]他家那隻哈巴狗很機靈，一聽到門鈴響起，就會跑到玄關等待來人。　△北京狗、獅子狗_x000D_\n2.諷指諂媚奉承的小人。[例]他手下都是些哈巴狗，當然就不容易發現自己的缺失。"]],"員工":[["ㄩㄢˊ ㄍㄨㄥ","團體組織中的工作人員。[例]新招聘的員工表現非常出色。"]],"哥哥":[["ㄍㄜ ˙ㄍㄜ","稱謂：(1)稱兄長。[例]哥哥從小品學兼優，是弟妹們的好榜樣。　◎　(2)稱同輩的男性。[例]隔壁的張哥哥今年剛考上大學，是眾人欽羨的對象。"]],"哪吒":[["ㄋㄨㄛˊ ㄓㄚˋ","佛教故事中的神仙。在小說演義中，哪吒出生時手帶金圈，腹圍紅綾，造形很突出。七歲時，因無意中殺死龍王之子，龍王一怒向其父李靖問罪，哪吒怕牽累父母而自殺。太乙真人因憐惜哪吒靈魂無處寄託，摘取蓮花葉鋪成人形使其重生。後哪吒與其父皆成神，四處捉妖降魔。[例]傳說哪吒腳踏風火輪，使他快速如飛。"]],"哭喊":[["ㄎㄨ ㄏㄢˇ","大聲哭泣喊叫。[例]弟弟因要不到玩具，而在地上哭喊撒賴。"]],"哭泣":[["ㄎㄨ ㄑㄧˋ","哭。[例]他個性堅強，遇到挫折從不哭泣。"]],"哭訴":[["ㄎㄨ ㄙㄨˋ","哭著訴說。[例]債權人向警察哭訴被倒債的經過。"]],"哲學":[["ㄓㄜˊ ㄒㄩㄝˊ","研究宇宙、人生原理及原則的學問。[例]唯心主義哲學、唯物主義哲學"]],"哲理":[["ㄓㄜˊ ㄌㄧˇ","有關宇宙人生的根本道理。[例]他這一番話很富哲理，使我獲益良多。"]],"唉唷":[["ㄞ ㄧㄛ","嘆詞。表示驚訝或痛苦。[例]唉唷，我的頭好痛。"]],"唯一":[["ㄨㄟˊ ㄧ","獨一無二。[例]小英是本班唯一得到全勤獎的畢業生。"]],"唱和":[["ㄔㄤˋ ㄏㄜˋ","1.唱歌時，一唱一和。[例]小牛蛙彼此唱和著，這鳴聲是夏夜裡最詳和的催眠曲。\n2.以詩詞互相酬答。[例]他們自組詩社，以文會友，朝夕唱和，吟誦不輟。"]],"唱歌":[["ㄔㄤˋ ㄍㄜ","吟唱歌曲。[例]一群小朋友圍在那裡唱歌跳舞，十分快樂。"]],"唾棄":[["ㄊㄨㄛˋ ㄑㄧˋ","輕視鄙棄。[例]他因沉迷酒色，蕩盡家產而遭到親友的唾棄。"]],"唾液":[["ㄊㄨㄛˋ ㄧㄝˋ","由口腔黏膜與唾腺分泌液混合而成的黏液。可滋潤口腔、浸漬食物、分解澱粉，具有部分的消化作用。[例]唾液有益於說話時滋潤口腔及幫助食物的吞嚥。　△口水"]],"啁啾":[["ㄓㄡ ㄐㄧㄡ","狀聲詞。形容鳥叫聲。[例]早晨鳥兒成群地啁啾鳴叫，將人們從沉睡中喚醒。"]],"啄木鳥":[["ㄓㄨㄛˊ ㄇㄨˋ ㄋㄧㄠˇ","動物名。鳥綱啄木鳥目啄木鳥科。嘴銳直而堅，能破樹皮穿穴，舌細長，尖端有鉤，可捕食樹洞裡的蠹蟲。足四趾，二向前，二向後，便於攀援樹幹。通常棲息於森林中，在樹幹上築巢而居。[例]就自然生態而言，啄木鳥是一種益鳥。"]],"啄食":[["ㄓㄨㄛˊ ㄕˊ","禽類動物用嘴取食。[例]小雞在泥地上啄食蚯蚓，填飽肚子。"]],"商品":[["ㄕㄤ ㄆㄧㄣˇ","總稱為買賣而製造的物品。[例]所謂商品可分為原料、半成品及成品。"]],"商店":[["ㄕㄤ ㄉㄧㄢˋ","買賣貨物的店鋪。[例]此地大小商店林立，已發展成為商業區。"]],"商標":[["ㄕㄤ ㄅㄧㄠ","為表彰商品，而以文字或圖畫等作成的一種標記。經政府核准註冊後取得專用權。[例]註冊商標，翻印必究。　△牌子"]],"商行":[["ㄕㄤ ㄏㄤˊ","規模較大的商店。[例]清末各租界地內有許多洋人設立的商行。"]],"商討":[["ㄕㄤ ㄊㄠˇ","商量討論。[例]大家若再這樣堅持己見，互不退讓，是商討不出結果的。"]],"商譽":[["ㄕㄤ ㄩˋ","商人或商店行號的信譽。[例]他不計血本的繼續生產，只為維護商譽。"]],"商量":[["ㄕㄤ ㄌㄧㄤˊ","商談討論，交換意見。[例]大家有話好商量，不要動粗，傷了和氣！"]],"問卷":[["ㄨㄣˋ ㄐㄩㄢˋ","一種設計成問答方式的意見調查表，由被調查人自行填答。[例]問卷調查"]],"問號":[["ㄨㄣˋ ㄏㄠˋ","一種標點符號。用在疑問句之後，其符號為「？」。如你到那兒去？[例]老師因看不懂他的作文寫些什麼，所以批改時打了個問號。　△疑問號"]],"問題":[["ㄨㄣˋ ㄊㄧˊ","1.足以引人研究討論，或尚待解決的事。[例]公害問題、犯罪問題\n2.考試時的題目。[例]期末考的問題出得太難了。"]],"啜泣":[["ㄔㄨㄛˋ ㄑㄧˋ","低聲哭泣。[例]因為得不到家人的諒解，她躲在房內啜泣，傷心不已。"]],"啜飲":[["ㄔㄨㄛˋ ㄧㄣˇ","喝、吸食。[例]在寧靜的夜裡，啜飲一口香茗，可以忘卻白天的一切煩憂。"]],"啞劇":[["ㄧㄚˇ ㄐㄩˋ","一種不用言語，只用動作、姿態來表達劇情的戲劇。　△默劇"]],"啞巴吃黃連":[["ㄧㄚˇ ㄅㄚ ㄔ ㄏㄨㄤˊ ㄌㄧㄢˊ","(歇後語)有苦說不出。[例]別提了！我是啞巴吃黃連──有苦說不出。"]],"啞鈴":[["ㄧㄚˇ ㄌㄧㄥˊ","一種體操器具。大部分是鐵製品，兩端各有圓形的錘，中為手握之柄。可鍛鍊臂力，常作為體操、舉重的輔助器材。[例]他手臂上結實的肌肉，全靠每天勤舉啞鈴而來。"]],"啟事":[["ㄑㄧˇ ㄕˋ","在報刊或布告欄上的公開聲明。[例]尋人啟事、道歉啟事、遺失啟事"]],"啼叫":[["ㄊㄧˊ ㄐㄧㄠˋ","鳥鳴。[例]黃鶯啼叫的聲音非常清脆悅耳。"]],"啼笑皆非":[["ㄊㄧˊ ㄒㄧㄠˋ ㄐㄧㄝ ㄈㄟ","形容情緒複雜，不知是該難過還是該發笑。[例]妹妹用了半條口紅塗了個大花臉，還自認為很漂亮，讓媽媽啼笑皆非。"]],"啼聲":[["ㄊㄧˊ ㄕㄥ","1.動物的鳴叫聲。[例]相傳杜鵑鳥的啼聲淒絕哀婉。\n2.幼兒的哭聲。[例]她半夜被嬰兒的啼聲吵醒，連忙披衣起來查看。"]],"啾啾":[["ㄐㄧㄡ ㄐㄧㄡ","狀聲詞：(1) 形容鳥蟲的鳴聲。[例]走在幽靜的山徑中，不時可以聽到啾啾的鳥叫聲。　(2) 形容馬鳴聲。[例]不聞爺孃喚女聲，但聞燕山胡騎聲啾啾。（南朝梁．無名氏〈木蘭詩〉二首之一）"]],"善意":[["ㄕㄢˋ ㄧˋ","好意。[例]我們應當要有接受別人善意批評的雅量。"]],"善良":[["ㄕㄢˋ ㄌㄧㄤˊ","心地端正純潔，沒有歹意邪念。[例]他時常救助貧苦的人，心地非常善良。"]],"喇叭":[["ㄌㄚˇ ㄅㄚ","1.樂器名。屬吹奏樂器。多為銅製。上端小，身細長而漸大，尾端圓敞。軍中多用來傳達命令。可分為法國號、小號、中音號、低音號、長號等。[例]十九世紀時，有人利用閥的特殊裝置來改變喇叭管身的長度，使其音色和性能日趨完美。\n2.裝置在交通工具內，將電流的變化轉變成聲音的設備。用手操作，具警告作用。[例]開車時請勿亂按喇叭。\n3.音響系統裡，利用電能轉成聲音的裝置。其構造主要有兩部分：一是固定位置的永久磁鐵，一是和線圈相連的紙製圓錐。當線圈內的電流產生變化時，受磁鐵作用的力量也起變化，紙製圓錐跟著振動，因而發出聲音。　△揚聲器\n4.借指多話，喜歡到處宣傳的人。[例]他真是個大喇叭，無論聽到什麼消息，立刻到處廣播。"]],"喉嚨":[["ㄏㄡˊ ㄌㄨㄥˊ","→咽喉"]],"喊叫":[["ㄏㄢˇ ㄐㄧㄠˋ","大聲呼叫。[例]她情急之下大聲喊叫，把小偷嚇跑了。"]],"喘氣":[["ㄔㄨㄢˇ ㄑㄧˋ","1.急促呼吸。[例]一路跑來，小明到現在還不停的喘氣呢！\n2.短暫的休息、放鬆。[例]忙了半天，終於可以稍微喘氣一下了。"]],"喜事":[["ㄒㄧˇ ㄕˋ","1.泛指一切值得慶賀的事。[例]人逢喜事精神爽。\n2.特指婚嫁的事。[例]月底大哥就要結婚了，大家都忙著辦喜事。"]],"喜好":[["ㄒㄧˇ ㄏㄠˋ","愛好、喜歡。[例]只要是他喜好的事物，他總是不計一切的去爭取。"]],"喜孜孜":[["ㄒㄧˇ ㄗ ㄗ","歡喜的樣子。[例]他喜孜孜的說著這次得獎的趣事。"]],"喜怒哀樂":[["ㄒㄧˇ ㄋㄨˋ ㄞ ㄌㄜˋ","人的各種情緒。[例]她是一個非常情緒化的人，所有的喜怒哀樂都寫在臉上。"]],"喜悅":[["ㄒㄧˇ ㄩㄝˋ","高興、愉快。[例]看到孩子們個個都很爭氣，她的內心充滿喜悅。"]],"喜愛":[["ㄒㄧˇ ㄞˋ","喜歡愛好。[例]他喜愛文學，從小就熟讀唐詩三百首。"]],"喜歡":[["ㄒㄧˇ ㄏㄨㄢ","1.快樂、高興。[例]媽媽收到弟弟親手畫的卡片，很是喜歡。\n2.喜愛。[例]爸爸最喜歡爬山，只要有時間他就會帶我同行。"]],"喝令":[["ㄏㄜˋ ㄌㄧㄥˋ","大聲命令。[例]看到兩兄弟打架，媽媽急忙喝令他們住手。"]],"喝斥":[["ㄏㄜˋ ㄔˋ","大聲責罵。[例]小孩子做錯事時要善加調教，而不要只是一味的喝斥。"]],"喝西北風":[["ㄏㄜ ㄒㄧ ㄅㄟˇ ㄈㄥ","比喻窮得沒有食物吃。[例]像他那樣的好吃懶做，不用多久就得喝西北風了。"]],"喝采":[["ㄏㄜˋ ㄘㄞˇ","大聲叫好。[例]他精湛的演出，贏得全場觀眾的喝采。"]],"喧囂":[["ㄒㄩㄢ ㄒㄧㄠ","聲音大而吵雜。[例]入夜後的臺北街頭，車聲依然喧囂不已。"]],"喧騰":[["ㄒㄩㄢ ㄊㄥˊ","1.吵鬧喧囂。[例]因為眾人意見分歧，彼此喧騰不休，直到會議結束仍無法達成協議。\n2.比喻聲名廣播。[例]他因提出特異的主張而喧騰一時。"]],"喧鬧":[["ㄒㄩㄢ ㄋㄠˋ","喧譁吵鬧。[例]為了避免抗議隊伍喧鬧滋事，部長決定接見部分代表。"]],"喪事":[["ㄙㄤ ㄕˋ","人死後的殮葬、哀祭等事宜。[例]辦理喪事應力求簡單莊嚴，避免不必要的排場鋪張。"]],"喪失":[["ㄙㄤˋ ㄕ","失去。[例]他因遲到而喪失了這次朗讀比賽的資格。"]],"喪家":[["ㄙㄤ ㄐㄧㄚ","有喪事的人家。[例]喪家的大門如果貼上「慈制」兩字，則表示母親去世。"]],"喪氣":[["ㄙㄤˋ ㄑㄧˋ","1.失去志氣或勇氣，顯得精神頹喪。[例]垂頭喪氣\n\t\n2.倒楣或感到不吉利。[例]才剛動工，就遇到這麼多麻煩，真喪氣！"]],"喪葬":[["ㄙㄤ ㄗㄤˋ","辦理人死後的一切事宜。[例]軍方依政府指示成立治喪委員會，處理因公殉職官兵的喪葬事宜。"]],"單于":[["ㄔㄢˊ ㄩˊ","漢朝時對匈奴君長的稱號。[例]月黑雁飛高，單于夜遁逃。（唐．盧綸〈和張僕射塞下曲〉六首之三）"]],"單刀直入":[["ㄉㄢ ㄉㄠ ㄓˊ ㄖㄨˋ","比喻直截了當的論及問題的核心。[例]他單刀直入的切入主題，令對方有點招架不住。"]],"單據":[["ㄉㄢ ㄐㄩˋ","凡可用作憑據的單子。[例]買賣交易的單據平時要保管好，必要時可供查證。"]],"單數":[["ㄉㄢ ㄕㄨˋ","1.數學上指正的奇數。如 1、 3、 5、 7、 9等數。\n2.某些語言中，如英語，表示單一數量的語詞。相對於複數而言。[例]單數主詞、單數動詞"]],"單槍匹馬":[["ㄉㄢ ㄑㄧㄤ ㄆㄧ ㄇㄚˇ","一桿槍，一匹馬，指一個人單身上陣作戰。比喻一個人單獨行動，沒有任何助力。[例]他當初赤手空拳，單槍匹馬創立了這間公司，如今旗下已有近百名員工了。"]],"單純":[["ㄉㄢ ㄔㄨㄣˊ","人或事物簡單而不複雜。[例]我這個人很單純，從不把事情想得太複雜。"]],"單薄":[["ㄉㄢ ㄅㄛˊ","1.所穿衣服既少且薄。[例]夜深了，你穿得如此單薄，小心著涼。\n2.身體薄弱、瘦弱。[例]她那單薄的身子，怎禁得起如此的風吹雨打？\n3.微薄稀少。[例]勢力單薄、人丁單薄"]],"單調":[["ㄉㄢ ㄉㄧㄠˋ","1.簡單而且缺乏變化。[例]演講時聲音不要太過單調，否則不容易吸引聽眾。\n2.形容簡單呆板，少變化而無趣味。[例]單調無趣的演講總令人昏昏欲睡。"]],"嗎啡":[["ㄇㄚˇ ㄈㄟ","由鴉片蒸發而成的無色微細柱狀結晶。味苦，有毒。醫學上用為麻醉性鎮痛劑，連續使用會上癮。§法morphine[例]癌症病人到後期往往須藉嗎啡來止痛。　△白麵兒"]],"嗓音":[["ㄙㄤˇ ㄧㄣ","喉嚨所發出的聲音。[例]他的嗓音低沉而有磁性。"]],"嗜好":[["ㄕˋ ㄏㄠˋ","特別的喜好。[例]集郵是他的嗜好。"]],"嗤之以鼻":[["ㄔ ㄓ ㄧˇ ㄅㄧˊ","從鼻子裡發出冷笑。表示不屑或鄙視。[例]他每每大言不慚，惹得眾人對他嗤之以鼻。"]],"嘆息":[["ㄊㄢˋ ㄒㄧˊ","嘆氣。[例]看他年紀輕輕就誤蹈法網，犯下大錯，令人嘆息不已。"]],"嘈雜":[["ㄘㄠˊ ㄗㄚˊ","形容聲音喧鬧、雜亂。[例]市場內交易熱絡，人聲嘈雜。"]],"嘉賓":[["ㄐㄧㄚ ㄅㄧㄣ","尊稱客人或來賓。[例]蒞臨這場盛會的嘉賓有很多是政、商界的名人。"]],"嘔吐":[["ㄡˇ ㄊㄨˋ","胃壁收縮異常，食物逆出口外。多由胃病、中毒、藥物刺激、半規管平衡作用受干擾或精神作用引起。[例]嘔吐是暈車、暈船的症狀之一。"]],"嘖嘖稱奇":[["ㄗㄜˊ ㄗㄜˊ ㄔㄥ ㄑㄧˊ","對事物的奇妙讚嘆不已。[例]看過那位氣功大師現場表演的人，莫不嘖嘖稱奇。"]],"嘗試":[["ㄔㄤˊ ㄕˋ","試一試、試驗。[例]在還沒確定自己的志向前，不妨多方嘗試一下。"]],"嘮叨":[["ㄌㄠˊ ㄉㄠ","囉囉嗦嗦的說個不停。[例]她嘮叨半天，到底在說些什麼呀？"]],"嘲弄":[["ㄔㄠˊ ㄋㄨㄥˋ","嘲笑戲弄。[例]雖然大家不斷的嘲弄他，但是他一點也不生氣。"]],"嘲諷":[["ㄔㄠˊ ㄈㄥˋ","嘲笑諷刺。[例]做人要謙虛，不可隨便嘲諷別人。"]],"嘴巴":[["ㄗㄨㄟˇ ㄅㄚ","1.嘴。[例]牙醫要病人張開嘴巴。_x000D_\n2.口部附近的部位。[例]他意識到自己說錯了話，就打了自己一個嘴巴。"]],"嘴脣":[["ㄗㄨㄟˇ ㄔㄨㄣˊ","脣。[例]弟弟剛吃完蛋糕，嘴脣還沾著不少奶油呢！ 　◎"]],"嘴角":[["ㄗㄨㄟˇ ㄐㄧㄠˇ","上下脣兩端連接處。[例]說到得意處，他嘴角揚起，十分自得。"]],"嘹亮":[["ㄌㄧㄠˊ ㄌㄧㄤˋ","聲音清澈響亮。[例]她的歌聲清脆嘹亮，非常動聽。"]],"嘻嘻哈哈":[["ㄒㄧ ㄒㄧ ㄏㄚ ㄏㄚ","1.形容嘻笑歡樂的樣子。[例]小朋友嘻嘻哈哈地玩耍，好不快樂。_x000D_\n2.輕浮不莊重。[例]師長苦口婆心地勸導，而他依舊擺出嘻嘻哈哈的態度。"]],"噓寒問暖":[["ㄒㄩ ㄏㄢˊ ㄨㄣˋ ㄋㄨㄢˇ","形容對人的關懷與愛護十分周到。[例]父母對子女每每噓寒問暖，關懷備至。"]],"器量":[["ㄑㄧˋ ㄌㄧㄤˋ","才識度量。[例]器量弘深、器量過人"]],"噪音":[["ㄗㄠˋ ㄧㄣ","振動不規則，聽起來不悅耳的聲音。[例]開車經過學校附近，尤其不能亂按喇叭，製造噪音。"]],"噴嚏":[["ㄆㄣ ㄊㄧˋ","鼻黏膜受了刺激，引起鼻孔急遽噴氣出聲的動作。[例]他剛才淋了雨，現在直打噴嚏，可能感冒了。"]],"嚇一跳":[["ㄒㄧㄚˋ ㄧ ㄊㄧㄠˋ","形容突然受到驚嚇的樣子。[例]三年不見，他的改變真是令人嚇一跳。"]],"嚇阻":[["ㄏㄜˋ ㄗㄨˇ","利用手段使人害怕而停止某種行為。[例]若公權力不彰，即使再多的法規也無法嚇阻犯罪。"]],"嚎啕大哭":[["ㄏㄠˊ ㄊㄠˊ ㄉㄚˋ ㄎㄨ","大聲哭泣。[例]一聽到親人的噩耗，她當場傷心欲絕，嚎啕大哭。"]],"嚮導":[["ㄒㄧㄤˋ ㄉㄠˇ","1.帶路。[例]為了尋找遭遇山難的人，警方特請熟悉山路的原住民在前嚮導。\n2.帶路的人。[例]爬山時，一定要請一位熟悉山路的嚮導帶路。"]],"嚮往":[["ㄒㄧㄤˋ ㄨㄤˇ","思慕而神往。[例]桃花源的生活令人嚮往。"]],"嚴厲":[["ㄧㄢˊ ㄌㄧˋ","嚴格、不寬容。[例]按照規定，失職人員將要接受嚴厲的處罰。"]],"嚴格":[["ㄧㄢˊ ㄍㄜˊ","遵守一定的標準，絕不寬容。[例]學校嚴格規定，禁止學生涉足不正當的場所。"]],"嚴肅":[["ㄧㄢˊ ㄙㄨˋ","1.態度嚴正莊重。[例]他神色嚴肅的訓誡犯錯的學生。\n2.嚴格、認真。[例]他以嚴肅的態度做學問。"]],"嚴重":[["ㄧㄢˊ ㄓㄨㄥˋ","情勢緊急危險、影響很大。[例]事態嚴重、問題嚴重"]],"嚶嚀":[["ㄧㄥ ㄋㄧㄥˊ","形容聲音清脆嬌細。[例]只聽見小嬰兒嚶嚀低哼，還扭動著他的小身軀，模樣真惹人憐。"]],"嚼蠟":[["ㄐㄩㄝˊ ㄌㄚˋ","比喻沒有滋味或樂趣。[例]假如不了解創作背景便來欣賞，那可能會如同嚼蠟般，毫無滋味可言。"]],"囑咐":[["ㄓㄨˇ ㄈㄨˋ","吩咐、叮嚀。[例]天氣冷了，母親囑咐我要加件外套。"]],"囚禁":[["ㄑㄧㄡˊ ㄐㄧㄣˋ","拘押、拘禁。[例]在遭歹徒挾持囚禁三天後，他憑著聰明機智終於逃脫成功。"]],"四周":[["ㄙˋ ㄓㄡ","周圍四面。[例]她最近搬新家，附近四周住的都是親戚朋友。"]],"四四方方":[["ㄙˋ ㄙˋ ㄈㄤ ㄈㄤ","形體方正的樣子。[例]這棟新屋的格局四四方方的，買主感到很滿意。"]],"四季":[["ㄙˋ ㄐㄧˋ","春、夏、秋、冬四時的總稱。[例]這個花園種滿各種花卉，四季都有不同的花朵盛開。"]],"四肢":[["ㄙˋ ㄓ","人體雙手雙腳的總稱。[例]他平常很少運動，跑了一會兒就覺得四肢無力。"]],"四處":[["ㄙˋ ㄔㄨˋ","各處。[例]他不慎遺失了重要文件，急得四處尋找。"]],"回去":[["ㄏㄨㄟˊ ㄑㄩˋ","1.回到原來的地方。[例]今天家裡有事，所以我要提早回去。\n2.俗稱死亡為「回去」。[例]老陳罹患重病，不幸在昨晚回去了。"]],"回國":[["ㄏㄨㄟˊ ㄍㄨㄛˊ","歸返國門。[例]每年十月，都有成千上萬的華僑回國參加雙十國慶的慶典。"]],"回報":[["ㄏㄨㄟˊ ㄅㄠˋ","1.報告或答覆事情的處理情形。[例]警察以無線電向總局回報火災灌救現場的最新狀況。\n2.酬謝、報答。[例]您的救命大恩，只怕我來生也無以回報。"]],"回家":[["ㄏㄨㄟˊ ㄐㄧㄚ","返家。[例]小朋友放學後應該馬上回家，以免家人擔心。"]],"回復":[["ㄏㄨㄟˊ ㄈㄨˋ","1.恢復。[例]自軍中退伍之後，他又回復普通百姓的生活。\n2.回答、答覆。[例]這個問題我先回去仔細思考，明天再給他回復。"]],"回憶":[["ㄏㄨㄟˊ ㄧˋ","1.回想往事。[例]回憶當年攜手走過的歲月，真是有甘有苦。\n2.過去的記憶。[例]在我的回憶中，童年生活就像是一幅永不褪色的圖畫。"]],"回應":[["ㄏㄨㄟˊ ㄧㄥˋ","1.回答他人的問話。[例]他在臺上發問，臺下卻沒人回應。\n2.響應他人的言語、行為。[例]他以具體的行動回應選民對他的支持。"]],"回收":[["ㄏㄨㄟˊ ㄕㄡ","將物品收回再利用。[例]為永續發展，政府大力推廣資源回收，希望民眾都能全力配合。"]],"回歸":[["ㄏㄨㄟˊ ㄍㄨㄟ","返回、歸到。[例]死亡並不可怕，它是一種回歸自然的現象。"]],"回眸":[["ㄏㄨㄟˊ ㄇㄡˊ","回過頭看。[例]回眸一笑"]],"回答":[["ㄏㄨㄟˊ ㄉㄚˊ","答覆、回應。[例]到底天上有多少星星，沒有人能夠回答。"]],"回音":[["ㄏㄨㄟˊ ㄧㄣ","1.回覆的音信。[例]他出國已經三個月了，卻一點兒回音也沒有，教家人好擔心。\n2.回聲。[例]我們在山腰上唱歌，卻從山谷傳來了回音，真是有趣！"]],"因此":[["ㄧㄣ ㄘˇ","連接詞。因而、所以。表示事情的結果。[例]這次學期考試我得了第二名，因此爸爸決定送我一份獎品。"]],"因為":[["ㄧㄣ ㄨㄟˋ","連詞。表示事情的原因。[例]因為途中有車禍塞車，所以才遲到了。"]],"因襲":[["ㄧㄣ ㄒㄧˊ","沿用，繼續使用。[例]漢朝曹參繼蕭何為相，仍因襲黃老無為之治。"]],"困境":[["ㄎㄨㄣˋ ㄐㄧㄥˋ","艱難困苦的處境。[例]長期失業使他的生活陷入困境。"]],"困擾":[["ㄎㄨㄣˋ ㄖㄠˇ","1.為難、煩擾。[例]這個問題困擾他好久，如今總算解決了。\n2.麻煩、難題。[例]他不負責任的態度帶給家人及朋友許多的困擾。"]],"困苦":[["ㄎㄨㄣˋ ㄎㄨˇ","貧困艱苦。[例]非洲饑荒地區的災民過著非常困苦的生活。"]],"困難":[["ㄎㄨㄣˋ ㄋㄢˊ","1.事情複雜或阻礙多，不容易完成。[例]要他同意這件事，恐怕有點困難。\n2.困苦艱難。[例]他不因生活困難而放棄學業。"]],"困頓":[["ㄎㄨㄣˋ ㄉㄨㄣˋ","1.疲倦勞累。[例]不堪長期旅途困頓，他終於病倒了！\n2.生活困苦。[例]現今仍有許多生活困頓的貧戶，亟需社會大眾伸出援手！"]],"固執":[["ㄍㄨˋ ㄓˊ","堅持己見，不肯變通。[例]他還是那麼固執，不肯退讓一步，使得事情無法順利解決。"]],"固定":[["ㄍㄨˋ ㄉㄧㄥˋ","穩定、不移動或不改變。[例]他一直想找個固定的工作。"]],"國君":[["ㄍㄨㄛˊ ㄐㄩㄣ","一國的君主。[例]封建時代的國君，大多以父死子繼的方式承傳君位。"]],"國字":[["ㄍㄨㄛˊ ㄗˋ","本國的文字。[例]教育部委託專家學者研訂國字標準字體。"]],"國歌":[["ㄍㄨㄛˊ ㄍㄜ","由國家制定，代表國家的樂歌。通常於集會、會議或比賽中演奏。[例]聽到國歌時，全體民眾應安靜肅立，以示對國家的尊敬。"]],"國王":[["ㄍㄨㄛˊ ㄨㄤˊ","君主制國家的最高領袖。[例]今天有一些國家的最高領導者仍是國王，像中東的約旦、和鄰近的泰國。"]],"國都":[["ㄍㄨㄛˊ ㄉㄨ","中央政府的所在地。[例]國都往往為一國首善之區。"]],"圍巾":[["ㄨㄟˊ ㄐㄧㄣ","圍在脖子上的長條形領巾。具有保暖、禦寒、裝飾的功用。[例]寒冬出門時，最好能戴條圍巾，以免受凍或感冒。"]],"圍攏":[["ㄨㄟˊ ㄌㄨㄥˇ","圍繞收攏。[例]用餐後，大家圍攏著營火，盡情的唱歌跳舞。"]],"圍棋":[["ㄨㄟˊ ㄑㄧˊ","一種棋藝。相傳為堯所發明。棋盤上縱橫各有十九道線，相互交錯成三百六十一個點，雙方分持黑白棋子著於點上，用以圍攻對方。凡被包圍而無活路者，則為對方所吃。最後再視所占之點的多寡來決定勝負。[例]閒來無事時，哥哥喜歡和朋友下圍棋。　△大棋"]],"圍爐":[["ㄨㄟˊ ㄌㄨˊ","1.圍坐在火爐四周。[例]在這寒夜，大家能圍爐聚談，可真是人生一大樂事！\n2.特指除夕夜一家人的團聚。[例]不管交通多麼壅塞，我還是一定得趕回家圍爐。"]],"圍牆":[["ㄨㄟˊ ㄑㄧㄤˊ","圍繞在四周，用來劃分界限的牆壁。通常用磚頭、水泥、鐵欄或竹籬做成。[例]貓兒的動作靈活，咻的一下便跳過圍牆了。"]],"圍籬":[["ㄨㄟˊ ㄌㄧˊ","圍繞某區域，使之與外界隔開的籬笆。[例]爺爺在後院做了一道圍籬，以防止家禽跑出去。"]],"圍繞":[["ㄨㄟˊ ㄖㄠˋ","包圍環繞。[例]大家議論紛紛，話題全都圍繞在近日公布的人事命令上。"]],"圍裙":[["ㄨㄟˊ ㄑㄩㄣˊ","工作時圍在身前的裙子。多用布或橡膠製成，可避免弄髒衣服。[例]媽媽先穿好圍裙之後才上廚房做菜。　◎"]],"圍觀":[["ㄨㄟˊ ㄍㄨㄢ","圍聚觀看。[例]由於民眾在火場圍觀，阻礙了消防隊員的救火行動。"]],"園丁":[["ㄩㄢˊ ㄉㄧㄥ","管理園圃，培植花木的人。[例]這座花圃在園丁辛勤的培植下，已開滿了各種香花。"]],"園區":[["ㄩㄢˊ ㄑㄩ","泛指各種活動場地的範圍。[例]主辦單位在展示園區內備有說明書，歡迎民眾踴躍索取。"]],"圓弧":[["ㄩㄢˊ ㄏㄨˊ","圓周中的任何一段。[例]她笑時嘴角上揚，形成一道圓弧，非常可愛。"]],"圓形":[["ㄩㄢˊ ㄒㄧㄥˊ","以定點為圓心，任意長為半徑所畫成的圖形。[例]妹妹在紙上畫了一個圓形，說是天上的月亮。　◎"]],"圓桌":[["ㄩㄢˊ ㄓㄨㄛ","桌面圓形的桌子。[例]除夕夜時全家人圍著圓桌吃年夜飯，氣氛十分溫馨。"]],"圓鼓鼓":[["ㄩㄢˊ ㄍㄨˇ ㄍㄨˇ","渾圓而凸起的樣子。[例]河豚一受到驚擾，身體就會脹得圓鼓鼓的。"]],"圖書館":[["ㄊㄨˊ ㄕㄨ ㄍㄨㄢˇ","將各種圖書、資料加以蒐集、分類、保存，供群眾閱覽參考的專門機構。[例]為了寫報告，他每天都到圖書館蒐集資料。"]],"圖案":[["ㄊㄨˊ ㄢˋ","由色彩或線條構成且能引發美感的圖形。[例]這件洋裝的圖案鮮明，穿在她身上更顯得青春洋溢。"]],"圖片":[["ㄊㄨˊ ㄆㄧㄢˋ","圖畫、照片、拓片等的統稱。[例]這本雜誌時常刊登各國的旅遊圖片，即使讀者不出遊也能飽覽各國風光。"]],"圖畫":[["ㄊㄨˊ ㄏㄨㄚˋ","以線條、色彩繪成的畫。[例]牆上掛了一幅弟弟精心描繪的圖畫。"]],"團圓":[["ㄊㄨㄢˊ ㄩㄢˊ","親屬團聚。[例]經過多年的找尋，王老伯終於和失散的親人團圓了。"]],"團結":[["ㄊㄨㄢˊ ㄐㄧㄝˊ","聚集結合眾人的力量。[例]當公司遇上營運困難時，全體員工應該更團結、更賣力，才能幫助公司度過難關。"]],"團聚":[["ㄊㄨㄢˊ ㄐㄩˋ","團圓聚集。[例]現代人工作繁忙，只有在春節時才能全家團聚，共享短暫的天倫之樂。"]],"團隊":[["ㄊㄨㄢˊ ㄉㄨㄟˋ","團體、隊伍。[例]團隊組織、團隊精神"]],"團體":[["ㄊㄨㄢˊ ㄊㄧˇ","具有共同目標的人群所結合而成的集團或組織。[例]政治團體、商業團體"]],"土丘":[["ㄊㄨˇ ㄑㄧㄡ","小土山。[例]為使地形富於變化，設計師在公園規劃了許多座土丘。"]],"土地":[["ㄊㄨˇ ㄉㄧˋ","1.田地，有土壤的地面。[例]土地遼闊、土地肥沃、土地改革\n2.疆域。[例]所謂國家，必須具有土地、人民和主權等三要素。\n3.→土地公"]],"土堆":[["ㄊㄨˇ ㄉㄨㄟ","高出地面的積土。[例]孩子們在土堆上玩得不亦樂乎。"]],"土壤":[["ㄊㄨˇ ㄖㄤˇ","覆蓋在地殼最外圍的一層土質，由土粒與腐植質混合而成。其中含有水分、空氣、礦物質和微生物，可供植物生長與動物棲息。[例]土壤、空氣和水是植物生長不可或缺的三要素。"]],"土狗":[["ㄊㄨˇ ㄍㄡˇ","1.原產於本地的狗。[例]根據研究，臺灣土狗是智慧極高、耐力又佳的狗種。\n2.→螻蛄"]],"土狼":[["ㄊㄨˇ ㄌㄤˊ","→鬣狗"]],"在乎":[["ㄗㄞˋ ㄏㄨ","在意、關心。[例]他總是我行我素，從不在乎別人的眼光。"]],"在家":[["ㄗㄞˋ ㄐㄧㄚ","1.居於家中。[例]在家靠父母，出外靠朋友。\n2.佛教指過世俗生活。相對於出家而言。[例]在家修佛，以早上、晚上為宜，身心清淨輕鬆，才能專注虔誠。"]],"地上":[["ㄉㄧˋ ㄕㄤˋ","地面上。[例]請把地上的紙屑撿起來。"]],"地下室":[["ㄉㄧˋ ㄒㄧㄚˋ ㄕˋ","建築物底部位於地面下的空間。通常用來儲存物品或停放車輛，空襲時可作緊急避難之用。[例]現代的高樓大廈大都把地下室闢為停車場。"]],"地主之誼":[["ㄉㄧˋ ㄓㄨˇ ㄓ ㄧˋ","本地主人應盡的招待情誼。[例]你難得到鄉下來，就讓我盡盡地主之誼吧！"]],"地勢":[["ㄉㄧˋ ㄕˋ","地面高低起伏的形勢。[例]地勢陡峭、地勢平坦"]],"地圖":[["ㄉㄧˋ ㄊㄨˊ","說明地表自然景觀和人文現象分布情況的圖形。圖上標有符號、文字等，或著上不同的顏色用以識別。[例]地圖是地理教學重要的輔助教具。"]],"地方":[["ㄉㄧˋ ㄈㄤ","1.區域、地區。[例]中部地方\n2.本地、當地。[例]地方人士、地方新聞\n3.省、縣等自治單位。相對於國家或中央政府而言。[例]地方稅、地方政府、地方自治\n4.處所、地點。[例]你從什麼地方來啊？\n5.某部分。[例]他的構想不錯，但有些地方值得商議。"]],"地標":[["ㄉㄧˋ ㄅㄧㄠ","1.用來標示界線位置的目標物。[例]縣政府常以石碑作為兩個鄉鎮交界的地標。\n2.地區景觀上突出的特徵。[例]中正紀念堂稱得上是臺北市的地標。"]],"地殼":[["ㄉㄧˋ ㄎㄜˊ","地球的表層部分。主要由堅硬的岩石組成。陸地部分厚約35公里，以花崗岩為主；海洋部分厚約5公里，以玄武岩為主。[例]矽酸鹽是構成地殼的主要成分。"]],"地毯":[["ㄉㄧˋ ㄊㄢˇ","鋪在地面上的毯子，多為毛織物，亦有用棉、麻等質料製成。[例]這張色彩鮮麗的地毯，將大廳襯得華麗無比。"]],"地洞":[["ㄉㄧˋ ㄉㄨㄥˋ","在地面下挖成的洞。[例]生活在地洞中的動物，通常有較敏銳的聽覺。"]],"地雷":[["ㄉㄧˋ ㄌㄟˊ","一種埋在土中，內裝炸藥，鑄以金屬外殼，安上引發裝置，使人員、車輛等因碰觸而引發爆炸，造成殺傷及破壞效果的武器。[例]他因誤觸地雷而被炸成重傷。"]],"地震":[["ㄉㄧˋ ㄓㄣˋ","由地球內部變動所引起的地殼位移。[例]地震時，要儘速逃往空地，或躲到牆角、桌下。"]],"地面":[["ㄉㄧˋ ㄇㄧㄢˋ","1.地球表面。[例]飛機升空之前，必須先在地面滑行。\n2.地板。[例]現在的房子很少用磨石地面，大部分都改用磁磚。"]],"均衡":[["ㄐㄩㄣ ㄏㄥˊ","均等、平衡。[例]每天攝取均衡的營養，才能常保身體的健康。"]],"坍塌":[["ㄊㄢ ㄊㄚ","崩壞倒塌。[例]建築工地的鷹架突然坍塌，工人死傷慘重。"]],"坎坷":[["ㄎㄢˇ ㄎㄜˇ","比喻人潦倒不得志。[例]他雖然命運坎坷，但仍以無比的信心與毅力，戰勝所有的逆境。"]],"坐下":[["ㄗㄨㄛˋ ㄒㄧㄚˋ","將臀部靠在地面、座位等。[例]他太累了，所以一坐下就睡著了。"]],"坐車":[["ㄗㄨㄛˋ ㄔㄜ","乘車、搭車。[例]從火車站坐車到學校，需要半個小時的車程。"]],"坐鎮":[["ㄗㄨㄛˋ ㄓㄣˋ","本指駐地鎮守。後比喻停駐在固定地點掌理事務或控制局勢。[例]總幹事到競選總部親自坐鎮，督導選務工作。"]],"坑洞":[["ㄎㄥ ㄉㄨㄥˋ","凹陷的洞穴。[例]連日豪雨淘空路基，形成一個大坑洞，過往人車極為危險，交通單位緊急封閉道路。"]],"坑道":[["ㄎㄥ ㄉㄠˋ","地面以下的通道。如為採礦而挖掘的地道。[例]聽說這座坑道是日軍在二次大戰時所挖的戰備道。"]],"坡道":[["ㄆㄛ ㄉㄠˋ","傾斜的道路。[例]前面是坡道，請減速慢行。"]],"坦然":[["ㄊㄢˇ ㄖㄢˊ","內心安寧舒泰的樣子。[例]只要問心無愧，就能坦然面對一切。"]],"坦率":[["ㄊㄢˇ ㄕㄨㄞˋ","坦白真率，不虛偽造作。[例]他個性坦率，又講義氣，所以大家都樂於和他交往。"]],"坦白":[["ㄊㄢˇ ㄅㄞˊ","率直真誠，毫無隱瞞。[例]他把事實坦白的說了出來，讓大家了解真相。"]],"垂危":[["ㄔㄨㄟˊ ㄨㄟˊ","1.瀕臨危險。[例]垂危之際，幸援軍及時趕到。\n2.將近死亡。[例]生命垂危的病人，希望能再見親屬最後一面。"]],"垂憐":[["ㄔㄨㄟˊ ㄌㄧㄢˊ","對他人關愛、憐惜。[例]這個孤兒身世淒苦，因而老奶奶對他特別垂憐。"]],"垂掛":[["ㄔㄨㄟˊ ㄍㄨㄚˋ","懸掛。[例]風鈴垂掛在窗前，微風一來，叮噹作響，甚是悅耳。"]],"垂直":[["ㄔㄨㄟˊ ㄓˊ","數學上指兩條直線、兩個平面或一直線與一平面以直角相交。[例]同一平面上的兩條直線垂直必有一個交點。"]],"垂落":[["ㄔㄨㄟˊ ㄌㄨㄛˋ","從上面直落下來。[例]繁茂的長春藤從二樓窗口垂落到地面，使這棟房子綠意盎然。"]],"垂頭喪氣":[["ㄔㄨㄟˊ ㄊㄡˊ ㄙㄤˋ ㄑㄧˋ","形容意志消沉的樣子。[例]我們應該積極樂觀，克服一切困難，千萬不可一遇挫折，就垂頭喪氣，灰心失志。"]],"垃圾":[["ㄌㄜˋ ㄙㄜˋ","1.各種廢棄物的統稱。[例]隨意傾倒垃圾是沒有公德心且不合法的行為。　_x000D_\n2.比喻沒用或會產生不良影響的人、事、物。[例]適度傾吐，把心裡的垃圾倒出來，有助於改善心情。"]],"垃圾桶":[["ㄌㄜˋ ㄙㄜˋ ㄊㄨㄥˇ","裝盛垃圾的容器。[例]在公眾出入的場所，應放置容積大的垃圾桶。"]],"垮臺":[["ㄎㄨㄚˇ ㄊㄞˊ","比喻事業、權勢或團體瓦解、潰敗。[例]由於經濟不景氣，再加上資金調度不易，使得這家公司垮臺了。"]],"埋伏":[["ㄇㄞˊ ㄈㄨˊ","暗中躲藏，伺機突擊敵人。[例]我軍埋伏了大批兵力，準備一舉殲滅入侵的敵寇。"]],"埋怨":[["ㄇㄢˊ ㄩㄢˋ","抱怨、責怪。[例]面對困境，與其百般埋怨，不如設法克服。"]],"埋頭":[["ㄇㄞˊ ㄊㄡˊ","形容集中精神，專心致力於一件事。[例]他成天埋頭於工作，幾乎沒有休閒娛樂。"]],"城堡":[["ㄔㄥˊ ㄅㄠˇ","城池堡壘。[例]歐洲有許多古代留下來的城堡，值得我們一遊！　◎"]],"城市":[["ㄔㄥˊ ㄕˋ","街道寬廣、人口密集，有繁盛商業的地方。相對於鄉村而言。[例]她剛從鄉下到這個城市來謀生，一切都還不熟悉。"]],"城鎮":[["ㄔㄥˊ ㄓㄣˋ","城市和鄉鎮。[例]為了國家進步繁榮，政府不斷建設各個城鎮。"]],"城門":[["ㄔㄥˊ ㄇㄣˊ","城牆的出入口。[例]吳三桂打開城門引清兵入關，導致明朝的滅亡。"]],"埡口":[["ㄧㄚˋ ㄎㄡˇ","狹窄的山口。[例]根據山友的經驗，許多高山埡口都是容易形成雲海的地方。"]],"執政":[["ㄓˊ ㄓㄥˋ","執掌政權。[例]國家若由賢者執政，必能使人民過著安定繁榮的生活。"]],"執法":[["ㄓˊ ㄈㄚˇ","執行法律。[例]他執法甚嚴，從不接受關說。"]],"執著":[["ㄓˊ ㄓㄨㄛˊ","泛指堅持某一觀點而不改變。[例]本著對舞蹈的執著，她日夜苦練從不以為苦。"]],"培植":[["ㄆㄟˊ ㄓˊ","1.栽種植物。[例]父親總是細心的培植庭院裡的一花一木。\n2.培養、扶植。[例]培植人才、培植勢力"]],"培育":[["ㄆㄟˊ ㄩˋ","培植養育。[例]培育英才、培育新品種"]],"培養":[["ㄆㄟˊ ㄧㄤˇ","1.長期策劃和訓練。[例]培養人才、培養信心\n2.在適宜的環境中培植養育。[例]培養細菌、培養新品種"]],"基督教":[["ㄐㄧ ㄉㄨ ㄐㄧㄠˋ","西元一世紀由巴勒斯坦境內拿撒勒人耶穌所創立的宗教，初期流行於亞細亞西部，現遍及世界。十一世紀分裂為天主教和東正教，十六世紀宗教改革後又從天主教分裂出許多新教派，如長老會、聖公會、浸信會、衛理會等。我國統稱新教為「基督教」。"]],"基礎":[["ㄐㄧ ㄔㄨˇ","房屋的基址和柱腳的礎石。引申為事物的根本。[例]無論做什麼事，都要將基礎打穩，才能更上一層樓。"]],"基金會":[["ㄐㄧ ㄐㄧㄣ ㄏㄨㄟˋ","為興辦、發展某種事業或活動而組成的團體。資金來源可經由社會募捐或工商業界出資等方式取得。人員有的採固定編制，有些則是義務性協助。[例]防癌基金會、兒童燙傷基金會、消費者文教基金會"]],"堂妹":[["ㄊㄤˊ ㄇㄟˋ","稱謂。用以稱伯叔的女兒中年歲比自己小者。[例]每逢暑假，叔叔都會送堂妹去參加夏令營，以培養她獨立自主的能力。　◎"]],"堅信":[["ㄐㄧㄢ ㄒㄧㄣˋ","深信不疑。[例]他堅信只要不斷努力，就一定會實現理想。"]],"堅固":[["ㄐㄧㄢ ㄍㄨˋ","強韌牢固。[例]這座橋梁經過專家精心設計，建造得非常堅固。"]],"堅定":[["ㄐㄧㄢ ㄉㄧㄥˋ","強毅不動搖。[例]他態度堅定，不為威武所屈。"]],"堅強":[["ㄐㄧㄢ ㄑㄧㄤˊ","堅定剛強，不易動搖或摧毀。[例]他的個性堅強，從不輕易屈服。"]],"堅持":[["ㄐㄧㄢ ㄔˊ","執意堅決。[例]凡事堅持到底，必能獲得最後勝利。"]],"堅硬":[["ㄐㄧㄢ ㄧㄥˋ","堅實強硬。[例]胡桃的果實外殼堅硬，很難用手剝開。"]],"堅韌":[["ㄐㄧㄢ ㄖㄣˋ","物體有韌性不易毀損。[例]這條繩子，堅韌無比，十分耐用。"]],"堆砌":[["ㄉㄨㄟ ㄑㄧˋ","1.將物體層疊累積。[例]這是小弟用積木堆砌起來的城堡。\n2.在文章中使用大量華麗而與內容無關的詞藻。[例]這篇文章犯堆砌的毛病。"]],"堆積":[["ㄉㄨㄟ ㄐㄧ","聚積堆高。[例]那塊空地堆積了很多垃圾，導致蚊蠅孳生，腐臭難聞。"]],"堆置":[["ㄉㄨㄟ ㄓˋ","堆積放置。[例]這批貨堆置這麼久了，還是賣不出去。"]],"堤防":[["ㄊㄧˊ ㄈㄤˊ","在岸邊、港口以土、石等堆築成的建築物。有防止洪水氾濫、波浪侵蝕或泥沙淤積等作用。[例]縣府決定加高沿海低窪地的堤防，以防海水倒灌。"]],"堪慮":[["ㄎㄢ ㄌㄩˋ","足以令人憂心、煩惱。[例]這間療養院正面臨經費缺乏、人手不足的困境，情況堪慮。"]],"堪稱":[["ㄎㄢ ㄔㄥ","足以稱為。[例]這位師傅的糕餅手藝堪稱業界翹楚，吸引許多老饕慕名前來購買。"]],"報仇":[["ㄅㄠˋ ㄔㄡˊ","對傷害自己的人進行反擊。[例]他現在一心想報仇，早已無法冷靜的思考。"]],"報告":[["ㄅㄠˋ ㄍㄠˋ","1.陳述，一般多為下對上。[例]這件事我必須向老師報告。\n2.報告的言語內容或文書。[例]口頭報告、讀書報告、檢驗報告\n3.應用文的一種。用於下級人員向上級陳述時。[例]公司員工曠職，必須向主管上一份報告，說明理由。"]],"報復":[["ㄅㄠˋ ㄈㄨˋ","對傷害自己的人進行反擊。[例]他好不容易把報復的念頭壓下，你就別再火上添油了！"]],"報恩":[["ㄅㄠˋ ㄣ","報答恩惠。[例]他成功後返回母校報恩，設置獎學金以鼓勵學弟妹。"]],"報紙":[["ㄅㄠˋ ㄓˇ","用一定的名稱，按期發行，報導政治、經濟、社會、文化等各類新聞的散頁出版品。一般分為日報與晚報。[例]多看報紙能增廣見聞。　△新聞紙"]],"報酬":[["ㄅㄠˋ ㄔㄡˊ","對出力者所提供的酬資、回饋。[例]適當的報酬，可以鼓勵人更加努力的工作。"]],"場地":[["ㄔㄤˇ ㄉㄧˋ","為某種需要而設立的地方或空地。[例]校方同意將體育館借給我們做為舉行茶會的場地。"]],"塊莖":[["ㄎㄨㄞˋ ㄐㄧㄥ","植物的地下莖呈塊狀者，如馬鈴薯、菊芋等。可分割成數塊，供繁殖新個體使用。　◎"]],"塌陷":[["ㄊㄚ ㄒㄧㄢˋ","下陷。[例]連續的大雨使得多處山石塌陷，交通受阻。"]],"塑像":[["ㄙㄨˋ ㄒㄧㄤˋ","1.以黏土、石膏、蠟或金屬等材料塑造而成的人或物的形象。[例]矗立在公園的藝術塑像成為這個城市的地標。_x000D_\n2.利用黏土、石膏、蠟或金屬等材料塑造人或物的形象。[例]為了找尋可用來塑像的好泥土，他幾乎跑遍了世界各地。"]],"塑膠":[["ㄙㄨˋ ㄐㄧㄠ","一種人工合成的有機化合物。主要原料有聚乙烯、聚氯乙烯等。有耐腐蝕、可塑性高等特質。廣泛應用於各種器材製作。[例]廉價耐用的塑膠製品，雖然為生活帶來不少便利，但也因難以分解，而產生了不少棘手的環保問題。"]],"塗抹":[["ㄊㄨˊ ㄇㄛˇ","1.劃掉、抹去。[例]考試時最好保持試卷的乾淨整齊，不要隨便用筆塗抹錯誤。\n2.隨意圖畫、信筆揮灑。[例]弟弟拿著彩色筆在圖畫紙上隨意塗抹。\n3.化妝。[例]國劇中的旦角上戲之前總得在臉上大肆塗抹一番。"]],"塗改":[["ㄊㄨˊ ㄍㄞˇ","塗抹文字，加以修改。[例]損益表的各項金額都有收據核對，不可任意塗改。"]],"塗鴉":[["ㄊㄨˊ ㄧㄚ","本指幼兒不懂事，亂塗詩書，黑色如鴉。後比喻隨意書寫，或謙稱自己的作品水準不夠。語本唐．盧仝〈示添丁〉詩。[例]當初我只是隨便塗鴉，沒想到會被報社採用。"]],"塞住":[["ㄙㄞ ㄓㄨˋ","封堵。[例]由於下水道被淤泥塞住，所以積水不退。"]],"塞車":[["ㄙㄞ ㄔㄜ","車輛擁擠所造成的交通阻塞。[例]由於主要幹道正在施工，因而導致附近道路嚴重塞車。"]],"填充":[["ㄊㄧㄢˊ ㄔㄨㄥ","補入、充塞。[例]冷媒不夠時就必須再填充，冰箱才能維持一定的冷度。"]],"塵土":[["ㄔㄣˊ ㄊㄨˇ","細小的灰土。[例]塵土沖天、塵土飛揚"]],"塵垢":[["ㄔㄣˊ ㄍㄡˋ","塵土汙垢。[例]這裡久無人居，覆滿了塵垢。"]],"塵埃":[["ㄔㄣˊ ㄞ","塵土。[例]雨後的路面沒有塵埃飛揚，空氣格外清新。"]],"墊子":[["ㄉㄧㄢˋ ˙ㄗ","用來墊襯的東西。[例]椅墊子、沙發墊子"]],"增值":[["ㄗㄥ ㄓˊ","與原有的價格相比而有所提高。[例]經濟景氣，連帶的房地產也增值得很快。"]],"增加":[["ㄗㄥ ㄐㄧㄚ","增添、加多。[例]神話故事雖然不一定可信，卻為我們的生活增加了許多趣味。"]],"增添":[["ㄗㄥ ㄊㄧㄢ","加添。[例]真不好意思，給您增添了許多麻煩！"]],"墨寶":[["ㄇㄛˋ ㄅㄠˇ","稱珍貴的字畫作品或尊稱他人的字畫作品。[例]這幅字是國父親筆的墨寶，十分珍貴。"]],"墨痕":[["ㄇㄛˋ ㄏㄣˊ","著墨的痕跡。[例]這字墨痕猶新，才寫不久。"]],"墨綠":[["ㄇㄛˋ ㄌㄩˋ","深綠色。[例]夕陽西墜，山色轉為墨綠。"]],"墨跡":[["ㄇㄛˋ ㄐㄧ","手寫所留的原本。也指書畫的真跡。[例]這些歷代名人的墨跡，都是稀世珍寶。"]],"墳墓":[["ㄈㄣˊ ㄇㄨˋ","埋葬死人的地方。[例]清明時節，家家都扶老攜幼去祭掃祖先的墳墓。"]],"壁虎":[["ㄅㄧˋ ㄏㄨˇ","動物名。爬蟲類有鱗目蜥蜴亞目。脊部色灰暗，身體扁平，四腳上有吸盤，能游行於天花板或直立的牆壁上。[例]壁虎的尾部尖長，遇到敵襲時常自斷逃生。　◎"]],"壓住":[["ㄧㄚ ㄓㄨˋ","1.以物品覆蓋其上。[例]風太大了！拿本書把桌上的紙張壓住吧！\n2.制止、抵擋。[例]他的氣焰過於囂張，幾乎沒有人能壓住他。"]],"壓力":[["ㄧㄚ ㄌㄧˋ","1.物體上所承受的作用力。[例]高山上的大氣壓力比平地小，空氣也較稀薄。\n2.個體生理或心理上感受到威脅時所引起的一種緊張不安的狀態，使人在情緒上產生不愉快或痛苦的感受。[例]適度的壓力往往可以鞭策自己，激發潛能。\n3.逼人的威勢。[例]國際間弱肉強食，大國往往對小國施加壓力。"]],"壓歲錢":[["ㄧㄚ ㄙㄨㄟˋ ㄑㄧㄢˊ","農曆除夕時，長輩給晚輩的錢。有為對方求福求壽的意思。[例]他將每一年收到的壓歲錢存起來，數目頗為可觀。"]],"壓軸":[["ㄧㄚ ㄓㄡˊ","戲劇的最後一齣稱大軸，大軸前一齣稱壓軸。比喻最精彩、最引人注目的節目或事件。[例]今晚的壓軸即將隆重登場，請大家拭目以待。　△壓軸戲"]],"壞話":[["ㄏㄨㄞˋ ㄏㄨㄚˋ","有關他人是非長短的不實言談。[例]他從不說別人的壞話，且處處與人為善，人緣甚佳。"]],"士兵":[["ㄕˋ ㄅㄧㄥ","軍隊中基層的戰士。目前我國軍中士兵分為上等兵、一等兵、二等兵等。[例]士兵們正在靶場上進行射擊訓練。"]],"壯烈":[["ㄓㄨㄤˋ ㄌㄧㄝˋ","英勇慘烈。[例]在戰場上壯烈犧牲的將士，是最令人敬佩的愛國典範。"]],"壯膽":[["ㄓㄨㄤˋ ㄉㄢˇ","增加勇氣、膽量。[例]弟弟怕黑，晚上上廁所時得找人壯膽。"]],"壽司":[["ㄕㄡˋ ㄙ","一種日本料理。在剛蒸熟的飯中，放入醋、糖、鹽等調味料，攪拌均勻，使之冷卻。然後在細竹簾上先鋪一層海苔皮或豆皮，鋪上一層飯後，再鋪上生魚片、漬菜、炒蛋等食品，最後再壓緊成筒狀，切成小塊食用。§日すし[例]壽司是最大眾化的日本料理。"]],"夏天":[["ㄒㄧㄚˋ ㄊㄧㄢ","一年四季中的第二個季節。[例]夏天一到，海水浴場處處可見戲水的人潮。"]],"夕陽":[["ㄒㄧˋ ㄧㄤˊ","1.傍晚時將西下的太陽。[例]夕陽西下，斷腸人在天涯。（元．馬致遠〈天淨沙．枯藤老樹昏鴉〉曲）_x000D_\n2.比喻沒落。[例]夕陽工業"]],"外側":[["ㄨㄞˋ ㄘㄜˋ","靠外面的一邊。[例]每逢下課，教室外側的走廊到處可見三五成群的學生。"]],"外公":[["ㄨㄞˋ ㄍㄨㄥ","稱謂。對媽媽的父親的稱呼，今亦稱「阿公」。[例]外公從小就教導我們要正正當當的做人。　△外祖父"]],"外圍":[["ㄨㄞˋ ㄨㄟˊ","1.圍繞於事物中心四周的部分。[例]通常城堡的外圍都掘有護城河，以加強防禦。\n2.比喻環繞在權力中心四周的。[例]總公司若沒有外圍這些分公司的支撐，無法持續發展。"]],"外套":[["ㄨㄞˋ ㄊㄠˋ","在平常服裝外面所加的禦寒衣物，稱為「外套」。[例]最近天氣寒冷，出門別忘了加件外套。"]],"外孫":[["ㄨㄞˋ ㄙㄨㄣ","稱謂：(1) 對女兒的子女的稱呼，今亦稱「孫子」。(2) 對女兒的兒子的稱呼，今亦稱「孫子」。"]],"外形":[["ㄨㄞˋ ㄒㄧㄥˊ","外在的形貌。[例]她的外形突出，演技精湛，天生就是當演員的料子。"]],"外面":[["ㄨㄞˋ ㄇㄧㄢˋ","外頭、外部。[例]他從小就離開了家，一個人在外面讀書求學。"]],"多久":[["ㄉㄨㄛ ㄐㄧㄡˇ","1.詢問時間的長短。[例]你們認識多久了？\n2.指一段時間。通常與否定詞「不」、「沒有」等連用，表示時間不長。[例]要不了多久，他就會知難而退的。\n3.多麼久。指一段長時間。[例]無論多久，我都願意等待。"]],"多元":[["ㄉㄨㄛ ㄩㄢˊ","多種樣式、面向。[例]現在想進大學讀書，除了考試之外，還有多元入學的各種管道。"]],"多半":[["ㄉㄨㄛ ㄅㄢˋ","1.大多數、大部分。[例]這次的活動多半是由小李負責設計、籌劃。\n2.可能、大概。[例]看他每天累的這個樣子，多半是照顧患病的媽媽吧！"]],"多少":[["ㄉㄨㄛ ㄕㄠˇ","1.若干。指數量。[例]老師請班長調查有多少學生要參加畢業旅行。\n2.或多或少。[例]不要以為這本書只是簡介的性質，它對我們多少是有幫助的。"]],"多數":[["ㄉㄨㄛ ㄕㄨˋ","超過半數以上的數目。[例]這次旅遊活動，班上多數同學都贊成去合歡山。"]],"多管閒事":[["ㄉㄨㄛ ㄍㄨㄢˇ ㄒㄧㄢˊ ㄕˋ","踰越本分，插手別人的事情。[例]他已經表明這件事由他自行處理，大家又何必多管閒事呢？"]],"多采多姿":[["ㄉㄨㄛ ㄘㄞˇ ㄉㄨㄛ ㄗ","形容姿態多樣，色彩迷人。後引申為內容豐富華麗，且變化多端。[例]他的生涯多采多姿，令人羨慕！"]],"多餘":[["ㄉㄨㄛ ㄩˊ","1.剩下來的。[例]同學們決議將此次活動多餘的經費，全部歸為班費。\n2.不必要的。[例]這話是多餘的。"]],"夜晚":[["ㄧㄝˋ ㄨㄢˇ","夜裡、晚上。[例]臺北市的夜晚，每每燈火通明，彷如白晝。"]],"夢幻":[["ㄇㄥˋ ㄏㄨㄢˋ","不切實際的夢境、幻覺。[例]這番奇遇猶如一場夢幻。"]],"夥伴":[["ㄏㄨㄛˇ ㄅㄢˋ","同伴。[例]他是我們登山的夥伴，幾乎每個禮拜天都一起去爬山。"]],"夥計":[["ㄏㄨㄛˇ ㄐㄧˋ","受人僱用，替人做事的人。[例]這個夥計做事勤快，腦筋又好，深得老闆器重。"]],"大人":[["ㄉㄚˋ ㄖㄣˊ","1.對父母或長上的尊稱，多用於書信。[例]父親大人、母親大人\n2.對權貴或官吏的稱呼。[例]知府大人、縣官大人\n3.成年人。相對於小孩而言。[例]大人們應以身作則遵守公共道德，作為小孩的典範。"]],"大使":[["ㄉㄚˋ ㄕˇ","派駐在邦交國，代表國家與一國元首處理外交事務的最高官員。"]],"大俠":[["ㄉㄚˋ ㄒㄧㄚˊ","武藝高超、名聲響亮的俠士。[例]古典小說裡的大俠，都有仗義扶弱的風範。"]],"大刀":[["ㄉㄚˋ ㄉㄠ","一種單刃厚背的兵器。[例]他耍大刀的精彩演出深獲觀眾的好評。　◎"]],"大剌剌":[["ㄉㄚˋ ㄌㄚˋ ㄌㄚˋ","大模大樣。[例]即使被上司罵得狗血淋頭，他還是一副大剌剌的模樣，根本就不在乎。"]],"大力士":[["ㄉㄚˋ ㄌㄧˋ ㄕˋ","力量很大的人。[例]他力能扛鼎，是個不折不扣的大力士。"]],"大哥":[["ㄉㄚˋ ㄍㄜ","1.稱謂。稱兄弟中年紀最長者。[例]在所有的兄弟姊妹中，就數大哥最疼我。\n2.尊稱同輩中年紀較長的男性。[例]他因入學晚了幾年，平時又挺照顧同學的，所以我們都叫他大哥。"]],"大哭":[["ㄉㄚˋ ㄎㄨ","大聲的哭，聲淚俱下。形容哭得非常厲害。[例]一看見心愛的玩具被弄得七零八落的，小男孩立即放聲大哭。"]],"大地":[["ㄉㄚˋ ㄉㄧˋ","整個地面。[例]春回大地"]],"大夫":[["ㄉㄞˋ ㄈㄨ","醫生。[例]王大夫仁心仁術，深受病人愛戴。"]],"大嫂":[["ㄉㄚˋ ㄙㄠˇ","稱謂：(1) 用以稱大哥的妻子。[例]大哥總在年初二陪大嫂回娘家。　(2) 稱呼較年長朋友的太太。[例]今天的聚會全讓大嫂一人張羅，真是打擾了。"]],"大家":[["ㄉㄚˋ ㄐㄧㄚ","1.眾人。[例]大家好、大家一起來\n\t\n2.世家望族。[例]大家閨秀、大家風範\n\t\n3.著名的專家。[例]唐宋古文八大家"],["ㄉㄚˋ ㄍㄨ","古時對女子的尊稱。[例]世稱漢代班昭為曹大家。"]],"大富翁":[["ㄉㄚˋ ㄈㄨˋ ㄨㄥ","1.非常富有的人。[例]他希望有朝一日能成為世界數一數二的大富翁。\n2.一種紙上遊戲。幾個人輪流擲色子，依擲出的點數決定可走的步數，在前進中獲得財產或失去財產，遊戲結束時以擁有最多財產的人為勝利者。[例]閒暇時，他喜歡和三五好友玩大富翁消遣。"]],"大將":[["ㄉㄚˋ ㄐㄧㄤˋ","1.統率軍隊的高階將領。[例]因為手下有英勇善戰的大將，使他很快就登上王位。\n2.比喻團體中技藝高超，足以擔當重任的人。[例]我方球隊擁有多名大將，冠軍應是非我莫屬了。"]],"大小":[["ㄉㄚˋ ㄒㄧㄠˇ","1.尊卑或長幼。[例]我們全家大小共有十口之多。\n\t\n2.尺寸。[例]這雙鞋的大小，剛好適合我的腳。\n\t\n3.重要與不重要的。泛指一切事務。[例]她是個能幹的家庭主婦，大小家事都打理得很好。"]],"大展身手":[["ㄉㄚˋ ㄓㄢˇ ㄕㄣ ㄕㄡˇ","極力的展現技藝或特長。[例]這次的兒童繪畫比賽，讓所有愛畫畫的小孩都有大展身手的機會。"]],"大庭廣眾":[["ㄉㄚˋ ㄊㄧㄥˊ ㄍㄨㄤˇ ㄓㄨㄥˋ","人多而公開的場合。[例]他常在大庭廣眾間高談闊論，以吸引他人的目光。"]],"大快朵頤":[["ㄉㄚˋ ㄎㄨㄞˋ ㄉㄨㄛˇ ㄧˊ","指愉快地咀嚼食物的樣子。[例]媽媽煮了滿桌的好菜，我又可以大快朵頤了。"]],"大房":[["ㄉㄚˋ ㄈㄤˊ","家族的長房。[例]在以往的觀念中，大房在家族中的地位比較高，但擔負的責任相對也比較大。"]],"大掃除":[["ㄉㄚˋ ㄙㄠˇ ㄔㄨˊ","大規模或大範圍的打掃環境。[例]年終大掃除、歲末大掃除"]],"大會舞":[["ㄉㄚˋ ㄏㄨㄟˋ ㄨˇ","運動會的一項表演節目。通常是由一群經過舞蹈訓練的人，從事舞蹈表演。[例]這次運動會的大會舞，是由蝴蝶舞蹈社負責設計籌劃的。"]],"大概":[["ㄉㄚˋ ㄍㄞˋ","1.內容大要、大致情形。[例]讀書的時候先掌握文章大概，才會有心得收穫。\n2.大約、約略。[例]這件事的前因後果大概就是這樣，請不要再妄作揣測。\n3.揣測估計之詞，表示極有可能。[例]從這裡走路到火車站，大概需要半小時。"]],"大樓":[["ㄉㄚˋ ㄌㄡˊ","高大的樓房。[例]這地區辦公大樓林立，市容非常壯觀。"]],"大氣層":[["ㄉㄚˋ ㄑㄧˋ ㄘㄥˊ","環繞地球的一層氣體。依據溫度變化，可將其垂直劃分為對流層、平流層、中氣層及增溫層。對流層為最低的一層，溫度隨高度遞減。此外，由於地球引力的關係，空氣的濃度離地表愈遠愈稀薄。"]],"大浪":[["ㄉㄚˋ ㄌㄤˋ","1.巨大的風浪。[例]颱風暴風半徑已接近本島，東部沿海都將出現大浪，請附近居民多加小心。\n2.引申指所遭受的重大挫折、打擊。[例]歷經了幾番人生大浪，他依然樂觀進取，努力不懈。"]],"大海撈針":[["ㄉㄚˋ ㄏㄞˇ ㄌㄠ ㄓㄣ","在大海裡撈取遺失的針。比喻東西很難找到或事情難以完成。[例]想在茫茫人海中找尋失散多年的兄弟，有如大海撈針般困難。"]],"大王":[["ㄉㄚˋ ㄨㄤˊ","1.古代對君主或諸侯王的尊稱。[例]大王很賞識他，將委以重任。\n2.俗稱盜匪的首領。[例]山下的官兵攻上來了，快去通報大王！\n3.指某方面非常專精或擅長的人。[例]發明大王、汽車大王、吹牛大王"]],"大發雷霆":[["ㄉㄚˋ ㄈㄚ ㄌㄟˊ ㄊㄧㄥˊ","比喻發怒，大聲責罵。[例]爸爸為了妹妹逃學的事而大發雷霆。"]],"大盜":[["ㄉㄚˋ ㄉㄠˋ","強行掠奪別人財物的人。[例]江洋大盜、蒙面大盜"]],"大約":[["ㄉㄚˋ ㄩㄝ","大概、大致估計。[例]大約再五天，我就可以完成這件工作了。"]],"大胃王":[["ㄉㄚˋ ㄨㄟˋ ㄨㄤˊ","指食量極大的人。[例]你別看他個頭小，他可是個不折不扣的大胃王。"]],"大腹便便":[["ㄉㄚˋ ㄈㄨˋ ㄆㄧㄢˊ ㄆㄧㄢˊ","肚子很大的樣子。[例]瞧她大腹便便，恐怕即將臨盆了。"]],"大臣":[["ㄉㄚˋ ㄔㄣˊ","擔負國家重任的官吏。[例]朝廷大臣、文武大臣、執政大臣"]],"大致":[["ㄉㄚˋ ㄓˋ","1.大概的內容或情形。[例]關於這案件我已知其大致，只是細節尚待查證。\n\t\n2.大概、大約。[例]新來的房客看起來大致有四十歲的模樣。"]],"大蒜":[["ㄉㄚˋ ㄙㄨㄢˋ","植物名。百合科蔥屬，多年生宿根草本。多生於暖地原野間，葉長而有微稜，色多淺綠，氣微臭，莖葉皆可食。具有健胃、整腸、驅除寄生蟲等功效。[例]大蒜含有維生素Ｂ等十幾種成分，有消除疲勞、降低血壓、促進食慾等功能。　◎"]],"大街":[["ㄉㄚˋ ㄐㄧㄝ","城鎮中路面較寬敞，且較為熱鬧繁華的街道。[例]這條大街商店林立，貨品種類繁多，購物非常方便。"]],"大西洋":[["ㄉㄚˋ ㄒㄧ ㄧㄤˊ","五大洋之一。在美洲以東，歐洲與非洲以西，北通北極海，南接南極洲。面積8158萬5000平方公里。[例]西元1492年，哥倫布自歐洲渡過大西洋發現了新大陸。"]],"大象":[["ㄉㄚˋ ㄒㄧㄤˋ","1.→象_x000D_\n2.《易經》各卦附有象傳，依據一卦的基本觀念，總體說明事物變化和人事現象，稱為「大象」。說明各爻的稱為「小象」。"]],"大費周章":[["ㄉㄚˋ ㄈㄟˋ ㄓㄡ ㄓㄤ","事情麻煩瑣碎，必須耗費許多心力來處理。[例]這件事何必大費周章，請那麼多人來幫忙？"]],"大量":[["ㄉㄚˋ ㄌㄧㄤˋ","1.氣度寬宏。[例]寬宏大量\n2.數量多。[例]這家百貨公司大量招募員工，打算近日開幕營業。"]],"大鈔":[["ㄉㄚˋ ㄔㄠ","1.面額大的鈔票。[例]百元大鈔、千元大鈔\n2.樂器名。俗稱北管戲中的「大鈸」。[例]除大鈔外，嗩吶和鑼也是北管中的主要樂器。"]],"大顯身手":[["ㄉㄚˋ ㄒㄧㄢˇ ㄕㄣ ㄕㄡˇ","充分顯露本領才幹。[例]學校舉辦作文比賽，就是我大顯身手的機會。"]],"大駕":[["ㄉㄚˋ ㄐㄧㄚˋ","對人的敬稱。[例]大駕光臨、勞動大駕"]],"天乾物燥":[["ㄊㄧㄢ ㄍㄢ ㄨˋ ㄗㄠˋ","空氣及物體因水分含量少，而呈現乾燥的狀態。[例]夏季裡天乾物燥，要小心火燭。"]],"天候":[["ㄊㄧㄢ ㄏㄡˋ","在一定的時間內，某一地區的大氣物理狀態。如氣溫、氣壓、溼度、風、降水等。[例]由於天候不佳，今早漁民停止出海了。"]],"天倫之樂":[["ㄊㄧㄢ ㄌㄨㄣˊ ㄓ ㄌㄜˋ","家人團聚時的歡樂。[例]逢年過節他一定回家，和家人共享天倫之樂。"]],"天堂":[["ㄊㄧㄢ ㄊㄤˊ","1.某些宗教上指人死後所居的永生極樂世界。[例]信仰讓他相信，逝去的親人已經在天堂了。_x000D_\n2.比喻美好的環境或狀態。[例]這裡風景優美，讓人彷彿置身人間天堂。"]],"天壤之別":[["ㄊㄧㄢ ㄖㄤˇ ㄓ ㄅㄧㄝˊ","天與地相隔很遠。比喻差別極大。[例]城市與鄉村在建設上有天壤之別，我們應努力縮短城鄉間的差距。"]],"天旋地轉":[["ㄊㄧㄢ ㄒㄩㄢˊ ㄉㄧˋ ㄓㄨㄢˇ","天地轉動。形容頭暈眼花。[例]坐完雲霄飛車後，只覺得天旋地轉，站都站不穩。"]],"天氣":[["ㄊㄧㄢ ㄑㄧˋ","在一定區域和一定時間內，多種氣象要素綜合顯示的大氣狀況。[例]今天天氣炎熱，路上的行人都揮汗如雨。"]],"天涯":[["ㄊㄧㄢ ㄧㄚˊ","指非常遙遠的地方。[例]夕陽西下，斷腸人在天涯。（元．馬致遠〈天淨沙．枯藤老樹昏鴉〉曲）"]],"天災":[["ㄊㄧㄢ ㄗㄞ","天然災害。如水災、旱災、地震等。[例]颱風所造成的天災，使數以千計的家園被毀壞，亟待我們伸出援手加以救助。"]],"天真":[["ㄊㄧㄢ ㄓㄣ","1.個性純真自然，沒有做作和虛偽。[例]兒童天真的笑容，常讓人覺得他們就是小天使的化身。\n2.頭腦簡單，容易受迷惑而上當。[例]這事原來不單純，我們的想法太天真了！"]],"天空":[["ㄊㄧㄢ ㄎㄨㄥ","泛指日月星辰所在的廣大空間。[例]蔚藍的天空飄著朵朵的白雲，好一幅美麗的景象。"]],"天窗":[["ㄊㄧㄢ ㄔㄨㄤ","在屋頂或車頂所開設的窗子，用來通風、採光。[例]這間閣樓有一個天窗，所以採光不錯。"]],"天籟":[["ㄊㄧㄢ ㄌㄞˋ","自然的聲音，指不藉任何人為所產生的聲音。[例]夏夜裡，鄉村的蛙鳴蟲叫是最美的天籟。"]],"天鵝":[["ㄊㄧㄢ ㄜˊ","動物名。鳥綱雁鴨目雁鴨科。形似鵝，體大頸長，上嘴有黃色的瘤，全身純白或黑。分布於寒帶，棲於水濱，善飛，吃植物、昆蟲等。[例]白色天鵝在湖上悠閒的划水，景致十分恬靜。　◎"]],"太平":[["ㄊㄞˋ ㄆㄧㄥˊ","極為安寧和平。[例]太平盛世、世界太平"]],"太空":[["ㄊㄞˋ ㄎㄨㄥ","地球大氣層以外的廣大無邊的空域，稱為「太空」。[例]人類對太空的探索，至今仍只是個開始而已。　◎"]],"太空梭":[["ㄊㄞˋ ㄎㄨㄥ ㄙㄨㄛ","為飛機、火箭、太空船三合一的飛行器，可來往於地球與太空軌道之間，並可載送人員、衛星等，因其穿梭於太空中，故稱為「太空梭」。[例]太空梭可以加添燃料再次使用。　◎"]],"太空總署":[["ㄊㄞˋ ㄎㄨㄥ ㄗㄨㄥˇ ㄕㄨˇ","世界各國為研究太空、開發太空計畫而設立的總體性中心機構。如美國太空總署。"]],"太陽":[["ㄊㄞˋ ㄧㄤˊ","天體恆星之一，半徑約為70萬公里，距地球約1億4960萬公里。有巨大的熱能輻射，表面溫度約為攝氏6000度，中心溫度在攝氏1000萬度以上。地球等太陽系八大行星即以它為中心作公轉。　◎"]],"太陽穴":[["ㄊㄞˋ ㄧㄤˊ ㄒㄩㄝˋ","人身的大穴道之一。位於眉稜骨和外眼角中點向後約一橫指的動脈搏動處。[例]他不斷的按著太陽穴，直喊頭疼。"]],"夫人":[["ㄈㄨ ㄖㄣˊ","對已婚婦女的尊稱。[例]今晚部長偕夫人去參加音樂晚會，以提倡正當的休閒娛樂。"]],"夫妻":[["ㄈㄨ ㄑㄧ","有婚姻關係的雙方，通常多用於男女間。[例]夫妻同心，化土為金。"]],"央求":[["ㄧㄤ ㄑㄧㄡˊ","懇求、請求。[例]小男孩苦苦央求媽媽為他購買模型飛機。"]],"失去":[["ㄕ ㄑㄩˋ","失掉。[例]一個小小的錯誤，讓他失去了成功的機會。"]],"失控":[["ㄕ ㄎㄨㄥˋ","失去控制、不能自制。[例]她在得知這件不幸的消息後，情緒一度失控。"]],"失敗":[["ㄕ ㄅㄞˋ","不成功、遭受挫折。[例]失敗為成功之母。"]],"失禮":[["ㄕ ㄌㄧˇ","1.不合乎禮儀。[例]他們兄弟倆當眾就在客人面前吵起架來，真是太失禮了。\n2.對人表示禮貌不周的客氣話。[例]讓你等這麼久，真是失禮得很。"]],"失誤":[["ㄕ ㄨˋ","錯誤、差錯。[例]這支球隊失誤連連，而讓對方擊出數支安打，拿下好幾分。"]],"夾子":[["ㄐㄧㄚˊ ˙ㄗ","1.夾東西的器具。[例]頭髮夾子、文件夾子\n2.放置財物等的扁形小袋。[例]皮夾子"]],"夾縫":[["ㄐㄧㄚˊ ㄈㄥˋ","1.兩個毗鄰物體間的狹窄空隙。[例]櫃子的夾縫容易藏汙納垢，不易清掃。\n2.比喻狹隘、艱難的處境。[例]他處在母親與妻子的夾縫中，左右為難。"]],"奄奄一息":[["ㄧㄢ ㄧㄢ ㄧ ㄒㄧˊ","僅存微弱的一口氣。形容生命垂危。[例]車禍傷患被送到醫院時已奄奄一息，最後終告不治。"]],"奇妙":[["ㄑㄧˊ ㄇㄧㄠˋ","神奇奧妙。[例]許多動物都有預知危險的本能，上帝造物真是奇妙。"]],"奇幻":[["ㄑㄧˊ ㄏㄨㄢˋ","非常神奇，好像夢幻一般。[例]魔術師的奇幻表演，讓現場觀眾驚嘆不已。"]],"奇怪":[["ㄑㄧˊ ㄍㄨㄞˋ","奇異，出乎意料。[例]對於這件事的發生，大家都感到很奇怪。"]],"奇恥大辱":[["ㄑㄧˊ ㄔˇ ㄉㄚˋ ㄖㄨˋ","重大的恥辱。[例]向來奉公守法的他，竟被他人栽贓指為收受回扣，簡直是奇恥大辱。"]],"奇數":[["ㄐㄧ ㄕㄨˋ","不能被二整除的數，如一、三、五等。相對於偶數而言。"]],"奇特":[["ㄑㄧˊ ㄊㄜˋ","奇異特殊。[例]他的穿著奇特，在人群中相當顯眼。"]],"奇觀":[["ㄑㄧˊ ㄍㄨㄢ","奇異罕見的現象、景觀。[例]世界奇觀、千古奇觀"]],"奇貨可居":[["ㄑㄧˊ ㄏㄨㄛˋ ㄎㄜˇ ㄐㄩ","把稀有難得的貨物囤積起來，以待高價出售。比喻持有某種事物或具有專長的人才作資本，等待時機，以牟取利益。語出《史記．卷八十五．呂不韋》。[例]這地區經重劃後的土地，不少投資者認為是奇貨可居，紛紛在此置產。"]],"奇蹟":[["ㄑㄧˊ ㄐㄧ","異於尋常、令人無法理解的現象或事情。[例]他被活埋了四小時竟然沒死，真是個奇蹟。"]],"奇遇":[["ㄑㄧˊ ㄩˋ","奇特的遭遇。[例]她永遠也想不到今日這個奇遇，改變了她往後的命運。"]],"奉告":[["ㄈㄥˋ ㄍㄠˋ","告知的敬辭。[例]對於這件事情，我只能說無可奉告。"]],"奉命":[["ㄈㄥˋ ㄇㄧㄥˋ","接受尊長或上級的命令。[例]大家不要把錯都歸在他身上，他也只是奉命行事罷了。"]],"奉獻":[["ㄈㄥˋ ㄒㄧㄢˋ","恭敬的交付、貢獻。[例]他將畢生的心力奉獻給教育事業。"]],"奉養":[["ㄈㄥˋ ㄧㄤˋ","侍奉供養。[例]奉養父母是為人子女應盡的義務。"]],"奏樂":[["ㄗㄡˋ ㄩㄝˋ","演奏樂曲。[例]鼓號樂隊的奏樂聲，令人心神振奮。"]],"契機":[["ㄑㄧˋ ㄐㄧ","轉機，事情轉變的關鍵。[例]這次任務調整是公司轉型的契機，希望大家發揮所長，全力以赴。"]],"奔跑":[["ㄅㄣ ㄆㄠˇ","快速的跑。[例]他沒命似的奔跑，好像被妖魔追趕一樣。"]],"奔騰":[["ㄅㄣ ㄊㄥˊ","奔馳騰躍。[例]萬馬奔騰"]],"套招":[["ㄊㄠˋ ㄓㄠ","電影或電視的武打動作片在拍攝之前，先由演員練習招數，稱為「套招」。[例]這部電影的女主角在套招時不幸傷了左眼，導演只得臨時換角。"]],"套色":[["ㄊㄠˋ ㄙㄜˋ","一種彩色印刷的方法。用平版或凸版分次印刷，每次印一種顏色，利用紅、黃、藍三種原色重疊可調出各種顏色。[例]書本上的彩色插圖，都是利用套色方法印製而成的。"]],"套餐":[["ㄊㄠˋ ㄘㄢ","已經配好菜色而整份出售的餐點。[例]這家餐廳的套餐既經濟又實惠，深得消費者的喜愛。"]],"奠定":[["ㄉㄧㄢˋ ㄉㄧㄥˋ","建立、確立。[例]今日的努力，奠定日後成功的基礎。"]],"奠立":[["ㄉㄧㄢˋ ㄌㄧˋ","建立。[例]他以誠信原則做生意，奠立了良好的商譽。"]],"奢靡":[["ㄕㄜ ㄇㄧˇ","奢侈浪費，不知節制。[例]他家境富有，自幼過著奢靡的生活。"]],"奧妙":[["ㄠˋ ㄇㄧㄠˋ","深奧奇妙。[例]大自然的一切運作看似奧妙，其實仍有一定的道理。"]],"奧援":[["ㄠˋ ㄩㄢˊ","內援，通常指有力而可靠的後援。[例]因為有經濟強國為奧援，這個跨國企業才安然的度過這段經濟不景氣的時期。"]],"奪冠":[["ㄉㄨㄛˊ ㄍㄨㄢˋ","爭取冠軍。[例]她未辜負眾望，終於在舞蹈比賽中奪冠。"]],"奪眶而出":[["ㄉㄨㄛˊ ㄎㄨㄤ ㄦˊ ㄔㄨ","形容淚水迅速的流出來。[例]她一聽到父親去世的消息，淚水馬上奪眶而出。"]],"奮不顧身":[["ㄈㄣˋ ㄅㄨˋ ㄍㄨˋ ㄕㄣ","勇往向前，不顧生死。[例]車禍發生時，他奮不顧身的搶救受傷的乘客。"]],"奮力":[["ㄈㄣˋ ㄌㄧˋ","鼓起力量。[例]他奮力一跳，打破全國的跳遠紀錄。"]],"奮戰":[["ㄈㄣˋ ㄓㄢˋ","奮勇戰鬥。[例]為了家人，他決定與病魔奮戰到底。"]],"奮鬥":[["ㄈㄣˋ ㄉㄡˋ","不屈服於環境，為達目的而努力。[例]他奮鬥多年，終於事業有成。"]],"女主人":[["ㄋㄩˇ ㄓㄨˇ ㄖㄣˊ","指一家之中的女性主人。[例]這個家經過女主人的巧手布置，環境舒適，滿室溫馨。"]],"女性":[["ㄋㄩˇ ㄒㄧㄥˋ","兩性之一，具雌性特徵者。與「男性」相對。"]],"女生":[["ㄋㄩˇ ㄕㄥ","泛指一般的女孩。[例]現代女生的審美觀點多元，各有所好。"]],"女神":[["ㄋㄩˇ ㄕㄣˊ","1.女性的神明。[例]媽祖是漁民的守護女神。\n2.指才貌出眾、表現特出的女性偶像。[例]這位女民歌手的歌藝，風靡一時，是粉絲心目中的女神。"]],"奶奶":[["ㄋㄞˇ ˙ㄋㄞ","1.稱謂：(1) 對祖母的稱呼。[例]奶奶年紀雖然大，但是她目前在國中補校進修，求上進的心不輸年輕人。　(2) 對老婦人的敬稱。[例]李奶奶　(3) 對女主人的尊稱。[例]少奶奶\n2.乳房的俗稱。[例]小嬰兒在喝母奶時，總會將臉蛋靠在母親的奶奶上。"]],"奶油":[["ㄋㄞˇ ㄧㄡˊ","一種從牛奶提煉出來的脂肪性食品。顏色為黃色或白色。通常用來塗抹麵包，作餅乾、蛋糕等。"]],"奶瓶":[["ㄋㄞˇ ㄆㄧㄥˊ","有奶嘴裝置的瓶子，是餵嬰兒喝牛奶的用具。[例]奶瓶在使用前要高溫消毒，以防止細菌感染。"]],"奶粉":[["ㄋㄞˇ ㄈㄣˇ","一種食品。把牛奶或羊奶等脫水製成易於保存的粉末，食用時加水沖調。其種類按脂肪含量的多寡，可分為全脂、半脂與脫脂三種。[例]母親將奶粉沖泡好後餵給小弟喝。"]],"奶茶":[["ㄋㄞˇ ㄔㄚˊ","將牛奶或奶精等攙入茶中，所調製的一種飲料。[例]西方人喜歡喝奶茶，尤其以英國人為最。"]],"她們":[["ㄊㄚ ˙ㄇㄣ","對兩個以上的女性的指稱詞。[例]她們讀高中時同住一室，情同姊妹。"]],"好久":[["ㄏㄠˇ ㄐㄧㄡˇ","很長的一段時間。[例]南部好久沒下雨，水庫的積水已經降到呆水位了。"]],"好事多磨":[["ㄏㄠˇ ㄕˋ ㄉㄨㄛ ㄇㄛˊ","渴望美好的事，往往要歷經很多波折才能如願。[例]他原本計劃安置好家庭後，便出國進修，無奈好事多磨，接踵而來的意外使他一直未能成行。"]],"好像":[["ㄏㄠˇ ㄒㄧㄤˋ","1.非常相像。[例]她們姊妹倆長得好像，不熟的人很容易認錯。\n2.似乎。[例]天色這麼暗，好像要下雨了。"]],"好勝":[["ㄏㄠˋ ㄕㄥˋ","喜歡超越、凌駕於他人之上。[例]他生性好勝，做事總想爭第一，不肯落於人後。"]],"好吃":[["ㄏㄠˇ ㄔ","美味可口。[例]遍嚐天下美食，他還是覺得家鄉菜最好吃。"],["ㄏㄠˋ ㄔ","愛吃、嘴饞。[例]小孩子因好吃糖果而弄得滿嘴蛀牙。"]],"好多":[["ㄏㄠˇ ㄉㄨㄛ","1.許多。[例]雖然是個簡單的道理，我卻花了好多年才想通。_x000D_\n2.多少。[例]今天出席的人有好多？"]],"好奇":[["ㄏㄠˋ ㄑㄧˊ","對於自己所不了解的事物，覺得新奇而感興趣。[例]他第一次出國，對於所看到的一切事物都很好奇。"]],"好學":[["ㄏㄠˇ ㄒㄩㄝˊ","容易學習。[例]玩飛盤的技巧簡單好學，但要掌控自如仍需不斷的練習。"],["ㄏㄠˋ ㄒㄩㄝˊ","喜歡學習。[例]由於好學不倦，如今他在學術研究上已卓然有成。"]],"好學不倦":[["ㄏㄠˋ ㄒㄩㄝˊ ㄅㄨˋ ㄐㄩㄢˋ","喜好學習而不知疲倦。[例]他的為人最大長處就是好學不倦。"]],"好客":[["ㄏㄠˋ ㄎㄜˋ","樂於款待客人。[例]他生性好客，家裡經常高朋滿座。"]],"好強":[["ㄏㄠˋ ㄑㄧㄤˊ","不願認輸、示弱。[例]他是一個好強的人，無論什麼困難，都會想盡辦法去克服。"]],"好朋友":[["ㄏㄠˇ ㄆㄥˊ ㄧㄡˇ","1.交情深厚的朋友。[例]他與幾個好朋友一起旅行去了。_x000D_\n2.女子月經來潮的委婉說法。_x000D_"]],"好看":[["ㄏㄠˇ ㄎㄢˋ","1.看起來舒適、美觀。[例]這套衣服，你穿起來很好看。\n2.體面、光采。[例]他花了大筆金錢，只為讓場面看起來很好看。\n3.難堪、出醜。[例]今天你不給我面子，改日一定要你好看！"]],"好處":[["ㄏㄠˇ ㄔㄨˋ","1.適合、得宜的地方或事情。[例]這幅名家畫作，無論運筆用色，都配合得恰到好處。\n2.利益、恩惠。[例]無論給他多少好處，他都不會答應去做違背良心的事情。"]],"好評":[["ㄏㄠˇ ㄆㄧㄥˊ","正面的評價。[例]這家公司的產品精良，廣受顧客好評。"]],"好逸惡勞":[["ㄏㄠˋ ㄧˋ ㄨˋ ㄌㄠˊ","貪圖安逸，憎惡勞動。[例]茶來伸手，飯來張口的日子，養成他好逸惡勞的個性。"]],"如何":[["ㄖㄨˊ ㄏㄜˊ","怎樣。[例]他做事從不問結果如何，只管埋頭苦幹。"]],"如廁":[["ㄖㄨˊ ㄘㄜˋ","上廁所。[例]衛生設備俱全的盥洗室，才能令人安心如廁。"]],"如意":[["ㄖㄨˊ ㄧˋ","1.稱心、符合心中的意願。[例]稱心如意、萬事如意、吉祥如意\n\t\n2.搔背的器具。以骨角、竹木削做人手指爪形，有長柄，可如人心意搔背部的癢，故稱為「如意」。後世演變成一種象徵吉祥的陳設品，以金、玉等刻製，頂端多作靈芝形或雲形，長柄微曲，可供賞玩。[例]古代的王公貴族經常把玩如意，將它當成玩賞品。　△不求人、搔背爬"]],"如果":[["ㄖㄨˊ ㄍㄨㄛˇ","假使、倘若。[例]如果人人都遵守交通規則，就可以大大減少車禍的發生。"]],"如此":[["ㄖㄨˊ ㄘˇ","這樣。[例]他如此優秀的成績，是經過長期的努力換來的。"]],"如火燎原":[["ㄖㄨˊ ㄏㄨㄛˇ ㄌㄧㄠˊ ㄩㄢˊ","像熊熊烈火燃燒草原一樣。比喻情勢迅速擴大，難以遏止。[例]這個超級網路病毒如火燎原迅速蔓延開來。"]],"如釋重負":[["ㄖㄨˊ ㄕˋ ㄓㄨㄥˋ ㄈㄨˋ","好像放下了沉重的負擔。比喻責任已盡，身心輕快。[例]聽到祖父病情好轉的消息，他頓時鬆了一口氣，如釋重負。"]],"如願以償":[["ㄖㄨˊ ㄩㄢˋ ㄧˇ ㄔㄤˊ","理想得以實現。[例]他經過不斷的努力，終於如願以償的進入大學了。"]],"妒忌":[["ㄉㄨˋ ㄐㄧˋ","憎恨他人勝過自己。[例]他才能出眾，有人欽佩，也有人妒忌。"]],"妖怪":[["ㄧㄠ ㄍㄨㄞˋ","怪異而害人的精怪。[例]她在此劇中飾演一個無惡不作的妖怪，演技精湛，深獲好評。"]],"妙計":[["ㄇㄧㄠˋ ㄐㄧˋ","巧妙的計策。[例]錦囊妙計"]],"妙齡":[["ㄇㄧㄠˋ ㄌㄧㄥˊ","美好的年齡。多指青春年少時期。"]],"妥協":[["ㄊㄨㄛˇ ㄒㄧㄝˊ","彼此退讓部分的意見、原則等，以避免爭端或衝突。[例]他執行公務一向秉公處理，絕不與惡勢力妥協。"]],"妥善":[["ㄊㄨㄛˇ ㄕㄢˋ","妥當完善。[例]這套新制度若能妥善運用，必能提高工作效率。"]],"妨害":[["ㄈㄤˊ ㄏㄞˋ","阻礙及損害。[例]不要在公共場所抽煙，以免妨害他人健康。"]],"妨礙":[["ㄈㄤˊ ㄞˋ","阻礙。[例]違規停車對交通的流暢妨礙極大。"]],"妹妹":[["ㄇㄟˋ ˙ㄇㄟ","稱謂：(1) 稱同父母所生而比自己年幼的女性。[例]他在家排行老大，下面還有兩個妹妹。　(2) 稱同輩親屬中比自己年幼的女性。[例]我的好妹妹！你別生氣了，是我不對！"]],"妻子":[["ㄑㄧ ㄗˇ","妻與兒女。[例]他與妻子四人常利用假日到郊外踏青。"],["ㄑㄧ ˙ㄗ","稱男子的配偶。[例]他和妻子之間相敬如賓，甚少有口角發生。"]],"妻室":[["ㄑㄧ ㄕˋ","妻子。[例]他年輕英俊又多金，且未有妻室，是標準的單身貴族。"]],"始終":[["ㄕˇ ㄓㄨㄥ","1.從開始到結束。[例]他無論念書、就業，始終潔身自好，與人為善。\n2.終究、還是。[例]我們等了他半天，他始終沒來。"]],"姍姍來遲":[["ㄕㄢ ㄕㄢ ㄌㄞˊ ㄔˊ","形容女子遲步緩來的樣子。後用以形容人遲到，不依時赴會。典出《漢書．卷九十七．外戚傳上．孝武李夫人傳》。[例]我準時赴約，他卻姍姍來遲，真令人生氣。"]],"姐姐":[["ㄐㄧㄝˇ ˙ㄐㄧㄝ","稱謂：(1) 稱同父母所生而比自己年長的女性。[例]從小我就跟姐姐感情很好，無話不談。　(2) 稱同輩親屬中比自己年長的女性。　(3) 對一般比自己年長女性的尊稱。"]],"姑丈":[["ㄍㄨ ㄓㄤˋ","稱謂。稱姑母的丈夫。[例]每逢爺爺或奶奶生日時，姑丈一定陪著姑姑遠從金門回來為老人家祝壽。　△姑父、姑爹　◎"]],"姑媽":[["ㄍㄨ ㄇㄚ","稱謂。稱父親的姊妹。[例]自從住鄉下的爺爺、奶奶去世後，每年大年初二爸爸都會請姑媽到家裡做客，讓姑媽仍享有回娘家的快樂。　△姑母、姑姑　◎"]],"姓名":[["ㄒㄧㄥˋ ㄇㄧㄥˊ","姓氏與名字。[例]他因車禍受傷而喪失記憶，甚至連自己的姓名也忘了。"]],"委婉":[["ㄨㄟˇ ㄨㄢˇ","婉轉曲折。[例]委婉的勸解勝於嚴厲的苛責。"]],"委屈":[["ㄨㄟˇ ㄑㄩ","1.壓制自己的意志，以遷就他人或環境。[例]為解決家裡的經濟危機，他只好委屈自己四處兼差。　△委曲_x000D_\n2.因遭受不合理的待遇而感到難過。[例]碰到不如意的事，可以向好友傾吐心中的委屈。　△委曲_x000D_\n3.虧待，有不足於人之意。[例]憑你的高才來擔任這份卑微的工作，真是太委屈你了。"]],"委靡":[["ㄨㄟˇ ㄇㄧˇ","頹喪，不振作。[例]頹墮委靡、委靡不振"]],"姨丈":[["ㄧˊ ㄓㄤˋ","稱謂。稱母親姊妹的丈夫。[例]姨丈開車非常平穩，讓乘坐的人感到既安全又舒適。　△姨夫、姨父、姨爹　◎"]],"姿態":[["ㄗ ㄊㄞˋ","姿勢、模樣。[例]他們跳舞時優雅的姿態，令人讚嘆。"]],"威力":[["ㄨㄟ ㄌㄧˋ","令人畏服的強大力量。[例]這次地震的威力強大，震央附近的城市受損嚴重。"]],"威嚇":[["ㄨㄟ ㄏㄜˋ","憑藉威勢脅迫人。"]],"威武":[["ㄨㄟ ㄨˇ","1.威風、有氣派。[例]三軍儀隊的成員，個個雄壯威武，看了不禁令人稱羨不已。\n2.威勢武力。[例]富貴不能淫，貧賤不能移，威武不能屈。（《孟子．滕文公下》）"]],"威猛":[["ㄨㄟ ㄇㄥˇ","威武勇猛。[例]他在球場上的表現，威猛過人，是教練團心目中的大將。"]],"威脅":[["ㄨㄟ ㄒㄧㄝˊ","以權勢威力脅迫。[例]他無視於威脅利誘，始終堅持自己的原則。"]],"威風":[["ㄨㄟ ㄈㄥ","1.令人敬畏的氣勢。[例]長他人志氣，滅自己威風。\n2.神氣、有氣派。[例]他穿上軍服後，威風十足。"]],"娃兒":[["ㄨㄚˊㄦ","小孩。[例]這娃兒長得眉清目秀，很討人喜歡。"]],"娓娓道來":[["ㄨㄟˇ ㄨㄟˇ ㄉㄠˋ ㄌㄞˊ","說話連續不間斷。[例]聽他娓娓道來事情的始末，大家才了解真相。"]],"娘子":[["ㄋㄧㄤˊ ㄗˇ","1.稱謂。古稱妻子。[例]在古時婚姻多靠媒妁之言，作丈夫的與自己的娘子在結婚前連一面都沒見過是常有的事。_x000D_\n2.泛稱女子。[例]鐵娘子、娘子軍"]],"娘家":[["ㄋㄧㄤˊ ㄐㄧㄚ","已婚婦女稱自己父母的家。[例]大年初二在習俗上是嫁出去的女兒回娘家的日子。"]],"娛樂":[["ㄩˊ ㄌㄜˋ","1.快樂，使歡樂。[例]他自告奮勇上臺表演餘興節目，娛樂賓客。\n2.消遣的樂事。[例]他休假時以看電影為娛樂。"]],"娟秀":[["ㄐㄩㄢ ㄒㄧㄡˋ","美好秀麗。[例]字跡娟秀"]],"婆娑":[["ㄆㄛˊ ㄙㄨㄛ","1.盤旋舞蹈的樣子。[例]婆娑起舞\n2.枝葉繁茂而隨風搖曳的樣子。[例]枝葉婆娑\n3.淚光閃動的樣子。[例]她抬起婆娑的淚眼望著我。"]],"婆婆":[["ㄆㄛˊ ˙ㄆㄛ","稱謂：(1) 尊稱年老的婦女。[例]王婆婆、李婆婆　(2) 妻子稱丈夫的母親。[例]自從結婚之後，我和婆婆相處融洽，極少爭執。　(3) 祖母的俗稱。[例]小時候我都和婆婆一起睡。"]],"婉約":[["ㄨㄢˇ ㄩㄝ","婉轉含蓄。[例]她的個性溫柔婉約，很好相處。"]],"婉謝":[["ㄨㄢˇ ㄒㄧㄝˋ","委婉謝絕。[例]他婉謝朋友的熱情援助，而獨力償還債務。"]],"婚嫁":[["ㄏㄨㄣ ㄐㄧㄚˋ","指締結婚姻之事。[例]他倆情投意合，目前已到論及婚嫁的階段了。"]],"婚禮":[["ㄏㄨㄣ ㄌㄧˇ","結婚時所舉行的公開儀式。[例]他們預備在海邊舉行婚禮。"]],"媒體":[["ㄇㄟˊ ㄊㄧˇ","傳播資料訊息的工具。如電視、廣播、報章雜誌等。[例]政府常利用各種媒體進行政策宣導。"]],"媲美":[["ㄆㄧˋ ㄇㄟˇ","美好的程度彼此相當。[例]小張的文筆流暢，足以媲美名作家。"]],"媽咪":[["ㄇㄚ ㄇㄧ","稱謂。對母親的暱稱。§英mammy　[例]小玲一到家，就在門口喊著：「媽咪！我回來了！」"]],"媽媽":[["ㄇㄚ ˙ㄇㄚ","稱謂：對母親的稱呼。[例]遠行前夕，媽媽再三叮嚀：一定要好好照顧自己。_x000D_"]],"嫂嫂":[["ㄙㄠˇ ˙ㄙㄠ","稱謂。稱哥哥的妻子。[例]哥哥跟嫂嫂鶼鰈情深，令人稱羨。　◎"]],"嫌惡":[["ㄒㄧㄢˊ ㄨˋ","厭惡。[例]態度傲慢的人，往往惹人嫌惡。"]],"嫌棄":[["ㄒㄧㄢˊ ㄑㄧˋ","因為厭惡而不願接近。[例]只要你不嫌棄，歡迎隨時駕臨寒舍。"]],"嫌犯":[["ㄒㄧㄢˊ ㄈㄢˋ","法律上指有犯罪嫌疑而未經證實的人。[例]經過警方嚴密的調查，終於掌握了特定的嫌犯。"]],"嫌疑":[["ㄒㄧㄢˊ ㄧˊ","被懷疑與某事相牽連。[例]經過查證，警方認為證人與嫌犯有串供的嫌疑。"]],"嫩葉":[["ㄋㄣˋ ㄧㄝˋ","植物剛萌生而柔弱的葉子。[例]校園裡的花草樹木紛紛長出了嫩葉，帶來了春天的訊息。"]],"嬌小":[["ㄐㄧㄠ ㄒㄧㄠˇ","小巧可愛。[例]小狗嬌小的身軀，看起來可愛極了。"]],"嬌羞":[["ㄐㄧㄠ ㄒㄧㄡ","害羞可愛的樣子。[例]新娘嬌羞的模樣，更加散發出迷人的氣息。"]],"嬰兒":[["ㄧㄥ ㄦˊ","初生的幼兒。[例]這名嬰兒長得白白胖胖，非常可愛。"]],"嬸嬸":[["ㄕㄣˇ ˙ㄕㄣ","稱謂。稱叔叔的妻子。[例]嬸嬸是叔叔事業上的得力助手。　◎"]],"子彈":[["ㄗˇ ㄉㄢˋ","槍彈、炮彈的總稱。由彈頭、彈殼、火帽、發射藥等部分所組成。[例]警方據報，在走私漁船上查獲大批槍械及子彈。"]],"子時":[["ㄗˇ ㄕˊ","指夜晚十一時到一時。[例]她是半夜十二點半出生的，生辰八字算是子時。"]],"孔武有力":[["ㄎㄨㄥˇ ㄨˇ ㄧㄡˇ ㄌㄧˋ","勇敢又有力氣。[例]這人生來就孔武有力，聽說能徒手抬起一輛汽車。"]],"字典":[["ㄗˋ ㄉㄧㄢˇ","以字為單位，按一定體例編次，並解釋文字的音義或形構，以備查檢的工具書。[例]《康熙字典》、《韋氏大字典》"]],"存心":[["ㄘㄨㄣˊ ㄒㄧㄣ","心懷某種意念。[例]存心不良、存心作壞"]],"存貨":[["ㄘㄨㄣˊ ㄏㄨㄛˋ","積存的貨品。[例]部分商家利用折扣的方式來出清存貨。"]],"存錢":[["ㄘㄨㄣˊ ㄑㄧㄢˊ","貯聚金錢。[例]讓孩子從小學習存錢，可使他們養成節儉儲蓄的好習慣。"]],"孝順":[["ㄒㄧㄠˋ ㄕㄨㄣˋ","孝敬順從父母。[例]孝順是做人的基本道理。"]],"季節":[["ㄐㄧˋ ㄐㄧㄝˊ","一年中，因氣候或活動取向具有某種特徵而區分出來的時段。[例]梅雨季節、農忙季節"]],"孤兒":[["ㄍㄨ ㄦˊ","父母雙亡或被父母遺棄而無人收養的兒童。[例]因為不能生育，她和丈夫打算認養一個孤兒。"]],"孤單":[["ㄍㄨ ㄉㄢ","單獨無依。[例]由於父母忙於工作，那個小孩常孤單一人在住家附近遊盪。"]],"孤寂":[["ㄍㄨ ㄐㄧˊ","孤單寂寞。[例]他表面上雖然開朗健談，其實內心非常孤寂。"]],"孤掌難鳴":[["ㄍㄨ ㄓㄤˇ ㄋㄢˊ ㄇㄧㄥˊ","比喻孤立無助，難以成事。[例]同事突然表示無法支援他處理這個案件，他頓時覺得孤掌難鳴。"]],"孤陋寡聞":[["ㄍㄨ ㄌㄡˋ ㄍㄨㄚˇ ㄨㄣˊ","學識淺薄，見聞不廣泛。[例]他不僅孤陋寡聞，還自以為是。"]],"孤零零":[["ㄍㄨ ㄌㄧㄥˊ ㄌㄧㄥˊ","孤單。[例]因為朋友失約，他只好一個人孤零零的吃飯。"]],"孩子":[["ㄏㄞˊ ˙ㄗ","1.未成年的人。[例]一群孩子圍著小販，爭買糖葫蘆。\n2.子女。[例]儘管她已長大成人，但在父母的心中，她永遠是最寶貝的孩子。"]],"孩童":[["ㄏㄞˊ ㄊㄨㄥˊ","小孩、兒童。[例]孩童是國家未來的主人翁、社會的棟梁。"]],"孫女":[["ㄙㄨㄣ ㄋㄩˇ","稱謂。稱兒子的女兒，今亦稱女兒的女兒。[例]他們家只有一個小孫女，兩老疼愛有加。"]],"孫子":[["ㄙㄨㄣ ㄗˇ","1.人名。即孫武。春秋時齊國人，生卒年不詳，著有兵法，嘗為吳王闔閭練兵。\n2.書名。春秋孫武撰，一卷，十三篇。為古代的兵書，內容分析戰爭形勢，探討軍事作戰策略、方式，被推崇為兵經。　△孫子兵法"],["ㄙㄨㄣ ˙ㄗ","稱謂：(1) 稱兒子的兒子，今亦稱女兒的兒子。[例]張奶奶時常帶著孫子到公園玩耍。 (2) 泛稱兒女的子女。[例]老壽星呵呵的笑說：「我一共有十個兒女，五十個孫子。」"]],"孵育":[["ㄈㄨ ㄩˋ","蟲、魚、鳥等類動物的卵，以自然或人工方式使胚胎發育成為幼體。[例]國人以人工方式成功的孵育了櫻花鉤吻鮭，使保育工作向前邁進了一大步。"]],"學問":[["ㄒㄩㄝˊ ㄨㄣˋ","學習所得的知識。[例]學問為濟世之本。"]],"學堂":[["ㄒㄩㄝˊ ㄊㄤˊ","古代學生受教育的場所，相當於現今的學校。[例]王冕幼時喪父，全靠母親做些針線，才能供他到村裡的學堂讀書。"]],"學徒":[["ㄒㄩㄝˊ ㄊㄨˊ","跟隨師傅學習技藝的人。[例]他白天在麵包店裡當學徒，晚上還到夜校去學簿記。"]],"學校":[["ㄒㄩㄝˊ ㄒㄧㄠˋ","講學研習的教育機構。[例]學校是培育人才的搖籃。"]],"學業":[["ㄒㄩㄝˊ ㄧㄝˋ","學習的課業。[例]由於家境清寒，他以半工半讀的方式完成學業。"]],"學習":[["ㄒㄩㄝˊ ㄒㄧˊ","1.研究練習。[例]他從去年開始學習書法，如今已能寫得一手好字。\n2.效法。[例]他做事認真負責的態度很值得我們學習。"]],"學者":[["ㄒㄩㄝˊ ㄓㄜˇ","在學術上有一定成就的人。[例]他在物理學超導體研究上有卓越貢獻，是一位出色的科學工作學者。"]],"宅院":[["ㄓㄞˊ ㄩㄢˋ","帶有庭院的宅舍，也指住宅。[例]今年生日，美美決定在她家宅院的前庭舉行餐會招待朋友。"]],"宇宙":[["ㄩˇ ㄓㄡˋ","時間與空間的總稱，即天地。[例]宇宙萬物十分奧妙，值得我們去探索。"]],"守時":[["ㄕㄡˇ ㄕˊ","遵守約定的時間。[例]約會要守時，才不會誤事。"]],"守衛":[["ㄕㄡˇ ㄨㄟˋ","1.看守防衛。[例]倉庫裡新進一些價值不菲的貨物，必須派人輪流守衛。\n2.看守防衛的人。[例]林伯伯在這家工廠擔任守衛已經十幾年了。"]],"守護":[["ㄕㄡˇ ㄏㄨˋ","守衛保護。[例]前線的將士們日夜守護著邊界，不讓敵人越雷池一步。"]],"安全":[["ㄢ ㄑㄩㄢˊ","平安而沒有危險。[例]時時注意居家安全，才能保障生命財產不受損失。"]],"安全帶":[["ㄢ ㄑㄩㄢˊ ㄉㄞˋ","供人繫綁以維護安全的繩帶。多見於高空作業、技藝表演，或飛機、汽機車、遊樂等設施中。[例]上高速公路時，為確保安全，駕駛人和前座乘客都必須繫上安全帶。"]],"安慰":[["ㄢ ㄨㄟˋ","1.安撫勸慰。[例]她哭得那麼傷心，卻沒有人過去安慰她。\n2.心中感到欣慰，沒有遺憾。[例]他今天的成就，使他的母親感到相當安慰。"]],"安排":[["ㄢ ㄆㄞˊ","安置辦理。[例]這次出遊事宜，全由他代為安排。"]],"安泰":[["ㄢ ㄊㄞˋ","平安康泰。[例]我們全家人在壽宴上齊祝爺爺身體安泰。"]],"安穩":[["ㄢ ㄨㄣˇ","安全穩當。[例]他這一覺睡得安穩，起床時精神百倍。"]],"安詳":[["ㄢ ㄒㄧㄤˊ","平靜、從容不迫。[例]安詳辭世、舉止安詳"]],"安靜":[["ㄢ ㄐㄧㄥˋ","靜寂無聲。[例]全班同學見老師一進教室，立刻安靜下來。"]],"完全":[["ㄨㄢˊ ㄑㄩㄢˊ","1.完整、齊全。[例]這篇文章旨意不夠完全，請再補充說明。\n2.全部。[例]他的話我完全同意。\n3.全然。[例]這件事完全是他惹起的，應該由他負責。"]],"完成":[["ㄨㄢˊ ㄔㄥˊ","做好、做成。[例]他花了一早上，終於將作業完成了。"]],"完整":[["ㄨㄢˊ ㄓㄥˇ","圓滿，完全沒有殘缺、遺漏。[例]問答題的作答應力求完整，才能獲得高分。"]],"完璧歸趙":[["ㄨㄢˊ ㄅㄧˋ ㄍㄨㄟ ㄓㄠˋ","藺相如完整的將璧歸還給趙國的故事。後比喻物歸原主。典出《史記．卷八十一．廉頗藺相如傳》。[例]這是撿來的東西，既知失主，理當完璧歸趙。"]],"完畢":[["ㄨㄢˊ ㄅㄧˋ","結束。[例]父親在電話裡說事情一處理完畢，就馬上回家。"]],"宏偉":[["ㄏㄨㄥˊ ㄨㄟˇ","宏壯雄偉。[例]面對宏偉的建築物，人類驚覺自己的渺小。"]],"宏揚":[["ㄏㄨㄥˊ ㄧㄤˊ","發揚光大。[例]他畢生致力於民權運動，宏揚平等博愛的精神。"]],"宗教":[["ㄗㄨㄥ ㄐㄧㄠˋ","基於人類對於宇宙、人生的神祕所產生的驚奇和敬畏心理，建構一種勸善懲惡的教義，並用來教化世人，使人信仰的文化活動與現象，稱為「宗教」。如佛教、基督教、伊斯蘭教等。"]],"官員":[["ㄍㄨㄢ ㄩㄢˊ","官吏，具一定職等的政府工作人員。[例]要改善政府形象，首先要要求官員建立廉能的形象。"]],"官府":[["ㄍㄨㄢ ㄈㄨˇ","官署的總稱。[例]地方官府"]],"官方":[["ㄍㄨㄢ ㄈㄤ","政府方面。[例]官方說法、官方消息"]],"官職":[["ㄍㄨㄢ ㄓˊ","泛稱官位。[例]古代士人常經由科舉考試謀得官職。"]],"定義":[["ㄉㄧㄥˋ ㄧˋ","能簡要完整表達某種概念的語言或文字。[例]人性太複雜，無法簡單的下一個定義。"]],"宛如":[["ㄨㄢˇ ㄖㄨˊ","彷彿。[例]陣陣寒風吹在身上，宛如針刺刀割。"]],"客人":[["ㄎㄜˋ ㄖㄣˊ","1.顧客。[例]有客人上門參觀了，趕緊茶水招待。\n2.賓客。接受邀請、受到招待的人。[例]你是客人，怎麼好意思讓你幫忙搬東西呢！\n3.→客家人"]],"客家人":[["ㄎㄜˋ ㄐㄧㄚ ㄖㄣˊ","東晉五胡亂華時，原居山西、陝西、河南、安徽一帶的居民，因避戰亂而集體南遷，在開墾江南的過程中，常和土著發生衝突，於是地方政府稱原先居住的土著為「主籍」，從北方遷來的漢人為「客籍」，這種主、客的區別就是現在客家名稱的由來。客家人多分布於福建、江西、湖南、廣東交界的地區，以及廣西、四川若干縣；今臺灣屏東、高雄、苗栗、新竹、桃園等地居民亦多為廣東遷來之客家人。客家人在聚居地區保持自己的習俗傳統，勤勞積極；其山歌別具風格。"]],"客廳":[["ㄎㄜˋ ㄊㄧㄥ","用來接待賓客的場所。[例]媽媽插了盆花，擺在客廳的大桌上。"]],"客戶":[["ㄎㄜˋ ㄏㄨˋ","顧客。[例]他是我們公司的大客戶，你要小心應付，別把他給惹毛了。"]],"客棧":[["ㄎㄜˋ ㄓㄢˋ","舊時供人休息、住宿的旅店。[例]這家餐館刻意布置成古代客棧的模樣，以招攬顧客。"]],"宣傳":[["ㄒㄩㄢ ㄔㄨㄢˊ","1.公開傳播宣揚，使眾人知曉。[例]這部影片的主角近日將隨片來臺，進行宣傳。\n2.為使大眾知曉而進行的傳播活動。[例]這部電影的宣傳做得很好，以致於未演先轟動。\n3.唱片公司中為歌手安排各項傳播等事宜的人。[例]他是這位名歌手的宣傳，幹練又有衝勁。"]],"宣洩":[["ㄒㄩㄢ ㄒㄧㄝˋ","疏導發洩。[例]輔導老師指導學生利用正當管道宣洩情緒。"]],"宣讀":[["ㄒㄩㄢ ㄉㄨˊ","當眾高聲朗讀。[例]宣讀誓言、宣讀遺囑"]],"室內":[["ㄕˋ ㄋㄟˋ","屋裡。[例]室內網球場、室內游泳池"]],"宮殿":[["ㄍㄨㄥ ㄉㄧㄢˋ","帝王居住的房屋。[例]這個文化古都保存了許多宮殿遺址，很值得參觀。"]],"害怕":[["ㄏㄞˋ ㄆㄚˋ","1.心中恐懼不安。[例]他講的鬼故事，令大家感到十分害怕。\n2.心中感到恐懼不安。[例]第一次參加跳傘訓練，他害怕得雙腿發軟，幾乎無法站穩。　◎"]],"害羞":[["ㄏㄞˋ ㄒㄧㄡ","不好意思，難為情。[例]她只要一害羞，馬上滿臉通紅，不知所措。　◎"]],"宴會":[["ㄧㄢˋ ㄏㄨㄟˋ","設置筵席款待賓客的聚會。[例]今晚的宴會有許多貴賓蒞臨，增添了不少光采。"]],"宵禁":[["ㄒㄧㄠ ㄐㄧㄣˋ","戒嚴時期，限制行人及車輛在夜晚外出的禁令。[例]當地因為發生叛軍政變，政府隨即宣布實施宵禁。"]],"家事":[["ㄐㄧㄚ ㄕˋ","家中的日常事務。[例]家事應該由家人一起分擔。_x000D_"]],"家喻戶曉":[["ㄐㄧㄚ ㄩˋ ㄏㄨˋ ㄒㄧㄠˇ","家家戶戶都知道，形容事情或名聲傳布極廣。[例]她是家喻戶曉的大明星，因此一舉一動都格外引人注目。"]],"家家酒":[["ㄐㄧㄚ ㄐㄧㄚ ㄐㄧㄡˇ","小孩子模仿、扮演家庭事務的遊戲。[例]小孩子們玩家家酒時，學大人的模樣真是可愛。"]],"家庭":[["ㄐㄧㄚ ㄊㄧㄥˊ","一種以婚姻、血緣、收養或同居等關係為基礎而形成的共同生活單位。[例]現代社會中家庭形態已非常多元。"]],"家庭醫師":[["ㄐㄧㄚ ㄊㄧㄥˊ ㄧ ㄕ","照顧家庭各成員健康的第一線醫師。通常由社區中開業的全科醫師，或衛生機構的醫師來擔當。"]],"家徒四壁":[["ㄐㄧㄚ ㄊㄨˊ ㄙˋ ㄅㄧˋ","家中只剩四面牆壁。形容家境貧困，一無所有。[例]即使家徒四壁，他仍積極進取，不向環境低頭。"]],"家教":[["ㄐㄧㄚ ㄐㄧㄠˋ","1.家庭中的禮法或指父母對子女的管教。[例]小明待人謙恭有禮，一看就知道是個有家教的孩子。\n2.指家庭教師。[例]爸爸打算請一位家教來幫弟弟補習功課。"]],"家譜":[["ㄐㄧㄚ ㄆㄨˇ","記載一家世系及重要人物事蹟的書。[例]父親按家譜的排行為孩子命名。"]],"家道中落":[["ㄐㄧㄚ ㄉㄠˋ ㄓㄨㄥ ㄌㄨㄛˋ","家境不如往昔富貴。[例]自從父親死後，家道中落，他與母親二人相依為命。"]],"家鄉":[["ㄐㄧㄚ ㄒㄧㄤ","故鄉。[例]他打算畢業後回到家鄉任教。"]],"家鄉味":[["ㄐㄧㄚ ㄒㄧㄤ ㄨㄟˋ","家鄉的風味。也指具有家鄉風味的食物。[例]老李只要犯了鄉愁，就來找我媽媽要點家鄉味吃。"]],"容器":[["ㄖㄨㄥˊ ㄑㄧˋ","盛物品的器皿。[例]停水前，居民用各式各樣的容器貯水備用。"]],"容忍":[["ㄖㄨㄥˊ ㄖㄣˇ","包容、忍耐。[例]感謝老師寬宏大量，容忍我的無禮。"]],"容易":[["ㄖㄨㄥˊ ㄧˋ","不困難。[例]這次考試的試題很容易，大家應該能獲得高分。"]],"容納":[["ㄖㄨㄥˊ ㄋㄚˋ","包容、接受。[例]這間教室很寬敞，容納百人，不成問題。"]],"容貌":[["ㄖㄨㄥˊ ㄇㄠˋ","面貌、相貌。[例]張將軍容貌清瘦，全無武人粗豪之氣。"]],"容量":[["ㄖㄨㄥˊ ㄌㄧㄤˋ","1.中空容器所能容物的量。[例]這個冰箱的容量很大，可冷藏大量的食物。\n2.容納的數量。[例]電容量、熱容量"]],"寂寞":[["ㄐㄧˊ ㄇㄛˋ","孤單冷清。[例]由於父母忙於事業，他又是獨子，因此常感到寂寞。"]],"寂寥":[["ㄐㄧˊ ㄌㄧㄠˊ","1.寂靜冷清。[例]寒冷的冬夜，街上顯得特別寂寥。\n2.寂寞空虛。[例]妻子去世後，他的日子過得很寂寥。"]],"寂靜":[["ㄐㄧˊ ㄐㄧㄥˋ","安靜無聲。[例]寂靜的夜裡，家人都安然入夢，感覺無比的恬然祥和。"]],"寄居蟹":[["ㄐㄧˋ ㄐㄩ ㄒㄧㄝˋ","動物名。節肢動物門甲殼綱寄居蟹科。廣布於全世界。寄居在空螺殼內，頭、胸部堅硬，腹部柔軟，有兩對觸角，第二對特長；足四對，第四對在腹部末端，可用以鉤住空殼。在熱帶島嶼中，有些寄居蟹則居住在椰殼中。[例]寄居蟹每隔一段時間便會尋找新的空螺殼，以容納長大的身軀。　◎"]],"密令":[["ㄇㄧˋ ㄌㄧㄥˋ","機密的命令。[例]部隊在接獲上級的密令之後，立即前往指定地點部署作戰。"]],"密切":[["ㄇㄧˋ ㄑㄧㄝˋ","1.親密、切近。[例]關係密切\n2.嚴密、仔細。[例]密切注意"]],"密合":[["ㄇㄧˋ ㄏㄜˊ","1.十分符合。[例]他們倆的供詞十分密合，因此警方宣告全案偵結，移送法辦。\n2.嚴密閉合。[例]因為紗窗很密合，不怕蚊子飛進來。"]],"密集":[["ㄇㄧˋ ㄐㄧˊ","稠密集結的。[例]臺北是人口密集的大都市。"]],"富國強兵":[["ㄈㄨˋ ㄍㄨㄛˊ ㄑㄧㄤˊ ㄅㄧㄥ","國家富有、軍力強大。[例]唐朝在太宗的經營下，成為一個富國強兵的泱泱大國。"]],"富庶":[["ㄈㄨˋ ㄕㄨˋ","物資豐富，人口眾多。[例]全民同心齊力的奮鬥使國家富庶，人民生活水準提高。"]],"富翁":[["ㄈㄨˋ ㄨㄥ","財富很多的人。[例]他是一位家財萬貫的富翁，但生活卻非常節儉。"]],"富裕":[["ㄈㄨˋ ㄩˋ","錢財充足。[例]他的家境十分富裕，從小就不愁吃穿。"]],"富饒":[["ㄈㄨˋ ㄖㄠˊ","富足充裕。[例]嘉南平原土壤肥沃，物產富饒。"]],"富麗堂皇":[["ㄈㄨˋ ㄌㄧˋ ㄊㄤˊ ㄏㄨㄤˊ","絢爛美麗、氣勢宏偉。[例]大廳上雕梁畫棟，一派富麗堂皇的景象。"]],"寒冬":[["ㄏㄢˊ ㄉㄨㄥ","嚴冷的冬天。[例]許多動物利用睡眠度過寒冬。"]],"寒冷":[["ㄏㄢˊ ㄌㄥˇ","氣候非常的冷。[例]今年的冬天特別寒冷。"]],"寓意":[["ㄩˋ ㄧˋ","寄託、隱含的意旨。[例]這個故事寓意深遠，發人深思。"]],"寓教於樂":[["ㄩˋ ㄐㄧㄠˋ ㄩˊ ㄌㄜˋ","在娛樂中隱含教育的作用。[例]這部電影寓教於樂，很適合小孩觀賞。"]],"寓言":[["ㄩˋ ㄧㄢˊ","以淺近假託的故事或自然物的擬人手法，表達某種哲理或隱含訓誨教育作用的文體。[例]《伊索寓言》"]],"寡欲":[["ㄍㄨㄚˇ ㄩˋ","對物質的欲求寡少。[例]清心寡欲"]],"實在":[["ㄕˊ ㄗㄞˋ","1.真實、不虛假。[例]大姐經營的餐廳因價格實在而生意興隆。\n\t\n2.誠實、可靠。[例]李先生為人很實在。\n\t\n3.的確。[例]他這種捨己助人的精神實在令人感動。"]],"實踐":[["ㄕˊ ㄐㄧㄢˋ","實行、履行。[例]無論待人處事都必須實踐忠信之德，才能在社會上立足。"]],"實驗":[["ㄕˊ ㄧㄢˋ","1.科學上為了要明瞭某種現象或驗證某種假設、理論，用各種方法反覆試驗，並觀察其變化。[例]這項藥品的療效目前仍在實驗中。\n2.為明瞭某種現象或理論，用各種方法反覆試驗的過程。[例]今天老師要教我們做一項化學實驗。"]],"寧死不屈":[["ㄋㄧㄥˊ ㄙˇ ㄅㄨˋ ㄑㄩ","寧願犧牲生命，也不屈服。[例]雖然敵人武力強大，但是全國軍民都抱著寧死不屈的決心，奮戰到底。"]],"寧靜":[["ㄋㄧㄥˊ ㄐㄧㄥˋ","安靜、平和。[例]走在寧靜的街道上，晚風徐徐吹來，舒服極了。"]],"寨主":[["ㄓㄞˋ ㄓㄨˇ","舊指占山為寇的盜賊首領。"]],"審查":[["ㄕㄣˇ ㄔㄚˊ","詳細勘驗檢查。"]],"寫稿":[["ㄒㄧㄝˇ ㄍㄠˇ","寫作文章。[例]他以替專欄寫稿為業。"]],"寬容":[["ㄎㄨㄢ ㄖㄨㄥˊ","寬恕、包容。[例]法律之前人人平等，絕不寬容高官要人玩法弄權。"]],"寬廣":[["ㄎㄨㄢ ㄍㄨㄤˇ","面積或範圍廣大。[例]新闢的公園占地寬廣，公共設施相當完善，是休閒的好去處。"]],"寬裕":[["ㄎㄨㄢ ㄩˋ","富足、充裕。[例]他們夫婦合力打拼，一家生活逐漸寬裕起來。"]],"寬闊":[["ㄎㄨㄢ ㄎㄨㄛˋ","寬廣遼闊。[例]寬闊平坦的嘉南平原堪稱是臺灣的糧倉。"]],"寬鬆":[["ㄎㄨㄢ ㄙㄨㄥ","1.寬大、鬆弛。[例]運動時穿著寬鬆的衣服，可讓肢體盡情伸展。\n2.指錢財充裕。[例]不要因為剛領薪水，手頭寬鬆，就隨便亂花錢。"]],"寵物":[["ㄔㄨㄥˇ ㄨˋ","因喜愛而於家中飼養的動物。如狗、貓、鳥、兔子等。[例]公寓大廈裡通常禁止住戶飼養寵物。"]],"寶剎":[["ㄅㄠˇ ㄔㄚˋ","對寺院的敬稱。[例]今日來到佛光寶剎，猶如登臨佛土淨界。"]],"寶劍":[["ㄅㄠˇ ㄐㄧㄢˋ","稀有珍貴的劍。[例]寶劍贈英雄"]],"寶庫":[["ㄅㄠˇ ㄎㄨˋ","1.珍藏寶貴物品的地方。[例]故宮不僅是收藏文物的寶庫，也是知識的寶庫。\n2.比喻物產豐富的地方。[例]由於水質良好、氣候適宜，使得本地成為各種食材的寶庫。"]],"寶玉":[["ㄅㄠˇ ㄩˋ","珍貴的玉石。[例]通靈寶玉、珍珠寶玉"]],"寶藏":[["ㄅㄠˇ ㄗㄤˋ","1.蘊藏於大自然中珍貴的天然資源。[例]大自然中的寶藏並非取之不盡，人類應該懂得珍惜。\n2.珍藏的貴重物品。[例]敦煌寶藏、故宮寶藏"]],"寶貝":[["ㄅㄠˇ ㄅㄟˋ","1.動物名。軟體動物門腹足綱。棲於海濱岩礁，殼可作裝飾用。\n2.貴重的物品。[例]這些書是她的寶貝，任何人都不可擅動。\n3.特別寵愛或想念的人。常用來稱呼兒女或戀人。[例]媽媽常說我是她的心肝寶貝。\n4.謔稱機靈逗趣的人。[例]他是我們班上的寶貝，常逗大夥兒開心。"]],"寶貴":[["ㄅㄠˇ ㄍㄨㄟˋ","珍貴、極有價值。[例]從書本中我們可以得到許多寶貴的知識。"]],"寺廟":[["ㄙˋ ㄇㄧㄠˋ","佛寺或廟宇的通稱。[例]他經常上寺廟禮佛，祈求家人平安順心。"]],"寺院":[["ㄙˋ ㄩㄢˋ","佛寺的通稱。[例]這間寺院歷史悠久，香火鼎盛。　△寺廟"]],"封面":[["ㄈㄥ ㄇㄧㄢˋ","書籍雜誌等的外層。[例]這本書的封面設計很別緻。"]],"將來":[["ㄐㄧㄤ ㄌㄞˊ","未來，尚未到的時間。[例]只要你好好用功，將來一定可以考取好的學校。"]],"將要":[["ㄐㄧㄤ ㄧㄠˋ","即將、快要。[例]時序將要入冬，天氣已經漸漸轉涼了。"]],"將計就計":[["ㄐㄧㄤ ㄐㄧˋ ㄐㄧㄡˋ ㄐㄧˋ","利用對方的計策反過來對付他。[例]對方既然有意刺探機密，咱們就將計就計，給他一個假情報。"]],"將軍":[["ㄐㄧㄤ ㄐㄩㄣ","1.泛指軍中的高級將領。如漢代有大將軍、驃騎將軍等。今指軍隊中，少將以上的高級武官。[例]王將軍一生馳騁沙場，功業彪炳。\n2.下象棋時，攻擊對方的將或帥，稱為「將軍」。[例]爺爺的一記將軍，讓哥哥輸得口服心服。"]],"將領":[["ㄐㄧㄤˋ ㄌㄧㄥˇ","1.泛指高級軍官。[例]這位將領驍勇善戰，每回出兵必立戰功。\n2.率領。[例]他將領精兵五千，一舉消滅叛賊的巢穴。"]],"專一":[["ㄓㄨㄢ ㄧ","心神專注，心無二用。[例]他上課總是心神專一的聽講。"]],"專家":[["ㄓㄨㄢ ㄐㄧㄚ","精於某種學術或技藝的人。[例]他是考古學的專家，對中國古物有很精深的研究。"]],"專心":[["ㄓㄨㄢ ㄒㄧㄣ","專一心思，集中心力。[例]學生在讀書學習時要專心，才能獲得好成績。"]],"專業":[["ㄓㄨㄢ ㄧㄝˋ","專門研究某種學業或從事某種事業。[例]他的專業知識豐富，常受邀到各地演講。"]],"專注":[["ㄓㄨㄢ ㄓㄨˋ","專心注意。[例]他心神專注的看書，絲毫不受外界影響。"]],"專長":[["ㄓㄨㄢ ㄔㄤˊ","專門而擅長的學問、技能。[例]張老師的專長是書法，所以每次上課時，都在強調書法的重要。"]],"專門":[["ㄓㄨㄢ ㄇㄣˊ","1.專精某一門技藝或學術。[例]這位學者專門研究教育問題。\n2.特地。[例]他專門從遠地趕回來探望父母親。"]],"尊嚴":[["ㄗㄨㄣ ㄧㄢˊ","不容侵犯的身分或地位。[例]即使身處逆境，他依然保持著自己的尊嚴，不輕易低頭。"]],"尊敬":[["ㄗㄨㄣ ㄐㄧㄥˋ","尊崇、敬重。[例]他忘我無私的奉獻精神，令人尊敬。"]],"尊稱":[["ㄗㄨㄣ ㄔㄥ","尊敬的稱呼。[例]「令尊」是對別人父親的尊稱。"]],"尊重":[["ㄗㄨㄣ ㄓㄨㄥˋ","敬重、重視。[例]孩子大了，父母要尊重孩子的隱私，不可私自翻閱他們的日記、書信。"]],"尋幽訪勝":[["ㄒㄩㄣˊ ㄧㄡ ㄈㄤˇ ㄕㄥˋ","尋找探求景色清雅的地方。[例]我們已玩遍島內風景區，這次想到外島去尋幽訪勝。"]],"尋找":[["ㄒㄩㄣˊ ㄓㄠˇ","找尋。[例]小陳滿處尋找他的眼鏡，最後才發現它竟然在自己的口袋裡。"]],"對付":[["ㄉㄨㄟˋ ㄈㄨˋ","應付。[例]他總是有辦法對付各種突發情況，令人不得不佩服。"]],"對比":[["ㄉㄨㄟˋ ㄅㄧˇ","兩種相反的觀念或事物，互相比較對照，使其特徵更加明顯。[例]他們兩人站在一起，一黑一白形成強烈的對比。"]],"對症下藥":[["ㄉㄨㄟˋ ㄓㄥˋ ㄒㄧㄚˋ ㄧㄠˋ","1.針對病症開方用藥。[例]經過醫生對症下藥，病人高燒已退。\n2.比喻針對問題做有效處理。[例]關於這件事，我們要找出問題癥結，才好對症下藥。"]],"對答":[["ㄉㄨㄟˋ ㄉㄚˊ","回答。[例]面對消費者的諮詢，客服人員一一對答，非常敬業。"]],"對話":[["ㄉㄨㄟˋ ㄏㄨㄚˋ","1.相互間的交談語句。[例]這部小說中人物的對話非常生動。\n2.一向沒有聯繫的國家、政府之間的接觸、談判。[例]以阿之間的對話，往往具有衝突性。"]],"對調":[["ㄉㄨㄟˋ ㄉㄧㄠˋ","互相調換。[例]對調座位、對調工作"]],"對錯":[["ㄉㄨㄟˋ ㄘㄨㄛˋ","正確或錯誤。[例]有時候事情是沒有絕對的對錯的。"]],"導正":[["ㄉㄠˇ ㄓㄥˋ","引導匡正。[例]優良的讀物可以導正思想。"]],"導熱":[["ㄉㄠˇ ㄖㄜˋ","熱能從溫度高的部分傳送到溫度低的部分，稱為「導熱」。[例]鋁因易於導熱，而被大量製造成廚房用具。"]],"導盲磚":[["ㄉㄠˇ ㄇㄤˊ ㄓㄨㄢ","鋪在地面上，用以引導盲人行進的磚塊。磚上有平面、直線、斜線、圓點等不同的紋路，表前進方向、危險或暫停等指示。[例]目前在人行道上，大都設有導盲磚，以引導盲人前進。"]],"導致":[["ㄉㄠˇ ㄓˋ","促成、引起。[例]他們夫妻倆因長期溝通不良而導致分手。"]],"導航":[["ㄉㄠˇ ㄏㄤˊ","1.引導航行的方向。利用電子儀器或由其他方法，使控制臺與航空器、船艦或飛彈等保持訊號聯繫，而由控制臺以人工或機器導引其飛航的方向。現代多用雷達導航、紅外線導航等。[例]無線電波遇到物體會反射回來的原理，可以用來導航。\n2.引申為指引行事的方向。[例]老師們經常為學生做升學導航的輔導。"]],"導遊":[["ㄉㄠˇ ㄧㄡˊ","專門引導觀光客遊覽的從業人員。大多經過專業訓練，對遊覽勝地的景觀與人文背景有深入了解，並多精通兩國以上的語言，隨時對旅客解說，以增進遊興。[例]導遊的素質，關係著旅遊的品質水準。"]],"導電":[["ㄉㄠˇ ㄉㄧㄢˋ","傳導、傳送電流。[例]金屬器材通常會被作為導電的工具。"]],"小伙子":[["ㄒㄧㄠˇ ㄏㄨㄛˇ ˙ㄗ","年輕男子。[例]李老先生每天爬山健行，體力比小伙子還好。"]],"小偷":[["ㄒㄧㄠˇ ㄊㄡ","竊賊。[例]他們合力抓住小偷，將其扭送警局。"]],"小姐":[["ㄒㄧㄠˇ ㄐㄧㄝˇ","1.社交場合中對女性的稱呼。[例]小姐，請問博物館怎麼走？_x000D_\n2.舊時僕人對主人女兒的稱呼。今亦用於敬稱他人的女兒。[例]大小姐、千金小姐"]],"小徑":[["ㄒㄧㄠˇ ㄐㄧㄥˋ","小路。[例]羊腸小徑"]],"小心":[["ㄒㄧㄠˇ ㄒㄧㄣ","留心、謹慎。[例]天乾物燥，小心火燭。"]],"小心翼翼":[["ㄒㄧㄠˇ ㄒㄧㄣ ㄧˋ ㄧˋ","形容非常小心謹慎，不敢疏忽。[例]我小心翼翼地將熱湯端上桌，深怕湯汁溢出燙傷手。"]],"小提琴":[["ㄒㄧㄠˇ ㄊㄧˊ ㄑㄧㄣˊ","樂器名。由早期的弓弦樂器發展而來。琴身主要是由一個木製的共鳴箱及一個長的琴桿所構成，正中央有四根弦，是小提琴的發聲來源。音色優美，是理想的獨奏樂器，亦適用於合奏。[例]餐會上那段小提琴的獨奏表演，贏得滿堂彩。"]],"小販":[["ㄒㄧㄠˇ ㄈㄢˋ","從事小買賣的生意人。[例]傍晚時分，小販們便陸續聚集在廟口，成了一處熱鬧的夜市。"]],"少女":[["ㄕㄠˋ ㄋㄩˇ","年輕的未婚女子。[例]她是個活力無限、青春洋溢的少女。"]],"少年":[["ㄕㄠˋ ㄋㄧㄢˊ","1.年輕。[例]勸君莫惜金縷衣，勸君惜取少年時。（唐．杜秋娘〈金縷衣〉詩）\n2.年輕的男子。[例]做一個新時代的少年，更要有為國為民的服務熱忱。"]],"少數":[["ㄕㄠˇ ㄕㄨˋ","不多，數量較少的。相對於多數而言。[例]少數服從多數，是民主風範的表現。"]],"少爺":[["ㄕㄠˋ ㄧㄝˊ","稱謂：(1) 舊時僕人對少主人的稱呼。[例]少爺，您要的東西，我都替您準備好了。 (2) 舊時尊稱他人的兒子。[例]您家少爺在哪兒高就呢？ (3) 稱特種營業場所的男性服務員。[例]酒店少爺"]],"少量":[["ㄕㄠˇ ㄌㄧㄤˋ","分量、數量不多的。[例]這湯若加上少量的鹽，味道會更美。"]],"尖銳":[["ㄐㄧㄢ ㄖㄨㄟˋ","1.尖而銳利。[例]這把刀子非常尖銳，要小心使用。\n2.形容聲音尖細刺耳。[例]隔壁傳來一陣陣尖銳的叫聲，淒厲異常。\n3.形容說話言辭鋒利，毫不留情。[例]她的批評，言辭雖然尖銳，但卻十分中肯。"]],"尚未":[["ㄕㄤˋ ㄨㄟˋ","還沒有。[例]事情尚未到不可收拾的地步，何必氣餒呢？"]],"尤其":[["ㄧㄡˊ ㄑㄧˊ","格外。[例]為了完成這份工作，大家都很賣力，尤其是她。"]],"就任":[["ㄐㄧㄡˋ ㄖㄣˋ","到職。[例]他就任後第一件事，便是革新公司的人事制度。"]],"就職":[["ㄐㄧㄡˋ ㄓˊ","正式上任。[例]今天是他的就職報到日。"]],"尷尬":[["ㄍㄢ ㄍㄚˋ","1.不好意思、難為情。[例]說話不經思考就脫口而出，常會造成尷尬的場面。\n2.處境困窘或事情棘手，難以應付。[例]主席面對雙方提出的意見，顯得很尷尬，不知如何處理。"]],"尺度":[["ㄔˇ ㄉㄨˋ","既定的範圍或標準。[例]檢查尺度、放寬尺度"]],"尼羅河":[["ㄋㄧˊ ㄌㄨㄛˊ ㄏㄜˊ","發源於東非高原的一條河流。上游的白尼羅河與藍尼羅河在蘇丹喀土木會流，成為尼羅河主流。流經蒲隆地、坦尚尼亞、盧安達、薩伊、肯亞、烏干達、蘇丹、衣索比亞、埃及等國，下游在埃及開羅附近進入尼羅河三角洲，注入地中海。全長約6648公里，為世界最長的河流。每年定期氾濫，使沿岸土壤更加肥沃。河口三角洲是世界古文明發祥地之一。[例]古埃及文明發源於尼羅河，對近代西方文化的發展有重大影響。"]],"尾巴":[["ㄨㄟˇ ㄅㄚ","1.動物或物體末梢突出的部分。[例]狗尾巴、飛機尾巴\n\t\n2.比喻尾隨附和的人。[例]他很有主見，從不當別人的尾巴。\n\t\n3.事情未了結的部分。[例]他做事總愛留個尾巴，讓人來收尾。"]],"尾鰭":[["ㄨㄟˇ ㄑㄧˊ","魚類脊椎末端突出的鰭，為魚類游泳動力的來源。[例]這條魚的尾鰭受傷了，以致難以游動。"]],"尿尿":[["ㄋㄧㄠˋ ㄋㄧㄠˋ","排尿。[例]弟弟在睡覺前一定要先去廁所尿尿。"]],"局部":[["ㄐㄩˊ ㄅㄨˋ","全體中的一部分。[例]局部麻醉"]],"居住":[["ㄐㄩ ㄓㄨˋ","長期住在一處。[例]他們世世代代都居住在那裡，對當地的風俗民情十分了解。"]],"居民":[["ㄐㄩ ㄇㄧㄣˊ","固定居住在某一地方的人民。[例]自從居民與警方合作打擊犯罪之後，這個社區的治安已明顯的改善。"]],"居然":[["ㄐㄩ ㄖㄢˊ","竟然，表示出乎意料。[例]沒想到他居然會說出這種話來！"]],"居高臨下":[["ㄐㄩ ㄍㄠ ㄌㄧㄣˊ ㄒㄧㄚˋ","位在高處，可向下俯視。或比喻處於有利的地位。[例]這個城市居高臨下，易守難攻，自古以來即為軍事堡壘。"]],"屈意奉承":[["ㄑㄩ ㄧˋ ㄈㄥˋ ㄔㄥˊ","屈意、委屈自己的意思。奉承、討好別人。屈意奉承指低聲下氣的討好別人。[例]他對老闆一味的屈意奉承，真讓人感到肉麻。"]],"屈打成招":[["ㄑㄩ ㄉㄚˇ ㄔㄥˊ ㄓㄠ","用嚴刑拷打，逼迫人招供認罪。[例]辦案偵訊要講技巧，不可屈打成招。"]],"屈服":[["ㄑㄩ ㄈㄨˊ","曲身降服。[例]在他的強大壓力之下，眾人不得不屈服。"]],"屈死":[["ㄑㄩ ㄙˇ","含冤受屈而死。[例]這齣戲演到主角屈死時，臺下的觀眾不禁發出嘆息聲。"]],"屈膝":[["ㄑㄩ ㄒㄧ","下跪。比喻屈服、投降。[例]即使戰到只剩一兵一卒，我們也不願屈膝求饒！"]],"屈辱":[["ㄑㄩ ㄖㄨˋ","委曲侮辱。[例]對他而言，放棄個人的自尊就是一項莫大的屈辱。"]],"屋頂":[["ㄨ ㄉㄧㄥˇ","建築物最上面覆蓋的部分。具有防風、雨、雪及抵擋陽光等功能。[例]每逢晴天，陽光便從屋頂的天窗透進來。"]],"屏息":[["ㄅㄧㄥˇ ㄒㄧˊ","抑止呼吸，止住聲息。[例]屏息靜觀"]],"屏氣凝神":[["ㄅㄧㄥˇ ㄑㄧˋ ㄋㄧㄥˊ ㄕㄣˊ","屏住呼吸，集中精神。謂專心一意。[例]在她演唱時，廳內所有的人都屏氣凝神，不敢稍微動一下。"]],"屏障":[["ㄆㄧㄥˊ ㄓㄤˋ","1.遮蔽、護衛。[例]中央山脈屏障著臺灣西部，能降低颱風帶來的災害。\n2.像屏風一樣有遮蔽保衛作用的東西，通常指山嶺、島嶼、江河或大型物體等。[例]萬里長城橫亙在中國北方，曾經是抵禦外族入侵的重要屏障。"]],"展延":[["ㄓㄢˇ ㄧㄢˊ","延長。[例]經房東同意，我們可以把租金展延到下個月才繳納。"]],"展現":[["ㄓㄢˇ ㄒㄧㄢˋ","展示顯現。[例]爬上山頂，繁華的城鎮就展現在眼前。"]],"展示":[["ㄓㄢˇ ㄕˋ","展現、陳列。[例]新車展示、樣品屋展示"]],"展緩":[["ㄓㄢˇ ㄏㄨㄢˇ","延期。[例]自強活動的行程因為天候不佳而一再展緩。"]],"展翅":[["ㄓㄢˇ ㄔˋ","張開翅膀飛翔。[例]經過多次的撲墜地面，小鳥終於能展翅高飛翱翔天際了。"]],"展覽":[["ㄓㄢˇ ㄌㄢˇ","陳列物品供人觀賞。[例]美術展覽、服裝展覽"]],"展開":[["ㄓㄢˇ ㄎㄞ","1.舒展、打開。[例]紮完營後他把睡袋展開，準備先休息一下。\n2.擴大或大規模進行。[例]競選的宣傳活動正熱烈的展開中。"]],"屢屢":[["ㄌㄩˇ ㄌㄩˇ","常常。[例]他的作品多以家國情懷為主題，屢屢勾起遊子的鄉愁，引發共鳴。"]],"屢試不爽":[["ㄌㄩˇ ㄕˋ ㄅㄨˋ ㄕㄨㄤˇ","爽，差錯。屢試不爽指經過多次試驗都沒有差錯。[例]這個方法十分有效，屢試不爽。"]],"層層":[["ㄘㄥˊ ㄘㄥˊ","一層又一層的樣子。[例]風一吹，田裡的稻浪就層層起伏。"]],"層巒疊嶂":[["ㄘㄥˊ ㄌㄨㄢˊ ㄉㄧㄝˊ ㄓㄤˋ","山峰重疊，連綿不斷。[例]中央山脈層巒疊嶂，甚為雄偉。"]],"屬地":[["ㄕㄨˇ ㄉㄧˋ","帝國主義國家，在本國以外占據的殖民地，或控制的附屬國。[例]印度半島從前是英國的屬地。"]],"屬於":[["ㄕㄨˇ ㄩˊ","隸屬、歸於、關於。[例]這個問題屬於哲學的範疇，必須細心考究思辨。"]],"山丘":[["ㄕㄢ ㄑㄧㄡ","較低的山。[例]山丘上有座涼亭，供遊客歇腳。"]],"山坡":[["ㄕㄢ ㄆㄛ","山頂與平地間的斜面地帶。[例]我家門前有小河，後面有山坡，山坡上有野花朵，野花紅似火。"]],"山城":[["ㄕㄢ ㄔㄥˊ","位於山中或多山的城鎮。[例]這座山城有古樸的街景，吸引了許多劇組前來取景。"]],"山寨":[["ㄕㄢ ㄓㄞˋ","舊指強盜土匪聚集的地方。[例]過去常有一些匪徒聚集成黨，扎下山寨，佔地為王。"]],"山峰":[["ㄕㄢ ㄈㄥ","山的頂端。[例]我登上山峰向遠處眺望，四方景物，盡收眼底。"]],"山崗":[["ㄕㄢ ㄍㄤ","較低的山。[例]雁群們飛越山崗往南方過冬。"]],"山巒":[["ㄕㄢ ㄌㄨㄢˊ","連綿的山。[例]這一帶山巒起伏，氣勢雄偉。"]],"山巔":[["ㄕㄢ ㄉㄧㄢ","山的頂端。[例]清晨太陽露出山巔，光芒四射，照亮大地。"]],"山明水秀":[["ㄕㄢ ㄇㄧㄥˊ ㄕㄨㄟˇ ㄒㄧㄡˋ","形容山水秀麗，風景優美。[例]西湖一帶山明水秀，遊人如織。"]],"山洞":[["ㄕㄢ ㄉㄨㄥˋ","山中的洞穴。[例]小說西遊記中，美猴王居住的山洞，名為水簾洞。"]],"山澗":[["ㄕㄢ ㄐㄧㄢˋ","兩山間的流水。[例]山區雨量豐沛，山澗終年不虞枯竭。"]],"山羊":[["ㄕㄢ ㄧㄤˊ","動物名。哺乳綱偶蹄目。體形似綿羊而較狹，頭長頸短，額有角一對，角尖向後，略呈三角形。四肢強壯，善於跳躍。毛直而不捲，公羊頷下有長鬚。毛皮可用來製衣褥。[例]這座農場專門飼養山羊，利潤極高。 ◎"]],"山脈":[["ㄕㄢ ㄇㄞˋ","山巒相連並依一定方向起伏延伸，狀似脈絡而成系統的山群。[例]崑崙山脈、陰山山脈、中央山脈"]],"山腳":[["ㄕㄢ ㄐㄧㄠˇ","山下靠近平地的地方。[例]山腳下有座佛寺，香火鼎盛。"]],"山谷":[["ㄕㄢ ㄍㄨˇ","兩山之間低下而狹窄的地方。[例]深山中人跡罕至，只在山谷裡偶見村落。"]],"山頂":[["ㄕㄢ ㄉㄧㄥˇ","山的頂端，最高的地方。[例]每到冬天，玉山山頂白雪皚皚，總吸引不少遊客。"]],"屹立不搖":[["ㄧˋ ㄌㄧˋ ㄅㄨˋ ㄧㄠˊ","像高山一樣穩固的聳立著。[例]那棵老樹歷經百年的風吹雨打，至今仍屹立不搖。"]],"岌岌可危":[["ㄐㄧˊ ㄐㄧˊ ㄎㄜˇ ㄨㄟˊ","形容非常危險。[例]這棟古屋在地震之後出現多處裂縫，隨時都有倒塌的可能，情況岌岌可危。"]],"岔口":[["ㄔㄚˋ ㄎㄡˇ","道路交錯或分岔的地方。[例]汽機車行經岔口，應格外小心駕駛，以策安全。"]],"岩層":[["ㄧㄢˊ ㄘㄥˊ","地殼中層狀的岩石。[例]石灰岩層經地下水溶蝕後，會形成石灰岩洞。"]],"岩岸":[["ㄧㄢˊ ㄢˋ","一種海岸線類型。特點為海岸線曲折、多港灣和島嶼，灣闊水深，適宜航運和漁業的發展。[例]臺灣的岩岸主要分布在臺灣北部和東部，如台北野柳、花蓮石梯坪等。"]],"岩漿":[["ㄧㄢˊ ㄐㄧㄤ","地球內部尚在熔融狀態的流體物質。主要成分為矽酸鹽，也含一些氧化物、硫化物、水、氣體等，冷卻後則形成火成岩。[例]火山爆發，噴出岩漿，往往造成鄰近地區的嚴重災害。"]],"岩石":[["ㄧㄢˊ ㄕˊ","構成地球外殼的礦物集合體。可分為火成岩、沉積岩、變質岩三種。是地球上岩石圈的主要物質。[例]爸爸最喜歡蒐集各種形狀的岩石。"]],"岸邊":[["ㄢˋ ㄅㄧㄢ","水邊陸地。[例]出航歸來，他將遊艇繫在岸邊。"]],"峭立":[["ㄑㄧㄠˋ ㄌㄧˋ","山壁陡險。[例]要登上那峭立的崖壁，談何容易！"]],"峰巒":[["ㄈㄥ ㄌㄨㄢˊ","泛指大小山峰。[例]晨霧散去之後，放眼望去，峰巒起伏，綿延不絕。"]],"島嶼":[["ㄉㄠˇ ㄩˇ","四周被水圍繞的小面積陸地。[例]時至今日，地球上仍有許多尚未開發的無人島嶼。"]],"峻峭":[["ㄐㄩㄣˋ ㄑㄧㄠˋ","1.山勢高而陡直。[例]這座山的山勢峻峭，沒有萬全的準備，千萬不要冒然攀登。\n2.比喻人品高超。[例]風格峻峭、風骨峻峭"]],"崇拜":[["ㄔㄨㄥˊ ㄅㄞˋ","尊敬佩服。[例]他從小就非常崇拜父親，一心把父親當作學習的榜樣。"]],"崎嶇":[["ㄑㄧˊ ㄑㄩ","1.地勢或道路高低不平。[例]這條路崎嶇難行，經過的人莫不叫苦連天。_x000D_\n2.比喻處境艱難。[例]雖然前途崎嶇，他仍然充滿信心。"]],"崗位":[["ㄍㄤˇ ㄨㄟˋ","1.軍警執勤的處所。[例]為防止偷渡，海防部隊密置崗位派人守備。\n2.職責、本分。[例]人人應堅守崗位，努力不懈，社會才會進步。"]],"崗哨":[["ㄍㄤˇ ㄕㄠˋ","1.站崗放哨的地方。[例]社區的崗哨對出入的人車都嚴加管制。\n2.站崗放哨的人。[例]他是一個盡忠職守的崗哨。"]],"嶄新":[["ㄓㄢˇ ㄒㄧㄣ","全新、極新。[例]他開了一部嶄新的轎車，引來許多羨慕的眼光。"]],"嶄露頭角":[["ㄓㄢˇ ㄌㄨˋ ㄊㄡˊ ㄐㄧㄠˇ","比喻顯露特出的才華或本領。語本唐．韓愈〈柳子厚墓誌銘〉。[例]由於他的點子多又新穎，很快便在廣告界嶄露頭角。"]],"巔峰":[["ㄉㄧㄢ ㄈㄥ","1.山頂、頂端。[例]這座山的巔峰長年煙靄繚繞，宛若人間仙境。\n2.比喻情況到達最高點。[例]他的人生正值巔峰狀態，卻因染上毒癮，而失去一切。"]],"巡視":[["ㄒㄩㄣˊ ㄕˋ","巡行視察。[例]農夫每天都會到田裡巡視稻苗生長的情形。"]],"巡迴":[["ㄒㄩㄣˊ ㄏㄨㄟˊ","沿一定路線到各處。[例]巡迴演講、巡迴展覽、巡迴演唱會"]],"巡邏":[["ㄒㄩㄣˊ ㄌㄨㄛˊ","到處視察警備。[例]警察進行定點巡邏，以確保轄區的安全。"]],"工作":[["ㄍㄨㄥ ㄗㄨㄛˋ","1.職業。[例]他熱愛導遊的工作。\n2.做事。[例]他在工作的時候不喜歡別人打擾。"]],"工具":[["ㄍㄨㄥ ㄐㄩˋ","1.泛指工作時所用的器具與設備。[例]修車工具、生產工具\n\t\n2.指車輛、船舶、飛機等運輸器具。[例]交通工具、運輸工具。\n\t\n3.比喻為達目的所使用的事物、手段。[例]語言是人們溝通的工具。"]],"工地":[["ㄍㄨㄥ ㄉㄧˋ","進行工程或相關事務的地方。[例]為了保持良好的施工品質，那位建築公司的負責人定期到工地視察。"]],"工廠":[["ㄍㄨㄥ ㄔㄤˇ","將原料或半成品製成成品的地方。[例]鐵工廠、紡織工廠"]],"左思右想":[["ㄗㄨㄛˇ ㄙ ㄧㄡˋ ㄒㄧㄤˇ","反覆的想了又想。[例]面對他人的惡意中傷，他左思右想，卻始終想不出曾經得罪過誰？"]],"左手":[["ㄗㄨㄛˇ ㄕㄡˇ","左邊的手。[例]一般人吃飯通常用左手拿碗，右手拿筷子。"]],"左撇子":[["ㄗㄨㄛˇ ㄆㄧㄝˇ ˙ㄗ","稱習慣使用左手進行日常活動的人。"]],"左轉":[["ㄗㄨㄛˇ ㄓㄨㄢˇ","向左方轉向。[例]前面岔路禁止左轉。"]],"左邊":[["ㄗㄨㄛˇ ㄅㄧㄢ","左側的方向。[例]學校的左邊是一家文具店。"]],"左顧右盼":[["ㄗㄨㄛˇ ㄍㄨˋ ㄧㄡˋ ㄆㄢˋ","東張西望，心中不安的樣子。[例]只看他左顧右盼，坐立不安，不知道發生了什麼事？"]],"巧妙":[["ㄑㄧㄠˇ ㄇㄧㄠˋ","精巧美妙。[例]戲法人人會變，各有巧妙不同。"]],"巧遇":[["ㄑㄧㄠˇ ㄩˋ","湊巧碰上。[例]巡邏警察在執行路檢時，巧遇逃亡多年的通緝犯，立刻予以逮捕歸案。"]],"巨人":[["ㄐㄩˋ ㄖㄣˊ","1.神話或童話中，身軀龐大且具有神力的人。[例]希臘神話中，認為地球是由力大無窮的巨人扛頂著。\n2.身材異常高大的人。多由腦下腺前葉生長激素分泌亢進所引起。[例]巨人異常高大的身材，多是因為遺傳因素所致。\n3.比喻某一領域中，具有巨大影響力的人。[例]他是百貨業界的巨人，全國擁有七十家大型的連鎖公司。"]],"巨大":[["ㄐㄩˋ ㄉㄚˋ","重大、非常大。[例]想不到這城市在短短的兩年間，會有如此巨大的改變。"]],"巨無霸":[["ㄐㄩˋ ㄨˊ ㄅㄚˋ","形容體積高大的人或物。[例]巨無霸長人、巨無霸飛機　△巨毋霸"]],"巨著":[["ㄐㄩˋ ㄓㄨˋ","內容精深、影響力極大，且具重要地位的著作。[例]這家出版社計劃翻譯世界文學巨著，以饗讀者。"]],"巨變":[["ㄐㄩˋ ㄅㄧㄢˋ","重大的改變。[例]雖然家庭遭逢巨變，他仍勇敢的面對未來艱辛的生活。"]],"差不多":[["ㄔㄚ ㄅㄨˋ ㄉㄨㄛ","1.相似、相差有限。[例]她們姊妹倆身材差不多，許多衣服都交換著穿。\n2.大概、大約。[例]這批貨差不多可在一個月內交貨。\n3.表示即將結束、用盡。[例]他每個月的薪水扣掉房租、會錢及基本生活費用就差不多了。"]],"差事":[["ㄔㄞ ㄕˋ","泛指工作、職務。[例]不用工作又有錢可以賺，那有這麼好的差事？"]],"差使":[["ㄔㄞ ㄕˇ","1.派遣。[例]董事長派了四個助手供總經理差使。\n2.原為舊時官場中臨時委任的官職，後亦泛指事情、職務。[例]這個職務是個好的差使，多少人想要都要不到呢！"]],"差別":[["ㄔㄚ ㄅㄧㄝˊ","區別、差異。[例]每種動物的生活習性都有差別。"]],"差勁":[["ㄔㄚ ㄐㄧㄥˋ","不佳、低劣。[例]一個人動作緩慢並不表示他的腦筋很差勁。"]],"差異":[["ㄔㄚ ㄧˋ","差別、不同。[例]若不是髮型有所差異，這對孿生姊妹的外表幾乎一模一樣。"]],"差遣":[["ㄔㄞ ㄑㄧㄢˇ","派遣、分派工作。[例]有什麼事儘管吩咐，我隨時聽候差遣。"]],"差錯":[["ㄔㄚ ㄘㄨㄛˋ","錯誤、過失。[例]酒醉開車，很容易出差錯。"]],"差點兒":[["ㄔㄚ ㄉㄧㄢˇㄦ","1.幾乎。[例]火車站周邊道路嚴重塞車，他差點兒趕不上這班火車。\n\t\n2.較次級的。[例]這塊衣料比起緞子是差點兒，但也稱得上是好的。"]],"已經":[["ㄧˇ ㄐㄧㄥ","表示時間已過，或動作、狀況、事情在某時間之前完成。[例]一大清早，許多人都還在睡夢中，他已經端坐在書房中讀了不少書了。"]],"巴士":[["ㄅㄚ ㄕˋ","可供人搭乘的大型汽車。§英bus[例]公共巴士、遊覽巴士　◎"]],"巷弄":[["ㄒㄧㄤˋ ㄌㄨㄥˋ","泛稱窄小的街道。[例]這個社區巷弄多又雜，不是熟人很容易迷路。"]],"巷道":[["ㄒㄧㄤˋ ㄉㄠˋ","市鎮小型街道的通稱。[例]巷道的清潔需要靠全體居民來共同維持。"]],"市井小民":[["ㄕˋ ㄐㄧㄥˇ ㄒㄧㄠˇ ㄇㄧㄣˊ","城市裡的居民百姓。[例]房屋價格節節高漲，市井小民苦無財力購屋，經常感嘆城市居大不易。"]],"市長":[["ㄕˋ ㄓㄤˇ","治理一市的最高行政首長。[例]臺北市長、基隆市長、彰化市長"]],"布丁":[["ㄅㄨˋ ㄉㄧㄥ","一種用麵粉、奶油、雞蛋、糖等蒸製而成的點心。[例]雞蛋布丁"]],"布告欄":[["ㄅㄨˋ ㄍㄠˋ ㄌㄢˊ","學校或機關團體張貼布告的地方。[例]學校走廊上大多設有布告欄。　◎"]],"布料":[["ㄅㄨˋ ㄌㄧㄠˋ","1.布的質料。[例]由於科技進步，很多化學產品都可以用作布料。\n2.泛指可用以縫製衣服的各種布匹。[例]這種款式的衣服，相當節省布料。"]],"布條":[["ㄅㄨˋ ㄊㄧㄠˊ","裁成條狀的布。[例]抗爭的民眾頭上都綁著白布條。"]],"布置":[["ㄅㄨˋ ㄓˋ","安排配置。[例]我們現正忙著布置晚會場地。"]],"布袋":[["ㄅㄨˋ ㄉㄞˋ","用布製成的袋子。[例]這口布袋是當年離家時，你奶奶親手縫給我的。"]],"帆船":[["ㄈㄢˊ ㄔㄨㄢˊ","1.張掛帆布憑藉風力行駛的船。[例]在蒸汽船尚未發明時，人們多駕駛帆船在海上航行。　◎\n\t\n2.一種駕駛帆船在海上航行或緩航的運動。列入奧運會正式比賽。船型為龍型、索林型、星型、飛行荷蘭人型、芬蘭人型和暴風雨型。每型各舉行七場比賽，選其中六場最好的成績計各船名次。各場第一名得0分，第二名得3分，第三名得5.7分，第四名得8分，第五名得10分，第六名得11.7分，第七名以下的得分為名次加6。以總分最低者得勝。"]],"希望":[["ㄒㄧ ㄨㄤˋ","1.心中有所期盼。[例]父母總是希望自己的小孩將來能有所成就。\n2.內心的期待、指望。[例]他對自己的未來充滿了希望。"]],"希求":[["ㄒㄧ ㄑㄧㄡˊ","希望得到，謀求。[例]自己不努力，而希求高官厚祿，無異是痴人說夢。"]],"帝王":[["ㄉㄧˋ ㄨㄤˊ","舊時稱君主國家的元首。[例]元世祖雄才大略，出兵遠征，為古今帝王所罕見。"]],"師傅":[["ㄕ ㄈㄨˋ","1.皇帝的老師。如太師、太傅、太保、少師、少傅、少保等。今泛指老師。[例]古代教導皇帝的師傅，通常都擁有豐富的學識及人生閱歷。\n2.稱有專門技藝的人。[例]這位做點心的師傅，手藝高超因此遠近馳名。"]],"師長":[["ㄕ ㄓㄤˇ","1.對老師的尊稱。[例]師長的諄諄教誨，促使他及時回頭，重新做人。\n2.在現行軍制中，統率陸軍一師的軍官。[例]這次的軍事演習，由數位師長共同研擬、規劃。"]],"席位":[["ㄒㄧˊ ㄨㄟˋ","1.座位。[例]這次研討會，主辦單位依受邀者的回條，確定席位數目。\n2.政治團體在議會中所占的座位，藉以表示當選的人數。[例]這次選舉，不知道執政黨能獲得多少席位？"]],"帳房":[["ㄓㄤˋ ㄈㄤˊ","1.管理銀錢出入的地方。[例]古代大戶人家都有帳房專管銀錢的出納。\n2.管理銀錢出入的人。[例]這個老帳房忠實可靠，深得主人的信賴。"]],"帳篷":[["ㄓㄤˋ ㄆㄥˊ","可拆卸自由搬運的組合式住宅。由支架及可折疊的皮革、布、塑膠等組合而成，除用於遊牧、狩獵外，亦應用在露營登山、馬戲團等。[例]帳篷是游牧民族逐水草而居的必要配備。"]],"常常":[["ㄔㄤˊ ㄔㄤˊ","指事情發生的頻率很高。[例]假日時爸媽常常帶我們去郊遊。 △經常、時常"]],"常態":[["ㄔㄤˊ ㄊㄞˋ","正常的狀態。[例]家中的小狗一反常態，大聲的吠叫起來，原來是隔壁失火了。"]],"常識":[["ㄔㄤˊ ㄕˋ","一般人所應具備的基本普通知識。[例]生活常識"]],"帽子":[["ㄇㄠˋ ˙ㄗ","戴在頭上，用以遮陽、避雨、保暖或裝飾的用品。[例]這頂帽子的樣式很特別。"]],"幅員":[["ㄈㄨˊ ㄩㄢˊ","疆域的大小。[例]中國地大物博，幅員遼闊，資源相當豐富。"]],"幣值":[["ㄅㄧˋ ㄓˊ","錢幣購買貨物的能力。[例]戰爭常使幣值貶降，造成嚴重的通貨膨脹。"]],"幫忙":[["ㄅㄤ ㄇㄤˊ","幫助他人做事或解決困難。[例]朋友有難應該互相幫忙。"]],"幫手":[["ㄅㄤ ㄕㄡˇ","助手、助理。[例]店裡這麼忙，要不要考慮請一位幫手？"]],"平價":[["ㄆㄧㄥˊ ㄐㄧㄚˋ","平實穩定的價格。[例]平價商店"]],"平均":[["ㄆㄧㄥˊ ㄐㄩㄣ","輕重相等，分量一致。[例]這次聚餐的費用，是由參與的同學平均分攤。"]],"平坦":[["ㄆㄧㄥˊ ㄊㄢˇ","1.沒有凹凸高低。[例]眼前是平坦無際的原野，風景一覽無遺。\n2.比喻沒有困難阻礙。[例]若能克服此類困難，往後一路平坦。"]],"平安":[["ㄆㄧㄥˊ ㄢ","平穩而沒有危險。[例]這艘貨輪已經平安抵達高雄港。"]],"平常":[["ㄆㄧㄥˊ ㄔㄤˊ","1.平日、平時。[例]你平常都走路上學嗎？\n2.普通、平凡，沒有特異之處。[例]平常心、平常人、稀鬆平常"]],"平時":[["ㄆㄧㄥˊ ㄕˊ","平常、平日。[例]平時做足準備，面對挑戰就不會自亂陣腳。"]],"平添":[["ㄆㄧㄥˊ ㄊㄧㄢ","平白增加。[例]霏霏的細雨，為湖面平添一份迷濛的美。"]],"平滑":[["ㄆㄧㄥˊ ㄏㄨㄚˊ","平整光滑。[例]住家的地板應避免過於平滑，否則很容易跌倒摔跤。"]],"平穩":[["ㄆㄧㄥˊ ㄨㄣˇ","平靜安穩，沒有任何驚險或波動。[例]物價平穩、心情平穩"]],"平靜":[["ㄆㄧㄥˊ ㄐㄧㄥˋ","安定詳和。[例]昨天飛機迫降的恐怖經歷，使她的心情一直無法平靜下來。"]],"平順":[["ㄆㄧㄥˊ ㄕㄨㄣˋ","平穩順利。[例]哥哥的求學過程一直很平順，沒遇過什麼挫折。"]],"年代":[["ㄋㄧㄢˊ ㄉㄞˋ","1.時間、時代。[例]年代久遠_x000D_\n2.西洋紀元中，從〇到九每十年稱為一個年代。如二十世紀八〇年代，是指西元1980至1989年。"]],"年初":[["ㄋㄧㄢˊ ㄔㄨ","一年的開頭幾天。[例]我打算年初回老家一趟，探訪親戚故舊。"]],"年夜飯":[["ㄋㄧㄢˊ ㄧㄝˋ ㄈㄢˋ","除夕夜家人團聚所吃的餐宴。[例]一家大小圍著圓桌，吃年夜飯，享天倫樂，溫馨無比。"]],"年幼":[["ㄋㄧㄢˊ ㄧㄡˋ","年紀小。[例]他在年幼的時候，就對音樂產生濃厚的興趣。"]],"年紀":[["ㄋㄧㄢˊ ㄐㄧˋ","年齡。[例]他的年紀雖輕，做起事來倒是相當練達。"]],"年級":[["ㄋㄧㄢˊ ㄐㄧˊ","學校中依據學生的修業年限和課程所分的學級。如國小有六個年級，國中有三個年級。[例]過了暑假，她就已經是高中三年級的學生了。"]],"年菜":[["ㄋㄧㄢˊ ㄘㄞˋ","過年期間所烹調的菜餚。[例]今年的年菜特別精緻，大家都吃得津津有味。"]],"年貨":[["ㄋㄧㄢˊ ㄏㄨㄛˋ","過年時所用的一切物品。[例]快過年了，大家都忙著採購年貨。"]],"年輕":[["ㄋㄧㄢˊ ㄑㄧㄥ","年紀不大。[例]年輕力壯、年輕氣盛"]],"年輕力壯":[["ㄋㄧㄢˊ ㄑㄧㄥ ㄌㄧˋ ㄓㄨㄤˋ","年紀輕，精力充沛。[例]他年輕力壯，能吃苦耐勞。"]],"年輕氣盛":[["ㄋㄧㄢˊ ㄑㄧㄥ ㄑㄧˋ ㄕㄥˋ","年紀輕，血氣強勁。[例]他年輕氣盛，做事較莽撞，請您多多包涵。"]],"年邁":[["ㄋㄧㄢˊ ㄇㄞˋ","年老、年紀大。[例]家母年邁，不堪舟車之苦，無法出國旅行。"]],"年齡":[["ㄋㄧㄢˊ ㄌㄧㄥˊ","年紀、歲數。[例]一個人的年齡常可從他臉上的皺紋大略得知。"]],"幸好":[["ㄒㄧㄥˋ ㄏㄠˇ","幸虧、還好。[例]這一次火災幸好發現得早，才沒有釀成巨大的災害。"]],"幸福":[["ㄒㄧㄥˋ ㄈㄨˊ","指生活、境遇圓滿愉快。[例]追求幸福是人類共同的願望。"]],"幸虧":[["ㄒㄧㄥˋ ㄎㄨㄟ","因某種機運而自困境中獲得解脫。[例]幸虧有至親好友的幫忙，我們才得以度過難關。"]],"幸運":[["ㄒㄧㄥˋ ㄩㄣˋ","好的運氣。[例]他摸彩得到第一特獎，真是幸運。"]],"幹勁":[["ㄍㄢˋ ㄐㄧㄥˋ","做事的熱忱與精力。[例]他做起事來幹勁十足，從不喊累。"]],"幹部":[["ㄍㄢˋ ㄅㄨˋ","統稱政黨等團體裡的主要工作人員。[例]班上的風紀股長是專門協助老師維持秩序的幹部。"]],"幻影":[["ㄏㄨㄢˋ ㄧㄥˇ","虛幻而不真實的影像。[例]一場大火，使他多年來開創的事業，在一夕之間成為幻影。"]],"幻象":[["ㄏㄨㄢˋ ㄒㄧㄤˋ","虛幻不真實的景象。如海市蜃樓等。[例]夢中的情節大都是幻象而已，何須當真。"]],"幼苗":[["ㄧㄡˋ ㄇㄧㄠˊ","1.剛由種子中發芽生長的植物體。[例]他將波斯菊的種子灑在土上，沒幾天就冒出一株株的幼苗來了。\n2.新生的一代。指兒童。[例]兒童是國家民族的幼苗，因此良好的教育環境是非常重要的。"]],"幽靜":[["ㄧㄡ ㄐㄧㄥˋ","幽雅清靜。[例]此地有崇山峻嶺，茂林修竹，風景秀麗，十分幽靜。"]],"幽默":[["ㄧㄡ ㄇㄛˋ","形容事情、言行滑稽有趣或意味深長。§英humour[例]他為人幽默風趣，很有人緣。"]],"幾乎":[["ㄐㄧ ㄏㄨ","將近、差一點。[例]因為山洪暴發，通往山上的那條路幾乎全被沖斷了。"]],"幾許":[["ㄐㄧˇ ㄒㄩˇ","多少。[例]庭院深深深幾許？陽柳堆煙，簾幕無重數。（宋．歐陽修〈蝶戀花．庭院深深深幾許〉詞）"]],"庇佑":[["ㄅㄧˋ ㄧㄡˋ","保佑。[例]感謝老天爺的庇佑，使我能順利度過這個難關！"]],"庇護":[["ㄅㄧˋ ㄏㄨˋ","保護、維護。[例]憲法的訂立，是為了庇護人民的生命、自由及財產。"]],"床鋪":[["ㄔㄨㄤˊ ㄆㄨˋ","臥榻，供人睡臥的家具。[例]他習慣每天起床後就把床鋪整理好。"]],"序幕":[["ㄒㄩˋ ㄇㄨˋ","1.戲劇上指某些多幕劇在第一幕前的一場戲。用以介紹劇中人物的歷史背景和劇情發生的遠因，或預示全劇的主題。後也泛用於文學作品。[例]看了這齣戲的序幕，我們對其內容已有概括性的了解了。\n2.借指重大事件的開端。[例]蘆溝橋事變揭開了八年抗戰的序幕。"]],"底下":[["ㄉㄧˇ ˙ㄒㄧㄚ","1.下面。[例]屋簷底下有燕子築巢。\n2.之後、以後。[例]底下所說的話非常重要，請大家務必記下。\n3.在權勢範圍管轄之內。[例]在他底下工作是一件非常辛苦的事。"]],"底部":[["ㄉㄧˇ ㄅㄨˋ","任何事物相對於上面的部分。[例]種花時，最好在花盆底部放些小石頭，以利排水。"]],"店員":[["ㄉㄧㄢˋ ㄩㄢˊ","商店的員工。[例]這位店員服務周到，使顧客感到親切愉快。"]],"店家":[["ㄉㄧㄢˋ ㄐㄧㄚ","1.指舊時的商店或旅店。[例]隔壁店家今天辦喜事，因此休業一天。\n2.稱店鋪的主人或夥計。[例]店家！麻煩給我一包鹽！"]],"店鋪":[["ㄉㄧㄢˋ ㄆㄨˋ","商店。[例]這條街有很多販賣兒童用品的店鋪。"]],"府城":[["ㄈㄨˇ ㄔㄥˊ","舊時較縣高一級的州郡最高行政官署的所在地。[例]臺南府城"]],"度過":[["ㄉㄨˋ ㄍㄨㄛˋ","經歷、通過。[例]他靠著意志力，度過這場生命的艱困挑戰。"]],"座位":[["ㄗㄨㄛˋ ㄨㄟˋ","供人坐的位子。[例]在擁擠的公車上，他將自己的座位讓給一位孕婦。"]],"座無虛席":[["ㄗㄨㄛˋ ㄨˊ ㄒㄩ ㄒㄧˊ","形容來訪或出席的人數眾多。[例]他的演講很轟動，每場都座無虛席。"]],"座艙":[["ㄗㄨㄛˋ ㄘㄤ","船舶或飛機中設有座位，供人活動的艙房。[例]這家航空公司以其飛機具有舒適且豪華的座艙來吸引旅客。"]],"座號":[["ㄗㄨㄛˋ ㄏㄠˋ","座位的號碼。[例]電影開演前，觀眾紛紛依座號入座。"]],"庫存":[["ㄎㄨˋ ㄘㄨㄣˊ","1.貯存、堆積。[例]公司庫存一批新貨，準備擇期推出。\n2.倉庫裡貯存的物品。[例]百貨公司常舉辦年終特賣會，以出清庫存。"]],"庫房":[["ㄎㄨˋ ㄈㄤˊ","貯藏物品的房屋。[例]庫房附近要嚴禁煙火，以策安全。"]],"庭園":[["ㄊㄧㄥˊ ㄩㄢˊ","房屋周圍的空地，通常可種植花木，作為休閒活動的場所。[例]經過爸爸的細心栽培，庭園裡花木扶疏，一片欣欣向榮的景象。"]],"庭院":[["ㄊㄧㄥˊ ㄩㄢˋ","圍牆內房舍以外的空地，有前院、後院之別。[例]夏日的夜晚，我們常在庭院裡喝茶談天。"]],"康乃馨":[["ㄎㄤ ㄋㄞˇ ㄒㄧㄣ","植物名。石竹科。一年生草本植物。莖節處膨大，葉對生、披針形，全株呈灰綠色，所開的花亦稱為「康乃馨」。花萼圓筒狀，先端開裂，花瓣呈鋸齒狀，邊緣深裂。花色豐富，有紅色、白色、粉色、黃色、鑲邊、紫色等。是世界性的母親節代表花卉，用來表示對母親的敬愛與懷念，為國內所產花卉八大金釵之一。　◎"]],"康復":[["ㄎㄤ ㄈㄨˋ","病癒，恢復健康。[例]他的病經過醫生的細心診療已經完全康復了。"]],"康樂":[["ㄎㄤ ㄌㄜˋ","安康快樂。[例]由於政府銳意革新，執政得當，使得國內經濟繁榮，百姓生活康樂。"]],"廁所":[["ㄘㄜˋ ㄙㄨㄛˇ","大小便的地方。[例]爸爸每天早晨起床第一件事，就是帶著報紙進廁所。"]],"廚師":[["ㄔㄨˊ ㄕ","掌理廚房烹飪事務的師傅。[例]這家餐廳為了擴大營業，增聘了好多位廚師。"]],"廠商":[["ㄔㄤˇ ㄕㄤ","製造或出售各種物品的商家。[例]新闢的工業區尚未完成規劃，目前仍沒有廠商遷入。"]],"廢棄":[["ㄈㄟˋ ㄑㄧˋ","因不再具有使用價值而捨棄。[例]這部機器的故障率太高，早已廢棄不用了。"]],"廢氣":[["ㄈㄟˋ ㄑㄧˋ","工廠在生產過程中或交通工具、機械等運轉所排放出來的有害人體的氣體。[例]那家化學工廠排放出來的廢氣嚴重汙染附近的空氣。"]],"廢鐵":[["ㄈㄟˋ ㄊㄧㄝˇ","鏽蝕或不堪使用的鋼鐵製品。[例]那輛轎車與大卡車相撞後成為一堆廢鐵。"]],"廢除":[["ㄈㄟˋ ㄔㄨˊ","廢止、取消。[例]中國百年來的不平等條約在八年抗戰末期始完全廢除。"]],"廣博":[["ㄍㄨㄤˇ ㄅㄛˊ","多方面、大範圍。多指學識豐富，胸懷廣大。[例]見識廣博"]],"廣受好評":[["ㄍㄨㄤˇ ㄕㄡˋ ㄏㄠˇ ㄆㄧㄥˊ","普遍受到讚美。[例]這家餐廳的餐點經濟實惠，服務親切，廣受好評。"]],"廣大":[["ㄍㄨㄤˇ ㄉㄚˋ","寬廣、廣闊。[例]躺在沙灘上，仰視廣大無垠的藍天，感覺非常舒暢。"]],"廣播":[["ㄍㄨㄤˇ ㄅㄛˋ","1.廣泛傳播。[例]這種小事，他也到處去廣播，真無聊！\n2.一種利用音波與電波傳達訊息的大眾傳播媒介。有廣義、狹義之分。廣義泛指聲音與影像的傳播；狹義則單指聲音的傳播。[例]善用廣播媒體做廣告，可以打響品牌的知名度。\n3.指以音波方式傳送出來的廣播節目。[例]他一邊看書，一邊聽廣播。"]],"廣泛":[["ㄍㄨㄤˇ ㄈㄢˋ","範圍廣大。[例]他的興趣很廣泛，琴棋書畫都略通一二。"]],"廣闊":[["ㄍㄨㄤˇ ㄎㄨㄛˋ","廣大寬闊。[例]中國土地幅員廣闊，物產豐富。"]],"廬山":[["ㄌㄨˊ ㄕㄢ","位於江西省九江市南方的山脈。主峰漢陽峰，海拔1474公尺。鄱陽湖、長江之濱，三面臨水，西連陸地。萬壑千巖，飛瀑流泉，林木蔥蘢，煙雲瀰漫。中有白鹿洞、墨池、玉淵、秀峰、三疊泉等名勝，西北有牯嶺，為著名避暑勝地，亦為歷史文化名山。相傳周武王時，有匡俗兄弟七人結廬此山，後登仙而去，徒留空廬而得名；一說以廬江得名，故稱。廬山以雄、奇、險、秀聞名於世，素有「匡廬奇秀甲天下」之譽。聯合國教科文組織列為世界地質公園、世界文化遺產。 [例]『不識廬山真面目，只緣身在此山中』為蘇東坡傳誦千古的名句，寫盡廬山的雄奇險秀。　△廬阜、匡盧、匡山"]],"延年益壽":[["ㄧㄢˊ ㄋㄧㄢˊ ㄧˋ ㄕㄡˋ","延長壽命。[例]多運動可以延年益壽。"]],"延後":[["ㄧㄢˊ ㄏㄡˋ","往後延期。[例]為了做更周全的準備，她決定將婚期延後。"]],"延長":[["ㄧㄢˊ ㄔㄤˊ","1.伸長、拉長。[例]這條橡皮筋可以延長為十公分。\n2.增加時間。[例]因為參觀人潮不斷，館方決定將展覽延長一週。"]],"延長線":[["ㄧㄢˊ ㄔㄤˊ ㄒㄧㄢˋ","1.兩端分別為插頭和插座的電線。用於延長插座的使用範圍。\n2.數學上稱有限直線的延長部分。　△延線"]],"建構":[["ㄐㄧㄢˋ ㄍㄡˋ","建立構成。[例]美好的生活建構在安定的社會上。"]],"建築":[["ㄐㄧㄢˋ ㄓㄨˊ","1.建造。[例]在這條既深且闊的河上，建築一座橋梁是很浩大的工程。\n2.定著於土地上或地面下具有頂蓋、梁柱或牆壁，供個人或公眾使用的構造物或雜項工作物。[例]經過三年的施工，這棟建築終於完成了。　△建築物"]],"建設":[["ㄐㄧㄢˋ ㄕㄜˋ","1.創建事業或增添設施。[例]建設國家、經濟建設、公共建設\n2.與建設有關的。[例]建設公司、建設工程"]],"弄倒":[["ㄋㄨㄥˋ ㄉㄠˇ","使東西傾倒。[例]她不小心將大家好不容易堆好的積木弄倒了。"]],"弄堂":[["ㄌㄨㄥˋ ㄊㄤˊ","小巷子。[例]穿過這條弄堂再右轉，就可以看到大馬路了。"]],"弄巧成拙":[["ㄋㄨㄥˋ ㄑㄧㄠˇ ㄔㄥˊ ㄓㄨㄛˊ","本想取巧，卻反而敗事。指枉費心機。[例]不肯腳踏實地，總是想撿小便宜，往往容易弄巧成拙。"]],"弄錯":[["ㄋㄨㄥˋ ㄘㄨㄛˋ","搞錯了。[例]他因弄錯時間而錯過了應搭的火車。"]],"弓弦":[["ㄍㄨㄥ ㄒㄧㄢˊ","固定在弓上的弦。[例]他拉緊弓弦，瞄準靶心，將箭射了出去。"]],"引導":[["ㄧㄣˇ ㄉㄠˇ","領導、引領指導。[例]父母、師長必須以更多的愛心與耐心，引導孩子度過青春期。"]],"引擎":[["ㄧㄣˇ ㄑㄧㄥˊ","發動機。利用電力、熱力、風力等發生動力的各種機器的總稱。如蒸氣機、內燃機、電動機等，種類繁多。§英engine[例]車輛如果常行駛山路，會因引擎負荷過度而縮短使用壽命。　△原動機"]],"引燃":[["ㄧㄣˇ ㄖㄢˊ","使燃燒。[例]森林公園由於遊客隨地丟棄煙蒂而引燃大火，幾乎燒遍了整座山頭。"]],"引發":[["ㄧㄣˇ ㄈㄚ","引起、造成。[例]他們各持己見，彼此爭執不下，才引發這場言詞衝突。"]],"引誘":[["ㄧㄣˇ ㄧㄡˋ","誘惑，引導別人做某種事。[例]青少年容易受同儕朋友的引誘，而做出越軌的行為。"]],"引起":[["ㄧㄣˇ ㄑㄧˇ","引發、由此發生。[例]使用瓦斯不慎，容易引起火災。"]],"弟弟":[["ㄉㄧˋ ˙ㄉㄧ","稱謂。稱同胞手足中，後出生的男性親屬。[例]媽媽一向主張哥哥和弟弟應該平均分擔家務。　◎"]],"弦樂":[["ㄒㄧㄢˊ ㄩㄝˋ","用弦樂器演奏出的音樂。[例]琴、箏、琵琶所演奏的音樂都屬弦樂。"]],"弧線":[["ㄏㄨˊ ㄒㄧㄢˋ","彎曲如弓的線條。[例]雨後的彩虹呈弧線掛在天邊，美麗極了。"]],"弱不禁風":[["ㄖㄨㄛˋ ㄅㄨˋ ㄐㄧㄣ ㄈㄥ","形容身體虛弱，連風吹都禁不住。[例]他那弱不禁風的身體，經過一年多的鍛鍊，終於變得又強又壯。"]],"張燈結綵":[["ㄓㄤ ㄉㄥ ㄐㄧㄝˊ ㄘㄞˇ","張掛燈籠，紮結著彩球、彩帶。是一種表現喜慶的習俗。[例]雙十節一到，市區內到處張燈結綵，顯得喜氣洋洋。"]],"張牙舞爪":[["ㄓㄤ ㄧㄚˊ ㄨˇ ㄓㄠˇ","1.形容猛獸發威的樣子。[例]獅子張牙舞爪的樣子看起來非常可怕。\n2.比喻張揚作勢，猖狂凶惡的樣子。[例]她發脾氣時一副張牙舞爪的姿態，令人避之唯恐不及。"]],"張開":[["ㄓㄤ ㄎㄞ","把合攏的物體分開、打開。[例]張開眼睛、張開翅膀、嘴巴張開"]],"強勁":[["ㄑㄧㄤˊ ㄐㄧㄥˋ","強而有力。[例]由於風勢強勁，海上的漁船紛紛進港避風。"]],"強壯":[["ㄑㄧㄤˊ ㄓㄨㄤˋ","健壯有力。[例]他找了幾位強壯的路人，幫忙推動陷入泥沼的車子。"]],"強度":[["ㄑㄧㄤˊ ㄉㄨˋ","能夠承受作用力的大小強弱，或是所包含的能量大小。如光線強度、磁場強度。[例]此次地震的強度雖不大，卻造成公路多處坍方，交通因而受阻。"]],"強求":[["ㄑㄧㄤˇ ㄑㄧㄡˊ","執意的要求、強迫爭取。[例]強求兒女接受父母的意見，有時候會造成不和諧的親子關係。"]],"強盛":[["ㄑㄧㄤˊ ㄕㄥˋ","強大壯盛。[例]教育是國家強盛的根本。"]],"強盜":[["ㄑㄧㄤˊ ㄉㄠˋ","用暴力強奪他人財物的人。[例]這夥擄人劫財的強盜，已於凌晨遭到警察逮捕。"]],"強硬":[["ㄑㄧㄤˊ ㄧㄥˋ","態度堅決，不願退讓。[例]由於雙方態度強硬，以致遲遲無法達成協議。"]],"強迫":[["ㄑㄧㄤˇ ㄆㄛˋ","施加壓力使服從。[例]他經常強迫部屬服從他的意見，因此很不得人心。"]],"強風":[["ㄑㄧㄤˊ ㄈㄥ","1.強勁的風。[例]強風伴隨著沙塵吹來，讓人難以睜開眼睛。_x000D_\n2.氣象學上指風力六級的風。"]],"彆扭":[["ㄅㄧㄝˋ ㄋㄧㄡˇ","1.脾氣執拗不和順的。[例]他的脾氣很彆扭。\n2.不通順、不流暢。[例]這個句子唸起來有點彆扭。\n3.不和、有爭執。[例]這兩人正在鬧彆扭，臉色都不好看。\n4.尷尬、難為情。[例]你不要這個樣子，讓別人看到了怪彆扭的。"]],"彈奏":[["ㄊㄢˊ ㄗㄡˋ","演奏樂器。[例]他不但擅長彈奏鋼琴，小提琴也拉得很好。"]],"彈弓":[["ㄉㄢˋ ㄍㄨㄥ","以彈力發射彈丸的弓。[例]用彈弓來射樹上的小鳥是非常不好的行為。　◎"]],"彈性":[["ㄊㄢˊ ㄒㄧㄥˋ","1.物體受外力作用時，會改變形體，而當外力除去後隨即恢復原狀的性質。[例]利用橡皮筋的彈性，可以緊封袋口，也可以重複使用。\n2.比喻事情無絕對的標準、形式等，可以隨狀況調整。[例]這筆預算我們可以彈性運用，不一定非得購買器材。\n3.指彈跳的能力。[例]他彈性極佳，在籃球隊中擔任中鋒。"]],"彈珠":[["ㄉㄢˋ ㄓㄨ","用玻璃或合成金屬製成的小圓珠。[例]從前打彈珠是小朋友們最普遍的一種遊戲。"]],"彈簧":[["ㄊㄢˊ ㄏㄨㄤˊ","利用具有彈性的材料所製成的零件。能在外力作用下發生伸長、縮短、彎曲、扭轉等形變，除去外力後又恢復原狀。[例]這套沙發的彈簧已經失去彈力了。"]],"彌足珍貴":[["ㄇㄧˊ ㄗㄨˊ ㄓㄣ ㄍㄨㄟˋ","非常寶貴。[例]這個家傳的玉鐲對我來說可是意義非凡，彌足珍貴。"]],"彎彎曲曲":[["ㄨㄢ ㄨㄢ ㄑㄩ ㄑㄩ","不直、曲折。[例]這條山路彎彎曲曲，非常難走。"]],"彎曲":[["ㄨㄢ ㄑㄩ","屈曲、不直。[例]水道彎曲的地方，水流的速度會減慢。"]],"彙整":[["ㄏㄨㄟˋ ㄓㄥˇ","聚集整理。[例]她彙整了自己近年來在報章上發表的文章，結集出版。"]],"形狀":[["ㄒㄧㄥˊ ㄓㄨㄤˋ","物體呈現在外的樣式、模樣。[例]這個瓶子的形狀是圓錐形的。"]],"彩排":[["ㄘㄞˇ ㄆㄞˊ","戲劇、舞蹈等正式演出前，最後一次的排演。所使用的服裝道具皆與正式演出時一樣。後亦指大型活動舉辦前最後的排練。[例]這齣戲預定今天下午彩排，明天正式公演。_x000D_"]],"彩筆":[["ㄘㄞˇ ㄅㄧˇ","畫筆。[例]這個畫家彩筆一揮，便是一幅好山好水。"]],"彩繪":[["ㄘㄞˇ ㄏㄨㄟˋ","器物或建築上彩色的圖案。[例]這家工廠製造的陶瓷有各式各樣的彩繪，相當精美別緻。"]],"彩色":[["ㄘㄞˇ ㄙㄜˋ","多種顏色的。[例]這本童話故事書附有彩色插畫，深深吸引住小朋友。"]],"彩虹":[["ㄘㄞˇ ㄏㄨㄥˊ","大氣中的水氣因日照的折射及反射作用，於天空中形成弧形的帶狀景觀，由外圈到內圈呈紅、橙、黃、綠、藍、靛、紫七種顏色。[例]雨過天青，天邊出現了一道美麗的彩虹。"]],"彩霞":[["ㄘㄞˇ ㄒㄧㄚˊ","因陽光的照射而產生多種顏色變化的雲層。[例]傍晚時分，他喜歡坐在河堤上，欣賞滿天的彩霞。"]],"影劇":[["ㄧㄥˇ ㄐㄩˋ","電影和戲劇。[例]你若常看影劇新聞，自然對明星的動向能瞭若指掌。"]],"彷彿":[["ㄈㄤˇ ㄈㄨˊ","似乎、好像、近似。[例]這個人我彷彿曾經見過。"]],"彼岸":[["ㄅㄧˇ ㄢˋ","1.對岸，那一邊。[例]風雨這麼大，船能不能順利抵達彼岸，大家毫無把握。\n2.借指所嚮往的境界。[例]只要有勇氣和毅力，定能到達成功的彼岸。\n3.佛教上指脫離此岸塵世的煩惱，而獲得解脫的境界。[例]在死者臨終時，師父帶領大家宣唸佛號，讓死者早登彼岸。"]],"彼此":[["ㄅㄧˇ ㄘˇ","1.人與人相互間。[例]與人相處，要有彼此容忍的雅量和互相尊重的概念。\n2.雙方情形相似。常以疊語方式出現。[例]彼此彼此，咱們誰也別笑誰了！"]],"往事":[["ㄨㄤˇ ㄕˋ","過去的、以往的事情。[例]童年往事、傷心往事"]],"往來":[["ㄨㄤˇ ㄌㄞˊ","1.去與來。[例]穿梭往來\n2.交往、交際。[例]他們倆自吵過一架後，便發誓互不往來。"]],"往年":[["ㄨㄤˇ ㄋㄧㄢˊ","過去、從前。[例]按照往年的慣例，校慶日將舉辦園遊會。"]],"征戰":[["ㄓㄥ ㄓㄢˋ","征伐、作戰。[例]他長年征戰邊關，備嘗艱苦。"]],"待產":[["ㄉㄞˋ ㄔㄢˇ","等待生產。[例]預產期快到了，她打算請假在家待產。"]],"待遇":[["ㄉㄞˋ ㄩˋ","1.工作的報酬。通常指薪俸。[例]這份工作的待遇雖然不高，但是很有發展性。\n2.對待、接待。[例]我們應邀到他家做客，並且受到極好的待遇。"]],"律師":[["ㄌㄩˋ ㄕ","受當事人委託或法院指定，協助當事人進行訴訟、辯護或處理有關法律事務的專業人員。[例]這位律師以追求公義聞名，常提供弱勢者免費諮詢或訴訟協助。"]],"後來":[["ㄏㄡˋ ㄌㄞˊ","1.後至、後到。[例]由於座位有限，後來的人只好站著聽演講。\n2.指過去某一時間後面的時間。[例]先前我們還有聯絡，後來就失去消息了。"]],"後座":[["ㄏㄡˋ ㄗㄨㄛˋ","指汽、機車後方的座位。[例]在回程中，他因為過於疲倦而在後座上睡著了。　◎"]],"後悔":[["ㄏㄡˋ ㄏㄨㄟˇ","事後懊悔當初的不該。[例]年輕的時候要充實自己，培養實力，不要等到老了才來後悔。"]],"後起之秀":[["ㄏㄡˋ ㄑㄧˇ ㄓ ㄒㄧㄡˋ","後輩中突出的優秀人才。[例]他年未三十，畫風卻已深受國內外名家的讚賞，可說是近年來畫壇的後起之秀。"]],"後退":[["ㄏㄡˋ ㄊㄨㄟˋ","向後退。[例]兩輛大卡車在窄道上相碰，誰也不願後退。"]],"徐徐":[["ㄒㄩˊ ㄒㄩˊ","緩慢的樣子。[例]晚風徐徐吹來，令人心曠神怡。"]],"徒弟":[["ㄊㄨˊ ㄉㄧˋ","學徒、弟子。[例]小王在機車行當徒弟，希望有朝一日也能自己開店當老板。"]],"徒步":[["ㄊㄨˊ ㄅㄨˋ","步行。"]],"徒然":[["ㄊㄨˊ ㄖㄢˊ","1.枉然、白費。[例]人若只有美貌，而沒有半點學問，那也是徒然。\n2.僅此、只是如此。[例]你徒然的替自己辯護而拿不出證據，叫人如何能信服呢？"]],"得":[["ㄉㄜˊ","1.獲取。與「失」相對。[例]獲得、得獎、得來不易\n\t\n2.契合、適宜。[例]得體、得法、相得益彰\n\t\n3.可以、能夠。[例]得過且過、不得無禮、得饒人處且饒人\n\t\n4.快意、滿足。[例]自得、得意\n\t\n5.遇。[例]得便、得空、得閒\n\t\n6.夠了。多用於談話時表反對、禁止或同意。[例]得了，別再出餿主意了！"],["˙ㄉㄜ","助詞。用在動詞、形容詞後面，表示結果或性狀。[例]跑得快、美得冒泡"],["ㄉㄟˇ","應該、必須、需要。[例]他總得把工作交代清楚再離職吧？"]],"得勝":[["ㄉㄜˊ ㄕㄥˋ","獲得勝利。[例]這場籃球賽經過激烈的廝殺之後，終於由本隊得勝。"]],"得天獨厚":[["ㄉㄜˊ ㄊㄧㄢ ㄉㄨˊ ㄏㄡˋ","形容人的天賦、社會條件，或是地方的自然環境特別優越。[例]她有一副得天獨厚的好嗓子，因此一出道便大受歡迎。"]],"得意":[["ㄉㄜˊ ㄧˋ","稱心如意或引以自豪。[例]他對於自己的精心傑作感到很得意。"]],"得意忘形":[["ㄉㄜˊ ㄧˋ ㄨㄤˋ ㄒㄧㄥˊ","形容人高興過度，舉止失去常態。語本《晉書．卷四十九．阮籍傳》。[例]別太得意忘形，小心遭人嫉妒。"]],"得意洋洋":[["ㄉㄜˊ ㄧˋ ㄧㄤˊ ㄧㄤˊ","形容十分得意的樣子。[例]看你一副得意洋洋的模樣，想必有什麼好事吧！"]],"得獎":[["ㄉㄜˊ ㄐㄧㄤˇ","獲得獎賞。[例]以他多年的寫作經驗及成就，得獎應該沒有問題。"]],"得病":[["ㄉㄜˊ ㄅㄧㄥˋ","患病。[例]王老先生雖得病多年，但仍很樂觀的投身義工工作。"]],"得過且過":[["ㄉㄜˊ ㄍㄨㄛˋ ㄑㄧㄝˇ ㄍㄨㄛˋ","形容苟且偷安，不求上進。[例]人要趁年輕好好打拚一番，千萬不要有得過且過的心理。"]],"得體":[["ㄉㄜˊ ㄊㄧˇ","言行舉止，恰如其分。[例]不論在任何場合，她的表現都十分得體。"]],"徘徊":[["ㄆㄞˊ ㄏㄨㄞˊ","1.在一個地方來回走動不離去。[例]他在公園裡徘徊，好像在等人似的。_x000D_\n2.比喻猶豫不決。[例]這件事在我心中徘徊已久，終難決定。"]],"徜徉":[["ㄔㄤˊ ㄧㄤˊ","安閒自在的四處走動。[例]他喜歡一個人無憂無慮的徜徉在青山綠水間。"]],"從事":[["ㄘㄨㄥˊ ㄕˋ","擔任、處理事務、投身。[例]她從小就想當老師，從事教書的工作。"]],"從來":[["ㄘㄨㄥˊ ㄌㄞˊ","從以前到現在。[例]她從來不曾開過車子，怎麼會知道如何發動引擎呢？"]],"從容":[["ㄘㄨㄥ ㄖㄨㄥˊ","1.舒緩悠閒、不慌不忙的樣子。[例]從容自若、從容吟味\n2.充裕、不緊迫。[例]時間還很從容，不需要那麼慌張！"]],"從容不迫":[["ㄘㄨㄥ ㄖㄨㄥˊ ㄅㄨˋ ㄆㄛˋ","沉著、不慌張。[例]在緊急狀況下要能從容不迫，才可使事情順利解決。"]],"從此":[["ㄘㄨㄥˊ ㄘˇ","從這個時候起。[例]他離開家鄉謀求發展後，從此再也沒有人知道他的下落了。"]],"從犯":[["ㄗㄨㄥˋ ㄈㄢˋ","幫助他人從事犯罪行為的人。[例]這件竊盜案共有主犯一人，從犯五人涉案。"]],"從缺":[["ㄘㄨㄥˊ ㄑㄩㄝ","使其空缺。[例]評審們認為此次參賽的作品水準低落，因此第一名從缺。"]],"從軍":[["ㄘㄨㄥˊ ㄐㄩㄣ","當兵，參與軍隊。[例]從軍報國、代父從軍"]],"復健":[["ㄈㄨˋ ㄐㄧㄢˋ","對於生理或心理有障礙的病人，給予適當的醫療救助，使病人恢復健康，能夠自立生活的過程。[例]爺爺中風後，經由復健，如今已能走動。"]],"復興":[["ㄈㄨˋ ㄒㄧㄥ","衰微後使其再度興盛起來。[例]文藝復興"]],"循環":[["ㄒㄩㄣˊ ㄏㄨㄢˊ","事物周而復始的運轉或變化。[例]血液循環、循環小數"]],"循規蹈矩":[["ㄒㄩㄣˊ ㄍㄨㄟ ㄉㄠˋ ㄐㄩˇ","遵守規矩。[例]她在學校一向循規蹈矩，是老師心目中的好學生。"]],"徬徨":[["ㄆㄤˊ ㄏㄨㄤˊ","1.徘徊不前的樣子。[例]瞧！那個人在巷口徬徨好一陣子了。_x000D_\n2.比喻猶疑不決。[例]究竟去或不去，他的內心徬徨不已。"]],"微不足道":[["ㄨㄟˊ ㄅㄨˋ ㄗㄨˊ ㄉㄠˋ","比喻卑微渺小得不值得一提。[例]個人的力量雖然微不足道，但只要大家團結合作，必能凝聚成一股強大的力量。"]],"微乎其微":[["ㄨㄟˊ ㄏㄨ ㄑㄧˊ ㄨㄟˊ","形容非常少或極細微。語本《爾雅．釋訓》。[例]這種病到現在還缺乏有效的治療方法，痊癒的可能性恐怕是微乎其微了。"]],"微微":[["ㄨㄟˊ ㄨㄟˊ","稍微、略微。[例]她嘴角微微一揚，露出會心的笑容。"]],"微笑":[["ㄨㄟˊ ㄒㄧㄠˋ","淺笑、淡淡的笑。[例]微笑是通行世界各地，最好的溝通語言。"]],"徵求":[["ㄓㄥ ㄑㄧㄡˊ","以書面或口頭方式詢問訪求。[例]班長打算先徵求眾人的意見，再決定畢業旅行的地點。"]],"徵選":[["ㄓㄥ ㄒㄩㄢˇ","公開徵求挑選。[例]某機關將公開徵選三名工讀生來擔任詢問臺服務的工作。"]],"德性":[["ㄉㄜˊ ㄒㄧㄥˋ","1.道德品性。[例]小明在校品學兼優，德性溫良，所以被推選為班長。_x000D_\n2.讓人反感或瞧不起的儀態、舉止、作風等。含有譏諷、輕蔑的意思。[例]瞧他那副囂張的德性，真是令人討厭。"]],"德政":[["ㄉㄜˊ ㄓㄥˋ","有益人民的政治措施。[例]他在行政院長任內推行了多項德政，至今仍為人們所推崇讚揚。"]],"心坎":[["ㄒㄧㄣ ㄎㄢˇ","內心深處。[例]媽媽的這番話真是說到我的心坎裡。"]],"心急":[["ㄒㄧㄣ ㄐㄧˊ","心中急躁。[例]事情總得一步一步的解決，你光是心急也沒有用。"]],"心情":[["ㄒㄧㄣ ㄑㄧㄥˊ","情緒、興致。[例]他無端遭上司責罵，心情十分惡劣。"]],"心意":[["ㄒㄧㄣ ㄧˋ","1.意思、意念。[例]他辭職的心意已定，任何人都沒辦法勸阻。\n2.情意。[例]妳這份心意我永遠都不會忘記。"]],"心房":[["ㄒㄧㄣ ㄈㄤˊ","1.位於心臟上方，可接受並送出血液的兩個空腔。左邊的為左心房，右邊的為右心房。[例]這個嬰兒心房發育不全，是造成先天性心臟病的主因。\n2.內心。[例]母親的關懷呵護溫暖著我的心房。"]],"心扉":[["ㄒㄧㄣ ㄈㄟ","指人的內心。[例]妳何不敞開心扉，接受他的關懷？"]],"心狠手辣":[["ㄒㄧㄣ ㄏㄣˇ ㄕㄡˇ ㄌㄚˋ","心腸險惡，手段殘忍。[例]歹徒十分心狠手辣，取了錢之後又將人質殺害。"]],"心猿意馬":[["ㄒㄧㄣ ㄩㄢˊ ㄧˋ ㄇㄚˇ","形容心意變化不定，有如馬騰猿跳一般。[例]事情已到關鍵處，你就別心猿意馬了，趕緊下決定吧！"]],"心疼":[["ㄒㄧㄣ ㄊㄥˊ","憐惜、捨不得。[例]前些日子，爸爸珍藏的明代瓷瓶被弟弟打破，每次提到這件事，他老人家就感到十分心疼。"]],"心腸":[["ㄒㄧㄣ ㄔㄤˊ","心地。[例]蛇蠍心腸、鐵石心腸"]],"心願":[["ㄒㄧㄣ ㄩㄢˋ","心中立意要做的事。[例]環遊世界是他這一生最大的心願。"]],"心馳神往":[["ㄒㄧㄣ ㄔˊ ㄕㄣˊ ㄨㄤˇ","心神專注、嚮往於事物上。[例]這部愛情文藝小說的情節，讓她非常心馳神往。"]],"必備":[["ㄅㄧˋ ㄅㄟˋ","一定需要具備的。[例]急救箱是每個家庭的必備用品。"]],"必定":[["ㄅㄧˋ ㄉㄧㄥˋ","1.一定。表示肯定的推斷。[例]只要每一步都走得穩當，必定可以步向成功的坦途。_x000D_\n2.表示態度堅決，不會改變。[例]不論天氣如何，我明天必定會撥空來看你。"]],"必然":[["ㄅㄧˋ ㄖㄢˊ","必定如此。[例]在人的一生中必然會經歷生、老、病、死。"]],"必要":[["ㄅㄧˋ ㄧㄠˋ","絕對需要的，必定不可缺少的。[例]建設便捷的交通，是提昇生活品質的必要措施。"]],"必需品":[["ㄅㄧˋ ㄒㄩ ㄆㄧㄣˇ","不可缺少的物品。[例]生活必需品"]],"必須":[["ㄅㄧˋ ㄒㄩ","一定要、必定要。[例]想要有好的表現，就必須努力用功，認真學習。"]],"忌諱":[["ㄐㄧˋ ㄏㄨㄟˋ","基於禮俗、宗教或習慣等因素而形成特有的禁忌或避諱。[例]來到一個陌生的環境，要謹言慎行，不要觸犯當地人的忌諱。"]],"忍不住":[["ㄖㄣˇ ㄅㄨˋ ㄓㄨˋ","不能忍受、不能克制。[例]看到哥哥扮了個鬼臉，妹妹忍不住笑了出來。"]],"忍受":[["ㄖㄣˇ ㄕㄡˋ","忍耐承受。[例]屋外的噪音震耳欲聾，令人無法忍受。"]],"忍氣吞聲":[["ㄖㄣˇ ㄑㄧˋ ㄊㄨㄣ ㄕㄥ","將怒氣克制下來，不敢發作。[例]對於上司的百般刁難，他只能忍氣吞聲，不敢爭辯。"]],"忍耐":[["ㄖㄣˇ ㄋㄞˋ","按捺住感情或感受，不使發作。[例]既然已經答應要完成這項任務，再艱苦也要忍耐下去。"]],"忐忑":[["ㄊㄢˇ ㄊㄜˋ","心神不寧。[例]面對老師突如其來的質問，他心中忐忑難安，不知所措。"]],"志向":[["ㄓˋ ㄒㄧㄤˋ","意志的趨向。[例]年輕人志向要遠大，做事要踏實。"]],"志工":[["ㄓˋ ㄍㄨㄥ","指願意在公共或志願團體內，不受報酬而貢獻其力量的人。[例]志工除了具備熱心與愛心之外，有時還須經過專業訓練。　△義工"]],"忘卻":[["ㄨㄤˋ ㄑㄩㄝˋ","忘記、遺忘。[例]他一朝得志，就忘卻故人舊友。"]],"忘恩負義":[["ㄨㄤˋ ㄣ ㄈㄨˋ ㄧˋ","受人恩惠而不知報答，反而做出對不起恩人的事情。[例]如此忘恩負義的人，遲早會受到上天的懲罰。"]],"忘記":[["ㄨㄤˋ ㄐㄧˋ","不記得。[例]他忘記寫功課，被老師處罰。"]],"忙碌":[["ㄇㄤˊ ㄌㄨˋ","事情太多，不得休息。[例]他的工作相當忙碌，經常從早忙到晚。"]],"忠實":[["ㄓㄨㄥ ㄕˊ","1.忠誠可靠。[例]狗是人類最忠實的朋友。\n2.真實。[例]報紙對於這件事的來龍去脈已做了最忠實的報導。"]],"忠誠":[["ㄓㄨㄥ ㄔㄥˊ","誠心盡力。[例]他為人忠誠，是值得深交的朋友。"]],"快樂":[["ㄎㄨㄞˋ ㄌㄜˋ","愉悅喜樂。[例]助人為快樂之本。"]],"快速":[["ㄎㄨㄞˋ ㄙㄨˋ","迅速。[例]穿越馬路時應該快速通過，以免發生危險。"]],"忽然":[["ㄏㄨ ㄖㄢˊ","突然。[例]忽然間烏雲密布，緊接著就下起大雨來了。"]],"忽略":[["ㄏㄨ ㄌㄩㄝˋ","疏忽、不注意。[例]發高燒是許多重大疾病的先期癥狀之一，千萬不可忽略。"]],"忽視":[["ㄏㄨ ㄕˋ","不在意、不重視。[例]過度開發所造成的環保生態問題，實在不容忽視。"]],"怎麼":[["ㄗㄣˇ ˙ㄇㄜ","1.為什麼。[例]他怎麼還不回來？真急死人了！\n2.如何。[例]這件事該怎麼解決？你提個辦法吧！"]],"怎麼辦":[["ㄗㄣˇ ˙ㄇㄜ ㄅㄢˋ","如何處理。[例]事情到了這種地步，該怎麼辦呢？"]],"怒氣":[["ㄋㄨˋ ㄑㄧˋ","憤怒的情緒。[例]他今天不知吃了什麼炸藥，一臉怒氣，動不動就發脾氣。"]],"怒火":[["ㄋㄨˋ ㄏㄨㄛˇ","如火焰般強烈的憤怒情緒。[例]他在連番受辱之後，終於壓不住心中的怒火，做出強烈的反擊。"]],"思念":[["ㄙ ㄋㄧㄢˋ","懷想、想念。[例]離家愈遠，對故鄉的思念也就愈深。"]],"思慮":[["ㄙ ㄌㄩˋ","思索考慮。[例]他思慮周密，辦事牢靠，可放心的委以重任。"]],"思索":[["ㄙ ㄙㄨㄛˇ","思考、推敲。[例]他一看到這道題目，便毫不思索的把答案寫了下來。"]],"思緒":[["ㄙ ㄒㄩˋ","思路，思想的條理。[例]思緒通暢、思緒紛亂"]],"思考":[["ㄙ ㄎㄠˇ","1.思索、考慮。[例]事關緊要，你決定前要仔細思考一番。_x000D_\n2.進行較深入、周到的思想活動。[例]外面吵雜的嬉鬧聲，令人無法思考。"]],"思辨":[["ㄙ ㄅㄧㄢˋ","思考辨析。[例]他聰明伶俐，思辨能力很強。"]],"怡然":[["ㄧˊ ㄖㄢˊ","欣悅自得的樣子。[例]即使在最困厄的環境中，他還是怡然自適，應付裕如。"]],"急促":[["ㄐㄧˊ ㄘㄨˋ","迅速倉促。[例]剛跑完百米競賽，她的呼吸顯得很急促。"]],"急切":[["ㄐㄧˊ ㄑㄧㄝˋ","緊急迫切。[例]父母對子女教養的方式如果過於急切，反而容易招致他們的反抗。"]],"急救":[["ㄐㄧˊ ㄐㄧㄡˋ","對病症或意外受傷所做的緊急救治。[例]由於他的急救得當，那位溺水的小孩逐漸甦醒了。"]],"急湍":[["ㄐㄧˊ ㄊㄨㄢ","急速的水流。[例]娟娟戲蝶過閒幔，片片輕鷗下急湍。（唐．杜甫〈小寒食舟中作〉詩）"]],"急診":[["ㄐㄧˊ ㄓㄣˇ","在醫療院所中對重病傷患所做的緊急診治。[例]他因車禍受傷，被送往醫院急診。"]],"急起直追":[["ㄐㄧˊ ㄑㄧˇ ㄓˊ ㄓㄨㄟ","迅速振作，努力追趕。[例]我們雖處在落後的局面，但別氣餒，現在急起直追還來得及。"]],"急躁":[["ㄐㄧˊ ㄗㄠˋ","急促焦躁。[例]眼看就要遲到了，卻仍塞在車陣當中，令她不免急躁起來。"]],"急迫":[["ㄐㄧˊ ㄆㄛˋ","立刻需要處理，不可以延誤。[例]救火是非常急迫的事，一刻都不能耽誤。"]],"性情":[["ㄒㄧㄥˋ ㄑㄧㄥˊ","性格、脾氣。[例]她的性情溫和，從來不與人爭吵。"]],"怨尤":[["ㄩㄢˋ ㄧㄡˊ","怨恨責怪。[例]媽媽為孩子們付出了青春，卻毫無怨尤。"]],"怨恨":[["ㄩㄢˋ ㄏㄣˋ","埋怨忿恨。[例]心中充滿怨恨的人，只會讓自己活得不快樂。"]],"怨聲載道":[["ㄩㄢˋ ㄕㄥ ㄗㄞˋ ㄉㄠˋ","到處充滿了怨恨的聲音。形容群眾普遍怨恨、不滿。[例]施行新制度前應先做好評估考量，以免民眾怨聲載道，叫苦連天。"]],"怪誕":[["ㄍㄨㄞˋ ㄉㄢˋ","古怪、不合情理。[例]這棟年久失修的古屋，有許多怪誕的傳說。"]],"怯懦":[["ㄑㄩㄝˋ ㄋㄨㄛˋ","膽小懦弱。[例]你若能戰勝自己的怯懦，那麼你已成功了一半。"]],"恆久":[["ㄏㄥˊ ㄐㄧㄡˇ","持久、長遠。[例]真理是恆久不變，且經得起任何考驗的。"]],"恍惚":[["ㄏㄨㄤˇ ㄏㄨ","1.神智模糊不清。[例]他昨晚熬夜讀書，所以今天精神有點恍惚。_x000D_\n2.彷彿、好像。[例]滿天的星斗，恍惚鑽石般閃爍著光芒。"]],"恍然大悟":[["ㄏㄨㄤˇ ㄖㄢˊ ㄉㄚˋ ㄨˋ","忽然完全明白。[例]經過老師一番懇談之後，他才恍然大悟：原來過去父母的管教都是出於關愛。"]],"恍若":[["ㄏㄨㄤˇ ㄖㄨㄛˋ","彷彿、好像。[例]她的氣質非凡，衣著光鮮亮麗，恍若仙子下凡般引人注目。"]],"恐嚇":[["ㄎㄨㄥˇ ㄏㄜˋ","以脅迫的言語或行動威嚇人。[例]他決定不接受歹徒的恐嚇，堅持向警方報案。"]],"恐怖":[["ㄎㄨㄥˇ ㄅㄨˋ","可怕、害怕。[例]深夜暗巷獨行，使得膽小的她倍覺恐怖。"]],"恐懼":[["ㄎㄨㄥˇ ㄐㄩˋ","惶恐、害怕。[例]小妹自從發生過車禍後，從此心懷恐懼，再也不肯騎車上學了。"]],"恐龍":[["ㄎㄨㄥˇ ㄌㄨㄥˊ","動物名。中生代棲息陸地的爬蟲類。頸子和尾巴均長，後肢長於前肢，有時以後肢及尾巴直立，形狀可怖。種類甚多，今均已絕跡。[例]活躍於侏羅紀的恐龍，進入新生代忽然滅絕的原因，至今仍是個謎。　◎"]],"恢復":[["ㄏㄨㄟ ㄈㄨˋ","1.回復到原來的樣子。[例]經過二年的重建，此地又恢復了震災前的繁華風貌。\n2.收復，將失去的收回來。[例]經過了四十年的努力，少康終於滅了寒浞，恢復夏朝。"]],"恣意":[["ㄗˋ ㄧˋ","放任而不加以約束。[例]詩人文士酒酣耳熱之際，往往恣意高歌，下筆千言。"]],"恨不得":[["ㄏㄣˋ ㄅㄨˋ ˙ㄉㄜ","巴不得、怨恨不能夠。[例]他全身被大雨淋溼了，恨不得馬上洗個熱水澡。"]],"恩師":[["ㄣ ㄕ","對自己有恩惠的老師的敬稱。[例]今日我有如此成就，完全是靠恩師當年的教誨。"]],"恩賜":[["ㄣ ㄙˋ","施恩賞賜。[例]大自然的一切都是造物者的恩賜，我們應當好好珍惜。"]],"恬淡":[["ㄊㄧㄢˊ ㄉㄢˋ","清靜淡泊，不求名利。[例]她一向喜愛過著恬淡的生活。"]],"恭喜":[["ㄍㄨㄥ ㄒㄧˇ","向人表示慶賀之敬詞。[例]恭喜你考上研究所。"]],"恭維":[["ㄍㄨㄥ ㄨㄟˊ","奉承、稱頌。[例]對於別人的恭維，她總是一笑置之。"]],"恭迎":[["ㄍㄨㄥ ㄧㄥˊ","恭敬的迎接。[例]恭迎聖駕、恭迎大駕"]],"恰好":[["ㄑㄧㄚˋ ㄏㄠˇ","剛好、正好。[例]他在途中恰好遇上大塞車，所以遲到了。"]],"恰巧":[["ㄑㄧㄚˋ ㄑㄧㄠˇ","恰好、碰巧。[例]今天我倆都恰巧沒事，不如一起去逛街吧！"]],"恰恰":[["ㄑㄧㄚˋ ㄑㄧㄚˋ","1.恰巧、剛好。[例]這個袋子恰恰可以裝進二十公斤的麵粉。\n2.一種舞蹈。起源於拉丁美洲，由墨西哥土風舞蛻變而來。舞曲節拍是四分之四或二分之二拍，節奏可快可慢，每兩小節有恰恰恰的伴唱聲。不需舞伴便可起舞，多由女性帶領，男性跟隨起舞。§英chacha[例]他跳恰恰時，舞姿翩翩，儀態曼妙，吸引了眾人目光。"]],"恰當":[["ㄑㄧㄚˋ ㄉㄤˋ","適當、合適。[例]這件事你處理得很恰當。"]],"悄悄":[["ㄑㄧㄠˇ ㄑㄧㄠˇ","1.寂靜、沒有聲響的樣子。[例]他躡著腳悄悄的進門，深怕驚醒了睡夢中的父親。\n2.憂愁的樣子。[例]憂心悄悄\n3.暗中、不為人知的。[例]他為了給新婚妻子一個驚喜，悄悄的安排了慶祝生日的活動。"]],"悄悄話":[["ㄑㄧㄠˇ ㄑㄧㄠˇ ㄏㄨㄚˋ","指輕聲細語，祕密不欲人知的話。[例]她最喜歡乘機撒嬌，向媽媽說些悄悄話。"]],"悔恨":[["ㄏㄨㄟˇ ㄏㄣˋ","後悔怨恨。[例]當父親過世後，他才悔恨自己沒有盡到為人子女的責任。"]],"悔過":[["ㄏㄨㄟˇ ㄍㄨㄛˋ","承認並懺悔過失。[例]他當著父母的面悔過認錯，並且立誓重新做人。"]],"悟出":[["ㄨˋ ㄔㄨ","領會、明白。[例]經過多日的思索，他終於悟出解答這道數學題的方法。"]],"悠哉":[["ㄧㄡ ㄗㄞ","悠閒自在的樣子。[例]他悠哉的在公園中閒逛，享受冬天溫暖的陽光。"]],"悠閒":[["ㄧㄡ ㄒㄧㄢˊ","閒適自得而無所牽掛。[例]爺爺悠閒地在公園裡散步。"]],"患得患失":[["ㄏㄨㄢˋ ㄉㄜˊ ㄏㄨㄢˋ ㄕ","沒得到時怕得不到，得到以後又怕失去。指因在意個人的利害得失而憂慮不安。[例]他做事患得患失，不能果決，經常誤了時機。"]],"患者":[["ㄏㄨㄢˋ ㄓㄜˇ","病人。[例]最近流行感冒，前往醫院求診的患者很多。"]],"悲傷":[["ㄅㄟ ㄕㄤ","哀痛傷心。[例]景物依舊，人事已非，悲傷之情不禁油然而生。"]],"悲劇":[["ㄅㄟ ㄐㄩˋ","1.一種戲劇類型。內容以敘述主要人物不幸遭遇為主，而結局令人感傷痛苦。[例]梁祝是齣有名的愛情悲劇。_x000D_\n2.比喻悲慘不幸的事件。[例]酒後切勿駕車，以免釀成悲劇。"]],"悲天憫人":[["ㄅㄟ ㄊㄧㄢ ㄇㄧㄣˇ ㄖㄣˊ","憂傷時局多變，哀憐百姓疾苦。[例]她懷著悲天憫人的襟懷，幫助了許多貧苦無依的人。"]],"悲慘":[["ㄅㄟ ㄘㄢˇ","悲傷慘痛。[例]我們應切記這次火災所帶來的悲慘教訓，時時小心謹慎才是。"]],"悶熱":[["ㄇㄣ ㄖㄜˋ","溫度較高，空氣不流通所造成的燥熱。[例]臺北盆地夏天非常悶熱，令人十分不舒服。"]],"情形":[["ㄑㄧㄥˊ ㄒㄧㄥˊ","事情所呈現的狀態。[例]他手術後復原的情形相當良好，再過幾天就可以出院了。"]],"情有獨鍾":[["ㄑㄧㄥˊ ㄧㄡˇ ㄉㄨˊ ㄓㄨㄥ","特別鍾愛某一事物。[例]我向來不愛吃水果，唯獨對香蕉情有獨鍾。"]],"情況":[["ㄑㄧㄥˊ ㄎㄨㄤˋ","事情所呈現的狀態。[例]警方已派員前往出事現場，了解實際情況。"]],"情緒":[["ㄑㄧㄥˊ ㄒㄩˋ","心理學上指個體因外在的刺激或內在的身體狀況所引起的心理狀態。包括喜、怒、哀、懼、愛、惡、欲等。泛指心情。[例]面對凶手時，受害者家屬的情緒顯得相當激動。"]],"情誼":[["ㄑㄧㄥˊ ㄧˋ","人與人之間彼此關愛的情感。[例]他們多年來相互扶持，情誼深厚。"]],"惋惜":[["ㄨㄢˋ ㄒㄧˊ","嘆惜、令人感覺可惜。[例]這麼聰明的人竟誤入歧途，不免令人惋惜。"]],"惕勵":[["ㄊㄧˋ ㄌㄧˋ","心存警戒而自我激勵。[例]日夜惕勵"]],"惜墨如金":[["ㄒㄧˊ ㄇㄛˋ ㄖㄨˊ ㄐㄧㄣ","原指作畫時墨色宜一遍遍地薄塗，最後才能達到漸次深入，濃淡有致的深厚效果，而不宜一次大量使用濃墨，後引申指不輕易落墨、下筆。[例]他向來惜墨如金，創作雖不多，卻件件是精品。"]],"惜福":[["ㄒㄧˊ ㄈㄨˊ","珍惜福分，不隨意揮霍。[例]要懂得惜福，才能知足常樂。"]],"惡劣":[["ㄜˋ ㄌㄧㄝˋ","不好、很壞。[例]行為惡劣、態度惡劣"]],"惡化":[["ㄜˋ ㄏㄨㄚˋ","情況轉壞。[例]病情惡化、水質惡化"]],"惡貫滿盈":[["ㄜˋ ㄍㄨㄢˋ ㄇㄢˇ ㄧㄥˊ","所作罪惡如繩貫錢，已周遍滿溢。[例]這槍擊犯惡貫滿盈，死有餘辜。"]],"惡魔":[["ㄜˋ ㄇㄛˊ","1.宗教上指引誘人作惡，阻礙人修持善道的惡神。[例]信仰可以幫助人除去心中的惡魔。　△魔鬼、邪魔\n2.比喻極為凶惡狠毒的人。[例]殺人惡魔"]],"惦記":[["ㄉㄧㄢˋ ㄐㄧˋ","思念、掛念。[例]她時時惦記著那些孤苦無依的老人，希望能給予一些援助。"]],"想法":[["ㄒㄧㄤˇ ㄈㄚˇ","對事物的看法、意見。[例]他缺少主見，每當面臨抉擇時，老是要問問旁人的想法。"]],"愁緒":[["ㄔㄡˊ ㄒㄩˋ","憂愁的情緒。[例]她因長久沒有家中的消息而滿懷愁緒。"]],"愈加":[["ㄩˋ ㄐㄧㄚ","更加。[例]這問題被他一攪和，變得愈加難以解決了。"]],"愉快":[["ㄩˊ ㄎㄨㄞˋ","欣悅、快樂。[例]保持愉快的心情來工作，往往可以事半功倍。"]],"愉悅":[["ㄩˊ ㄩㄝˋ","快樂、喜悅。[例]他親切的服務態度，令顧客感到愉悅。"]],"意外":[["ㄧˋ ㄨㄞˋ","1.料想不到。[例]一向小氣的他竟然慷慨解囊，令所有人大感意外。\n2.意料之外的不幸事件。[例]在海邊游泳要注意安全，以免發生意外。"]],"意志":[["ㄧˋ ㄓˋ","思想志向，即人類自行決定行為的能力。[例]他意志堅定，做任何事都全力以赴，堅持到底。"]],"意思":[["ㄧˋ ˙ㄙ","1.意旨、意義。[例]這段文字的意思艱深，不容易了解。\n2.情趣、趣味。[例]晚會冷場太多，沒什麼意思。\n3.道義、交情。[例]把難題推給好朋友，實在太不夠意思了。\n4.表示心意。[例]大家各憑能力捐點錢意思意思，不必勉強。"],["ㄧˋ ㄙ","心意、想法。[例]仔細推敲對方的意思，似乎同意我們的看法。"]],"意涵":[["ㄧˋ ㄏㄢˊ","事物所包含的意義。[例]這篇文章雖淺顯易懂，卻有深刻的意涵，耐人尋味。"]],"意義":[["ㄧˋ ㄧˋ","1.意旨、含意。[例]他重覆閱讀幾次之後，才真正了解書中的意義。\n2.行為、事物的價值或重要性。[例]大難不死，使他深刻體會生命的意義。"]],"愕然":[["ㄜˋ ㄖㄢˊ","受驚而失神的樣子。[例]對這個突如其來的消息，眾人不禁為之愕然。"]],"愚弄":[["ㄩˊ ㄋㄨㄥˋ","欺騙玩弄。[例]在愚人節當天以惡作劇愚弄他人，應注意玩笑的分寸。"]],"愚笨":[["ㄩˊ ㄅㄣˋ","愚昧笨拙，反應不靈巧。[例]很多成績不好的學生只是學習意願不高，並非資質愚笨。"]],"愚蠢":[["ㄩˊ ㄔㄨㄣˇ","呆蠢笨拙。[例]為了趕時間而冒生命危險闖越平交道，是害人害己的愚蠢行為。"]],"愛不釋手":[["ㄞˋ ㄅㄨˋ ㄕˋ ㄕㄡˇ","喜歡得捨不得放手。[例]他一見到那個貝殼，就愛不釋手的把玩。"]],"愛心":[["ㄞˋ ㄒㄧㄣ","關愛的心。[例]他從小就充滿愛心，喜歡幫助別人。"]],"愛惜":[["ㄞˋ ㄒㄧˊ","愛護珍惜。[例]他只知用功讀書，卻不知愛惜眼睛，以致近視日益加深。"]],"愛憐":[["ㄞˋ ㄌㄧㄢˊ","疼愛憐惜。[例]她哭泣時的模樣惹人愛憐。"]],"愛戴":[["ㄞˋ ㄉㄞˋ","敬愛擁戴。[例]執政者勤政愛民，必定會受人民愛戴。"]],"愜意":[["ㄑㄧㄝˋ ㄧˋ","滿意、舒適。[例]他近來事事順利，日子過得十分愜意。"]],"感動":[["ㄍㄢˇ ㄉㄨㄥˋ","情緒因受外界刺激而有所震撼、激盪。[例]他的一席話深深的感動了我。"]],"感受":[["ㄍㄢˇ ㄕㄡˋ","1.感覺、領會。[例]她那親切和藹的笑容，讓我感受到無比的溫馨。\n2.感染。[例]他因感受風寒而病倒在床，必須請兩天病假好好休養。"]],"感官":[["ㄍㄢˇ ㄍㄨㄢ","動物接收外界種種刺激的器官。如耳、目、鼻、舌、皮膚等。[例]大都會五光十色的生活，容易使人的感官迷失。　△感覺器"]],"感恩":[["ㄍㄢˇ ㄣ","感謝他人的恩惠。[例]永保一顆感恩的心，生活就會充滿樂趣和意義。"]],"感慨":[["ㄍㄢˇ ㄎㄞˇ","有所感觸而發出慨嘆。[例]看到朋友一個個飛黃騰達，他不由得感慨起自己的懷才不遇。"]],"感懷":[["ㄍㄢˇ ㄏㄨㄞˊ","內心有所感觸。[例]面對此情此景，感懷往日歡樂時光，不覺黯然神傷。"]],"感激":[["ㄍㄢˇ ㄐㄧ","真心感謝。[例]你的盛情款待，真是讓我感激不盡。"]],"感謝":[["ㄍㄢˇ ㄒㄧㄝˋ","因受惠而表示謝意。[例]很感謝你的鼎力相助，使我得以度過這次難關。"]],"愧疚":[["ㄎㄨㄟˋ ㄐㄧㄡˋ","慚愧不安。[例]在朋友有難時，未能及時伸出援手，使他感到非常愧疚。"]],"慈悲":[["ㄘˊ ㄅㄟ","佛教用語。慈指給予眾生安樂；悲指拔除眾生的痛苦。後轉為慈愛、悲憫的意思。[例]多數的宗教本著慈悲為懷的精神，教導世人互助互愛。"]],"慈愛":[["ㄘˊ ㄞˋ","仁慈且富有愛心。多指長輩對晚輩的愛而言。[例]母親的慈愛溫暖著每個孩子的心房。"]],"慈眉善目":[["ㄘˊ ㄇㄟˊ ㄕㄢˋ ㄇㄨˋ","形容慈祥、和善的容貌。[例]看他慈眉善目的，一定是個好人。"]],"慈祥":[["ㄘˊ ㄒㄧㄤˊ","慈善祥和。[例]祖母見到兒孫們，臉上總會露出慈祥的笑容。"]],"態度":[["ㄊㄞˋ ㄉㄨˋ","1.人的容貌舉止。[例]他的態度從容，一副很鎮定的樣子。\n2.對事情採取的主張或立場。[例]對於這件事，他尚未表明態度，我們先不要下定論。"]],"慌張":[["ㄏㄨㄤ ㄓㄤ","慌忙緊張的樣子。[例]他頭腦不夠冷靜，一旦遇到緊急事故，便慌張得不知所措。"]],"慎終追遠":[["ㄕㄣˋ ㄓㄨㄥ ㄓㄨㄟ ㄩㄢˇ","終，父母之喪。遠，祖先。慎終追遠指依禮慎重辦理父母喪事，祭祀要誠心地追念遠祖。語出《論語．學而》。[例]在重要的傳統節日祭祖是慎終追遠的表現。"]],"慎重":[["ㄕㄣˋ ㄓㄨㄥˋ","謹慎認真不苟且。[例]經過慎重的考慮之後，他決定放棄這個計畫。"]],"慎防":[["ㄕㄣˋ ㄈㄤˊ","小心防範。[例]出入公共場合，請注意隨身攜帶的貴重物品，慎防扒手。"]],"慘痛":[["ㄘㄢˇ ㄊㄨㄥˋ","悲痛。[例]經過這次慘痛的教訓後，他再也不敢亂服成藥了。"]],"慘白":[["ㄘㄢˇ ㄅㄞˊ","蒼白。[例]他目睹車禍的發生，當場面色慘白，看來受到不小的驚嚇。"]],"慘遭":[["ㄘㄢˇ ㄗㄠ","悲慘的遭遇到。[例]他在這次山崩中，不幸慘遭活埋。"]],"慘重":[["ㄘㄢˇ ㄓㄨㄥˋ","十分嚴重。[例]這次颱風過境，造成全臺各地損失慘重。"]],"慚愧":[["ㄘㄢˊ ㄎㄨㄟˋ","1.羞愧。[例]他在發現自己做錯事後，感到十分慚愧後悔。\n2.僥倖、難得。常用作自謙之詞。[例]本人不才，竟能獲獎，真是慚愧！慚愧！"]],"慢吞吞":[["ㄇㄢˋ ㄊㄨㄣ ㄊㄨㄣ","形容說話或動作很慢的樣子。[例]你有什麼事就快點說，別慢吞吞的，真令人著急。"]],"慢慢":[["ㄇㄢˋ ㄇㄢˋ","1.平緩的樣子。[例]你先冷靜下來，聽我慢慢的將事情說清楚。\n\t\n2.漸漸。[例]上班一個月後，他慢慢的進入狀況了。"]],"慢跑":[["ㄇㄢˋ ㄆㄠˇ","以和緩的速度跑步。[例]慢跑是他最喜歡的運動。"]],"慣例":[["ㄍㄨㄢˋ ㄌㄧˋ","常例，成為習慣的處理方式。[例]依照慣例，在球賽開打前，兩方選手會先行禮握手，以表示君子風度。"]],"慣用":[["ㄍㄨㄢˋ ㄩㄥˋ","習慣使用。[例]他慣用左手做事，是個左撇子。"]],"慧根":[["ㄏㄨㄟˋ ㄍㄣ","1.佛教以智慧可破除煩惱，達觀真理，生一切功德，以成聖道，故稱為「慧根」，為五根之一。後多指人對佛法信悟的能力。[例]師父發現他極具慧根，而將他引入佛門。\n2.生而具有的才華、能力。[例]他在數理方面頗具慧根，可以好好栽培。"]],"慰勞":[["ㄨㄟˋ ㄌㄠˋ","用言語或物質慰問勞苦或有功的人。[例]公司將舉辦國外旅遊，以慰勞員工。"]],"慰問":[["ㄨㄟˋ ㄨㄣˋ","安慰問候。[例]閒暇時，她常和朋友到養老院慰問老人。"]],"慶祝":[["ㄑㄧㄥˋ ㄓㄨˋ","對值得欣喜或紀念的事表示慶賀祝福。[例]全國各界正積極準備慶祝雙十國慶的活動。"]],"慶賀":[["ㄑㄧㄥˋ ㄏㄜˋ","向有喜慶之事的人道賀。[例]為慶賀哥哥考上第一志願，爸爸送給他一套床頭音響。"]],"慷慨":[["ㄎㄤ ㄎㄞˇ","1.大方、不吝嗇。[例]王先生為人慷慨，出手大方，時常一擲千金而面不改色。\n2.志氣高昂。[例]慷慨激昂、慷慨赴義"]],"憂愁":[["ㄧㄡ ㄔㄡˊ","1.擔憂發愁。[例]他因籌不出這筆醫藥費而十分憂愁。\n2.憂傷哀愁。[例]聽音樂可以讓我鬆弛神經，忘卻憂愁。"]],"憂慮":[["ㄧㄡ ㄌㄩˋ","煩惱擔心。[例]母親為了大哥的婚事十分憂慮。"]],"憎恨":[["ㄗㄥ ㄏㄣˋ","厭惡痛恨。[例]憎恨製造對立，包容才能和平相處。"]],"憎惡":[["ㄗㄥ ㄨˋ","怨恨、不喜歡。[例]他們之間結怨已久，彼此深深的憎惡著對方。"]],"憐惜":[["ㄌㄧㄢˊ ㄒㄧˊ","同情愛惜。[例]看她弱不禁風的模樣，令人心生憐惜。"]],"憐愛":[["ㄌㄧㄢˊ ㄞˋ","憐惜疼愛。[例]這個小女孩活潑聰明，十分惹人憐愛。"]],"憤怒":[["ㄈㄣˋ ㄋㄨˋ","生氣、發怒。[例]他的個性溫和，很少看見他如此憤怒。"]],"憤恨":[["ㄈㄣˋ ㄏㄣˋ","憤怒、怨恨。[例]憤恨不平、憤恨難消"]],"憤慨":[["ㄈㄣˋ ㄎㄞˇ","憤怒而激動。[例]對歹徒綁架學童的作法，大家感到憤慨不已。"]],"懇切":[["ㄎㄣˇ ㄑㄧㄝˋ","誠懇真摯。[例]看他說得那麼懇切，你就答應他的請求吧！"]],"應付":[["ㄧㄥ ㄈㄨˋ","應該支付、付給。[例]這批貨物的應付帳款為十萬元。"],["ㄧㄥˋ ㄈㄨˋ","1.對事或人採取合宜的應對措施。[例]這個問題很棘手，他可能應付不來。\n2.敷衍。[例]如果有人找經理，請小王先去應付一下。"]],"應和":[["ㄧㄥˋ ㄏㄜˋ","呼應、響應。"]],"應對":[["ㄧㄥˋ ㄉㄨㄟˋ","言語間的對答。[例]父母經常告誡我們，與人應對要有禮貌。"]],"應接不暇":[["ㄧㄥˋ ㄐㄧㄝ ㄅㄨˋ ㄒㄧㄚˊ","形容美景繁多，令人目不暇給。後亦形容事物繁多紛至，讓人應付不來。語出南朝宋．劉義慶《世說新語．言語》。[例]春節將至，趕辦年貨的人潮讓商家應接不暇。"]],"應有盡有":[["ㄧㄥ ㄧㄡˇ ㄐㄧㄣˋ ㄧㄡˇ","該有的都有。形容非常齊備。[例]百貨公司的貨色齊全，應有盡有。"]],"應用":[["ㄧㄥˋ ㄩㄥˋ","1.切合實用的。[例]應用數學、應用美術\n2.使用。[例]這種方法在目前應用得極為普遍。"]],"應當":[["ㄧㄥ ㄉㄤ","應該。[例]為人子女者應當孝順父母親。"]],"應許":[["ㄧㄥˋ ㄒㄩˇ","承諾、許可。[例]父母已經應許妹妹暑假到國外遊覽。"]],"應該":[["ㄧㄥ ㄍㄞ","1.理所當然、分內所當為。[例]我們應該盡力做好環保，給下一代一個乾淨的地球。_x000D_\n2.表示推測，有不確定之意。[例]他到現在還沒出現，應該是路上塞車了。"]],"應驗":[["ㄧㄥˋ ㄧㄢˋ","預言或預感與後來發生的事實相符。[例]沒想到他當初說的話果然應驗。"]],"懊悔":[["ㄠˋ ㄏㄨㄟˇ","深切後悔。[例]他對於打架鬧事，而被學校記過，感到相當懊悔。"]],"懊惱":[["ㄠˋ ㄋㄠˇ","心中悔恨、悶悶不樂。[例]對於因為自己一時的貪念所犯下的錯誤，他懊惱不已。"]],"懦弱":[["ㄋㄨㄛˋ ㄖㄨㄛˋ","膽怯軟弱。[例]他個性懦弱，即使受到不合理的對待也不敢表示自己的不滿。"]],"懶惰":[["ㄌㄢˇ ㄉㄨㄛˋ","懈怠不勤奮，不喜歡勞動、工作。[例]他一改以往懶惰的習性，發憤向學，終於以優異的成績畢業。"]],"懶散":[["ㄌㄢˇ ㄙㄢˇ","懶惰散漫的樣子。[例]為了避免退休後日漸懶散，他決定投身社會的公益活動。"]],"懷恨":[["ㄏㄨㄞˊ ㄏㄣˋ","心裡記恨。[例]他們倆相互懷恨對方許久，直到誤會化解才和好如初。"]],"懷抱":[["ㄏㄨㄞˊ ㄅㄠˋ","1.抱在懷裡。[例]小妹每晚總是要懷抱著洋娃娃才能入睡。\n2.胸前。[例]她依偎在母親懷抱裡，不知不覺就睡著了。\n3.內心存有、心中蘊含。[例]他懷抱著遠大的理想，獨自到異鄉奮鬥。"]],"懷疑":[["ㄏㄨㄞˊ ㄧˊ","心中存有疑惑。[例]他做事一向負責認真，從沒有人懷疑他的工作熱忱。"]],"懸崖勒馬":[["ㄒㄩㄢˊ ㄧㄞˊ ㄌㄜˋ ㄇㄚˇ","瀕臨懸崖而能及時勒住奔馬。比喻人面臨險境，能及時回頭醒悟。[例]他一度吸毒成癮，幸而後來懸崖勒馬，努力戒除，才未造成終身的遺憾。"]],"懸梁刺股":[["ㄒㄩㄢˊ ㄌㄧㄤˊ ㄘˋ ㄍㄨˇ","懸梁，將頭髮用繩子綁在屋梁上防止打瞌睡。刺股，用錐子刺腿保持清醒。懸梁刺股比喻發憤學習。[例]他年輕時效法古人懸梁刺股的精神刻苦讀書，才有今天的成就。"]],"懸殊":[["ㄒㄩㄢˊ ㄕㄨ","相差很遠。[例]這場比賽雙方實力懸殊，還沒開打便可預見結果。"]],"懸賞":[["ㄒㄩㄢˊ ㄕㄤˇ","提供賞酬，公開徵求別人做某事。今多用於緝捕嫌犯、尋找失物等。[例]警方提供五十萬元的懸賞獎金，鼓勵民眾提供破案線索。"]],"戀慕":[["ㄌㄧㄢˋ ㄇㄨˋ","愛戀、仰慕。[例]他雖然長期旅居國外，但是對父母家人的戀慕之情卻與時俱深。"]],"戀戀不捨":[["ㄌㄧㄢˋ ㄌㄧㄢˋ ㄅㄨˋ ㄕㄜˇ","十分留戀，捨不得離開。[例]畢業前夕，全班同學都顯得戀戀不捨、離情依依。"]],"戀棧":[["ㄌㄧㄢˋ ㄓㄢˋ","原指馬貪戀豆料。後比喻貪戀官祿名位。[例]經過幾番宦海沉浮，他再也無心戀棧，決定辭官歸隱。"]],"戀舊":[["ㄌㄧㄢˋ ㄐㄧㄡˋ","眷念、思慕舊的人事物。[例]她很戀舊，童年時的玩具還完整保存到現在。"]],"戎裝":[["ㄖㄨㄥˊ ㄓㄨㄤ","軍裝。[例]父親身著筆挺的戎裝，顯得英姿煥發，意氣豪邁。"]],"成功":[["ㄔㄥˊ ㄍㄨㄥ","達成目標、成就功業。[例]凡事只要努力不懈，最後一定會成功。"]],"成效":[["ㄔㄥˊ ㄒㄧㄠˋ","功效、效果。[例]這種藥雖然貴，可是成效非常好。"]],"成為":[["ㄔㄥˊ ㄨㄟˊ","變成。[例]他靠自己的努力成為事業有成的企業家，可說是白手成家的典範。"]],"成熟":[["ㄔㄥˊ ㄕㄡˊ","1.植物成長的顛峰時期，一般指開花、結果的階段。[例]此時正是草莓成熟的季節，許多果園都開放供民眾採摘。\n2.事態的完全發展。[例]由於時機尚未成熟，此事暫時不便對外公布。\n3.指人類生理、心理上的完全發育狀態。[例]幾年不見，小華已經長大成熟了。"]],"成績":[["ㄔㄥˊ ㄐㄧ","績效評量。[例]小明的學業成績十分優異，每學期都是全班第一名。"]],"成群":[["ㄔㄥˊ ㄑㄩㄣˊ","群聚。[例]下課後，小學生們成群結伴的玩耍。"]],"成群結隊":[["ㄔㄥˊ ㄑㄩㄣˊ ㄐㄧㄝˊ ㄉㄨㄟˋ","形容一群群的人或動物集合在一起行動。[例]放假時，他們成群結隊出外遊玩。"]],"成長":[["ㄔㄥˊ ㄓㄤˇ","1.生理上的變化，長成、長大。[例]小明在父母的呵護下成長茁壯。\n2.績效的增加。[例]經濟成長"]],"我們":[["ㄨㄛˇ ˙ㄇㄣ","稱包括本身在內的若干人。[例]我們是在公司的酒會上認識的。"]],"或是":[["ㄏㄨㄛˋ ㄕˋ","或者。[例]這件事由你來負責，或是你想找別人幫忙？"]],"截長補短":[["ㄐㄧㄝˊ ㄔㄤˊ ㄅㄨˇ ㄉㄨㄢˇ","取有餘以補不足。[例]父親工作收入不多，幸賴母親截長補短，才能使一家人生活無虞。"]],"戰戰兢兢":[["ㄓㄢˋ ㄓㄢˋ ㄐㄧㄥ ㄐㄧㄥ","形容謹慎小心的樣子。[例]戰戰兢兢，如臨深淵，如履薄冰。（《詩經．小雅．小旻》）"]],"戰火":[["ㄓㄢˋ ㄏㄨㄛˇ","古代舉烽火以示防警，今則泛指戰爭。[例]許多珍貴的寶物在戰火中損毀，實在令人惋惜！"]],"戰略":[["ㄓㄢˋ ㄌㄩㄝˋ","1.作戰的策略。[例]由於將軍的戰略非常完善，我們打了一場漂亮的勝仗。\n2.比喻指導全局的策略。[例]他們依教練的戰略上場比賽，果然締造佳績。"]],"戰績":[["ㄓㄢˋ ㄐㄧ","戰爭或爭鬥後獲取的成績。[例]這次我軍深夜出擊，獲得輝煌的戰績。"]],"戲劇":[["ㄒㄧˋ ㄐㄩˋ","透過演員將某種故事或情節，以動作、歌唱、對白等方式表演出來的藝術。[例]戲劇通常能反映出一個時代的社會生活與思想。"]],"戲弄":[["ㄒㄧˋ ㄋㄨㄥˋ","愚弄、捉弄他人。[例]他常戲弄人，讓大家都相當反感。"]],"戲耍":[["ㄒㄧˋ ㄕㄨㄚˇ","1.愚弄、戲弄他人。[例]看到大夥都笑了，他才發現原來自己被戲耍了。\n2.玩耍。[例]小弟弟每天總要到公園戲耍一番，才會感到快樂、滿足。"]],"戶口名簿":[["ㄏㄨˋ ㄎㄡˇ ㄇㄧㄥˊ ㄅㄨˋ","政府發給每戶人家，用來記載一戶人口基本資料的簿冊。包括戶籍所在、戶口稱謂、姓名、血型、身分證字號、出生別、出生年月日、役別、父母姓名、配偶姓名等欄位。"]],"戶外":[["ㄏㄨˋ ㄨㄞˋ","門外、室外。[例]利用假日到戶外郊遊踏青，可以紓解平時工作所帶來的壓力。"]],"戶籍":[["ㄏㄨˋ ㄐㄧˊ","人口和家庭登記制度中，以戶為單位，所登記的戶與戶內個人資料。[例]戶籍登記、戶籍謄本"]],"房子":[["ㄈㄤˊ ˙ㄗ","房屋。[例]他打算把房子賣掉，搬到別的地方去。"]],"房屋":[["ㄈㄤˊ ㄨ","固定在土地上可供居住或工作等的建築物。[例]這棟房屋外表雖然老舊，但裡面的裝潢還很新。"]],"房舍":[["ㄈㄤˊ ㄕㄜˋ","房屋。[例]他準備將這些老舊的房舍拆掉重建。"]],"房門":[["ㄈㄤˊ ㄇㄣˊ","房間的門。[例]他沒關上房門，從客廳還是可以看到他的一舉一動。"]],"房間":[["ㄈㄤˊ ㄐㄧㄢ","房屋內的隔間。[例]我們家有三個房間，其中兩間是臥房，一間是書房。"]],"所以":[["ㄙㄨㄛˇ ㄧˇ","1.因此、因而。常與「因為」連用，表示因果關係。[例]他因為吃得太多，所以覺得肚子好脹。\n2.原因、理由。[例]問其所以"]],"所向披靡":[["ㄙㄨㄛˇ ㄒㄧㄤˋ ㄆㄧ ㄇㄧˇ","風吹到的地方，草木就跟著倒下。比喻力量所到之處，敵人紛紛潰散，無法阻擋。[例]本校棒球隊在這次校際聯賽中所向披靡，再度蟬聯冠軍。"]],"所謂":[["ㄙㄨㄛˇ ㄨㄟˋ","1.所說的。[例]他因為貪心而人財兩失，真是所謂賠了夫人又折兵。\n2.某些人所說的。有不承認、不贊同的意思。[例]商店所謂特賣，其實有些是商人出清庫存貨品的手段。"]],"扁舟":[["ㄆㄧㄢ ㄓㄡ","小船。[例]一葉扁舟"]],"扁食":[["ㄅㄧㄢˇ ㄕˊ","北平方言。指餛飩、水餃、鍋貼之類的麵食。　△餛飩"]],"扇子":[["ㄕㄢˋ ˙ㄗ","一種搖動生風以驅除熱氣的用具。[例]爺爺搖著扇子在庭院裡乘涼。"]],"手不釋卷":[["ㄕㄡˇ ㄅㄨˋ ㄕˋ ㄐㄩㄢˋ","釋，放下。手不釋卷指手中總是拿著書卷。形容勤奮好學。[例]無論在何處，他總是手不釋卷，難怪學問如此淵博。"]],"手勢":[["ㄕㄡˇ ㄕˋ","表達意思時用手所做的姿勢。[例]正當我要開口說話時，媽媽卻做了一個手勢要我閉嘴。"]],"手印":[["ㄕㄡˇ ㄧㄣˋ","1.手的印痕。[例]小弟弟玩泥巴時，在牆上留了兩個手印。\n2.特指按在供狀、契據等文件上的指紋。[例]證人在筆錄上按下手印以示負責。"]],"手套":[["ㄕㄡˇ ㄊㄠˋ","套在手上，用以保護及禦寒的用具。[例]交通警察戴著白手套指揮交通，看起來很顯眼。"]],"手把":[["ㄕㄡˇ ㄅㄚˋ","機車、自行車或某些機器上供手執持、掌控的部分。[例]爸爸騎車時，總是兩手穩穩的抓住手把，一點也不敢大意。"]],"手指":[["ㄕㄡˇ ㄓˇ","手掌末端的部分，左、右手各有五根。[例]她的手指像小嬰兒般纖細、柔嫩。　△手指頭　◎"]],"手掌":[["ㄕㄡˇ ㄓㄤˇ","手的中心部分。[例]爺爺拿了一把糖果放在妹妹的手掌上。　◎"]],"手杖":[["ㄕㄡˇ ㄓㄤˋ","拄著走路的棍子。[例]奶奶年紀大了，必須拿著手杖才能走路。　△拐杖"]],"手背":[["ㄕㄡˇ ㄅㄟˋ","手掌的反面。[例]爺爺的手背滿布皺紋，像是刻劃著他一生經歷的滄桑。"]],"手腕":[["ㄕㄡˇ ㄨㄢˋ","1.手與臂相接的部分。[例]奶奶的手腕因過於使力而扭傷了。　◎\n2.手段、本事。[例]耍手腕、交際手腕"]],"手臂":[["ㄕㄡˇ ㄅㄧˋ","手腕以上到肩胛的部分。[例]她的右手臂被熱水燙傷後就失去正常功能。　◎"]],"手舞足蹈":[["ㄕㄡˇ ㄨˇ ㄗㄨˊ ㄉㄠˋ","手、腳舞動跳躍。形容非常高興喜悅的樣子。語本《孟子．離婁上》。[例]她一聽到獲得頭獎的消息，立刻高興得手舞足蹈。"]],"手錶":[["ㄕㄡˇ ㄅㄧㄠˇ","戴在手腕的小錶。[例]他送給她一只手錶當作生日禮物。　△手表、腕錶"]],"手電筒":[["ㄕㄡˇ ㄉㄧㄢˋ ㄊㄨㄥˇ","以乾電池或充電電池為電源，便於隨手攜帶的筒形照明器。[例]哥哥拿著手電筒去尋找掉在草堆裡的鑰匙。"]],"才智":[["ㄘㄞˊ ㄓˋ","才能與智慧。[例]他憑著聰明才智，順利度過許多難關。"]],"才能":[["ㄘㄞˊ ㄋㄥˊ","才智與能力。[例]他擁有絕佳的協商才能，最適宜從政。"]],"才藝":[["ㄘㄞˊ ㄧˋ","才華與技藝。[例]學習任何才藝，都必須投注相當的心力，才能成功。"]],"扎根":[["ㄓㄚ ㄍㄣ","植物的根部往土裡生長。比喻深入底層，建立基礎。[例]海洋志工隊積極培育小志工，希望讓環保觀念向下扎根。"]],"打仗":[["ㄉㄚˇ ㄓㄤˋ","作戰。[例]有些種族複雜的國家，經年累月的打仗，弄得民不聊生。"]],"打包":[["ㄉㄚˇ ㄅㄠ","整理並包紮物品。[例]搬家時，最好將這些書先行打包。"]],"打扮":[["ㄉㄚˇ ㄅㄢˋ","1.妝飾儀容。[例]今晚的宴會，她打扮得很得體。\n2.衣著穿戴。[例]從她的穿著打扮，可以看得出來是富貴人家出身的。"]],"打折":[["ㄉㄚˇ ㄓㄜˊ","降低商品的售價。[例]在打折期間，百貨公司常可見到大批購物人潮。"]],"打招呼":[["ㄉㄚˇ ㄓㄠ ㄏㄨ","1.人與人之間，以寒暄問候或打手勢來互相致意。[例]她見到熟人，總是不忘打招呼。\n\t\n2.事情進行前，先通知或接洽相關的人，以求順利成功。[例]這件事我已經和他打招呼了相信一定沒問題。"]],"打掃":[["ㄉㄚˇ ㄙㄠˇ","灑掃、掃除清理。[例]這房子太髒了，應該好好打掃一番。"]],"打撈":[["ㄉㄚˇ ㄌㄠ","從水中撈取東西。[例]工作人員在失事現場打撈飛機殘骸。"]],"打擊":[["ㄉㄚˇ ㄐㄧˊ","1.敲打。[例]他擅長用鼓棒打擊大小不同的鼓，發出美妙的音樂。\n2.挫折、刺激。[例]他無視於失敗的打擊，仍繼續努力朝目標前進。\n3.棒、壘球上指打擊手以棒擊球。[例]接下來，輪到強棒打擊，很有得分的希望。"]],"打敗":[["ㄉㄚˇ ㄅㄞˋ","1.戰爭或競爭中失敗。[例]這場球賽如果我們被打敗，就會遭到淘汰。\n2.戰勝。[例]他奮勇力戰，終於打敗敵手。"]],"打架":[["ㄉㄚˇ ㄐㄧㄚˋ","互相毆打。[例]他因和人打架而受傷了。"]],"打滾":[["ㄉㄚˇ ㄍㄨㄣˇ","1.躺在地上來回翻滾。[例]小狗在沙堆裡打滾玩耍。\n2.浮沉周旋。[例]我在商場中打滾已有三十年了，這點小事還難不倒我。"]],"打瞌睡":[["ㄉㄚˇ ㄎㄜ ㄕㄨㄟˋ","坐著或靠著斷斷續續的睡。[例]今天我太累了，不知不覺就在公車上打瞌睡，錯過了該下的車站。"]],"打破":[["ㄉㄚˇ ㄆㄛˋ","1.破壞、擊碎。[例]小弟因為打破窗戶玻璃而被父親責罵。\n2.突破。[例]他打破運動會的一百公尺短跑紀錄。"]],"打算":[["ㄉㄚˇ ㄙㄨㄢˋ","考慮、計劃。[例]我打算畢業後，先工作一年，然後再出國留學。"]],"打聽":[["ㄉㄚˇ ㄊㄧㄥ","探問。[例]他到街上去打聽消息。"]],"打造":[["ㄉㄚˇ ㄗㄠˋ","以手工製造。[例]這條項鍊打造得相當精緻。"]],"打針":[["ㄉㄚˇ ㄓㄣ","將藥液注射到有機體內。[例]小孩最怕打針了。"]],"打鐘":[["ㄉㄚˇ ㄓㄨㄥ","學校、機關團體等表示上、下課或上、下班的信號。[例]打鐘了！趕快進教室上課吧！"]],"打開":[["ㄉㄚˇ ㄎㄞ","1.推開、拉開、掀開。[例]打開門、打開書本、打開鍋蓋\n2.打破目前的侷限。[例]打開局面、打開門路、打開一條血路"]],"打雷":[["ㄉㄚˇ ㄌㄟˊ","帶異性電的雲層接觸時，產生強烈閃光及發出巨大聲響的現象。[例]那個小孩從小就怕打雷，一聽到雷聲，就摀住耳朵，躲了起來。"]],"打鬥":[["ㄉㄚˇ ㄉㄡˋ","互相毆打。[例]他們倆為了一些小事就打鬥起來了。"]],"托兒所":[["ㄊㄨㄛ ㄦˊ ㄙㄨㄛˇ","學前兒童的保育機構。分半日托、日托、全托，目的在接受委託，代為照顧年幼的子女。[例]他們夫妻倆白天都得上班，只好將小孩送到托兒所。　△託兒所"]],"托福":[["ㄊㄨㄛ ㄈㄨˊ","1.依托別人的福氣，使自己幸運。常用於回話時，謙稱自己運氣不錯。[例]這次能平安歸來，真是托福了。\n2.一種針對非英語系國家的留美學生所舉行的英語能力測驗。§英TOEFL[例]考完托福後，他隨即著手申請留學事宜。"]],"托育":[["ㄊㄨㄛ ㄩˋ","託付別人，代為養育照顧。[例]托育中心、托育機構"]],"托腮":[["ㄊㄨㄛ ㄙㄞ","以手掌捧著面頰。[例]他在那裡托腮沉思已經很久了，不知道究竟在想些什麼！"]],"扭傷":[["ㄋㄧㄡˇ ㄕㄤ","身體在活動時用力過猛或不小心，使筋骨或肌肉受傷。[例]筋骨扭傷應及早治療，以免惡化。"]],"扭曲":[["ㄋㄧㄡˇ ㄑㄩ","1.扭動物體使其形態改變。[例]為了扮鬼臉取悅小孩，他努力地扭曲自己的臉。\n2.歪曲、顛倒。[例]為了替自己開脫罪嫌，他極力扭曲事實。"]],"扭轉":[["ㄋㄧㄡˇ ㄓㄨㄢˇ","1.掉轉、旋轉。[例]他一看到那個討厭的人，立刻扭轉身子離去。\n2.扳轉、改變。[例]扭轉局勢、扭轉形象"]],"扭轉乾坤":[["ㄋㄧㄡˇ ㄓㄨㄢˇ ㄑㄧㄢˊ ㄎㄨㄣ","比喻將局面整個轉變過來。通常是指由逆勢轉為順勢。[例]看他自信滿滿，我們也都期待著他能扭轉乾坤，再奪回失去的訂單。"]],"扮演":[["ㄅㄢˋ ㄧㄢˇ","化裝演出。[例]在這齣舞臺劇裡，我扮演一個警察。"]],"扶梯":[["ㄈㄨˊ ㄊㄧ","有扶手的樓梯。[例]他身體有點不舒服，所以順著扶梯，慢慢走回房間。"]],"扶疏":[["ㄈㄨˊ ㄕㄨ","枝葉繁茂，四處伸展的樣子。[例]公園中花木扶疏，綠意盎然，是個休憩的好地方。"]],"批准":[["ㄆㄧ ㄓㄨㄣˇ","上級對下級請求的事項或意見表示同意。[例]總經理批准了他的辭呈，下個月他就可以離職了。"]],"批判":[["ㄆㄧ ㄆㄢˋ","評論判斷。[例]他一向留心時事，經常批判社會的種種不合理現象。"]],"批改":[["ㄆㄧ ㄍㄞˇ","修改文章、公文或作業等，並加評語。[例]當老師的很忙，白天要上課，晚上還得批改學生的作業。"]],"批評":[["ㄆㄧ ㄆㄧㄥˊ","1.評論是非好壞。通常針對缺點、錯誤提出意見或加以攻擊。[例]遭人批評的時候，要先冷靜的自我反省，不要急於反擊或辯駁。\n2.對文學或藝術品加以分析、比較及評價。[例]文學批評"]],"扼腕":[["ㄜˋ ㄨㄢˋ","用手握腕。表示內心嘆息、惋惜、失意或憤怒等不平情緒。[例]傑出優秀的他不幸遇難，師長們聞之無不扼腕。"]],"找尋":[["ㄓㄠˇ ㄒㄩㄣˊ","尋覓索求。[例]她四處找尋，總找不著走失的愛犬。"]],"承受":[["ㄔㄥˊ ㄕㄡˋ","接受、負荷。[例]她這半輩子以來所承受的苦，是外人無法體會的。"]],"承認":[["ㄔㄥˊ ㄖㄣˋ","1.供認、招認。[例]嫌犯終於承認那樁銀行搶案是他犯下的。_x000D_\n2.接納、認可。"]],"承諾":[["ㄔㄥˊ ㄋㄨㄛˋ","應允同意。[例]對於做不到的事，我們不要輕易下承諾。"]],"技法":[["ㄐㄧˋ ㄈㄚˇ","技巧和方法。[例]習畫者一旦準確掌握所學派別的技法，便能有更優異的表現。"]],"技能":[["ㄐㄧˋ ㄋㄥˊ","專門的技術和能力。[例]為了提升技術員的專業技能，公司決定近期送他們到國外進修。"]],"技藝":[["ㄐㄧˋ ㄧˋ","講究技巧性的表演藝術或手藝。[例]要學會任何一項特殊的技藝，都必須花費相當的苦心與時間。"]],"抄寫":[["ㄔㄠ ㄒㄧㄝˇ","照原文書寫下來。[例]老師叫小明上臺將課文抄寫一遍。"]],"抄球":[["ㄔㄠ ㄑㄧㄡˊ","球賽時從對方球員的側面或背面搶球。[例]他以矯捷的身手抄球，隨後快跑運球上籃。"]],"抄襲":[["ㄔㄠ ㄒㄧˊ","1.抄錄或因襲模仿他人作品以為己作。[例]這篇散文因有抄襲嫌疑而被取消名次。\n2.軍隊繞道前進，由敵軍的側面或背面突擊。[例]我方採抄襲戰略而大敗敵軍。"]],"抄錄":[["ㄔㄠ ㄌㄨˋ","照原文抄寫。[例]他作筆記最仔細了，老師寫在黑板上的字，他都一字不漏的抄錄下來。"]],"抉擇":[["ㄐㄩㄝˊ ㄗㄜˊ","選擇。[例]在就業與升學之間，你應早作抉擇。"]],"把持":[["ㄅㄚˇ ㄔˊ","1.獨自掌握操縱，不許他人參與。[例]把持大權、把持朝政\n2.約束、控制。[例]面對各種誘惑的時候，要能夠把持得住。"]],"把握":[["ㄅㄚˇ ㄨㄛˋ","1.抓住、掌握。[例]把握機會、把握人生方向\n2.成功的信心。[例]這場比賽我沒有把握取勝。"]],"把脈":[["ㄅㄚˇ ㄇㄞˋ","中醫以食、中、無名三指端按在被檢查者的橈動脈部位，探查脈象變化的診察方式。[例]中醫師透過把脈來診斷病人的健康狀況。"]],"抑制":[["ㄧˋ ㄓˋ","壓抑控制。[例]他終究抑制不住心中的悲傷，眼淚奪眶而出。"]],"抑或":[["ㄧˋ ㄏㄨㄛˋ","或者。[例]不管你的行為是有意，抑或無意，反正都傷了父母親的心了。"]],"抒發":[["ㄕㄨ ㄈㄚ","表達、發洩。[例]適當的抒發情緒，有助於身心健康。"]],"抓住":[["ㄓㄨㄚ ㄓㄨˋ","捉住、掌握住。[例]這張照片充分抓住了她的神韻。"]],"抓緊":[["ㄓㄨㄚ ㄐㄧㄣˇ","緊抓著，牢牢的握著。[例]過馬路時，弟弟抓緊媽媽的手不放。"]],"投入":[["ㄊㄡˊ ㄖㄨˋ","1.擲入、丟入。[例]垃圾要投入垃圾桶，才不會造成環境汙染。\n2.心意專注。[例]畫畫是他的興趣，只要一進畫室，他便全心投入繪畫的世界中。"]],"投手":[["ㄊㄡˊ ㄕㄡˇ","棒球或壘球比賽中，投球讓對方擊球員打擊的防守者。[例]他在本屆棒球比賽中獲選為最佳投手。"]],"投稿":[["ㄊㄡˊ ㄍㄠˇ","將文稿送交報社、雜誌社、出版社等，供採用登載。[例]他對寫作很有興趣，常向各大雜誌社投稿。"]],"投筆從戎":[["ㄊㄡˊ ㄅㄧˇ ㄘㄨㄥˊ ㄖㄨㄥˊ","戎，指軍隊或戰爭。投筆從戎指棄文從軍。典出《後漢書．卷四十七．班超傳》。[例]經過審慎的考慮，他決心投筆從戎，完成報效國家的心願。"]],"投訴":[["ㄊㄡˊ ㄙㄨˋ","向有關部門申訴。[例]消費者發現有廣告不實的情形時，可以向消費者文教基金會投訴。"]],"投降":[["ㄊㄡˊ ㄒㄧㄤˊ","停止抵抗，向對方降順。[例]警察包圍搶匪，勸他棄械投降。"]],"抗拒":[["ㄎㄤˋ ㄐㄩˋ","抵抗拒絕。[例]美食當前，令人食指大動，難以抗拒其誘惑。"]],"抗爭":[["ㄎㄤˋ ㄓㄥ","對不滿意的措施或意見，極力抗拒，以爭取權益。[例]對於這樣無理的要求，我一定要抗爭到底。"]],"抗衡":[["ㄎㄤˋ ㄏㄥˊ","對抗。指彼此勢力相敵，不相上下。[例]拿破崙在十九世紀初席捲了大半的歐洲，所到之處，幾乎無人可與之抗衡。"]],"抗議":[["ㄎㄤˋ ㄧˋ","對他人的意見或措施表示反對。[例]我們對他不合理的要求提出嚴重抗議。"]],"折回":[["ㄓㄜˊ ㄏㄨㄟˊ","中途返回。[例]走到半路，他才想起關門時忘了拔鑰匙，連忙折回。"]],"折扣":[["ㄓㄜˊ ㄎㄡˋ","1.貨物按照定價減去一個數目後出售。[例]折扣是商家促銷的一種手法。\n2.比喻與事實不能完全相符。[例]他性喜誇張，聽他的話一定要打個折扣。"]],"折損":[["ㄓㄜˊ ㄙㄨㄣˇ","損失、虧損。[例]因天災造成農作物折損時，可視情形向政府申請補助。"]],"折斷":[["ㄓㄜˊ ㄉㄨㄢˋ","用外力把東西弄斷。[例]他不小心把向同學借來的尺折斷了。"]],"折疊":[["ㄓㄜˊ ㄉㄧㄝˊ","把物體的一部分翻轉和另一部分緊密相連。[例]為攜帶方便、節省空間，所有的露營裝備幾乎都可折疊。 △摺疊"]],"折磨":[["ㄓㄜˊ ㄇㄛˊ","1.使精神或肉體上承受痛苦。[例]他在飽受病痛折磨的情形下，仍奮力完成那部鉅著。\n2.在精神或肉體上所承受的痛苦。[例]那種喪夫喪子的折磨，不是一般人所承受得了的。"]],"折返":[["ㄓㄜˊ ㄈㄢˇ","半途轉回。[例]登山隊因遇暴風雪而取消原定計畫，暫時折返基地觀望。"]],"折騰":[["ㄓㄜ ㄊㄥˊ","反覆。引申為折磨。[例]折騰了老半天，我終於把問題解決了。"]],"披肩":[["ㄆㄧ ㄐㄧㄢ","披搭在肩上的服飾。[例]這件披肩搭配旗袍比較好看。"]],"披露":[["ㄆㄧ ㄌㄨˋ","發表、宣布、顯露出來。[例]消基會向媒體披露不合衛生標準的食品商名單，使消費大眾免於受騙。"]],"抬價":[["ㄊㄞˊ ㄐㄧㄚˋ","提高價錢。[例]年節將屆，各物嚴禁抬價。"]],"抬頭":[["ㄊㄞˊ ㄊㄡˊ","1.舉起頭來。[例]抬頭挺胸\n2.書信或公文行文時，遇有尊稱則另行提行書寫。[例]正式的書信文件，抬頭及稱謂等格式細節都應注意。\n3.支票、統一發票上指來往戶頭的戶名。[例]洽購公物時，通常會要求廠商在發票上填上抬頭，以利報帳。"]],"抬頭挺胸":[["ㄊㄞˊ ㄊㄡˊ ㄊㄧㄥˇ ㄒㄩㄥ","身體挺立，很有精神的樣子。[例]閱兵大典上，國軍健兒個個抬頭挺胸，精神飽滿。"]],"抬高":[["ㄊㄞˊ ㄍㄠ","1.將物體舉高。[例]請把桌子抬高一點，好讓我能順利打掃。\n2.提高。[例]抬高物價"]],"抱怨":[["ㄅㄠˋ ㄩㄢˋ","訴說心中的不滿、怨恨。[例]他總是不斷的抱怨上天對他不公平。"]],"抵免":[["ㄉㄧˇ ㄇㄧㄢˇ","抵消減免。[例]插班生已修過相同科目的學分，可以抵免，不必再修。"]],"抵抗":[["ㄉㄧˇ ㄎㄤˋ","抵禦、抗拒。[例]萬里長城是為了抵抗外族侵略而建造的。"]],"抵擋":[["ㄉㄧˇ ㄉㄤˇ","抵禦、抗拒。[例]你只穿一件薄衫，恐怕無法抵擋外頭刺骨的寒風。"]],"抵禦":[["ㄉㄧˇ ㄩˋ","抵擋防禦。[例]長城是為了抵禦外族侵略而修建的。"]],"抵達":[["ㄉㄧˇ ㄉㄚˊ","到達。[例]坐了三、四個小時的車終於抵達了目的地。"]],"抹布":[["ㄇㄛˇ ㄅㄨˋ","用來擦拭的布。[例]請拿塊抹布將桌面擦乾淨。　◎"]],"抹煞":[["ㄇㄛˇ ㄕㄚ","一筆勾消、絲毫不顧。[例]不要因為小小的過失，就完全抹煞他過去的功勞。"]],"押解":[["ㄧㄚ ㄐㄧㄝˋ","拘送、押運。[例]警方在押解人犯途中，必須嚴加戒備。"]],"抽屜":[["ㄔㄡ ㄊㄧˋ","設在桌子或櫃子中，可以推拉或上鎖的置物匣。[例]他的私人信件都放在書桌左邊的抽屜。　◎"]],"抽獎":[["ㄔㄡ ㄐㄧㄤˇ","抽出得獎人，贈以獎品。[例]這個贈獎活動定於月底公開抽獎。"]],"抽空":[["ㄔㄡ ㄎㄨㄥˋ","抽出空閒時間。[例]他雖然很忙，每天仍會抽空看些書刊雜誌。"]],"抽筋":[["ㄔㄡ ㄐㄧㄣ","筋肉痙攣作痛。[例]感染破傷風會有抽筋的現象。"]],"抽籤":[["ㄔㄡ ㄑㄧㄢ","1.在神廟中抽取書有籤號的竹籤以卜吉凶。[例]這件事他實在難以決定，只好到廟裡去抽籤問神。\n2.遇事難以決定時，為求公平而依人數做籤，用以抽取決定的方式。[例]這次的報名人數眾多，但參加的名額有限，所以將抽籤決定。"]],"拂曉":[["ㄈㄨˊ ㄒㄧㄠˇ","天將亮時。[例]拂曉時分，雞鳴四起。"]],"拆除":[["ㄔㄞ ㄔㄨˊ","拆掉、去除。[例]在規勸無效後，工務局決定強行拆除違建。"]],"拈香":[["ㄋㄧㄢˊ ㄒㄧㄤ","原指撮香焚燒以敬拜神佛。後泛指祭拜鬼神。[例]拈香祭拜"]],"拉攏":[["ㄌㄚ ㄌㄨㄥˇ","攀交、籠絡。[例]他極力拉攏對方，希望減少一個敵手。"]],"拉車":[["ㄌㄚ ㄔㄜ","1.藉由人力或畜力拖行使車輛前進。[例]農業機具的發明，幾乎完全取代了牛隻耕田、拉車的工作。_x000D_\n2.駕車或搭車。[例]遠距而又緊湊的賽程，讓球員們飽嚐長途拉車之苦。"]],"拉鋸":[["ㄌㄚ ㄐㄩˋ","1.雙方各執鋸子的一端，一來一往地鋸東西。[例]拉鋸的動作看似簡單，其實要保持平衡與力道的均勻，並非易事。_x000D_\n2.比喻雙方你來我往，相持不下。[例]這場球賽是標準的拉鋸戰，下半場才開始，雙方就已經第八度平手了。"]],"拉麵":[["ㄌㄚ ㄇㄧㄢˋ","1.一種麵食。將麵粉加水和好，略放一段時間，使得水分充分滲入麵粉中，然後將它用力拉長並對折，撲上乾麵粉再拉，如此成倍數增加，拉成許多麵條。因不斷揉拉，吃起來較具韌勁。[例]這家館子的拉麵風味獨特，吸引了許多老饕。\n2.將麵糰用手拉長後對折，撲上乾麵粉再拉的過程。[例]園遊會上，我們請來飯店的大師傅為遊客表演拉麵的工夫。　△扯麵"]],"拌勻":[["ㄅㄢˋ ㄩㄣˊ","攪拌均勻。[例]沖牛奶時加糖要拌勻，否則糖會多沉澱在杯底。"]],"拌合":[["ㄅㄢˋ ㄏㄜˊ","攪拌在一起。[例]把石灰、細砂和泥土拌合起來，就是三合土。"]],"拍子":[["ㄆㄞ ˙ㄗ","1.用來拍打東西的器具。[例]蒼蠅拍子\n2.量詞。計算音樂節奏的單位。[例]四拍子、二拍子"]],"拍手":[["ㄆㄞ ㄕㄡˇ","鼓掌，雙手相擊拍。[例]拍手稱快、拍手叫好、拍手大笑"]],"拍打":[["ㄆㄞ ㄉㄚˇ","輕輕的打。[例]她輕輕的拍打衣服，將灰塵抖掉。"]],"拍攝":[["ㄆㄞ ㄕㄜˋ","利用攝影器材將人或物的形象記錄在軟片上。[例]他正在拍攝一部原住民生活的紀錄片。"]],"拍照":[["ㄆㄞ ㄓㄠˋ","拍攝相片。[例]畢業典禮後，許多學生在校園內拍照留念。"]],"拐彎抹角":[["ㄍㄨㄞˇ ㄨㄢ ㄇㄛˋ ㄐㄧㄠˇ","比喻說話或做事不直爽。[例]他說話總愛拐彎抹角，繞了一大圈才進入主題。"]],"拒絕":[["ㄐㄩˋ ㄐㄩㄝˊ","不接受、不答應。[例]為了維持健康，民眾拒絕食用添加色素、防腐劑的食品。"]],"拓印":[["ㄊㄚˋ ㄧㄣˋ","將石碑或金石器物上的文字、圖案顯現在紙張上，稱為「拓印」。[例]他將那塊石碑的字拓印到紙上，準備寫一篇研究的文章。"]],"拓展":[["ㄊㄨㄛˋ ㄓㄢˇ","開拓發展。[例]拓展業務、拓展國民外交"]],"拓本":[["ㄊㄚˋ ㄅㄣˇ","指從石碑上拓印下來的紙本。拓印時先將紙張浸溼，敷在碑刻或金石文物上，用毛刷刷平，此時凹刻的字跡、圖案處便會凹下去。等紙晾乾後，再以布包拍打碑面上墨，平坦的地方烏黑一片，有字跡的地方則是空白。墨乾後將紙揭起，整平，即完成摹印的工作。如曹全碑拓本、玄祕塔碑拓本。　◎"]],"拔河":[["ㄅㄚˊ ㄏㄜˊ","一種比賽力氣大小的運動。參賽者分成兩隊，各持繩索的一端，同時用力向後拉，以能將繩上的標識拉過一定界限者為優勝。古代的拔河方式，是兩隊隔河而拔，輸方會掉到水裡。[例]拔河比賽最能展現團隊精神。"]],"拖地":[["ㄊㄨㄛ ㄉㄧˋ","1.垂在地上。[例]她的裙子長得都拖地了，需要修改一下。\n2.用拖把擦抹地面。[例]弟弟每次拖地都馬馬虎虎，爸爸笑他就像在用毛筆寫大字。"]],"拖延":[["ㄊㄨㄛ ㄧㄢˊ","延誤耽擱。[例]他為了處理公司的事情，而拖延了出國的行程。"]],"拖拖拉拉":[["ㄊㄨㄛ ㄊㄨㄛ ㄌㄚ ㄌㄚ","做事慢吞吞，不乾脆俐落。[例]他是個慢郎中，做起事來總是拖拖拉拉的，缺乏效率。"]],"拖泥帶水":[["ㄊㄨㄛ ㄋㄧˊ ㄉㄞˋ ㄕㄨㄟˇ","1.指因糾纏牽扯，而無法直探禪的本源，本為佛教禪宗語。語出《五燈會元．卷十五．開先善暹禪師》。後指做事、說話、寫作等不夠簡潔、乾脆。[例]他的作品多數是長篇大論、拖泥帶水，實在缺乏組織能力。\n2.被泥水沾汙。[例]大雨滂沱造成路上泥濘不堪，只見妹妹回家時拖泥帶水，全身髒兮兮的。"]],"拖車":[["ㄊㄨㄛ ㄔㄜ","須由曳引車或其他車牽引而其本身並無動力的車輛。有全拖車及半拖車之分，可裝載貨物或供運輸之用。[例]搬運工人將貨物逐一搬上拖車，以便運往南部。"]],"拖鞋":[["ㄊㄨㄛ ㄒㄧㄝˊ","一種無後鞋幫的便鞋，多在室內穿用。[例]穿拖鞋出席正式的場合，是不禮貌的行為。"]],"拘捕":[["ㄐㄩ ㄅㄨˇ","捉拿、逮捕。[例]這個通緝犯逃亡多年，終於被拘捕歸案。"]],"拘泥":[["ㄐㄩ ㄋㄧˋ","固執，不知變通。[例]創作時不拘泥於固定的形式，才能有好的作品。"]],"拘留":[["ㄐㄩ ㄌㄧㄡˊ","指行政法上行政罰的一種制裁。即剝奪違反行政法規之受罰行為人身體自由的短期自由罰，期限原則上為一日以上、三日以下，但遇有依法加重時，合計最長得拘留五日。又依社會秩序維護法規定，拘留應在拘留所內執行。[例]他因涉嫌妨害風化，而被處拘留三天。"]],"拘禁":[["ㄐㄩ ㄐㄧㄣˋ","拘捕監禁。[例]我們的人身自由受憲法保障，非經法律程序，相關機關不得隨意拘禁人民。"]],"拚命":[["ㄆㄢˋ ㄇㄧㄥˋ","豁出性命，不計一切。[例]他拚命衝進火場中，終於救出身陷火窟的孩子。"]],"招募":[["ㄓㄠ ㄇㄨˋ","召集徵求。[例]公司最近要招募一批技術人員。"]],"招呼":[["ㄓㄠ ㄏㄨ","1.寒暄、問候或示意的言語、手勢。[例]有什麼事您只要打一聲招呼，我一定幫忙。\n2.接待、款待。[例]今日賀客盈門，主人正忙著招呼客人呢！\n3.呼喚。[例]小哥！你媽媽正在招呼你回家吃飯呢！"]],"招式":[["ㄓㄠ ㄕˋ","武術上的動作。[例]看他耍了一套少林拳的招式，真是虎虎生風！"]],"招手":[["ㄓㄠ ㄕㄡˇ","揮動手臂以示意。[例]他頻頻向我招手，示意我快步前進。"]],"招搖撞騙":[["ㄓㄠ ㄧㄠˊ ㄓㄨㄤˋ ㄆㄧㄢˋ","假借某種名義到處炫耀，進行詐騙。[例]他到處招搖撞騙，最後終於被警察逮捕，移送法辦。"]],"招架不住":[["ㄓㄠ ㄐㄧㄚˋ ㄅㄨˋ ㄓㄨˋ","無法抵擋或沒有力量再支撐下去。[例]我隊實力堅強，每場比賽都讓對手招架不住，輕易獲得冠軍。"]],"招牌":[["ㄓㄠ ㄆㄞˊ","1.商店、機構標識名號的牌子。[例]街道上五花八門的招牌，令人目不暇給。_x000D_\n2.比喻名譽、名聲。[例]他處事非常謹慎，深怕砸了好不容易才建立起來的招牌。_x000D_\n3.拿手的或最具代表性的。[例]紅燒獅子頭是媽媽的招牌美食。"]],"拜託":[["ㄅㄞˋ ㄊㄨㄛ","恭敬請託。[例]鄰居出遠門時，常拜託我照顧他們的小狗。"]],"拜訪":[["ㄅㄞˋ ㄈㄤˇ","拜候、探望。[例]這次到南部出差，母親要我順道去拜訪舅父。"]],"括約肌":[["ㄎㄨㄛˋ ㄩㄝ ㄐㄧ","一種環狀肌。位於賁門、幽門及肛門，能收縮和舒張，為控制食物通過或排泄物排出的關卡。"]],"拭目以待":[["ㄕˋ ㄇㄨˋ ㄧˇ ㄉㄞˋ","比喻期待事情的發展及結果。[例]他撰寫的新書即將出版，許多讀者都拭目以待。"]],"拮据":[["ㄐㄧㄝˊ ㄐㄩ","境況窘迫。多指經濟困難。[例]經濟拮据"]],"拯救":[["ㄓㄥˇ ㄐㄧㄡˋ","援救、救助。[例]義軍的成立，是為了推翻暴政，拯救生活在水深火熱中的人民。"]],"拱手讓人":[["ㄍㄨㄥˇ ㄕㄡˇ ㄖㄤˋ ㄖㄣˊ","輕易的把東西讓給別人。[例]這次比賽中華隊表現失常，冠軍寶座只好拱手讓人。"]],"拳擊":[["ㄑㄩㄢˊ ㄐㄧˊ","一種西洋拳術運動。是一種兩人用拳頭互相對打的活動。比賽分為職業賽和業餘賽兩種。並按體重由輕到重依次分為微量級、中量級和重量級。各級再分為甲、乙、丙、丁四等。競賽規則為：一、拳擊手必須戴手套。二、每回合三分鐘，回合間休息一分鐘。三、若一方被擊倒在地，而無法於十秒鐘內站起，裁判可宣布另一方獲勝。四、不可蓄意毆打對手。[例]拳擊選手都受過嚴格的訓練，個個體格壯碩，孔武有力。　◎"]],"拼圖":[["ㄆㄧㄣ ㄊㄨˊ","一種遊戲。把一張完整的圖案，切割成許多不規則的形狀，再把這些零散的圖塊，拼湊出原圖案。[例]拼圖是一項很好的益智遊戲。"]],"拼湊":[["ㄆㄧㄣ ㄘㄡˋ","將零星的事物聚合起來。[例]好不容易！總算把這些撕碎的紙片拼湊回去了。"]],"拼盤":[["ㄆㄧㄣ ㄆㄢˊ","1.由多種菜餚或水果拼湊而成盤的食品。[例]水果拼盤、什錦拼盤\n2.比喻許多不同東西拼湊在一起。[例]春天花園裡百花齊開，就像五顏六色的彩色拼盤一般。"]],"拼音":[["ㄆㄧㄣ ㄧㄣ","按照字或詞的音節，連綴音素而成音。如將「ㄉ」、「ㄨ」、「ㄥ」拼音，讀出「ㄉㄨㄥ」音。"]],"拾取":[["ㄕˊ ㄑㄩˇ","撿獲、拾得。[例]他在海灘拾取了很多奇形怪狀的石頭。"]],"拾級而上":[["ㄕㄜˋ ㄐㄧˊ ㄦˊ ㄕㄤˋ","順著階梯一步一步的往上走。[例]廟前這階梯叫「青雲梯」，且讓我們拾級而上。"]],"拾金不昧":[["ㄕˊ ㄐㄧㄣ ㄅㄨˋ ㄇㄟˋ","撿到別人遺失的錢財而不據為己有。[例]拾金不昧是值得表揚的行為。"]],"拿手":[["ㄋㄚˊ ㄕㄡˇ","擅長。[例]爬樹是他這個從小在鄉下長大的孩子最拿手的功夫。"]],"拿捏":[["ㄋㄚˊ ㄋㄧㄝ","掌握事情的分寸。[例]對於時機的掌握上他總是拿捏得很準。"]],"持久":[["ㄔˊ ㄐㄧㄡˇ","維持長久，長久堅持。[例]夫妻間要能互助互諒，婚姻才能持久。"]],"持續":[["ㄔˊ ㄒㄩˋ","繼續不斷。[例]這場雨持續下了好幾天還沒有停止的跡象。"]],"指導":[["ㄓˇ ㄉㄠˇ","指示引導。[例]在老師的耐心指導下，學生都有了明顯的進步。"]],"指揮":[["ㄓˇ ㄏㄨㄟ","1.發號施令，指示別人行動。[例]警察在十字路口指揮交通，以維持交通的順暢。\n2.樂隊、合唱團等表演時，以手或指揮棒指示節拍、表情的人。[例]指揮可說是一個樂團的靈魂人物。"]],"指桑罵槐":[["ㄓˇ ㄙㄤ ㄇㄚˋ ㄏㄨㄞˊ","指著桑樹罵槐樹，比喻拐彎抹角的罵人。[例]他在指桑罵槐，難道你聽不出來嗎？"]],"指標":[["ㄓˇ ㄅㄧㄠ","以可觀察或測量的現象，作為另一無法測量事物的情況或屬性的指示。如工業化程度高低，可用汽車產量作為衡量，所以汽車產量就是工業化的指標。[例]指標統計所顯示出的事實，可以作為社會發展規劃的參考。"]],"指責":[["ㄓˇ ㄗㄜˊ","責備、怪罪。[例]他常因辦事不力而遭受老闆指責。"]],"指針":[["ㄓˇ ㄓㄣ","鐘錶或儀表上用以標示時間或度數的針。[例]鐘錶上的指針分為時針、分針、秒針。"]],"按兵不動":[["ㄢˋ ㄅㄧㄥ ㄅㄨˋ ㄉㄨㄥˋ","暫時停住軍事行動，有觀望形勢的意思。今亦指負有任務卻不採取行動。[例]目前情勢未明，我們最好按兵不動，以免遭受損失。"]],"按圖索驥":[["ㄢˋ ㄊㄨˊ ㄙㄨㄛˇ ㄐㄧˋ","原指按照圖象尋求好馬。後指根據資料線索以尋找、探求。語本《漢書．卷六十七．梅福傳》。[例]進入市區後，我們只要照著地圖按圖索驥，就可以找到目的地了。"]],"挑剔":[["ㄊㄧㄠ ㄊㄧ","吹毛求疵，苛求責備。[例]這件事我已盡了全力，請別再挑剔了。"]],"挑戰":[["ㄊㄧㄠˇ ㄓㄢˋ","1.向人尋釁，激起競爭。[例]他透過報章媒體，公開向上一屆的拳王挑戰。_x000D_\n2.艱巨的任務、考驗。[例]我們要勇於面對挑戰，即使失敗也不氣餒。_x000D_\n3.面對考驗，克服困難。[例]我們應該讓孩子在成長中學會負起責任，勇敢挑戰困難。"]],"挑撥":[["ㄊㄧㄠˇ ㄅㄛ","搬弄是非。[例]這種挑撥是非的人，最是可惡！"]],"挑撥離間":[["ㄊㄧㄠˇ ㄅㄛ ㄌㄧˊ ㄐㄧㄢˋ","搬弄是非，分化彼此感情，使人互相猜忌。[例]只要你們倆互相信任，別人是無法從中挑撥離間的。"]],"挑明":[["ㄊㄧㄠˇ ㄇㄧㄥˊ","將意思表達清楚，使對方明瞭。[例]有話就請挑明了說，別拐彎抹角的。"]],"挑燈":[["ㄊㄧㄠˇ ㄉㄥ","撥動燈心、燭蕊，使燈光更亮。[例]挑燈夜話"]],"挑選":[["ㄊㄧㄠ ㄒㄩㄢˇ","選擇。[例]她挑選了幾本好書，送給朋友作為生日禮物。"]],"挖掘":[["ㄨㄚ ㄐㄩㄝˊ","1.掘取。[例]考古學家在古代遺址中挖掘出許多古物。\n2.比喻探求。[例]那位老闆善於挖掘員工的潛能。"]],"挖洞":[["ㄨㄚ ㄉㄨㄥˋ","挖掘洞穴。[例]鼴鼠是一種善於挖洞的動物。"]],"挨家挨戶":[["ㄞ ㄐㄧㄚ ㄞ ㄏㄨˋ","依照次序一家接著一家。[例]衛生單位派人，挨家挨戶的進行消毒工作，希望能杜絕病媒蚊的孳生。"]],"挨打":[["ㄞ ㄉㄚˇ","被打。[例]他因為搗蛋不聽話而挨打。"]],"挨罵":[["ㄞ ㄇㄚˋ","被罵。[例]他做事老是心不在焉，頻頻出錯，難怪常挨罵。"]],"挫折":[["ㄘㄨㄛˋ ㄓㄜˊ","事情進行不順利或遭遇失敗。[例]遭遇挫折不要灰心喪志，只要再接再厲必能成功。"]],"振動":[["ㄓㄣˋ ㄉㄨㄥˋ","1.震盪、撼動。[例]振動人心\n2.物體往返於一定位置間，或物理現象及物理量以一定的振幅反覆進行，有一定的往返週期者，稱為「振動」。[例]電的振動會產生電波，可用來傳達訊息、測量距離等。"]],"振奮":[["ㄓㄣˋ ㄈㄣˋ","振作奮發。[例]聽到本班獲得音樂比賽冠軍，大家都振奮不已。"]],"挺住":[["ㄊㄧㄥˇ ㄓㄨˋ","勉力支撐住。[例]你的心臟較弱，等一下如果聽到什麼不好的消息，可千萬要挺住。"]],"挺直":[["ㄊㄧㄥˇ ㄓˊ","直立不彎曲。[例]立正的時候要把腰幹挺直，看起來才有精神。"]],"挺胸":[["ㄊㄧㄥˇ ㄒㄩㄥ","挺起胸膛。[例]走路要抬頭挺胸，不要彎腰駝背。"]],"挺身而出":[["ㄊㄧㄥˇ ㄕㄣ ㄦˊ ㄔㄨ","毫不畏縮，勇敢的站出來承擔責任。[例]遇到紛爭，他總是挺身而出，善加勸解。"]],"挽回":[["ㄨㄢˇ ㄏㄨㄟˊ","事情將敗壞而想辦法補救或振興。[例]球賽中場休息時，教練與球員們研商對策，企圖挽回頹勢。"]],"捉住":[["ㄓㄨㄛ ㄓㄨˋ","以手握住，捕獲。[例]店主暗中注意了好久，如今總算捉住那名慣竊。"]],"捉弄":[["ㄓㄨㄛ ㄋㄨㄥˋ","戲弄，對人開玩笑。[例]他老是捉弄人家，難怪別人不理他。"]],"捉摸":[["ㄓㄨㄛ ㄇㄛ","揣測、料想。[例]他性情多變，令人難以捉摸。"]],"捍衛":[["ㄏㄢˋ ㄨㄟˋ","保衛、防衛。[例]軍人捍衛國家的精神，真是令人敬佩。"]],"捏麵人":[["ㄋㄧㄝ ㄇㄧㄢˋ ㄖㄣˊ","一種傳統民間技藝。以蒸熟的糯米團加入色料、糖或鹽搓揉均勻，用手指或梳子、剪刀、牛骨籤等工具，以塑造技法捏出許多人物、動物等的樣子。[例]捏麵人這種技藝要達到相當造詣，需要雕塑、繪畫等多項基礎配合。　△米雕"]],"捐款":[["ㄐㄩㄢ ㄎㄨㄢˇ","1.捐獻錢財。[例]災後不到幾天，許多個人與機關團體，紛紛發揮愛心，踴躍捐款救助災戶。\n2.所捐獻的款項。[例]這筆捐款將視各災區的實際需要分配運用。"]],"捐血":[["ㄐㄩㄢ ㄒㄧㄝˇ","捐出血液給需要的人。[例]捐血一袋，救人一命，請大家踴躍響應。"]],"捐贈":[["ㄐㄩㄢ ㄗㄥˋ","捐獻、贈送。[例]目前國內已開始倡導器官捐贈，響應的人不計其數。"]],"捐軀":[["ㄐㄩㄢ ㄑㄩ","為國家犧牲生命或因公喪生。[例]對日抗戰期間，數百萬的國軍為國捐軀，寫下了一段可歌可泣的歷史。"]],"捕手":[["ㄅㄨˇ ㄕㄡˇ","棒球比賽中，在本壘後方的守備隊員。[例]捕手在棒球場上是整個防守陣勢的指揮者。"]],"捕捉":[["ㄅㄨˇ ㄓㄨㄛ","1.追捕捉拿。[例]上野外教學課時，老師要我們捕捉一些昆蟲來進行觀察。\n2.比喻掌握某一事物的特質，使其呈現出來。[例]他擅長用鏡頭捕捉山林之美。"]],"捕撈":[["ㄅㄨˇ ㄌㄠ","在水中捕捉打撈。[例]到野外溪流戲水，不要任意捕撈魚蝦，以免破壞生態。"]],"捕獲":[["ㄅㄨˇ ㄏㄨㄛˋ","捕捉而有所獲得。[例]這艘漁船今日出海捕獲不少大魚。"]],"捧場":[["ㄆㄥˇ ㄔㄤˇ","原指到劇場欣賞演員的表演，今亦指臨場替他人助陣。[例]昨晚我登臺表演，許多好朋友都來捧場。"]],"捧腹":[["ㄆㄥˇ ㄈㄨˋ","用手捧著腹部。多用來指大笑時以手按著肚子的樣子。[例]捧腹大笑、令人捧腹"]],"捧腹大笑":[["ㄆㄥˇ ㄈㄨˋ ㄉㄚˋ ㄒㄧㄠˋ","大笑時用手捧著肚子。[例]他言談詼諧，常令人捧腹大笑。"]],"捧花":[["ㄆㄥˇ ㄏㄨㄚ","捧在手中的花束，通常指婚禮專供新娘捧托的花束。[例]這束捧花主要是由紫玫瑰和滿天星搭配而成。"]],"捲髮":[["ㄐㄩㄢˇ ㄈㄚˇ","1.卷曲的頭髮。[例]那一頭烏黑的捲髮，看起來異常嫵媚動人。\n2.使頭髮捲曲。[例]她在參加宴會之前都會先捲髮、化妝一番。"]],"捷報":[["ㄐㄧㄝˊ ㄅㄠˋ","戰勝的消息。後泛指勝利成功的好消息。[例]每當前線傳來捷報，國人無不歡欣鼓舞。"]],"捷徑":[["ㄐㄧㄝˊ ㄐㄧㄥˋ","1.便捷的近路。[例]警方人員分兩路圍捕歹徒；一路隨後追趕，一路抄捷徑到前頭攔截，終於順利擒獲。\n2.比喻快速便捷的方法。[例]除力學深思之外，沒有任何捷徑可以抵達真知的境界。"]],"掀翻":[["ㄒㄧㄢ ㄈㄢ","掀起翻倒。[例]他與對方談判破裂，憤而掀翻桌子。"]],"掀開":[["ㄒㄧㄢ ㄎㄞ","揭開、翻開。[例]他掀開蓋子，從蒸籠裡拿出熱騰騰的饅頭。"]],"掃墓":[["ㄙㄠˇ ㄇㄨˋ","祭拜打掃墳墓。[例]清明掃墓，是慎終追遠的美德。"]],"掃射":[["ㄙㄠˇ ㄕㄜˋ","1.用機槍迅速地左右往返射擊。[例]在機關槍掃射下，敵軍受創嚴重，終於退走。_x000D_\n2.眼珠很快地轉向各處看看。[例]老師一進門就用嚴厲的眼光掃射教室四周，同學便很快地安靜下來。"]],"掃帚":[["ㄙㄠˋ ㄓㄡˇ","1.掃地用具。以竹枝、芒草等紮成。有長柄。[例]他拿起掃帚把院子裡的枯葉掃成一堆。\n2.植物名。藜科地膚子屬，一年生草本。高一公尺餘。分枝多，葉互生，夏季開花。胞果呈扁球形。莖枝晒乾後可做掃帚。[例]將掃帚的莖枝晒乾後，一端紮起來，另一端不紮，再加上長柄，便是掃把了。　△地膚"]],"掃把":[["ㄙㄠˋ ㄅㄚˇ","掃除塵土、垃圾的用具。古時多以竹枝、芒草，今則多以塑膠紮成，一端散開，以利掃拂。有長柄。[例]每天清晨，王伯伯總會拿著掃把，打掃整條街道，街坊鄰居皆蔚為佳話。"]],"掃描":[["ㄙㄠˇ ㄇㄧㄠˊ","1.利用電子光束、雷射光、無線電波、聲波、超音波等，依次定向、來回、有順序、週期性的移動過程。如雷達、聲納、電視、電腦都是藉著掃描，方能呈現或接收影像。[例]利用雷達掃描，可以偵測到是否有敵機入侵。\n2.將景觀或事物的內容快速的瀏覽一番。[例]他將公文掃描一遍之後，發現事態嚴重，馬上派人處理。"]],"掃興":[["ㄙㄠˇ ㄒㄧㄥˋ","破壞原有的興致。[例]難得的假日，卻因雨而無法去露營，真是掃興！"]],"掃蕩":[["ㄙㄠˇ ㄉㄤˋ","澈底消滅。[例]警方決定大力掃蕩非法行業，以維護社會安寧。"]],"掃除":[["ㄙㄠˇ ㄔㄨˊ","1.清掃汙穢。[例]店家等最後一批客人走了，放下鐵門，開始掃除工作。\n\t\n2.清除有礙前進的事物。[例]登陸敵人陣地前，必須先由工兵部隊進行灘頭掃除地雷工作，以利軍隊推進。"]],"授徒":[["ㄕㄡˋ ㄊㄨˊ","招收學生，傳授學問或技藝。[例]開班授徒"]],"授權":[["ㄕㄡˋ ㄑㄩㄢˊ","有權力者，將權力委託他人或機構，使代為執行。[例]處長已授權張主任來處理這件事。"]],"授與":[["ㄕㄡˋ ㄩˇ","給與、付與。[例]有關單位為了表揚他熱心公益的精神，將授與獎牌一座。"]],"掉落":[["ㄉㄧㄠˋ ㄌㄨㄛˋ","1.掉下、落下。[例]秋風瑟瑟，枯黃的樹葉一片片掉落下來。\n2.遺漏、丟失。[例]昨天我在公車上掉落了一個黑色皮夾。"]],"掌上明珠":[["ㄓㄤˇ ㄕㄤˋ ㄇㄧㄥˊ ㄓㄨ","手掌上的明珠。比喻極受寵愛珍視的人，多指愛女。[例]她就是總經理的掌上明珠。　△掌珠、掌上珠"]],"掌心":[["ㄓㄤˇ ㄒㄧㄣ","手掌中心。[例]孫悟空終究是逃不出如來佛的掌心。"]],"掌握":[["ㄓㄤˇ ㄨㄛˋ","掌管、控制。[例]未來掌握在自己手中，機會來臨之前，應做好充分的準備。_x000D_"]],"掌聲":[["ㄓㄤˇ ㄕㄥ","拍手的聲音。常用以表示鼓勵、稱讚。[例]當掌聲響起，所有的辛勞與汗水都有了代價。"]],"排列":[["ㄆㄞˊ ㄌㄧㄝˋ","1.依照次序排成行列。[例]遠處一片綠油油的稻田，如棋盤般整齊的排列著。\n2.從一組事物中取出一些，而置於某些位置，稱為「排列」。[例]排列組合"]],"排山倒海":[["ㄆㄞˊ ㄕㄢ ㄉㄠˇ ㄏㄞˇ","形容力量巨大，氣勢壯闊。[例]突然一個巨浪排山倒海而來，看得人心驚肉跳。"]],"排擠":[["ㄆㄞˊ ㄐㄧˇ","憑藉勢力或用不正當手段排斥別人。[例]他常為了自己的利益排擠別人，所以沒人願意和他做朋友。"]],"排放":[["ㄆㄞˊ ㄈㄤˋ","放出、排解出。[例]排放汙水、排放廢氣"]],"排斥":[["ㄆㄞˊ ㄔˋ","1.排除駁斥不能相容或不利於自己的人事物。[例]對新的事物應該試著去瞭解，不要一味的排斥。\n2.醫學上指生物體抵抗非本身組織的外來物質，所產生免疫反應的一連串變化。如人體器官移植後的發燒，便是人體的排斥作用之一。[例]人體換腎後，要注意觀察排斥情形，以免引發併發症。"]],"排水":[["ㄆㄞˊ ㄕㄨㄟˇ","將積水或汙水等排除。[例]平時就要清理水溝淤泥，否則大雨一來，無法及時排水，恐將水淹成災。"]],"排練":[["ㄆㄞˊ ㄌㄧㄢˋ","排演練習。[例]儀隊正在排練明天要表演的隊形變化。"]],"排行":[["ㄆㄞˊ ㄏㄤˊ","依長幼次序排列。[例]他在家中排行老么，懂事又乖巧，深得父母寵愛。"]],"排除":[["ㄆㄞˊ ㄔㄨˊ","消除、除去。[例]坍方已經排除，道路恢復暢通。"]],"排隊":[["ㄆㄞˊ ㄉㄨㄟˋ","依照順序排列成行伍。[例]排隊上車、排隊購票、排隊入場　◎"]],"掘井":[["ㄐㄩㄝˊ ㄐㄧㄥˇ","挖井。[例]先民必得掘井才能汲水，現代則有了方便的自來水。"]],"掘取":[["ㄐㄩㄝˊ ㄑㄩˇ","1.挖掘拾取。[例]爺爺用鋤頭在田裡掘取已成熟的地瓜。\n2.發掘吸收。[例]不斷掘取新知，才能使自己的思想觀念更為充實豐富。"]],"掙扎":[["ㄓㄥ ㄓㄚˊ","1.費盡全力勉強支撐或抵抗。[例]為了維持家計，儘管病情嚴重，他仍然掙扎著起來工作。\n2.形容非常猶豫、難以決定。[例]在父母與女友之間，他掙扎了許久，還是割捨不下任何一方。"]],"掙脫":[["ㄓㄥ ㄊㄨㄛ","用力擺脫束縛，以獲得自由。[例]關在牢籠中的禽獸都想掙脫束縛，重返自然呢！"]],"掛念":[["ㄍㄨㄚˋ ㄋㄧㄢˋ","心中繫念、放心不下。[例]爸爸從國外打電話回家說在外一切平安，請家人不用掛念。"]],"掠奪":[["ㄌㄩㄝˋ ㄉㄨㄛˊ","搶奪、奪取。[例]掠奪別人的智慧財產，和偷盜的行為並無差異。"]],"掠影":[["ㄌㄩㄝˋ ㄧㄥˇ","從眼前閃掠過的影像。比喻模糊的印象。[例]浮光掠影"]],"掠食者":[["ㄌㄩㄝˋ ㄕˊ ㄓㄜˇ","捕食他種生物而藉以生存的動物。[例]獅子是非洲草原上的凶猛掠食者。"]],"採取":[["ㄘㄞˇ ㄑㄩˇ","選擇取用。[例]由於家境清寒，他決定採取半工半讀的方式完成學業。"]],"採摘":[["ㄘㄞˇ ㄓㄞ","採取、摘取。[例]他採摘路旁的果實解渴。"]],"採收":[["ㄘㄞˇ ㄕㄡ","採摘、收取。[例]現在正是採收芒果的季節，各農家都非常忙碌。"]],"採納":[["ㄘㄞˇ ㄋㄚˋ","接受。[例]他的改革理念獲上司認同，所以一提出就被採納。"]],"採訪":[["ㄘㄞˇ ㄈㄤˇ","探採尋訪。通常指新聞記者訪問打探消息。[例]他在報社負責採訪財經新聞。"]],"採買":[["ㄘㄞˇ ㄇㄞˇ","1.採購、買辦。[例]學會所需的文具用品，一向由總務負責採買。\n2.學校或團體中負責採購事宜者。尤指買菜的人而言。[例]本校餐廳一向由採買負責採購廚房所需物品。"]],"採購":[["ㄘㄞˇ ㄍㄡˋ","挑選購買。[例]他每星期上菜市場採購一次。"]],"採集":[["ㄘㄞˇ ㄐㄧˊ","採取蒐集。[例]那個生物學家專門研究昆蟲，時常到山中採集標本。"]],"探望":[["ㄊㄢˋ ㄨㄤˋ","拜訪看望。[例]許多慈善團體會定期派遣志工探望獨居的長者，提供各項協助。"]],"探測":[["ㄊㄢˋ ㄘㄜˋ","探察偵測。[例]海底探測"]],"探索":[["ㄊㄢˋ ㄙㄨㄛˇ","探查摸索。[例]太空探索、探索自我、探索真理"]],"探親":[["ㄊㄢˋ ㄑㄧㄣ","探訪親戚。[例]返鄉探親"]],"探訪":[["ㄊㄢˋ ㄈㄤˇ","1.拜訪探問。[例]他打算回國探訪幾位好久不見的老朋友。\n2.訪查、搜尋。[例]他經常遊覽名山，探訪勝景。"]],"探險":[["ㄊㄢˋ ㄒㄧㄢˇ","冒險探索。[例]他經常夢想去南極探險。"]],"接受":[["ㄐㄧㄝ ㄕㄡˋ","收受、接納。[例]他接受記者採訪，說明事件的始末。"]],"接種":[["ㄐㄧㄝ ㄓㄨㄥˋ","將疫苗注射到人或動物體內使人產生抗體，以預防疾病。[例]政府免費為學齡前兒童接種各種疫苗，預防傳染疾病。"]],"接續":[["ㄐㄧㄝ ㄒㄩˋ","連續、持續。[例]校園意外接續發生，教育當局呼籲各校加強維護校園安全。"]],"接觸":[["ㄐㄧㄝ ㄔㄨˋ","1.碰著、觸碰。[例]傷口要盡量避免與手指接觸，以免感染細菌而發炎。\n2.接近、親近。[例]常接觸大自然有益於身心健康。"]],"接近":[["ㄐㄧㄝ ㄐㄧㄣˋ","1.靠近，相離不遠。[例]我家接近圖書館，借閱書籍非常方便。\n2.接觸、親近。[例]老師藉郊遊的機會接近同學，以了解大家的現況。"]],"控制":[["ㄎㄨㄥˋ ㄓˋ","操縱、節制。[例]他已超過標準體重了，醫生建議他除了運動外，還得控制飲食。"]],"控訴":[["ㄎㄨㄥˋ ㄙㄨˋ","泛指原告對被告於民事上侵害他人權益或刑事上的違法行為，請求法院或檢察署予以救濟或制裁被告的訴訟行為。[例]李先生決定近日向法院控訴鄰居侵占他土地的不法行為。"]],"推動":[["ㄊㄨㄟ ㄉㄨㄥˋ","1.推進啟動。[例]大家合力推動陷在泥淖的車子，最後好不容易成功了。\n2.使進展。[例]政府全力推動國民外交，擴大我國在國際的活動空間。"]],"推擠":[["ㄊㄨㄟ ㄐㄧˇ","推開擠入。[例]影迷為了一睹明星的風采，紛紛向前推擠，搶占視線最好的位置。"]],"推測":[["ㄊㄨㄟ ㄘㄜˋ","推想揣測。[例]警察由現場遺留未熄的香煙，推測歹徒才剛剛離開。"]],"推演":[["ㄊㄨㄟ ㄧㄢˇ","推算演繹。[例]希臘物理學家阿基米得由溢出浴缸的水量，推演出計算不規則物體體積的方法來。"]],"推理":[["ㄊㄨㄟ ㄌㄧˇ","一種邏輯的思考方式。由已知或假定的前提來推求結論，或由已知的答案結果反求其理由根據。廣泛應用在心理學、犯罪學、偵辦案件方面。[例]小說人物福爾摩斯擅長以推理方式找出罪案的真凶。"]],"推辭":[["ㄊㄨㄟ ㄘˊ","拒絕。[例]她以要回家照顧小孩為理由，推辭所有的交際應酬。"]],"推銷":[["ㄊㄨㄟ ㄒㄧㄠ","推廣銷售。[例]廠商藉著廣告或試用品等方式來推銷新產品。"]],"推陳出新":[["ㄊㄨㄟ ㄔㄣˊ ㄔㄨ ㄒㄧㄣ","除去老舊的，創造出新的事物或方法。[例]本公司的產品要不斷的推陳出新，以迎合顧客的需求。"]],"掩埋":[["ㄧㄢˇ ㄇㄞˊ","埋藏。[例]這地窖下掩埋著一罈好酒。"]],"掩蓋":[["ㄧㄢˇ ㄍㄞˋ","1.掩蔽、遮蓋。[例]連日來的大雪掩蓋了大地。\n2.隱藏。[例]他雖強作鎮定，仍掩蓋不了內心的驚恐。"]],"掩蔽":[["ㄧㄢˇ ㄅㄧˋ","掩藏遮蔽。[例]遼闊的平原上，一無掩蔽之所。"]],"掩護":[["ㄧㄢˇ ㄏㄨˋ","1.遮掩保護。[例]在混戰中，他掩護我逃走。\n2.包庇。[例]他接受對方許多好處，所以刻意掩護他們。"]],"掩鼻":[["ㄧㄢˇ ㄅㄧˊ","遮住鼻子。[例]路旁的垃圾堆發出惡臭，路人皆掩鼻而過。"]],"措施":[["ㄘㄨㄛˋ ㄕ","為解決某種情況所採取的處理方法。[例]層出不窮的公共危險事件，正好警惕業者要做好公共安全措施。"]],"措辭":[["ㄘㄨㄛˋ ㄘˊ","選用語詞來表達自己的意念。[例]措辭不當容易引起不必要的誤會。"]],"描寫":[["ㄇㄧㄠˊ ㄒㄧㄝˇ","以色彩、文字或圖畫等，把事物的形象、情狀表現出來。[例]他文筆很好，尤其描寫景物栩栩如生，令人讚賞。"]],"描紅":[["ㄇㄧㄠˊ ㄏㄨㄥˊ","初學者根據書法範本上套印的紅字，以毛筆蘸墨，在上面一點一畫依樣描摹。[例]描紅可以幫助我們熟悉字體的基本結構。"]],"描繪":[["ㄇㄧㄠˊ ㄏㄨㄟˋ","1.依樣仔細畫下來。[例]她用畫筆把眼前的景物描繪出來。\n2.用文字摹寫。[例]西遊記中所描繪的人物，個個栩栩如生，躍然紙上。"]],"描述":[["ㄇㄧㄠˊ ㄕㄨˋ","用語言文字來表達事物的情狀。[例]目擊者將當時案發的情形從頭描述一遍。"]],"提供":[["ㄊㄧˊ ㄍㄨㄥ","供應、供給。[例]警方根據目擊證人提供的線索，循線追查，終於偵破此樁搶案。"]],"提前":[["ㄊㄧˊ ㄑㄧㄢˊ","把預定的時間向前挪移。[例]如果工程進行順利，預計明年三月即可提前完工。"]],"提振":[["ㄊㄧˊ ㄓㄣˋ","鼓舞、振作。[例]提振士氣、提振民心"]],"提早":[["ㄊㄧˊ ㄗㄠˇ","將預定的時間挪前。[例]今年的梅雨季提早來臨。"]],"提款":[["ㄊㄧˊ ㄎㄨㄢˇ","將儲存於金融機構的款項提領出來。[例]利用提款機提款既方便又迅速。"]],"提示":[["ㄊㄧˊ ㄕˋ","點出或指出別人所未想到的，以做為思考的線索。[例]經主持人提示，馬上就有人猜出謎底。"]],"提議":[["ㄊㄧˊ ㄧˋ","1.提出主張或意見，以供討論。[例]爸爸提議暑假全家出國旅行一週，大家一致同意。\n2.所提出的意見。[例]到澎湖畢業旅行的提議，經表決後以最高票通過。"]],"提起":[["ㄊㄧˊ ㄑㄧˇ","1.拿起、舉起。[例]他提起公事包，匆匆忙忙的趕去上班。\n2.談到、說起。[例]一提起往事，老先生總顯得神采奕奕，神情愉悅。\n3.振作。[例]他努力提起精神，連夜把作品趕出來。\n4.提出。[例]這件詐欺案，由檢察官提起公訴，現已進入司法程序。"]],"提醒":[["ㄊㄧˊ ㄒㄧㄥˇ","從旁提示或指點，使人注意。[例]多虧你提醒，我才沒錯過今天的會議。"]],"提高":[["ㄊㄧˊ ㄍㄠ","使原來較低的位置、程度、等級、數量、水準等加以提升或增高。[例]提高產量、提高效率、提高聲量"]],"揚名":[["ㄧㄤˊ ㄇㄧㄥˊ","名譽、聲望遠播。[例]揚名國際、揚名立萬"]],"揚言":[["ㄧㄤˊ ㄧㄢˊ","宣揚、散播某種言論。[例]他揚言再過一年，要把公司所有的股份買回。"]],"換季":[["ㄏㄨㄢˋ ㄐㄧˋ","1.季節變換。[例]換季時氣溫冷暖不定，最容易感冒了。\n2.衣著隨季節的變換而改變。[例]學校從下星期起換季，請各位同學著夏季制服。"]],"握拳":[["ㄨㄛˋ ㄑㄩㄢˊ","手指向掌心彎曲抓緊而成拳頭。[例]雙手握拳，放在腰際，前後擺動，才是正確的跑步姿勢。"]],"揭發":[["ㄐㄧㄝ ㄈㄚ","把事情揭露、舉發出來。[例]他舞弊營私被揭發後，受到革職的處分。"]],"揭示":[["ㄐㄧㄝ ㄕˋ","揭露、公布。[例]他以親身經歷揭示、控訴極權暴政的血腥罪行。"]],"揭開":[["ㄐㄧㄝ ㄎㄞ","1.掀開、打開。[例]他揭開鍋蓋加進調味料後，讓它繼續悶煮。_x000D_\n2.揭發、顯露事實真相。[例]由於偵查人員縝密地調查，終於揭開了事件真相，化解了民眾的疑慮。"]],"揮別":[["ㄏㄨㄟ ㄅㄧㄝˊ","揮手告別。[例]他隔著車窗，向月臺上送行的親友揮別。"]],"揮動":[["ㄏㄨㄟ ㄉㄨㄥˋ","揮舞、舞動。[例]球迷們揮動手上的看板，賣力為場上的球隊加油。"]],"揮手":[["ㄏㄨㄟ ㄕㄡˇ","揮動手臂：(1) 表示告別。[例]驪歌初唱，又到了揮手道別的時節。　(2) 示意叫人走開。[例]他不耐煩的揮手，要僕人都退下。　(3) 和人打招呼。[例]在街上看見一個熟悉的身影，他興奮的揮手大叫，沒想到卻認錯了人。"]],"揮毫":[["ㄏㄨㄟ ㄏㄠˊ","運筆寫字或繪畫。[例]畫家提筆揮毫，頃刻間一幅潑墨山水便在眼前呈現了。"]],"揮汗如雨":[["ㄏㄨㄟ ㄏㄢˋ ㄖㄨˊ ㄩˇ","抹掉的汗水如同下雨一般。形容流很多汗。[例]頂著大太陽工作，每個人都揮汗如雨。"]],"揮舞":[["ㄏㄨㄟ ㄨˇ","舉起手臂，或手中拿著東西不斷搖動。[例]女孩揮舞著水袖，優雅的跳了一支祝壽舞。"]],"援軍":[["ㄩㄢˊ ㄐㄩㄣ","增援的軍隊。[例]正當危急之際，忽傳援軍已至，我軍士氣為之大振。"]],"損壞":[["ㄙㄨㄣˇ ㄏㄨㄞˋ","毀壞、破壞。[例]颱風過後，院子裡的花架損壞得十分嚴重。"]],"搏命":[["ㄅㄛˊ ㄇㄧㄥˋ","不顧生命，全力以赴。[例]這位影星經常在影片中搏命演出，從不使用替身。"]],"搏鬥":[["ㄅㄛˊ ㄉㄡˋ","1.徒手或以刀、棍等器物激烈對打。[例]武松就在景陽崗上與老虎展開了一場搏鬥！_x000D_\n2.比喻對抗。[例]他因嚴重車禍，正在加護病房與死神搏鬥。"]],"搖搖晃晃":[["ㄧㄠˊ ㄧㄠˊ ㄏㄨㄤˋ ㄏㄨㄤˋ","左右搖擺，晃動不定的樣子。[例]老王酒喝多了走路搖搖晃晃的，千萬不要讓他開車。"]],"搖撼":[["ㄧㄠˊ ㄏㄢˋ","搖動。[例]小弟弟用力搖撼樹幹，想把果實搖落下來。"]],"搖擺":[["ㄧㄠˊ ㄅㄞˇ","1.來回搖盪、擺動。[例]臺上的熱情演出，使得臺下歌迷都不禁隨著音樂搖擺著身體。\n2.游移、變動。[例]機會難得，別再搖擺不定，以免錯失良機！"]],"搖晃":[["ㄧㄠˊ ㄏㄨㄤˋ","搖擺晃動。[例]強震使得整棟屋子搖晃得相當厲害。"]],"搖曳":[["ㄧㄠˊ ㄧˋ","搖盪、搖晃。[例]湖邊垂柳在風中輕輕搖曳，姿態極美。"]],"搖曳生姿":[["ㄧㄠˊ ㄧˋ ㄕㄥ ㄗ","姿態美妙，婀娜多姿的樣子。[例]晚風吹得滿園的桂花搖曳生姿，清香撲鼻。"]],"搖盪":[["ㄧㄠˊ ㄉㄤˋ","搖擺晃盪。[例]窗口的風鈴隨風搖盪，發出清脆的聲音。"]],"搖籃":[["ㄧㄠˊ ㄌㄢˊ","1.嬰兒的睡具。形狀似籃子，可左右搖動，使嬰兒容易入睡。[例]母親正哼著歌，輕輕推著搖籃哄妹妹入睡。_x000D_\n2.比喻發源地或培育的場所。[例]空軍官校是我國培育空軍飛行員的搖籃。"]],"搖頭":[["ㄧㄠˊ ㄊㄡˊ","頭向左右搖動。通常用以表示拒絕、否定、阻止或不以為然的意思。[例]老爸看了她的成績單後直搖頭嘆氣。"]],"搖頭晃腦":[["ㄧㄠˊ ㄊㄡˊ ㄏㄨㄤˋ ㄋㄠˇ","形容自以為是或自得其樂的樣子。[例]老師每教授《論語》時，總會自己先搖頭晃腦的朗誦一遍。"]],"搗亂":[["ㄉㄠˇ ㄌㄨㄢˋ","擾亂秩序，破壞別人正在進行的事。[例]警察加強戒備，以防不良分子趁機搗亂。"]],"搗鬼":[["ㄉㄠˇ ㄍㄨㄟˇ","暗中使用陰謀詭計。[例]此案之所以會失敗，可能是有人暗中搗鬼。"]],"搜尋":[["ㄙㄡ ㄒㄩㄣˊ","搜求尋覓。[例]經過他多年來四處搜尋，終於找回失散已久的弟弟。"]],"搜救":[["ㄙㄡ ㄐㄧㄡˋ","搜索營救。[例]救難隊出動大批人馬，上山搜救因山崩而受困的學生。"]],"搜索":[["ㄙㄡ ㄙㄨㄛˇ","搜尋探求。[例]在救難隊的全力搜索下，終於將摔落山谷的遊客全數救出。"]],"搞怪":[["ㄍㄠˇ ㄍㄨㄞˋ","玩花樣、耍把戲。[例]別搞怪，被我知道了可饒不了你。"]],"搞鬼":[["ㄍㄠˇ ㄍㄨㄟˇ","暗中使用手段以從事破壞。[例]這件事原可順利完成，全因他從中搞鬼，以致功敗垂成。"]],"搧風":[["ㄕㄢ ㄈㄥ","1.搖動輕而薄的器物以產生風。[例]他拿著扇子，一邊搧風，一邊打瞌睡。\n2.鼓動、挑撥。[例]他正氣得冒火，你就別在一旁搧風了！"]],"搪塞":[["ㄊㄤˊ ㄙㄜˋ","堵塞堤防上的縫隙。比喻敷衍了事。語本《淮南子．人間》。[例]做錯事就該勇於承認，不要找藉口來搪塞。"]],"搬運":[["ㄅㄢ ㄩㄣˋ","把東西搬動、運送到別處。[例]那個花瓶已經在搬運過程中摔壞了。"]],"搭乘":[["ㄉㄚ ㄔㄥˊ","乘坐交通工具。[例]他每天搭乘公車去上班。"]],"搭載":[["ㄉㄚ ㄗㄞˋ","搭乘裝載。[例]這輛旅行車可搭載八個人。"]],"搭配":[["ㄉㄚ ㄆㄟˋ","兩相配合。[例]模特兒身上穿著一襲金色的洋裝，搭配上水晶項鍊，非常亮麗搶眼。"]],"搶修":[["ㄑㄧㄤˇ ㄒㄧㄡ","建築物、道路等損壞時，立即快速修復。[例]電力公司搶修被颱風損壞的設施，以及早恢復供電。"]],"搶先":[["ㄑㄧㄤˇ ㄒㄧㄢ","爭先，趕在別人之前。[例]為獲得獎品，同學們個個搶先舉手回答問題。"]],"搶奪":[["ㄑㄧㄤˇ ㄉㄨㄛˊ","以強力奪取、爭奪。[例]這個搶奪彩球的遊戲，玩起來既緊張又有趣。"]],"搶手":[["ㄑㄧㄤˇ ㄕㄡˇ","商品暢銷，極受群眾喜愛。[例]這本書極為搶手，因而一版再版。"]],"搶答":[["ㄑㄧㄤˇ ㄉㄚˊ","爭先回答。[例]老師的問題剛說完，許多同學就紛紛舉手搶答。"]],"摒除":[["ㄅㄧㄥˋ ㄔㄨˊ","排除。[例]我們應摒除一切困難，勇往直前。"]],"摔倒":[["ㄕㄨㄞ ㄉㄠˇ","跌倒。[例]他不慎摔倒，左手嚴重骨折。"]],"摔跤":[["ㄕㄨㄞ ㄐㄧㄠ","1.跌倒。[例]路面溼滑，不小心就會摔跤。\n2.→摔角"]],"摘取":[["ㄓㄞ ㄑㄩˇ","採摘、採取。[例]西瓜成熟了，可以摘取食用。"]],"摘要":[["ㄓㄞ ㄧㄠˋ","以簡潔的文字作扼要敘述。[例]他從新聞摘要中得知這件重大消息。"]],"摘除":[["ㄓㄞ ㄔㄨˊ","採取、去除。[例]居家附近若發現蜂巢，當請專人來摘除，以免發生危險。"]],"摩娑":[["ㄇㄛˊ ㄙㄨㄛ","用手撫摩。[例]那位孕婦一手摩娑著她隆起的腹部，臉上洋溢著母性的光輝。"]],"摩拳擦掌":[["ㄇㄛˊ ㄑㄩㄢˊ ㄘㄚ ㄓㄤˇ","形容準備行動、躍躍欲試的樣子。[例]球員們個個摩拳擦掌，準備上場比賽。"]],"摩擦":[["ㄇㄛˊ ㄘㄚ","1.兩物接觸並來回擦動。[例]摩擦生熱\n2.比喻爭執或衝突。[例]因為個性、想法、習慣等不同，人與人之間難免發生摩擦。"]],"摯友":[["ㄓˋ ㄧㄡˇ","感情深厚的朋友。[例]在我最失意的時候，幸好有摯友的鼓勵，才讓我重新振作起來。"]],"摯情":[["ㄓˋ ㄑㄧㄥˊ","真誠的情感。[例]我的一片摯情終於感動了頑固的他。"]],"摸彩":[["ㄇㄛ ㄘㄞˇ","贈送財物的抽獎活動。[例]公司今年的尾牙摸彩，獎品豐富，請踴躍參加。"]],"摸索":[["ㄇㄛ ㄙㄨㄛˇ","尋求、探索。[例]他在陶藝方面摸索多年，終於學有所成。"]],"摺紙":[["ㄓㄜˊ ㄓˇ","摺疊紙張。專指將紙張折疊成船、青蛙、帽子等各種不同形狀的手藝。[例]摺紙活動可以訓練手指的靈活度，還可以陶冶性情。"]],"撇開":[["ㄆㄧㄝ ㄎㄞ","拋開不顧。[例]談公事時，必須撇開人情包袱，否則什麼事也辦不成。"]],"撐腰":[["ㄔㄥ ㄧㄠ","給予支持，當靠山。[例]別仗著有人撐腰就有恃無恐，蠻不講理！"]],"撐開":[["ㄔㄥ ㄎㄞ","將事物張開。[例]下雨了，趕快把傘撐開吧！"]],"撒嬌":[["ㄙㄚ ㄐㄧㄠ","仗著對方的寵愛而恣意做出嬌態。[例]小妹不停的向父親撒嬌，嘴裡直嚷著要一個洋娃娃。"]],"撒尿":[["ㄙㄚ ㄋㄧㄠˋ","小便。[例]主人應訓練小狗不要隨地撒尿。"]],"撒旦":[["ㄙㄚ ㄉㄢˋ","基督教中稱魔鬼為「撒旦」，原指反抗上帝而誘人犯罪的惡魔，他是善的仇敵，是上帝和人類的敵對者。§英satan[例]在基督教裡，撒旦是魔鬼的化身，是黑暗的代表。"]],"撒謊":[["ㄙㄚ ㄏㄨㄤˇ","說謊話。[例]他為人誠實，從不撒謊。"]],"撞傷":[["ㄓㄨㄤˋ ㄕㄤ","因撞擊而受傷。[例]他開車撞傷別人，必須賠償一筆醫藥費。"]],"撞擊":[["ㄓㄨㄤˋ ㄐㄧˊ","衝撞、碰擊。[例]這部車子受到嚴重撞擊，恐怕無法再上路了。"]],"撤退":[["ㄔㄜˋ ㄊㄨㄟˋ","放棄陣地或遷離已占領的地區。[例]將軍一見情勢失利，便馬上下令撤退。"]],"撥動":[["ㄅㄛ ㄉㄨㄥˋ","1.划動、轉動。[例]一隻隻小鴨吃力的撥動腳掌，急急忙忙的往前划行。\n2.撩惹、挑弄。[例]撥動心弦"]],"撥開":[["ㄅㄛ ㄎㄞ","將物推開或分開。[例]他用竹竿將草叢撥開，探路前進。"]],"撫平":[["ㄈㄨˇ ㄆㄧㄥˊ","安撫而使其平復。[例]撫平傷口"]],"撫慰":[["ㄈㄨˇ ㄨㄟˋ","安撫慰勉。[例]她的心靈受創甚深，亟須撫慰。"]],"撫摸":[["ㄈㄨˇ ㄇㄛ","用手輕輕觸摸。[例]母親撫摸著嬰兒的臉龐，心裡感到無限的滿足與欣喜。"]],"撫養":[["ㄈㄨˇ ㄧㄤˇ","保護教養。[例]父母把子女撫養成人，是備嘗辛勞的。"]],"播報":[["ㄅㄛˋ ㄅㄠˋ","利用擴音器、收音機或電視機傳送聲音、影像的報導方式。[例]在體育新聞之後，往往接著播報氣象。"]],"播送":[["ㄅㄛˋ ㄙㄨㄥˋ","利用無線或有線電波傳播放送。[例]收音機現正播送一場精彩的球賽。"]],"撲克牌":[["ㄆㄨ ㄎㄜˋ ㄆㄞˊ","一種紙牌。共有五十四張，其中兩張是鬼牌。分黑桃、紅心、方塊、梅花四種花色，每種從一到十三點，其中傑克Ｊ當十一，皇后Ｑ當十二，國王Ｋ當十三，都是人頭圖案。§英poker[例]除夕夜為了守歲，他們玩了一夜的撲克牌。"]],"撲朔迷離":[["ㄆㄨ ㄕㄨㄛˋ ㄇㄧˊ ㄌㄧˊ","形容事物錯綜複雜，難以辨明真相。語本《樂府詩集．卷二十五．橫吹曲辭五．古辭．木蘭詩》二首之一。[例]這個案子的案情撲朔迷離，疑雲重重，令警方傷透腦筋。"]],"撲殺":[["ㄆㄨ ㄕㄚ","消滅、擊殺。[例]每到夏天登革熱流行的季節，衛生單位就會加強撲殺病媒蚊。"]],"撲滅":[["ㄆㄨ ㄇㄧㄝˋ","撲打消滅。[例]一接獲火警通知，消防隊員便迅速趕至現場撲滅大火。"]],"撲空":[["ㄆㄨ ㄎㄨㄥ","白跑一趟，找不到所要找的對象或事物。[例]如果要去拜訪他，請事先以電話相約，以免撲空。"]],"撿拾":[["ㄐㄧㄢˇ ㄕˊ","拾取。[例]校園裡有茂密的松林，吸引許多民眾去撿拾松果。"]],"擁戴":[["ㄩㄥˇ ㄉㄞˋ","擁護愛戴。[例]他以專業而努力的問政表現，受到選民的擁戴。"]],"擁抱":[["ㄩㄥˇ ㄅㄠˋ","1.相擁而抱。[例]家人們輪流與大哥擁抱，依依不捨的送大哥出國求學。\n2.接納、親近。[例]只有認同自己族群的人，才能熱情的擁抱故鄉的土地。"]],"擁擠":[["ㄩㄥˇ ㄐㄧˇ","人、物眾多密集的樣子。[例]在擁擠的人潮中，要謹防扒手。"]],"擁有":[["ㄩㄥˇ ㄧㄡˇ","持有、據有。[例]他擁有一大片未開發的土地。"]],"擂臺":[["ㄌㄟˊ ㄊㄞˊ","古時為比賽武術所搭建的高臺。今泛指比賽時所使用的臺子。[例]擂臺上拳擊選手不斷奮力出拳，臺下觀眾則拼命吶喊加油。"]],"擅改":[["ㄕㄢˋ ㄍㄞˇ","私自更改。[例]身分證上的資料不得擅改，以免觸犯偽造文書罪。"]],"擅用":[["ㄕㄢˋ ㄩㄥˋ","擅自使用。[例]未經他人同意，不得擅用他人物品。"]],"擅自":[["ㄕㄢˋ ㄗˋ","獨斷獨行，自作主張。[例]擅自翻印他人的著作，是觸犯著作權法的侵權行為。"]],"擅長":[["ㄕㄢˋ ㄔㄤˊ","專長，專精於某種技藝或學術。[例]在運動方面，他擅長游泳。"]],"擇期":[["ㄗㄜˊ ㄑㄧˊ","選擇適當的日期。[例]雙方父母都已同意，他們打算儘快擇期舉行婚禮。"]],"擊退":[["ㄐㄧˊ ㄊㄨㄟˋ","打敗敵人使其退走。[例]我方以強大的火力擊退入侵的敵軍。"]],"擋風":[["ㄉㄤˇ ㄈㄥ","阻擋風勢。[例]擋風遮雨"]],"操勞":[["ㄘㄠ ㄌㄠˊ","工作勞苦。[例]他因操勞過度，健康日益惡化。"]],"操場":[["ㄘㄠ ㄔㄤˇ","供軍事操練或體育活動的廣場。一般指學校的運動場。[例]下一節體育課，本班同學將在操場打躲避球。"]],"操心":[["ㄘㄠ ㄒㄧㄣ","1.憂慮、不放心。[例]父母總是為兒女的學業、生活操心不已。\n2.花心思處理事情。[例]這件工作多虧他日夜操心，才能在期限內完成。"]],"操行":[["ㄘㄠ ㄒㄧㄥˋ","品行、品德。[例]在學校除了求取知識，研究學問，更應注重操行，敦厲品德。"]],"擔任":[["ㄉㄢ ㄖㄣˋ","擔負某種職務及責任。[例]他在擔任總經理職務期間，將公司整治得有條不紊，業績從此蒸蒸日上。"]],"擔保":[["ㄉㄢ ㄅㄠˇ","承當保證。[例]經過這次教訓後，我擔保他絕不敢再犯了。"]],"擔子":[["ㄉㄢˋ ˙ㄗ","1.扁擔和掛在兩端用以荷物的東西，後亦指所挑的東西。[例]他把蔬菜放在擔子裡準備挑去市場出售。\n2.負擔的責任。[例]由於雙親早逝，他獨力挑起扶養弟妹的擔子。"]],"擔心":[["ㄉㄢ ㄒㄧㄣ","掛念、不放心。[例]外出時要記得告訴父母親，免得他們擔心。"]],"擔憂":[["ㄉㄢ ㄧㄡ","擔心、憂慮。[例]為人子女，要保重自己的身體，以免父母親擔憂。"]],"擔架":[["ㄉㄢ ㄐㄧㄚˋ","以雙棍為抬桿，棍間裹布，形似床，用來抬送傷患的長條形架子。[例]他兩腿骨折，無法行動，醫護人員用擔架將他送上救護車。　◎"]],"擔當":[["ㄉㄢ ㄉㄤ","擔負、承當。[例]以他的學識經驗和能力，足以擔當此項重責大任。"]],"據稱":[["ㄐㄩˋ ㄔㄥ","根據消息宣稱。[例]據稱這塊空地近期內會開始動工，準備興建一座購物商場。"]],"擠滿":[["ㄐㄧˇ ㄇㄢˇ","充塞。[例]每到午餐時間，這家飯館總是擠滿了人。"]],"擦傷":[["ㄘㄚ ㄕㄤ","皮膚因與粗糙物體摩擦而受傷。[例]他不小心跌倒，兩個膝蓋都擦傷了。"]],"擱淺":[["ㄍㄜ ㄑㄧㄢˇ","1.船隻因水位太低，未能提供所需的浮力而無法行進。[例]這艘船受到強烈颱風的吹襲而擱淺在暗礁上。\n2.比喻事情受阻而停頓。[例]這個議案因客觀環境無法配合而擱淺了。"]],"擴充":[["ㄎㄨㄛˋ ㄔㄨㄥ","擴大、充實。[例]公司看好國際市場的發展潛能，正積極的在海外擴充業務。"]],"擴大":[["ㄎㄨㄛˋ ㄉㄚˋ","增大面積或範圍。[例]本店即將重新改裝，擴大營業。"]],"擴張":[["ㄎㄨㄛˋ ㄓㄤ","擴大伸張。[例]君主極權時代，各朝為擴張自己的領土及勢力範圍，時常出兵征戰。"]],"擷取":[["ㄐㄧㄝˊ ㄑㄩˇ","摘取。[例]對於西方文化，我們只可擷取它的精華，不可全盤接受。"]],"擺動":[["ㄅㄞˇ ㄉㄨㄥˋ","搖擺移動。[例]微風一吹，柳條兒就輕輕的擺動起來。"]],"擾亂":[["ㄖㄠˇ ㄌㄨㄢˋ","破壞、騷擾。[例]隔壁家的狗兒經常在半夜發出吠聲，擾亂鄰居睡眠安寧。"]],"擾人":[["ㄖㄠˇ ㄖㄣˊ","攪亂人，使人不舒服。[例]昨夜蚊聲四起，實在擾人！"]],"攀岩":[["ㄆㄢ ㄧㄢˊ","一種戶外休閒運動項目，指攀爬陡峭岩壁。攀爬者通常需善用地形，並配合鉚釘等器具，逐步上移，以便能順利攻頂。[例]進行攀岩真要步步為營，處處小心，否則一失足成千古恨。"]],"攀爬":[["ㄆㄢ ㄆㄚˊ","抓住物體往上爬。[例]他們沿著山崖往上攀爬。"]],"攀登":[["ㄆㄢ ㄉㄥ","用手抓住東西往上爬。[例]他攀登過很多有名的山峰。"]],"攀談":[["ㄆㄢ ㄊㄢˊ","找機會和人接近、交談。[例]我在酒會上找個機會與他攀談，才知道他的來歷。"]],"攔下":[["ㄌㄢˊ ㄒㄧㄚˋ","攔阻下來。[例]要不是被朋友攔下，他差點就因為一時衝動而和人拳腳相向。"]],"攔住":[["ㄌㄢˊ ㄓㄨˋ","攔擋、阻止。[例]他正要出門，卻被來訪的朋友一把攔住。"]],"攔截":[["ㄌㄢˊ ㄐㄧㄝˊ","1.半途攔阻，截斷去路。[例]警方派員在公路上攔截違規超載的車輛，並開單舉發。\n2.軍事上指船艦或飛機對接近領域的不明目標物，加以鑑別、阻攔或攻擊，使其無法侵入我方的行動。[例]軍方出動空軍攔截侵入領空的飛機。"]],"攔腰":[["ㄌㄢˊ ㄧㄠ","從半中腰圍擋。[例]攔腰抱住"]],"攔阻":[["ㄌㄢˊ ㄗㄨˇ","阻擋、阻止。[例]弟弟在廚房玩火，幸虧媽媽及時攔阻，才避免釀成災禍。"]],"攜帶":[["ㄒㄧ ㄉㄞˋ","提拿佩帶。[例]出外旅行時，攜帶行李，越少越好。"]],"攜手":[["ㄒㄧ ㄕㄡˇ","1.手拉手。比喻感情親密。[例]經過多年的愛情長跑，他們終於決定攜手共度未來。\n2.比喻合作無間。[例]市政建設要靠大家攜手合作，才能達成預期的目標。"]],"攝取":[["ㄕㄜˋ ㄑㄩˇ","吸收、吸取。[例]要攝取均衡的營養，身體才會健康。"]],"攝氏":[["ㄕㄜˋ ㄕˋ","攝氏寒暑表的簡稱。用來表示溫度的高低。為瑞典人攝爾修（Celsius)創造，常用符號Ｃ來表示。[例]因為熱浪襲擊，此地白日氣溫高達攝氏45度。"]],"攤位":[["ㄊㄢ ㄨㄟˋ","擺放攤子的位置。[例]校慶園遊會場設置了各式各樣的攤位，供師生同樂。"]],"攤販":[["ㄊㄢ ㄈㄢˋ","擺攤子出售貨物的攤位或人。[例]這條人行道攤販林立，使人寸步難行。"]],"攪和":[["ㄐㄧㄠˇ ㄏㄨㄛˋ","1.攪拌調和。[例]把麵粉和蛋攪和一下，就可以開始煎餅了。\n2.湊熱鬧、製造麻煩。[例]這個問題與你無關，請不要在這裡窮攪和！"]],"攪拌":[["ㄐㄧㄠˇ ㄅㄢˋ","攪動、拌合。[例]她用筷子把肉餡攪拌均勻，就開始包餃子了。"]],"支持":[["ㄓ ㄔˊ","1.支撐維持。[例]小妹妹做功課累得支持不住，便趴在桌子上睡著了。\n2.贊助、鼓勵。[例]互相支持、鼎力支持"]],"支撐":[["ㄓ ㄔㄥ","1.頂住，使物體不倒塌。[例]媽媽利用幾根竹竿來支撐給風刮得半倒的絲瓜棚。\n2.支持、維持。[例]這個家全靠他幫傭的薪水在支撐，常常入不敷出。"]],"支柱":[["ㄓ ㄓㄨˋ","1.支撐物體的柱子。[例]這座橋梁的支柱已出現龜裂的現象。\n2.比喻可供依靠之物。[例]精神支柱\n3.比喻組織中的主要人物。[例]他是本會的支柱，許多事情都得靠他才能完成。"]],"收割":[["ㄕㄡ ㄍㄜ","刈取成熟的農作物。[例]農夫們頂著烈日收割稻作。"]],"收成":[["ㄕㄡ ㄔㄥˊ","1.農作物的收穫。[例]強烈颱風登陸將嚴重影響稻穀、蔬果的收成。\n2.泛指各種有形無形的成績或成果。[例]今年資訊界的收成豐碩，業界研發出許多新的軟體。"]],"收拾":[["ㄕㄡ ㄕˊ","1.整理、處理。[例]每個人要負責收拾自己的房間。\n2.折磨、懲處。[例]弟弟你再胡鬧，小心爸爸來收拾你！"]],"收據":[["ㄕㄡ ㄐㄩˋ","收領金錢或物品後所開立的憑證單據。[例]麻煩您開立收據，我好回去報帳。"]],"收穫":[["ㄕㄡ ㄏㄨㄛˋ","1.割取成熟的農作物。[例]農夫在春天播種插秧，到秋天就可以收穫了。\n2.泛指得到成果或利益。[例]參與這場研討會，使我收穫不少。"]],"收編":[["ㄕㄡ ㄅㄧㄢ","接收改編。[例]上級命令我們負責收編敵人投降的部隊。"]],"收藏":[["ㄕㄡ ㄘㄤˊ","1.收集保藏。[例]他熱愛中國文化，平時酷好收藏字畫。\n2.所收集保藏的各項物品。[例]這些都是他平日精心的收藏，絕不輕易示人。"]],"收購":[["ㄕㄡ ㄍㄡˋ","收買購置。[例]他到處收購土地，準備興建住宅，出售圖利。"]],"收集":[["ㄕㄡ ㄐㄧˊ","聚集物品。[例]他收集了許多資料，準備撰寫論文。"]],"改正":[["ㄍㄞˇ ㄓㄥˋ","把錯誤的改成正確的。[例]他將多年的壞習慣改正，脫胎換骨似的成了另外一個人。"]],"改良":[["ㄍㄞˇ ㄌㄧㄤˊ","除去事物的缺點使其更加優良。[例]洋香瓜經過品種改良後，味道更甜美了。"]],"改變":[["ㄍㄞˇ ㄅㄧㄢˋ","更改、變動。[例]無論有多麼困難，都不能改變他出國留學的決心。"]],"改造":[["ㄍㄞˇ ㄗㄠˋ","改革變更，重新建造。[例]改造思想、改造世界"]],"改進":[["ㄍㄞˇ ㄐㄧㄣˋ","改正以求進步。[例]了解自己的缺點後，就必須力求改進，不可一錯再錯。"]],"攻勢":[["ㄍㄨㄥ ㄕˋ","進攻行動的氣勢。[例]甲方的辯論攻勢凌厲，乙方幾已招架不住。"]],"攻占":[["ㄍㄨㄥ ㄓㄢˋ","攻取、占領。[例]當援軍到達時，才發現敵軍已經攻占了這座城池。"]],"攻打":[["ㄍㄨㄥ ㄉㄚˇ","攻擊敵方。[例]為了擴張版圖，那位獨裁者下令攻打鄰國。"]],"攻擊":[["ㄍㄨㄥ ㄐㄧˊ","以武力、語言、文字等各種方式進攻或傷害別人。[例]那架飛機在回程中受到不明物體攻擊，只好緊急降落。"]],"放假":[["ㄈㄤˋ ㄐㄧㄚˋ","假日停止工作。[例]國慶日放假一天。"]],"放大鏡":[["ㄈㄤˋ ㄉㄚˋ ㄐㄧㄥˋ","以凸透鏡裝置而成，可放大物體的單顯微鏡。[例]老年人因視力減退，常常要用放大鏡來看報。"]],"放學":[["ㄈㄤˋ ㄒㄩㄝˊ","學校結束一日課程後，放學生回家。[例]小英放學後會幫媽媽做家事。"]],"放屁":[["ㄈㄤˋ ㄆㄧˋ","1.從肛門洩出體內的廢氣。[例]今天不知吃壞了什麼東西，怎麼老放屁？\n2.罵人家所說的話荒謬無理，不值得重視。[例]他只會放屁，別聽信！"]],"放晴":[["ㄈㄤˋ ㄑㄧㄥˊ","陰雨後日出。[例]下了這麼多天雨，今天總算放晴了。"]],"放棄":[["ㄈㄤˋ ㄑㄧˋ","拋棄。[例]不到最後關頭，絕不輕言放棄。"]],"放縱":[["ㄈㄤˋ ㄗㄨㄥˋ","1.縱容，不加約束。[例]不能太放縱孩子，應該好好管教。\n\t\n2.不循規矩禮節。[例]做學生的言行舉止要得體，不能放縱。"]],"放蕩":[["ㄈㄤˋ ㄉㄤˋ","行為不加約束。[例]放蕩不羈"]],"放鬆":[["ㄈㄤˋ ㄙㄨㄥ","1.從緊束的狀況中放開。[例]放鬆繩子、放鬆腰帶\n2.比喻紓解。[例]考試結束，考生可以放鬆心情，好好玩一下。\n3.放寬、不堅守原則。[例]放鬆標準、放鬆規定"]],"政府":[["ㄓㄥˋ ㄈㄨˇ","唐宋時稱宰相處理政務的地方。現為國家統治機關的總稱，為近代國家構成要素之一。凡具有制定法律及執行法律之權力的政治組織，稱為「政府」。[例]有廉能的政府，才有公平與安定的社會。"]],"故事":[["ㄍㄨˋ ㄕˋ","傳說或杜撰的事物。[例]小朋友團團圍住老師，要求再說一個故事。"]],"故居":[["ㄍㄨˋ ㄐㄩ","原來的住所。[例]人們為了表揚他傑出的藝術成就，於是在他的故居成立紀念館，供人參觀。"]],"故鄉":[["ㄍㄨˋ ㄒㄧㄤ","出生、成長的地方。[例]清新的環境及熱情的親友，促使他退休之後回到故鄉居住。"]],"故障":[["ㄍㄨˋ ㄓㄤˋ","機械無法順利運作。[例]機器突然故障，工廠因而停工了數小時。"]],"效果":[["ㄒㄧㄠˋ ㄍㄨㄛˇ","1.功效、成果。[例]這次展覽會的效果不錯，各廠商均接獲不少訂單。\n2.戲劇演出為配合劇情需要而製造的特殊聲光。[例]這齣戲逼真的效果，使觀眾更能融入劇情中。"]],"效法":[["ㄒㄧㄠˋ ㄈㄚˇ","學習、模仿。[例]他見義勇為的精神，值得大家效法。"]],"效率":[["ㄒㄧㄠˋ ㄌㄩˋ","1.物理上指儀器所輸出的有效能量與輸入儀器的總能量的比值。\n2.泛指所付出的心力與所獲得的成果的比率。[例]他辦事有效率，深得上司讚賞。"]],"效用":[["ㄒㄧㄠˋ ㄩㄥˋ","效果與作用。[例]董事長期望公司各部門放棄成見，通力合作，發揮最大的效用。"]],"效能":[["ㄒㄧㄠˋ ㄋㄥˊ","功能、效果。[例]這種新式的熱水瓶，保溫效能很好。"]],"敏捷":[["ㄇㄧㄣˇ ㄐㄧㄝˊ","迅速快捷。[例]他文思敏捷，出口成章。"]],"敏銳":[["ㄇㄧㄣˇ ㄖㄨㄟˋ","感覺靈敏，見識深刻。[例]他觀察力非常敏銳，對事理看法極為精闢。"]],"救命":[["ㄐㄧㄡˋ ㄇㄧㄥˋ","拯救性命。[例]他及時將溺水的孩童救起，可說是這位小朋友的救命恩人。"]],"救援":[["ㄐㄧㄡˋ ㄩㄢˊ","救助、援助。[例]張氏夫婦日前車禍喪生，家中遺留兩個幼兒，急待各界救援。"]],"救濟":[["ㄐㄧㄡˋ ㄐㄧˋ","用財物幫助貧苦的人。[例]多一點救濟之心，那麼社會亦將多一分祥和之氣。"]],"救護":[["ㄐㄧㄡˋ ㄏㄨˋ","救助保護。[例]這名患者在醫護人員的緊急救護下，終於從昏迷中清醒過來。"]],"救難":[["ㄐㄧㄡˋ ㄋㄢˋ","解救困厄、危難。[例]每逢有山難發生，警方便會派人前往搜尋救難。"]],"敗仗":[["ㄅㄞˋ ㄓㄤˋ","失敗的戰爭或競爭。[例]小陳聰明機伶，怎會在商場上吃了敗仗呢？"]],"教堂":[["ㄐㄧㄠˋ ㄊㄤˊ","基督教教徒集會傳教與舉行儀式的建築物。[例]這一對新人的婚禮是在教堂舉行的。　◎"]],"教室":[["ㄐㄧㄠˋ ㄕˋ","老師傳授知識、技能的場所。[例]經過同學們合力打掃清洗後，整間教室頓時煥然一新。"]],"教書":[["ㄐㄧㄠ ㄕㄨ","教導他人學習書中知識，也泛指從事教育工作。[例]她把教書當做一生的職志。"]],"教會":[["ㄐㄧㄠˋ ㄏㄨㄟˋ","天主教、基督教等教派的信徒所組織的團體。[例]羅馬教會、希臘教會"]],"教練":[["ㄐㄧㄠˋ ㄌㄧㄢˋ","1.教導訓練。[例]他在駕訓班接受三個月的教練之後，順利通過監理所的考驗而取得駕照。\n2.從事訓練別人學習某種技能的人。[例]他是個經驗豐富的籃球教練，曾經多次帶領隊伍出國參加比賽。"]],"教育":[["ㄐㄧㄠˋ ㄩˋ","1.教導培育。[例]父母從小就教育他「一分耕耘，一分收穫」的觀念。\n2.一種有關培植人才，訓練技能，以支應國家建設、社會發展的事業。[例]教育是攸關國家發展的百年大計，絕對不容忽視。"]],"散布":[["ㄙㄢˋ ㄅㄨˋ","1.散播傳布。[例]這個消息經過他散布之後，現在已經是無人不知了。\n2.分散、分布。[例]每年國慶日，散布各地的華僑都會組團回國參加慶典。"]],"散心":[["ㄙㄢˋ ㄒㄧㄣ","排遣煩悶，使心情舒暢。[例]她打算暫時離開這個傷心地，到國外好好散心。"]],"散播":[["ㄙㄢˋ ㄅㄛˋ","傳播、散布。[例]散播謠言"]],"散步":[["ㄙㄢˋ ㄅㄨˋ","隨意走走。[例]飯後散步可以幫助消化。"]],"散沙":[["ㄙㄢˇ ㄕㄚ","比喻分散不團結。[例]他們全班像一盤散沙，難怪各項競賽都殿後。"]],"散發":[["ㄙㄢˋ ㄈㄚ","散布、發出。[例]園子裡的蘭花散發出陣陣清香。"]],"敦厚":[["ㄉㄨㄣ ㄏㄡˋ","寬宏厚道。[例]溫柔敦厚、性情敦厚"]],"敬上":[["ㄐㄧㄥˋ ㄕㄤˋ","1.用於書信的結尾敬辭。_x000D_\n2.尊敬長上。[例]敬上愛下"]],"敬重":[["ㄐㄧㄥˋ ㄓㄨㄥˋ","敬佩尊重。[例]他在政治上的成就與風範，深得國人敬重。"]],"敲門":[["ㄑㄧㄠ ㄇㄣˊ","拍門、扣門。[例]平生不做虧心事，半夜不怕鬼敲門。"]],"整理":[["ㄓㄥˇ ㄌㄧˇ","整頓、收拾。[例]整理家務、整理行囊"]],"整軍經武":[["ㄓㄥˇ ㄐㄩㄣ ㄐㄧㄥ ㄨˇ","修整武備，治理軍事。"]],"整齊":[["ㄓㄥˇ ㄑㄧˊ","有次序、有條理而不紊亂。[例]接受檢閱的隊伍邁開整齊的步伐，精神抖擻的通過司令臺。"]],"敵人":[["ㄉㄧˊ ㄖㄣˊ","仇敵，與己方有仇恨而相對抗的人。[例]他們因為立場不同，竟然由好友變成了敵人。"]],"敵對":[["ㄉㄧˊ ㄉㄨㄟˋ","彼此因利害相衝突，或所處立場不同，而採取的一種對抗、對立，甚至仇視的態度。[例]辯論比賽時，敵對的雙方必須保持良好的風度。"]],"敵方":[["ㄉㄧˊ ㄈㄤ","敵人，敵對的彼方。[例]經過一番纏鬥，敵方終於被我方凌厲的攻勢所擊敗。"]],"敵軍":[["ㄉㄧˊ ㄐㄩㄣ","和我方敵對的軍隊。[例]面對強大的敵軍，我方已經做好萬全的準備。"]],"數學":[["ㄕㄨˋ ㄒㄩㄝˊ","討論數量、形狀及它們之間的關係的科學。包括算術、代數、幾何、三角、解析幾何、微分、積分等。[例]他在語文方面的能力較差，但在數學上表現優異。"]],"數落":[["ㄕㄨˇ ㄌㄨㄛˋ","責備。[例]這次考試他科科不及格，回家後被爸爸好好的數落了一頓。"]],"斂財":[["ㄌㄧㄢˋ ㄘㄞˊ","搜刮、聚斂錢財。[例]他藉職權之便，違法斂財，不久即遭人檢舉而受到法律的制裁。"]],"文具":[["ㄨㄣˊ ㄐㄩˋ","讀書寫字所用的器具。如紙、筆、橡皮擦等。[例]現在的書店通常兼賣文具，方便了不少學生。"]],"文學":[["ㄨㄣˊ ㄒㄩㄝˊ","廣義泛指一切以文字記述傳達思想的著作，狹義則專指以藝術手法，表現思想、情感或想像的作品。[例]自小他即對文學表現出超乎常人的喜愛。"]],"文書":[["ㄨㄣˊ ㄕㄨ","1.統稱公文、契約等文件。[例]到各級行政機構去辦理事務，免不了要填寫申請文書。\n2.從事文書工作的人員。[例]關於上次的會議記錄，文書會提供給大家。"]],"文章":[["ㄨㄣˊ ㄓㄤ","1.由文字連綴而成的篇章。[例]文章要的是內容豐富，而不一定要有很長的敘述。\n2.曲折隱微的含義。[例]這件事看來很不尋常，其中必定大有文章。"]],"文粹":[["ㄨㄣˊ ㄘㄨㄟˋ","選擇精華的文章彙集成冊。[例]這本八十年代的小說文粹，收錄的文章都在水準之上。"]],"文質彬彬":[["ㄨㄣˊ ㄓˊ ㄅㄧㄣ ㄅㄧㄣ","文采和實質均備，配合諧調。後用以形容人舉止文雅有禮。語出《論語．雍也》。[例]不論是就談吐或舉止，他都算得上是一位文質彬彬之士。"]],"文采":[["ㄨㄣˊ ㄘㄞˇ","文辭、文才。[例]他的文采一向過人，是以在各種文藝競賽裡，屢次拔得頭籌。"]],"斑白":[["ㄅㄢ ㄅㄞˊ","花白的髮色，常指年老。[例]鬢髮斑白"]],"斑馬":[["ㄅㄢ ㄇㄚˇ","動物名。哺乳綱奇蹄目。身有黑白二色相間的斑紋。好群棲，產於美、非二洲。[例]身上帶條紋的斑馬，一直是動物園相當受歡迎的明星。　◎"]],"斑點":[["ㄅㄢ ㄉㄧㄢˇ","散布在物體上的雜色小點。[例]這麼好看的緞子上，竟然有油汙斑點！"]],"斗篷":[["ㄉㄡˇ ㄆㄥˊ","一種寬大無袖，披在肩上用來擋風禦寒的外衣。[例]外頭天寒地凍，又刮著大風，出門時別忘了披件斗篷。　△披風、一口中、一口鐘"]],"料理":[["ㄌㄧㄠˋ ㄌㄧˇ","1.處理。[例]家裡大小事務，都是媽媽一手料理的。\n2.照顧。[例]離家多年，我已習慣自己料理自己。\n3.菜餚。[例]日本料理以精緻聞名。"]],"斜坡":[["ㄒㄧㄝˊ ㄆㄛ","傾斜的坡地。[例]這片斜坡，是他們一家賴以維生的茶園。"]],"斜角":[["ㄒㄧㄝˊ ㄐㄧㄠˇ","數學上對鈍角與銳角的總稱。"]],"斥責":[["ㄔˋ ㄗㄜˊ","大聲責罵。[例]為了這次的業務疏失，他被上司斥責了一頓。"]],"斧頭":[["ㄈㄨˇ ˙ㄊㄡ","砍伐樹木、劈削木材的用具。[例]伐木工人拿著斧頭到樹林裡砍樹。　△斧子"]],"新人":[["ㄒㄧㄣ ㄖㄣˊ","1.稱新婚的男女。[例]喜宴上，大家舉杯祝賀這對新人永浴愛河，白頭偕老。\n2.新手、新進人員。[例]這批新人全是公司對外招考錄取的，個個都很優秀。"]],"新奇":[["ㄒㄧㄣ ㄑㄧˊ","新鮮奇特。[例]初次出國，他對國外的一切事物都感到新奇。"]],"新娘":[["ㄒㄧㄣ ㄋㄧㄤˊ","稱剛結婚或正要舉行結婚典禮的女子。[例]那披上白紗的新娘，臉上泛著喜悅的光彩。_x000D_"]],"新家":[["ㄒㄧㄣ ㄐㄧㄚ","新近遷入的住所。[例]我們最近剛搬入新家，有空來坐坐。"]],"新年":[["ㄒㄧㄣ ㄋㄧㄢˊ","一年的開始。[例]家家戶戶都忙著除舊布新以迎接新年。"]],"新聞":[["ㄒㄧㄣ ㄨㄣˊ","1.報社、廣播電臺、電視臺等，對國內外所發生重要的事件而做的最新報導。[例]新聞記者、新聞採訪、新聞廣播\n2.從沒聽過的新鮮事。[例]他們兩個人結婚了？這可真是件天大的新聞吶！"]],"新芽":[["ㄒㄧㄣ ㄧㄚˊ","新長出的嫩芽。亦比喻新出現的人才。[例]春天來臨，許多植物開始抽新芽了。"]],"新鮮":[["ㄒㄧㄣ ㄒㄧㄢ","1.形容食物清潔鮮美而沒有變質。[例]這條魚是剛從湖裡撈上來的，趁新鮮清蒸了吃。\n2.新奇的、沒發生過的。[例]瞧他興奮的樣子，不知又有什麼新鮮事兒發生。"]],"斷崖":[["ㄉㄨㄢˋ ㄧㄞˊ","絕壁，陡峭的崖壁。[例]這條路的一旁就是斷崖，非常危險。"]],"斷然":[["ㄉㄨㄢˋ ㄖㄢˊ","1.絕對、無論如何。[例]這種違法亂紀的事，斷然不可做！\n2.決斷之詞。[例]由於前線告急，指揮官斷然下令全軍撤退，固守基地。"]],"斷絕":[["ㄉㄨㄢˋ ㄐㄩㄝˊ","中斷隔絕。[例]斷絕來往"]],"斷裂":[["ㄉㄨㄢˋ ㄌㄧㄝˋ","分解裂開。[例]這座橋因地震而斷裂，造成往來交通的不便。"]],"方便":[["ㄈㄤ ㄅㄧㄢˋ","1.便利。[例]自從這裡開了一家超級市場以後，買東西就方便多了。\n2.便利於人的事。[例]請您行個方便，幫個忙吧！\n3.上廁所。[例]在這種荒郊野外，哪裡能找得到地方方便呢？"]],"方向":[["ㄈㄤ ㄒㄧㄤˋ","1.東南西北、前後、上下等的區別。[例]順著這個方向走，就可以到郵局了。\n\t\n2.目標。[例]我們要把握人生的方向。\n\t\n3.情勢。[例]先看事情發展的方向再做決定吧！"]],"方式":[["ㄈㄤ ㄕˋ","做事情所採取的順序、形式。[例]表演方式、工作方式"]],"方案":[["ㄈㄤ ㄢˋ","1.計畫。[例]對於這突發的狀況，我還沒有任何方案可因應。\n2.公文格式之一。依據階段性施政方針所擬定的工作計畫。往往涉及跨都會的業務。[例]建築業管理輔導方案"]],"方正":[["ㄈㄤ ㄓㄥˋ","1.端正不歪斜，成正方形。[例]字體方正、格局方正\n2.正直。[例]方正不阿、品行方正"]],"方法":[["ㄈㄤ ㄈㄚˇ","為達到某種目的所用的方式和步驟。[例]早睡早起是保持身體健康的好方法。"]],"方興未艾":[["ㄈㄤ ㄒㄧㄥ ㄨㄟˋ ㄞˋ","正在蓬勃發展中，一時不會停止。[例]這股風潮方興未艾，很值得我們注意。"]],"於是":[["ㄩˊ ㄕˋ","因此，因而。表承上啟下的連詞。[例]因為晚上停電，家裡於是點起蠟燭照明。"]],"施展":[["ㄕ ㄓㄢˇ","發揮、展露。[例]他甫自學校畢業，滿懷熱忱的希望在工作崗位上施展抱負與才能。"]],"施工":[["ㄕ ㄍㄨㄥ","進行工程。[例]這棟大樓的施工情形良好，應該可以如期完成。"]],"施惠":[["ㄕ ㄏㄨㄟˋ","給予恩惠、德澤。[例]他施惠於人，從不求回報，在鄉里中贏得美名。"]],"旁人":[["ㄆㄤˊ ㄖㄣˊ","局外人，與事件沒有關係的人。[例]家務事應由自己家人解決，旁人通常只會愈幫愈忙。"]],"旁觀":[["ㄆㄤˊ ㄍㄨㄢ","在一旁觀看，不涉入事件本身。[例]當局者迷，旁觀者清。"]],"旁邊":[["ㄆㄤˊ ㄅㄧㄢ","近側，靠近的地方。[例]我家住在學校旁邊。"]],"旅客":[["ㄌㄩˇ ㄎㄜˋ","旅行的人。[例]歐洲風景綺麗，總是吸引大批旅客前往觀光。"]],"旅程":[["ㄌㄩˇ ㄔㄥˊ","旅遊的行程。[例]他喜歡單獨出遊，自行規劃出國旅程，既輕鬆又自在。"]],"旅行":[["ㄌㄩˇ ㄒㄧㄥˊ","出外旅遊。[例]旅行不但可以調劑身心，還能增廣見聞。"]],"旅費":[["ㄌㄩˇ ㄈㄟˋ","旅行時所需支出的費用。主要有交通、住宿、飲食等數項。[例]她計劃旅遊歐洲已經多年，但因旅費不足，一直未能成行。"]],"旅遊":[["ㄌㄩˇ ㄧㄡˊ","旅行遊覽。[例]這趟環島深度旅遊，不但參訪了各地頗富盛名的名勝古蹟，對臺灣歷史及風土民情有更深的了解。"]],"旅館":[["ㄌㄩˇ ㄍㄨㄢˇ","提供旅客休息、住宿的營業場所。[例]每到旅遊旺季，這一處觀光遊樂區裡的旅館總是供不應求。"]],"旋即":[["ㄒㄩㄢˊ ㄐㄧˊ","馬上、立刻。[例]一聽到妻子已入院待產，他旋即趕往醫院去。"]],"旋律":[["ㄒㄩㄢˊ ㄌㄩˋ","若干高低、長短、強弱不同的樂音，依節奏上的一定組織關係連續奏出，稱為「旋律」。是構成音樂的基本要素，可以表現出音樂的內容、風格及體裁。[例]這首老歌旋律優美，令人百聽不厭。"]],"旋轉":[["ㄒㄩㄢˊ ㄓㄨㄢˇ","迴旋轉動。[例]旋轉木馬、旋轉餐廳　◎"]],"旋風":[["ㄒㄩㄢˋ ㄈㄥ","1.氣流一面繞圓心旋轉，一面前進移動所形成的螺旋狀的風。多因某處氣壓驟低，四面空氣向該處急速湧入而形成。[例]沙漠中突然吹起一陣旋風，揚起滾滾的沙塵。\n2.來勢凶猛或引起震撼的事件。[例]服裝界最近颳起一陣復古的旋風，街頭上處處可見穿著喇叭褲的人。"]],"旗幟":[["ㄑㄧˊ ㄓˋ","1.旗有標幟的功用，所以泛稱旌旗為「旗幟」。[例]園遊會場上飄著許多畫有動物圖案的旗幟。\n2.比喻名義、藉口。[例]那批反抗軍打著維護和平的旗幟在境內從事恐怖活動。"]],"既有":[["ㄐㄧˋ ㄧㄡˇ","固有，本來已有。[例]對於既有的文化，應當善加保存，並且進一步發揚光大。"]],"既然":[["ㄐㄧˋ ㄖㄢˊ","連詞。多用在上半句的句首，表示前提，而後再加以推論。[例]你既然不想參加這次聚會，那就別去了。"]],"日光":[["ㄖˋ ㄍㄨㄤ","太陽的光。[例]這植物由於日光照射不足，生長情況並不理想。"]],"日子":[["ㄖˋ ˙ㄗ","1.時間、光陰。[例]我們倆認識的日子不算長，但彼此都很了解。\n2.時候、期間。[例]前些日子借的書可以還了嗎？\n3.日期。指特定的某日。[例]他們倆結婚的事就等挑個日子確定了。\n4.生活。[例]臺灣剛光復時，整個社會亟待重整，日子很不好過。"]],"日晒雨淋":[["ㄖˋ ㄕㄞˋ ㄩˇ ㄌㄧㄣˊ","1.暴露在外，沒有任何東西遮蔽。[例]車子停在外面，天天日晒雨淋，車身的烤漆已有點腐蝕了。\n2.形容在外奔波，非常辛勞。[例]為了給家人一個安定的生活，他每天日晒雨淋的，也毫無怨言。"]],"日暈":[["ㄖˋ ㄩㄣˋ","太陽光透過雲層中的冰晶，折射而產生在太陽周圍的光環。有時為彩色，有時為白色。通常被當作天氣變化的預兆。"]],"日曆":[["ㄖˋ ㄌㄧˋ","記載年、月、日、星期和節氣、紀念日等的印刷品。一年一本，一日一頁。[例]年關將近，市面上有許多設計精美的日曆供人選購。"]],"日期":[["ㄖˋ ㄑㄧˊ","發生某事的確定日子或時期。[例]截止日期、考試日期、開會日期"]],"日積月累":[["ㄖˋ ㄐㄧ ㄩㄝˋ ㄌㄟˇ","逐日、逐月的長時間不斷的累積。比喻歷時久遠。語本漢．董仲舒〈元光元年舉賢良對策〉。[例]學問需要日積月累的努力學習，而非一下子就能成功。"]],"日記":[["ㄖˋ ㄐㄧˋ","每日的生活紀錄。[例]偷看別人的日記是不道德的行為。"]],"旨意":[["ㄓˇ ㄧˋ","1.主旨目的。[例]由於未曾參與上次的御前會議，所以不了解聖上寫出來的文章旨意。\n2.帝王的命令。[例]古時對於皇上所頒布的旨意，臣民都必須遵從。"]],"早上":[["ㄗㄠˇ ㄕㄤˋ","早晨。[例]他每天早上天還沒亮就起床工作了。"]],"早安":[["ㄗㄠˇ ㄢ","早晨見面時的問候語。[例]他早上在上學的途中遇到老師，兩人互道早安。"]],"早晚":[["ㄗㄠˇ ㄨㄢˇ","1.早晨與晚間。[例]最近早晚溫差很大，出門時要多帶件衣服。\n2.遲早。[例]他如此勤奮好學，早晚必成大器。"]],"早晨":[["ㄗㄠˇ ㄔㄣˊ","早上，黎明。[例]春天的早晨，我常被鳥鳴聲喚醒。"]],"早餐":[["ㄗㄠˇ ㄘㄢ","早晨的餐點。[例]父母親每天很早就起床為全家人準備早餐。"]],"旱災":[["ㄏㄢˋ ㄗㄞ","因長期雨水不足而造成的災害。[例]因為缺水而造成的旱災，可望由連日的豪雨而解除。"]],"旱田":[["ㄏㄢˋ ㄊㄧㄢˊ","土地表面不蓄水或缺乏灌溉設施的田地。多種植不需要大量水分的作物，如花生、棉花、小麥等。[例]這一帶的旱田都是種植小麥。"]],"旺季":[["ㄨㄤˋ ㄐㄧˋ","在一年內營業最旺盛或商品銷售最旺盛的季節。[例]在旅遊旺季，機位一票難求。"]],"旺盛":[["ㄨㄤˋ ㄕㄥˋ","興旺繁盛。[例]雖然屢遭挫折，他仍然鬥志旺盛，毫不氣餒。"]],"昂貴":[["ㄤˊ ㄍㄨㄟˋ","價格很高。[例]進口的名牌貨品價格都比較昂貴。"]],"昆蟲":[["ㄎㄨㄣ ㄔㄨㄥˊ","蟲類的總稱。多指身體由頭、胸、腹三部分組成，以氣管呼吸的節足動物。如螞蟻、蜻蜓等。[例]昆蟲是世界上種類最多的動物。"]],"明亮":[["ㄇㄧㄥˊ ㄌㄧㄤˋ","1.光線充足。[例]屋裡的燈火全打開了，十分明亮。\n2.發亮的。[例]她的眼睛像夜空的星星般明亮。"]],"明天":[["ㄇㄧㄥˊ ㄊㄧㄢ","1.今天的下一天。[例]今夜颱風來襲，不知明天要不要上班？\n2.不遠的未來。[例]展望美好的明天。"]],"明察秋毫":[["ㄇㄧㄥˊ ㄔㄚˊ ㄑㄧㄡ ㄏㄠˊ","目光敏銳，可看見秋天鳥獸新長的細毛。比喻能洞察一切，看出極細微的地方。[例]最優秀的偵探在於能明察秋毫，從最細微處找出破綻。"]],"明查暗訪":[["ㄇㄧㄥˊ ㄔㄚˊ ㄢˋ ㄈㄤˇ","公開調查，暗中尋訪。[例]經過月餘的明查暗訪，整個事件終於真相大白。"]],"明白":[["ㄇㄧㄥˊ ㄅㄞˊ","1.了解、知道。[例]你們如果明白為什麼會這樣，我就不再多作解釋了。_x000D_\n2.清楚、明確。[例]把話說明白，別支支吾吾的。_x000D_\n3.聰明、不糊塗。[例]你是個明白人，該怎麼做，自然是曉得的！"]],"明瞭":[["ㄇㄧㄥˊ ㄌㄧㄠˇ","明白了解。[例]教育的目的在使學生明瞭做人處事的道理。"]],"明豔":[["ㄇㄧㄥˊ ㄧㄢˋ","明亮豔麗。[例]明豔動人"]],"明辨":[["ㄇㄧㄥˊ ㄅㄧㄢˋ","清楚的分辨。[例]做人要明辨是非，不可昧著良心做事。"]],"昏頭轉向":[["ㄏㄨㄣ ㄊㄡˊ ㄓㄨㄢˋ ㄒㄧㄤˋ","1.形容頭腦暈眩，不辨方向。[例]他在地上連續轉了幾圈，把自己搞得昏頭轉向，差點跌倒。\n2.形容頭腦不清，無法冷靜思考。[例]他這一陣子大小活動不斷，忙得昏頭轉向。"]],"星光":[["ㄒㄧㄥ ㄍㄨㄤ","星的光芒。[例]秋天的夜空，星光閃閃，透顯著宇宙的奧祕。"]],"星團":[["ㄒㄧㄥ ㄊㄨㄢˊ","銀河系內的星球整群圍繞著共同的質量中心公轉，稱為「星團」。分為球狀星團和疏散星團兩種，前者約有十萬顆星，後者則只有數十到數百顆星。"]],"星星":[["ㄒㄧㄥ ㄒㄧㄥ","1.頭髮花白的樣子。[例]經過歲月的洗禮，昔日英姿煥發的年輕人，如今已是兩鬢星星，滿頭華髮了。\n2.形容零星細小。[例]小弟不慎打破茶杯，頓時滿地都是星星點點的玻璃碎片。"],["ㄒㄧㄥ ˙ㄒㄧㄥ","泛稱夜空中發光的星體。[例]長煙一空，萬里無雲，滿天的星星閃耀著清輝。"]],"星期":[["ㄒㄧㄥ ㄑㄧˊ","1.我國古代曆法與西洋曆法，皆以七天為一週，故以連續的七天做為計日名稱，稱為「星期」。[例]星期六、星期天_x000D_\n2.量詞。計算時間的單位。七天為一星期。 [例]他花了好幾星期時間才完成這份讀書報告。"]],"星空":[["ㄒㄧㄥ ㄎㄨㄥ","繁星閃耀的夜空。[例]我們以天文望遠鏡觀賞閃亮的夏夜星空。"]],"星羅棋布":[["ㄒㄧㄥ ㄌㄨㄛˊ ㄑㄧˊ ㄅㄨˋ","形容布列繁密，如星星、棋子般的廣泛分布。[例]來到野柳，最迷人處正是那星羅棋布的怪石奇岩。"]],"星辰":[["ㄒㄧㄥ ㄔㄣˊ","星的通稱。[例]日月星辰永無止息的運行著。"]],"映射":[["ㄧㄥˋ ㄕㄜˋ","投映照射。[例]月光映射湖面上，閃耀著粼粼波光。"]],"映照":[["ㄧㄥˋ ㄓㄠˋ","映射、照射。[例]湖面在夕陽映照下，水光粼粼，煞是美麗。"]],"映襯":[["ㄧㄥˋ ㄔㄣˋ","1.映照烘托。[例]這棟建築紅牆碧瓦，互相映襯，煞是好看。\n2.將兩種不同的，特別是相反的觀念或事實，對列比較，從而使語氣增強、意義更為明顯的修辭法。如吳勝雄〈負荷〉一文中「只因為這是生命中最沉重也是最甜蜜的負荷」，用「沉重」和「甜蜜」兩個相反的觀念，突顯出對家庭的熱愛與強烈的責任感。"]],"春天":[["ㄔㄨㄣ ㄊㄧㄢ","1.春季，為四季之首。[例]春天是萬物甦醒的季節。\n2.比喻最美好、光明、燦爛的日子。[例]雖然我們相處只有短短數日，卻是我生命中最美好的春天。"]],"春節":[["ㄔㄨㄣ ㄐㄧㄝˊ","我國傳統節日之一。指農曆正月初一。[例]春節是遊子返鄉與家人團聚的時刻。"]],"昨天":[["ㄗㄨㄛˊ ㄊㄧㄢ","前一日。[例]他昨天淋雨回來，今天就覺得身體不太舒服了。"]],"昨晚":[["ㄗㄨㄛˊ ㄨㄢˇ","昨夜。[例]他昨晚作了一個惡夢，一直到今天早上都還心有餘悸。"]],"昭告":[["ㄓㄠ ㄍㄠˋ","明白的告知。[例]昭告世人、昭告天下"]],"是否":[["ㄕˋ ㄈㄡˇ","疑問副詞。指對不對，是不是。[例]老師問我們是否讀過一些偉人傳記？"]],"時代":[["ㄕˊ ㄉㄞˋ","1.現代。[例]他的思想早已跟不上時代了。\n2.某一階段、時期。[例]幼年時代、冰河時代、銅器時代"]],"時候":[["ㄕˊ ㄏㄡˋ","1.時刻。[例]遭遇緊急危難的時候，唯有處變不驚才能化險為夷。\n2.某一段時間。[例]小時候、古時候"]],"時常":[["ㄕˊ ㄔㄤˊ","指事情發生的頻率很高。[例]我倆雖分隔兩地，卻時常保持聯繫。 △常常、經常"]],"時鐘":[["ㄕˊ ㄓㄨㄥ","一種可以顯示時間的計時器。[例]牆上那座時鐘雖然古老，但仍相當準確。"]],"時間":[["ㄕˊ ㄐㄧㄢ","1.有起點和終點的一段時刻。如年、月、日、時、分、秒等，都是時間的單位。[例]《資治通鑑》是司馬光花了十九年的時間才完成的鉅著。_x000D_\n2.凡過去、現在、未來之無限流轉者，稱為「時間」。相對於空間而言。[例]時間就是金錢。"]],"晉見":[["ㄐㄧㄣˋ ㄐㄧㄢˋ","進見、拜見。[例]當選年度創業楷模的青年企業家，最近將晉見總統。"]],"晒黑":[["ㄕㄞˋ ㄏㄟ","經太陽曝晒後，使膚色變得較深。[例]他晒黑了，我差點認不出來。"]],"晚上":[["ㄨㄢˇ ㄕㄤˋ","日落以後。[例]國慶日晚上滿天的煙火，將整個夜空變成一幅幅動人的圖畫。"]],"晚安":[["ㄨㄢˇ ㄢ","晚上向人問好的用語，多用於道別時。[例]弟弟向爸媽道晚安後，才上床睡覺。"]],"晚會":[["ㄨㄢˇ ㄏㄨㄟˋ","傍晚或夜間舉行的歡樂集會。[例]去年的營火晚會是在濛濛細雨裡舉行的，至今令人懷念不已。"]],"晚間":[["ㄨㄢˇ ㄐㄧㄢ","日暮以後。[例]晚間通常是一家人團聚的溫馨時刻。"]],"晚飯":[["ㄨㄢˇ ㄈㄢˋ","晚上吃的正餐。[例]邊吃晚飯邊看電視，對胃腸消化有礙，宜盡量避免。"]],"普遍":[["ㄆㄨˇ ㄅㄧㄢˋ","廣泛存在的、具共同性質的。[例]我國國民的生活水準已普遍提高。"]],"景色":[["ㄐㄧㄥˇ ㄙㄜˋ","風光、景物。[例]這條小溪畔風光明媚，景色優美，常令人流連忘返。"]],"景象":[["ㄐㄧㄥˇ ㄒㄧㄤˋ","1.情形、現象。[例]由於景氣旺盛，工商發達，社會上呈現出繁榮的景象。\n2.景色。[例]阿里山的日出景象壯觀，讓遊客們嘆為觀止。"]],"晴天":[["ㄑㄧㄥˊ ㄊㄧㄢ","不雨無雲而有陽光的天氣。[例]氣象報告說明天將是個晴天。"]],"晴朗":[["ㄑㄧㄥˊ ㄌㄤˇ","陽光普照，沒有雲霧。[例]近來天氣晴朗，各風景區都擠滿了人潮。"]],"晴空":[["ㄑㄧㄥˊ ㄎㄨㄥ","晴朗的天空。[例]成群飛鳥劃過晴空，自由翱翔的景象，洋溢著無限生機。"]],"晶亮":[["ㄐㄧㄥ ㄌㄧㄤˋ","明亮光潔的樣子。[例]爸爸把商店的櫥窗擦得晶亮，好迎接客人上門。"]],"晶瑩":[["ㄐㄧㄥ ㄧㄥˊ","明亮透澈。[例]他從母親晶瑩的淚光中感受到母愛的溫暖。"]],"晶瑩剔透":[["ㄐㄧㄥ ㄧㄥˊ ㄊㄧ ㄊㄡˋ","光亮透明。[例]荷葉上的露珠在朝陽的映照之下，顯得格外晶瑩剔透。"]],"智慧":[["ㄓˋ ㄏㄨㄟˋ","1.聰明才智。[例]人類運用智慧創造了文明，提升了生活品質。\n2.佛家指證悟一切現象之真實性的智力。　△般若"]],"晾乾":[["ㄌㄧㄤˋ ㄍㄢ","把溼的衣物等置於有陽光或陰涼處使其水分蒸發而變乾。[例]今天突然放晴，大家紛紛拿出衣服掛在陽臺上晾乾。"]],"暈倒":[["ㄩㄣ ㄉㄠˇ","昏倒。[例]小英因體力不支而在運動場上暈倒了。"]],"暈眩":[["ㄩㄣ ㄒㄩㄢˋ","頭昏眼花。[例]他被撞倒的時候只感到一陣震盪與暈眩，隨即失去了知覺。"]],"暈船":[["ㄩㄣ ㄔㄨㄢˊ","乘船時因過度搖晃而產生頭暈，甚至嘔吐的現象。[例]海面風浪太大，所有的乘客都暈船了。"]],"暑假":[["ㄕㄨˇ ㄐㄧㄚˋ","學校的常態期末假期，通常夏天在七、八兩月間實施。[例]今年暑假，他報名參加許多夏令營活動。"]],"暑氣":[["ㄕㄨˇ ㄑㄧˋ","夏天的熱氣。[例]炎熱的夏季裡，泡在游泳池中令人感到暑氣全消。"]],"暖和":[["ㄋㄨㄢˇ ˙ㄏㄨㄛ","溫暖。[例]每年秋天，伯勞鳥就往南飛到暖和的地方過冬。"]],"暖身":[["ㄋㄨㄢˇ ㄕㄣ","1.運動前，做些緩和動作以舒展筋骨。[例]比賽開始前，他先做些體操暖身。\n2.比喻為事情或活動的開始作準備。[例]年底選戰將至，候選人紛紛為選舉暖身造勢。"]],"暗礁":[["ㄢˋ ㄐㄧㄠ","未露出於海面的礁石。[例]那艘船不幸觸到暗礁而逐漸沉沒，船長立刻命令船員放下救生艇逃生。"]],"暗示":[["ㄢˋ ㄕˋ","用間接、含蓄的方法來表達意思。[例]如果主人頻看手表，也許是暗示客人應該告辭了。"]],"暗自竊喜":[["ㄢˋ ㄗˋ ㄑㄧㄝˋ ㄒㄧˇ","私下裡高興。[例]他為了自己的計謀得逞而暗自竊喜。"]],"暗號":[["ㄢˋ ㄏㄠˋ","祕密的口令或記號。[例]初次見面，他們約定暗號，以便能認出對方。"]],"暢快":[["ㄔㄤˋ ㄎㄨㄞˋ","1.舒暢快樂，稱心如意。[例]每當我心情不好時，跟好友聊一聊天，就覺得暢快多了。\n2.性情直爽。[例]他為人暢快，很好相處。"]],"暢談":[["ㄔㄤˋ ㄊㄢˊ","盡情的談話。[例]多年不見，我與他徹夜不眠，暢談近況。"]],"暫停":[["ㄓㄢˋ ㄊㄧㄥˊ","進行中作短時間的中止。[例]比賽中藍隊的教練要求更換球員而使比賽暫停。"]],"暫時":[["ㄓㄢˋ ㄕˊ","短時間。[例]陳小姐暫時照顧受傷的小鳥，等牠復原後再放回大自然。"]],"暫緩":[["ㄓㄢˋ ㄏㄨㄢˇ","暫且延遲。[例]因為發現多處錯誤，這本書暫緩出版。"]],"暮色":[["ㄇㄨˋ ㄙㄜˋ","傍晚昏暗的天色。[例]暮色四合，遠處的燈火漸漸亮了起來。"]],"暱稱":[["ㄋㄧˋ ㄔㄥ","親暱的稱呼。[例]情侶之間往往有各式各樣的暱稱。"]],"暴漲":[["ㄅㄠˋ ㄓㄤˇ","1.水位突然升高。[例]一場滂沱大雨使得河水暴漲。\n2.貨物價格突然上揚。[例]颱風過後，蔬果價格往往一夕之間暴漲數倍。"]],"暴躁":[["ㄅㄠˋ ㄗㄠˋ","粗暴而急躁，不能控制情緒。[例]他的性情暴躁，容易得罪人。"]],"暴露":[["ㄆㄨˋ ㄌㄨˋ","1.缺乏遮蔽，沒有阻擋的。[例]長時間暴露在烈日下，很容易中暑。_x000D_\n2.揭發、揭露。[例]他無意間暴露了自己的身分。"]],"暴風":[["ㄅㄠˋ ㄈㄥ","1.急驟強勁的風。[例]暴風驟雨_x000D_\n2.氣象學上指風力十一級的風。_x000D_"]],"曉得":[["ㄒㄧㄠˇ ˙ㄉㄜ","知道、明白。[例]妹妹小小年紀就曉得如何利用時間，真是難得。"]],"曙光":[["ㄕㄨˋ ㄍㄨㄤ","1.清晨大地初現的亮光。[例]清晨第一道曙光出現前，許多人就已經展開一天的工作了。\n2.比喻轉機的希望。[例]在他的積極奔走下，成立讀書會的事終於露出一線曙光。"]],"曝晒":[["ㄆㄨˋ ㄕㄞˋ","在陽光底下直晒。[例]經過一整天的曝晒，弄溼的毯子已全乾了。"]],"曠世":[["ㄎㄨㄤˋ ㄕˋ","當代無可比擬。[例]曠世巨作、曠世奇才"]],"曠職":[["ㄎㄨㄤˋ ㄓˊ","未請假而缺勤。[例]他因經常曠職而被老闆解僱了！"]],"曠課":[["ㄎㄨㄤˋ ㄎㄜˋ","學生沒有請假而缺課。[例]他因經常曠課逃學，已遭學校記過處分。"]],"曲折":[["ㄑㄩ ㄓㄜˊ","1.彎曲拗折。[例]這條山路非常蜿蜒曲折，開車經過時要特別小心。\n2.形容事情複雜。[例]這件案子如此曲折，一時之間恐怕無法釐清頭緒。\n3.挫折、波折。[例]他的一生遭遇不少曲折，旁人聽來頗覺離奇。"]],"曲線":[["ㄑㄩ ㄒㄧㄢˋ","1.彎曲的線條。[例]這幅畫主要是由許多曲線交錯層疊而成，饒富趣味。　◎\n2.外圍的輪廓、線條。多用以形容人體的身材體態。[例]這件衣服剪裁合宜，完全貼合她的曲線。"]],"曲解":[["ㄑㄩ ㄐㄧㄝˇ","歪曲原意，或故意做不正確的解釋。[例]他專心聆聽別人說話，以避免曲解善意而產生誤會。"]],"曲調":[["ㄑㄩˇ ㄉㄧㄠˋ","樂曲的調子。[例]這首歌的曲調婉轉，演奏起來一定動聽。"]],"更上層樓":[["ㄍㄥˋ ㄕㄤˋ ㄘㄥˊ ㄌㄡˊ","達到更高的境界。[例]只有不斷奮進，才能在事業上更上層樓。"]],"更換":[["ㄍㄥ ㄏㄨㄢˋ","更改替換。[例]這窗帘使用多年，早已陳舊汙損，該是更換的時候了。"]],"更改":[["ㄍㄥ ㄍㄞˇ","更動、改變。[例]由於天候不佳，只好臨時更改旅遊路線。"]],"更替":[["ㄍㄥ ㄊㄧˋ","更換替代。[例]營區大門的衛兵每二小時更替一次。"]],"更甚":[["ㄍㄥˋ ㄕㄣˋ","更加嚴重。[例]一入嚴冬，風雪更甚，行人幾乎是寸步難行。"]],"更迭":[["ㄍㄥ ㄉㄧㄝˊ","接連不斷的交替、更換。[例]世代更迭，人事遞嬗，往昔叱吒一時的風雲人物，又在那裡呢？"]],"書信":[["ㄕㄨ ㄒㄧㄣˋ","信件。[例]書信的內容要詞義清楚，條理明白，使收信人看了容易瞭解。"]],"書僮":[["ㄕㄨ ㄊㄨㄥˊ","舊時在富人家中侍候主人或其弟子讀書，兼做雜役的未成年僮僕。"]],"書包":[["ㄕㄨ ㄅㄠ","學生裝書用的背包。[例]開學了，妹妹背著書包上學去。"]],"書房":[["ㄕㄨ ㄈㄤˊ","家中讀書寫字的房間。[例]爸爸正在書房寫作，不許任何人干擾。　△書齋、芸窗"]],"書本":[["ㄕㄨ ㄅㄣˇ","書冊。[例]優良的書本可以發揮淨化心靈的功用。"]],"書籍":[["ㄕㄨ ㄐㄧˊ","書本冊籍的總稱。[例]王教授將他生平珍愛的一些書籍捐贈給圖書館。"]],"書籤":[["ㄕㄨ ㄑㄧㄢ","夾在書裡，作為閱讀進度標識的卡片。[例]姊姊送了一套書籤給我當生日禮物。"]],"書香":[["ㄕㄨ ㄒㄧㄤ","讀書的風氣與傳統。多指家世、門風而言。[例]書香世家"]],"曼妙":[["ㄇㄢˋ ㄇㄧㄠˋ","形容姿態輕靈柔美。[例]臺上舞者曼妙的舞姿，使臺下的觀眾如痴如醉。"]],"曾孫":[["ㄗㄥ ㄙㄨㄣ","稱謂。稱孫子的兒子。[例]林老先生的曾孫才剛滿月，長得白胖可愛。"]],"曾祖母":[["ㄗㄥ ㄗㄨˇ ㄇㄨˇ","稱謂。稱祖父的母親。[例]鄉下那張大床，是曾祖母的嫁妝。"]],"曾祖父":[["ㄗㄥ ㄗㄨˇ ㄈㄨˋ","稱謂。稱祖父的父親。[例]我們家從曾祖父起便遷居於此，務農為生。"]],"曾經":[["ㄘㄥˊ ㄐㄧㄥ","表示以前有過的行為或情況的副詞。[例]他曾經寫過一篇文章，歌詠大自然的美景。"]],"最初":[["ㄗㄨㄟˋ ㄔㄨ","最早的時期、開始的時候。[例]他們兩人最初是相識在朋友的生日派對上。"]],"最好":[["ㄗㄨㄟˋ ㄏㄠˇ","1.極好。[例]她沏了一壺最好的茶，請好友品嚐。\n2.表示非常希望。[例]宴會最好親自參加，以表示對主人的尊重。"]],"最後":[["ㄗㄨㄟˋ ㄏㄡˋ","時間或次序上居於末了的位置。[例]他由於工作忙碌，常常搭當天最後一班公車回家。"]],"會合":[["ㄏㄨㄟˋ ㄏㄜˊ","聚集、相逢。[例]登山隊將分兩路上山，預定三天後在山頂會合。"]],"會場":[["ㄏㄨㄟˋ ㄔㄤˇ","集會的場所。[例]他面帶笑容走進會場，揮手向大家打招呼。"]],"會計":[["ㄎㄨㄞˋ ㄐㄧˋ","1.管理財務帳目和出納的事宜。[例]她上大學之前曾學過三年的會計。_x000D_\n2.擔任管理財務帳目和出納職務的人。[例]總公司目前請了三位會計，負責所有關係企業的帳目。"]],"會面":[["ㄏㄨㄟˋ ㄇㄧㄢˋ","見面。[例]他們倆雖長期通信，但是卻不曾會面。"]],"月初":[["ㄩㄝˋ ㄔㄨ","每個月開始的幾天。[例]各公司行號大多在月初發薪。"]],"月暈":[["ㄩㄝˋ ㄩㄣˋ","月光受到稀薄而高的冰雲折射所形成的光環。"]],"月氏":[["ㄩㄝˋ ㄓ","西域古國之一。位於今甘肅省中部及青海省東境。漢時被匈奴所破而西走伊犁河一帶的稱為「大月氏」，留居原地而歸屬匈奴的則稱為「小月氏」。此義或讀為ㄖㄡˋㄓ。"]],"月餅":[["ㄩㄝˋ ㄅㄧㄥˇ","一種包餡的糕餅點心，為中秋節應節食品。[例]中秋節是家人團聚吃月餅的節日。"]],"有勁":[["ㄧㄡˇ ㄐㄧㄥˋ","1.有力氣、力量。[例]他的兩手很有勁，能輕鬆自如地抬起二十公斤的貨物。_x000D_\n2.認真。[例]老董在各桌招呼客人，忙得好有勁。"]],"有效":[["ㄧㄡˇ ㄒㄧㄠˋ","有效果、成效。[例]她將有限的空間作了最有效的利用，使整個房間感覺非常寬敞整潔。"]],"有朝一日":[["ㄧㄡˇ ㄓㄠ ㄧ ㄖˋ","將來有一天。[例]有朝一日成功時，千萬別忘記曾經給予幫助的人。"]],"有條不紊":[["ㄧㄡˇ ㄊㄧㄠˊ ㄅㄨˋ ㄨㄣˋ","條理分明，有秩序。語本《書經．盤庚上》。[例]這位祕書總是將檔案整理得有條不紊，方便同事找尋所需的資料。"]],"有益":[["ㄧㄡˇ ㄧˋ","有幫助。[例]開卷有益"]],"有趣":[["ㄧㄡˇ ㄑㄩˋ","有趣味。[例]每天小玲都會將學校有趣的事，一一說給爸媽聽。"]],"朋友":[["ㄆㄥˊ ㄧㄡˇ","彼此有交情的人。[例]朋友相處久了難免有磨擦，彼此要多包容。"]],"服侍":[["ㄈㄨˊ ㄕˋ","侍候、照料。[例]一個嬌生慣養，處處要人服侍的人是很難適應團體生活的。"]],"服務":[["ㄈㄨˊ ㄨˋ","1.為社會、別人做事。[例]人生當以服務為目的。\n2.任職。[例]他在政府機關服務已經很多年了。"]],"服役":[["ㄈㄨˊ ㄧˋ","依照我國兵役法規定，男子在19歲至36歲之間，接受軍事訓練，擔負保家衛國的責任。為國民應盡的義務之一。[例]他雖在軍中服役，仍能利用空閒時間念書充實自己。　△服兵役_x000D_"]],"服從":[["ㄈㄨˊ ㄘㄨㄥˊ","遵從、聽從。[例]在軍中必須服從長官的命令。"]],"服飾":[["ㄈㄨˊ ㄕˋ","服裝和佩飾。[例]他的服飾搭配得體，頗能襯托出他的氣質。"]],"朝代":[["ㄔㄠˊ ㄉㄞˋ","某一世系帝王統治的時代。[例]唐朝是詩歌發展相當興盛的朝代。"]],"朝夕":[["ㄓㄠ ㄒㄧˋ","本指早晨和晚上。後亦比喻為從早到晚、時時刻刻。[例]她們朝夕相處，彼此融洽，情同姊妹。"]],"朝天":[["ㄔㄠˊ ㄊㄧㄢ","朝向上方。[例]四腳朝天、碗底朝天"]],"朝廷":[["ㄔㄠˊ ㄊㄧㄥˊ","1.君主辦事聽政的地方。[例]皇帝在朝廷接見各國前來進貢的使者。\n2.借指君主時代的政府。[例]他因屢建奇功受到朝廷的重視。"]],"朝政":[["ㄔㄠˊ ㄓㄥˋ","朝廷的政事。[例]把持朝政、干預朝政"]],"朝暮":[["ㄓㄠ ㄇㄨˋ","早晚。[例]他們因朝暮相處，日久生情，進而結成連理。"]],"朝會":[["ㄓㄠ ㄏㄨㄟˋ","中小學校於清晨所舉行的集會。[例]在今天的朝會上，校長頒發獎狀給這次月考成績優秀的同學。"]],"朝氣":[["ㄓㄠ ㄑㄧˋ","本指早晨的氣象。後比喻為清新活潑，奮發進取的氣概。與「暮氣」相對。[例]一大清早，學生們在操場上做著體操，個個精神抖擻，朝氣十足。"]],"朝氣蓬勃":[["ㄓㄠ ㄑㄧˋ ㄆㄥˊ ㄅㄛˊ","形容精神振作，充滿旺盛的活力。[例]看到隊員們個個朝氣蓬勃，紀律嚴整，讓人對此次比賽充滿信心。"]],"朝秦暮楚":[["ㄓㄠ ㄑㄧㄣˊ ㄇㄨˋ ㄔㄨˇ","秦和楚為戰國時代的兩大國，夾處其間的韓、趙、魏等國，時而事秦，時而事楚，反覆變化。比喻人心反覆無常。[例]他三心二意，朝秦暮楚，令人難以信賴。"]],"朝聖":[["ㄔㄠˊ ㄕㄥˋ","信徒朝拜聖地或聖跡。[例]每年總會有成千上萬的基督教徒前往耶路撒冷朝聖。"]],"朝陽":[["ㄓㄠ ㄧㄤˊ","早晨的太陽。[例]朝陽的光芒照亮了整片天空，美好的一天就此開始。"]],"朝露":[["ㄓㄠ ㄌㄨˋ","早上的露水，太陽一出就會被晒乾。常用來比喻短暫的事物。[例]人生有如朝露般的短暫，所以應加珍惜。"]],"期待":[["ㄑㄧˊ ㄉㄞˋ","期望等待。[例]這名新秀深具潛力，備受期待。"]],"期盼":[["ㄑㄧˊ ㄆㄢˋ","期待、盼望。[例]這波旱情極其嚴重，萬民引頸期盼早日普降甘霖。"]],"木偶":[["ㄇㄨˋ ㄡˇ","1.用木頭雕刻的人偶。[例]這些木偶是王伯伯費心收藏的藝術品。\n2.比喻不靈活或不能自主、受人操縱的人。[例]他的一舉一動聽人操縱，活像是個木偶。"]],"木工":[["ㄇㄨˋ ㄍㄨㄥ","1.製作木器的工人。[例]爸爸打算請木工做一個衣櫃。\n2.泛指各種以木材為原料的工藝。[例]他在中學畢業之後，便跟師傅一起學木工了。"]],"木材":[["ㄇㄨˋ ㄘㄞˊ","將樹木截斷用以供建築及製作器物的材料。[例]木材在製作器具或造屋之前，必須經過乾燥處理。"]],"木板":[["ㄇㄨˋ ㄅㄢˇ","木製的板子。[例]簡陋的木造房屋，常用木板來隔間。"]],"木棍":[["ㄇㄨˋ ㄍㄨㄣˋ","木製的棍子。[例]童子軍拿著木棍在會場維持秩序。"]],"木棒":[["ㄇㄨˋ ㄅㄤˋ","木製的棒子。"]],"木筏":[["ㄇㄨˋ ㄈㄚˊ","以木材平紮成的船板形水上交通工具，飄浮水面，可用來載人運物，多用於水道淺的河川。[例]乘著木筏順流而下，就可以到外婆家了。"]],"木頭":[["ㄇㄨˋ ˙ㄊㄡ","1.木材。[例]獨木舟是用整段木頭做成的。\n2.比喻人遲鈍或動作不靈活的人。[例]他反應遲鈍，簡直是塊木頭。"]],"未來":[["ㄨㄟˋ ㄌㄞˊ","將來。相對於現在、過去而言。[例]把握現在，才能創造未來。"]],"未必":[["ㄨㄟˋ ㄅㄧˋ","不一定。[例]近來天候不佳，園遊會未必能如期舉行。"]],"未曾":[["ㄨㄟˋ ㄘㄥˊ","沒有。與「曾經」相對。[例]自從畢業後，她未曾回到學校探望過師長。"]],"未知":[["ㄨㄟˋ ㄓ","不知道。[例]雖然動過緊急手術，可是能否能安然存活，尚在未知之天！"]],"末日":[["ㄇㄛˋ ㄖˋ","基督教稱世界即將滅亡的那一天。一般泛指生命結束或滅亡的日子。[例]把失戀當成世界末日來臨一般，實在沒有必要。"]],"末梢":[["ㄇㄛˋ ㄕㄠ","事物的最後部分。[例]神經末梢"]],"末端":[["ㄇㄛˋ ㄉㄨㄢ","物體的尾部或盡頭。[例]他在繩子的末端打了一個結。"]],"本事":[["ㄅㄣˇ ㄕˋ","1.文學或戲曲作品中所依據的故事情節或原委。[例]這部電影的本事取材自奧運選手的成長過程，十分感人。\n\t\n2.文學或戲曲作品中的情節大意。[例]早期電影放映時均附有本事說明劇情。"],["ㄅㄣˇ ˙ㄕ","能力、本領。[例]成就任何事業都得靠真本事，不要心存僥倖。"]],"本性":[["ㄅㄣˇ ㄒㄧㄥˋ","與生俱來的質性。[例]我相信每一個人的本性都是善良的。"]],"本質":[["ㄅㄣˇ ㄓˊ","人或事物的根本性質。[例]法律的本質是公平與正義。_x000D_"]],"朽壞":[["ㄒㄧㄡˇ ㄏㄨㄞˋ","腐朽損壞。[例]這棟木屋因受白蟻侵蝕，內部已朽壞，急需改建。"]],"杉木":[["ㄕㄢ ㄇㄨˋ","植物名。杉科杉木屬，常綠大喬木。樹幹挺直，樹皮縱裂，外皮呈棕褐色，內皮為赤色。葉旋生而扭成二列，螺旋狀著生，線狀披針形，邊緣有細鋸齒。花單性，雌雄同株。果實為卵圓形毬果，有短柄，種子下垂。材質堅硬細緻，可供建築和製造器具，亦可製作棺木。[例]高山地區普遍可栽植耐寒的杉木。"]],"杏仁":[["ㄒㄧㄥˋ ㄖㄣˊ","杏核中的仁，為杏的種子。扁圓如心臟形，味美，微苦，可炒食，亦可入藥。[例]杏仁茶、杏仁豆腐　△杏核兒"]],"杏壇":[["ㄒㄧㄥˋ ㄊㄢˊ","孔子授徒講學的地方。後人因而在山東曲阜孔廟前築壇、建亭、書碑、植杏，取名杏壇。今作為教育界的通稱。[例]這位老師獻身杏壇四十年，作育英才無數。"]],"材料":[["ㄘㄞˊ ㄌㄧㄠˋ","1.一切可供製作的原料或可供取用的資料。[例]這個故事是寫小說的好材料。\n2.適合從事某事的人。[例]他手指靈巧，音感又佳，是塊學習樂器的材料。"]],"材質":[["ㄘㄞˊ ㄓˊ","工業設計或藝術創作上所稱的創作材料。[例]這套廚具以不鏽鋼材質製成，非常耐用。"]],"村莊":[["ㄘㄨㄣ ㄓㄨㄤ","鄉民聚集居住的地方。[例]這村莊還保有許多舊式建築，十分難得。"]],"杜撰":[["ㄉㄨˋ ㄓㄨㄢˋ","指毫無事實根據而憑空捏造、虛構。[例]小說中的人物大多是作者杜撰出來的。"]],"杜絕":[["ㄉㄨˋ ㄐㄩㄝˊ","阻塞斷絕。[例]近年強颱日增，澈底整治河川，杜絕水患是當務之急。"]],"杜鵑":[["ㄉㄨˋ ㄐㄩㄢ","1.動物名。鳥綱鵑形目。身體呈灰褐色，口大，尾羽長，胸腹有黑色橫紋。初夏時常啼叫不停，鳴聲淒厲。[例]杜鵑的叫聲特殊，在古代的文學著作中經常提及。\n2.植物名。杜鵑花科杜鵑花屬，常綠灌木。葉呈橢圓形，春夏開紅、紫或白花。[例]春天一到，陽明山上的杜鵑便綻放著嬌豔的花朵。　△映山紅"]],"束手無策":[["ㄕㄨˋ ㄕㄡˇ ㄨˊ ㄘㄜˋ","比喻想不出辦法解決問題。[例]他得了一種怪病，群醫皆束手無策。"]],"束緊":[["ㄕㄨˋ ㄐㄧㄣˇ","綁緊。[例]他束緊袋口，以免東西掉出來。"]],"束縛":[["ㄕㄨˋ ㄈㄨˊ","拘束或限制。[例]小鹿掙開繩圈的束縛，迅速跑向叢林。"]],"杯墊":[["ㄅㄟ ㄉㄧㄢˋ","用來放置茶杯的小墊子。[例]你最好在那茶杯下墊個杯墊，免得在桌面上留下印子。"]],"杯子":[["ㄅㄟ ˙ㄗ","用來盛放液體或其他物品的小型容器。[例]他端起杯子，一口氣把酒喝光。　△杯 　◎"]],"杯盤狼藉":[["ㄅㄟ ㄆㄢˊ ㄌㄤˊ ㄐㄧˊ","狼藉，散亂的樣子。杯盤狼藉形容酒席結束，杯盤散亂的情形。[例]宴會結束，桌上杯盤狼藉，不知要費多少時間才能清理乾淨。"]],"東倒西歪":[["ㄉㄨㄥ ㄉㄠˇ ㄒㄧ ㄨㄞ","歪倒傾斜、搖搖欲墜的樣子。[例]強烈颱風過境，把庭院的圍籬吹得東倒西歪，七橫八豎。"]],"東區":[["ㄉㄨㄥ ㄑㄩ","某地區的東邊部分。[例]臺北市的東區漸漸取代西門町，成為新的商業中心。"]],"東方":[["ㄉㄨㄥ ㄈㄤ","1.太陽升起的方向。[例]她們徹夜長談，一直到東方天色微明才各自就寢。\n2.亞洲的泛稱。[例]東方人"]],"東西":[["ㄉㄨㄥ ㄒㄧ","1.東方與西方。[例]東西文化交流\n2.從東到西。[例]東西走向、東西橫貫公路"],["ㄉㄨㄥ ˙ㄒㄧ","物品。[例]我習慣睡前把明天要用的各項東西先準備好，以免到時手忙腳亂。"]],"東部":[["ㄉㄨㄥ ㄅㄨˋ","某一區域的東側部分。[例]花蓮位於臺灣的東部。"]],"松柏":[["ㄙㄨㄥ ㄅㄛˊ","松樹和柏樹。常用來比喻長壽或堅貞的節操。[例]這座廟宇四周松柏參天，環境顯得十分清幽。"]],"松鼠":[["ㄙㄨㄥ ㄕㄨˇ","動物名。哺乳綱齧齒目松鼠科。形似鼠而大，毛黑褐色，尾巴長大而蓬鬆，密生長毛，眼大，視力敏銳，門牙尖銳。活潑機靈，行動敏捷，常棲息樹上，以果實為生。[例]松鼠會將食物貯藏在樹洞、鳥巢等處，作為冬天的食物。　△栗鼠　◎"]],"枇杷":[["ㄆㄧˊ ㄆㄚˊ","植物名。薔薇科枇杷屬，常綠喬木。葉呈長橢圓形，邊緣具疏鋸齒。花小色白，果實也稱為「枇杷」，呈淡黃或橙黃色，可食。葉和核果可入藥，具鎮咳作用。　◎"]],"枉費心機":[["ㄨㄤˇ ㄈㄟˋ ㄒㄧㄣ ㄐㄧ","白白的浪費心思。意謂徒勞無功。[例]事情的發展已成定局，大家不用再枉費心機了。"]],"枕藉":[["ㄓㄣˋ ㄐㄧㄝˋ","縱橫相枕而躺。[例]大夥兒太累了，紛紛在通鋪上枕藉而臥。"]],"林地":[["ㄌㄧㄣˊ ㄉㄧˋ","林木所生長的土地。[例]濫墾林地不僅影響生態平衡，同時也是違法的行為。"]],"果園":[["ㄍㄨㄛˇ ㄩㄢˊ","種植果樹的園子。[例]觀光果園　△果木園"]],"果子":[["ㄍㄨㄛˇ ˙ㄗ","草木的果實，多指可食用者而言。[例]果園裡的木棚架上結滿了即將成熟的果子。"]],"果汁":[["ㄍㄨㄛˇ ㄓ","用水果擠榨出來的汁液，或以水果汁液做成的飲料。如檸檬汁、葡萄汁等。[例]多喝果汁可以美容養顏。"]],"果然":[["ㄍㄨㄛˇ ㄖㄢˊ","事情的結果與所預料的一樣。[例]經過一年的苦練，他果然贏得這次乒乓球比賽的冠軍。"]],"枝椏":[["ㄓ ㄧㄚ","樹木旁生的小枝條。[例]春天一到，許多樹木都長出了新綠的枝椏。"]],"枯燥":[["ㄎㄨ ㄗㄠˋ","單調、無趣。[例]枯燥乏味"]],"枯竭":[["ㄎㄨ ㄐㄧㄝˊ","乾枯、竭盡。[例]水源枯竭、思慮枯竭"]],"枴杖":[["ㄍㄨㄞˇ ㄓㄤˋ","支撐身體的手杖。[例]自從上回跌跤以後，奶奶總是拄著枴杖走路。"]],"架構":[["ㄐㄧㄚˋ ㄍㄡˋ","1.構築、建造。[例]架構橋梁的工程技術，在科學發達的今天顯得日新月異。\n2.結構、間架。[例]這篇論文的架構完整嚴謹，確是一篇佳作。"]],"柏樹":[["ㄅㄛˊ ㄕㄨˋ","→柏"]],"柏油":[["ㄅㄛˊ ㄧㄡˊ","煙煤、石油、油頁岩、木材或其他有機物乾餾後，凝聚而成具有稠度的液體或半固體。主要成分為瀝青，呈褐色或黑色，是製造煤氣時的副產品。[例]自從這條泥土路鋪上柏油後，光整的路面取代過去塵土飛揚的情形。"]],"某些":[["ㄇㄡˇ ㄒㄧㄝ","對一些不指名的人、地或事物的代稱。[例]某些人、某些場所"]],"染色":[["ㄖㄢˇ ㄙㄜˋ","用染料使物品著色。[例]老師將植物細胞標本染色後分發給各組，用顯微鏡觀察。"]],"柔媚":[["ㄖㄡˊ ㄇㄟˋ","溫柔嫵媚。[例]她的性格剛毅堅強，同時也有柔媚的一面。"]],"柔軟":[["ㄖㄡˊ ㄖㄨㄢˇ","軟而不粗硬。[例]晒過太陽的棉被，摸起來十分柔軟。"]],"查哨":[["ㄔㄚˊ ㄕㄠˋ","巡查守衛崗哨之軍警人員的執勤情形。[例]查哨必須確實，千萬不可敷衍了事，以保部隊安全。"]],"查獲":[["ㄔㄚˊ ㄏㄨㄛˋ","調查而獲得。[例]警方查獲大批走私槍械，價值高達數千萬元。"]],"查緝":[["ㄔㄚˊ ㄑㄧˋ","追查緝捕。[例]警方出動大批警力查緝在逃的槍擊要犯。"]],"柱子":[["ㄓㄨˋ ˙ㄗ","1.建築物中，支撐橫梁、桁架、樓板等的直立長條形構件。可用鋼筋混凝土、鋼材、磚石或木材等製成。[例]柱子是支撐屋頂重量的主要架構。\n2.瑟、箏等撥弦樂器上的支弦木。木製，橋形，立於瑟、箏等面板上傳導共鳴。"]],"柳丁":[["ㄌㄧㄡˇ ㄉㄧㄥ","→柳橙"]],"柳橙":[["ㄌㄧㄡˇ ㄔㄥˊ","植物名。芸香科柑屬，常綠小喬木。枝多棘針，葉呈橢圓形，上有鋸齒。果實為小圓球狀，表皮有溝紋，果肉深黃且多汁。[例]柳橙含有豐富的纖維和維他命Ｃ，是營養豐富的水果。　△甜橙、柳丁　◎"]],"柳絮":[["ㄌㄧㄡˇ ㄒㄩˋ","柳花凋謝結實，種子上帶有叢毛，隨風飛散，形似棉絮，故稱為「柳絮」。[例]落花兼柳絮，無處不紛紛。（唐．張喬〈送友人往宜春〉詩）"]],"柴扉":[["ㄔㄞˊ ㄈㄟ","以樹枝木幹做成的門。借指簡陋的居所。[例]柴扉虛掩"]],"柴火":[["ㄔㄞˊ ㄏㄨㄛˇ","供燃燒用的木材。[例]他把柴火扔進燃燒中的火爐，希望讓室內更暖和些。"]],"柵欄":[["ㄓㄚˋ ㄌㄢˊ","用竹子、木條、鐵條或其他物品做成的圍欄。[例]屋外的柵欄上爬滿了牽牛花，顯得綠意盎然。"]],"柵門":[["ㄓㄚˋ ㄇㄣˊ","有柵欄的門或柵欄形式的門。[例]校方為維護學童的安全，上課時都將校門口的柵門拉上。"]],"栗子":[["ㄌㄧˋ ˙ㄗ","栗樹的果實。"]],"校園":[["ㄒㄧㄠˋ ㄩㄢˊ","一校所擁有的校地範圍。[例]校園中遍植花木，綠意盎然。"]],"校對":[["ㄐㄧㄠˋ ㄉㄨㄟˋ","1.核對原稿以訂正文字在排印或繕寫上的錯誤。[例]這本書必須經過縝密校對後，才可以出版發行。\n2.負責校對工作的人。[例]他是報社的校對，工作相當辛苦。"]],"校歌":[["ㄒㄧㄠˋ ㄍㄜ","代表一個學校的教育宗旨與特有精神的歌曲。[例]每年的新生訓練，學校都會安排校歌的教唱。"]],"校稿":[["ㄐㄧㄠˋ ㄍㄠˇ","訂正稿件或出版品在文字或內容上的錯誤。[例]每到月底，他就必須加班來處理繁重的校稿工作。"]],"校舍":[["ㄒㄧㄠˋ ㄕㄜˋ","學校的教室房舍。[例]學校將於近期內改建老舊校舍，以維護師生安全。"]],"校規":[["ㄒㄧㄠˋ ㄍㄨㄟ","學校訂定，學生須遵行的規則。[例]在學校要遵守校規，努力讀書，做個好學生。"]],"校長":[["ㄒㄧㄠˋ ㄓㄤˇ","主持一校行政事務的最高領導人。[例]本校校長的作風開明，很受師生愛戴。"]],"校際":[["ㄒㄧㄠˋ ㄐㄧˋ","學校與學校之間。[例]這學期的校際學術交流活動，相信有助於增廣學生視野。"]],"栩栩如生":[["ㄒㄩˇ ㄒㄩˇ ㄖㄨˊ ㄕㄥ","形貌生動逼真，像真的一樣。語本《莊子．齊物論》。[例]這幅畫上的花鳥畫得栩栩如生，像是可以聞到花香、聽到鳥叫一般。"]],"株連":[["ㄓㄨ ㄌㄧㄢˊ","因一人犯罪，而牽連其他相關人。像砍伐樹木，根株相連一般。[例]株連九族"]],"核准":[["ㄏㄜˊ ㄓㄨㄣˇ","審定後批准。多用於公文。[例]他的房屋貸款案已經核准了，近日內就可到銀行辦理手續。"]],"核桃":[["ㄏㄜˊ ㄊㄠˊ","→胡桃"]],"根基":[["ㄍㄣ ㄐㄧ","1.事物的基礎。[例]他的公司根基穩固，雖然經濟不景氣，業績仍然小幅成長。\n2.佛教上指道根。[例]他本是個有大根基的人，只因利慾薰心，把他的道根埋沒了。"]],"根據":[["ㄍㄣ ㄐㄩˋ","憑靠、依據。[例]警方根據線民通報，將潛逃多日的人犯逮捕歸案。"]],"根本":[["ㄍㄣ ㄅㄣˇ","1.事物的本源、基礎。[例]人民是國家的根本，沒有人民，國家便無法建立。\n2.主要的、重要的。[例]憲法是國家的根本大法。\n3.澈底。[例]只有釜底抽薪，才能根本解決問題。\n4.從來、自始至終。[例]這本書我根本就沒見過，要如何評論呢？"]],"根柢":[["ㄍㄣ ㄉㄧˇ","1.草木的根。[例]人民之於國家就如根柢之於草木一樣重要。\n2.事物的基礎、根基。[例]這位老教授的國學根柢深厚，在詩詞方面造詣尤精。"]],"根深柢固":[["ㄍㄣ ㄕㄣ ㄉㄧˇ ㄍㄨˋ","比喻基礎堅固，牢不可拔。[例]老一輩的人有些觀念根深柢固，難以改變。"]],"根深蒂固":[["ㄍㄣ ㄕㄣ ㄉㄧˋ ㄍㄨˋ","比喻事物十分牢固，不易動搖。[例]他此種觀念已是根深蒂固，很難改變。"]],"根莖":[["ㄍㄣ ㄐㄧㄥ","1.根狀的地下莖。外形像根，有節，沒有根冠而有頂芽。[例]蓮藕是蓮花的根莖，可供食用。\n2.植物的根和莖。[例]這棵百年老樹根莖粗大，枝葉茂密。"]],"根部":[["ㄍㄣ ㄅㄨˋ","植物的營養器官之一，多生長在土裡，具有固定、吸收或貯藏水分、養分的功能。"]],"格局":[["ㄍㄜˊ ㄐㄩˊ","結構和式樣。[例]這間房子格局方正，採光通風俱佳，居住起來一定非常舒適。"]],"格式":[["ㄍㄜˊ ㄕˋ","規格形式。[例]公文書寫，依照用途或對象的不同，而有一定的格式。"]],"格格不入":[["ㄍㄜˊ ㄍㄜˊ ㄅㄨˋ ㄖㄨˋ","彼此牴觸，不相調和。[例]這幅西洋油畫掛在古色古香的大廳上，顯得格格不入。"]],"栽培":[["ㄗㄞ ㄆㄟˊ","1.種植培養。[例]這套指導人如何栽培花卉的書非常實用。\n2.比喻教育、提拔人才。[例]他在老師多年來大力栽培之下，終於學有所成。"]],"栽種":[["ㄗㄞ ㄓㄨㄥˋ","種植。[例]政府將陸續輔導農家栽種蔬果，以改善稻米產量過剩的情形。"]],"桂冠":[["ㄍㄨㄟˋ ㄍㄨㄢ","用桂花、桂葉編成的帽子。古代希臘人用來授予傑出的詩人或競技勝利的人。後人常以桂冠做為光榮的象徵。[例]對古希臘人來說，桂冠雖不值錢，但卻代表很高的榮譽。"]],"桂圓":[["ㄍㄨㄟˋ ㄩㄢˊ","經過烘乾或炒熟的龍眼果實。[例]桂圓的味道香甜，是滋補養氣的極品。"]],"桂花":[["ㄍㄨㄟˋ ㄏㄨㄚ","桂樹所開的花。花朵小，呈白色或淡黃色。可供觀賞及用為香料。[例]秋天是桂花飄香的季節。　◎"]],"桃花":[["ㄊㄠˊ ㄏㄨㄚ","1.桃樹所開的花。[例]滿山的桃花，好像在熱烈歡迎春天的來臨。_x000D_\n2.桃花星。星命學家視為凶星。"]],"框架":[["ㄎㄨㄤ ㄐㄧㄚˋ","事物的格式與架構。[例]這部電影僅保留原著故事的框架，細節部分則有很大的改變。"]],"桌子":[["ㄓㄨㄛ ˙ㄗ","上有一水平面，下有柱子支撐，可在桌面工作或放置物品的家具。製材為木、鋁、塑膠等。計算單位為「張」。[例]他忙得沒時間整理堆在桌子上的書。"]],"桌面":[["ㄓㄨㄛ ㄇㄧㄢˋ","桌子上部平板的表面。[例]她的桌面總是清理得很乾淨，一塵不染。"]],"梁上君子":[["ㄌㄧㄤˊ ㄕㄤˋ ㄐㄩㄣ ㄗˇ","竊賊的雅稱。[例]他們家裡昨夜遭到梁上君子的光顧，損失慘重。"]],"梁柱":[["ㄌㄧㄤˊ ㄓㄨˋ","用來支撐房屋等建築物的條柱。[例]這個村莊受到炮火的摧殘，到處只見斷垣殘壁和傾頹的梁柱。"]],"梅花":[["ㄇㄟˊ ㄏㄨㄚ","梅樹所開的花。花五瓣，色白或紅，臘月開者稱為「臘梅」，早春開者稱為「春梅」。[例]梅花堅貞耐寒，是我國的國花。　◎"]],"梅花鹿":[["ㄇㄟˊ ㄏㄨㄚ ㄌㄨˋ","動物名。脊椎動物門哺乳綱偶蹄目。夏季毛栗紅色，背有白斑，冬季呈棕紅黃色。共有十三個亞種，分布在亞洲東南部。臺灣梅花鹿是其中體形較大之亞種，生活於中低海拔的平原及丘陵地。　◎"]],"梅雨":[["ㄇㄟˊ ㄩˇ","華南地區每年五至七月、日本南部六至七月初，因東南季風滯留而帶來綿綿不斷的雨水，因正值梅子成熟，故稱為「梅雨」。[例]梅雨時期空氣潮溼，東西容易發霉。　△霉雨、黃梅雨"]],"條件":[["ㄊㄧㄠˊ ㄐㄧㄢˋ","具備的要項。[例]他在各方面都符合公司聘任人才的條件，因而被錄取。"]],"條文":[["ㄊㄧㄠˊ ㄨㄣˊ","法律或章程中分條說明的文字。[例]律師必須熟諳法律條文，才能妥善維護當事人的利益。"]],"條款":[["ㄊㄧㄠˊ ㄎㄨㄢˇ","法令、條約、契約或文件中所訂定的事項。[例]政府曾經在訓政時期制定臨時條款，作為當時的施政方針。"]],"條理":[["ㄊㄧㄠˊ ㄌㄧˇ","脈絡、條貫。[例]條理分明"]],"條紋":[["ㄊㄧㄠˊ ㄨㄣˊ","長條狀的紋路、圖案。[例]這件襯衫的條紋設計得很別緻。"]],"梯子":[["ㄊㄧ ˙ㄗ","用以登高的器具或設備。[例]他爬上梯子，把棉被收到櫥櫃的頂層。"]],"梯形":[["ㄊㄧ ㄒㄧㄥˊ","只有兩邊平行，另外兩邊不平行的四邊形。[例]梯形的跳箱上窄下寬，穩定性高，使用時相當安全。◎"]],"梯田":[["ㄊㄧ ㄊㄧㄢˊ","山坡上呈階梯狀的田地。階與階之間以矮埂相隔，有利於耕作及蓄水。[例]從飛機窗口望出去，山谷間的梯田構成一幅美麗的幾何圖案。"]],"梳妝":[["ㄕㄨ ㄓㄨㄤ","婦女梳理妝扮。[例]為了參加今晚的喜宴，她特別梳妝打扮了一番。"]],"梳子":[["ㄕㄨ ˙ㄗ","梳理毛髮的用具。[例]使用豬鬃製的梳子梳頭，聽說可以防止頭髮分叉。"]],"梳洗":[["ㄕㄨ ㄒㄧˇ","梳頭洗臉。[例]他梳洗乾淨後，便出門去了。"]],"棄置":[["ㄑㄧˋ ㄓˋ","廢棄不用，扔在一旁。[例]這部腳踏車棄置多年，都生鏽了。"]],"棉布":[["ㄇㄧㄢˊ ㄅㄨˋ","棉紗織成的布。[例]棉布吸汗耐洗，是很好的製衣布料。"]],"棉花":[["ㄇㄧㄢˊ ㄏㄨㄚ","棉的果實成熟後，種子表面著生的纖毛。可供紡織用。[例]棉花的纖維柔韌纖長，是重要的紡織原料。"]],"棉花糖":[["ㄇㄧㄢˊ ㄏㄨㄚ ㄊㄤˊ","先將砂糖加熱成漿，再用機器將其快速轉動，拉成糖絲，纏繞在竹棒上的零嘴，外觀像似一團棉絮，故稱為「棉花糖」。[例]舔棉花糖是許多人童年的美好回憶。"]],"棍棒":[["ㄍㄨㄣˋ ㄅㄤˋ","棍子與棒子。[例]他昨晚遭歹徒以棍棒襲擊，身上的財物被洗劫一空。"]],"棒喝":[["ㄅㄤˋ ㄏㄜˋ","佛教用語。禪師啟發弟子開悟的方法。或用棒打，或大聲一喝，或棒喝一起來，使弟子於當下開悟。後來也指用言語警醒迷誤的人。[例]父親這番話猶如棒喝，使他內心深為過去的荒唐行為悔恨不已。"]],"棒球":[["ㄅㄤˋ ㄑㄧㄡˊ","1.一種球類運動。比賽時，出場球員通常每隊九人，每場比賽有九局，各攻守一次為一局，九局賽畢，以得分多者為勝，兩隊得分相等，則延長比賽。　◎_x000D_\n2.棒球運動所用的球。為正圓形，以皮、塑膠等製成，圓周為23公分，重約142至149公克。"]],"棗泥":[["ㄗㄠˇ ㄋㄧˊ","把棗煮熟後去皮、搗爛製成的泥狀物。多用作糕餅的餡。[例]棗泥月餅"]],"棟梁":[["ㄉㄨㄥˋ ㄌㄧㄤˊ","1.房屋的正梁或指建造房屋的木材。[例]楠、檜質地細密，外形筆直，宜作棟梁。\n2.比喻擔負國家重責大任的人。[例]青少年是國家未來的棟梁，我們應細心培育。"]],"森嚴":[["ㄙㄣ ㄧㄢˊ","嚴密不可侵犯的樣子。[例]戒備森嚴、防衛森嚴"]],"森林":[["ㄙㄣ ㄌㄧㄣˊ","樹木密生的寬廣地區。[例]森林兼具木材供應、水土保持、觀光休憩等功能，是重要的天然資源之一。"]],"棲息":[["ㄑㄧ ㄒㄧˊ","休息、停留。[例]這些水鳥夜晚棲息在沼澤旁的樹叢裡。"]],"棲身":[["ㄑㄧ ㄕㄣ","居住、停留。[例]流浪者是沒有固定棲身之所的。"]],"椅子":[["ㄧˇ ˙ㄗ","泛指供人坐、臥的器具。其材質有木、竹、藤、金屬、塑膠等。[例]公園裡有許多造型優雅的椅子，供遊人休憩之用。"]],"植物":[["ㄓˊ ㄨˋ","百穀草木的總稱。為有機生物之一。植物細胞與動物細胞最大的不同在於具有細胞壁，且大部分內含葉綠素，可行光合作用，攝取光、水等無機物，並轉化成養分。植物通常固定於一處，種子可藉水、風、人等外力帶至各地繁殖。種類繁多，約可分為草本、木本等類別。"]],"椰子":[["ㄧㄝˊ ˙ㄗ","植物名。棕櫚科可可椰子屬，常綠喬木。樹幹直立，不分枝，頂端叢生羽狀複葉。果實亦稱為「椰子」，橢圓形，核果，外果皮為青綠色，中果皮為厚纖維層，內果皮為角質硬殼。果核外層為白色椰肉，可生食或製成椰子油或椰子粉；中心空腔內充滿椰子汁，為天然的清涼飲料。[例]南臺灣天氣炎熱，適合種植椰子。　◎"]],"楊桃":[["ㄧㄤˊ ㄊㄠˊ","植物名。酢漿草科五斂子屬，常綠灌木或小喬木。高一丈多，葉為羽狀複葉，互生，呈倒卵形或卵狀橢圓形。果實為漿果，亦稱為「楊桃」，於七月至十二月成熟，形為卵狀橢圓，呈黃色或黃綠色，多汁，味道甘酸，氣味芳香，可供食用及藥用。[例]楊桃汁有清嗓潤喉的功效，常喝可使聲音圓潤甜美。　△羊桃、五斂子　◎"]],"楚楚可憐":[["ㄔㄨˇ ㄔㄨˇ ㄎㄜˇ ㄌㄧㄢˊ","本形容松枝纖弱柔美。語出南朝宋．劉義慶《世說新語．言語》。後用以形容姿態嬌媚動人，惹人憐愛。也用以形容柔弱哀悽，讓人心生憐憫。[例]見她眼眶含淚，一副楚楚可憐的樣子，實在令人不捨。"]],"楚河漢界":[["ㄔㄨˇ ㄏㄜˊ ㄏㄢˋ ㄐㄧㄝˋ","1.楚漢相爭時，項羽、劉邦約定以鴻溝為界。比喻敵對雙方的界限。[例]南北韓以北緯38度線為楚河漢界，各據一方，對峙至今。\n\t\n2.象棋棋盤的中界。[例]下棋時，兵、卒兩種棋子只要過了楚河漢界，便不得再回頭了。"]],"業績":[["ㄧㄝˋ ㄐㄧ","泛指工作的成果、績效。[例]本公司今年的業績比去年成長了百分之五。"]],"極端":[["ㄐㄧˊ ㄉㄨㄢ","1.物體的端頭、頂點。[例]子午線是一條通過地球南北極端的假想線。\n2.非常，達到極點。[例]他接待顧客極端熱忱，深得經理的欣賞、倚重。\n3.偏向一方的言行。[例]他的個性偏激，常走極端，當心招來不良的後果。"]],"楷模":[["ㄎㄞˇ ㄇㄛˊ","榜樣，可供學習效法的對象。[例]孝悌楷模、勞工楷模"]],"概要":[["ㄍㄞˋ ㄧㄠˋ","總括的綱要，多用於書名。[例]這本《圖解天文學概要》，作者用簡要文字，概括天文學的基礎知識，並配合圖解說明，讀來淺顯易懂。"]],"榮幸":[["ㄖㄨㄥˊ ㄒㄧㄥˋ","非常光采、幸運。[例]受到老師的讚美，使我深感榮幸。"]],"榮獲":[["ㄖㄨㄥˊ ㄏㄨㄛˋ","光榮的得到。[例]他榮獲雙料冠軍，興奮不已。"]],"榮耀":[["ㄖㄨㄥˊ ㄧㄠˋ","1.光采顯耀。[例]獲得諾貝爾獎是多麼榮耀的事！\n2.光榮的聲譽。[例]他將所有的榮耀歸於父母師長。"]],"榮華富貴":[["ㄖㄨㄥˊ ㄏㄨㄚˊ ㄈㄨˋ ㄍㄨㄟˋ","顯榮發達，財多位尊。[例]釋迦牟尼捨棄王宮中榮華富貴的生活，苦身修道，終成正果。"]],"構思":[["ㄍㄡˋ ㄙ","運用心思。通常指創作前所進行的思維活動。[例]經過長時間的構思，他終於完成了劇本的大綱。"]],"構成":[["ㄍㄡˋ ㄔㄥˊ","造成、組成。[例]這棟大樓是由地上十層、地下兩層的建築物所構成。"]],"構築":[["ㄍㄡˋ ㄓㄨˊ","建造修築。[例]軍方在邊境構築了許多防禦堡壘，以確保國家的安全。"]],"構造":[["ㄍㄡˋ ㄗㄠˋ","物體的組織。[例]人體的構造非常精妙，非人工技術所能模擬。"]],"槌子":[["ㄔㄨㄟˊ ˙ㄗ","敲擊器物的工具。[例]我想釘個釘子來掛畫，卻到處找不到槌子。"]],"槍托":[["ㄑㄧㄤ ㄊㄨㄛ","槍枝後部用以承受射擊時產生的後座力，和便於用手托住的部位。[例]打靶時，槍托應抵住肩窩，才不會誤傷身體的其他部位。"]],"樂器":[["ㄩㄝˋ ㄑㄧˋ","奏樂所使用的器具。種類甚多，普通可分為弦樂器、管樂器、敲擊樂器三大類。[例]在所有的樂器中，他最擅長彈吉他。"]],"樂曲":[["ㄩㄝˋ ㄑㄩˇ","凡符合音樂三要素（旋律、節奏、和聲）的有組織的聲音，稱為「樂曲」。[例]他致力於樂曲的創作，想成為作曲家。"]],"樂極生悲":[["ㄌㄜˋ ㄐㄧˊ ㄕㄥ ㄅㄟ","歡樂至極，往往轉生悲愁。[例]他中了一千萬的彩券，高興得逢人就說，結果樂極生悲，當天晚上彩券就被人給偷了。"]],"樓宇":[["ㄌㄡˊ ㄩˇ","泛指房屋。[例]古城中高高低低的樓宇，在夕陽的映照下，更具特色。"]],"樓層":[["ㄌㄡˊ ㄘㄥˊ","樓房的層級。[例]這棟大廈的樓層之多，號稱全市第一。"]],"樓頂":[["ㄌㄡˊ ㄉㄧㄥˇ","樓房最上面露空的一層。[例]他在樓頂上布置了一座空中花園。"]],"標本":[["ㄅㄧㄠ ㄅㄣˇ","經過處理，可長久保存原貌的動、植、礦物等。如蝴蝶標本、岩石標本。"]],"標榜":[["ㄅㄧㄠ ㄅㄤˇ","1.表揚、稱讚。[例]自我標榜、互相標榜\n2.揭示、標舉。[例]現在的洗衣機大多標榜全自動，操作方便。"]],"標的":[["ㄅㄧㄠ ㄉㄧˋ","1.箭靶、射擊目標。[例]標的物\n2.努力的方向、目標。[例]人生的標的是追求有意義的生活，而非舒適的生活。"]],"標示":[["ㄅㄧㄠ ㄕˋ","標明、揭示。[例]這塊牌子標示著「遊客止步」。"]],"標題":[["ㄅㄧㄠ ㄊㄧˊ","標明文章或作品內容的簡短語句。[例]報刊上的標題，要簡明醒目。"]],"標點符號":[["ㄅㄧㄠ ㄉㄧㄢˇ ㄈㄨˊ ㄏㄠˋ","在文句中，用來分別句讀（ㄉㄡˋ）和標明詞句性質、種類的符號。[例]老師說不要小看標點符號，標錯了，語意就不同了。"]],"模仿":[["ㄇㄛˊ ㄈㄤˇ","仿照、仿效。[例]學習階段的小孩子很容易模仿父母的一言一行。"]],"模型":[["ㄇㄛˊ ㄒㄧㄥˊ","模仿實物的原形，縮小製成的樣品。通常用於展示或實驗。[例]飛機模型、汽車模型"]],"模式":[["ㄇㄛˊ ㄕˋ","1.標準形式。[例]寫作公文有一定的模式，不可任意更動。\n2.事情處理的方式。[例]臺灣以中小企業為主體的經建模式，對開發中國家深具參考價值。"]],"模擬":[["ㄇㄛˊ ㄋㄧˇ","模仿實際狀況。[例]模擬考、模擬演習"]],"模樣":[["ㄇㄛˊ ㄧㄤˋ","1.形狀、式樣。[例]錦盒裡的首飾，不知道是什麼模樣？_x000D_\n2.容貌、樣子。"]],"模範":[["ㄇㄛˊ ㄈㄢˋ","榜樣。[例]他的言談舉止足以作為所有青年的模範。"]],"模糊":[["ㄇㄛˊ ㄏㄨˊ","不清楚、不明顯。[例]大霧中視線模糊不清，駕駛人請減速慢行。"]],"樣式":[["ㄧㄤˋ ㄕˋ","樣子、形式。[例]這種樣式的裙子，搭配高筒靴會更出色。"]],"樣貌":[["ㄧㄤˋ ㄇㄠˋ","形狀、外貌。[例]在不知對方樣貌如何就要我去相親，實在很不妥。"]],"樸實":[["ㄆㄨˊ ㄕˊ","質樸實在。[例]他為人溫柔敦厚，誠懇樸實。"]],"樸素":[["ㄆㄨˊ ㄙㄨˋ","樸實而不刻意修飾。[例]他的穿著一向簡單樸素。"]],"樹叢":[["ㄕㄨˋ ㄘㄨㄥˊ","叢聚生長的樹木。[例]夏天的夜裡，常可看見許多螢火蟲穿梭在樹叢中。"]],"樹幹":[["ㄕㄨˋ ㄍㄢˋ","樹木的主要枝幹。[例]廟旁那棵百年老樹的樹幹昨天被雷劈斷了。"]],"樹木":[["ㄕㄨˋ ㄇㄨˋ","木本植物的通稱。[例]道路兩旁的樹木被颱風吹得東倒西歪。"]],"樹林":[["ㄕㄨˋ ㄌㄧㄣˊ","成片聚集生長的樹木。[例]夏季的午後，他喜歡到河邊的樹林裡散步。"]],"樹枝":[["ㄕㄨˋ ㄓ","從樹幹旁生出的枝條。[例]一陣風吹過，看樹枝搖曳，樹影婆娑。"]],"樹根":[["ㄕㄨˋ ㄍㄣ","樹木的根。"]],"樹梢":[["ㄕㄨˋ ㄕㄠ","樹木的末端。[例]有隻小鳥停在樹梢上迎風鳴唱。"]],"樹脂":[["ㄕㄨˋ ㄓ","一種植物體內分泌的碳氫化合物。由損傷的樹皮處流出。原為半流體，其易於揮發的部分失去後，即成透明固體，質地堅硬，加熱則軟化，具有可塑性。[例]樹脂可用以製造塗料、黏合劑、絕緣材料等。"]],"樹葉":[["ㄕㄨˋ ㄧㄝˋ","樹木的葉子。[例]樹葉在雨後的陽光照射下顯得特別青翠。"]],"樹薯":[["ㄕㄨˋ ㄕㄨˇ","植物名。大戟科木薯屬，落葉灌木。原產巴西，分布於西、南非洲及亞洲南部各國。莖有髓，脆而易折，分枝為三叉。葉掌狀，三至七深裂。花為圓錐花序，黃或紅黃色。果實為球狀蒴果，具稜翅。其肉質地下塊根亦稱為「樹薯」。[例]樹薯可供食用或製粉，並為酒精及味精的主要原料。　△木薯"]],"橙色":[["ㄔㄥˊ ㄙㄜˋ","橘黃色。[例]這件橙色的洋裝穿在她身上，顯得十分亮麗。"]],"機器":[["ㄐㄧ ㄑㄧˋ","機械器具。由各種零件組成，可供運轉操控以節省人力，並使工作更為便利、生產量提高的裝置。[例]人類發明各式各樣的機器來代替人工，促進了產業的發達。"]],"機場":[["ㄐㄧ ㄔㄤˇ","指載卸客貨及供飛機起飛和降落的區域。[例]機場裡擠滿了出入境的旅客，真是熱鬧極了。　△航空站"]],"機會":[["ㄐㄧ ㄏㄨㄟˋ","關鍵性的時機。[例]錯過這個機會，你會後悔一輩子。"]],"機械":[["ㄐㄧ ㄒㄧㄝˋ","泛指各種機具、器械。[例]機械可以完成很多人力做不到的工作。"]],"機率":[["ㄐㄧ ㄌㄩˋ","機會或可能性的比值。[例]他聰明又用功，考上好學校的機率很大。"]],"機緣":[["ㄐㄧ ㄩㄢˊ","原指眾生信受佛法的時機和因緣。後泛指機會和因緣。[例]由於種種機緣，我們才能相遇又相知。"]],"機遇":[["ㄐㄧ ㄩˋ","機會和境遇。[例]縱使有了好的機遇，也得看我們是否能趁勢掌握良機。"]],"橡樹":[["ㄒㄧㄤˋ ㄕㄨˋ","植物名。殼斗科麻櫟屬，落葉喬木。多分布於北半球溫帶地區。葉有柄，互生，長橢圓狀披針形。殼斗皿形，外有鑿形鱗片。果實為橡實，果皮堅硬，內含種子，可做豬、鳥等的飼料。木材可做家具、地板、枕木。樹皮可製收斂劑。[例]這套家具完全採用橡樹原木製成。　△麻櫟"]],"橡皮擦":[["ㄒㄧㄤˋ ㄆㄧˊ ㄘㄚ","用橡皮製成，可擦掉筆跡的文具。[例]品質不佳的橡皮擦常會把紙面塗成黑黑的一片。"]],"橡皮筋":[["ㄒㄧㄤˋ ㄆㄧˊ ㄐㄧㄣ","以橡膠製成的圓環形或線形物品。具有彈性，可用來綑綁東西。[例]小時候我們常把橡皮筋串成一長條，當做跳繩來玩。"]],"橡膠":[["ㄒㄧㄤˋ ㄐㄧㄠ","具有橡皮狀彈性的鏈狀高分子物質。分為植物樹液取出的天然橡膠和化學合成的合成橡膠。因其具有彈性、耐磨、不透水、不導電、不透氣等性質，可製成橡皮筋、皮球、輪胎、絕緣體等。[例]天然橡膠、合成橡膠"]],"橫向":[["ㄏㄥˊ ㄒㄧㄤˋ","橫的方向。[例]螃蟹是橫向行走的動物。"]],"橫禍":[["ㄏㄥˋ ㄏㄨㄛˋ","意外的災難、禍患。[例]這真是天外飛來的橫禍。"]],"橫財":[["ㄏㄥˋ ㄘㄞˊ","意外獲得的財富，多指用非法手段取得的財物。[例]他在香港賭賽馬，獲得一筆橫財。"]],"橫貫":[["ㄏㄥˊ ㄍㄨㄢˋ","橫向貫穿兩邊。[例]這條公路橫貫中央山脈，是連繫東西部的便捷要道。"]],"橫越":[["ㄏㄥˊ ㄩㄝˋ","橫向越過。[例]他獨自駕駛飛機橫越太平洋的創舉，受到國人的矚目。"]],"橫跨":[["ㄏㄥˊ ㄎㄨㄚˋ","橫向跨越。[例]雨後的彩虹像拱橋般橫跨在天邊，景緻十分迷人。"]],"檔名":[["ㄉㄤˇ ㄇㄧㄥˊ","檔案名稱。[例]電腦中每個檔案都有檔名，以便於存取或刪除。"]],"檔案":[["ㄉㄤˇ ㄢˋ","1.分類保存的各種文件和資料。[例]開會前，請借調相關檔案備查。\n2.電腦中相關資料的組合。[例]你最好把電腦中的檔案備份至隨身碟，以防萬一。"]],"檢定":[["ㄐㄧㄢˇ ㄉㄧㄥˋ","檢查判定。[例]他參加職業考試接受技能檢定。"]],"檢查":[["ㄐㄧㄢˇ ㄔㄚˊ","檢視查看。[例]開學後，學生將暑假作業送交老師檢查。"]],"檢舉":[["ㄐㄧㄢˇ ㄐㄩˇ","舉發他人行為的過失或違法的事情。[例]選委會鼓勵民眾檢舉賄選。"]],"檢視":[["ㄐㄧㄢˇ ㄕˋ","檢驗視查。[例]為確保公共安全無虞，有關單位已派員檢視該場所的逃生設備。"]],"檢討":[["ㄐㄧㄢˇ ㄊㄠˇ","檢視探討。[例]公司定期召開業務會議檢討營運得失。"]],"檢閱":[["ㄐㄧㄢˇ ㄩㄝˋ","1.檢視查看。[例]他接到成績單後，決定申請複查，請考委會再次檢閱試卷。_x000D_\n2.軍隊的檢查校閱。[例]檢閱三軍"]],"檢驗":[["ㄐㄧㄢˇ ㄧㄢˋ","檢查測驗。[例]藥廠研發的新產品已通過藥品檢驗標準，近日即將上市。"]],"檳榔":[["ㄅㄧㄣ ㄌㄤˊ","植物名。棕櫚科檳榔屬，常綠喬木。高三丈多，葉為羽狀複葉，枝幹似椰子而較細，栽種五年，才開花結果。一年一株可生三、四穗，每穗結實三、四百顆，味澀而微甘。將果實切開夾入石灰、荖花可食之。"]],"櫛比鱗次":[["ㄐㄧㄝˊ ㄅㄧˋ ㄌㄧㄣˊ ㄘˋ","比喻緊密的連接排列。[例]大都會裡高樓大廈櫛比鱗次，好似一座水泥叢林。"]],"權利":[["ㄑㄩㄢˊ ㄌㄧˋ","法律上所規定人民應享有的利益。[例]人民的權利受到憲法的保障。"]],"權力":[["ㄑㄩㄢˊ ㄌㄧˋ","可控制、管轄、支配等的職權或力量。[例]這片土地是他私人所有，他有權力做任何處置，誰也無法干涉。"]],"權勢":[["ㄑㄩㄢˊ ㄕˋ","權力威勢。[例]他為人淡泊名利，對於財富、權勢總是不屑營求。"]],"權益":[["ㄑㄩㄢˊ ㄧˋ","人民依法所享有的利益。[例]我們應勇於舉發不法的製造商，才不致讓自己的消費權益受損。"]],"權限":[["ㄑㄩㄢˊ ㄒㄧㄢˋ","權力的界限、範圍。[例]公司裡的每一個人都有自己的工作權限，最好不要越權行事。"]],"欠缺":[["ㄑㄧㄢˋ ㄑㄩㄝ","短少、不夠。[例]工廠因欠缺人手而刊登廣告招募員工。"]],"次序":[["ㄘˋ ㄒㄩˋ","依次排列的順序。[例]乘車應排隊依先後次序上下車，不要爭先恐後。"]],"次數":[["ㄘˋ ㄕㄨˋ","1.動作、事件等重複出現的回數。[例]請假次數過多，會影響工作考績。\n2.數學的代數式中，各項變數次方的數目，稱為「次數」。單項中的次數為各元的指數總和，如 x²y次數為3。代數式中，則以各項中次方最高者的次數為此一代數式的次數，如x²＋2x＋1的次數為2。"]],"次第":[["ㄘˋ ㄉㄧˋ","先後的次序。[例]優勝者上臺依次第排好，接受頒獎。"]],"欣喜":[["ㄒㄧㄣ ㄒㄧˇ","歡欣喜悅。[例]他獲知妻子順利生產，母女平安，欣喜不已。"]],"欣賞":[["ㄒㄧㄣ ㄕㄤˇ","1.以喜愛的心情來玩賞。[例]儘管寒流來襲，大家仍然不畏風寒，到合歡山欣賞雪景。\n2.喜愛賞識。[例]他堅決果斷，勇於任事的氣魄頗受民眾欣賞。"]],"欲擒故縱":[["ㄩˋ ㄑㄧㄣˊ ㄍㄨˋ ㄗㄨㄥˋ","想要擒住或控制對方，卻故意先放鬆，讓對方鬆弛戒備，使更容易就範。[例]歹徒中了警方欲擒故縱之計，於外出購物時遭警方逮獲。"]],"欲望":[["ㄩˋ ㄨㄤˋ","想要得到某種東西或目的的意念、願望。[例]許多人的欲望需求就像無底洞，永遠也填不滿。"]],"欲罷不能":[["ㄩˋ ㄅㄚˋ ㄅㄨˋ ㄋㄥˊ","想要停止卻做不到。語出《論語．子罕》。[例]電腦的應用千變萬化，讓人一接觸就欲罷不能。"]],"欲蓋彌彰":[["ㄩˋ ㄍㄞˋ ㄇㄧˊ ㄓㄤ","想要遮蓋掩飾，卻反而更加顯露。語本《左傳．昭公三十一年》。[例]看他忙於辯解的樣子，簡直就是欲蓋彌彰，不打自招。"]],"欺人太甚":[["ㄑㄧ ㄖㄣˊ ㄊㄞˋ ㄕㄣˋ","欺凌他人到了使人無法容忍的地步。[例]他不過才借了一千塊，你就要他還二千，未免欺人太甚了。"]],"欺凌":[["ㄑㄧ ㄌㄧㄥˊ","欺壓凌辱。[例]如果發現有人遭受流氓欺凌，應該立即通報警察處理。"]],"欺瞞":[["ㄑㄧ ㄇㄢˊ","蓄意隱藏真相，不讓人知道。[例]你應該要開誠布公，一味欺瞞是解決不了事情的。"]],"欺負":[["ㄑㄧ ㄈㄨˋ","欺凌侮辱。[例]他仗著人高馬大，總是欺負弱小。"]],"欺騙":[["ㄑㄧ ㄆㄧㄢˋ","說假話哄騙。[例]用欺騙的手段達到目的是不對的。"]],"欽羨":[["ㄑㄧㄣ ㄒㄧㄢˋ","敬佩羨慕。[例]他年紀輕輕，卻已經事業有成，實在讓人欽羡。"]],"歌喉":[["ㄍㄜ ㄏㄡˊ","唱歌的嗓子，亦借指歌聲。[例]同樂會上，音樂老師應同學的要求，上臺一展歌喉。"]],"歌曲":[["ㄍㄜ ㄑㄩˇ","結合曲調和歌詞，可供演唱的樂曲。[例]流行歌曲、抒情歌曲"]],"歌謠":[["ㄍㄜ ㄧㄠˊ","民間歌曲或通俗歌曲。[例]兒童歌謠、鄉土歌謠"]],"歡呼":[["ㄏㄨㄢ ㄏㄨ","快樂的呼叫。[例]鼓掌歡呼"]],"歡唱":[["ㄏㄨㄢ ㄔㄤˋ","快活的歌唱。[例]齊聲歡唱"]],"歡喜":[["ㄏㄨㄢ ㄒㄧˇ","快樂、高興。[例]滿心歡喜"]],"歡愉":[["ㄏㄨㄢ ㄩˊ","歡樂愉快。[例]每到農作物豐收的季節，整個農村便呈現出一片歡愉的景象。"]],"歡樂":[["ㄏㄨㄢ ㄌㄜˋ","歡喜快樂。[例]春節期間處處洋溢著歡樂的氣氛。"]],"歡笑":[["ㄏㄨㄢ ㄒㄧㄠˋ","歡樂的笑。[例]他的幽默和機智，經常給班上帶來許多歡笑。"]],"歡迎":[["ㄏㄨㄢ ㄧㄥˊ","1.高興地迎接。[例]列隊歡迎_x000D_\n2.誠心希望，樂意接受。[例]歡迎光臨、歡迎投稿"]],"歡騰":[["ㄏㄨㄢ ㄊㄥˊ","高興得歡呼跳躍。[例]欣逢雙十國慶，普天同慶，舉國歡騰。"]],"止咳":[["ㄓˇ ㄎㄜˊ","使咳嗽停止。[例]這種藥既能止咳又不傷胃，你不妨試試！"]],"止血":[["ㄓˇ ㄒㄧㄝˇ","使傷口不再流血。[例]適當的止血急救，可以增加重傷病人的存活機會。"]],"正中":[["ㄓㄥˋ ㄓㄨㄥ","正當中間的位置。[例]廳堂靠牆的正中有一張桌子，桌上供奉著一座神像。"]],"正在":[["ㄓㄥˋ ㄗㄞˋ","剛好位於某個地點或恰在進行某種活動。[例]車禍發生時，他正在現場而目擊了整個事件的經過。"]],"正好":[["ㄓㄥˋ ㄏㄠˇ","恰好、剛好。[例]他來得正好，可以證明我沒有說謊。"]],"正月":[["ㄓㄥ ㄩㄝˋ","農曆每年的第一個月。[例]農業社會裡，春節各項慶祝活動總要到正月十五才全部結束。"]],"正當":[["ㄓㄥˋ ㄉㄤ","正值、適逢。[例]正當我等得不耐煩之際，他才突然出現。"],["ㄓㄥˋ ㄉㄤˋ","合理的、正確的。[例]從事休閒活動要選擇正當的娛樂場所。"]],"正直":[["ㄓㄥˋ ㄓˊ","公正剛直。[例]他做人做事都很正直，從不徇私護短。"]],"正確":[["ㄓㄥˋ ㄑㄩㄝˋ","準確、無誤。[例]測驗完畢後，老師將考題的正確答案公布在黑板上。"]],"正襟危坐":[["ㄓㄥˋ ㄐㄧㄣ ㄨㄟˊ ㄗㄨㄛˋ","整理服裝儀容，端正的坐好。形容莊重嚴肅的樣子。[例]與會人員個個正襟危坐，安靜聆聽主席訓示。"]],"正面":[["ㄓㄥˋ ㄇㄧㄢˋ","1.自己面部五官的那一面。[例]他看到老師從正面走來。\n2.亦用於指物體顯現在外，裝飾較講究的一面。[例]這櫃子的正面經過刨磨上光後，顯得很平滑。\n3.事情顯示肯定效益的一面。相對於反面而言。[例]正面意義、正面影響"]],"此起彼落":[["ㄘˇ ㄑㄧˇ ㄅㄧˇ ㄌㄨㄛˋ","這裡起來，那裡落下。形容連續不斷。[例]過年時鞭炮聲此起彼落，好不熱鬧。"]],"步伐":[["ㄅㄨˋ ㄈㄚ","行進的腳步。"]],"步兵":[["ㄅㄨˋ ㄅㄧㄥ","徒步作戰的兵種，為陸軍主要兵種。具有多種性能，以近距離及獨立戰鬥為其特色。[例]我方出動坦克掩護步兵進攻。"]],"步履":[["ㄅㄨˋ ㄌㄩˇ","步伐、腳步。[例]期末考一結束，大家都踩著輕鬆的步履，踏上返鄉的路途。"]],"步步為營":[["ㄅㄨˋ ㄅㄨˋ ㄨㄟˊ ㄧㄥˊ","形容小心謹慎，防備周全。[例]他因初次創業，所以凡事都步步為營，不敢掉以輕心。"]],"步行":[["ㄅㄨˋ ㄒㄧㄥˊ","徒步行走。[例]弟弟每天步行去上學。"]],"步驟":[["ㄅㄨˋ ㄗㄡˋ","本指行走的緩急、快慢。今多用以比喻做事的程序。[例]他處理此事不按步驟進行，難怪會手忙腳亂。"]],"武力":[["ㄨˇ ㄌㄧˋ","1.軍事力量、兵力。[例]政府的精銳部隊，殲滅了以武力進犯的敵人。\n2.勇力、蠻力。[例]以武力逼迫他人就範，是野蠻的行為。"]],"武功":[["ㄨˇ ㄍㄨㄥ","1.以武力使鄰邦臣服的功績。[例]唐太宗貞觀年間是文治武功都達到鼎盛的時期。\n2.武術、功夫。[例]小說中的大俠常懷著一身武功，行走江湖。"]],"武器":[["ㄨˇ ㄑㄧˋ","具有攻擊能力的設備或器械。多作為軍事用途。[例]現代的武器多具有強大的殺傷力。"]],"武士":[["ㄨˇ ㄕˋ","歐洲及日本中古社會的一種階層。以作戰為職業，且具備高尚的道德情操。[例]日本的幕府沒落後，不少武士頓失所依，成為浪人。"]],"歧視":[["ㄑㄧˊ ㄕˋ","輕視，以不公平的態度相待。[例]種族歧視"]],"歧路亡羊":[["ㄑㄧˊ ㄌㄨˋ ㄨㄤˊ ㄧㄤˊ","楊子的鄰居走失了一隻羊，因大路上岔路太多，縱使苦苦搜尋，也無法找回丟失的羊。典出《列子．說符》。比喻事理本同末異，繁雜多變，求道者苦無正確方向，容易誤入歧途，以致一事無成。[例]他廣蒐各家學說，卻無法融會貫通，理出頭緒，終致歧路亡羊，一無所獲。"]],"歪斜":[["ㄨㄞ ㄒㄧㄝˊ","不正。[例]他因顏面神經受到損害，而導致口眼歪斜。"]],"歷代":[["ㄌㄧˋ ㄉㄞˋ","過去的各世代、朝代。[例]歷代皇朝、歷代祖先"]],"歷史":[["ㄌㄧˋ ㄕˇ","1.人類過去所有活動的總稱。[例]走過的歷史，我們無能為力去改變；但未來要什麼樣的歷史，我們卻可以自己去抉擇。\n2.以歷史為研究對象的學科。[例]歷史是國民中學的必修科目。\n3.過去的事實。[例]他們之間的恩怨早已成為歷史。"]],"歷時":[["ㄌㄧˋ ㄕˊ","所經歷的時間。[例]這項活動，從籌備到結束，歷時達三個月之久。"]],"歷歷在目":[["ㄌㄧˋ ㄌㄧˋ ㄗㄞˋ ㄇㄨˋ","清楚明白的呈現在眼前。[例]他望著發黃的相片，往事歷歷在目，彷彿又回到舊日的時光。"]],"歷盡":[["ㄌㄧˋ ㄐㄧㄣˋ","經歷遍盡。[例]這本小說敘述的是一位老人歷盡滄桑，見證世態炎涼的悲慘故事。"]],"歷程":[["ㄌㄧˋ ㄔㄥˊ","經歷的過程。[例]心路歷程"]],"歷經":[["ㄌㄧˋ ㄐㄧㄥ","經歷遍盡。[例]他歷經千辛萬苦，終於找到失散多年的兄弟。"]],"歷練":[["ㄌㄧˋ ㄌㄧㄢˋ","歷經磨練。[例]經過這些年來的歷練，他成熟了許多。"]],"歸屬":[["ㄍㄨㄟ ㄕㄨˇ","歸附、隸屬。[例]這塊山坡地是歸屬於林務局管理的。"]],"歸心似箭":[["ㄍㄨㄟ ㄒㄧㄣ ㄙˋ ㄐㄧㄢˋ","形容回家的心意非常迫切。[例]他離家多時，歸心似箭，恨不得能長對翅膀立刻飛回家去。"]],"歸納":[["ㄍㄨㄟ ㄋㄚˋ","歸類、歸結。[例]將書中的重點歸納起來，有助於提昇學習的效率。"]],"死亡":[["ㄙˇ ㄨㄤˊ","喪失生命。[例]親人的遽逝，讓她體會到死亡的巨痛。"]],"死心塌地":[["ㄙˇ ㄒㄧㄣ ㄊㄚ ㄉㄧˋ","專心一意，絕不改變。[例]儘管丈夫在病榻上昏迷多年，她依然死心塌地的陪伴在身邊。"]],"殊途同歸":[["ㄕㄨ ㄊㄨˊ ㄊㄨㄥˊ ㄍㄨㄟ","走不同的道路而到達同一目的。比喻採取的方法雖不同，所得的結果卻相同。語本《易經．繫辭下》。[例]許多宗教教義殊途同歸，最後終是勸人為善。"]],"殘留":[["ㄘㄢˊ ㄌㄧㄡˊ","剩餘、殘餘。[例]蔬果應澈底做好清潔工作，以避免農藥殘留。"]],"殘破":[["ㄘㄢˊ ㄆㄛˋ","殘缺破爛、不完整。[例]這棟房屋年久失修，早已殘破不堪。"]],"殘缺":[["ㄘㄢˊ ㄑㄩㄝ","殘破而不完整。[例]這份資料由於年代久遠，不但字跡模糊不清，頁數也殘缺不全。"]],"段考":[["ㄉㄨㄢˋ ㄎㄠˇ","學期中階段性的測驗。[例]學校將在下個月舉行這學期的第一次段考，大家要好好準備。"]],"段落":[["ㄉㄨㄢˋ ㄌㄨㄛˋ","文章、事物根據內容劃分後該停頓或結束的地方。[例]這篇文章段落清楚，文字也很流暢，算得上是篇佳作。"]],"殷切":[["ㄧㄣ ㄑㄧㄝˋ","熱切、急切。[例]父母殷切期望出國求學的兒子早日歸來。"]],"殷勤":[["ㄧㄣ ㄑㄧㄣˊ","懇切、周到。[例]母親端出水果來，殷勤地招待客人。"]],"殷實":[["ㄧㄣ ㄕˊ","充足、富裕。[例]雖然家道殷實，他還是過著很節儉的生活。"]],"殷紅":[["ㄧㄢ ㄏㄨㄥˊ","紅黑色。[例]車禍現場留下大片殷紅的血跡，令人觸目驚心。"]],"殺價":[["ㄕㄚ ㄐㄧㄚˋ","要求降低價錢。[例]本店商品貨真價實，謝絕殺價。"]],"殺戮":[["ㄕㄚ ㄌㄨˋ","屠殺、殺害。[例]這部戰爭片的殺戮場面，令人看得膽顫心驚。"]],"殺雞儆猴":[["ㄕㄚ ㄐㄧ ㄐㄧㄥˇ ㄏㄡˊ","比喻懲罰一個人以警告另一個人。"]],"毋須":[["ㄨˊ ㄒㄩ","不用、沒有必要。[例]這件事我會負責處理，妳毋須擔心。"]],"母親":[["ㄇㄨˇ ㄑㄧㄣ","1.稱謂。對媽媽的稱呼。[例]最難報答母親恩，母親恩情海樣深。　◎_x000D_\n2.比喻孕育的根源。[例]大地是萬物的母親。"]],"每位":[["ㄇㄟˇ ㄨㄟˋ","每一個，用以指人。[例]此次活動所需費用，由每位同仁自行負擔。"]],"每天":[["ㄇㄟˇ ㄊㄧㄢ","天天、每一天。[例]他每天都到操場跑步。　△每日"]],"每逢":[["ㄇㄟˇ ㄈㄥˊ","凡是遇到。[例]每逢佳節倍思親。（唐．王維〈九月九日憶山東兄弟〉詩）"]],"比喻":[["ㄅㄧˇ ㄩˋ","譬喻、比方。如以月亮的圓缺來比喻人事的盛衰，以流水的逝去比喻年華難再。"]],"比手畫腳":[["ㄅㄧˇ ㄕㄡˇ ㄏㄨㄚˋ ㄐㄧㄠˇ","以手腳等肢體動作輔助說明，表達想要傳達的意思。[例]弟弟比手畫腳了老半天，我還是一頭霧水。"]],"比比皆是":[["ㄅㄧˋ ㄅㄧˋ ㄐㄧㄝ ㄕˋ","比比，指到處。到處都是，形容很多。[例]如今趕時髦的人，比比皆是。"]],"比照":[["ㄅㄧˇ ㄓㄠˋ","1.按照已有的格式或援例辦理。[例]這件事比照前例辦理。\n2.比較對照。[例]把這兩件案子的犯罪模式一比照後，可以斷定是同一個人做的。"]],"比肩":[["ㄅㄧˋ ㄐㄧㄢ","1.肩靠肩。[例]他們比肩坐在山坡上看夕陽。\n2.形容彼此關係密切，互助合作。[例]面對此次金融風暴，大家應比肩努力，共度難關。"]],"比賽":[["ㄅㄧˇ ㄙㄞˋ","1.比較本領、技能的高低或優劣。[例]他正和同學在比賽下圍棋。\n2.指競技、較量的事情。[例]籃球比賽、合唱比賽、繪畫比賽"]],"比較":[["ㄅㄧˇ ㄐㄧㄠˋ","取兩樣以上的事物，評比較量其優劣、高下等。[例]近來因為工作比較忙碌，所以遲了幾天回信。"]],"比鄰":[["ㄅㄧˋ ㄌㄧㄣˊ","1.近鄰。[例]海內存知己，天涯若比鄰。（唐．王勃〈杜少府之任蜀州〉詩）\n2.相鄰。[例]這兩棟比鄰的房屋，格局和價碼都差不多。"]],"毛巾":[["ㄇㄠˊ ㄐㄧㄣ","用來擦臉、擦身體的棉織品。質地鬆軟，吸水性佳。[例]他因為使用不潔的毛巾擦臉而感染砂眼。"]],"毛毛蟲":[["ㄇㄠˊ ㄇㄠˊ ㄔㄨㄥˊ","→毛蟲"]],"毛毛雨":[["ㄇㄠˊ ㄇㄠˊ ㄩˇ","密而細的小雨。[例]出門時別忘記攜帶雨具，外面已經下起毛毛雨來了。"]],"毛茸茸":[["ㄇㄠˊ ㄖㄨㄥˊ ㄖㄨㄥˊ","形容毛多而柔細。[例]毛茸茸的絨毛玩具，很受小朋友歡迎。"]],"毛衣":[["ㄇㄠˊ ㄧ","用毛線織成的衣服。[例]這是母親親手織的毛衣，穿在身上格外溫暖。"]],"毫不在意":[["ㄏㄠˊ ㄅㄨˋ ㄗㄞˋ ㄧˋ","一點都不放在心上。[例]他受到旁人的誹謗，卻毫不在意，不當一回事。"]],"毫不猶豫":[["ㄏㄠˊ ㄅㄨˋ ㄧㄡˊ ㄩˋ","當機立斷，一點也不遲疑。[例]他見到朋友有難，總是毫不猶豫地出力相助。"]],"毫無":[["ㄏㄠˊ ㄨˊ","一點也沒有。[例]毫無限制地砍伐森林會造成地球環境惡化。"]],"民俗":[["ㄇㄧㄣˊ ㄙㄨˊ","民間傳統的風俗習慣。[例]臺灣由於特殊地理環境及歷史背景，產生豐富多元的民俗特色。"]],"民國":[["ㄇㄧㄣˊ ㄍㄨㄛˊ","1.指民主國家。[例]國父認為民有、民治、民享的國家，即所謂的「民國」。\n2.中華民國的簡稱。[例]他生於民國三十年十月十日。"]],"氛圍":[["ㄈㄣ ㄨㄟˊ","周圍的氣氛和情調。[例]這家餐廳經常舉辦親子活動，讓用餐環境洋溢著歡樂喜悅的氛圍。"]],"氣喘":[["ㄑㄧˋ ㄔㄨㄢˇ","1.呼吸急促。[例]氣喘吁吁\n2.由於支氣管發生痙攣性收縮而引起的陣發性呼吸困難、哮鳴、咳嗽的反復發作。如肺炎、心力衰竭、慢性支氣管炎等病多有這種症狀。　△哮喘"]],"氣喘吁吁":[["ㄑㄧˋ ㄔㄨㄢˇ ㄒㄩ ㄒㄩ","大聲喘氣、呼吸急促的樣子。[例]走了二個多鐘頭的上坡路，大家都氣喘吁吁的。"]],"氣喘如牛":[["ㄑㄧˋ ㄔㄨㄢˇ ㄖㄨˊ ㄋㄧㄡˊ","形容呼吸急促，大聲喘氣。[例]他平常很少運動，才爬幾層樓梯就氣喘如牛了。"]],"氣定神閒":[["ㄑㄧˋ ㄉㄧㄥˋ ㄕㄣˊ ㄒㄧㄢˊ","形容人的神態安詳閒適。[例]這位棋手在緊要關頭仍能氣定神閒，從容對弈，真是不容易。"]],"氣憤":[["ㄑㄧˋ ㄈㄣˋ","生氣憤怒。[例]因為無故被冤枉，他感到非常氣憤。"]],"氣氛":[["ㄑㄧˋ ㄈㄣ","在特定的環境中，所形成的一種可感覺的景象或情調。[例]這間餐廳的氣氛很羅曼蒂克。"]],"氣沖沖":[["ㄑㄧˋ ㄔㄨㄥ ㄔㄨㄥ","形容非常生氣的樣子。[例]他拿著過期的鮮乳，氣沖沖的找老闆理論。"]],"氣泡":[["ㄑㄧˋ ㄆㄠˋ","氣體在固體或液體的內部或表面，所形成的球狀或半球狀體。[例]飲料中大量的氣泡，讓他喝了以後不斷打嗝。"]],"氣焰":[["ㄑㄧˋ ㄧㄢˋ","火勢。比喻人或其他事物的威風、氣勢。[例]他的成就並不突出，氣焰卻是囂張得令人厭煩。"]],"氣球":[["ㄑㄧˋ ㄑㄧㄡˊ","以伸縮性的橡膠薄膜或塗有樹膠的布等製囊，再灌入氫、氦、空氣等氣體所製成的球。若充入比空氣輕的氣體時，則可飄浮上升。用途很廣，如用來做玩具及氣象、軍事上的探測、乘坐飛行等。[例]大會所施放的五彩氣球，將天空點綴得十分美麗。"]],"氣象":[["ㄑㄧˋ ㄒㄧㄤˋ","1.一切大氣的狀態和現象，如颳風、下雨、打雷、閃電等。[例]天氣圖是氣象預報時不可或缺的基本資料。\n2.人的舉止、氣度。[例]他的眉宇間帶著幾分威嚴的氣象。\n3.景象、情況。[例]這棟樓房年久失修，早已失去昔日豪華的氣象。"]],"氣質":[["ㄑㄧˋ ㄓˊ","性情、秉性。通常指天生的才質或表現在言行舉止上的個性特點。[例]她出身於書香世家，氣質清麗高雅。"]],"氣餒":[["ㄑㄧˋ ㄋㄟˇ","喪失鬥志，失去勇氣和信心。[例]失敗時千萬別氣餒，只有持續努力，才有成功的機會。"]],"水塘":[["ㄕㄨㄟˇ ㄊㄤˊ","池塘。[例]鵝兒在水塘裡悠游，好不自在！"]],"水壺":[["ㄕㄨㄟˇ ㄏㄨˊ","裝水的器具。[例]登山時最好攜帶水壺，以免口渴難耐。"]],"水彩":[["ㄕㄨㄟˇ ㄘㄞˇ","一種用水調和的繪畫顏料。係用膠水調製，可溶於水，較具透明性，但作品保存期限較油畫短。[例]小明到書局買了一盒水彩，準備畫圖用。"]],"水果":[["ㄕㄨㄟˇ ㄍㄨㄛˇ","可以生食，內含有漿液的果實。如橘子、梨子、西瓜、鳳梨等。[例]多吃水果，有益於養顏美容，幫助消化。"]],"水池":[["ㄕㄨㄟˇ ㄔˊ","積水的池子。[例]雨天過後，這個水池積滿了水。"]],"水泄不通":[["ㄕㄨㄟˇ ㄒㄧㄝˋ ㄅㄨˋ ㄊㄨㄥ","連水都無法流通。形容非常擁擠的樣子。[例]花車遊行時，圍觀群眾將街道擠得水泄不通。"]],"水流":[["ㄕㄨㄟˇ ㄌㄧㄡˊ","水流動的情形。[例]這座港口因水流穩定，終年不結冰，故經濟效益頗高。"]],"水源":[["ㄕㄨㄟˇ ㄩㄢˊ","1.河流發源的地方。[例]他們往溪流的上游走，想要一探它的水源。\n2.灌溉用水或飲用水等的來源。[例]最近水源不足，嚴重影響到人民生活。"]],"水溝":[["ㄕㄨㄟˇ ㄍㄡ","疏通流水的溝道。[例]我們要定期清除水溝，才不致於滋生蚊蟲。"]],"水滴":[["ㄕㄨㄟˇ ㄉㄧ","向下落的水點。[例]陣雨過後，水滴沿著屋簷掉落下來。"]],"水災":[["ㄕㄨㄟˇ ㄗㄞ","因久雨、河水氾濫、融雪或山洪暴發等因素而造成的災害。[例]連日的豪雨，已使各地水災頻傳。"]],"水珠":[["ㄕㄨㄟˇ ㄓㄨ","圓珠狀的水滴。[例]一顆顆水珠從葉上滑落，滴答的聲響，串成清脆的樂曲。"]],"水瓢":[["ㄕㄨㄟˇ ㄆㄧㄠˊ","被剖成兩半，用以舀水、盛水的瓢杓子。也可泛指一般的舀水工具。"]],"水田":[["ㄕㄨㄟˇ ㄊㄧㄢˊ","能蓄水，並供耕種的田地。[例]農夫正在整治水田以便插秧。"]],"水稻":[["ㄕㄨㄟˇ ㄉㄠˋ","植物名。禾本科稻屬，一年生草本。莖高約一公尺，直立、中空、有節。葉狹長而尖，互生，秋天莖頂抽穗，內含眾多小穗，每小穗頂端左右有二穎，內有二舟狀苞片，如花萼及花冠，具有保護的功用。花粉質輕量多，由風傳送，開花後結成穎果，稱為「稻子」，為人類主要糧食之一。其稈可作屋頂、編蓆、製鞋，或當燃料、飼料等。[例]臺灣的水稻每年至少有二穫。"]],"水管":[["ㄕㄨㄟˇ ㄍㄨㄢˇ","水流所通過的管子。[例]水管破裂了，趕緊找人來修理吧！"]],"水腫":[["ㄕㄨㄟˇ ㄓㄨㄥˇ","由於血液或淋巴循環不良等，使液體在身體的細胞組織中發生異常的積聚現象，而引起全身或局部的腫脹症狀。通常心臟病、腎臟病患者有此症狀。[例]患有水腫的病人應減少鹽分的攝取。"]],"水蜜桃":[["ㄕㄨㄟˇ ㄇㄧˋ ㄊㄠˊ","一種桃類的水果。果實飽滿，核小汁多，色美味甜。多產於海拔二千公尺左右的高山地區，臺灣則以東部及梨山產量最多。[例]水蜜桃除了生食外，也可加工製成果汁或罐頭。"]],"水面":[["ㄕㄨㄟˇ ㄇㄧㄢˋ","水的表面。[例]船身過處，在平靜的水面激起水花。　△水皮兒"]],"水鳥":[["ㄕㄨㄟˇ ㄋㄧㄠˇ","棲息在水邊，以水中生物為主食的鳥類。[例]假日時，我們喜歡到關渡平原觀賞水鳥。　△水禽"]],"永恆":[["ㄩㄥˇ ㄏㄥˊ","恆久不變。[例]患難時的相扶持，使他們堅信兩人之間的友誼將是永恆的。"]],"永遠":[["ㄩㄥˇ ㄩㄢˇ","永久、恆久。[例]古聖先賢的事蹟永遠留存史冊，供後人景仰與效法。"]],"求偶":[["ㄑㄧㄡˊ ㄡˇ","尋求配偶。[例]他因年紀漸長而求偶心切。"]],"求助":[["ㄑㄧㄡˊ ㄓㄨˋ","請求救助。[例]民眾如發現緊急事件，可立即打一一〇電話向警方求助。"]],"求救":[["ㄑㄧㄡˊ ㄐㄧㄡˋ","請求救援。[例]他一聽到有人高聲求救，便奮不顧身的衝上前去竭力相助。"]],"求饒":[["ㄑㄧㄡˊ ㄖㄠˊ","請求饒恕。[例]連聲求饒、跪地求饒"]],"汗流浹背":[["ㄏㄢˋ ㄌㄧㄡˊ ㄐㄧㄚˊ ㄅㄟˋ","流了很多汗，溼透了背部。[例]為了布置會場，他忙得汗流浹背。"]],"汗牛充棟":[["ㄏㄢˋ ㄋㄧㄡˊ ㄔㄨㄥ ㄉㄨㄥˋ","汗牛，指以牛車載書，牛累得出汗；充棟，指藏書滿屋。汗牛充棟形容書籍極多。語本唐．柳宗元〈唐故給中皇太子侍讀陸文通先生墓表〉。[例]想不到他的藏書汗牛充棟，多達數千本。"]],"汙染":[["ㄨ ㄖㄢˇ","1.沾染、弄髒。[例]車輛排出的廢氣，汙染了原本清新的空氣。_x000D_\n2.感染，因有害物質的傳播而造成危害。"]],"汙水":[["ㄨ ㄕㄨㄟˇ","不潔淨的水。包括雨水、家庭排放出來的廢水及工業廢水等。[例]工廠任意排放汙水，將嚴重破壞河川生態。"]],"汙泥":[["ㄨ ㄋㄧˊ","1.稀爛的泥土。[例]前面有一灘汙泥，小心別踩到。\n\t\n2.比喻骯髒、惡劣的環境。[例]這人能出汙泥而不染，奮發向上，真是難得。"]],"江湖":[["ㄐㄧㄤ ㄏㄨˊ","1.泛稱江河湖泊。[例]江湖風起，煙波蕩漾。\n\t\n2.舊時泛指中原各地。今多指所處的環境。[例]人在江湖，身不由己。\n\t\n3.指閱歷豐富，練達世故的人。[例]他是個老江湖，這事難不倒他的！"]],"池塘":[["ㄔˊ ㄊㄤˊ","蓄水的凹坑。[例]池塘裡有許多魚兒游來游去。"]],"汲取":[["ㄐㄧˊ ㄑㄩˇ","吸取、吸收。[例]陳老先生不斷的汲取新知，好學不倦的精神不輸給年輕人。"]],"決定":[["ㄐㄩㄝˊ ㄉㄧㄥˋ","1.做判斷或主張。[例]她有了更好的工作機會，所以決定向公司辭職。\n2.針對事情所做出的結論。[例]這項提案迫於時間，一定要在今天做出決定。"]],"決策":[["ㄐㄩㄝˊ ㄘㄜˋ","為達成計畫、目標所決定的方法或策略。[例]這是公司目前的決策，希望各位同仁支持。"]],"決議":[["ㄐㄩㄝˊ ㄧˋ","凡議案經主席提付表決者，不論表決結果，都稱為「決議」。[例]這次開會的決議，將從下星期開始實行。"]],"汽水":[["ㄑㄧˋ ㄕㄨㄟˇ","將碳酸氣溶於水中，再加入糖、果汁、香料等所製成的飲料。[例]汽水是高熱量的飲料，多喝無益。　△荷蘭水、蘇打水"]],"汽油":[["ㄑㄧˋ ㄧㄡˊ","從石油中提煉而得，揮發性高，燃點低，可用做內燃機的液態燃料，也用作橡膠、油漆等的溶劑。最常用為汽車、機車等產生原動力。[例]政府宣布，汽油價格將隨國際原油油價，回歸浮動機制。　△揮發油"]],"汽船":[["ㄑㄧˋ ㄔㄨㄢˊ","原指使用蒸汽機發動運轉行駛的船。後泛指各種動力引擎推進的船。[例]船長駕駛著汽船航行在河道上。"]],"汽艇":[["ㄑㄧˋ ㄊㄧㄥˇ","設有高速推進裝置的小型船，以內燃機發動，速度快，機動性大。[例]救難人員利用汽艇救起落水的遊客。　△摩托船"]],"汽車":[["ㄑㄧˋ ㄔㄜ","泛指任何使用自身裝設的動力以行駛，並有四輪或四輪以上的陸路交通運輸工具。通常用揮發性的油料與空氣混合，透過內燃方式來產生原動力，主要在公路上行駛，用來載人或搬運貨物。[例]汽車數量逐年增加，排放廢氣也隨著增加，如何減少廢氣汙染，成為環保重要議題。　◎"]],"沉吟":[["ㄔㄣˊ ㄧㄣˊ","1.遲疑猶豫。[例]他沉吟了片刻，決定親自出馬。\n2.仔細思考。[例]沉吟不語"]],"沉思":[["ㄔㄣˊ ㄙ","努力、深入的思考。[例]他沉思了好久，才回答這個問題。"]],"沉沒":[["ㄔㄣˊ ㄇㄛˋ","沉入水中。[例]這艘漁船因為觸礁而沉沒了。"]],"沉浸":[["ㄔㄣˊ ㄐㄧㄣˋ","本指浸泡在水中。後比喻處在某種境界中。[例]新婚半年的她，至今仍沉浸在幸福喜悅中。"]],"沉穩":[["ㄔㄣˊ ㄨㄣˇ","1.沉著穩重。[例]他個性沉穩內斂，做事認真負責。\n2.安穩恬酣。[例]她昨晚頭痛，整夜睡得很不沉穩。"]],"沉重":[["ㄔㄣˊ ㄓㄨㄥˋ","1.物體的重量很重。[例]叔叔旅行回來，沉重的行李內裝滿了各式各樣的禮物。\n2.形容病勢嚴重或壓力、負擔很大。[例]聽到親人病危的消息，他的心情更加沉重。"]],"沉默":[["ㄔㄣˊ ㄇㄛˋ","靜默，不說話。[例]一向愛說話的他，突然變得很沉默，令人覺得奇怪。"]],"沒什麼":[["ㄇㄟˊ ㄕㄣˊ ˙ㄇㄜ","1.沒關係。表示不在乎、無所謂的態度。[例]舉手之勞而已，沒什麼！\n2.沒有任何的事或物。[例]只要憑著堅強的毅力，沒什麼困難不能克服。"]],"沒完沒了":[["ㄇㄟˊ ㄨㄢˊ ㄇㄟˊ ㄌㄧㄠˇ","1.沒有終了的時候。[例]這件事怎老是做不完，好像沒完沒了。\n2.比喻與人糾纏不清。[例]為了一點小事件，他沒完沒了的纏著我理論，真是煩人。"]],"沒收":[["ㄇㄛˋ ㄕㄡ","私有財物因違反規定而予以強制扣留或充公。[例]入境通過海關時，任何違禁品都會被沒收。"]],"沒有":[["ㄇㄟˊ ㄧㄡˇ","1.表示具有或存在的否定。[例]沒有入場券不能進場參觀。\n2.表示已經或曾經的否定。[例]小張昨天沒有來上班。\n3.不如。[例]我沒有他那麼有學問。\n4.不到、不足。[例]他才來沒有三分鐘，又匆匆忙忙的走了。"]],"沒空":[["ㄇㄟˊ ㄎㄨㄥˋ","沒有空閒的時間。[例]最近太忙了，一直沒空處理這些瑣事。"]],"沒精打采":[["ㄇㄟˊ ㄐㄧㄥ ㄉㄚˇ ㄘㄞˇ","沒有精神、提不起勁來。[例]可能是昨晚沒睡好，他今天整個人沒精打采的。"]],"沒落":[["ㄇㄛˋ ㄌㄨㄛˋ","衰敝蕭條。[例]這個城市從前非常熱鬧，但因人口外移，現在已經沒落冷清了。"]],"沒趣":[["ㄇㄟˊ ㄑㄩˋ","1.沒有面子、難堪。[例]大伙兒正在興頭上，卻被他澆了冷水，好沒趣。\n2.沒有。[例]這部電影情節平淡，看來沒趣。"]],"沒錯":[["ㄇㄟˊ ㄘㄨㄛˋ","1.正確無誤。[例]你猜的沒錯，他果然是真正的幕後主使人。\n2.沒有做錯。[例]這件事他沒錯，你就別責罵他了。"]],"沖刷":[["ㄔㄨㄥ ㄕㄨㄚ","1.一面用水沖，一面刷洗。[例]這一大片玻璃經清潔人員沖刷後，顯得非常光亮。\n2.水流沖擊，使土石流失或造成剝蝕。[例]岸邊的岩石經過海浪的沖刷，逐漸形成了海蝕平臺。"]],"沖泡":[["ㄔㄨㄥ ㄆㄠˋ","用水沖澆浸泡。[例]初為人母的她，常為沖泡奶粉而手忙腳亂。"]],"沙啞":[["ㄕㄚ ㄧㄚˇ","聲音低沉嘶啞。[例]他的聲音因感冒而變得沙啞。"]],"沙子":[["ㄕㄚ ˙ㄗ","細小的石粒。[例]一群小朋友圍在工地旁的沙堆上玩沙子。"]],"沙拉":[["ㄕㄚ ㄌㄚ","一種以蔬菜、水果、肉類等食材為主，加醬料拌和而成的食品。§英salad[例]生菜沙拉"]],"沙洲":[["ㄕㄚ ㄓㄡ","水流中由泥沙淤積而成的陸地。[例]臺灣西南沿海有很多沙洲。"]],"沙漠":[["ㄕㄚ ㄇㄛˋ","地面覆蓋沙土，乾旱缺水，植物稀少的土地。平均年雨量不足二百五十公釐。如撒哈拉沙漠、澳洲沙漠等。[例]沙漠地區日夜的溫差極大。"]],"沙灘":[["ㄕㄚ ㄊㄢ","水邊的沙地。[例]沙灘上的足印被浪潮沖刷得了無痕跡。"]],"沙發":[["ㄕㄚ ㄈㄚ","一種有靠背、扶手，裝有彈簧或厚泡沫塑料的椅子。§英sofa [例]他整個人斜躺在沙發上，顯得疲憊不堪。"]],"沙礫":[["ㄕㄚ ㄌㄧˋ","細沙子和碎石塊。[例]大風吹起，路上的沙礫就到處飛揚。"]],"沮喪":[["ㄐㄩˇ ㄙㄤˋ","情緒低落、灰心喪志。[例]得知未被錄取的消息後，他臉上難掩沮喪之情。"]],"河川":[["ㄏㄜˊ ㄔㄨㄢ","大小河流的通稱。[例]中國的河川受地形影響，多為東西走向。"]],"河流":[["ㄏㄜˊ ㄌㄧㄡˊ","天然水流的統稱。[例]這條河流汙染嚴重，急需進行整治。"]],"河豚":[["ㄏㄜˊ ㄊㄨㄣˊ","動物名。脊椎動物亞門硬骨魚綱魨形目。口小腹大，無鱗，有棘刺，背淡蒼色，腹白色。受驚擾時會全身鼓脹、豎起棘刺以嚇敵。肉甚鮮美，但肝臟、皮膚等部位多有劇毒，食用時若處理不慎，往往致死。[例]在日本，領有合格執照的專業廚師，才能烹調河豚，以確保顧客的安全。　△豚魚　◎"]],"沸騰":[["ㄈㄟˋ ㄊㄥˊ","1.液體加熱至一定的溫度時，發生上湧汽化的現象。[例]國人習慣飲用加熱沸騰過的水。_x000D_\n2.喧噪、高漲。[例]人聲沸騰、熱血沸騰"]],"油垢":[["ㄧㄡˊ ㄍㄡˋ","含油的汙垢。[例]清洗廚房油垢，是年終大掃除中最費力的工作。"]],"油墨":[["ㄧㄡˊ ㄇㄛˋ","印刷所用的顏色油，黏性很強，主要是由亞麻仁油、桐油、樹脂、膠等加入各種顏料和鈷、錳、鉛等金屬鹽的乾燥劑製造而成。[例]翻閱報紙之後，要將兩手所沾的油墨洗乾淨。　△墨油"]],"油漬":[["ㄧㄡˊ ㄗˋ","物體上所沾染的油汙。[例]衣服上的油漬可以用去漬油洗淨。"]],"油炸":[["ㄧㄡˊ ㄓㄚˊ","利用煮沸的油使食物熟透。[例]年糕裹上麵粉後油炸，就成為美味可口的點心。"]],"油燈":[["ㄧㄡˊ ㄉㄥ","用香油、菜油等作燃料的小燈。[例]古人常使用油燈來照明。"]],"治理":[["ㄓˋ ㄌㄧˇ","1.統治、管理。[例]治理國家是千頭萬緒的工作。\n2.整治、修整。[例]歷代治理黃河者不知凡幾，但大都成效有限。"]],"治病":[["ㄓˋ ㄅㄧㄥˋ","醫療疾病。[例]醫生治病，常需精密的儀器輔助。"]],"治療":[["ㄓˋ ㄌㄧㄠˊ","醫治疾病。[例]經過醫生細心的治療，他的病情已經逐漸好轉了。"]],"沼澤":[["ㄓㄠˇ ㄗㄜˊ","水草茂密且樹木、灌木叢生的潮溼泥濘地。主要由於湖泊裡面的物質長期沉積，湖水越來越淺，湖底長滿苔蘚等植物而形成。[例]前面是一大片沼澤，既潮溼又泥濘，經過時要特別小心。"]],"沾染":[["ㄓㄢ ㄖㄢˇ","因接觸而被附著或受影響。[例]他自從交上壞朋友後，便沾染上吸毒的惡習。"]],"沿街":[["ㄧㄢˊ ㄐㄧㄝ","1.靠著街道。[例]她住在沿街的一棟公寓內。\n2.順著街道。[例]沿街一路走下去，就可以到達你要去的地方。"]],"沿襲":[["ㄧㄢˊ ㄒㄧˊ","依循舊例而不改變。[例]凡事要跟著時代走，不能一味沿襲老套。"]],"沿路":[["ㄧㄢˊ ㄌㄨˋ","一路上。[例]馬拉松賽跑的過程中，沿路都有加油打氣的民眾。"]],"沿途":[["ㄧㄢˊ ㄊㄨˊ","一路上。[例]陽明山花季時，從山下到山上，沿途櫻花盛開，美不勝收。"]],"泉湧":[["ㄑㄩㄢˊ ㄩㄥˇ","形容事物或靈感如泉水般湧出，源源不絕。[例]文思泉湧、淚如泉湧"]],"法令":[["ㄈㄚˇ ㄌㄧㄥˋ","法律條文或命令。[例]社會變遷快速，有些法令應隨時修改以順應時代需求。"]],"法子":[["ㄈㄚˊ ˙ㄗ","方法。[例]大家一起想想，有沒有什麼法子可以解決這個問題。"]],"法庭":[["ㄈㄚˇ ㄊㄧㄥˊ","法官審問及判決民事、刑事訴訟的場地、處所。[例]如果你真的不願意私下和解，那我們只有法庭上見了！"]],"法律":[["ㄈㄚˇ ㄌㄩˋ","經由特定成員共同討論制訂，可為大家共同遵守並具有約束懲治效率的法規條文。[例]各國的法律依其風俗民情的不同而有別。"]],"法規":[["ㄈㄚˇ ㄍㄨㄟ","因某種特定範圍、目的而制訂的規則條文。[例]行政法規"]],"泛舟":[["ㄈㄢˋ ㄓㄡ","乘船浮遊於水上。現多指乘橡皮艇順湍流而下的水上活動。[例]到秀姑巒溪泛舟是驚險刺激的水上活動。"]],"泡沫":[["ㄆㄠˋ ㄇㄛˋ","聚在一堆的許多小氣泡。[例]肥皂水經攪拌後會產生許多泡沫。"]],"泡泡":[["ㄆㄠ ㄆㄠ","形容物體寬大膨鬆。[例]泡泡褲、泡泡袖"],["ㄆㄠˋ ㄆㄠˋ","氣泡、水泡或泡狀的東西。[例]吹泡泡、起泡泡、泡泡浴"]],"泡湯":[["ㄆㄠˋ ㄊㄤ","比喻落空、報廢、沒有用。[例]這樣一來，那我們的計畫不就泡湯了嗎？"]],"泡菜":[["ㄆㄠˋ ㄘㄞˋ","一種用鹽水加酒、花椒、薑及辣椒等配料浸漬而成的生菜。[例]吃油膩食物時，若能配上一盤泡菜，十分爽口。"]],"波動":[["ㄅㄛ ㄉㄨㄥˋ","1.水波起伏動盪。[例]飛馳而過的快艇使得湖面波動不已。\n2.動盪、不穩定。[例]物價波動、情緒波動\n3.物理學上指物質某一點的振動，能漸次傳播到四周，產生週期相同的振動。如向靜止的水面投下石頭時，就會以落水點為中心，上下起伏向四方擴散開。[例]地震強度的測量，是視震源所發出震波的波動大小來判定的。"]],"波及":[["ㄅㄛ ㄐㄧˊ","水波擴散，及於四周。比喻有所影響、牽累。[例]地下爆竹工廠失火，波及到許多民宅。"]],"波折":[["ㄅㄛ ㄓㄜˊ","比喻事情的變化曲折。[例]經歷的波折愈多，成功的果實愈覺甘美。"]],"波浪":[["ㄅㄛ ㄌㄤˋ","江河湖海等因外力作用而在水面出現高低起伏的現象。[例]波浪滔天、波浪洶湧"]],"波濤":[["ㄅㄛ ㄊㄠˊ","1.大波浪。[例]颱風來襲時，海面上波濤洶湧，猶如萬馬奔騰。\n2.比喻人事的起伏變化。[例]情海起波濤"]],"波濤洶湧":[["ㄅㄛ ㄊㄠˊ ㄒㄩㄥ ㄩㄥˇ","1.形容波浪很大。[例]因颱風過境，海面上白浪掀天，波濤洶湧。\n2.比喻事情發展起伏變化大。[例]整個事件的發展，波濤洶湧，令人無法掌握。"]],"波紋":[["ㄅㄛ ㄨㄣˊ","水面微浪形成的紋理。[例]微風掠過，湖面泛起陣陣波紋。"]],"泥土":[["ㄋㄧˊ ㄊㄨˇ","土壤、泥地。[例]嘉南平原的泥土肥沃，適合栽種多種農作物。"]],"泥巴":[["ㄋㄧˊ ㄅㄚ","溼而黏的泥土。[例]他從小就愛玩泥巴，如今已成一位有名的雕塑家。"]],"泥沙":[["ㄋㄧˊ ㄕㄚ","細碎的泥粒。[例]地上的泥沙被一陣大風刮得到處紛飛。"]],"泥漿":[["ㄋㄧˊ ㄐㄧㄤ","泥土和水混合成的黏濁半流體。[例]在鄉下，時常可以看見水牛在泥漿裡打滾。"]],"泥濘":[["ㄋㄧˊ ㄋㄧㄥˋ","雨後水與土混雜而黏溼的樣子。[例]颱風過後，山路泥濘，行車須特別小心。"]],"注意":[["ㄓㄨˋ ㄧˋ","關注留意。[例]過馬路時，必須小心注意兩方來車。"]],"注重":[["ㄓㄨˋ ㄓㄨㄥˋ","特別看重。[例]隨著國民平均所得的提高，國人也越來越注重生活品質。"]],"泰然":[["ㄊㄞˋ ㄖㄢˊ","態度鎮定，神色自然。[例]他臨危不亂，泰然處之。"]],"泳池":[["ㄩㄥˇ ㄔˊ","供人游泳的水池。[例]救生員須在泳池邊隨時注意狀況。"]],"洗刷":[["ㄒㄧˇ ㄕㄨㄚ","1.洗滌刷淨。[例]一清早，爸爸便將車子洗刷得乾乾淨淨。\n2.洗除冤屈、恥辱。[例]他終於獲得平反，洗刷過去所蒙的冤屈。"]],"洗手間":[["ㄒㄧˇ ㄕㄡˇ ㄐㄧㄢ","供人洗手及大小解的地方。[例]公共場所大都設有洗手間，供人方便。　△廁所"]],"洗淨":[["ㄒㄧˇ ㄐㄧㄥˋ","清洗乾淨。[例]她用水將碗盤洗淨。"]],"洗澡":[["ㄒㄧˇ ㄗㄠˇ","用水清洗身體。[例]爸爸每天回家後都會先洗澡，再吃晚飯。"]],"津津樂道":[["ㄐㄧㄣ ㄐㄧㄣ ㄌㄜˋ ㄉㄠˋ","形容很有興味的談論。[例]當年小王見義勇為、捨身救人的事蹟，至今仍為眾人津津樂道。"]],"洪亮":[["ㄏㄨㄥˊ ㄌㄧㄤˋ","聲音大且響亮。[例]這嬰兒哭聲洪亮，看來非常健康。"]],"洪水":[["ㄏㄨㄥˊ ㄕㄨㄟˇ","氾濫成災的大水。[例]颱風來襲前應先疏通溝渠，以防洪水成災。"]],"洶洶":[["ㄒㄩㄥ ㄒㄩㄥ","形容氣勢盛大猛烈的樣子。[例]經過三年的蟄伏，他復出參加比賽，連戰皆捷，來勢洶洶。"]],"洶湧":[["ㄒㄩㄥ ㄩㄥˇ","1.水猛烈向上騰湧的樣子。[例]波濤洶湧\n2.形容聲勢盛大。[例]每當圖書館閱覽室一開放，群眾便洶湧而入選取好位置。"]],"活動":[["ㄏㄨㄛˊ ㄉㄨㄥˋ","1.運動。[例]他每天早晨都會到公園裡活動筋骨。_x000D_\n2.為某種目的而採取的行動。[例]聯誼活動、競選活動、社團活動_x000D_\n3.可拆卸、組裝或移動的。[例]活動車庫、活動道具、活動扳手"]],"活水":[["ㄏㄨㄛˊ ㄕㄨㄟˇ","有源頭常流動的水。[例]問渠那得清如許，為有源頭活水來。（宋．朱熹〈觀書有感〉詩二首之一）"]],"活潑":[["ㄏㄨㄛˊ ㄆㄛ","生動而不呆板。[例]她個性活潑，交遊廣闊。"]],"活生生":[["ㄏㄨㄛˊ ㄕㄥ ㄕㄥ","1.活的。[例]他大難不死，歷劫歸來，活生生地在眾人面前出現\n2.實際的、真實的。[例]這小說裡的離奇情節，竟活生生地發生在我們眼前！\n3.栩栩如生的樣子。[例]他善於人物畫，能夠把人物的神韻活生生地呈現出來\n4.活活的。[例]你再不改邪歸正，奶奶準會活生生被你氣死。"]],"活用":[["ㄏㄨㄛˊ ㄩㄥˋ","靈活運用。[例]讀書要能活用，千萬不可食古不化。"]],"活絡":[["ㄏㄨㄛˊ ㄌㄨㄛˋ","1.疏通血脈、筋骨。[例]活絡筋骨\n2.靈活、通達。[例]他的腦筋非常活絡，常有一些新點子。\n3.流通、有活力。[例]景氣轉佳使得房地產業等受到鼓舞，資金也開始活絡起來。"]],"派任":[["ㄆㄞˋ ㄖㄣˋ","由上級委任擔任某種職務。[例]他被公司派任為駐美商務代表。"]],"派遣":[["ㄆㄞˋ ㄑㄧㄢˇ","指派差遣。一般使用在上對下或組織機構對所屬人員。[例]這次上級派遣他到海外，接受兩年的訓練。"]],"流傳":[["ㄌㄧㄡˊ ㄔㄨㄢˊ","散布傳播。[例]許多古老而原始的神話傳說，至今仍在民間流傳。"]],"流失":[["ㄌㄧㄡˊ ㄕ","散失。[例]不肖業者濫墾濫伐，使得很多山坡地土壤嚴重流失。"]],"流星":[["ㄌㄧㄡˊ ㄒㄧㄥ","1.太空中的漂浮物進入地球大氣層後，與空氣摩擦燃燒發光，快速飛越天空，即形成流星。[例]流星的速度很快，一晃眼便看不見了。　△賊星\n2.比喻快速短暫。[例]人壽幾何？譬如流星！"]],"流水":[["ㄌㄧㄡˊ ㄕㄨㄟˇ","1.流動的水。[例]流水潺潺\n2.比喻如水流般連續不斷的情形。[例]流水席、流水年華"]],"流淌":[["ㄌㄧㄡˊ ㄊㄤˇ","流動。[例]每一次淚水流淌的經驗，都會是我們成長的養分。"]],"流瀉":[["ㄌㄧㄡˊ ㄒㄧㄝˋ","流散、傾瀉。[例]她拉開窗簾，讓屋內流瀉著輕柔的月光。"]],"流質":[["ㄌㄧㄡˊ ㄓˊ","液狀的物質。[例]有些體力虛弱的病人只能吃流質的食物。"]],"流逝":[["ㄌㄧㄡˊ ㄕˋ","如流水般逝去。[例]韶光流逝，良可痛惜。"]],"流連忘返":[["ㄌㄧㄡˊ ㄌㄧㄢˊ ㄨㄤˋ ㄈㄢˇ","貪戀沉迷於某一事物而忘了歸去。後形容徘徊、留戀而不忍離去。[例]這裡的明媚風光使他流連忘返。"]],"流量":[["ㄌㄧㄡˊ ㄌㄧㄤˋ","單位時間內物體通過某定點的數量。[例]車流量、水流量"]],"浩瀚":[["ㄏㄠˋ ㄏㄢˋ","1.水勢盛大的樣子。[例]看到大海的浩瀚，令人更加感到自己的渺小。\n2.廣大繁多的樣子。[例]他由浩瀚的典籍中，領略了中國文化的博大精深。"]],"浪漫":[["ㄌㄤˋ ㄇㄢˋ","富有詩意，充滿感性氣氛的。[例]各大飯店在情人節當天紛紛推出浪漫的燭光晚餐，以吸引顧客。"]],"浪潮":[["ㄌㄤˋ ㄔㄠˊ","1.海水漲落而形成的起伏波浪。[例]她赤足漫步在沙灘上，凝視著眼前一波波的浪潮而陷入回憶中。\n2.比喻一時形成，聲勢浩大的社會風氣或行動。[例]許多著名的音樂家提出了新理論及實際創作，掀起了音樂界革命的浪潮。"]],"浪濤":[["ㄌㄤˋ ㄊㄠˊ","巨大的波浪。[例]浪濤洶湧"]],"浪花":[["ㄌㄤˋ ㄏㄨㄚ","波浪衝擊岸邊而濺起的水花。[例]海岸邊的朵朵浪花，映照著滿天彩霞，構成一幅美麗的圖畫。"]],"浪費":[["ㄌㄤˋ ㄈㄟˋ","對財物、人力、時間等沒有節制或無益地耗費。[例]我們只有一個地球，不可再浪費有限的資源。"]],"浮泛":[["ㄈㄨˊ ㄈㄢˋ","虛浮而不切實際。[例]文意浮泛"]],"浮潛":[["ㄈㄨˊ ㄑㄧㄢˊ","一種水中活動。通常頭戴面鏡，不攜帶氧氣筒，在水面上浮游或淺潛，要換氣時，必須透過呼吸管或浮出水面。[例]浮潛是暑假非常熱門的休閒活動。"]],"浮現":[["ㄈㄨˊ ㄒㄧㄢˋ","顯現、湧現。[例]見到眼前的景象，十幾年前的往事一一浮現心頭。"]],"浮腫":[["ㄈㄨˊ ㄓㄨㄥˇ","虛腫、水腫。[例]她兩眼浮腫，顯然是剛哭過。"]],"浴室":[["ㄩˋ ㄕˋ","洗澡用的房間。[例]進出浴室要小心，以防滑倒！"]],"海參":[["ㄏㄞˇ ㄕㄣ","動物名。棘皮動物門海參綱，無脊椎動物。色黑，多肉刺，圓柱形，體柔軟，可食用。[例]海參具有高蛋白質、低膽固醇的特性，因而被許多人視為健康食品。"]],"海島":[["ㄏㄞˇ ㄉㄠˇ","突出海面的島嶼。[例]太平洋中海島星羅棋布。"]],"海拔":[["ㄏㄞˇ ㄅㄚˊ","陸地或山岳等高出平均海平面的垂直距離。[例]特有種的紅毛杜鵑，生長在高海拔山區，是臺灣珍貴的天然資源。"]],"海洋":[["ㄏㄞˇ ㄧㄤˊ","地球表面除陸地外的廣大鹹水水域。包括太平洋、大西洋、印度洋、地中海、北極海等，約占地球表面的百分之七十一。[例]海洋汙染日益嚴重，對海中生物的生存造成莫大的威脅。"]],"海浪":[["ㄏㄞˇ ㄌㄤˋ","海水受風吹、氣壓變化、海底地震、火山活動等外力作用的影響所產生的波浪。[例]海浪洶湧，非常壯觀。"]],"海港":[["ㄏㄞˇ ㄍㄤˇ","沿海供船隻停泊的港口。如旅順、大連、基隆等。[例]高雄是位於臺灣西南邊的一座海港。"]],"海灘":[["ㄏㄞˇ ㄊㄢ","泛稱海邊的沙地。[例]夏日的海灘常聚滿戲水的人潮。"]],"海獅":[["ㄏㄞˇ ㄕ","動物名。脊索動物門哺乳綱。分布於極地、溫帶或亞熱帶的海域裡。後鰭腳可以向前彎曲，能支撐起身體在陸地上行走或跑步，成年的雄海獅因頭頸部會長出美麗的鬃毛，好像雄獅子，故名「海獅」。"]],"海綿":[["ㄏㄞˇ ㄇㄧㄢˊ","1.多細胞動物中最原始的一類。體壁中有膠狀物，內含骨骼，用以支撐軀體；骨骼有針骨和海綿絲兩種，其中海綿絲可供洗滌用。最常見於淺海海域，呈褐色、紅色或綠色等。[例]海綿的幼體會依附其他生物或固著在其他岩礁上生活。\n2.一種以橡膠或塑料製成的多孔化學成品。吸水力強，彈性佳。[例]用沾水的海綿清洗髒玻璃，既省時省力又不致刮損玻璃表面。"]],"海葵":[["ㄏㄞˇ ㄎㄨㄟˊ","動物名。腔腸動物門。體軟，呈圓柱形，頂端叢生觸手，內含毒刺，可用來捕食生物。多生活於溫帶海域。　△菟葵"]],"海螺":[["ㄏㄞˇ ㄌㄨㄛˊ","動物名。軟體動物門腹足綱腹足目。屬大型卷貝。生活於海中，以海膽、海星、貝類等為主食。其殼可做號角或手工藝品。"]],"海豚":[["ㄏㄞˇ ㄊㄨㄣˊ","動物名。哺乳綱鯨目海豚科。長約二公尺，頭小，口尖，背部青黑色，腹部白色，前肢呈鰭狀，可用來保持平衡。以魚、蝦、烏賊等為主食。有很好的記憶力，能學習複雜的動作，是相當聰明的動物。[例]海洋公園的海豚很有靈性，深受遊客喜愛。　△海豬　◎◎"]],"海闊天空":[["ㄏㄞˇ ㄎㄨㄛˋ ㄊㄧㄢ ㄎㄨㄥ","1.形容天地遼闊而無邊際。[例]站在非洲大草原中，放眼望去，只見海闊天空，一望無際。\n2.比喻心胸開闊或心情開朗。[例]既然雙方損失不大，假如各退一步，豈不海闊天空？"]],"海鮮":[["ㄏㄞˇ ㄒㄧㄢ","產於海中可供食用的新鮮海產。[例]這家餐廳的海鮮料理，物美價廉，遠近馳名。　△海產"]],"海鷗":[["ㄏㄞˇ ㄡ","動物名。鳥綱鷸形目鷗科。廣泛分布於世界各海洋上空，體色以白色為主，頭、尾、背等呈黑褐色。嘴彎如鉤，趾間有蹼，擅長游泳及飛行。除了以魚、蛤蜊等海中生物為食物外，還會爭食漁民丟棄的食物，因此有海邊的清道夫之稱。[例]海鷗飛翔的美姿，與無懼狂風巨浪的毅力，不少作家寫下了讚美歌頌的作品。　◎"]],"浸泡":[["ㄐㄧㄣˋ ㄆㄠˋ","放在液體中泡。[例]太過油膩的碗盤，可先用熱水浸泡去除油漬再清洗，較易洗淨。"]],"浸溼":[["ㄐㄧㄣˋ ㄕ","因水分滲透而使物品潮溼。[例]我的衣褲全被汗水浸溼了，貼在身上很不舒服。"]],"浸潤":[["ㄐㄧㄣˋ ㄖㄨㄣˋ","1.沾潤、滋潤。[例]浸潤恩澤\n2.逐漸親熱、討好。[例]若是以利相交往，浸潤日久，必生是非。"]],"消失":[["ㄒㄧㄠ ㄕ","不見、不復存在。[例]那艘船漸行漸遠，終於消失在海的那一頭。"]],"消息":[["ㄒㄧㄠ ㄒㄧˊ","音信、訊息。[例]知道他考取公費留學的消息後，全家人都非常高興。"]],"消瘦":[["ㄒㄧㄠ ㄕㄡˋ","體貌消減瘦弱。[例]近來一場大病，使她豐腴的臉龐消瘦不少。"]],"消費":[["ㄒㄧㄠ ㄈㄟˋ","人類使用財物以滿足生活的需要。[例]為了鼓勵顧客消費，各百貨公司紛紛推出折扣品。"]],"消遣":[["ㄒㄧㄠ ㄑㄧㄢˇ","1.娛樂。[例]漫長的假期裡，你打算做何消遣？\n2.嘲笑戲弄。[例]他生性害羞，請不要再消遣他了。"]],"消除":[["ㄒㄧㄠ ㄔㄨˊ","排除、除去。[例]消除髒亂是大家共同的責任。"]],"涉及":[["ㄕㄜˋ ㄐㄧˊ","牽涉，關聯到。[例]這名嫌犯可能還涉及其他的搶案。"]],"涉獵":[["ㄕㄜˋ ㄌㄧㄝˋ","對學問、書籍或其他事物，只做粗淺的認識，而未深入鑽研。[例]他雖主修鋼琴但對傳統樂器亦涉獵極廣。"]],"涕淚":[["ㄊㄧˋ ㄌㄟˋ","鼻涕和眼淚。[例]看到電視中那幕母子重逢的感人鏡頭，令人不覺涕淚俱下。"]],"涕零":[["ㄊㄧˋ ㄌㄧㄥˊ","流淚。[例]感激涕零"]],"液體":[["ㄧㄝˋ ㄊㄧˇ","有一定體積，無一定形狀，而能流動的物體。如常溫下的水、油等。[例]液體燃料、液體電蚊香"]],"涼亭":[["ㄌㄧㄤˊ ㄊㄧㄥˊ","供行人休息或乘涼避雨的亭子。[例]走過一段上坡路後，我們在一處涼亭略作休息。"]],"涼快":[["ㄌㄧㄤˊ ㄎㄨㄞˋ","1.涼爽舒適。[例]一陣大雨過後，天氣變得涼快多了。\n\t\n2.形容穿著暴露。[例]由於文化背景的不同，西方女子的穿著，比我們涼快多了。\n\t\n3.比喻休息，不必插手某些事件。[例]這是別人家的家務事，我們還是到一邊涼快去吧！"]],"涼拌":[["ㄌㄧㄤˊ ㄅㄢˋ","用冷食菜餚加料拌和的調理方式。[例]涼拌竹筍、涼拌黃瓜"]],"涼爽":[["ㄌㄧㄤˊ ㄕㄨㄤˇ","清涼舒爽。[例]往常過了中秋，天氣就逐漸涼爽了。"]],"淋溼":[["ㄌㄧㄣˊ ㄕ","澆灑溼透。[例]一旦被雨淋溼，回家後要趕快擦乾身子，換乾淨衣服。"]],"淋雨":[["ㄌㄧㄣˊ ㄩˇ","被雨澆灑。[例]淋雨後很容易著涼感冒。"]],"淘氣":[["ㄊㄠˊ ㄑㄧˋ","頑皮、搗蛋。通常指孩童而言。[例]這個小孩雖然很淘氣，但腦筋卻非常靈活。"]],"淘汰":[["ㄊㄠˊ ㄊㄞˋ","經由選擇或競爭，剔除較低劣的人或物。[例]他因穿著和應對不得體，在面試時便被淘汰掉了。"]],"淚水":[["ㄌㄟˋ ㄕㄨㄟˇ","眼淚。[例]天然的淚水具有消毒、淨化、潤溼眼球的功能。"]],"淡化":[["ㄉㄢˋ ㄏㄨㄚˋ","1.減輕、減弱物質中的成分。[例]阿拉伯半島上臨海的國家多將海水淡化，作為日常的飲用水。\n2.事情採較不挑起注意或反作用的方式處理。[例]公司為免引起員工恐慌，刻意淡化這件意外。"]],"淡淡":[["ㄉㄢˋ ㄉㄢˋ","1.味道清淺。[例]這株蘭花散發出淡淡的清香。\n2.光線微弱迷茫的樣子。[例]他拉開窗簾，淡淡的月光射進屋內。\n3.態度冷漠、不熱情。[例]他對人總是淡淡的。"]],"淡雅":[["ㄉㄢˋ ㄧㄚˇ","清淡高雅。[例]這種香水味道淡雅，市場銷售情況很好。"]],"淪落":[["ㄌㄨㄣˊ ㄌㄨㄛˋ","1.陷落、墮入。[例]想當初他在股市風光一時，沒想到如今卻因違規交易，淪落為階下囚。\n2.流落、流離。[例]同是天涯淪落人，相逢何必曾相識。（唐．白居易〈琵琶行〉）"]],"淪陷":[["ㄌㄨㄣˊ ㄒㄧㄢˋ","喪失疆土。[例]國土淪陷，使得許多人無家可歸。"]],"深仇大恨":[["ㄕㄣ ㄔㄡˊ ㄉㄚˋ ㄏㄣˋ","形容極深、極大的仇恨。[例]你們又沒什麼深仇大恨，為什麼非得惡言相向不可？"]],"深刻":[["ㄕㄣ ㄎㄜˋ","1.深入內心，難以忘懷。[例]印象深刻、記憶深刻\n2.見解精闢透澈，含意深遠。[例]這位主講人發表如此深刻的講演，使與會者都十分感動。\n3.深切、切實。[例]經過這次的教訓，讓我們深刻的體認到健康的重要。"]],"深呼吸":[["ㄕㄣ ㄏㄨ ㄒㄧ","盡力吸入多量新鮮空氣，再呼出多量濁氣。[例]緊張時不妨做做深呼吸，可稍微舒緩不安的情緒。"]],"深奧":[["ㄕㄣ ㄠˋ","艱深。[例]這本書內容深奧難懂，所以銷路不很理想。"]],"深藏":[["ㄕㄣ ㄘㄤˊ","深深的隱藏。[例]這段甜美的回憶，將永遠深藏在我的心中。"]],"混亂":[["ㄏㄨㄣˋ ㄌㄨㄢˋ","雜亂沒有次序。[例]只要到了上、下班的尖峰時間，市區的交通就變得非常混亂。"]],"混合":[["ㄏㄨㄣˋ ㄏㄜˊ","摻雜調和。[例]他把柳橙、鳳梨、胡蘿蔔、芭樂和蜂蜜、水混合，打成綜合果汁。"]],"混水摸魚":[["ㄏㄨㄣˋ ㄕㄨㄟˇ ㄇㄛ ㄩˊ","原指在混濁的水中撈魚。後比喻趁混亂的時機撈取好處；或指工作不認真，藉機偷懶。[例]他做事總愛混水摸魚，逃避責任，後來大家都不願與他合作了。"]],"混淆":[["ㄏㄨㄣˋ ㄧㄠˊ","1.混雜而界限不明。[例]這段論述前後矛盾，顯示作者觀念混淆，思路不清。\n2.擾亂觀念、事物，使無法分辨。[例]混淆視聽"]],"淹水":[["ㄧㄢ ㄕㄨㄟˇ","被水覆蓋。[例]都市的排水系統若不健全，下雨時便容易淹水。"]],"淹沒":[["ㄧㄢ ㄇㄛˋ","淹埋、遮蓋。[例]豪雨成災，淹沒了許多農田。"]],"淺灘":[["ㄑㄧㄢˇ ㄊㄢ","河岸海邊水淺的地方。[例]每到夏天，便有很多人在淺灘上弄潮戲水。"]],"添加":[["ㄊㄧㄢ ㄐㄧㄚ","添入、增加。[例]在牙膏中添加少量的氟化物，有助於預防齲齒。"]],"添加物":[["ㄊㄧㄢ ㄐㄧㄚ ㄨˋ","為了某種用途而增加進去的東西。[例]糖果及零食中常含有色素、香料等添加物，對人體沒有什麼好處。"]],"添購":[["ㄊㄧㄢ ㄍㄡˋ","增加購置。[例]為了布置新居，他添購了不少家具。"]],"清掃":[["ㄑㄧㄥ ㄙㄠˇ","清理打掃。[例]本社區的居民常集體清掃街道，共同維護環境整潔。"]],"清明節":[["ㄑㄧㄥ ㄇㄧㄥˊ ㄐㄧㄝˊ","我國傳統的節日。國曆四月四、五或六日。清明原是節氣的名稱，後來為祭祖、掃墓的節日。民國二十四年政府定清明節為「民族掃墓節」。"]],"清晰":[["ㄑㄧㄥ ㄒㄧ","清楚明白。[例]口齒清晰、條理清晰、畫面清晰"]],"清楚":[["ㄑㄧㄥ ㄔㄨˇ","清晰明白。[例]對於童年往事，他依然記得非常清楚。"]],"清水":[["ㄑㄧㄥ ㄕㄨㄟˇ","清澈而不含雜質的水。[例]她將花插在盛有清水的花瓶中。"]],"清洗":[["ㄑㄧㄥ ㄒㄧˇ","清除、洗淨。[例]他將杯子放在水龍頭底下清洗乾淨。"]],"清涼":[["ㄑㄧㄥ ㄌㄧㄤˊ","涼爽。[例]夏天喝西瓜汁，既清涼又可口。"]],"清淡":[["ㄑㄧㄥ ㄉㄢˋ","1.食物只含少量油脂與鹽分。[例]飲食清淡可減少血管內的脂肪含量，預防高血壓、心臟病等的發生。\n2.不景氣、營業數額少。[例]連日大雨，這個觀光景點遊客寥寥無幾，特產店生意清淡。"]],"清淨":[["ㄑㄧㄥ ㄐㄧㄥˋ","乾淨。[例]這裡的泉水非常清淨甜美。"]],"清澈":[["ㄑㄧㄥ ㄔㄜˋ","澄淨透明。[例]那條溪清澈得可以看見水中的魚兒游來游去。"]],"清爽":[["ㄑㄧㄥ ㄕㄨㄤˇ","清新舒爽。[例]陣陣涼風迎面吹來，令人覺得十分清爽。"]],"清脆":[["ㄑㄧㄥ ㄘㄨㄟˋ","聲音清晰悅耳。[例]她的歌聲清脆嘹亮，十分動聽。"]],"清蒸":[["ㄑㄧㄥ ㄓㄥ","利用水的熱氣蒸熟食物的烹調法。[例]這條魚經過清蒸後，味道十分鮮美。"]],"清靜":[["ㄑㄧㄥ ㄐㄧㄥˋ","安靜不嘈雜。[例]弟弟整天愛吵鬧，總讓人耳根子不得清靜。"]],"減少":[["ㄐㄧㄢˇ ㄕㄠˇ","縮減降低、少於原來的數量。[例]報導指出，多運動可減少心血管疾病的發生。"]],"減弱":[["ㄐㄧㄢˇ ㄖㄨㄛˋ","程度上由大變小或由強轉弱。[例]隨著颱風離境，沿海風浪已經減弱。"]],"減法":[["ㄐㄧㄢˇ ㄈㄚˇ","一種數學運算方式。求兩個或兩個以上的數之差。[例]減法運算是基礎數學的教學項目之一。"]],"渡海":[["ㄉㄨˋ ㄏㄞˇ","過海。[例]他渡海來臺探訪老友，以慰思念之情。"]],"渡船頭":[["ㄉㄨˋ ㄔㄨㄢˊ ㄊㄡˊ","可停泊渡船，供客、貨上下的地方。[例]遊客可以在渡船頭搭船遊河，欣賞沿途美麗的河岸風光。"]],"測量":[["ㄘㄜˋ ㄌㄧㄤˊ","使用儀器或量具以測定速度、長度等數值，或有關地形、地物之高下、大小等狀態。[例]任何建築物的規劃設計，都必須先經過精密的測量，絲毫馬虎不得。"]],"測驗":[["ㄘㄜˋ ㄧㄢˋ","以一定標準測量能力或成績。[例]智力測驗、體力測驗"]],"港口":[["ㄍㄤˇ ㄎㄡˇ","在河、海岸邊設置碼頭，便於船隻停泊、乘客上下和貨物裝卸的地方。[例]這個港口的設備十分現代化。"]],"港灣":[["ㄍㄤˇ ㄨㄢ","港口的通稱。由自然條件或人工設施形成，便於船隻停泊，大多有防風、防浪的設備。[例]海上颱風警報一發布，外海的船隻紛紛進入港灣避風。"]],"港都":[["ㄍㄤˇ ㄉㄨ","因港口而繁榮起來的都市。[例]煙火節是這個港都年度最重要的慶典活動。"]],"渲染":[["ㄒㄩㄢˋ ㄖㄢˇ","1.國畫的一種用色技巧。以水墨或顏料，襯托物像，而形成陰陽向背的效果。[例]水墨畫常以渲染的手法，點出主題與背景的明暗分別。_x000D_\n2.比喻言詞、文字過度吹噓誇大。[例]媒體對事件的過度渲染，常會誤導民眾對真相的認知與了解。"]],"渴望":[["ㄎㄜˇ ㄨㄤˋ","非常希望、盼望。[例]他出國多年，十分渴望能早日回國。"]],"游泳":[["ㄧㄡˊ ㄩㄥˇ","一種體育運動。為人在水中靠自力漂浮，並以各種不同姿勢划水前進的水中運動。常用的游姿有捷泳、蛙泳、蝶泳、仰泳等。[例]游泳之前，應先做暖身體操。　◎"]],"游泳池":[["ㄧㄡˊ ㄩㄥˇ ㄔˊ","用人工開鑿，供人游泳的水池。[例]游泳池的水應定期消毒、更換，以確保衛生。"]],"游牧":[["ㄧㄡˊ ㄇㄨˋ","沒有一定的住所，將牛、馬、羊等牲口一邊移動，一邊飼養的粗放式畜牧，稱為「游牧」。有逐水草而居、山牧季移等二種形態。[例]沙漠地區雨量稀少，無法發展農業，人們就以游牧來適應環境。"]],"渺小":[["ㄇㄧㄠˇ ㄒㄧㄠˇ","微小。[例]面對浩瀚的宇宙，人類顯得很渺小。"]],"渺茫":[["ㄇㄧㄠˇ ㄇㄤˊ","1.景物遼闊無際，模糊不清的樣子。[例]湖上煙霧渺茫，朦朧中別有一番景色。\n2.事物的狀況不明而難以預料。[例]自從他出國後，音訊渺茫，不知近況如何？"]],"渾厚":[["ㄏㄨㄣˊ ㄏㄡˋ","飽滿雄厚。[例]筆力渾厚"]],"渾天儀":[["ㄏㄨㄣˋ ㄊㄧㄢ ㄧˊ","古代觀測天體運行的儀器。東漢張衡所製。"]],"渾水":[["ㄏㄨㄣˊ ㄕㄨㄟˇ","混濁不清的水。多比喻複雜、麻煩的處境。[例]看這情勢不太樂觀，我們還是別蹚這趟渾水吧！"]],"渾渾噩噩":[["ㄏㄨㄣˊ ㄏㄨㄣˊ ㄜˋ ㄜˋ","迷糊、不解事理。[例]他決定振作起來，不再渾渾噩噩過日子。"]],"渾濁":[["ㄏㄨㄣˊ ㄓㄨㄛˊ","汙濁不清澈。[例]花瓶裡的水有點渾濁，似乎應該換了。"]],"渾然不覺":[["ㄏㄨㄣˊ ㄖㄢˊ ㄅㄨˋ ㄐㄩㄝˊ","完全沒有察覺。[例]他專注在小說的情節中，都已過了吃飯時間，卻渾然不覺。"]],"渾身":[["ㄏㄨㄣˊ ㄕㄣ","全身。[例]他感冒了，早上起來覺得渾身無力。"]],"湊熱鬧":[["ㄘㄡˋ ㄖㄜˋ ㄋㄠˋ","1.參加熱鬧的事情。[例]他最喜歡湊熱鬧！\n2.形容給人添麻煩。[例]大家都忙得不得了，你卻偏在這個節骨眼兒上湊熱鬧！真無聊！"]],"湊錢":[["ㄘㄡˋ ㄑㄧㄢˊ","籌措、聚集錢財。[例]最近生意清淡，老闆只好湊錢來支付店面的租金。"]],"湍急":[["ㄊㄨㄢ ㄐㄧˊ","水勢急速。[例]颱風常常帶來豪雨，使得河水暴漲，水勢湍急。"]],"湖泊":[["ㄏㄨˊ ㄅㄛˊ","位在內陸具有相當面積和深度的積水。按成因可分為構造湖、火口湖、堰塞湖、冰川湖、岩溶湖、風蝕湖及人工湖。按湖泊與徑流關係，則可分為內陸湖及外流湖。按含鹽度，可分為淡水湖、微鹹水湖、鹹水湖和鹽湖。[例]裡海為全世界最大的內陸湖泊。"]],"湛藍":[["ㄓㄢˋ ㄌㄢˊ","深藍色。[例]望著眼前一片湛藍的海水，令人煩惱全消。"]],"湧現":[["ㄩㄥˇ ㄒㄧㄢˋ","如泉水般出現。[例]這一片美好的景象令他靈感湧現，創作出動人的音樂。"]],"湯匙":[["ㄊㄤ ㄔˊ","飲食時用來舀湯的器具。[例]小弟弟還不會拿筷子，所以吃飯時都用湯匙。　△調羹"]],"湯圓":[["ㄊㄤ ㄩㄢˊ","一種以糯米製成的食品。將糯米粉搓揉成圓糰狀，分有餡、無餡兩種。[例]民間習俗認為冬至吃過湯圓後，就算多一歲了。　△湯糰"]],"源源不絕":[["ㄩㄢˊ ㄩㄢˊ ㄅㄨˋ ㄐㄩㄝˊ","河流的源頭很遠，水流的長度很長。形容連續不斷。[例]源源不絕的靈感，使他很快就把這篇散文寫完了。"]],"準備":[["ㄓㄨㄣˇ ㄅㄟˋ","1.事先安排或籌劃。[例]事前有充分的準備，臨時才不會手忙腳亂。\n2.打算。[例]明天的宴會我不準備參加了。"]],"準確":[["ㄓㄨㄣˇ ㄑㄩㄝˋ","精密確實，沒有誤差。[例]計算帳目，必求準確無誤。"]],"溝通":[["ㄍㄡ ㄊㄨㄥ","彼此間意見的交流或疏通。[例]我們在開會時充分溝通意見。"]],"溪流":[["ㄒㄧ ㄌㄧㄡˊ","小水流或河流。[例]很多魚類只能棲息於清澈冷冽的溪流中。"]],"溪澗":[["ㄒㄧ ㄐㄧㄢˋ","兩山所夾的流水。[例]大雨過後，山中的溪澗漲滿了水。"]],"溪谷":[["ㄒㄧ ㄍㄨˇ","溪流的谷道。[例]山中的溪谷經常瀰漫著霧氣。"]],"溫和":[["ㄨㄣ ㄏㄜˊ","1.形容人的性情或態度平和溫順。[例]招待人員的態度溫和有禮，使大家都有賓至如歸的感覺。_x000D_\n2.不猛烈、不急劇的。[例]藥性溫和、氣候溫和"]],"溫度":[["ㄨㄣ ㄉㄨˋ","冷熱的程度。[例]寒流來襲，今天的溫度創下入冬以來的最低溫。"]],"溫度計":[["ㄨㄣ ㄉㄨˋ ㄐㄧˋ","用來測量冷熱程度的儀器。[例]拿溫度計量了體溫後，他才發現自己原來有點發燒。　△溫度表　◎"]],"溫暖":[["ㄨㄣ ㄋㄨㄢˇ","1.暖和。[例]春天來臨，氣候已漸漸溫暖了。\n2.溫馨。[例]過年時全家團圓吃年夜飯，感覺十分溫暖。"]],"溫水":[["ㄨㄣ ㄕㄨㄟˇ","不冷不熱、溫度適中的水。[例]冬天一到，溫水游泳池陸續開放了。"]],"溫泉":[["ㄨㄣ ㄑㄩㄢˊ","天然湧出，高於年平均氣溫的泉水。大抵由於地殼有裂隙，地下水滲入後受地熱影響而升高溫度。[例]一般人相信，洗溫泉不但可以消毒殺菌，甚至還能醫治疾病。　△湯泉、溫湯"]],"溫潤":[["ㄨㄣ ㄖㄨㄣˋ","溫和溼潤。[例]春天氣候溫潤，十分宜人。"]],"溫煦":[["ㄨㄣ ㄒㄩˇ","和暖。[例]此地氣候溫煦，四季如春。"]],"溫馨":[["ㄨㄣ ㄒㄧㄣ","親切溫暖。[例]現實的生活雖有挫折與艱辛，但同時也充滿著溫馨甜美。"]],"溶劑":[["ㄖㄨㄥˊ ㄐㄧˋ","可溶解其他溶質，而形成均勻混合物的液體。如水、酒精等。[例]松脂原為黃色固體，可溶解於酒精、二硫化碳等溶劑。　△溶媒"]],"溼地":[["ㄕ ㄉㄧˋ","指地下水面高，經常為水所淹沒的地帶。如沼澤、窪地、水塘等。可防止潮汐入侵內地、淨化沉澱水源、提供鳥類、水生、兩棲類及淡鹹水過渡植物的生長環境。關渡淡水河的出海口處即為溼地。[例]環保團體呼籲保護溼地，以讓水鳥有個棲息地。"]],"滋味":[["ㄗ ㄨㄟˋ","1.泛指食物酸、甜、苦、辣、鹹等味道。[例]這魚湯滋味鮮美，令人口齒留香。\n2.比喻感覺。[例]辛苦的努力有了收穫，令他嚐到成功的滋味。"]],"滋潤":[["ㄗ ㄖㄨㄣˋ","浸潤、潤澤。[例]草木受到春雨的滋潤，顯得生意盎然。"]],"滋養":[["ㄗ ㄧㄤˇ","滋補營養。[例]為了維持讀書的體力，他常吃些補品滋養身體。"]],"滑梯":[["ㄏㄨㄚˊ ㄊㄧ","一種一邊是梯子，一邊是斜的滑板，人從梯子上去，從平臺上順著斜板滑下的遊戲器具。[例]爺爺常帶妹妹到公園去溜滑梯。"]],"滑翔":[["ㄏㄨㄚˊ ㄒㄧㄤˊ","不依靠動力，藉氣流的升降在空中飄行。[例]利用滑翔翼在空中滑翔，滿足了人們想飛行的夢想。"]],"滑行":[["ㄏㄨㄚˊ ㄒㄧㄥˊ","滑動前進。[例]他喜歡溜冰時那種任意滑行的快感。"]],"滑鼠":[["ㄏㄨㄚˊ ㄕㄨˇ","一種可在電腦螢幕上顯示游標，隨意移動的小型手控裝置。[例]為了使電腦的操作更順手方便，現在滑鼠的設計越見精巧。"]],"滔天":[["ㄊㄠ ㄊㄧㄢ","漫天。形容極大。[例]滔天大罪"]],"滔滔":[["ㄊㄠ ㄊㄠ","1.水流滾滾不絕的樣子。[例]江水滔滔\n2.形容話多而連續不斷。[例]雄辯滔滔"]],"滔滔不絕":[["ㄊㄠ ㄊㄠ ㄅㄨˋ ㄐㄩㄝˊ","形容說話連續而不間斷。[例]姨媽滔滔不絕的敘述她在旅途中的奇遇，大家都聽得津津有味。"]],"滲入":[["ㄕㄣˋ ㄖㄨˋ","1.液體慢慢透進物體裡面。[例]煎魚前，她先將鹽抹在魚肉上，讓鹹味滲入肉裡。\n2.比喻思想或勢力逐漸侵入或影響。[例]他讀了這些書後，作者的思想已經滲入他的腦子裡。"]],"滲水":[["ㄕㄣˋ ㄕㄨㄟˇ","水由物體的縫隙透漏。[例]這房子年久失修，一下雨就會滲水進來。"]],"滲漏":[["ㄕㄣˋ ㄌㄡˋ","液體向下浸透或向上溢入。[例]海水從船底的裂縫滲漏進來。"]],"滴下":[["ㄉㄧ ㄒㄧㄚˋ","液體物質下落。[例]知道他不幸的遭遇後，她難過的滴下眼淚。"]],"滴滴答答":[["ㄉㄧ ㄉㄧ ㄉㄚ ㄉㄚ","狀聲詞。形容水聲、馬蹄聲或鐘擺左右晃盪的聲音。[例]牆上的古鐘已滴滴答答的陪我們度過數十年的歲月。"]],"滴答":[["ㄉㄧ ㄉㄚ","狀聲詞。形容水滴落下或鐘錶擺動的聲音。[例]牆上時鐘滴答滴答的響個不停。"]],"滴管":[["ㄉㄧ ㄍㄨㄢˇ","化學、醫學上的用具。滴管通常是用玻璃製成的中空玻璃管，一頭裝有橡皮套，將液體擠壓至另一頭的沒有調節作用的窄細通口，每次只滴出一滴，用來量取定量液體。"]],"滿分":[["ㄇㄢˇ ㄈㄣ","獲得全部的分數。[例]他幾乎每次考試都拿滿分。"]],"滿意":[["ㄇㄢˇ ㄧˋ","符合心意。[例]經理對我的表現相當滿意，因此決定升任我為部門的主管。"]],"滿懷":[["ㄇㄢˇ ㄏㄨㄞˊ","1.整個胸部。[例]我只顧看手上的資料，一出辦公室，就和他撞個滿懷。\n2.充滿胸中。[例]青年人對未來滿懷希望，才能產生努力向上的動力。"]],"漁港":[["ㄩˊ ㄍㄤˇ","供漁船停泊、進出，且具備便利漁業經營條件的港灣。[例]漁港多備有冷藏設備，可供魚貨存放。"]],"漂亮":[["ㄆㄧㄠˋ ㄌㄧㄤˋ","1.美麗、好看。[例]她真是一位人見人愛的漂亮姑娘。\n2.精彩、出色。[例]這件事你做得很漂亮。"]],"漂泊":[["ㄆㄧㄠ ㄅㄛˊ","比喻生活不固定，居無定所。[例]他長年漂泊海外，很少回家。"]],"漂流":[["ㄆㄧㄠ ㄌㄧㄡˊ","1.漂浮流動。[例]他在海上漂流了三天三夜，最後漂到一個無人的荒島上。\n2.比喻四處漂泊、居無定所。[例]自從雙親過世之後，他就過著漂流不定的生活。"]],"漂浮":[["ㄆㄧㄠ ㄈㄨˊ","在水面飄蕩浮流。[例]朵朵落花漂浮在水面上，隨波逐流。"]],"漂白":[["ㄆㄧㄠˇ ㄅㄞˊ","以藥劑浸洗布、紙等纖維品，使其變白或去漬。[例]這件衣服經過漂白後，就跟新的一樣。"]],"漆器":[["ㄑㄧ ㄑㄧˋ","一種表面塗裹多層漆料的手工藝品。漆上常以繪畫、雕刻、鑲嵌加以美化，色彩絢麗，紋飾優美動人，不怕水浸，能耐溫，可抗酸鹼腐蝕，內胎多以木材、苧麻做成。[例]脫胎漆器、剔紅漆器"]],"漆黑":[["ㄑㄧ ㄏㄟ","形容非常黑暗，沒有亮光。[例]停電後，房間裡一片漆黑，伸手不見五指。"]],"演化":[["ㄧㄢˇ ㄏㄨㄚˋ","1.推演變化。[例]事情演化成如此，實在出人意料。\n2.遺傳學上指生物種為了因應時空的嬗變，而在形態和生存形式上有異於其遠祖的現象。[例]從這張圖中可以看出人類演化的過程。"]],"演戲":[["ㄧㄢˇ ㄒㄧˋ","1.表演戲劇。[例]每年廟會時，村民都會請戲班子在廣場搭臺演戲。\n2.裝模作樣，用以欺瞞他人或取得信任。[例]別再演戲了，我才不會上當！"]],"演技":[["ㄧㄢˇ ㄐㄧˋ","表演的技術、手法。[例]他的演技精湛，刻劃角色入木三分。"]],"演算":[["ㄧㄢˇ ㄙㄨㄢˋ","練習計算。[例]老師要同學在黑板上演算數學習題。"]],"演練":[["ㄧㄢˇ ㄌㄧㄢˋ","按照計畫、步驟完整而仔細的練習。[例]他們一再的演練，希望將最好的成果呈現給觀眾。"]],"演說":[["ㄧㄢˇ ㄕㄨㄛ","向大眾講述自己對於某個問題的見解。[例]他到各地演說，均得到熱烈的回響。"]],"演講":[["ㄧㄢˇ ㄐㄧㄤˇ","向大眾講述自己對於某個問題的見解。[例]他應母校之邀回校演講。"]],"演變":[["ㄧㄢˇ ㄅㄧㄢˋ","事物在時間推移的過程中所產生的變化。[例]世事的演變往往出人意料之外。"]],"漠然":[["ㄇㄛˋ ㄖㄢˊ","冷漠不關心的樣子。[例]有人對世界熱心奉獻，也有人漠然不顧。"]],"漫山遍野":[["ㄇㄢˋ ㄕㄢ ㄅㄧㄢˋ ㄧㄝˇ","形容數目眾多，到處都是。[例]嘉義梅山每到冬季開滿漫山遍野的梅花，吸引了不少遊客。"]],"漫長":[["ㄇㄢˋ ㄔㄤˊ","特別長、長得看不到盡頭。[例]學習是條漫長的道路，既考驗耐心，也考驗毅力。"]],"漲價":[["ㄓㄤˇ ㄐㄧㄚˋ","物價上揚。[例]颱風過後，蔬菜水果馬上跟著漲價。"]],"漲潮":[["ㄓㄤˇ ㄔㄠˊ","由於太陽和月亮之間的引力作用，使得海洋水位上升的現象。[例]漲潮時千萬不可去游泳，以免發生危險。"]],"漸漸":[["ㄐㄧㄢˋ ㄐㄧㄢˋ","表示程度、數量等的逐步增減。[例]這個星期三開始，天氣會漸漸好轉，氣溫也會回升。"]],"漸進":[["ㄐㄧㄢˋ ㄐㄧㄣˋ","逐步的前進或發展。[例]循序漸進"]],"潑水":[["ㄆㄛ ㄕㄨㄟˇ","灑水。[例]掃地前可先潑水，以防灰塵飛揚。"]],"潑灑":[["ㄆㄛ ㄙㄚˇ","澆、灑。[例]把汙水潑灑到街上，是不道德的行為。"]],"潔白":[["ㄐㄧㄝˊ ㄅㄞˊ","乾淨清白。[例]她穿了一身潔白的衣服，看起來像天女下凡。"]],"潛入":[["ㄑㄧㄢˊ ㄖㄨˋ","暗中侵入。[例]他潛入敵後從事間諜工作。"]],"潛水":[["ㄑㄧㄢˊ ㄕㄨㄟˇ","一種戶外活動。指人進入水面以下潛游。潛水分為浮潛和深潛兩種。浮潛時，潛水者只需戴蛙鏡、穿蛙鞋，加配一根呼吸管即可。因潛水者必須不停的浮上水面換氣，只能潛到九到十二公尺深，一分鐘左右就要回到水面。深潛時，要穿蛙鞋、潛水衣、戴蛙鏡、背空氣筒及腰配墜重腰帶。"]],"潤飾":[["ㄖㄨㄣˋ ㄕˋ","潤色修飾。[例]這篇文章架構不錯，文辭稍加潤飾後，一定是佳作。"]],"潮汐":[["ㄔㄠˊ ㄒㄧˋ","海水受日、月引力作用而發生的週期性漲落現象。白天發生的稱「潮」，夜晚發生的稱「汐」，平均每隔十二小時二十五分漲落一次。[例]潮汐具有規則性，但有時也會受風、浪、氣壓等影響而產生變化。"]],"潺潺":[["ㄔㄢˊ ㄔㄢˊ","狀聲詞。形容流水聲。[例]山谷裡溪水潺潺，顯得分外寧靜。"]],"澄明":[["ㄔㄥˊ ㄇㄧㄥˊ","清澈明亮。[例]靈臺澄明，洞察世情。"]],"澄清":[["ㄉㄥˋ ㄑㄧㄥ","經由過濾，將水中雜質沉澱，使其清澈。[例]明礬有殺菌及消毒的功效，可用來澄清水質。"],["ㄔㄥˊ ㄑㄧㄥ","1.清澈、清亮。[例]湖裡的水雖然澄清，但仍有些病菌，不可直接飲用。\n\t\n2.把事情弄清楚明白。[例]澄清誤會"]],"澄澈":[["ㄔㄥˊ ㄔㄜˋ","清澈、明亮。[例]這一泓澄澈的湖水，更增添了山林的靈秀之氣。"]],"澆水":[["ㄐㄧㄠ ㄕㄨㄟˇ","以水灌溉。[例]這些花需要每天澆水，才不致於枯死。"]],"澆灌":[["ㄐㄧㄠ ㄍㄨㄢˋ","澆水、灌溉。[例]種植農作物一定要按時澆灌，才能有好的收成。"]],"澎湃":[["ㄆㄥ ㄆㄞˋ","1.波濤互相衝擊的聲音或氣勢。[例]波濤澎湃、洶湧澎湃_x000D_\n2.引申有聲勢浩大，氣勢壯闊之意。[例]思湧澎湃、熱情澎湃"]],"澎湖群島":[["ㄆㄥˊ ㄏㄨˊ ㄑㄩㄣˊ ㄉㄠˇ","位於臺灣海峽上的群島，由90個大小島嶼組成，總面積約128平方公里，其中以澎湖本島面積最大。軍事地位重要，漁業為重要的產業。"]],"激動":[["ㄐㄧ ㄉㄨㄥˋ","受刺激而情緒高昂衝動。[例]當她聽到自己的作品獲獎時，情緒非常激動。"]],"激勵":[["ㄐㄧ ㄌㄧˋ","激發、鼓勵。[例]激勵人心"]],"激昂":[["ㄐㄧ ㄤˊ","形容情緒激越昂揚。[例]參加愛國歌曲比賽的學生，個個都情緒激昂、歌聲嘹亮。"]],"激發":[["ㄐㄧ ㄈㄚ","刺激使引發反應。[例]老師在課堂上運用各種方式以激發學生的學習興趣。"]],"濃密":[["ㄋㄨㄥˊ ㄇㄧˋ","濃厚茂密。[例]這座濃密的森林，給人陰森的感覺。"]],"濃湯":[["ㄋㄨㄥˊ ㄊㄤ","汁液濃稠的湯。[例]玉米濃湯、蔬菜濃湯"]],"濃郁":[["ㄋㄨㄥˊ ㄩˋ","香氣濃烈。[例]這束花不但顏色鮮麗，而且香味濃郁。"]],"濃霧":[["ㄋㄨㄥˊ ㄨˋ","稠密的霧。[例]根據路況報導，高速公路林口路段有濃霧瀰漫，請駕駛人行經該地時小心駕駛。"]],"濟助":[["ㄐㄧˋ ㄓㄨˋ","接濟幫助。[例]他常濟助貧寒學生，幫助他們完成學業。"]],"濟貧":[["ㄐㄧˋ ㄆㄧㄣˊ","救助貧困的人。[例]劫富濟貧"]],"濾心":[["ㄌㄩˋ ㄒㄧㄣ","一種可以過濾水中雜質、汙泥的裝置。淨水器、飲水機等皆有此裝置，一般由綿紗或活性碳組成。需視水質狀況定期清洗或更換，以確保濾淨效果。[例]飲水機的水質似乎不太純淨，應該更換濾心了。"]],"瀏海":[["ㄌㄧㄡˊ ㄏㄞˇ","垂在額前的短髮。[例]她的額前垂著短短的瀏海，看起來非常俏麗。"]],"瀏覽":[["ㄌㄧㄡˊ ㄌㄢˇ","隨意看看。[例]瀏覽雜誌、四處瀏覽"]],"瀑布":[["ㄆㄨˋ ㄅㄨˋ","從高處直瀉而下的水流，遠望似布匹垂落。如尼加拉大瀑布。[例]遠遠望去，瀑布好似一條白練懸掛在山崖前。"]],"瀕危":[["ㄅㄧㄣ ㄨㄟˊ","接近危險的境地。多指人病危將死，或物種即將滅絕。[例]病重瀕危、瀕危物種"]],"瀰漫":[["ㄇㄧˊ ㄇㄢˋ","遍布、滿布。[例]戰雲瀰漫、煙霧瀰漫"]],"灌救":[["ㄍㄨㄢˋ ㄐㄧㄡˋ","1.用水澆滅火苗，平息火災。[例]這場大火在消防人員全力灌救之下，終於被撲滅了。\n2.一種用藥水灌入病人的腸胃，使其能排出有害物質，脫離危險的救治方法。[例]他誤食農藥，醫生與護士正忙著灌救。"]],"灌水":[["ㄍㄨㄢˋ ㄕㄨㄟˇ","1.將水注入物體中。[例]當消費者發現這位商人所販賣的豬肉經過灌水處理，紛紛要求賠償。\n2.利用不正當的方法改變事物的質感或重量等。引申為膨脹或虛偽不實。[例]這筆工程款項被認為有灌水的嫌疑，有關單位正著手調查中。"]],"灌溉":[["ㄍㄨㄢˋ ㄍㄞˋ","用人為方法引水澆灌植物、田地，以利生長。[例]嘉南大圳灌溉的區域涵蓋雲林、嘉義、臺南等縣市。"]],"灌籃":[["ㄍㄨㄢˋ ㄌㄢˊ","在籃球比賽中，球員於籃下高躍而起，以雙手或單手直接將球扣入籃框內的動作。[例]球賽時，球員一記漂亮的灌籃，往往會贏得滿場的喝采。"]],"灌醉":[["ㄍㄨㄢˋ ㄗㄨㄟˋ","勉強別人喝酒以致於酒醉。"]],"灑掃":[["ㄙㄚˇ ㄙㄠˇ","灑水掃地。[例]新年將到，弟妹們也都提著水桶、拿起掃帚，幫忙媽媽灑掃庭院。"]],"灑水":[["ㄙㄚˇ ㄕㄨㄟˇ","把水散潑在地面。[例]在地面上灑水，可避免塵土飛揚。"]],"火坑":[["ㄏㄨㄛˇ ㄎㄥ","1.比喻非常悲慘痛苦的環境。[例]明明知道那是火坑，我們怎忍心讓他去跳！_x000D_\n2.比喻妓院。"]],"火柴":[["ㄏㄨㄛˇ ㄔㄞˊ","一端蘸有磷、硫等易燃物品的細小木條。可用於摩擦生火。[例]早年火柴為民生取火的必需品，現已被打火機及高科技產品所取代。"]],"火焰":[["ㄏㄨㄛˇ ㄧㄢˋ","燃燒時發出的光焰。[例]國慶煙火的火焰照亮整個淡水河的夜空。"]],"火爆":[["ㄏㄨㄛˇ ㄅㄠˋ","1.急躁、暴躁。[例]火爆脾氣\n2.激烈，充滿火藥味。[例]場面火爆、氣氛火爆"]],"火紅":[["ㄏㄨㄛˇ ㄏㄨㄥˊ","像火一樣紅的顏色。[例]她穿了一件火紅的洋裝，相當搶眼。"]],"火車":[["ㄏㄨㄛˇ ㄔㄜ","泛指行駛於鐵路上的列車。因為最初是藉著火力產生蒸氣以牽引車廂，故稱為「火車」。目前多已電氣化。[例]逢年過節時，搭乘火車返鄉的人特別多。　◎◎"]],"火鍋":[["ㄏㄨㄛˇ ㄍㄨㄛ","1.一種鍋與爐合為一體的烹飪器具。[例]媽媽上街買了一個新火鍋，打算除夕圍爐時拿來使用。\n2.在沸湯中加入各種菜餚，可邊煮邊吃的一種烹飪方式。亦指用火鍋煮的菜餚。[例]冬天裡大家常圍著桌子吃火鍋，其樂融融。"]],"灰塵":[["ㄏㄨㄟ ㄔㄣˊ","塵土、塵埃。[例]這本書因為不常使用，所以蒙上了一層厚厚的灰塵。"]],"灰暗":[["ㄏㄨㄟ ㄢˋ","1.暗淡、不明亮。[例]天色灰暗\n2.艱難、不順利。[例]我們應該攜手互勉，共度當前的灰暗期。"]],"灰色":[["ㄏㄨㄟ ㄙㄜˋ","1.介於黑、白之間的顏色。[例]他今天穿的是灰色的襯衫、藍色的牛仔褲。\n2.比喻態度消極或志氣消沉。[例]這位作家的小說經常帶點灰色，實與他的生活背景有關。"]],"災難":[["ㄗㄞ ㄋㄢˋ","自然或人為的禍害。[例]古代傳說當彗星出現時，將有災難發生。"]],"炎夏":[["ㄧㄢˊ ㄒㄧㄚˋ","炎熱的夏天。[例]炎夏裡能在清涼的水中游泳，真是莫大的享受。"]],"炎熱":[["ㄧㄢˊ ㄖㄜˋ","氣候酷熱。[例]今年夏天特別炎熱，冷氣機因而銷售量大增。"]],"炒作":[["ㄔㄠˇ ㄗㄨㄛˋ","刻意以人為操作來製造某種效果，以便達成目的。[例]炒作股票、炒作新聞"]],"炒菜":[["ㄔㄠˇ ㄘㄞˋ","1.用油加佐料炒製菜餚。湯汁較少，有別於熬菜。[例]炒菜時放一點肉絲，味道會更鮮美。\n\t\n2.烹調食物。[例]他不但會讀書，炒菜功夫更是一流。"]],"炒飯":[["ㄔㄠˇ ㄈㄢˋ","用油及佐料炒製的米飯。[例]離家在外，我十分懷念媽媽拿手的炒飯，簡單又美味。"]],"炙熱":[["ㄓˋ ㄖㄜˋ","炎熱、酷熱。[例]在炙熱的夏天裡，游泳池、海邊經常聚集了大批戲水的人潮。"]],"炫耀":[["ㄒㄩㄢˋ ㄧㄠˋ","1.誇耀、誇顯。[例]他常把年輕時候在田徑場上的輝煌紀錄，拿出來炫耀、吹噓。\n2.光芒燦爛耀眼的樣子。[例]營火晚會上，火光炫耀，大家的臉上都充滿了愉快的笑容。"]],"炮兵":[["ㄆㄠˋ ㄅㄧㄥ","一種火力支援兵種，為陸軍地面火力之骨幹。具有核子、非核子、生物及化學戰狀況下作戰的能力，可分為野戰炮兵與防空炮兵。[例]明日下午二點開始進攻，炮兵先行炸射，至二點五十分停止。"]],"炮彈":[["ㄆㄠˋ ㄉㄢˋ","以炮來發射的彈藥。由彈頭、藥筒、引信、發射藥、底火等構成。依其用途可分為穿甲彈、爆破彈、燃燒彈、煙幕彈等。[例]八二三炮戰時，金門幾乎每寸土地都曾被炮彈炸射過。"]],"炮竹":[["ㄆㄠˋ ㄓㄨˊ","→爆竹"]],"炮製":[["ㄆㄠˊ ㄓˋ","用火煉藥，可使藥物增強療效，減低毒性，易於保存、使用。[例]古法炮製、如法炮製"]],"炸彈":[["ㄓㄚˋ ㄉㄢˋ","一種爆炸性炮彈武器。由彈體、安定器、炸藥及引信等組成。分炮用、手用、飛機用三種，一般由飛機投擲。[例]我軍計劃在敵區上空投擲炸彈，以破壞其戰備。"]],"為什麼":[["ㄨㄟˋ ㄕㄣˊ ˙ㄇㄜ","詢問目的或原因的疑問詞。[例]有話好說嘛！為什麼動手打人？　△為甚麼"]],"為何":[["ㄨㄟˋ ㄏㄜˊ","為什麼。[例]情勢為何轉變得如此之快？"]],"為難":[["ㄨㄟˊ ㄋㄢˊ","1.感到苦惱或難以處置。[例]你這個要求，真叫我為難！\n2.作對、刁難。[例]他已經盡力，大家就別再為難他了。"]],"烈焰":[["ㄌㄧㄝˋ ㄧㄢˋ","熾熱、猛烈的火焰。[例]阿美族人圍著熊熊烈焰，歡愉的跳著豐年舞。"]],"烈酒":[["ㄌㄧㄝˋ ㄐㄧㄡˇ","酒精濃度較高，作用強烈的酒。[例]狂飲烈酒後的宿醉，令人頭痛欲裂，輾轉難眠。"]],"烏雲":[["ㄨ ㄩㄣˊ","濃灰色的雲。[例]天空烏雲密布，恐怕快要下雨了。"]],"烏雲密布":[["ㄨ ㄩㄣˊ ㄇㄧˋ ㄅㄨˋ","黑雲布滿天空。形容天氣陰霾。[例]天空中烏雲密布，頃刻之間，大雨傾盆而下。"]],"烏鴉":[["ㄨ ㄧㄚ","動物名。脊椎動物鳥綱雀形目鴉科。體長尺餘，嘴大且直。全身黑色，帶有綠色光澤。趾具鉤爪，警覺性高，以穀物、果實、昆蟲、動物腐屍為食物。多棲息於城市近郊或山區高樹。[例]一般人認為烏鴉飛臨屋頂鳴叫是不吉祥的預兆。　◎"]],"烏黑":[["ㄨ ㄏㄟ","純黑。[例]她有一雙烏黑動人的眼睛。"]],"烘乾":[["ㄏㄨㄥ ㄍㄢ","以火或高溫烤乾。[例]連續幾天都在下雨，他只好用烘乾機烘乾衣物。"]],"烘托":[["ㄏㄨㄥ ㄊㄨㄛ","從周圍或旁邊渲染，使主體或重點更加顯明。[例]這齣戲因為配角的烘托，使主角形象更為鮮明。"]],"烘烤":[["ㄏㄨㄥ ㄎㄠˇ","將物體直接置於熱源處或以高溫乾烤。[例]他們把肉片放在網架上烘烤成肉乾。"]],"烤爐":[["ㄎㄠˇ ㄌㄨˊ","用來烘烤食物的爐子。[例]這隻剛從烤爐端出來的火雞，香氣四溢，令人垂涎三尺。"]],"烤鴨":[["ㄎㄠˇ ㄧㄚ","將鴨子處理乾淨後，加調味料懸在火上燻烤而成的食物。[例]北平烤鴨　△燒鴨子"]],"焚化":[["ㄈㄣˊ ㄏㄨㄚˋ","燃燒物體使它化為灰燼。[例]病死豬應予以焚化，以免流入市場。"]],"焚燒":[["ㄈㄣˊ ㄕㄠ","燃燒。[例]在大火焚燒下，數間木屋頃刻化為灰燼。"]],"焚風":[["ㄈㄣˊ ㄈㄥ","暖溼空氣在迎風面受山勢阻擋而上升，凝結成雲後降雨，氣流在背風面下降時所形成熱且乾燥的風。[例]焚風的出現會使草木枯萎，甚至引起森林火災。"]],"無傷大雅":[["ㄨˊ ㄕㄤ ㄉㄚˋ ㄧㄚˇ","對事物的整體性沒有什麼妨害。[例]開玩笑也要有分寸，總要無傷大雅才好。"]],"無力":[["ㄨˊ ㄌㄧˋ","1.沒有力氣。[例]有氣無力、渾身無力\n2.沒有能力。[例]他欠那麼多錢，我也無力幫忙。"]],"無垠":[["ㄨˊ ㄧㄣˊ","遙遠而沒有邊際。[例]一望無垠、廣漠無垠"]],"無奈":[["ㄨˊ ㄋㄞˋ","無可奈何、沒有辦法。[例]她倉卒中做此決定並非自願而是出於無奈。"]],"無孔不入":[["ㄨˊ ㄎㄨㄥˇ ㄅㄨˋ ㄖㄨˋ","無所不到，比喻利用一切的機會。[例]病菌是無孔不入的，平日須多注意飲食、環境衛生。"]],"無幾":[["ㄨˊ ㄐㄧˇ","很少、不多。[例]所剩無幾、寥寥無幾"]],"無影無蹤":[["ㄨˊ ㄧㄥˇ ㄨˊ ㄗㄨㄥ","消逝得沒有蹤跡。[例]經過老師的開導，我心中的疑慮，便消失得無影無蹤了。"]],"無悔":[["ㄨˊ ㄏㄨㄟˇ","沒有後悔。[例]無怨無悔"]],"無情":[["ㄨˊ ㄑㄧㄥˊ","1.沒有感情。[例]他不是個無情的人，絕不會見死不救的。\n2.不留情面。[例]翻臉無情、水火無情"]],"無憾":[["ㄨˊ ㄏㄢˋ","沒有遺憾。[例]死而無憾"]],"無懈可擊":[["ㄨˊ ㄒㄧㄝˋ ㄎㄜˇ ㄐㄧˊ","沒有任何缺點可讓人指摘或挑剔。[例]這計畫十分嚴謹周密，簡直無懈可擊。"]],"無所謂":[["ㄨˊ ㄙㄨㄛˇ ㄨㄟˋ","1.沒關係，不在意。[例]他為了達成理想，縱使夜以繼日的工作也無所謂。\n2.談不上。[例]這個問題見仁見智，無所謂對錯。"]],"無拘無束":[["ㄨˊ ㄐㄩ ㄨˊ ㄕㄨˋ","自由而不受約束。[例]小時候曾夢想，自己有朝一日能像飛鳥一樣，在天空無拘無束的翱翔。"]],"無法":[["ㄨˊ ㄈㄚˇ","1.任意作惡，完全不顧法律綱紀。[例]無法無天\n2.沒有辦法、不能夠。[例]幸虧及時急救得當，若再延誤送醫就無法挽救了。"]],"無涯":[["ㄨˊ ㄧㄚˊ","沒有邊際。[例]學海無涯，唯勤是岸。"]],"無濟於事":[["ㄨˊ ㄐㄧˋ ㄩˊ ㄕˋ","對事情沒有任何幫助。[例]事已至此，後悔是無濟於事的。"]],"無理取鬧":[["ㄨˊ ㄌㄧˇ ㄑㄩˇ ㄋㄠˋ","比喻不合情理的吵鬧或故意的搗亂。語本唐．韓愈〈答柳柳州食蝦蟆〉詩。[例]小弟弟躺在地上無理取鬧惹得母親更加生氣。"]],"無私":[["ㄨˊ ㄙ","公正不偏私。[例]大公無私、鐵面無私"]],"無聊":[["ㄨˊ ㄌㄧㄠˊ","1.煩悶、精神空虛，沒有依賴寄託。[例]周而復始，一成不變的生活常會令人感到人生很無聊。\n2.形容沒有意義的言語舉止。[例]捉弄別人是很無聊的舉動。"]],"無論":[["ㄨˊ ㄌㄨㄣˋ","不論、不管。[例]無論結果好壞與否，我都樂於接受。"]],"無謂":[["ㄨˊ ㄨㄟˋ","沒有意義、沒有道理。[例]大家不應把時間浪費在無謂的爭辯上。"]],"無限":[["ㄨˊ ㄒㄧㄢˋ","沒有窮盡。[例]春到人間，大地展現無限生機。"]],"無須":[["ㄨˊ ㄒㄩ","不必、不用。[例]吉人自有天相，我們對他的成敗無須過於擔心。"]],"焦急":[["ㄐㄧㄠ ㄐㄧˊ","焦慮著急。[例]火車快開了，同伴卻還沒來，真令人焦急。"]],"焦慮":[["ㄐㄧㄠ ㄌㄩˋ","由緊張、不安、焦急、憂慮、擔心、恐懼等感受交織而成的複雜情緒狀態。[例]我只要一想到要面對眾人演講，心裡便感到十分焦慮。"]],"焦炭":[["ㄐㄧㄠ ㄊㄢˋ","由煙煤碳化而成的灰色燃料。質硬，多孔，含碳量約百分之八十。[例]焦炭燃燒時產生的熱度很高，可供冶鐵鍊鋼之用。　△焦煤"]],"焦躁":[["ㄐㄧㄠ ㄗㄠˋ","焦急煩躁。[例]飢餓的老虎樣子顯得異常焦躁。"]],"然後":[["ㄖㄢˊ ㄏㄡˋ","表示接某種動作或情況之後。[例]事先研究一下，然後再考慮怎麼去做。"]],"煉鐵":[["ㄌㄧㄢˋ ㄊㄧㄝˇ","將鐵礦石、焦碳及石灰石裝入鼓風爐中，高溫燒煉，使鐵和礦石分離而得純鐵的方法。[例]煉鐵所產生的爐渣，可再加工製成水泥。"]],"煎熬":[["ㄐㄧㄢ ㄠˊ","內心受折磨而焦灼痛苦。[例]歹徒禁不住良心的煎熬，終於向警方坦承犯行。"]],"煙囪":[["ㄧㄢ ㄘㄨㄥ","爐灶或鍋爐用以排煙的長管。[例]那家工廠的煙囪冒著黑煙，汙染空氣，因而遭到取締。　△煙突、煙筒"]],"煙火":[["ㄧㄢ ㄏㄨㄛˇ","1.煮飯的炊煙和柴火。[例]她看起來超凡脫俗，像是不食人間煙火的仙子。\n2.一種以火硝為主，並摻雜其他藥物製成的物品。燃燒時噴射出各種變幻燦爛的形狀，供遊戲觀賞之用。[例]黑漆漆的天空，被燃燒的煙火點綴得光明燦爛。"]],"煙霧":[["ㄧㄢ ㄨˋ","1.自然界的水氣凝聚而成的雲霧。[例]這座湖終年煙霧繚繞，具有一股神祕感。\n2.燃燒所造成的火煙。[例]那裡煙霧瀰漫，可能發生火災了！"]],"煞住":[["ㄕㄚ ㄓㄨˋ","止住、收住。[例]幸好他及時煞住這項合作計畫，才未使公司蒙受重大損失。"]],"煞星":[["ㄕㄚˋ ㄒㄧㄥ","凶戾的鬼神。多以喻指極為暴惡的人。[例]在街坊鄰居眼裡，他是人見人怕的煞星。"]],"煞有介事":[["ㄕㄚˋ ㄧㄡˇ ㄐㄧㄝˋ ㄕˋ","真有這麼一回事似的。[例]他煞有介事的描述半夜撞鬼的情形，使大家聽了毛骨聳然。"]],"煞費苦心":[["ㄕㄚˋ ㄈㄟˋ ㄎㄨˇ ㄒㄧㄣ","極費心思。[例]為了把這個晚會辦好，他真是煞費苦心。"]],"煞車":[["ㄕㄚ ㄔㄜ","1.減緩或停止車輛、機器運動。[例]他因煞車不及，撞到前面的車子。\n2.減緩或停止車輛、機器運動的裝置。[例]根據警方調查，這起車禍係因煞車失靈所致。"]],"照亮":[["ㄓㄠˋ ㄌㄧㄤˋ","1.照射得十分明亮。[例]煙火照亮了整個天空。\n2.比喻使黑暗化為明亮。[例]母親的慈暉照亮了我們的人生。"]],"照射":[["ㄓㄠˋ ㄕㄜˋ","光線照耀投射在物體上。[例]這些鑽石在燈光的照射下，更顯得耀眼晶亮。"]],"照拂":[["ㄓㄠˋ ㄈㄨˊ","照顧、關懷。[例]母親細心的照拂我們，將我們養大成人。"]],"照顧":[["ㄓㄠˋ ㄍㄨˋ","1.照料、看顧、幫助。[例]他非常乖巧懂事，從小就幫忙爸媽照顧弟弟和妹妹。\n\t\n2.商店中指顧客前來購買的意思。[例]本店平日多虧各位的照顧，才能有今天的局面。"]],"煩心":[["ㄈㄢˊ ㄒㄧㄣ","煩擾心緒。[例]近來煩心的事太多了，害得我吃不下、睡不著。"]],"煩忙":[["ㄈㄢˊ ㄇㄤˊ","事情煩多而忙碌。[例]他近來工作煩忙，無暇他顧。"]],"煩悶":[["ㄈㄢˊ ㄇㄣˋ","心中鬱悶不快活。[例]問題接踵而來，讓她感到十分煩悶。"]],"煩惱":[["ㄈㄢˊ ㄋㄠˇ","1.情緒愁悶而不快活。[例]令人煩惱的事情難免，我們得看開點！\n2.煩悶而不快活的情緒。[例]知足常樂，何苦自尋煩惱？"]],"煩擾":[["ㄈㄢˊ ㄖㄠˇ","1.攪擾。[例]小孩的哭鬧，煩擾她不得不停下手邊的工作。\n2.因受攪擾而心煩。[例]我為最近諸多不順的事情，煩擾不已。"]],"煩瑣":[["ㄈㄢˊ ㄙㄨㄛˇ","煩雜瑣碎。[例]這件事太煩瑣了，這幾天可能無法處理完成。"]],"煩躁":[["ㄈㄢˊ ㄗㄠˋ","煩悶焦躁。[例]眼看事情無法解決，心裡不免煩躁起來。"]],"煮沸":[["ㄓㄨˇ ㄈㄟˋ","將東西加熱至沸騰。[例]生水要先煮沸後才能安心飲用。"]],"煮飯":[["ㄓㄨˇ ㄈㄢˋ","泛指燒飯煮菜，料理餐點。[例]他一個人生活慣了，洗衣、煮飯、打掃都難不倒他。"]],"熄滅":[["ㄒㄧˊ ㄇㄧㄝˋ","滅掉火源，停止燃燒。[例]出門前要記得將家中火源熄滅，以免發生火災。"]],"熄火":[["ㄒㄧˊ ㄏㄨㄛˇ","1.將火熄滅。[例]營火晚會後，務必記得熄火，以策安全。\n2.機動車輛的引擎停止運轉。[例]這輛老爺車，一旦熄火，要想再發動，可就比登天還難囉！"]],"熊心豹膽":[["ㄒㄩㄥˊ ㄒㄧㄣ ㄅㄠˋ ㄉㄢˇ","形容膽量極大。[例]難道他吃了熊心豹膽？否則怎敢直指老闆的不是。"]],"熔岩":[["ㄖㄨㄥˊ ㄧㄢˊ","火山爆發時，從火山口或地面的裂縫中，流出來的岩漿及其冷卻後的產物。熔岩冷凝形成的岩塊，多呈粗鬆的礦滓狀，其含矽量越大，形成的岩塊越碎。[例]火山爆發時噴出的熔岩溫度在攝氏700度以上，足以致命。"]],"熔點":[["ㄖㄨㄥˊ ㄉㄧㄢˇ","固體開始熔解時的溫度。在一定壓力下，溫度上升到一定值時，固態晶體物質開始轉變為液態，若繼續加熱到完全溶解時，溫度仍維持不變。[例]冰的熔點為攝氏零度。　△鎔點、融解點"]],"熟悉":[["ㄕㄡˊ ㄒㄧ","知道得很詳細。[例]她對公司的業務很熟悉，有問題請教她準沒錯。"]],"熟睡":[["ㄕㄡˊ ㄕㄨㄟˋ","睡得很沉。[例]母親看著熟睡中的妹妹，忍不住輕輕的吻她一下。"]],"熟稔":[["ㄕㄡˊ ㄖㄣˇ","熟識。[例]他們才認識沒多久，就熟稔得像多年的老友。"]],"熟練":[["ㄕㄡˊ ㄌㄧㄢˋ","技術純熟。[例]那些球員個個身手矯捷、動作熟練，一副勢在必得的樣子。"]],"熟能生巧":[["ㄕㄡˊ ㄋㄥˊ ㄕㄥ ㄑㄧㄠˇ","熟練了自然能領悟出竅門。[例]所謂「熟能生巧」，只要肯勤加練習，對於這部機器就能操作自如了。"]],"熬煮":[["ㄠˊ ㄓㄨˇ","用小火慢慢烹煮。[例]這高湯是用上等排骨熬煮而成的，因此味道特別鮮美。"]],"熱心":[["ㄖㄜˋ ㄒㄧㄣ","形容人做事積極且富關懷熱情。[例]熱心公益、熱心助人"]],"熱淚盈眶":[["ㄖㄜˋ ㄌㄟˋ ㄧㄥˊ ㄎㄨㄤ","形容心情激動得眼眶充滿了淚水。[例]這部愛情片她重複看了好幾遍，每次都感動得熱淚盈眶。"]],"熱烈":[["ㄖㄜˋ ㄌㄧㄝˋ","熱情激烈。[例]熱烈歡迎、反應熱烈、熱烈展開"]],"熱絡":[["ㄖㄜˋ ㄌㄨㄛˋ","感情深厚，往來頻繁。[例]他們兩家同時搬到這個社區，彼此來往很熱絡。"]],"熱衷":[["ㄖㄜˋ ㄓㄨㄥ","急切的追求且全心投入。[例]時下年輕人，非常熱衷於自助旅行。"]],"熱飲":[["ㄖㄜˋ ㄧㄣˇ","溫熱的飲料。[例]這家餐廳除備有餐點外，還供應各種冷、熱飲。"]],"熱騰騰":[["ㄖㄜˋ ㄊㄥˊ ㄊㄥˊ","形容很熱或冒著熱氣的樣子。[例]寒冷的冬季裡，喝一碗熱騰騰的湯，真是一大享受。"]],"熱鬧":[["ㄖㄜˋ ㄋㄠˋ","1.場面熱烈人潮擁擠。[例]這夜市整晚人潮不斷，熱鬧得很！_x000D_\n2.熱烈喧鬧的場面、景象。[例]街角的超市今天慶祝開幕，我們也去瞧瞧熱鬧吧！_x000D_\n3.慶祝，使氣氛活潑、高興。[例]奶奶八十大壽，爸爸決定好好熱鬧一下。"]],"熾熱":[["ㄔˋ ㄖㄜˋ","1.很熱、酷熱。[例]中午時分，烈日當頭，天氣相當熾熱。\n2.非常熱烈。[例]他對故鄉懷有十分熾熱的情感。"]],"燃燒":[["ㄖㄢˊ ㄕㄠ","可燃物質在空氣中與氧劇烈化合，而產生光與熱的現象。[例]請勿在高速公路旁燃燒稻草，以免影響行車視線。"]],"燈光":[["ㄉㄥ ㄍㄨㄤ","1.燈所照出來的光線。[例]閱讀時應該要有明暗適度的燈光。\n2.專指舞臺或攝影棚內的照明。[例]這次舞臺劇的燈光由張先生負責設計與控制。"]],"燈塔":[["ㄉㄥ ㄊㄚˇ","港口或島嶼上的高塔。夜間能發出明滅的燈光，指引船隻航行的方向。"]],"燈泡":[["ㄉㄥ ㄆㄠˋ","→電燈泡"]],"燈管":[["ㄉㄥ ㄍㄨㄢˇ","裝有金屬絲、惰性氣體，經灼熱即發光的條形燈具。[例]辦公室的燈光相當昏暗，應儘快更換新的燈管。"]],"燈籠":[["ㄉㄥ ㄌㄨㄥˊ","以塑膠、細竹或鐵絲做骨架，外表糊上紗、紙，並用蠟燭、電燈做光源的燈具。可以提、掛，作為裝飾品或照明用具。[例]每逢廟會，社區裡便掛起一排排紅色燈籠，增添不少熱鬧的氣氛。　◎"]],"燈絲":[["ㄉㄥ ㄙ","真空管中的金屬絲。多以鎢製成，通電後能發光發熱，放射電子或產生射線。[例]這顆燈泡的燈絲燒斷了，因此無法發光。"]],"燒焦":[["ㄕㄠ ㄐㄧㄠ","因加熱過度而碳化或枯乾。[例]爐子裡的番薯因為烤得太久而燒焦了。"]],"營利":[["ㄧㄥˊ ㄌㄧˋ","謀求利潤。[例]慈善機構從事社會服務，不是營利機關。"]],"營地":[["ㄧㄥˊ ㄉㄧˋ","軍隊官兵駐守的所在地。[例]營地每夜都有士兵輪值，以確保安全。"]],"營火":[["ㄧㄥˊ ㄏㄨㄛˇ","夜間露營時，在營帳外堆木燃燒的火。[例]營火晚會"]],"營隊":[["ㄧㄥˊ ㄉㄨㄟˋ","隊伍。[例]這次的露營大會有數百個營隊參加，場面非常壯觀。"]],"營養":[["ㄧㄥˊ ㄧㄤˇ","提供個體能量，維持生命活力、抵抗力的養分。[例]食物中含有各種營養，均衡攝取才能保持健康。"]],"燥熱":[["ㄗㄠˋ ㄖㄜˋ","乾燥炎熱。[例]今天下午天氣燥熱，令人昏昏欲睡。"]],"燦爛":[["ㄘㄢˋ ㄌㄢˋ","形容光彩美麗。[例]他的笑容如同太陽般燦爛，十分吸引人。"]],"燦爛奪目":[["ㄘㄢˋ ㄌㄢˋ ㄉㄨㄛˊ ㄇㄨˋ","形容光彩美麗，十分耀眼。[例]美麗的煙火，將整個天空點綴得燦爛奪目。"]],"爆炸":[["ㄅㄠˋ ㄓㄚˋ","1.物體體積發生急速膨脹，使周圍氣壓產生強烈變化而炸破，發出巨大的聲響。[例]瓦斯爆炸\n2.比喻事物產生快而多。[例]這是一個知識爆炸的時代。"]],"爆竹":[["ㄅㄠˋ ㄓㄨˊ","用紙捲裹火藥做成，點燃引線就會炸裂。多用於年節、喜慶。[例]過年燃放爆竹固然可以增添喜氣，但也要注意安全。　△炮竹"]],"爐灶":[["ㄌㄨˊ ㄗㄠˋ","1.爐子和灶。[例]在某些偏遠地區，仍有部分人家使用爐灶升火煮飯。\n2.比喻事業的基礎。[例]經過一年的休養生息，他決心另起爐灶，從頭開始。"]],"爪子":[["ㄓㄨㄚˇ ˙ㄗ","禽、獸的尖甲腳趾。[例]虎爪子、雞爪子　△爪兒"]],"爪牙":[["ㄓㄠˇ ㄧㄚˊ","1.動物的尖爪和利牙。[例]老鷹、獅子尖利的爪牙，都是捕食獵物時的利器。\n2.借指仗勢欺人的走狗。[例]抗戰時期，有些喪心病狂的人，出賣靈魂，竟做了日本兵的爪牙。"]],"爪痕":[["ㄓㄠˇ ㄏㄣˊ","爪甲留下的印痕。[例]這處海灘常有海鳥聚集覓食，在沙灘上留下了許多爪痕。"]],"爭光":[["ㄓㄥ ㄍㄨㄤ","爭取榮耀。[例]他為國爭光，勇奪奧林匹克運動會十項全能的金牌。"]],"爭吵":[["ㄓㄥ ㄔㄠˇ","爭鬥吵鬧。[例]寬容與體諒是避免爭吵的不二法門。"]],"爭執":[["ㄓㄥ ㄓˊ","各執己見，不肯相讓。[例]人與人之間若能互相關懷，互相信賴，許多爭執或衝突自然消弭於無形。"]],"爭奪":[["ㄓㄥ ㄉㄨㄛˊ","爭相奪取，互不退讓。[例]與其費盡心思去爭奪名利，不如修養身心，精進德業。"]],"爭論":[["ㄓㄥ ㄌㄨㄣˋ","紛爭辯論，各不退讓。[例]雙方已經就此議題多方爭論，仍然無法達成協議。"]],"父子":[["ㄈㄨˋ ㄗˇ","父親與兒子。[例]陳伯父與我情同父子。"]],"父母":[["ㄈㄨˋ ㄇㄨˇ","父親和母親。[例]養兒方知父母恩"]],"父親":[["ㄈㄨˋ ㄑㄧㄣ","稱謂。對爸爸的稱呼。[例]等父親回來，我們再一起吃晚飯。　◎"]],"爸爸":[["ㄅㄚˋ ˙ㄅㄚ","稱謂：對父親的稱呼。[例]爸爸教我們：跌倒了就要勇敢地爬起來。"]],"爺爺":[["ㄧㄝˊ ˙ㄧㄝ","稱謂：(1) 對祖父的稱呼。[例]爺爺雖已年近八十，身子骨還是很硬朗。　(2) 稱和祖父同輩分或年紀相當的男性。[例]隔壁的李爺爺慈祥和藹，大夥兒都喜歡和他接近。"]],"爽朗":[["ㄕㄨㄤˇ ㄌㄤˇ","1.直爽、開朗。[例]她個性爽朗，是朋友眼中的開心果。\n2.形容天氣清朗明麗，令人舒暢。[例]這種爽朗的天氣最適合郊遊。"]],"爽約":[["ㄕㄨㄤˇ ㄩㄝ","失約。[例]他為了上次爽約的事，一再向我道歉。"]],"牆壁":[["ㄑㄧㄤˊ ㄅㄧˋ","以磚石、泥土、木板等做成，用以隔間或屏障的建築物。[例]她在牆壁釘上鋼釘，準備用來掛畫裝飾。"]],"牆角":[["ㄑㄧㄤˊ ㄐㄧㄠˇ","兩面牆相連的轉折處。[例]他在牆角放置三角形的書架，以充分的利用空間。"]],"片刻":[["ㄆㄧㄢˋ ㄎㄜˋ","一會兒，形容極短的時間。[例]他一路上馬不停蹄的趕路，片刻都不得休息。"]],"版面":[["ㄅㄢˇ ㄇㄧㄢˋ","1.書報雜誌上每一頁的整面稱為「版面」。[例]這整個版面都是有關於總統訪問南非的消息。\n2.書報雜誌每一頁文字圖畫的編排形式。[例]總編對於版面的設計，非常在行。"]],"牙膏":[["ㄧㄚˊ ㄍㄠ","刷牙時所用的軟膏狀物。有清潔牙齒和維護口腔衛生的功效。主要原料為普通牙粉、肥皂粉、甘油及糖水等。[例]牙膏中添加的氟化物，對牙齒的琺瑯質具有保護作用。"]],"牙齒":[["ㄧㄚˊ ㄔˇ","動物體的咀嚼器官，為固立於上下顎骨之齒槽突的硬組織突起物。其構造可分為硬組織形成的琺瑯質、象牙質和牙骨質，以及包在硬組織中心而屬於軟組織的牙髓。人的牙齒包括門牙、犬齒、臼齒三部分。除了咀嚼食物的主要功能外，對於發音及臉部的美感也很重要。[例]保持口腔的清潔與衛生，才能擁有一口健康的牙齒。　◎◎◎"]],"牛乳":[["ㄋㄧㄡˊ ㄖㄨˇ","牛的乳汁。[例]牛乳中含有許多營養，多喝有益健康。　△牛奶"]],"牛仔":[["ㄋㄧㄡˊ ㄗㄞˇ","原指美國西部牧場的畜牧者。後泛指牧場工人。[例]那位牛仔的套繩和射騎技術非常精湛，在這一帶無人能比。"]],"牛奶":[["ㄋㄧㄡˊ ㄋㄞˇ","牛的乳汁。[例]常喝牛奶有益身體健康。　△牛乳"]],"牛排":[["ㄋㄧㄡˊ ㄆㄞˊ","將牛的里肌肉切成厚片，以調味料醃過，依各人喜好煎成不同熟度，再淋上醬汁的食物。[例]牛排以三分熟的口味最佳，可惜國人因飲食習慣的不同，多選擇七分熟。"]],"牛車":[["ㄋㄧㄡˊ ㄔㄜ","用牛拉的車。[例]以前常以「嫁妝一牛車」來表示女孩子的嫁妝很多。"]],"牠們":[["ㄊㄚ ˙ㄇㄣ","兩個以上的動物合稱。[例]動物園有許多頑皮可愛的猴子，小朋友都很喜歡牠們。"]],"牢牢":[["ㄌㄠˊ ㄌㄠˊ","1.堅固的樣子。[例]我們把帳篷的繩索牢牢地繫緊。_x000D_\n2.持續不變。[例]他牢牢地盯著電視看，不想錯過劇中的任何一個情節。"]],"牧場":[["ㄇㄨˋ ㄔㄤˇ","牧養牛、羊的場所。[例]大約有一萬頭牛被畜養在這個牧場裡。"]],"物品":[["ㄨˋ ㄆㄧㄣˇ","東西、貨物。[例]這家便利商店規模雖然不大，物品卻很齊全。"]],"物欲":[["ㄨˋ ㄩˋ","追求物質的欲望。[例]政治腐敗、道德不彰容易形成一個物欲橫流的社會。"]],"物種":[["ㄨˋ ㄓㄨㄥˇ","生物分類的基本單位。"]],"物競天擇":[["ㄨˋ ㄐㄧㄥˋ ㄊㄧㄢ ㄗㄜˊ","物種互相競爭，適應自然者生存，不適應者即遭淘汰。為達爾文《演化論》所提出的主要觀念。"]],"特別":[["ㄊㄜˋ ㄅㄧㄝˊ","與眾不同。[例]這場露天演唱會十分特別，吸引不少的觀眾前往欣賞。"]],"特徵":[["ㄊㄜˋ ㄓㄥ","特殊的徵象、標誌。[例]因天色昏暗、視線不佳，所以他未能認清作案歹徒身上的特徵。"]],"特殊":[["ㄊㄜˋ ㄕㄨ","特別的、不同於一般的。[例]這次的情況非常特殊，無法用一般的方式辦理，必須專案處理。"]],"特產":[["ㄊㄜˋ ㄔㄢˇ","某地特有的或特別有名的產品。[例]太陽餅是臺中的特產。"]],"特質":[["ㄊㄜˋ ㄓˊ","1.異於其他事物的性質。[例]中華文化具有融合異己的特質。\n2.心理學上指個人持久性的特殊行為方式或心理特徵。[例]人格特質"]],"牽動":[["ㄑㄧㄢ ㄉㄨㄥˋ","牽連影響。[例]此舉恐將牽動全局，不得不慎！"]],"牽手":[["ㄑㄧㄢ ㄕㄡˇ","1.手牽著手。[例]他們牽手漫步在夕陽下。_x000D_\n2.指太太。[例]他逢人便說自己娶了個好牽手。"]],"牽扯":[["ㄑㄧㄢ ㄔㄜˇ","牽連拉扯。[例]最好把問題澈底解決了，免得日後牽扯不清。"]],"牽掛":[["ㄑㄧㄢ ㄍㄨㄚˋ","記掛想念。[例]她由於牽掛在外地求學的孩子，常常夜不成眠。"]],"牽涉":[["ㄑㄧㄢ ㄕㄜˋ","牽連涉及。[例]這個問題牽涉很廣，一時間很難說清楚。"]],"牽連":[["ㄑㄧㄢ ㄌㄧㄢˊ","牽涉關聯。[例]這件弊案牽連甚廣，有關單位正擴大調查中。"]],"犧牲":[["ㄒㄧ ㄕㄥ","1.古代祭祀用的牲畜。[例]古代祭祀時所用的犧牲，以牛、羊、豬為主。\n2.為了某種目的或理想而付出自己的生命或權利。[例]戰士為了保衛國家，不惜犧牲生命，奮勇作戰。"]],"犯法":[["ㄈㄢˋ ㄈㄚˇ","觸犯法律。[例]知法犯法，罪無可逭。"]],"犯錯":[["ㄈㄢˋ ㄘㄨㄛˋ","做錯事。[例]老師再三告誡他，只希望他不要再犯錯。"]],"狀態":[["ㄓㄨㄤˋ ㄊㄞˋ","狀況、情形。[例]警戒狀態、心理狀態、混亂狀態"]],"狀況":[["ㄓㄨㄤˋ ㄎㄨㄤˋ","情形。[例]財務狀況、緊急狀況"]],"狀聲詞":[["ㄓㄨㄤˋ ㄕㄥ ㄘˊ","描摹聲音的詞彙。如颼颼、淅瀝、嘩啦等。[例]狀聲詞的運用，可使文章更加生動。 △擬聲詞_x000D_"]],"狂奔":[["ㄎㄨㄤˊ ㄅㄣ","疾速如瘋狂般往前奔走。[例]縱馬狂奔"]],"狂風":[["ㄎㄨㄤˊ ㄈㄥ","1.猛烈的強風。[例]樹木被狂風吹折，連根拔起。_x000D_\n2.氣象學上指風力十級的風。"]],"狐狸":[["ㄏㄨˊ ㄌㄧˊ","1.本指狐和狸兩種動物，後多專指狐。[例]童話故事中的狐狸常是狡猾奸詐的。_x000D_\n2.狐狸生性狡猾多疑，故多用來比喻狡詐而作惡多端的壞人。[例]他作惡多端卻能不讓人捉到把柄，真是隻老狐狸。"]],"狗仗人勢":[["ㄍㄡˇ ㄓㄤˋ ㄖㄣˊ ㄕˋ","比喻倚仗權勢欺人。[例]你少狗仗人勢，欺人太甚了！"]],"狠心":[["ㄏㄣˇ ㄒㄧㄣ","心性殘忍。[例]這些黑道分子個個狠心，怎麼可能和你講情面？"]],"狠狠的":[["ㄏㄣˇ ㄏㄣˇ ˙ㄉㄜ","激烈的、重重的。[例]王伯伯看不慣兒子終日遊手好閒，狠狠的罵了他一頓。"]],"狡兔三窟":[["ㄐㄧㄠˇ ㄊㄨˋ ㄙㄢ ㄎㄨ","狡猾的兔子有三處藏身的洞穴。比喻人有多處藏身的地方或多種避禍的準備。語本《戰國策．齊策四》。[例]他可是狡兔三窟，想抓到他很不容易。"]],"狡猾":[["ㄐㄧㄠˇ ㄏㄨㄚˊ","詭變多詐。[例]他像狐狸般狡猾，你千萬不要上當！"]],"狡詐":[["ㄐㄧㄠˇ ㄓㄚˋ","狡猾奸詐。[例]他為人狡詐，很多人都上過他的當。"]],"狩獵":[["ㄕㄡˋ ㄌㄧㄝˋ","利用獵具或獵狗等捕捉野生鳥獸。[例]任意狩獵是違法的。"]],"狹小":[["ㄒㄧㄚˊ ㄒㄧㄠˇ","1.窄小。[例]這裡的空間很狹小，容納不下這麼多人。\n2.形容人心胸狹窄、見識短淺。[例]他的心胸狹小，連一點小事都耿耿於懷。"]],"狹窄":[["ㄒㄧㄚˊ ㄓㄞˇ","1.寬度窄小。[例]自從那條狹窄的外環道路拓寬後，塞車的狀況改善不少。\n2.形容心胸狹小、眼光短淺。[例]心地狹窄的人很難過著輕鬆快樂的生活。"]],"狼吞虎嚥":[["ㄌㄤˊ ㄊㄨㄣ ㄏㄨˇ ㄧㄢˋ","形容吃東西又猛又急。[例]肚子再餓也不該狼吞虎嚥，那對腸胃的消化會產生很大的負擔。"]],"狼犬":[["ㄌㄤˊ ㄑㄩㄢˇ","→狼狗"]],"狼狽":[["ㄌㄤˊ ㄅㄟˋ","1.本指情勢窘迫，進退兩難。後亦比喻身心困頓疲乏。[例]她提著大批行李趕路，卻遇到大雨，被淋得狼狽不堪。\n2.比喻彼此勾結，相倚為惡。[例]狼狽為奸"]],"狼藉":[["ㄌㄤˊ ㄐㄧˊ","傳說狼群常在草地上臥息，離去時會將草地弄得一片凌亂，以消滅蹤跡。後用此語形容凌亂不堪或毫無秩序、紀律。[例]杯盤狼藉"]],"猛然":[["ㄇㄥˇ ㄖㄢˊ","突然。[例]到了辦公室，他才猛然想起家裡瓦斯爐忘了關。"]],"猛獸":[["ㄇㄥˇ ㄕㄡˋ","凶猛的野獸。[例]非洲叢林中，常有猛獸出沒，經過時要小心提防才好。"]],"猜度":[["ㄘㄞ ㄉㄨㄛˋ","猜測、推想。[例]此事未經證實前，切勿任意猜度。"]],"猜忌":[["ㄘㄞ ㄐㄧˋ","不信任別人，猜想別人將對自己不利。[例]他們倆表面上稱兄道弟，私底下卻互相猜忌，各懷鬼胎。"]],"猜想":[["ㄘㄞ ㄒㄧㄤˇ","推測料想。[例]雨這麼大，我猜想他不會來了。"]],"猜拳":[["ㄘㄞ ㄑㄩㄢˊ","一種遊戲，有各種不同的方式。最簡單的一種是：同時伸出食指、中指代表「剪刀」，握拳代表「石頭」，攤開手掌代表「布」。如果石頭對上布，布贏；剪刀對上石頭，石頭贏；布對上剪刀，剪刀贏。[例]我們猜拳，輸的人洗碗。"]],"猜謎":[["ㄘㄞ ㄇㄧˊ","根據謎面猜測謎底。[例]他說話老是喜歡拐彎抹角，和人玩猜謎遊戲。"]],"猴子":[["ㄏㄡˊ ˙ㄗ","→猴"]],"猶在":[["ㄧㄡˊ ㄗㄞˋ","還存在。[例]青山猶在，綠水長流。"]],"猶豫":[["ㄧㄡˊ ㄩˋ","拿不定主意。[例]遇到好機會，要趕緊把握，千萬別猶豫不決，坐失良機。"]],"獅子":[["ㄕ ˙ㄗ","→獅"]],"獎勵":[["ㄐㄧㄤˇ ㄌㄧˋ","以贈予榮譽、財物等方式獎賞鼓勵。[例]弟弟月考得第一名，爸爸送他一套百科全書以示獎勵。"]],"獎狀":[["ㄐㄧㄤˇ ㄓㄨㄤˋ","為獎勵而頒發的證書。[例]他獲得全校作文比賽第一名，校長頒給他一張獎狀，以為鼓勵。"]],"獎賞":[["ㄐㄧㄤˇ ㄕㄤˇ","對於有功或在競賽中獲得優勝的人員或團體，給予物品、金錢的獎勵。[例]這場高爾夫球賽的冠軍，將獲得百萬元的獎賞。"]],"獨一無二":[["ㄉㄨˊ ㄧ ㄨˊ ㄦˋ","只此一個，別無其他。形容最特殊，沒有可比或相同的。[例]中國萬里長城是世上獨一無二的歷史奇觀。"]],"獨吞":[["ㄉㄨˊ ㄊㄨㄣ","比喻利益為一人所占有。[例]這些錢是大家辛苦賺來的，豈容一人獨吞！"]],"獨大":[["ㄉㄨˊ ㄉㄚˋ","勢力最大，無可匹敵。[例]一黨獨大是無法使民主政治步上正常軌道的。"]],"獨特":[["ㄉㄨˊ ㄊㄜˋ","獨有的、特殊的。[例]想要在眾多的競爭者中脫穎而出，就要有自己獨特的風格。"]],"獨白":[["ㄉㄨˊ ㄅㄞˊ","戲劇中人物向觀眾單獨道出個人內心感受，或即將發生之事的一段臺詞。沿用至電影或小說中，則成為腳色獨自抒發個人情感和願望的話。[例]這部電影中女主角有一段獨白十分感人。"]],"獨立":[["ㄉㄨˊ ㄌㄧˋ","1.獨自站立。[例]一盞孤燈，獨立街頭。\n2.不倚靠他人而能自立。[例]他成年後就離家開始學習獨立。\n3.指國家有完全自主權，不受外來力量干涉。[例]美國於西元1776年宣布脫離英國獨立。"]],"獨自":[["ㄉㄨˊ ㄗˋ","自己一個人。[例]他常獨自到國外自助旅行以增廣見聞。"]],"獨處":[["ㄉㄨˊ ㄔㄨˇ","獨自居處。[例]他依賴性太強，考上大學後在外租屋，正好可以培養獨處的能力。"]],"獨裁":[["ㄉㄨˊ ㄘㄞˊ","指獨自裁斷政事的專制統治。[例]秦始皇的專斷獨裁，造成六國遺民起兵反抗。"]],"獲准":[["ㄏㄨㄛˋ ㄓㄨㄣˇ","得到允許。[例]她向上司極力的爭取，終於獲准休假一星期。"]],"獲取":[["ㄏㄨㄛˋ ㄑㄩˇ","取得。[例]養成讀報的習慣，可以獲取各類的新資訊。"]],"獲得":[["ㄏㄨㄛˋ ㄉㄜˊ","獲取、得到。[例]只有努力再努力，才能獲得令自己滿意的成績。"]],"獲獎":[["ㄏㄨㄛˋ ㄐㄧㄤˇ","得到獎品。[例]他以精湛的技藝，打敗所有競賽者而光榮獲獎。"]],"獲益":[["ㄏㄨㄛˋ ㄧˋ","得到益處。[例]他的學養深厚，智識淵博，與他為友，真是獲益不少。"]],"獲釋":[["ㄏㄨㄛˋ ㄕˋ","得到釋放。[例]由於法官明察秋毫，伸張正義，他終於無罪獲釋。"]],"獵人":[["ㄌㄧㄝˋ ㄖㄣˊ","以狩獵為業的人。[例]他的槍法準、反應快，是一個相當出色的獵人。"]],"獵犬":[["ㄌㄧㄝˋ ㄑㄩㄢˇ","一種受過訓練，可輔助人類狩獵的狗。通常都具有嗅覺敏銳、動作迅捷、反應機警和耐力好等特質。[例]森林的那頭傳出獵犬追逐獵物的吠聲。"]],"獵鷹":[["ㄌㄧㄝˋ ㄧㄥ","泛稱鳥綱鷲鷹目的猛禽。雙翅寬廣強勁，眼睛大而銳利，可在空中盤旋並準確測出獵物的位置。利爪和勾嘴是牠們最厲害的武器。生活領域廣闊，在凍原、草原、湖泊、沼澤和沙漠等不同生態環境中，皆見其蹤跡。如隼、老鷹、灰面鷲等。[例]生態環境的破壞、人類的捕殺已經使獵鷹的生存受到嚴重威脅。"]],"獻計":[["ㄒㄧㄢˋ ㄐㄧˋ","提供謀略、計策。[例]由於陳平、張良獻計，使劉邦棄和背約，擊潰項羽，因而結束楚漢之爭。"]],"獻醜":[["ㄒㄧㄢˋ ㄔㄡˇ","露出醜態。向人表露自己技能時的謙詞。[例]承蒙各位不嫌棄，那我就獻醜了。"]],"玄妙":[["ㄒㄩㄢˊ ㄇㄧㄠˋ","深奧微妙。[例]自然界中仍有許多玄妙的事情，是現今科學無法解釋的。"]],"玄關":[["ㄒㄩㄢˊ ㄍㄨㄢ","住宅入門處與正廳之間的空間。[例]他在玄關換好拖鞋，才走進客廳。"]],"率先":[["ㄕㄨㄞˋ ㄒㄧㄢ","領先、首先。[例]他率先發起募捐，獲得同事們熱烈的響應。"]],"率隊":[["ㄕㄨㄞˋ ㄉㄨㄟˋ","率領隊伍。[例]他身為體育教練，經常要率隊征戰各地。"]],"率領":[["ㄕㄨㄞˋ ㄌㄧㄥˇ","帶領、引導。[例]母鴨率領一群小鴨走向池塘。"]],"玉兔":[["ㄩˋ ㄊㄨˋ","本指傳說在月亮中的兔子。後亦借指為月亮。[例]玉兔東升"]],"玉米":[["ㄩˋ ㄇㄧˇ","→玉蜀黍"]],"王位":[["ㄨㄤˊ ㄨㄟˋ","帝王的權位。[例]中國歷代大都是以嫡長子來繼承王位。"]],"王侯":[["ㄨㄤˊ ㄏㄡˊ","王爵和侯爵。泛指顯貴的人。[例]他事業有成，過著如王侯般優渥的生活。"]],"王冠":[["ㄨㄤˊ ㄍㄨㄢ","帝王的帽子。[例]王冠象徵帝王的權力和榮耀。"]],"王后":[["ㄨㄤˊ ㄏㄡˋ","帝王的正妻。[例]王后母儀天下，所以歷朝選后均非常審慎。"]],"王子":[["ㄨㄤˊ ㄗˇ","帝王的兒子。如英國有查爾斯王子。"]],"王宮":[["ㄨㄤˊ ㄍㄨㄥ","帝王所居住的宮殿。[例]凡爾賽宮是法國著名的王宮。"]],"王牌":[["ㄨㄤˊ ㄆㄞˊ","1.牌戲中牌力最強的牌。在沒有特別指定的情況下，通常以黑桃為王牌。[例]眼看就要輸了，他趕緊打出手上的王牌。\n2.比喻具有關鍵性、可影響大局的人物。[例]他的球技精湛，是球隊的王牌投手。"]],"玩具":[["ㄨㄢˊ ㄐㄩˋ","可供遊戲玩樂的東西。[例]為了確保兒童的安全，請選購安全玩具。"]],"玩弄":[["ㄨㄢˊ ㄋㄨㄥˋ","戲弄、愚弄。[例]人與人之間應真誠相待，不要心存玩弄。"]],"玩耍":[["ㄨㄢˊ ㄕㄨㄚˇ","遊戲。[例]吃過午飯，他就和鄰家小孩在門前的空地上玩耍。"]],"玻璃":[["ㄅㄛ ㄌㄧˊ","用白砂、石灰石、碳酸鈉、碳酸鉀等混合起來，加高熱燒融，冷卻後製成的堅硬物質。有透明與半透明兩種，可以製成鏡子、窗戶等各種用具。[例]雖然他擊出了一支全壘打，但也打破了教室窗戶的玻璃。"]],"珊瑚":[["ㄕㄢ ㄏㄨˊ","腔腸動物珊瑚蟲綱的泛稱。生活在暖海中。許多珊瑚蟲集結營生，分泌具有石灰質的黏液，硬化後所形成的骨架亦稱為「珊瑚」。形狀分歧如樹枝。色彩鮮豔美觀，有白色、紅色、桃紅色、黑色等。其骨骼質地略硬，可製成項鍊、胸針等飾品。[例]水族箱內各種顏色的珊瑚幾乎搶盡了魚的風采。"]],"珊瑚礁":[["ㄕㄢ ㄏㄨˊ ㄐㄧㄠ","由造礁珊瑚和石灰質生物遺骸經長期堆積所構成的礁石。一般多形成於熱帶及亞熱帶的陸地邊緣水域。可分為裙礁、堡礁及環礁。[例]澳洲的大堡礁是有名的珊瑚礁海域，更是喜愛潛水者的樂園。"]],"珍惜":[["ㄓㄣ ㄒㄧˊ","重視愛惜。[例]今日國家社會的安定繁榮得來不易，大家要珍惜。"]],"珍珠":[["ㄓㄣ ㄓㄨ","1.蚌內因異物侵入或病理變化而產生的圓形顆粒。有光澤，呈白色或微黃色。一般分為天然養珠及人工養珠兩種。[例]珍珠項鍊　△真珠_x000D_\n2.指粉圓。[例]珍珠奶茶"]],"珍貴":[["ㄓㄣ ㄍㄨㄟˋ","珍奇、貴重。[例]這所圖書館收藏了許多珍貴的善本書。"]],"珍饈":[["ㄓㄣ ㄒㄧㄡ","珍奇美味的食物。[例]珍饈佳餚"]],"珠聯璧合":[["ㄓㄨ ㄌㄧㄢˊ ㄅㄧˋ ㄏㄜˊ","日月如併合的璧玉，星辰如成串的珍珠。比喻人才或美好的事物相匹配或同時聚集。常用作祝賀新婚的頌辭。語本《漢書．卷二十一．律曆志上》。[例]這對新人真是郎才女貌、珠聯璧合。"]],"班會":[["ㄅㄢ ㄏㄨㄟˋ","在各級學校中，由全班同學共同參加的定期集會，通常一週舉行一次。[例]這次班會的主要議題，在於討論郊遊的有關事宜。"]],"班級":[["ㄅㄢ ㄐㄧˊ","現行教育制度上的一種編制。學校按學生的年齡或程度，把若干人合在一起以便教學所編成的單位。[例]本校今年新生多招收了五個班級。"]],"班長":[["ㄅㄢ ㄓㄤˇ","1.學校每一班級中，由學生互相推選或老師指派的學生代表，負責管理或執行班級事務。[例]老師說一位好班長是要品學兼優，熱忱助人的。　△班代、班頭_x000D_\n2.部隊編制中，負責率領一個班的士官。[例]報告班長，前方發現敵人蹤跡！"]],"班門弄斧":[["ㄅㄢ ㄇㄣˊ ㄋㄨㄥˋ ㄈㄨˇ","班，魯班，古代巧匠，相傳為木匠祖師。班門弄斧指在巧匠魯班門前玩弄斧頭。比喻在行家面前賣弄本事，不自量力。常用作自謙之詞。[例]就憑你，也敢在專家面前吹噓，真是班門弄斧，不自量力。"]],"現代":[["ㄒㄧㄢˋ ㄉㄞˋ","當代，目前所處的時代。[例]現代科學日新月異，進步神速。"]],"現在":[["ㄒㄧㄢˋ ㄗㄞˋ","現今、眼前。[例]現在外面正下著大雨，沒事就不要出去了。"]],"現狀":[["ㄒㄧㄢˋ ㄓㄨㄤˋ","目前的狀態。[例]有抱負者應該有所突破，不可安於現狀。"]],"球場":[["ㄑㄧㄡˊ ㄔㄤˇ","球類運動的場所。[例]球場上正展開一場激烈的籃賽，敵我兩隊廝殺得非常厲害。"]],"球拍":[["ㄑㄧㄡˊ ㄆㄞ","打球用的拍子。[例]這支球拍的網線已斷落，不能再用了。"]],"球賽":[["ㄑㄧㄡˊ ㄙㄞˋ","球類競賽。[例]這場球賽非常精彩，球迷們的加油聲響徹雲霄。"]],"琅琅":[["ㄌㄤˊ ㄌㄤˊ","狀聲詞。形容金石相擊或讀書時，清朗而響亮的聲音。[例]琅琅上口"]],"琅琅上口":[["ㄌㄤˊ ㄌㄤˊ ㄕㄤˋ ㄎㄡˇ","琅琅，玉石清脆響亮的撞擊聲，比喻響亮的讀書聲。琅琅上口形容對詩文誦讀熟練，能順口誦讀而出。[例]這首童謠是大家兒時的共同回憶，多數人都能琅琅上口。"]],"理論":[["ㄌㄧˇ ㄌㄨㄣˋ","1.具有系統、組織的定律或論點。是由實際的驗證中歸納出，或由觀念推演而得。如科學上的理論。[例]經過多次實驗及觀念推演，我們終於證實了這項科學理論。\n2.按照事物的道理評析，相對於實際或實踐而言。[例]這項提案理論上雖可行，實際上卻是行不通的。\n3.見解、觀點。[例]一談到投資理財，他總是滔滔不絕的發表自己的理論。\n4.據理爭論、講理。[例]等我們找到充分的證據後，再與不肖業者理論。"]],"理髮廳":[["ㄌㄧˇ ㄈㄚˇ ㄊㄧㄥ","修剪、梳理頭髮的場所。通常指男子的理髮場所。"]],"琉璃":[["ㄌㄧㄡˊ ㄌㄧˊ","1.一種天然有光澤的青色寶石。　△流離\n2.一種鋁、鈉化合物燒製而成的半透明釉料。常見的有綠色、藍色或黃色，現則可用不同的化學配方調製成各式顏色。可加在黏土外層，燒製成缸、瓦、盆等，亦可用於建築。\n3.玻璃的古稱。[例]藝術琉璃"]],"琢磨":[["ㄓㄨㄛˊ ㄇㄛˊ","1.雕琢和磨製玉石。[例]他將這塊寶石琢磨成心形墜飾。\n2.比喻對品德或文章不斷精益求精。[例]同學間互相切磋琢磨，有助於課業的進步。\n3.思索、研究、考慮。[例]他琢磨了一夜，終於把問題想通了。"]],"瑣事":[["ㄙㄨㄛˇ ㄕˋ","細小零碎的事情。[例]他原本月底要出國，因為瑣事纏身，所以改到下個月。"]],"瑣碎":[["ㄙㄨㄛˇ ㄙㄨㄟˋ","形容細小繁多。[例]做家事看似輕鬆，其實瑣碎的事情很多，倒蠻累人的。"]],"瑤池":[["ㄧㄠˊ ㄔˊ","本為傳說中西王母所居之地，後泛指神仙居住的地方。[例]古來人們莫不幻想神仙生活的無憂無慮，所以瑤池便成為眾所嚮往之地。"]],"瑤臺":[["ㄧㄠˊ ㄊㄞˊ","1.用玉石裝飾華美的高臺。\n2.仙人居住的地方。[例]若非群玉山頭見，會向瑤臺月下逢。（唐．李白〈清平調〉三首之一）"]],"璀璨":[["ㄘㄨㄟˇ ㄘㄢˋ","光采鮮明的樣子。[例]不怕萬難，努力向上，必有璀璨的前程。"]],"環境":[["ㄏㄨㄢˊ ㄐㄧㄥˋ","泛指地表上影響人類及其他生物賴以生活、生存的空間、資源及其他有關的事物狀態。[例]社會環境、學習環境、居住環境"]],"環島":[["ㄏㄨㄢˊ ㄉㄠˇ","環繞島嶼四周。[例]環島旅行"]],"環繞":[["ㄏㄨㄢˊ ㄖㄠˋ","成圓形的旋繞。[例]運動員依次進場後環繞操場一周。"]],"瓊瑤":[["ㄑㄩㄥˊ ㄧㄠˊ","1.美玉、美石。[例]投我以木桃，報之以瓊瑤。（《詩經．衛風．木瓜》）\n2.比喻別人所致贈的禮物或詩文。[例]書信來天外，瓊瑤滿匣中。（唐．劉禹錫〈酬太原令狐相公見寄〉詩）"]],"瓜子":[["ㄍㄨㄚ ㄗˇ","1.泛稱瓜果的種子。_x000D_\n2.一種食品。大多以西瓜、倭瓜、南瓜、葵花的種子，加調味品煮炒、焙製而成。[例]葵瓜子、醬油瓜子_x000D_\n3.形狀像瓜子的。[例]瓜子臉"]],"瓢蟲":[["ㄆㄧㄠˊ ㄔㄨㄥˊ","動物名。昆蟲綱瓢蟲科。軀體為半球形，體長約八至十公釐，背上有紅色或黑色斑點。因體形像倒蓋著的水瓢，故稱為「瓢蟲」。[例]瓢蟲身上的紅黑斑點，對比鮮明，相當醒目。"]],"瓦礫":[["ㄨㄚˇ ㄌㄧˋ","碎瓦砂礫。[例]附近的工地管理不善，造成整條街滿地瓦礫。"]],"瓦缶":[["ㄨㄚˇ ㄈㄡˇ","一種有蓋、腹大口小的陶器，用來盛裝酒或水，也可作為敲擊樂器。"]],"瓶子":[["ㄆㄧㄥˊ ˙ㄗ","口小、頸窄、腹大的容器。一般以瓷土、玻璃、塑料等製成，多用以盛裝液體。[例]這瓶子上的花鳥彩繪很細緻。"]],"瓶頸":[["ㄆㄧㄥˊ ㄐㄧㄥˇ","本指瓶口下方細長似頸的部分，後引申在任何工作中所遭遇足以影響事物順利進行的阻礙。[例]工業瓶頸、交通瓶頸、創作瓶頸"]],"甘蔗":[["ㄍㄢ ㄓㄜˋ","植物名。禾本科甘蔗屬，多年生大草本。高約三公尺，莖直立似竹，有節實心，含有多量之甘甜水分，為製糖原料，可生食。[例]臺灣所種植的甘蔗，紅色外皮的專供生食，白色外皮的則用來製糖。　△諸蔗　◎"]],"甘藷":[["ㄍㄢ ㄕㄨˇ","→番薯"]],"甚至":[["ㄕㄣˋ ㄓˋ","表示更進一層的連接詞。[例]他忙得甚至連吃飯時間都沒有。"]],"甜美":[["ㄊㄧㄢˊ ㄇㄟˇ","1.甘甜味美。[例]荔枝的味道甜美，我們全家人都喜歡吃。\n2.秀美迷人。[例]她笑起來十分甜美，很討人喜歡。"]],"甜菜":[["ㄊㄧㄢˊ ㄘㄞˋ","植物名。藜科，一年或二年生草本植物。原產於歐洲。葉柄長，紅色。葉片大，濃綠色或紅色。花小，黃綠色。地下有一個膨大像蘿蔔的根。根中組織脆嫩，富含糖分、多種維生素、鈣和鐵質。　△糖蘿蔔、甜蘿蔔"]],"甜蜜":[["ㄊㄧㄢˊ ㄇㄧˋ","1.味道很甜美。[例]甜蜜香濃的水果，令人垂涎。\n2.比喻幸福美滿。[例]自從他們結婚後，生活一直很甜蜜。"]],"生命":[["ㄕㄥ ㄇㄧㄥˋ","1.生物生存的壽命。[例]生命是很可貴的，應該好好珍惜。\n2.某種活動延續的期間。[例]政治生命\n3.形容藝術作品十分靈活生動，非常有生氣。[例]這是一幅有生命的畫，畫中的人物呼之欲出。"]],"生存":[["ㄕㄥ ㄘㄨㄣˊ","活著，讓生命持續。[例]任何人都不能剝奪別人生存的權利。"]],"生意":[["ㄕㄥ ㄧˋ","生命力、生長的活力。[例]春雨滋長萬物，使大地顯得生意盎然。"],["ㄕㄥ ˙ㄧ","商人之間的交易、買賣。[例]他因為做生意失敗而負債累累。"]],"生態":[["ㄕㄥ ㄊㄞˋ","1.生物圈內的生物，不論是同種或異種，彼此間都會相互影響，而生物和其生存的環境 ，也會發生相互作用，這些現象稱為「生態」。[例]保護野生動物，才能維持自然生態的平衡。\n2.比喻某特定環境中各組成因素之間的互動現象。[例]政治生態"]],"生日":[["ㄕㄥ ㄖˋ","誕生之日。[例]為了慶祝生日，他請了許多同學來參加派對。"]],"生氣":[["ㄕㄥ ㄑㄧˋ","1.生動活潑的氣象。[例]生氣勃勃_x000D_\n2.發怒。[例]他屢勸不聽，又一意孤行，實在讓人生氣。"]],"生活":[["ㄕㄥ ㄏㄨㄛˊ","1.生存。[例]我們生活在這個世界上，應該時時懷著感謝的心。\n2.泛指一切飲食起居等方面的情況、境遇。[例]他是個不慕名利的人，因此生活過得極其平淡。"]],"生涯":[["ㄕㄥ ㄧㄚˊ","原指人的生命有止境。今用以指所過的生活或所經歷的人生。語本《莊子．養生主》。[例]他對自己的生涯已經做了妥善的規劃，現在正一步步的朝目標與理想邁進。"]],"生疏":[["ㄕㄥ ㄕㄨ","1.不熟悉、陌生、疏遠。[例]人地生疏\n2.不熟練。[例]他已經很久沒跳舞了，所以對舞步有些生疏。"]],"生病":[["ㄕㄥ ㄅㄧㄥˋ","得病、害病。[例]平時注意衛生保健，可以減少許多生病的機會。"]],"生硬":[["ㄕㄥ ㄧㄥˋ","1.不自然。[例]看他跳舞的動作如此生硬，好像機器人一樣。\n2.語文生澀、不流暢。[例]這篇文章語辭生硬，內容貧乏，難怪評價不高。"]],"生長":[["ㄕㄥ ㄓㄤˇ","發育成長。[例]植物的生長，少不了陽光、空氣和水分。"]],"產品":[["ㄔㄢˇ ㄆㄧㄣˇ","生產的物品。[例]這家廠商專門研發高科技產品。"]],"產生":[["ㄔㄢˇ ㄕㄥ","出現、發生。[例]親子之間如果無法溝通，將會產生代溝。"]],"甦醒":[["ㄙㄨ ㄒㄧㄥˇ","從昏迷中醒過來。[例]經過醫生的急救處理，休克的傷患總算甦醒了過來。"]],"用力":[["ㄩㄥˋ ㄌㄧˋ","使勁出力。[例]這櫃子太重了，要大家一起用力才能抬起來。"]],"用功":[["ㄩㄥˋ ㄍㄨㄥ","勤加修習。多指求學而言。[例]要有好的表現，就必須努力用功，勤勉學習。"]],"用心":[["ㄩㄥˋ ㄒㄧㄣ","1.認真、盡心。[例]凡事用心做，才能有所收穫。\n2.存心、居心。[例]別有用心"]],"用料":[["ㄩㄥˋ ㄌㄧㄠˋ","使用的材料。[例]這家牛肉麵館用料實在，口味獨特，所以生意十分興隆。"]],"用法":[["ㄩㄥˋ ㄈㄚˇ","使用的方法。[例]這種血壓器的用法簡單，一般人就能自行操作。"]],"用餐":[["ㄩㄥˋ ㄘㄢ","吃飯、進食。[例]他習慣在用餐後泡杯茶喝。"]],"甩掉":[["ㄕㄨㄞˇ ㄉㄧㄠˋ","丟掉、拋棄。[例]他一進門便甩掉鞋子，然後倒在沙發上。"]],"甩餅":[["ㄕㄨㄞˇ ㄅㄧㄥˇ","印度甩餅，是馬來西亞印度裔發明的食物。做法是將和好的小片麵皮，多次旋轉向上拋甩，形成大而薄的圓餅，再放到鍋上烙熟。[例]每次去吃印度料理，一口甩餅一口咖哩，美味極了。"]],"由來":[["ㄧㄡˊ ㄌㄞˊ","事情的起源。[例]老師為我們解說這個典故的由來。"]],"由於":[["ㄧㄡˊ ㄩˊ","表示原因或理由。[例]由於人手不足，公司決定再請幾名工讀生來幫忙。"]],"由衷":[["ㄧㄡˊ ㄓㄨㄥ","出於本心、真心誠意。[例]我由衷的感謝您多年來的照顧。"]],"甲殼":[["ㄐㄧㄚˇ ㄎㄜˊ","昆蟲或蝦、蟹、龜等動物的外殼。質地堅硬，有保護身體的作用。[例]海龜馱負著厚重的甲殼，在海灘上緩慢爬行。"]],"甲蟲":[["ㄐㄧㄚˇ ㄔㄨㄥˊ","鞘翅目昆蟲的統稱。前翅革質化，靜止時，左右翅在背上正中線合而為一，並可蓋住膜質後翅和腹部。甲蟲類約有二百科，分布廣泛，除南北極外，棲息地遍布全球。[例]甲蟲是完全變態的昆蟲，牠們的生活史包括卵、幼蟲、蛹、成蟲四個階段。"]],"申請":[["ㄕㄣ ㄑㄧㄥˇ","1.向上級或相關單位說明理由，提出請求。[例]凡申請加入本會會員者，每年均享有各項優惠活動。\n2.人民對政府或下級對上級的請求事項。[例]他提出的調職申請，很快就得到上級的批准。"]],"男子":[["ㄋㄢˊ ㄗˇ","泛稱男性。[例]成年男子、男子雙打"]],"男生":[["ㄋㄢˊ ㄕㄥ","對年輕男子的稱呼。[例]這一班總共有三十位同學，男生就占了二十位。"]],"男裝":[["ㄋㄢˊ ㄓㄨㄤ","男性穿著的服裝。[例]這家百貨公司正舉辦秋季男裝展示會，吸引了不少的顧客。"]],"留住":[["ㄌㄧㄡˊ ㄓㄨˋ","留下、留止。[例]他吩咐家人先把客人留住，辦完事後他會儘快趕回家來。"]],"留戀":[["ㄌㄧㄡˊ ㄌㄧㄢˋ","有所眷戀而捨不得。[例]留戀不已"]],"留言":[["ㄌㄧㄡˊ ㄧㄢˊ","用書面形式留下要說的話。[例]我們的社團成員來去不定，只有藉著留言來互相傳達訊息。"]],"畢恭畢敬":[["ㄅㄧˋ ㄍㄨㄥ ㄅㄧˋ ㄐㄧㄥˋ","形容極為恭敬。[例]他雖然當上了董事長，一見到老師仍然畢恭畢敬。"]],"畢業":[["ㄅㄧˋ ㄧㄝˋ","1.在學校或訓練班修完規定的課程。[例]他研究所畢業後，決定回國貢獻所學。\n2.籃球比賽中，犯規滿五次，被罰出場戲稱為「畢業」。[例]球賽還沒結束，對方已有兩個主將犯滿畢業了。"]],"畢生":[["ㄅㄧˋ ㄕㄥ","終生、一輩子。[例]這次可怕的經歷，使他畢生難忘。"]],"略勝一籌":[["ㄌㄩㄝˋ ㄕㄥˋ ㄧ ㄔㄡˊ","比喻兩相比較，其中一方稍微高明一些。[例]地主隊在球技方面略勝一籌，因而得以晉級爭奪冠亞軍。"]],"番茄":[["ㄈㄢ ㄑㄧㄝˊ","植物名。一年生草本。莖略呈蔓生狀態，高約一公尺，葉互生，羽狀複葉。夏季開黃色花朵。果實亦稱為「番茄」，呈扁圓形或小球形，為紅色或黃綠色漿果，可供食用或製成果汁。　◎◎"]],"畫圖":[["ㄏㄨㄚˋ ㄊㄨˊ","描繪、繪製圖像。[例]空閒時從事畫圖，不但可以怡情養性，也可以展現才華。"]],"畫廊":[["ㄏㄨㄚˋ ㄌㄤˊ","專門展示圖畫等藝術作品的場所。[例]這家畫廊經常展出本土畫家的作品，對宣揚臺灣鄉土藝術頗有頁獻。"]],"畫畫":[["ㄏㄨㄚˋ ㄏㄨㄚˋ","畫圖、作畫。[例]他非常喜歡畫畫，從小就立志要做個畫家。"]],"異口同聲":[["ㄧˋ ㄎㄡˇ ㄊㄨㄥˊ ㄕㄥ","大家都說同樣的話。形容眾口一詞，意見相同。[例]眾人異口同聲地要求老闆改善工作環境的品質。"]],"異樣":[["ㄧˋ ㄧㄤˋ","不一樣、不平常。[例]他奇特的穿著打扮，每每引起他人投以異樣的眼光。"]],"當之無愧":[["ㄉㄤ ㄓ ㄨˊ ㄎㄨㄟˋ","夠資格承擔得起某種榮譽或稱號，不必感到慚愧。[例]他平日熱心公益，樂善好施，當選好人好事代表實在當之無愧。"]],"當作":[["ㄉㄤˋ ㄗㄨㄛˋ","看成、認作。[例]他把我當作親生兒子一樣，百般呵護。　△當做"]],"當務之急":[["ㄉㄤ ㄨˋ ㄓ ㄐㄧˊ","當前迫切需要處理的事。語本《孟子．盡心上》。[例]目前市政建設的當務之急，在改善日益嚴重的交通問題。"]],"當天":[["ㄉㄤ ㄊㄧㄢ","即日、這天。[例]自從高鐵通車以後，臺北、高雄兩地，當天即可往返。"]],"當心":[["ㄉㄤ ㄒㄧㄣ","謹慎、留心、注意。[例]出門在外，凡事要當心。"]],"當成":[["ㄉㄤˋ ㄔㄥˊ","視同、認為。[例]別把教室當成遊樂場所。"]],"當時":[["ㄉㄤ ㄕˊ","從前、那時候。[例]他把事發當時的狀況，仔細的描述了一遍。"]],"當晚":[["ㄉㄤ ㄨㄢˇ","當天晚上。[例]回國當晚，他急著分享這次旅遊的所見所聞，滔滔不絕地講了一晚。"]],"當機立斷":[["ㄉㄤ ㄐㄧ ㄌㄧˋ ㄉㄨㄢˋ","掌握時機，立刻做出決斷。[例]登山領隊見山中天候惡劣，當機立斷，率領全隊下山。"]],"當然":[["ㄉㄤ ㄖㄢˊ","理應如此。[例]憑著多年的情誼，我當然會全力幫助你度過難關。"]],"當鋪":[["ㄉㄤˋ ㄆㄨˋ","收取貴重物品以為抵押，而出借現款給典當者的店鋪。[例]她急需用錢，只好拿些首飾向當鋪典當。"]],"當面":[["ㄉㄤ ㄇㄧㄢˋ","面對面、當著彼此的面。[例]雙方當面把事情解釋清楚，才不致產生誤會。"]],"疆土":[["ㄐㄧㄤ ㄊㄨˇ","國家的領土。[例]假如沒有軍人在前線捍衛疆土，百姓將何以安居樂業？"]],"疆界":[["ㄐㄧㄤ ㄐㄧㄝˋ","國界、邊界。[例]許多河流、山脈常是國與國之間的天然疆界。"]],"疊羅漢":[["ㄉㄧㄝˊ ㄌㄨㄛˊ ㄏㄢˋ","一種雜技表演。人上架人，可變化各種式樣。[例]這次慶典中的疊羅漢表演，博得了大家熱烈的掌聲。"]],"疏失":[["ㄕㄨ ㄕ","疏忽失誤。[例]有關單位承認對這件事的處理有疏失，正想辦法予以補救。"]],"疏導":[["ㄕㄨ ㄉㄠˇ","1.使淤塞的河道暢通。[例]大禹採取疏導的方法治理洪水，才解決了多年的水患。\n2.引導使通暢。[例]交通警察在路口指揮，疏導交通。"]],"疏通":[["ㄕㄨ ㄊㄨㄥ","1.疏導水流，使其通暢。[例]疏通溝渠\n2.調解雙方的爭執。[例]這場糾紛若不是他居中疏通排解，恐怕很難收場。"]],"疏離":[["ㄕㄨ ㄌㄧˊ","對周圍的人、事、物，不親近、關心。[例]自從畢業後，他和同學漸漸疏離了。"]],"疏鬆":[["ㄕㄨ ㄙㄨㄥ","1.鬆散不緊密。[例]一陣強風吹過後，使他原本疏鬆的頭髮，更加凌亂了。\n2.使鬆散。[例]疏鬆土壤，有益作物生長。"]],"疑問":[["ㄧˊ ㄨㄣˋ","令人質疑的問題。[例]如有任何疑問，請打電話至本中心查詢。"]],"疑惑":[["ㄧˊ ㄏㄨㄛˋ","懷疑、不明白。[例]他用疑惑的眼神望著我，好像對我的決定沒什麼信心。"]],"疤痕":[["ㄅㄚ ㄏㄣˊ","傷口癒合後的痕跡。[例]上次的刀傷，使他手上留下了一道疤痕。"]],"疫情":[["ㄧˋ ㄑㄧㄥˊ","流行性或急性傳染病的發生與發展情況。[例]這波流感的疫情非常嚴峻，請小心防範。"]],"疲倦":[["ㄆㄧˊ ㄐㄩㄢˋ","勞累困倦。[例]從事校對工作，眼睛很容易疲倦。"]],"疲憊":[["ㄆㄧˊ ㄅㄟˋ","極為疲勞困倦。[例]走了三天的山路，所有的隊員都已疲憊不堪。"]],"疲於奔命":[["ㄆㄧˊ ㄩˊ ㄅㄣ ㄇㄧㄥˋ","指事情繁多，奔波勞累，不堪其苦。[例]由於身兼數職，使得他疲於奔命，體力不堪負荷。"]],"疲累":[["ㄆㄧˊ ㄌㄟˋ","疲倦困怠。[例]經過一場家庭變故，他感到身心萬分疲累。"]],"疲軟":[["ㄆㄧˊ ㄖㄨㄢˇ","1.疲乏倦怠，不振作。[例]登山歸來，只覺得一身疲軟，什麼事都不想做。\n2.形容金錢交易不熱絡。[例]由於經濟不景氣，最近股票市場交易呈現疲軟狀態。"]],"疼惜":[["ㄊㄥˊ ㄒㄧˊ","疼愛、憐惜。[例]他懂事又貼心，很得老人家的疼惜。"]],"疼愛":[["ㄊㄥˊ ㄞˋ","關切憐愛。[例]奶奶最疼愛這個唯一的小孫女。"]],"疼痛":[["ㄊㄥˊ ㄊㄨㄥˋ","痛。[例]不要輕忽身體上的疼痛，它有可能是疾病的警訊。"]],"疾駛":[["ㄐㄧˊ ㄕˇ","快速行駛。[例]警車一路鳴笛疾駛，以追趕逃竄的歹徒。"]],"病危":[["ㄅㄧㄥˋ ㄨㄟˊ","病情嚴重而有生命危險。[例]他接到父親病危的通知，內心萬分悲慟。"]],"病媒":[["ㄅㄧㄥˋ ㄇㄟˊ","傳染疾病的媒介。當病原體經由節肢動物或無脊椎動物而傳播到人身上時，即稱該種媒介動物為「病媒」。[例]登革熱是以斑蚊為病媒傳到人體上。"]],"病情":[["ㄅㄧㄥˋ ㄑㄧㄥˊ","疾病變化的情況。[例]他的病情不穩定，你可要多留意！"]],"病毒":[["ㄅㄧㄥˋ ㄉㄨˊ","一種能使有機體致病的細小微生物。僅能由電子顯微鏡觀察到。沒有生殖能力，只能在活寄主的細胞內增殖。[例]一般感冒都是受到了濾過性病毒感染所致。"]],"病源":[["ㄅㄧㄥˋ ㄩㄢˊ","發病的原因。[例]找出病源，對症下藥，才能早日康復。"]],"痊癒":[["ㄑㄩㄢˊ ㄩˋ","疾病治好，恢復健康。[例]在醫生細心的診療下，他多年的痼疾終於痊癒了。"]],"痕跡":[["ㄏㄣˊ ㄐㄧ","事物留下的跡象。[例]警方根據竊賊遺留在現場的痕跡，順利偵破此案。"]],"痘瘡":[["ㄉㄡˋ ㄔㄨㄤ","→天花"]],"痛哭失聲":[["ㄊㄨㄥˋ ㄎㄨ ㄕ ㄕㄥ","傷心大哭，以致氣結無法出聲。[例]聽到親人這起噩耗，罹難者的家屬們莫不痛哭失聲。"]],"痛哭流涕":[["ㄊㄨㄥˋ ㄎㄨ ㄌㄧㄡˊ ㄊㄧˋ","形容非常悲痛而流淚大哭。語本《漢書．卷四十八．賈誼傳》。[例]看到自己辛苦經營的事業毀於一旦，他不禁痛哭流涕，傷心欲絕。"]],"痛苦":[["ㄊㄨㄥˋ ㄎㄨˇ","肉體或精神上所感受的苦楚。[例]痛苦萬分、痛苦不堪"]],"痛飲":[["ㄊㄨㄥˋ ㄧㄣˇ","暢飲、痛快的喝。[例]難得大家齊聚一堂，何不趁現在好好痛飲一番呢？"]],"痱子":[["ㄈㄟˋ ˙ㄗ","→痱"]],"瘋狂":[["ㄈㄥ ㄎㄨㄤˊ","1.精神錯亂、舉止失常。[例]聽到兒子出了車禍，他瘋狂似的跑向醫院。\n\t\n2.極端狂熱、毫無節制。[例]百貨公司周年慶大折扣活動期間，許多民眾紛紛瘋狂大採購。"]],"瘦小":[["ㄕㄡˋ ㄒㄧㄠˇ","身材瘦、個頭小。[例]身材瘦小、體型瘦小"]],"瘦弱":[["ㄕㄡˋ ㄖㄨㄛˋ","身體消瘦、虛弱。[例]醫生說她太瘦弱了，要多補充營養。"]],"瘧疾":[["ㄋㄩㄝˋ ㄐㄧˊ","由瘧蚊散播瘧原蟲所引起的急性傳染病。其症狀有週期性的發冷發熱、大量出汗、頭痛、口渴、全身無力及溶血等現象。[例]熱帶地區因氣候條件終年有利蚊子生長，所以往往是瘧疾疫區。　△打擺子、冷熱病"]],"療傷":[["ㄌㄧㄠˊ ㄕㄤ","治療、調養傷勢。[例]他的傷勢不輕，需要休息一段時間來療傷。"]],"療癒":[["ㄌㄧㄠˊ ㄩˋ","治好傷痛。[例]這些優美的樂曲療癒了許多悲傷無助的心靈。"]],"癌症":[["ㄞˊ ㄓㄥˋ","→癌"]],"登報":[["ㄉㄥ ㄅㄠˋ","在報紙上刊載消息，或發表意見。[例]登報聲明、登報作廢"]],"登記":[["ㄉㄥ ㄐㄧˋ","記錄。[例]戶籍登記、所有權登記、考試成績登記"]],"登錄":[["ㄉㄥ ㄌㄨˋ","註冊或登記。[例]她將新書登錄後歸放到書架上。"]],"登陸":[["ㄉㄥ ㄌㄨˋ","從海上行進至陸地。[例]這次的強烈颱風，預計將在晚上七時登陸。"]],"發問":[["ㄈㄚ ㄨㄣˋ","提出問題。[例]同學們有不懂的地方，請舉手發問。"]],"發展":[["ㄈㄚ ㄓㄢˇ","開展，逐漸進展。[例]良好的教育是孩童身心健全發展的重要關鍵。_x000D_"]],"發怒":[["ㄈㄚ ㄋㄨˋ","生氣動怒。[例]他脾氣不好，動不動就會發怒。"]],"發愁":[["ㄈㄚ ㄔㄡˊ","因沒有主意或辦法而感到憂愁。[例]他正為籌不到學費而發愁。"]],"發抖":[["ㄈㄚ ㄉㄡˇ","身體因寒冷、恐懼或憤怒而顫抖。[例]小弟不小心打破了父親心愛的古董花瓶，氣得父親渾身發抖。"]],"發掘":[["ㄈㄚ ㄐㄩㄝˊ","1.挖掘。[例]考古學家從古墓中發掘出許多珍貴文物。_x000D_\n2.發現、引出。[例]發掘人才"]],"發明":[["ㄈㄚ ㄇㄧㄥˊ","1.創造出前所未有的事物。_x000D_\n2.被創造出來的新事物或新方法。[例]他的這項發明，引起科學界的注意。_x000D_\n3.具有獨創性的見解、闡發。[例]在他這本書中，對孔子的理論學說頗有發明，值得一提。"]],"發炎":[["ㄈㄚ ㄧㄢˊ","身體因受傷遭細菌感染而產生發紅、腫脹或疼痛等症狀。[例]傷口發炎"]],"發現":[["ㄈㄚ ㄒㄧㄢˋ","1.找到別人從未見過的事物、地方或道理。[例]哥倫布發現新大陸。\n2.察覺、發覺。[例]守衛發現有外人企圖潛入社區內行竊。"]],"發癢":[["ㄈㄚ ㄧㄤˇ","1.皮膚受外物刺激，而產生想要抓搔的感覺。[例]他因皮膚過敏而全身發癢。\n2.內心對外在刺激產生某種無法自抑的反應。[例]她看見自己喜愛的物品卻無力購買時，心裡直發癢。"]],"發胖":[["ㄈㄚ ㄆㄤˋ","身體變胖。[例]由於飲食不節制，他已經逐漸發胖了。"]],"發脾氣":[["ㄈㄚ ㄆㄧˊ ㄑㄧˋ","生氣、發怒。[例]他怎麼不先問清楚事情的真相就亂發脾氣？"]],"發號施令":[["ㄈㄚ ㄏㄠˋ ㄕ ㄌㄧㄥˋ","發布指示、命令。[例]這個企劃案由他負責統籌並發號施令。"]],"發行":[["ㄈㄚ ㄒㄧㄥˊ","發布通行。[例]發行紙幣、發行書報、發行股票"]],"發覺":[["ㄈㄚ ㄐㄩㄝˊ","察覺、發現。[例]發覺真相、發覺錯誤"]],"發言":[["ㄈㄚ ㄧㄢˊ","1.表達意見、發表言論。[例]請大家踴躍發言。\n2.發表的言論。[例]他在研討會上的發言極為中肯。"]],"發誓":[["ㄈㄚ ㄕˋ","立下誓言，莊重地表示決心或提出保證。[例]我發誓不達目的決不放棄。"]],"發財":[["ㄈㄚ ㄘㄞˊ","1.獲得很多金錢。[例]他為了發財，不惜從事投機事業。\n2.詢問別人工作情況的客套話。[例]您最近在哪兒發財？"]],"發酵":[["ㄈㄚ ㄒㄧㄠˋ","有機物質受細菌或酵母菌的作用，發生化學變化，產生酒精的過程。[例]酵母菌行發酵作用時，可以將糖分解為酒精和二氧化碳。"]],"發電":[["ㄈㄚ ㄉㄧㄢˋ","1.產生電力。[例]水力發電、核能發電_x000D_\n2.拍發電報。[例]美國總統大選揭曉，各國元首皆發電祝賀。"]],"白天":[["ㄅㄞˊ ㄊㄧㄢ","從太陽升起，到太陽落下的時段。[例]春分和秋分這兩天，白天和夜晚的時間一樣長。"]],"白板":[["ㄅㄞˊ ㄅㄢˇ","1.麻將牌的牌面只有一方形框，沒有其他色彩或圖案者。　△白皮_x000D_\n2.一種非巴比妥鹽類的安眠鎮靜藥。藥效強，可抑制中樞神經，有鎮靜、催眠的作用，容易使人上癮。如果服食過量，會使人呼吸困難、發冷、休克，甚至死亡。_x000D_\n3.一種用白色顏料製成的黑板。以白板筆代替粉筆書寫。[例]學校教室自從換了白板後，不再有粉筆灰四處飛揚的情形了。"]],"白璧無瑕":[["ㄅㄞˊ ㄅㄧˋ ㄨˊ ㄒㄧㄚˊ","潔白玉上毫無瑕疵。比喻人或事物沒有缺點。[例]對自己品行修養的期許，要求達到如白璧無瑕般的境界。"]],"白皙":[["ㄅㄞˊ ㄒㄧ","形容人的皮膚潔白。[例]這件禮服與她白皙的皮膚十分搭配。_x000D_"]],"白砂":[["ㄅㄞˊ ㄕㄚ","1.一種含矽的礦砂。主要成分為二氧化矽，是製造玻璃的主要原料。\n2.指白砂糖。[例]糖的分類上，特砂與白砂都是指白糖而言。"]],"白紗":[["ㄅㄞˊ ㄕㄚ","白色細薄的紡織品。常借指新娘禮服。[例]她是我們班第一位披上白紗，走上紅毯的人。"]],"白紙":[["ㄅㄞˊ ㄓˇ","1.白色的紙。[例]白紙寫黑字\n2.沒有任何文字或圖案的空白紙。[例]這是一張白紙，上面一個字也沒有。"]],"白色":[["ㄅㄞˊ ㄙㄜˋ","像雪或乳汁般素淨的顏色。[例]白色往往被拿來當作純潔的象徵。"]],"白茫茫":[["ㄅㄞˊ ㄇㄤˊ ㄇㄤˊ","一片白色、朦朧不清的樣子。[例]起霧了，四周白茫茫的一片，所有的路都看不清了。"]],"白蟻":[["ㄅㄞˊ ㄧˇ","動物名。昆蟲綱等翅目。已知者約一千九百種，產於熱帶及亞熱帶。外形似螞蟻，但體色較淺，身體較柔軟，多以木質物為食。[例]這櫃子已被白蟻蛀得差不多了，只好丟掉。"]],"白袍":[["ㄅㄞˊ ㄆㄠˊ","白色的袍子。今或借指醫護人員。[例]醫生穿上白袍，就是一種專業與責任的象徵。"]],"白費":[["ㄅㄞˊ ㄈㄟˋ","付出心力而沒有得到效果。[例]老師教我們的苦心不會白費，我們必更加努力用功以回報之。"]],"白雪":[["ㄅㄞˊ ㄒㄩㄝˇ","指雪，雪色純白，所以稱為「白雪」。[例]接連幾天，天空飄著棉絮般的白雪。"]],"白雲":[["ㄅㄞˊ ㄩㄣˊ","白色的雲。[例]天上飄著朵朵白雲。"]],"百倍":[["ㄅㄞˇ ㄅㄟˋ","1.一百倍。[例]因為投資正確，他的資產在兩年內竟然暴增百倍。\n2.形容程度加深很多。[例]勇氣百倍"]],"百合花":[["ㄅㄞˇ ㄏㄜˊ ㄏㄨㄚ","百合所開的花。花蓋呈漏斗狀，花被六片，有多種花色。[例]小房間內，插上這幾朵百合花，頓時滿室生香，溫馨起來。　◎"]],"百姓":[["ㄅㄞˇ ㄒㄧㄥˋ","泛指一般平民、國民。[例]只准州官放火，不准百姓點燈。"]],"百寶箱":[["ㄅㄞˇ ㄅㄠˇ ㄒㄧㄤ","收藏各種寶物的匣子。[例]這是妹妹心愛的百寶箱，不可隨便翻動。"]],"百年":[["ㄅㄞˇ ㄋㄧㄢˊ","1.形容時間、年代久遠。[例]百年老店\n2.死去，年壽到了終點。[例]等我百年之後，請幫忙將這棟房子捐給慈善機構。"]],"百科全書":[["ㄅㄞˇ ㄎㄜ ㄑㄩㄢˊ ㄕㄨ","普遍搜羅各門類的知識，用分別條目的方式加以簡明介紹的工具書。內容有綜合性的、專業性的、國家與地區的，還有專為兒童寫的。體例上，有分類編排的，也有按條目的英文字母或中文筆畫順序編排的。我國古代類書，如宋朝的《太平御覽》、明朝的《永樂大典》等，都具有百科全書的性質。[例]百科全書是一所沒有圍牆的大學。"]],"百老匯":[["ㄅㄞˇ ㄌㄠˇ ㄏㄨㄟˋ","一條縱貫美國紐約市曼哈頓區的街道。全長二十五公里，街巷間劇院林立，是著名的音樂與戲劇中心，亦是全球戲劇界的焦點所在。許多美國著名的電影明星，都崛起於此。§英Broadway"]],"百貨":[["ㄅㄞˇ ㄏㄨㄛˋ","總稱以衣著、器皿等日常生活用品為主的各種商品。[例]百貨店、百貨公司"]],"百貨公司":[["ㄅㄞˇ ㄏㄨㄛˋ ㄍㄨㄥ ㄙ","集各類商品於一處，依其類別分部售賣的商店。較一般百貨店規模大、貨品多。西元1830年首創於法國，今普及世界各大都市。[例]百貨公司除了要講究賣場的設計外，服務人員的態度也是吸引顧客的重要因素。"]],"的確":[["ㄉㄧˊ ㄑㄩㄝˋ","確切真實。[例]這個故事的確很精彩，難怪會流傳至今。"]],"皇上":[["ㄏㄨㄤˊ ㄕㄤˋ","古代臣民對皇帝的尊稱。[例]古代百姓心目中的皇上，具有絕對的權威。"]],"皇室":[["ㄏㄨㄤˊ ㄕˋ","皇帝的家族。[例]中國有許多朝代都因皇室內亂而滅亡。"]],"皇帝":[["ㄏㄨㄤˊ ㄉㄧˋ","秦朝以後對天子的稱號。[例]楚漢相爭後，天下諸侯將相共同推尊漢王為皇帝。"]],"皎潔":[["ㄐㄧㄠˇ ㄐㄧㄝˊ","明亮潔白。[例]今晚的月色分外皎潔。"]],"皮夾":[["ㄆㄧˊ ㄐㄧㄚˊ","用薄軟的皮革製成的扁平小錢包。[例]昨天在公車上掉了一只皮夾，損失不小。"]],"皮球":[["ㄆㄧˊ ㄑㄧㄡˊ","用橡皮製成具有彈性的球。[例]很多小朋友喜歡玩踢皮球的遊戲。"]],"皮膚":[["ㄆㄧˊ ㄈㄨ","覆蓋於高等動物表面的構造。由外而內分為表皮、真皮和皮下組織三層，具有保護、呼吸、排泄、調節體溫等功用。[例]他因為食物過敏，皮膚上長出一粒粒的疹子。"]],"皮蛋":[["ㄆㄧˊ ㄉㄢˋ","1.以石灰黏土、食鹽、稻殼及水混合，包裹在雞、鴨蛋殼表面，所醃成的蛋製品。[例]皮蛋豆腐是一道常見的小菜。　△變蛋\n2.戲稱頑皮的小孩。[例]他小時候是個皮蛋，常常闖禍。"]],"皮開肉綻":[["ㄆㄧˊ ㄎㄞ ㄖㄡˋ ㄓㄢˋ","形容皮肉裂開，受傷嚴重的樣子。[例]那個流氓被人打得皮開肉綻，遍體鱗傷。"]],"皮革":[["ㄆㄧˊ ㄍㄜˊ","獸皮經過去毛、去脂等處理而製成的熟皮。[例]皮革可以做成各種皮製品，如皮鞋、皮包、皮衣、皮帶等。"]],"皺紋":[["ㄓㄡˋ ㄨㄣˊ","皮膚或物體的褶紋。[例]不知何時開始，媽媽光滑的臉上有了一條條細小的皺紋。"]],"皺褶":[["ㄓㄡˋ ㄓㄜˊ","物體因壓縮而顯出的褶紋。[例]這件褲子在腰部打了三道皺褶，穿起來寬鬆自在。"]],"盆栽":[["ㄆㄣˊ ㄗㄞ","栽種於盆中的花卉樹木，可作為擺設。[例]農業局鼓勵市民在頂樓陽臺廣植盆栽，讓屋頂成為花園。"]],"益友":[["ㄧˋ ㄧㄡˇ","指對自己工作、學習等有幫助的朋友。語本《論語．季氏》。[例]良師益友"]],"益處":[["ㄧˋ ㄔㄨˋ","好處。[例]適當的運動對身體有很大的益處。"]],"益蟲":[["ㄧˋ ㄔㄨㄥˊ","捕食害蟲，有益人類或農作物的蟲類。如蜂、蝶、蜻蜓。"]],"盎司":[["ㄤˋ ㄙ","量詞。英美計算重量的單位。分金衡、常衡兩種，金衡一盎司等於十二分之一磅，常衡一盎司等於十六分之一磅。§英ounce 　△英兩"]],"盎然":[["ㄤˋ ㄖㄢˊ","盈溢、充滿。[例]小弟天生好奇，對新奇的事物都一副興趣盎然的樣子。"]],"盒子":[["ㄏㄜˊ ˙ㄗ","1.有底、蓋可相合的盛物器皿。[例]請把那個裝針線的盒子放在縫紉機旁邊。\n2.一種麵粉製的北方食品。在兩片緊壓的麵皮中包裹內餡，烙熟後食用。[例]韭菜盒子"]],"盔甲":[["ㄎㄨㄟ ㄐㄧㄚˇ","盔，保護頭部的帽子。甲，保護身體的鎧甲。盔甲指古代戰士用來護身禦敵的戰服，多用金屬或皮革製成。[例]博物館近期將推出中古世紀武士的盔甲特展。　◎"]],"盛事":[["ㄕㄥˋ ㄕˋ","美好盛大的事。[例]四年一度的奧運會是世界體壇的盛事。"]],"盛大":[["ㄕㄥˋ ㄉㄚˋ","隆重、規模宏大。[例]電影公司為得獎者舉行了盛大的慶功宴。"]],"盛怒":[["ㄕㄥˋ ㄋㄨˋ","非常憤怒。[例]他當時在盛怒之下，幾乎失去理性。"]],"盛情":[["ㄕㄥˋ ㄑㄧㄥˊ","深厚的情意。[例]他這趟旅遊，對當地居民的盛情招待留下深刻的印象。"]],"盛意":[["ㄕㄥˋ ㄧˋ","隆盛的情意。[例]王老先生雖極力婉拒大家為他舉行的祝壽酒會，最後仍難辭盛意，不得不接受祝賀。"]],"盛極必衰":[["ㄕㄥˋ ㄐㄧˊ ㄅㄧˋ ㄕㄨㄞ","興隆強盛到極點，就會衰落破敗下來。[例]由歷史的發展情況來看，得知盛極必衰，是千古不變的道理。"]],"盛舉":[["ㄕㄥˋ ㄐㄩˇ","盛大的活動。[例]這次的募款活動，感謝各界善心人士共襄盛舉。"]],"盛行":[["ㄕㄥˋ ㄒㄧㄥˊ","廣泛流行。[例]近年來盛行少油、薄鹽與減糖的飲食觀念。"]],"盛開":[["ㄕㄥˋ ㄎㄞ","花朵開得茂盛。[例]院子裡的桂花盛開，香氣撲鼻。"]],"盛飯":[["ㄔㄥˊ ㄈㄢˋ","將飯裝入碗中。[例]這家自助餐廳顧客可以自己去盛飯。"]],"盜賊":[["ㄉㄠˋ ㄗㄟˊ","強盜竊賊。[例]這一帶常有盜賊出沒，最好不要前往旅遊。"]],"盡力":[["ㄐㄧㄣˋ ㄌㄧˋ","竭力。[例]凡事盡力就好，不要太在意結果了。"]],"盡責":[["ㄐㄧㄣˋ ㄗㄜˊ","盡力做好責任範圍內的事。[例]村長服務鄉里非常盡責，很受村民的愛戴。"]],"盡頭":[["ㄐㄧㄣˋ ㄊㄡˊ","終點、末端。[例]小路的盡頭是一大片黃澄澄的油菜花田，迎風搖曳。"]],"監牢":[["ㄐㄧㄢ ㄌㄠˊ","囚禁罪犯的牢獄。[例]他因犯罪被判十年徒刑，已於上個月押解至監牢服刑。"]],"監督":[["ㄐㄧㄢ ㄉㄨ","監察督導。[例]今日將有上級人員到工地來監督工程的進行。"]],"監禁":[["ㄐㄧㄢ ㄐㄧㄣˋ","因被收監而喪失自由。[例]他因殺人被判終身監禁。"]],"監考":[["ㄐㄧㄢ ㄎㄠˇ","監視考試，使應試者遵守紀律。[例]監考老師考前詳細地說明考場規則，避免考生違規。"]],"盤旋":[["ㄆㄢˊ ㄒㄩㄢˊ","1.旋轉、環繞。[例]老鷹盤旋於空中，虎視眈眈地尋找獵物。_x000D_\n2.徘徊逗留。[例]他在門外盤旋了老半天才離開。"]],"盤腿":[["ㄆㄢˊ ㄊㄨㄟˇ","坐時兩腿交叉彎曲平放在地面的姿勢。[例]盤腿而坐　◎"]],"盤飧":[["ㄆㄢˊ ㄙㄨㄣ","盤中的食物。[例]媽媽的手藝了得，三兩下就讓那些不起眼的食材變成精美的盤飧。"]],"盪漾":[["ㄉㄤˋ ㄧㄤˋ","振動起伏，多用於指水波、聲音。[例]水波盪漾"]],"目不暇給":[["ㄇㄨˋ ㄅㄨˋ ㄒㄧㄚˊ ㄐㄧˇ","形容諸多美好事物同時呈現，或景物變化太快，觀者來不及欣賞、分辨。[例]坐在火車裡欣賞沿途風光、窗外的美景一幕幕掠過，令人目不暇給。"]],"目不轉睛":[["ㄇㄨˋ ㄅㄨˋ ㄓㄨㄢˇ ㄐㄧㄥ","形容凝神注視的樣子。[例]上國文課時，同學們都目不轉睛的盯著臺上新來的老師。"]],"目光":[["ㄇㄨˋ ㄍㄨㄤ","1.眼神。[例]目光炯炯、目光如炸\n2.比喻人的識見。[例]目光短淺、目光如豆"]],"目標":[["ㄇㄨˋ ㄅㄧㄠ","1.目力的標的或目力能注視的地方。[例]打靶時，要瞄準目標，才能有好成績。\n2.工作或計畫中擬定要達到的標準。[例]目標既定，當然要全力以赴才好。"]],"目次":[["ㄇㄨˋ ㄘˋ","1.節目的次序。[例]按照今晚節目的目次，應該只剩一個節目了。\n2.書刊的目錄。[例]要了解一本書的大概內容，最好是查閱書前的目次。"]],"目的":[["ㄇㄨˋ ㄉㄧˋ","想要達到的目標。"]],"目的地":[["ㄇㄨˋ ㄉㄧˋ ㄉㄧˋ","想要到達的地方。[例]再十分鐘就到目的地了，大家要打起精神！"]],"目眩":[["ㄇㄨˋ ㄒㄩㄢˋ","因頭暈而眼花。[例]有些婦女在懷孕期間，會有頭暈目眩的症狀。"]],"目瞪口呆":[["ㄇㄨˋ ㄉㄥˋ ㄎㄡˇ ㄉㄞ","形容因驚嚇或錯愕而神情呆滯的樣子。[例]他被這場突如其來的車禍嚇得目瞪口呆。"]],"盯人":[["ㄉㄧㄥ ㄖㄣˊ","密切關注對方的一舉一動。[例]警方先以跟監盯人的方式鎖定毒梟，等確實掌握毒品的來源和動向之後，再一網打盡。"]],"盲人":[["ㄇㄤˊ ㄖㄣˊ","失明的人。[例]盲人可以藉由觸摸點字來閱讀書籍。"]],"盲目":[["ㄇㄤˊ ㄇㄨˋ","比喻認識不清，心無定見。[例]假若盲目的做出這個決定，恐怕會造成公司很大的損失。"]],"盲腸炎":[["ㄇㄤˊ ㄔㄤˊ ㄧㄢˊ","由闌尾炎引起，依發病的緩急，分為急性盲腸炎和慢性盲腸炎。有腹痛、嘔吐、噁心等症狀，治療方法以闌尾切除手術為主。[例]盲腸炎是因闌尾的管道發生阻塞，感染細菌所引起。　△闌尾炎"]],"直接":[["ㄓˊ ㄐㄧㄝ","沒有轉折，不必透過中間的人事物。[例]有什麼問題可以直接告訴我，不必顧慮。"]],"直爽":[["ㄓˊ ㄕㄨㄤˇ","性情坦率豪爽。[例]王伯伯是個道地的北方人，個性非常直爽。"]],"直率":[["ㄓˊ ㄕㄨㄞˋ","性情直爽不虛偽。[例]他個性直率，從不拘泥小節。"]],"直行":[["ㄓˊ ㄒㄧㄥˊ","依直線行走。[例]沿這條路往前直行，就會到達停車場。"]],"相伴":[["ㄒㄧㄤ ㄅㄢˋ","互相伴隨、陪伴。[例]她一下班就回家與母親相伴。"]],"相似":[["ㄒㄧㄤ ㄙˋ","相像。[例]他和父親長得很相似，好像是從同一個模子印出來的。"]],"相信":[["ㄒㄧㄤ ㄒㄧㄣˋ","1.信任，認為可以信賴。[例]他這個人誠實可靠，值得相信。\n2.認為確實如此而不懷疑。[例]經過這次教訓，我相信大家不會再犯同樣的錯誤了。"]],"相偕":[["ㄒㄧㄤ ㄒㄧㄝˊ","一起、一同。[例]這次的觀摩會，她們將相偕出席。"]],"相傳":[["ㄒㄧㄤ ㄔㄨㄢˊ","1.長期以來經眾人輾轉傳述。[例]湘竹上的斑點，相傳是娥皇、女英的眼淚。\n2.傳授。[例]他家做豆腐的手藝是代代相傳的。"]],"相像":[["ㄒㄧㄤ ㄒㄧㄤˋ","有共同或相似之處。[例]這對父子容貌十分相像，簡直是同一模子印出來的。"]],"相反":[["ㄒㄧㄤ ㄈㄢˇ","彼此互為反面。[例]她們二人的意見常常相反，因此很難相互協調。"]],"相得益彰":[["ㄒㄧㄤ ㄉㄜˊ ㄧˋ ㄓㄤ","彼此互相烘托，更能突顯出各自的優點。[例]這座花園奇特的屋舍造型，加上盛放的萬紫千紅，互相輝映，真是相得益彰。"]],"相戀":[["ㄒㄧㄤ ㄌㄧㄢˋ","彼此愛慕。[例]他們相戀已有五年，打算要結婚。"]],"相撲":[["ㄒㄧㄤ ㄆㄨ","1.雙方以徒手撲倒對方的遊戲。類似現今的摔跤。[例]小時候，爸爸常帶著我們兄弟玩相撲的遊戲。\n2.一種流行於日本的摔跤運動。參賽的人身體肥胖，以將對手推出場外或摔倒對方，使其肘、膝或肩、背著地為勝。[例]相撲不只是日本人喜愛觀賞的競技，也是他們文化的一部分。"]],"相擁而泣":[["ㄒㄧㄤ ㄩㄥˇ ㄦˊ ㄑㄧˋ","因為情緒激動而互相擁抱哭泣。[例]空難生還者一見到親人，不禁相擁而泣。"]],"相片":[["ㄒㄧㄤˋ ㄆㄧㄢˋ","照片，攝影後沖印出的紙片。[例]教室後方掛有一張班上同學參加合唱比賽時合照的相片。"]],"相異":[["ㄒㄧㄤ ㄧˋ","不同。[例]在團體裡意見相異時，雙方應互相溝通，尋求解決的途徑。"]],"相當":[["ㄒㄧㄤ ㄉㄤ","1.雙方差不多。[例]二位候選人的條件相當，這場選戰將會非常激烈。\n2.大致等於。[例] 1公斤相當於3.2磅。\n3.非常。[例]她進國樂社不到一年，彈奏古箏的指法已經相當純熟。"]],"相簿":[["ㄒㄧㄤˋ ㄅㄨˋ","存放相片的簿本。[例]相簿內的透明膠膜，可有效保護相片避免受損。"]],"相聚":[["ㄒㄧㄤ ㄐㄩˋ","彼此會合、同在一起。[例]我長年在外工作，只有逢年過節才會返鄉與家人相聚。"]],"相處":[["ㄒㄧㄤ ㄔㄨˇ","在生活中接觸、往來。[例]她的個性隨和，很容易與人相處。"]],"相親相愛":[["ㄒㄧㄤ ㄑㄧㄣ ㄒㄧㄤ ㄞˋ","彼此親近關懷。[例]同學間應該相親相愛，互助合作。"]],"相貌":[["ㄒㄧㄤˋ ㄇㄠˋ","容貌、長相。[例]相貌堂堂"]],"相距":[["ㄒㄧㄤ ㄐㄩˋ","相隔、彼此間距離。[例]我們即使相距千里，友情依舊堅定。"]],"相較":[["ㄒㄧㄤ ㄐㄧㄠˋ","互相比較。[例]相較於購物逛街，我比較喜歡到郊外踏青。"]],"相逢":[["ㄒㄧㄤ ㄈㄥˊ","彼此碰見。[例]能在異鄉與老友相逢，真是倍感親切。"]],"相遇":[["ㄒㄧㄤ ㄩˋ","相逢、碰上。[例]父親回家後，高興的提起他和老友相遇的事。"]],"盼望":[["ㄆㄢˋ ㄨㄤˋ","殷切的等候、期望。[例]她一心盼望兒子早日學成歸國。"]],"省下":[["ㄕㄥˇ ㄒㄧㄚˋ","由預定的消費中節約下來。[例]他省下自己的零用錢購買母親節禮物。"]],"省事":[["ㄒㄧㄥˇ ㄕˋ","處理政務。[例]總統年事已高，任期屆滿後將不再繼續省事問政。"],["ㄕㄥˇ ㄕˋ","減省辦事的手續。[例]使用免洗餐具雖然省事，卻造成了環境汙染。"]],"省力":[["ㄕㄥˇ ㄌㄧˋ","節省氣力的耗費。[例]騎腳踏車沿著山坡下山，非常輕鬆省力。"]],"省略":[["ㄕㄥˇ ㄌㄩㄝˋ","省去、略去。[例]時間相當緊迫，因此他省略細節，只是提綱挈領，扼要敘述。"]],"省電":[["ㄕㄥˇ ㄉㄧㄢˋ","減少電力的耗費。[例]選用省電節能的電氣產品，既環保又省錢。"]],"眉毛":[["ㄇㄟˊ ㄇㄠˊ","前額與上眼瞼之間，左右各一的橫生細毛。有防止上額汗水進入眼睛的作用。[例]她的眉毛稀疏，顏色也淡。　◎"]],"眉清目秀":[["ㄇㄟˊ ㄑㄧㄥ ㄇㄨˋ ㄒㄧㄡˋ","形容面貌清秀俊美。[例]他生得眉清目秀，很討人喜歡。"]],"眉目傳情":[["ㄇㄟˊ ㄇㄨˋ ㄔㄨㄢˊ ㄑㄧㄥˊ","用眼神來傳達情意。[例]情侶間的眉目傳情，別有旁人無法領會的滋味。"]],"眉頭":[["ㄇㄟˊ ㄊㄡˊ","兩眉之間。[例]他心情不佳，終日眉頭深鎖。"]],"看似":[["ㄎㄢˋ ㄙˋ","看起來像是。[例]灌籃得分看似輕鬆，卻是球員苦練的成果。"]],"看出":[["ㄎㄢˋ ㄔㄨ","察覺。[例]由他的言談舉止中，可以看出他的確是個謙謙君子。"]],"看家":[["ㄎㄢ ㄐㄧㄚ","看守門戶。[例]母親不放心妹妹一個人看家，所以請奶奶過來作伴。"]],"看家本領":[["ㄎㄢ ㄐㄧㄚ ㄅㄣˇ ㄌㄧㄥˇ","自己特別專長，但不輕易顯露的技藝。[例]短打觸擊是中華隊的看家本領，使得對方守備陣容大亂。"]],"看扁":[["ㄎㄢˋ ㄅㄧㄢˇ","看不起、輕視。"]],"看望":[["ㄎㄢˋ ㄨㄤˋ","探訪問候。[例]看望師長、看望老友"]],"看法":[["ㄎㄢˋ ㄈㄚˇ","對人、事、物所持的觀點。[例]兄弟倆常因對事情的看法不同而引發爭辯。"]],"看病":[["ㄎㄢˋ ㄅㄧㄥˋ","1.醫生替人診治病情。[例]李大夫外出看病去了，麻煩你晚一點再聯絡。\n2.讓醫生診治病情。[例]今天下午我要去看病，改天再去拜訪你。"]],"看管":[["ㄎㄢ ㄍㄨㄢˇ","管理照顧。[例]我去打個電話，煩請你幫我看管一下行李。"]],"看見":[["ㄎㄢˋ ㄐㄧㄢˋ","看到、見到。[例]小王在路上看見久未聯絡的大學同學，連忙跑過去打招呼。"]],"看護":[["ㄎㄢ ㄏㄨˋ","1.看顧、照料。[例]由於母親的細心看護，他的病情已漸有起色。_x000D_\n2.以照護病人、老年人等為職業的人。[例]最近他病情加重，因此需要一位特別看護日夜照顧他。"]],"看門":[["ㄎㄢ ㄇㄣˊ","看守門戶。[例]父母雙雙外出，只留下小孩獨自看門，不但違法，而且危險。"]],"真實":[["ㄓㄣ ㄕˊ","真確實在。[例]他所說的都是真實的，一點也沒誇大。"]],"真摯":[["ㄓㄣ ㄓˋ","真實誠懇。[例]真摯的友誼是歷久彌堅的。"]],"真正":[["ㄓㄣ ㄓㄥˋ","真確、實在。[例]他一生手不釋卷，不愧為真正的讀書人。"]],"真相":[["ㄓㄣ ㄒㄧㄤˋ","事物的原本面目或真實情況、經過。[例]這件事的真相有待當事人出面說明。"]],"真誠":[["ㄓㄣ ㄔㄥˊ","真實誠懇。[例]他待人真誠，深受大家信賴。"]],"真諦":[["ㄓㄣ ㄉㄧˋ","真確的精義。[例]愛的真諦在於付出，而非占有。"]],"眨眼":[["ㄓㄚˇ ㄧㄢˇ","1.眼睛迅速開合。[例]殺人不眨眼\n2.比喻極短暫的時間。[例]爆破人員一引發炸藥，眨眼間整棟大樓便夷為平地。"]],"眷屬":[["ㄐㄩㄢˋ ㄕㄨˇ","親人、家屬。[例]公務人員眷屬都可以參加醫療保險。"]],"眺望":[["ㄊㄧㄠˋ ㄨㄤˋ","遠望。[例]登上高峰，眺望萬里雲山，心胸頓覺開闊。"]],"眺望臺":[["ㄊㄧㄠˋ ㄨㄤˋ ㄊㄞˊ","供人眺望遠方的高臺。[例]從這個眺望臺俯視群山，氣象萬千，令人心曠神怡。"]],"眼前":[["ㄧㄢˇ ㄑㄧㄢˊ","1.面前、眼睛前面。[例]他推開窗戶，眼前是一片綠油油的稻田。\n2.目前、現在。[例]眼前有個大好機會，你可要好好把握。"]],"眼淚":[["ㄧㄢˇ ㄌㄟˋ","淚腺流出的液體。[例]他想到悲傷的往事，難過得直掉眼淚。"]],"眼皮":[["ㄧㄢˇ ㄆㄧˊ","眼瞼，即眼睛外部可以開合的軟皮。可保護眼球。[例]他昨晚沒睡好，今早起來眼皮浮腫，精神不佳。"]],"眼眶":[["ㄧㄢˇ ㄎㄨㄤ","眼窩的四周。[例]與出國留學的丈夫分離在即，她哭得眼眶紅紅的。"]],"眼睛":[["ㄧㄢˇ ㄐㄧㄥ","動物身上觀察外物的視覺器官。[例]她有一雙水汪汪的大眼睛。"]],"眼簾":[["ㄧㄢˇ ㄌㄧㄢˊ","眼睛視覺範圍。[例]到了展覽會場，首先映入眼簾的，是一幅巨大的宣傳海報。"]],"眼鏡":[["ㄧㄢˇ ㄐㄧㄥˋ","用玻璃片、水晶片等加上鏡架製成，戴在眼睛前，以矯正視力或遮住強烈光線、風沙的器具。[例]近視眼鏡、老花眼鏡、太陽眼鏡"]],"眾多":[["ㄓㄨㄥˋ ㄉㄨㄛ","數量很多。[例]新書才一發表，就得到眾多讀者的回響，她內心感到無比的欣慰。"]],"眾志成城":[["ㄓㄨㄥˋ ㄓˋ ㄔㄥˊ ㄔㄥˊ","比喻眾人一心，堅固如城。[例]在當前外交情勢窘迫之際，國人更應抱持眾志成城的意念，突破困境。"]],"眾說紛紜":[["ㄓㄨㄥˋ ㄕㄨㄛ ㄈㄣ ㄩㄣˊ","各種說法紛亂不一致。[例]關於昨夜火災的起火原因，眾說紛紜，有關單位現正進行勘驗。"]],"睡眠":[["ㄕㄨㄟˋ ㄇㄧㄢˊ","眼睛閉上、身心鬆弛的一種休息狀態。[例]睡眠不足"]],"睡著":[["ㄕㄨㄟˋ ㄓㄠˊ","入睡。[例]小嬰兒已經睡著了，大家不要吵醒她。"]],"睡覺":[["ㄕㄨㄟˋ ㄐㄧㄠˋ","閉上眼睛進入睡眠狀態。[例]時候不早了，大家趕快去睡覺吧！"],["ㄕㄨㄟˋ ㄐㄩㄝˊ","睡醒。[例]雲髻半偏新睡覺，花冠不整下堂來。（唐．白居易〈長恨歌〉）"]],"督學":[["ㄉㄨ ㄒㄩㄝˊ","督察及輔導學校行政與教學情形的教育行政人員。[例]校長陪同督學巡視校園。"]],"睿智":[["ㄖㄨㄟˋ ㄓˋ","深明通達的智識。[例]以他的聰明睿智，將來必可在商場上占有一席之地。"]],"瞇眼":[["ㄇㄧ ㄧㄢˇ","微閉著眼睛。[例]爺爺微笑瞇眼，看著小孫子在院子裡玩耍。"]],"瞥見":[["ㄆㄧㄝ ㄐㄧㄢˋ","突然、無意中看見。[例]他一眼瞥見一輛紅色的汽車從門前疾馳而過。"]],"瞧不起":[["ㄑㄧㄠˊ ㄅㄨˋ ㄑㄧˇ","看不起。[例]可別瞧不起這小小的螺絲釘，少了它機器就無法順利運轉。"]],"瞧見":[["ㄑㄧㄠˊ ㄐㄧㄢˋ","看見。[例]他瞧見弟弟正在玩打火機，連忙大聲喝止。"]],"瞬間":[["ㄕㄨㄣˋ ㄐㄧㄢ","轉眼之間。比喻非常短的時間。[例]魔術師運用奇幻的手法使自由女神像在瞬間消失。"]],"瞭如指掌":[["ㄌㄧㄠˇ ㄖㄨˊ ㄓˇ ㄓㄤˇ","本指天下事如掌中物，易於了解。後比喻對事情了解得非常清楚。語本《論語．八佾》。[例]她們已是十幾年的老朋友了，對彼此的好惡當然是瞭如指掌。"]],"瞭望":[["ㄌㄧㄠˋ ㄨㄤˋ","站在高處向遠方眺望。常有監視、偵察的意思。[例]他用望遠鏡小心的瞭望，以觀察敵人的動靜。"]],"瞭望臺":[["ㄌㄧㄠˋ ㄨㄤˋ ㄊㄞˊ","用以眺望遠方敵情或景物的高臺。[例]站在瞭望臺上放眼望去，無邊的美景盡收眼底。"]],"瞭若指掌":[["ㄌㄧㄠˇ ㄖㄨㄛˋ ㄓˇ ㄓㄤˇ","比喻非常清楚了解。[例]我和他交往了數年，對他的個性已經瞭若指掌。"]],"瞭解":[["ㄌㄧㄠˇ ㄐㄧㄝˇ","知曉、明白。[例]沒有親身體驗，就無法瞭解當事者的感受。　△了解"]],"瞻前顧後":[["ㄓㄢ ㄑㄧㄢˊ ㄍㄨˋ ㄏㄡˋ","1.指做事謹慎周密，能夠首尾兼顧。[例]想把活動辦好，就必須設想周到、瞻前顧後，這樣在面對突發狀況時才不致無法應付。\n2.形容做事顧慮太多，猶豫不決。[例]做事若瞻前顧後，顧忌太多便無法如期完成。"]],"矗立":[["ㄔㄨˋ ㄌㄧˋ","高聳直立。[例]廣場正中矗立著一棟高達四十層的大樓，格外引人注目。"]],"矛盾":[["ㄇㄠˊ ㄉㄨㄣˋ","比喻言語行為自相牴觸。典出《韓非子．勢難》。[例]自相矛盾"]],"矢口否認":[["ㄕˇ ㄎㄡˇ ㄈㄡˇ ㄖㄣˋ","完全不承認。[例]弟弟矢口否認花瓶是他打破的。"]],"知名":[["ㄓ ㄇㄧㄥˊ","聲名很大，為眾人所知。[例]李先生是政界的知名人士。"]],"知己":[["ㄓ ㄐㄧˇ","指相互了解而友誼深厚的人。[例]海內存知己，天涯若比鄰。（唐．王勃〈杜少府之任蜀州〉詩）"]],"知己知彼":[["ㄓ ㄐㄧˇ ㄓ ㄅㄧˇ","對敵我雙方的情形或實力都很瞭解。[例]知己知彼，百戰百勝。"]],"知曉":[["ㄓ ㄒㄧㄠˇ","知道、明白。[例]由於嚴父的教導，他從小就知曉為人處世的道理。"]],"知覺":[["ㄓ ㄐㄩㄝˊ","1.知道、察覺。[例]對此事，他早已知覺有異，只是礙於情面而沒有說破。\n2.身體感官受到刺激而傳入中樞神經後，所產生的一種直接反應。[例]王小姐因車禍傷及腦部後，已呈無知覺狀態。"]],"知識":[["ㄓ ㄕˋ","人在學習、實踐過程中所獲得的學問、經驗等。[例]他涉獵甚廣，知識相當豐富。"]],"知道":[["ㄓ ㄉㄠˋ","明白、瞭解。[例]這件事大家都已經知道了。"]],"矩形":[["ㄐㄩˇ ㄒㄧㄥˊ","數學上指四內角皆為直角的平行四邊形。包含正方形與長方形。[例]樹下那張矩形石桌，常有老人家在那兒品茗泡茶。"]],"短兵相接":[["ㄉㄨㄢˇ ㄅㄧㄥ ㄒㄧㄤ ㄐㄧㄝ","以短小武器做近身搏鬥。形容面對面激烈的搏打、爭鬥。[例]敵我兩軍在邊境相遇，短兵相接，戰況激烈。"]],"短少":[["ㄉㄨㄢˇ ㄕㄠˇ","不足、缺乏。[例]資金短少"]],"短淺":[["ㄉㄨㄢˇ ㄑㄧㄢˇ","狹窄膚淺。[例]目光短淺、見識短淺"]],"短篇":[["ㄉㄨㄢˇ ㄆㄧㄢ","篇幅短小，文字不多的作品。[例]這個短篇字字珠璣，非常值得閱讀。"]],"短缺":[["ㄉㄨㄢˇ ㄑㄩㄝ","欠缺、不足。[例]糧食短缺、資金短缺"]],"短袖":[["ㄉㄨㄢˇ ㄒㄧㄡˋ","長度不超過上臂的袖子。[例]短袖上衣、短袖襯衫"]],"短裙":[["ㄉㄨㄢˇ ㄑㄩㄣˊ","長度不超過膝蓋的裙子。[例]啦啦隊表演時，女孩們都穿上迷你短裙，盡情舞動，展現青春活力。"]],"短褲":[["ㄉㄨㄢˇ ㄎㄨˋ","長度不超過膝蓋的褲子。[例]夏天時我喜歡穿短褲，既涼快又方便。"]],"短跑":[["ㄉㄨㄢˇ ㄆㄠˇ","短距離的賽跑。如100、200、400公尺等。[例]在100公尺的短跑競賽中，她以十二秒一的成績奪得第一名。"]],"矯正":[["ㄐㄧㄠˇ ㄓㄥˋ","改正、糾正。[例]矯正聽力、矯正姿勢"]],"矯治":[["ㄐㄧㄠˇ ㄓˋ","矯正、治療。[例]他由於睡姿不良造成脊椎骨彎曲，只好到醫院接受矯治。"]],"石墩":[["ㄕˊ ㄉㄨㄣ","以石頭砌成的基座。[例]山洪爆發，沖毀了這座橋的石墩。"]],"石油":[["ㄕˊ ㄧㄡˊ","從油井中汲出的碳氫化合物的混合物。為黑色黏滯性大的液體。是有機物質在古地質年代沉積而成。[例]石油經分餾後，可得到天然氣、煤油、潤滑油、柏油等不同產品，用途廣泛。"]],"石碑":[["ㄕˊ ㄅㄟ","石質碑刻。上有文字或圖案，可供紀念或作為標誌。[例]這座廟的建造經過全刻在廟前的石碑上。"]],"石磨":[["ㄕˊ ㄇㄛˋ","一種用來磨碎穀粒的器具，由一對磨盤組成。操作時，下磨盤固定不動，把穀粒放入上磨盤中部的孔，然後將上磨盤作水平轉動，孔中的穀粒便可被磨成粉狀。[例]上等的石磨是以細砂質磨石製成的。"]],"石雕":[["ㄕˊ ㄉㄧㄠ","1.在石材上雕刻形象或花紋的藝術。可雕石材如白大理石、文石、玉石等。[例]這位師傅的石雕技術已臻完美境界。\n2.用石材雕刻成的作品。[例]這座愛神維納斯的大理石石雕，栩栩如生，舉世聞名。"]],"石頭":[["ㄕˊ ˙ㄊㄡ","由礦物質集合而成的堅硬塊狀物質。[例]這條健康步道是用許多卵形小石頭鋪成的。"]],"砂岩":[["ㄕㄚ ㄧㄢˊ","由砂膠結而成的沉積岩。[例]石英砂岩、長石砂岩"]],"砂石":[["ㄕㄚ ㄕˊ","砂土和石頭。[例]警方正全力取締違規超載砂石的貨車。"]],"砂糖":[["ㄕㄚ ㄊㄤˊ","由蔗糖製成的顆粒狀糖。如紅砂糖、白砂糖。"]],"砂紙":[["ㄕㄚ ㄓˇ","黏附金剛砂的厚紙。可用以磨光器物的表面。[例]他用砂紙把門上的金屬把手磨得光亮如新。"]],"砂鍋":[["ㄕㄚ ㄍㄨㄛ","一種用陶土燒製成的鍋。多用於烹煮食物或熬藥。[例]砂鍋魚頭　△沙鍋"]],"砍伐":[["ㄎㄢˇ ㄈㄚ","用刀斧劈砍樹木。[例]適度砍伐林木，才不會造成森林迅速消失，危及地球生態環境。"]],"研磨":[["ㄧㄢˊ ㄇㄛˊ","把東西磨製成粉末。[例]她將藥丸研磨成藥粉以利服用。"]],"研究":[["ㄧㄢˊ ㄐㄧㄡˋ","1.深入探索事物的性質、規律、道理等。[例]老師要同學們種植綠豆，以研究它的生長過程。\n2.商量、考慮。[例]這件事我們必須再研究一下，才能給您答覆。"]],"研讀":[["ㄧㄢˊ ㄉㄨˊ","研究誦讀。[例]老師指導我們研讀課外書刊，以增廣知識。"]],"破壞":[["ㄆㄛˋ ㄏㄨㄞˋ","損毀、敗壞。[例]大家使用時小心，千萬別破壞公物。"]],"破曉":[["ㄆㄛˋ ㄒㄧㄠˇ","天剛亮。[例]天剛破曉，早餐店就開始忙碌起來。"]],"破洞":[["ㄆㄛˋ ㄉㄨㄥˋ","破口、破窟窿。[例]媽媽用針線把衣服的破洞補好。"]],"破碎":[["ㄆㄛˋ ㄙㄨㄟˋ","破裂散碎。[例]他玩球時不慎打到窗戶，玻璃破碎一地。"]],"破裂":[["ㄆㄛˋ ㄌㄧㄝˋ","1.破損裂開。[例]玻璃破裂\n2.破壞、分裂。多指感情與關係。[例]感情破裂、婚姻破裂"]],"硬幣":[["ㄧㄥˋ ㄅㄧˋ","以金屬材料鑄成的貨幣。[例]目前通行的硬幣有一元、五元、十元、五十元四種。　△金屬貨幣"]],"碎屑":[["ㄙㄨㄟˋ ㄒㄧㄝˋ","碎末。[例]他為了做一張木桌，把地上弄得都是碎屑。"]],"碎步":[["ㄙㄨㄟˋ ㄅㄨˋ","小而快的步伐。[例]她碎步上前，接受校長的頒獎。"]],"碑文":[["ㄅㄟ ㄨㄣˊ","刻在石碑上的文字。[例]從這碑文內容看來，死者生前是位將軍。"]],"碗盤":[["ㄨㄢˇ ㄆㄢˊ","飯碗和盤子。[例]用溫水洗碗盤，不會殘留有害物質。"]],"碗筷":[["ㄨㄢˇ ㄎㄨㄞˋ","吃飯用的飯碗、筷子。[例]把碗筷擺好，準備吃飯。"]],"碧波":[["ㄅㄧˋ ㄅㄛ","浮現在澄澈水面上的青綠波紋。[例]每當風日晴和時，日月潭上便碧波萬頃，遊艇穿梭。"]],"碰運氣":[["ㄆㄥˋ ㄩㄣˋ ˙ㄑㄧ","對所做的事情沒有把握，只是存著僥倖心理。[例]由於沒有經驗，這些樹苗是否能種得活，只有碰運氣了。"]],"確定":[["ㄑㄩㄝˋ ㄉㄧㄥˋ","明確而肯定。[例]等出發時間確定後再通知他們比較恰當。"]],"確鑿":[["ㄑㄩㄝˋ ㄗㄠˊ","極為真實確定。[例]在證據確鑿的情況下，嫌犯終於俯首認罪。"]],"磁性":[["ㄘˊ ㄒㄧㄥˋ","1.具有相吸、相斥等物理的性質。[例]普通鋼鐵經過磁化，也能產生磁性。\n2.吸引力。[例]他的聲音低沉悅耳，富有磁性。"]],"磁磚":[["ㄘˊ ㄓㄨㄢ","一種質地細緻的磚。表面經塗釉處理，具有磁器般的光澤。抗潮耐熱，用來鋪設地板或牆面，清潔而美觀。[例]磁磚清洗容易，是鋪設廚房地板最常使用的材料。　△瓷磚"]],"磁鐵":[["ㄘˊ ㄊㄧㄝˇ","以天然磁鐵礦加工製成，或以鋼、合金經磁化後製成的磁體。具有吸引鐵、鈷、鎳等金屬物體的性質。[例]磁鐵磁性的強度，會影響磁場的範圍。　△吸鐵石、玄石、磁石"]],"磚牆":[["ㄓㄨㄢ ㄑㄧㄤˊ","用磚塊砌成的牆。[例]那面磚牆經過長期的風吹雨打，已經快坍塌了。"]],"磚瓦":[["ㄓㄨㄢ ㄨㄚˇ","泛指磚塊、瓦片等建築材料。[例]鄰居正在整修房子，磚瓦碎片散落滿地。"]],"磨光":[["ㄇㄛˊ ㄍㄨㄤ","1.將器物表面磨成光滑。[例]木匠用細砂紙將桌面磨光。\n2.消耗殆盡。[例]自從做了這份校對工作，我的煩躁性子漸漸被磨光了。"]],"磨坊":[["ㄇㄛˋ ㄈㄤ","將米、麥等研磨成粉的場所。[例]荷蘭人用風車來推動磨坊中的磨盤。"]],"磨平":[["ㄇㄛˊ ㄆㄧㄥˊ","磨擦使東西平滑。[例]他用砂輪將鋼板磨平打光。"]],"磨滅":[["ㄇㄛˊ ㄇㄧㄝˋ","消滅。[例]這次的經歷將是我心中不可磨滅的記憶。"]],"磨牙":[["ㄇㄛˊ ㄧㄚˊ","1.借物體來磨短或磨利牙齒。[例]老鼠因為門牙長個不停，所以要啃東西來磨牙。\n2.睡覺時一種無意識的牙齒相磨現象。[例]不知是否太累了，最近睡覺時常會不自覺的磨牙。\n3.閒聊或作無謂的爭辯。[例]他沒事就喜歡串門子、閒磨牙，令人覺得很厭煩。"]],"磨練":[["ㄇㄛˊ ㄌㄧㄢˋ","鍛鍊、考驗。[例]磨練心志"]],"磨蹭":[["ㄇㄛˊ ㄘㄥˋ","1.輕微的摩擦。[例]她的小狗喜歡在她腳邊磨蹭。\n2.做事緩慢、不俐落。[例]快點走，別再那兒磨蹭了！\n3.糾纏。[例]小弟磨蹭了半天，媽媽終於答應帶他出去玩。"]],"磨難":[["ㄇㄛˊ ㄋㄢˋ","阻礙、災難。[例]無論多少磨難都打擊不了他堅強的意志。"]],"礁岩":[["ㄐㄧㄠ ㄧㄢˊ","暗藏或突出水面的岩石。[例]退潮時，海岸邊露出許多礁岩。"]],"礁石":[["ㄐㄧㄠ ㄕˊ","突出海面或離海面很近的岩石。[例]這段航道礁石很多，來往的船隻經常失事。"]],"礙眼":[["ㄞˋ ㄧㄢˇ","不順眼、有所妨礙。[例]在騎樓下放置私人廢棄物，不但缺乏公德心，而且也十分礙眼。"]],"礦坑":[["ㄎㄨㄤˋ ㄎㄥ","為開採礦物所挖掘的坑道、洞穴。[例]這個地區因礦脈枯竭而停止開採後，留下了不少廢棄的礦坑。"]],"礦工":[["ㄎㄨㄤˋ ㄍㄨㄥ","以採礦為業的工人。[例]礦工冒著生命危險在礦穴裡工作的精神，實在令人感佩。"]],"礦產":[["ㄎㄨㄤˋ ㄔㄢˇ","可開採的礦物。[例]這片海域蘊藏著豐富的礦產，目前正準備鑽探開發中。"]],"礦石":[["ㄎㄨㄤˋ ㄕˊ","含有礦物的岩石。[例]礦石的開採與國家工業發展具有密切的關係。"]],"礫石":[["ㄌㄧˋ ㄕˊ","地質學上稱顆粒狀的岩石。由暴露在地表的岩石經風化作用而形成，沉積於山麓或經河流搬運，沉積於河床上。[例]含礫石多的土壤，缺乏保持水分和養分的能力，十分貧瘠。"]],"示威":[["ㄕˋ ㄨㄟ","1.顯示威力、力量。[例]籃球比賽才一開場，我方便排出最堅強的陣容向對方示威。\n2.為了表示抗議或達成目的，結合群眾以顯示威力的集體行動。[例]示威遊行、示威抗議"]],"示範":[["ㄕˋ ㄈㄢˋ","說明或展現可供大家學習的方法或典範。[例]烹飪老師正在示範紅燒魚的作法。"]],"社區":[["ㄕㄜˋ ㄑㄩ","一群人以自由結合的方式所居住的特定區域。此範圍內的每一分子，皆可共享區域內所有的服務與利益。[例]他們剛搬進去新社區，裡面有嚴密的警衛系統和完備的公共設施。"]],"社團":[["ㄕㄜˋ ㄊㄨㄢˊ","二人以上為同一目的而組成的團體。[例]校內有各式各樣的社團，學生可以按照自己的興趣和喜好自由參加。"]],"祈求":[["ㄑㄧˊ ㄑㄧㄡˊ","懇切的請求。[例]她誠心祈求警方能幫她找回失蹤的小孩。"]],"祈福":[["ㄑㄧˊ ㄈㄨˊ","祈求上天賜予福祉。[例]他自小身體不好，母親時常到廟裡為他祈福。"]],"祈禱":[["ㄑㄧˊ ㄉㄠˇ","1.禱告求福。[例]每次出海，他的妻子總是默默祈禱他能平安歸來。\n2.宗教中向神請求、告白，或讚美、感謝神等儀式。[例]他是個虔誠的基督徒，每個星期天都上教堂祈禱。"]],"祕密":[["ㄇㄧˋ ㄇㄧˋ","1.隱密的。[例]這件事只能祕密進行，不能聲張。\n2.隱密而不讓人知道的事。[例]他們倆最近講話都吞吞吐吐的，不知是否有不可告人的祕密。"]],"祕訣":[["ㄇㄧˋ ㄐㄩㄝˊ","關鍵、有效或巧妙的處理方法。[例]努力不懈是成功的唯一祕訣。"]],"祖先":[["ㄗㄨˇ ㄒㄧㄢ","始祖或歷代的先人。[例]我們能有今日的富強，都是靠祖先們流血流汗累積而成的。"]],"祝福":[["ㄓㄨˋ ㄈㄨˊ","原指求神賜福，後用於泛指祝人平安、幸福。[例]他對即將遠行的好友致上深深的祝福。"]],"神出鬼沒":[["ㄕㄣˊ ㄔㄨ ㄍㄨㄟˇ ㄇㄛˋ","形容行動快速，變化莫測。語本《淮南子．兵略》。[例]這一帶的海盜神出鬼沒，過往的船隻莫不提心吊膽。"]],"神奇":[["ㄕㄣˊ ㄑㄧˊ","神妙奇特，不可思議。[例]化腐朽為神奇。"]],"神往":[["ㄕㄣˊ ㄨㄤˇ","心神嚮往。[例]陶淵明筆下的桃花源，令許多人悠然神往。"]],"神清氣爽":[["ㄕㄣˊ ㄑㄧㄥ ㄑㄧˋ ㄕㄨㄤˇ","神志清朗，心情舒暢。[例]假日到郊外踏青，讓人感到神清氣爽。"]],"神祕":[["ㄕㄣˊ ㄇㄧˋ","高深難料，超乎尋常理性認知之外。[例]對手冷靜從容的表情，令他覺得神祕莫測。"]],"神話":[["ㄕㄣˊ ㄏㄨㄚˋ","1.關於天地的初創、神靈的奇蹟，以及說明風俗習慣、禮儀和信仰的起源與意義的故事。多為先民對無法理解的自然現象和社會生活的一種主觀幻想的解釋和美麗的嚮往，富有浪漫的色彩。[例]希臘的神話故事舉世聞名。\n2.荒誕無稽的言論。[例]他居然說他可以在十秒內跑完四百公尺，簡直是神話！"]],"神農氏":[["ㄕㄣˊ ㄋㄨㄥˊ ㄕˋ","傳說中上古的帝王。他為治療疾病親嚐百草，並發明耒耜，教人民種植五穀，為中國古代傳說中務農、製藥的始祖，故稱為「神農」。後世與燧人氏、伏羲氏合稱為「三皇」。"]],"神采":[["ㄕㄣˊ ㄘㄞˇ","精神、風采。[例]神采飛揚"]],"神采飛揚":[["ㄕㄣˊ ㄘㄞˇ ㄈㄟ ㄧㄤˊ","活力充沛、神色自得的樣子。[例]他看起來神采飛揚、活力十足，令人印象深刻。"]],"祥和":[["ㄒㄧㄤˊ ㄏㄜˊ","良善和睦。[例]讓我們攜手共同建立一個祥和的社會。"]],"祥瑞":[["ㄒㄧㄤˊ ㄖㄨㄟˋ","吉祥的徵兆。亦泛指所有吉祥的事物。[例]古人會將一些特殊的天象或罕見的動植物，視為祥瑞之徵兆。"]],"票券":[["ㄆㄧㄠˋ ㄑㄩㄢˋ","泛指股票、彩券等作為憑證用的證券。[例]這些票券都是有價證券，要小心保管，以免遺失。"]],"票選":[["ㄆㄧㄠˋ ㄒㄩㄢˇ","以投票方式選舉。[例]今天公司將票選最佳服務人員，希望大家踴躍投票。"]],"祭壇":[["ㄐㄧˋ ㄊㄢˊ","舉行祭典的壇臺。[例]古時雄偉的祭壇，今日多已成為觀光勝地。"]],"禁不住":[["ㄐㄧㄣ ㄅㄨˋ ㄓㄨˋ","1.承受不起。[例]她的身子一向嬌弱，禁不住這種變化無常的天氣。\n2.抑制不住、忍耐不住。[例]聽完他的話，大家禁不住笑了起來。"]],"禁不起":[["ㄐㄧㄣ ㄅㄨˋ ㄑㄧˇ","承受不住。[例]行道樹禁不起颱風的肆虐，紛紛斷裂折落。"]],"禁忌":[["ㄐㄧㄣˋ ㄐㄧˋ","忌諱。[例]妄下定論是科學研究的一大禁忌。"]],"禁止":[["ㄐㄧㄣˋ ㄓˇ","制止、不准。[例]這條馬路正在施工，禁止車輛通行。"]],"禍從口出":[["ㄏㄨㄛˋ ㄘㄨㄥˊ ㄎㄡˇ ㄔㄨ","禍害多因說話不謹慎而引起。[例]說話要三思，免得禍從口出，徒增困擾。"]],"禮俗":[["ㄌㄧˇ ㄙㄨˊ","禮儀和習俗。[例]他生性豁達，不拘禮俗，令人感到非常自在。"]],"禮儀":[["ㄌㄧˇ ㄧˊ","禮節的規範與儀式。[例]到外國旅遊時，要留意各地不同的禮儀，以免貽笑大方。"]],"禮堂":[["ㄌㄧˇ ㄊㄤˊ","開會或舉行典禮的廳堂。[例]本屆畢業典禮在禮堂舉行，場面非常隆重。"]],"禮尚往來":[["ㄌㄧˇ ㄕㄤˋ ㄨㄤˇ ㄌㄞˊ","指別人以禮相待，自己也要以禮回報。語出《禮記．曲禮上》。[例]禮尚往來，若只受饋而不往贈，雙方的情意就要日漸淡薄了。"]],"禮教":[["ㄌㄧˇ ㄐㄧㄠˋ","禮儀教化。[例]如果人人能遵循禮教，那麼社會必然祥和安樂。"]],"禮物":[["ㄌㄧˇ ㄨˋ","餽贈的物品。[例]生日禮物、聖誕禮物、結婚禮物"]],"禮盒":[["ㄌㄧˇ ㄏㄜˊ","以盒子包裝的禮品。[例]我們帶了水果禮盒去探望老師。"]],"禮節":[["ㄌㄧˇ ㄐㄧㄝˊ","禮制的儀式、規矩。[例]中國是禮儀之邦，非常重視各種禮節。"]],"禮讓":[["ㄌㄧˇ ㄖㄤˋ","尊重而退讓。[例]駕駛人如果彼此能夠禮讓，交通必定通暢不少。"]],"禱告":[["ㄉㄠˇ ㄍㄠˋ","祝告鬼神或上帝，以求福佑。[例]他禱告上天，祈求母親的病早日痊癒。"]],"禿頭":[["ㄊㄨ ㄊㄡˊ","頭頂沒有頭髮。亦指頭頂沒有頭髮的人。[例]我最近一直掉頭髮，可能哪天就變成禿頭了。"]],"秉持":[["ㄅㄧㄥˇ ㄔˊ","操持、執守。[例]做人要秉持公道，不可徇私。"]],"秋千":[["ㄑㄧㄡ ㄑㄧㄢ","一種遊戲器材。在高架或樹幹上繫兩條等長的繩索或鐵鍊，下面拴上橫板，人可坐立其上，前後擺盪。[例]小朋友在秋千上盪來盪去，玩得十分高興。　△鞦韆"]],"秋天":[["ㄑㄧㄡ ㄊㄧㄢ","秋季。[例]時序一進入秋天，楓葉便開始變紅了。"]],"秋風":[["ㄑㄧㄡ ㄈㄥ","1.秋季的風。[例]秋風吹起時，片片落葉在風中飛舞。\n2.假借事端求人資助或利用藉口向人求取財利。[例]像他這種秋風之客，為人所不齒。"]],"秋高氣爽":[["ㄑㄧㄡ ㄍㄠ ㄑㄧˋ ㄕㄨㄤˇ","形容秋天天氣晴朗涼爽。[例]秋高氣爽，正是郊遊踏青的好時節。"]],"科學家":[["ㄎㄜ ㄒㄩㄝˊ ㄐㄧㄚ","從事科學研究工作而有一定成就的人。通常指研究自然科學的專家，如物理學家、生物學家等。[例]他希望將來能成為一位傑出的科學家。"]],"科技":[["ㄎㄜ ㄐㄧˋ","科學技術。[例]科技發展日新月異，移民外太空的想法可能有機會實現。"]],"科目":[["ㄎㄜ ㄇㄨˋ","對學術或其他事項按性質劃分的類別。[例]數學和英文是他最拿手的科目。"]],"租用":[["ㄗㄨ ㄩㄥˋ","租借、使用他人的房地、器物等而予以付費。[例]他出外旅遊時，總會在當地租用汽車，以作為代步的交通工具。"]],"租金":[["ㄗㄨ ㄐㄧㄣ","房地、器物等出租給他人使用時，約定按期所收取的價錢。[例]這間房子的租金很貴。"]],"秩序":[["ㄓˋ ㄒㄩˋ","次序、條理。[例]搭乘公車時要遵守秩序，不要爭先恐後。"]],"移動":[["ㄧˊ ㄉㄨㄥˋ","改變原來的位置或方向。[例]他很不喜歡別人隨便移動書房中的文物。"]],"稀奇古怪":[["ㄒㄧ ㄑㄧˊ ㄍㄨˇ ㄍㄨㄞˋ","少見而怪異。[例]這件案子越是深入了解，越覺得稀奇古怪。"]],"稀薄":[["ㄒㄧ ㄅㄛˊ","稀少淡薄。[例]高山上的空氣較稀薄，常使登山者感到不適。"]],"程度":[["ㄔㄥˊ ㄉㄨˋ","衡量抽象事物的標準。[例]小明雖然才四歲，但語文能力已經有小學一年級的程度了。"]],"稍微":[["ㄕㄠ ㄨㄟˊ","程度或分量上極少的。[例]只要稍微再下一點工夫，這件作品就會更完美。"]],"稍縱即逝":[["ㄕㄠ ㄗㄨㄥˋ ㄐㄧˊ ㄕˋ","略為輕忽或不注意便會失去。形容時間或機會容易錯失。[例]時間稍縱即逝，我們一定要好好把握。"]],"稚拙":[["ㄓˋ ㄓㄨㄛˊ","幼稚樸拙。多用以形容人的行為或作品等。[例]孩子們以稚拙的字跡寫了一張父親節卡片。"]],"稚齡":[["ㄓˋ ㄌㄧㄥˊ","年紀小。[例]由於父母意外身亡，身為長女的她必須肩負起照顧稚齡弟妹的責任。"]],"稠密":[["ㄔㄡˊ ㄇㄧˋ","多而密。[例]這一帶交通方便，因此人口稠密。"]],"種子":[["ㄓㄨㄥˇ ㄗˇ","植物的雌蕊經過受精後，子房內的胚珠發育成熟的部分。主要由種皮、胚、胚乳三部分組成。[例]我把花的種子埋在泥土裡，並按時澆水，希望它能趕快發芽。"]],"種植":[["ㄓㄨㄥˋ ㄓˊ","栽種培植。[例]父親以種植蘭花，來打發退休後的生活。"]],"種田":[["ㄓㄨㄥˋ ㄊㄧㄢˊ","種植五穀、蔬菜等農作物。[例]鄉下種田的農夫，日出而作、日沒而息，一年到頭辛勤耕耘。"]],"種類":[["ㄓㄨㄥˇ ㄌㄟˋ","依據人物、事物的品名、性質或特點而分的類別。[例]植物的種類繁多，不是一朝一夕便能認識得完的。"]],"稱兄道弟":[["ㄔㄥ ㄒㄩㄥ ㄉㄠˋ ㄉㄧˋ","以兄弟相稱，表示關係親密。[例]他們倆相處融洽，漸漸的彼此便稱兄道弟起來。"]],"稱呼":[["ㄔㄥ ㄏㄨ","對人口頭上的稱謂。[例]那位先生不知怎麼稱呼？"]],"稱心如意":[["ㄔㄥˋ ㄒㄧㄣ ㄖㄨˊ ㄧˋ","符合心意，達到願望。[例]找了好幾個月，終於買到合意的房子，這回總算讓他稱心如意了。"]],"稱羨":[["ㄔㄥ ㄒㄧㄢˋ","讚揚羨慕。[例]他們倆結婚多年，仍然恩愛如昔，真是令人稱羨。"]],"稱職":[["ㄔㄥˋ ㄓˊ","才能足夠勝任所擔負的職務。[例]他工作表現十分稱職，很受上司器重。"]],"稱謂":[["ㄔㄥ ㄨㄟˋ","對人或物所加的名稱。[例]親屬稱謂、正式稱謂"]],"稱讚":[["ㄔㄥ ㄗㄢˋ","讚美、褒揚。[例]對成長中的孩子適時加以稱讚，可以建立他們的自信心。"]],"稱霸":[["ㄔㄥ ㄅㄚˋ","1.憑恃武力或權勢壓倒別人，而取得領導地位。[例]春秋時代，齊桓公九合諸侯，尊王攘夷，而稱霸中原。_x000D_\n2.實力堅強，比賽獲得優勝。[例]那位網球選手因球技高超而長年稱霸網壇。_x000D_"]],"稻子":[["ㄉㄠˋ ˙ㄗ","1.水稻的子實。[例]這些稻子將送往工廠碾成食米銷售。\n2.對稻作的通稱。[例]稻子是臺灣栽培得最多的糧食作物。"]],"稻田":[["ㄉㄠˋ ㄊㄧㄢˊ","種稻的田地。[例]稻米產量過剩，王伯伯打算將稻田轉作其它經濟作物。"]],"稻穗":[["ㄉㄠˋ ㄙㄨㄟˋ","叢聚成串的稻穀。[例]看著結實纍纍的稻穗，農夫們臉上露出了欣喜的笑容。"]],"稻米":[["ㄉㄠˋ ㄇㄧˇ","稻子去殼後的米粒。[例]政府推出許多用稻米製作的點心食譜，以鼓勵國民多多食用。"]],"稿件":[["ㄍㄠˇ ㄐㄧㄢˋ","草稿或文件。[例]這份稿件很重要，請妥善保存。"]],"稿子":[["ㄍㄠˇ ˙ㄗ","作品的底稿。[例]在投稿前，我都會將寫好的稿子拿給老師看一遍。"]],"稿紙":[["ㄍㄠˇ ㄓˇ","專門用來寫稿的紙。多印有直行或小方格。[例]他把寫好的文章謄到稿紙上，準備寄到報社發表。"]],"稿費":[["ㄍㄠˇ ㄈㄟˋ","出版機構付給作者的酬勞。其種類包括文章、繪畫、攝影等作品。[例]他除了教書，還寫些文章，賺點稿費。"]],"稿酬":[["ㄍㄠˇ ㄔㄡˊ","出版機構付給作者的酬勞。[例]他的小說登出來了，還領了一筆稿酬。"]],"穀倉":[["ㄍㄨˇ ㄘㄤ","儲存穀糧的倉庫。[例]農夫正忙著將晒好的稻穀搬入穀倉中儲放。"]],"穀物":[["ㄍㄨˇ ㄨˋ","穀類作物的通稱。[例]此地土質肥沃，最適宜穀物的栽種。"]],"積木":[["ㄐㄧ ㄇㄨˋ","一種玩具。以木頭或塑膠等材質製成，有各種形狀及色彩，能組合成多種形式的建築物及圖案。可藉以啟發智慧及組織能力。[例]這兩位小朋友正在同心協力的將積木組合成一間房子。"]],"積極":[["ㄐㄧ ㄐㄧˊ","1.意願強烈、主動力行。[例]他對於參與社會公益活動一向很積極。\n2.正面的、肯定的。[例]推選好人好事代表，對淨化社會，淳化風俗有積極正面的影響。"]],"穩固":[["ㄨㄣˇ ㄍㄨˋ","1.穩定牢固。[例]這棟房子因為地基不穩固，恐有倒塌之虞。\n2.使牢固。[例]加強戰備，穩固國防力量。"]],"穩如泰山":[["ㄨㄣˇ ㄖㄨˊ ㄊㄞˋ ㄕㄢ","比喻像泰山一樣穩定牢固，不可動搖。[例]他在公司的地位穩如泰山，從來無人能夠取代。"]],"穩妥":[["ㄨㄣˇ ㄊㄨㄛˇ","穩當妥帖。[例]他為人誠信，把事情託付他，再穩妥不過了。"]],"穩定":[["ㄨㄣˇ ㄉㄧㄥˋ","平穩安定。[例]他找到工作後，每個月就有穩定的收入。"]],"穩賺不賠":[["ㄨㄣˇ ㄓㄨㄢˋ ㄅㄨˋ ㄆㄟˊ","指從事某種行業一定賺錢。[例]只要嚴格控制生產成本與品質，這是一門穩賺不賠的生意。"]],"穩重":[["ㄨㄣˇ ㄓㄨㄥˋ","沉著莊重，做事深思熟慮。[例]他個性穩重，深受上司信賴。"]],"究竟":[["ㄐㄧㄡˋ ㄐㄧㄥˋ","1.到底。[例]他又哭又笑的，真不知道究竟是悲傷還是高興？\n2.真相、結果。[例]聽說那座山蘊藏金礦，我們決定前往一探究竟。"]],"空中":[["ㄎㄨㄥ ㄓㄨㄥ","天空中。[例]小鳥在空中自由自在的飛翔。"]],"空位":[["ㄎㄨㄥˋ ㄨㄟˋ","還未使用、空出來的座位。[例]這班公車已經沒有空位了，我們還是等下一班吧！"]],"空地":[["ㄎㄨㄥˋ ㄉㄧˋ","沒有加以利用或空無所有的土地。[例]爺爺決定將屋後的空地開墾成菜園。"]],"空屋":[["ㄎㄨㄥ ㄨ","無人居住的房子。[例]這棟空屋竟被人們繪聲繪影的說成是一間鬼屋。"]],"空曠":[["ㄎㄨㄥ ㄎㄨㄤˋ","開闊、寬廣。[例]這一大片空曠的草原，真讓人有呼嘯狂奔的衝動。"]],"空泛":[["ㄎㄨㄥ ㄈㄢˋ","空洞而不切實際。[例]這篇文章立論空泛，評審認為應予汰除。"]],"空白":[["ㄎㄨㄥˋ ㄅㄞˊ","1.空無所有的、尚未規劃使用的。[例]空白授權、空白筆記本_x000D_\n2.紙上沒有被填滿的部分。[例]中國山水畫上的空白，正是要人寄託雲煙遐想的。"]],"空閒":[["ㄎㄨㄥˋ ㄒㄧㄢˊ","閒暇。[例]他喜歡利用空閒的時候去爬爬山、釣釣魚。"]],"空間":[["ㄎㄨㄥ ㄐㄧㄢ","1.物質存在的一種客觀形式，由長度、寬度、高度表現出來。[例]三度空間\n2.泛稱天地之間。[例]在廣大的宇宙空間，仍然有許多人類無法以科學解釋的現象。"]],"空闊":[["ㄎㄨㄥ ㄎㄨㄛˋ","寬大遼闊。[例]一大群小朋友在空闊的草地上追逐嬉戲，笑鬧聲不絕於耳。"]],"空隙":[["ㄎㄨㄥˋ ㄒㄧˋ","物體上有縫隙的地方。[例]窗戶上有個空隙，難怪屋內會覺得這麼冷。"]],"穿戴":[["ㄔㄨㄢ ㄉㄞˋ","穿著打扮。[例]穿戴整齊、穿戴時髦"]],"穿插":[["ㄔㄨㄢ ㄔㄚ","1.交雜。[例]在一大束紅玫瑰中穿插一些白色的滿天星，別具一番風貌。\n2.小說、戲劇、電影等添加某些情節或節目表演以襯托主題、填補空檔、緩和觀眾注意力。[例]這部戰爭片穿插著淒美的愛情故事。"]],"穿梭":[["ㄔㄨㄢ ㄙㄨㄛ","往來次數頻繁。[例]他來回穿梭在會場中，張羅著大大小小的事。"]],"穿著":[["ㄔㄨㄢ ㄓㄨㄛˊ","衣著服飾。[例]從他的穿著打扮看來，似乎不是本地人。"]],"穿透":[["ㄔㄨㄢ ㄊㄡˋ","穿通貫透。[例]子彈穿透鋼板，它的威力之大，就可想而知了。"]],"突然":[["ㄊㄨˊ ㄖㄢˊ","形容情況緊急且出人意外。[例]小王在一片安靜中突然起身說話，言語中在在表現出他的不滿。"]],"突發":[["ㄊㄨˊ ㄈㄚ","忽然發生。[例]他心臟病突發，現正在急診室急救。"]],"窗戶":[["ㄔㄨㄤ ㄏㄨˋ","裝置於牆上可通風透光的設備。[例]他打開窗戶好讓空氣流通。"]],"窗簾":[["ㄔㄨㄤ ㄌㄧㄢˊ","掛在窗上用來遮蔽光線或視線的竹簾。[例]臥室裡掛窗簾可以遮光、透氣，有助於安睡。"]],"窘境":[["ㄐㄩㄥˇ ㄐㄧㄥˋ","艱難貧困的處境。[例]因為父親驟然逝世，使得他們全家的生活頓時陷入了窘境。"]],"窘迫":[["ㄐㄩㄥˇ ㄆㄛˋ","艱困急迫。[例]就在錢包被扒，無錢付帳的窘迫之際，他適時出現替我解決了問題。"]],"窮困":[["ㄑㄩㄥˊ ㄎㄨㄣˋ","生計窘迫或境遇艱難。[例]雖然家境清寒，生活窮困，他仍然勤奮向學。"]],"窺探":[["ㄎㄨㄟ ㄊㄢˋ","1.暗中察看。[例]部署在軍事重地的防空雷達，基於國家安全，嚴禁民眾窺探。\n2.探究、察覺。[例]從這部電影的內容中，可以窺探出現代人心靈的空虛。"]],"竅門":[["ㄑㄧㄠˋ ㄇㄣˊ","比喻關鍵、要點或特殊的方法。[例]經過一下午的摸索，他終於領悟到這個遊戲的竅門。"]],"立刻":[["ㄌㄧˋ ㄎㄜˋ","即時、馬上。[例]槍聲一響，選手們立刻邁開腳步向前奔跑。"]],"立即":[["ㄌㄧˋ ㄐㄧˊ","立刻、即時。[例]天空一變黑，媽媽立即把衣服收進屋裡，以防下雨。"]],"立正":[["ㄌㄧˋ ㄓㄥˋ","端正直立。通常在軍事或體操口令上，命令人在原地站好，挺胸正立。[例]唱國歌時，應該立正，表示尊敬。"]],"立誓":[["ㄌㄧˋ ㄕˋ","發誓，立下誓言。[例]他立誓要洗刷前恥，重新做人。"]],"站崗":[["ㄓㄢˋ ㄍㄤˇ","1.站在崗位上，執行守衛或警戒的任務。[例]校方每天安排糾察隊員在校門口站崗，負責維持秩序。\n2.調侃人為追求某種目的而耐心等候。[例]為追求女友，他天天到女生宿舍前站崗。"]],"站立":[["ㄓㄢˋ ㄌㄧˋ","身體平直的挺立著。[例]同學們站立在老師兩旁，拍了一張全班的合照。"]],"竟敢":[["ㄐㄧㄥˋ ㄍㄢˇ","居然敢。表示意外的語氣。[例]平常看他依賴性很強，沒想到他竟敢一個人去自助旅行。"]],"竟然":[["ㄐㄧㄥˋ ㄖㄢˊ","居然。表示出乎意料之外。[例]他竟然說出這種使母親傷心的話，真是太不孝了。"]],"章程":[["ㄓㄤ ㄔㄥˊ","分段條列的法則、規定。[例]根據組織章程，本會應設會長一人綜理會務。"]],"章節":[["ㄓㄤ ㄐㄧㄝˊ","書的組成部分。通常一本書的大段落稱「章」，小段落稱「節」。[例]這本小說有些章節寫得很精彩。"]],"章魚":[["ㄓㄤ ㄩˊ","動物名。頭足綱章魚科。外觀像球狀，似烏賊而大，有八腕，體內有墨囊，是一種常見的可食用的軟體動物。多棲息於淺海、軟泥或岩礁處，捕食魚類、甲殼類。肉肥厚鮮美，營養豐富。[例]章魚遇到危險時，就會從墨囊噴出墨汁，再趁機逃逸。　△八帶魚、八腳章魚、八腳魚　◎"]],"童年":[["ㄊㄨㄥˊ ㄋㄧㄢˊ","幼年時期。[例]童年的困苦環境，磨鍊出他日後堅毅不撓的個性。"]],"童話":[["ㄊㄨㄥˊ ㄏㄨㄚˋ","為兒童編寫的故事，適於兒童心理與興趣，行文淺易，多敘述神奇美妙的故事，啟發兒童的心智，增加幻想的空間。如格林童話、安徒生童話等。[例]「愛麗絲夢遊奇境記」是世界有名的童話。"]],"竭盡":[["ㄐㄧㄝˊ ㄐㄧㄣˋ","用盡、窮盡。[例]竭盡心力"]],"端正":[["ㄉㄨㄢ ㄓㄥˋ","1.整齊、不歪邪。[例]儀容端正、字跡端正\n2.正直、不邪曲。[例]他為人端正，深受大家尊敬。\n3.使不歪邪。[例]法院對這次賄選案的判決，有助於端正選舉風氣。"]],"端莊":[["ㄉㄨㄢ ㄓㄨㄤ","端正莊重。"]],"競爭":[["ㄐㄧㄥˋ ㄓㄥ","為某種目的而相互爭勝。[例]此次參加徵文比賽的人數很多，競爭十分激烈。"]],"競賽":[["ㄐㄧㄥˋ ㄙㄞˋ","泛指各種競爭比賽。[例]體育競賽、整潔競賽"]],"競逐":[["ㄐㄧㄥˋ ㄓㄨˊ","1.爭相追逐。[例]風和日麗的早晨，小朋友們在草地上相互競逐，好不開心。\n2.競爭、角逐。[例]他有意競逐本屆的市長。"]],"競選":[["ㄐㄧㄥˋ ㄒㄩㄢˇ","為某種特定目的，依法採取一連串有組織、有計畫的競爭行動，以爭取選民投票支持。[例]他決定競選立法委員，為民喉舌，服務鄉梓。"]],"竹子":[["ㄓㄨˊ ˙ㄗ","→竹"]],"竹林":[["ㄓㄨˊ ㄌㄧㄣˊ","竹叢遍布的林子。[例]這座山後面有一大片蒼翠的竹林。"]],"竹筍":[["ㄓㄨˊ ㄙㄨㄣˇ","竹子地下莖所生的嫩芽。可供食用，亦可入藥，有消渴、利尿的療效。[例]竹筍可涼拌，也可煮湯或炒菜，是夏天常見的健康食品。　△竹萌"]],"笑呵呵":[["ㄒㄧㄠˋ ㄏㄜ ㄏㄜ","笑的樣子。[例]弟弟俏皮可愛的模樣，逗得大家笑呵呵。"]],"笑咪咪":[["ㄒㄧㄠˋ ㄇㄧ ㄇㄧ","微笑時眼皮微微靠攏的樣子。形容笑容滿面。[例]她總是笑咪咪的向人打招呼。"]],"笑哈哈":[["ㄒㄧㄠˋ ㄏㄚ ㄏㄚ","大笑的樣子。[例]爸爸帶回妹妹愛吃的巧克力，她高興得笑哈哈。"]],"笑容":[["ㄒㄧㄠˋ ㄖㄨㄥˊ","含笑的面容。[例]笑容滿面、面帶笑容"]],"笑納":[["ㄒㄧㄠˋ ㄋㄚˋ","餽贈禮物時，請人接受的客氣話。[例]一點小意思，不成敬意，請笑納！"]],"笑臉":[["ㄒㄧㄠˋ ㄌㄧㄢˇ","含笑的面孔。[例]笑臉相迎、笑臉迎人"]],"笑話":[["ㄒㄧㄠˋ ㄏㄨㄚˋ","1.能引人發笑的言語，或內容好笑的事物。[例]這則笑話，不僅好笑，還發人深省。_x000D_\n2.表示輕視語氣的詞。有譏諷人自不量力的意思。[例]他想和我比腕力？笑話！"]],"笛聲":[["ㄉㄧˊ ㄕㄥ","警笛、汽笛、笛子等所發出的聲音。[例]笛聲悠揚"]],"符號":[["ㄈㄨˊ ㄏㄠˋ","含特別意義以供辨識的記號。[例]標點符號、注音符號"]],"笨拙":[["ㄅㄣˋ ㄓㄨㄛˊ","反應遲鈍、不靈巧。[例]我雙手笨拙，不善繡花。"]],"第一":[["ㄉㄧˋ ㄧ","最先、最前、最好、最重要的。[例]他好勝心強，每件事都想要得第一。"]],"第一名":[["ㄉㄧˋ ㄧ ㄇㄧㄥˊ","排名第一，最前面、最好的名次。[例]他參加全校的繪畫比賽，得到寫生組的第一名。"]],"第一波":[["ㄉㄧˋ ㄧ ㄅㄛ","第一回合。[例]檢警雙方已經展開第一波的掃黑行動。"]],"第六感":[["ㄉㄧˋ ㄌㄧㄡˋ ㄍㄢˇ","眼、耳、鼻、舌、身等五種身體器官感覺以外的特殊敏感，是一種直覺或靈感，具神祕色彩。[例]他的第六感一向很靈，你最好相信他的直覺。"]],"筆挺":[["ㄅㄧˇ ㄊㄧㄥˇ","1.如筆般的挺直。[例]忠烈祠前的衛兵筆挺的站著，動也不動。\n2.形容衣服熨燙後，布面平順，摺紋很直。[例]弟弟每天都穿著筆挺的制服上學去。"]],"筆桿":[["ㄅㄧˇ ㄍㄢˇ","1.筆的柄桿。[例]他在思考時，習慣一手耍弄筆桿。\n2.借指文人的筆。[例]他是靠搖筆桿兒過活的。"]],"筆畫":[["ㄅㄧˇ ㄏㄨㄚˋ","文字書寫的一筆一畫。我國書法將筆畫分為點、橫、豎、撇、折等。[例]龜字的筆畫十分複雜，老師要我們特別注意。"]],"筆直":[["ㄅㄧˇ ㄓˊ","像筆桿一樣挺直。[例]在軍隊中，當班長一聲令下，喊立正，士兵們的身子個個挺得筆直。"]],"筆端":[["ㄅㄧˇ ㄉㄨㄢ","筆頭。借指文章、書畫等作品。[例]他以天下蒼生為念，眼見生靈塗炭，悲憫之情不時流露於筆端。"]],"筆筒":[["ㄅㄧˇ ㄊㄨㄥˇ","筒形的插筆用具。[例]這筆筒是用易開罐做成的。"]],"筆跡":[["ㄅㄧˇ ㄐㄧ","文字書寫的架構或習慣筆法。[例]從筆跡來看，這兩封信是出自於同一人。"]],"等不及":[["ㄉㄥˇ ㄅㄨˋ ㄐㄧˊ","耐不住、迫不及待。[例]他猶豫再三，還是不肯開口說話，大家都等不及了。"]],"等候":[["ㄉㄥˇ ㄏㄡˋ","等待。[例]他在客廳來回踱步，焦急地等候遲遲未歸的孩子。"]],"等待":[["ㄉㄥˇ ㄉㄞˋ","等候。[例]天未亮，許多遊客便已爬上山頂等待觀看日出。"]],"等於":[["ㄉㄥˇ ㄩˊ","相等、相同。[例]多讀好書等於多交益友。"]],"等第":[["ㄉㄥˇ ㄉㄧˋ","等級次第。[例]這家百貨公司分區擺設不同等第的商品，因應不同需求的顧客參觀選購。"]],"等級":[["ㄉㄥˇ ㄐㄧˊ","品級、次第。[例]果農將水果區分等級包裝出售。"]],"等距":[["ㄉㄥˇ ㄐㄩˋ","相等的距離。[例]這條路上的行道樹以等距種植，看起來十分整齊。"]],"筋疲力竭":[["ㄐㄧㄣ ㄆㄧˊ ㄌㄧˋ ㄐㄧㄝˊ","形容非常疲倦。[例]為了籌備這次的活動，他忙得筋疲力竭。"]],"筋骨":[["ㄐㄧㄣ ㄍㄨˇ","筋肉及骨骼。[例]天將降大任於是人也，必先苦其心志，勞其筋骨。（《孟子．告子下》"]],"答允":[["ㄉㄚ ㄩㄣˇ","答應、應允。[例]他的這項決定，希望能得到父親的答允。"]],"答應":[["ㄉㄚ ㄧㄥˋ","1.應聲回答。[例]剛才那麼大聲叫你，為什麼不答應？\n2.允許、承諾。[例]既然答應了，就要盡心去做。"]],"答案":[["ㄉㄚˊ ㄢˋ","問題的解答。[例]這題數學的正確答案是什麼？"]],"答腔":[["ㄉㄚ ㄑㄧㄤ","回答。[例]跟他講話，他總是不答腔。"]],"答詢":[["ㄉㄚˊ ㄒㄩㄣˊ","回答詢問的事情。[例]縣長在議會開議期間，一定要親自到議會去答詢。"]],"策動":[["ㄘㄜˋ ㄉㄨㄥˋ","發動、推動。[例]為了奪權，他策動了這場政變。"]],"策反":[["ㄘㄜˋ ㄈㄢˇ","我方工作人員滲透敵人內部，與敵方人員建立情誼，以各種方法說服敵方人員或其首腦，在適當時機接受我方指揮，為我方服務。[例]在下一次選舉前，他們將策反部分反對派人士，投靠我方。"]],"策士":[["ㄘㄜˋ ㄕˋ","有計謀的人。[例]今天總經理有此決定，必是他身邊的策士所獻的謀略。"]],"筷子":[["ㄎㄨㄞˋ ˙ㄗ","用來夾飯菜或其他東西的長條形用具。多用木、竹、金屬等材料製成。[例]用筷子夾菜，是運用物理學中的槓桿原理。　◎"]],"算計":[["ㄙㄨㄢˋ ㄐㄧˋ","1.考慮、計劃。[例]這件事還需要多加算計，才能決定。\n2.計算、約計。[例]爸爸算計著說：「今年春節可以休息六天。」\n3.暗中謀害別人。[例]他的心胸狹窄，一天到晚總想算計人。"]],"管弦":[["ㄍㄨㄢˇ ㄒㄧㄢˊ","管樂和弦樂。泛指音樂。[例]隔壁張家是個音樂世家，每日的管弦之聲不絕於耳。"]],"管教":[["ㄍㄨㄢˇ ㄐㄧㄠˋ","1.保證、一定。[例]你若是再執迷不悟，管教你有嚐不完的苦頭。\n\t\n2.約束並教導。[例]小明的父親管教方式失當，經過學校老師充分溝通後，已大有改善了。"]],"管理":[["ㄍㄨㄢˇ ㄌㄧˇ","管轄經理。[例]他管理這棟大廈已有十幾年了，住戶們對他的工作表現非常滿意。"]],"箭步":[["ㄐㄧㄢˋ ㄅㄨˋ","一下子竄得很遠的腳步。比喻移動身體的速度極快。[例]他一個箭步，上籃擦板得分，為本隊拿下致勝的關鍵分數。"]],"節制":[["ㄐㄧㄝˊ ㄓˋ","限制使合宜不過度。[例]吃東西要懂得節制，才能保持腸胃的正常功能。"]],"節奏":[["ㄐㄧㄝˊ ㄗㄡˋ","1.音樂中交替出現有規律的強弱、長短的現象。[例]節奏的快慢強弱，是音樂帶給人不同感受的要素。\n2.比喻有規律的進行流程。[例]改變生活節奏常可賦予生命新氣象。"]],"節目":[["ㄐㄧㄝˊ ㄇㄨˋ","泛指各種演出活動的項目。[例]特別節目、電視節目、廣播節目"]],"節省":[["ㄐㄧㄝˊ ㄕㄥˇ","節約儉省。[例]由於家境貧困，他從小就養成節省的習慣。"]],"範例":[["ㄈㄢˋ ㄌㄧˋ","可以當做模範的事例。[例]他對這件事的處理方法，可以做為大家依循的範例。"]],"篇幅":[["ㄆㄧㄢ ㄈㄨˊ","指文章的長短，或排版時所占版面的位置大小。[例]這篇稿子所占的篇幅太大，恐怕得刪短一點。"]],"篇目":[["ㄆㄧㄢ ㄇㄨˋ","1.書籍中篇章的標題。[例]訂定篇目是著書前的重要工作之一。\n2.書籍中篇章標題的目次。[例]一本書的篇目通常放在全書的前面，以利讀者查詢。"]],"築堤":[["ㄓㄨˊ ㄊㄧˊ","建築堤防。[例]築堤修路"]],"築巢":[["ㄓㄨˊ ㄔㄠˊ","修建窩巢。[例]燕子往往利用枯草、泥土和唾液來築巢。"]],"篳路藍縷":[["ㄅㄧˋ ㄌㄨˋ ㄌㄢˊ ㄌㄩˇ","篳路指柴車，藍縷指破衣服。駕柴車，穿破衣，以開闢土地。比喻創造事業的艱苦、不易。語出《左傳．宣公十二年》。[例]由於前人的篳路藍縷、辛勤付出，我們才有今日富強的局面。"]],"簇擁":[["ㄘㄨˋ ㄩㄥˇ","群圍著。[例]大明星一現身，總有許多影迷簇擁在他身旁。"]],"簡介":[["ㄐㄧㄢˇ ㄐㄧㄝˋ","簡明扼要的介紹。[例]一般國家公園多備有手冊，簡介園內的環境和歷史。"]],"簡化":[["ㄐㄧㄢˇ ㄏㄨㄚˋ","化繁瑣為簡單。[例]監理處決定開辦通訊業務，簡化民眾申請手續。"]],"簡單":[["ㄐㄧㄢˇ ㄉㄢ","1.簡易單純，不複雜。[例]面對記者的追問，他只簡單回覆，不願多說。\n2.平凡，與一般人或事物相同。[例]這個人不簡單，你可別小看了他！"]],"簡陋":[["ㄐㄧㄢˇ ㄌㄡˋ","簡單粗陋。[例]工程期間，他們搭建簡陋的工寮暫作棲身之所。"]],"簽名":[["ㄑㄧㄢ ㄇㄧㄥˊ","簽署名字。[例]這份合約需要本人親筆簽名才能生效。"]],"簽收":[["ㄑㄧㄢ ㄕㄡ","收到信件或物品後，在指定的單據上蓋印、簽字，表示已經收到。[例]重要掛號郵件須由收件人親自簽收。"]],"簽證":[["ㄑㄧㄢ ㄓㄥˋ","1.一國主管機關在本國或外國公民的護照或其他旅行證件上簽注、蓋印，表示准其出入該國國境或過境的手續。[例]落地簽證\n2.准許其他國家或地區人民進入國境的入境許可文件。[例]要出入外國國境，事先均須取得該國的簽證。"]],"籃子":[["ㄌㄢˊ ˙ㄗ","用籐、竹、塑料等製成的盛物器具。[例]媽媽總是帶著籃子去買菜，以減少使用塑膠袋，為環保盡一份心力。　◎"]],"籃框":[["ㄌㄢˊ ㄎㄨㄤ","裝置在籃板上作為投球目標的鐵圈。[例]這個球因碰到籃框而彈了出來。"]],"籃球":[["ㄌㄢˊ ㄑㄧㄡˊ","1.一種球類運動。由美國人詹姆斯˙奈史密斯於西元1891年發明。因早期將球投於桃籃中而得名。所屬的十三條簡則是參考橄欖球、足球、曲棍球等球類運動而制定。1893年成立國際業餘籃球會後，成為奧運正式比賽項目。1976年納入女子奧運正式比賽項目。　◎_x000D_\n2.籃球運動所使用的球。用皮、橡膠或人造橡膠等製成，正圓形，周長約75至78公分，重量約600至650公克。"]],"籌備":[["ㄔㄡˊ ㄅㄟˋ","事先預備計劃。[例]經過幾年的籌備，這家公司終於開張了。"]],"籌劃":[["ㄔㄡˊ ㄏㄨㄚˋ","籌備策劃。[例]這次的義賣活動是由他精心籌劃的。"]],"籠罩":[["ㄌㄨㄥˊ ㄓㄠˋ","由四面八方加以覆蓋。[例]父親受傷至今仍昏迷不醒，使全家籠罩在一片愁雲慘霧之中。"]],"籬笆":[["ㄌㄧˊ ㄅㄚ","用竹條或木條編成的柵欄。[例]爸爸在籬笆旁種了許多花草，使院落顯得更雅緻。"]],"米漿":[["ㄇㄧˇ ㄐㄧㄤ","用米和花生磨製而調成的濃稠汁液。[例]一杯米漿，一根油條，就是他多年來固定不變的早餐。"]],"米粒":[["ㄇㄧˇ ㄌㄧˋ","米的顆粒。[例]他們家的經濟情況很差，米缸裡連顆米粒也都沒有。"]],"米酒":[["ㄇㄧˇ ㄐㄧㄡˇ","用米釀製成的酒。[例]米酒是國人做菜常用的佐料。"]],"粉末":[["ㄈㄣˇ ㄇㄛˋ","細末狀的固體顆粒。[例]幼兒吃的藥，多半會先把藥粒碾成粉末。"]],"粉碎":[["ㄈㄣˇ ㄙㄨㄟˋ","1.形容碎裂成極小塊。[例]妹妹不小心將爸爸心愛的花瓶摔得粉碎。\n2.澈底擊破、打敗。[例]由於大家團結一致，粉碎了敵人分化我們的陰謀。"]],"粉筆":[["ㄈㄣˇ ㄅㄧˇ","用白堊或熟石膏製成，細條狀，用來在黑板書寫、畫圖的筆。[例]在投影機及電腦未發明之前，老師只能依賴用粉筆在黑板上板書的方式教學。"]],"粉紅":[["ㄈㄣˇ ㄏㄨㄥˊ","用白色和紅色調和成的顏色。[例]她今天一身粉紅系列的打扮，看起來非常俏麗。"]],"粉蝶":[["ㄈㄣˇ ㄉㄧㄝˊ","動物名。昆蟲綱鱗翅目粉蝶科。成蟲多為白、黃、橙色，喜愛十字花科植物，常產卵於菜葉反面，以葉片為食。最常見者為白粉蝶，分布於世界各地。其他尚有小巧美麗的黃蝶，及華貴的紅衽蝶等。幼蟲青綠而細長，為農業害蟲。　◎"]],"粗俗":[["ㄘㄨ ㄙㄨˊ","粗鄙庸俗。[例]他言語粗俗，非常沒有教養。"]],"粗大":[["ㄘㄨ ㄉㄚˋ","又粗又大。[例]臉上皮膚的油脂分泌過多容易造成毛細孔粗大。"]],"粗心":[["ㄘㄨ ㄒㄧㄣ","做事不仔細、不小心。[例]他做事粗心，老是出錯。"]],"粗獷":[["ㄘㄨ ㄍㄨㄤˇ","粗野狂放。[例]他一臉絡腮鬍，看起來很粗獷。"]],"精明":[["ㄐㄧㄥ ㄇㄧㄥˊ","聰敏仔細。[例]他做事一向精明，怎麼可能會犯這種錯呢？"]],"精湛":[["ㄐㄧㄥ ㄓㄢˋ","精良深厚。[例]李醫師的醫術精湛，一生救人無數。"]],"精益求精":[["ㄐㄧㄥ ㄧˋ ㄑㄧㄡˊ ㄐㄧㄥ","不斷努力求進步。[例]我們做事應秉持精益求精的態度，如此才能更臻完美。"]],"精簡":[["ㄐㄧㄥ ㄐㄧㄢˇ","精練簡要。[例]這篇文章內容精簡，見解獨到，是篇上乘之作。"]],"精緻":[["ㄐㄧㄥ ㄓˋ","精巧細緻。[例]桌上那些精緻的小點心是誰做的呢？"]],"精華":[["ㄐㄧㄥ ㄏㄨㄚˊ","事物最精粹，最有價值的部分。[例]播出的影片濃縮了整個球季比賽的精華，精彩可期，收視率一定不錯。"]],"精采":[["ㄐㄧㄥ ㄘㄞˇ","優美出色。[例]今晚的芭蕾舞表演十分精采，觀眾個個看得如痴如醉。"]],"精鍊":[["ㄐㄧㄥ ㄌㄧㄢˋ","1.敏銳幹練。[例]他做事精鍊，是個不可多得的領導人才。\n2.簡潔精要。[例]文章應力求精鍊，不宜冗長。"]],"精闢":[["ㄐㄧㄥ ㄆㄧˋ","深入而透澈。[例]他常在報章雜誌發表精闢的政治言論，內容獨到，頗受好評。"]],"糊里糊塗":[["ㄏㄨˊ ㄌㄧˇ ㄏㄨˊ ㄊㄨˊ","形容人行事極為迷糊或不明道理。[例]他做事糊里糊塗的，很難委以重任。"]],"糖分":[["ㄊㄤˊ ㄈㄣˋ","含糖的成分。[例]這杯飲料的糖分太高，甜得叫人受不了！"]],"糖廠":[["ㄊㄤˊ ㄔㄤˇ","將甘蔗、甜菜、米、麥等原料，提煉製成糖類的工廠。[例]這一大片甘蔗園都是鎮上那家糖廠的。"]],"糖果":[["ㄊㄤˊ ㄍㄨㄛˇ","以糖為主要原料，再加入香料、食用色素等其他材料製成的甜味食品。因選用的材料及加工的過程不同，製成品的種類極多。如軟糖、牛奶糖、巧克力糖等。[例]食用過多糖果容易引起蛀牙。"]],"糖水":[["ㄊㄤˊ ㄕㄨㄟˇ","將糖溶於水所製成的溶液。[例]她最愛吃甜食，每次吃刨冰總要多淋上幾杓糖水。"]],"糞便":[["ㄈㄣˋ ㄅㄧㄢˋ","大便。[例]對於農家而言，糞便是一種天然肥料。"]],"糟糕":[["ㄗㄠ ㄍㄠ","指事情或情況很壞。[例]火車快開了，他若趕不上就糟糕了。"]],"糟糠":[["ㄗㄠ ㄎㄤ","比喻粗食。亦借指貧賤時共患難的妻子。[例]糟糠自厭、糟糠之妻、不棄糟糠"]],"糟蹋":[["ㄗㄠ ㄊㄚˋ","1.浪費或損壞而不加愛惜。[例]那包餅乾還沒吃完就被丟棄，真是糟蹋食物。\n2.侮辱、蹂躪。[例]他說話老愛糟蹋人，難怪人緣不好。"]],"糾察":[["ㄐㄧㄡ ㄔㄚˊ","1.糾舉、督察以維持公共秩序。[例]他本週擔任糾察工作，所以必須提早到校。\n2.指糾舉、督察以維持公共秩序的人。[例]校門口每天都有糾察輪值，以維護同學們上下學的交通安全。"]],"糾察隊":[["ㄐㄧㄡ ㄔㄚˊ ㄉㄨㄟˋ","維持群體秩序的小隊編制。[例]小明表現優良，被學校選為糾察隊的隊長。"]],"糾纏":[["ㄐㄧㄡ ㄔㄢˊ","1.互相纏繞。[例]那兩棵樹互相糾纏環繞，宛如一對恩愛的夫婦。\n2.煩擾不休。[例]遇到糾纏不清的人，最好的辦法就是不理他。"]],"紀律":[["ㄐㄧˋ ㄌㄩˋ","綱紀規章。[例]服從命令、嚴守紀律是軍人的本分。"]],"紀念冊":[["ㄐㄧˋ ㄋㄧㄢˋ ㄘㄜˋ","為紀念具有特殊意義的事情而製作或發行的簿冊。[例]畢業紀念冊"]],"紀念品":[["ㄐㄧˋ ㄋㄧㄢˋ ㄆㄧㄣˇ","可供紀念的物品。[例]他每到一個國家旅行，都會買一些富有地方風味的紀念品。"]],"紀念碑":[["ㄐㄧˋ ㄋㄧㄢˋ ㄅㄟ","為紀念某重大事件、功績或有特殊貢獻的人物所立的石碑。[例]創校紀念碑"]],"約束":[["ㄩㄝ ㄕㄨˋ","管束。[例]父母親應該適當約束孩子的行為，不可太過寵愛放縱。"]],"約莫":[["ㄩㄝ ˙ㄇㄛ","大約、大概。[例]這次的同學會，約莫有二十幾個人會來。"]],"紅燒":[["ㄏㄨㄥˊ ㄕㄠ","一種烹調方式。將食物略作炒炸後，加入醬油、冰糖等調味料，燜燒至熟。如紅燒肉、紅燒獅子頭。[例]這道菜如果改用紅燒，味道會更好。"]],"紅腫":[["ㄏㄨㄥˊ ㄓㄨㄥˇ","組織細胞發炎腫大的現象。[例]傷口處理不當，常會引起細菌感染，導致發炎紅腫。"]],"紅色":[["ㄏㄨㄥˊ ㄙㄜˋ","1.像鮮血般的顏色。[例]她穿了一件紅色的外套，看起來鮮豔亮麗。\n2.大陸地區用來象徵對於革命或政治警覺性高的特質。[例]紅色娘子軍，既紅又專。"]],"紋路":[["ㄨㄣˊ ㄌㄨˋ","物體表面呈現的線形條紋。[例]每個人的手心表面，都有許多長短不一的紋路交錯其上。"]],"納稅":[["ㄋㄚˋ ㄕㄨㄟˋ","繳納稅款。[例]政府各項建設所需經費的來源，主要是依靠國民的納稅而來。"]],"純樸":[["ㄔㄨㄣˊ ㄆㄨˊ","純厚樸實。[例]都市的繁華喧囂，和鄉村的純樸安適，形成強烈的對比。"]],"純潔":[["ㄔㄨㄣˊ ㄐㄧㄝˊ","心地純一清淨，沒有邪惡的念頭。[例]我們應該常保純潔的赤子之心。"]],"純粹":[["ㄔㄨㄣˊ ㄘㄨㄟˋ","完全。[例]這次的不愉快，純粹是他的固執所造成的。"]],"純金":[["ㄔㄨㄣˊ ㄐㄧㄣ","1.不含雜質的金子。即24ｋ金。[例]純金的可塑性強，延展性高。\n2.用純金打造的。[例]純金手鍊、純金項鍊"]],"紗布":[["ㄕㄚ ㄅㄨˋ","用紗織成的薄布。經過消毒後，可用以包紮外傷。[例]他一星期前出了車禍，至今手上仍裹著紗布。"]],"紙上談兵":[["ㄓˇ ㄕㄤˋ ㄊㄢˊ ㄅㄧㄥ","僅擅長理論上的軍事談論，卻無法在戰場上實際運用。比喻不合實際的空談、議論。典出《史記．卷八十一．廉頗藺相如傳》。[例]這些提案只是紙上談兵，所以在開會討論時全數遭到否決。"]],"紙巾":[["ㄓˇ ㄐㄧㄣ","紙製成的手巾或餐巾。[例]餐館通常會準備紙巾供顧客使用。"]],"紙漿":[["ㄓˇ ㄐㄧㄤ","製紙的原料。將木材、破布等物品，經過蒸煮、漂白等手續處理後所得的糊狀纖維素，攤平烘乾後就成為紙。[例]他們將回收的紙張溶成紙漿，預備做成再生紙。"]],"紙牌":[["ㄓˇ ㄆㄞˊ","紙製的娛樂用品。如用作賭具的撲克牌、四色牌等。[例]圓形紙牌曾經是六十年代許多小孩的童玩。"]],"紙鈔":[["ㄓˇ ㄔㄠ","紙質的貨幣，多由國家銀行或政府授權的銀行發行。也稱為「紙幣」。[例]百元紙鈔、千元紙鈔"]],"級距":[["ㄐㄧˊ ㄐㄩˋ","等級間的差距。[例]政府按照人民收入的高低，分成各種稅率級距。"]],"紛亂":[["ㄈㄣ ㄌㄨㄢˋ","雜亂。[例]現在我的思緒非常紛亂，無法立即做出判斷。"]],"紛爭":[["ㄈㄣ ㄓㄥ","糾紛爭執。[例]國界劃定不明，是引起兩國紛爭的主因。"]],"紛紛":[["ㄈㄣ ㄈㄣ","1.多而雜亂的樣子。[例]白雪紛紛何所似？（南朝宋．劉義慶《世說新語．言語》）_x000D_\n2.接連不斷的樣子。[例]颱風即將來襲，漁船紛紛停止作業，進港避風。"]],"素材":[["ㄙㄨˋ ㄘㄞˊ","文學或藝術作品裡所用的題材。[例]這篇小說以作者旅遊的經歷為創作素材，內容十分生動有趣。"]],"素淨":[["ㄙㄨˋ ㄐㄧㄥˋ","顏色或裝飾樸素不濃豔。[例]那女孩有張素淨的臉龐，出奇的秀氣，頗惹人憐愛。"]],"紡紗":[["ㄈㄤˇ ㄕㄚ","將短的纖維聚集，加以適當操作而紡製成紗線。[例]紡紗的工作需要耐心與技術。"]],"紡織":[["ㄈㄤˇ ㄓ","紡紗與織布。[例]這家博物館典藏的紡織工藝品，極具民族特色。"]],"紡織業":[["ㄈㄤˇ ㄓ ㄧㄝˋ","專門從事紡紗織布等工作的工業。[例]紡織業是臺灣六、七十年代最重要的工業，也帶動了當時國內的經濟發展。"]],"索性":[["ㄙㄨㄛˇ ㄒㄧㄥˋ","乾脆、直接了當。[例]大家索性把話說清楚，免得造成不必要的誤會。"]],"索討":[["ㄙㄨㄛˇ ㄊㄠˇ","討取。[例]年關一到，債主都會上門向債務人索討欠債。"]],"索賄":[["ㄙㄨㄛˇ ㄏㄨㄟˋ","索取賄賂。[例]公務人員不可藉職權之便索賄。"]],"紫色":[["ㄗˇ ㄙㄜˋ","由紅色與藍色調和而成的顏色。[例]紫色玫瑰品種稀有，價格也不便宜。"]],"紫蘇":[["ㄗˇ ㄙㄨ","植物名。脣形科紫蘇屬，一年生草本。莖方形，葉卵形，夏開淡紅色脣形花。莖、葉、果實皆可入藥，有鎮咳、健胃、利尿等作用。[例]用紫蘇醃製的梅子，是十分開胃的食品。"]],"紮營":[["ㄓㄚˊ ㄧㄥˊ","屯駐營寨。[例]這塊空地背山面水，非常適合紮營。"]],"累壞":[["ㄌㄟˋ ㄏㄨㄞˋ","因操勞過度而精神、體力不佳。[例]這個月來每天加班，把他累壞了。"]],"累積":[["ㄌㄟˇ ㄐㄧ","層積聚集。[例]投資理財需要專業的知識，更要經驗的累積，才能提高理財的成效。"]],"細小":[["ㄒㄧˋ ㄒㄧㄠˇ","極小。[例]孫悟空的金箍棒可以縮得十分細小，藏在耳朵裡。"]],"細心":[["ㄒㄧˋ ㄒㄧㄣ","用心，心思周密。[例]做完考卷，請細心檢查一遍。"]],"細膩":[["ㄒㄧˋ ㄋㄧˋ","1.細緻潤滑。[例]這家麵包店所推出的布丁，口感細膩、味道香濃，很受顧客喜愛。\n2.精細周密。[例]這篇文章描寫景物的手法非常細膩，是難得的好作品。"]],"細菌":[["ㄒㄧˋ ㄐㄩㄣˋ","一種單細胞的微生物。可分為桿菌、球菌和螺旋菌三類，以分裂法繁殖，多靠寄生或腐生方法生存，普遍分布在自然界中。有些細菌會引起嚴重的疾病，如霍亂、破傷風等，有些則對人類有益處，如乳酸菌。[例]傷口若處理不當，將會引起細菌感染。"]],"紳士":[["ㄕㄣ ㄕˋ","舊時多指地主或退職的官員。現泛指地方上有聲望的人或是舉止斯文有禮的人。[例]他溫文儒雅的紳士風度，吸引許多異性的愛慕。"]],"終了":[["ㄓㄨㄥ ㄌㄧㄠˇ","結束、完畢。[例]他在比賽終了前投進逆轉的三分球，觀眾都熱情歡呼。"]],"終於":[["ㄓㄨㄥ ㄩˊ","最後、總算。表示所預料或期望的情況到最後還是發生了。[例]經過多次試驗後，太空梭終於發射成功。"]],"終結":[["ㄓㄨㄥ ㄐㄧㄝˊ","結束。[例]辯論終結、審判終結"]],"組合":[["ㄗㄨˇ ㄏㄜˊ","1.將個別零件組織成為一整體。[例]他花了一整天的時間，終於把那架飛機模型組合完成了。\n2.數學上指從相異的諸物中，每次取出定數，不管次序，而求其相配的種類數，稱為「組合」。[例]數學老師深怕同學們不明瞭，因此對於排列組合的講解特別仔細。"]],"組員":[["ㄗㄨˇ ㄩㄢˊ","一個編組內的人員。[例]這件企劃案須經全體組員贊成後才能執行。"]],"組織":[["ㄗㄨˇ ㄓ","1.構成。[例]他們決定組織一個文藝社團。\n2.一群人為達特定目標，經由一定的程序所組成的團體。[例]政府組織、議會組織、商業組織\n3.生物學上指多個細胞生物體中，各細胞和細胞間質依一定秩序聯合為一體，並產生一定功能的基本結構。[例]肌肉組織、神經組織"]],"絆腳石":[["ㄅㄢˋ ㄐㄧㄠˇ ㄕˊ","在路上會絆人腳的石頭。比喻阻礙進展的人或事物。[例]猶豫是成功的絆腳石。"]],"結伴":[["ㄐㄧㄝˊ ㄅㄢˋ","互相結成同伴。[例]結伴同行"]],"結冰":[["ㄐㄧㄝˊ ㄅㄧㄥ","水在冰點以下時凝聚成冰塊的現象。[例]冬天時，高緯度地區的河川湖泊常會結冰。"]],"結束":[["ㄐㄧㄝˊ ㄕㄨˋ","終結、了結。[例]雙方因實力相差懸殊，因此比賽在七局上半場便提前結束。"]],"結果":[["ㄐㄧㄝˊ ㄍㄨㄛˇ","1.植物長出果實。[例]園中桃樹現在已經結果纍纍，不久便可採摘了。\n2.事物最後的結局。[例]這件事終於在大家通力合作下得到圓滿的結果。"]],"結構":[["ㄐㄧㄝˊ ㄍㄡˋ","各組織成分的搭配、排列或構造。[例]房屋結構、文章結構、原子結構"]],"絕對":[["ㄐㄩㄝˊ ㄉㄨㄟˋ","1.一定、肯定。[例]任何事情，如果不努力，是絕對無法成功的。\n2.不依靠任何條件而獨立存在，而且恆定不起變化。凡事物有對等關係的稱為「相對」 ，僅有單方面的稱為「絕對」。[例]人世間有很多事情都不是絕對的，你又何必如此固 執己見呢？"]],"絕技":[["ㄐㄩㄝˊ ㄐㄧˋ","超群卓越，無人能及的技能。[例]他擁有模仿各種動物聲音的絕技。"]],"絕無僅有":[["ㄐㄩㄝˊ ㄨˊ ㄐㄧㄣˇ ㄧㄡˇ","只有一個，絕對再沒別的了。形容極其少有。[例]這真是場絕無僅有的激烈比賽，參賽者莫不使出渾身解數。"]],"絕跡":[["ㄐㄩㄝˊ ㄐㄧ","絕滅、斷絕蹤跡。[例]這種野生動物因為人為捕殺及自然環境的惡化，已日漸絕跡了。"]],"絢爛":[["ㄒㄩㄢˋ ㄌㄢˋ","光彩燦爛奪目。[例]黃昏時，天空布滿了絢爛的彩霞。"]],"絢麗":[["ㄒㄩㄢˋ ㄌㄧˋ","燦爛美麗。[例]春天繁花盛開，山野絢麗多彩，美不勝收。"]],"絢麗多姿":[["ㄒㄩㄢˋ ㄌㄧˋ ㄉㄨㄛ ㄗ","形容色彩亮麗繽紛的樣子。[例]聖誕節將到，各大百貨公司的櫥窗都妝點得絢麗多姿。"]],"給予":[["ㄐㄧˇ ㄩˇ","交付、提供。[例]他因為受傷無法承擔家計的事件一經報導，社會各界紛紛給予援助。"]],"給與":[["ㄐㄧˇ ㄩˇ","交付、提供。[例]對於損失慘重的災區農戶，政府決定給與全額補助。"]],"絨布":[["ㄖㄨㄥˊ ㄅㄨˋ","用棉紗或羊毛等織成，表面有一層細絨的布料。如絲絨、燈芯絨、法蘭絨等。[例]絨布的觸感柔軟，製成衣裳，穿在身上十分溫暖。"]],"絨毛":[["ㄖㄨㄥˊ ㄇㄠˊ","1.物體表面上所披覆的柔細短毛。[例]絨毛玩具\n2.小腸內壁無數纖細的小指狀突起組織，內有微血管、乳糜管，可增加小腸內壁的吸收面積。[例]小腸內壁的絨毛具有吸收及輸送營養的功能。"]],"絮煩":[["ㄒㄩˋ ㄈㄢˊ","言語煩煩不休。[例]話休絮煩"]],"統一":[["ㄊㄨㄥˇ ㄧ","1.將零散、分離的事物統合為一體。[例]統一天下、統一文字\n2.一致的、沒有差別的。[例]統一標準、統一訂價"]],"統帥":[["ㄊㄨㄥˇ ㄕㄨㄞˋ","1.統領指揮。[例]統帥三軍\n2.國家軍隊的最高指揮官。通常指國家元首而言。[例]依照中華民國憲法的規定，總統是三軍的最高統帥。"]],"統治":[["ㄊㄨㄥˇ ㄓˋ","政府運用權力支配領土和國民的行為。[例]統治階級、威權統治、高壓統治"]],"統計":[["ㄊㄨㄥˇ ㄐㄧˋ","1.總括計算。[例]這次颱風來襲，農作物嚴重受損，統計結果大約損失一億元。\n2.收集同一範圍內的事物加以整理、計算，運用數字表示眾多事實的特性，並觀察其全體相關和演變情形而作的比較和研究。[例]公司以民意調查的統計數據作為開發市場的參考。"]],"絲毫":[["ㄙ ㄏㄠˊ","一點點、非常少。[例]他為人很有修養，別人惡意的中傷，他絲毫不在意。"]],"絹印":[["ㄐㄩㄢˋ ㄧㄣˋ","一種印刷方法。以絲、尼龍或鋼絲織成網屏，張覆在框上，印刷時在網屏上圖案以外的部分用藥劑或膠填滿，再以油墨印刷，油彩即透過未填滿的孔隙印刷在承印物上。[例]這幅畫是用絹印的手法製成的，具有和一般圖畫不同的風格。"]],"經典":[["ㄐㄧㄥ ㄉㄧㄢˇ","1.具重要性，可以作為典範的書籍。[例]博覽經典、曠世經典\n2.形容製作精美，可以流傳久遠，成為後世典範的。[例]經典之作、經典名著"]],"經常":[["ㄐㄧㄥ ㄔㄤˊ","指事情發生的頻率很高。[例]他經常在放學之後到書店看書。 △常常、時常"]],"經歷":[["ㄐㄧㄥ ㄌㄧˋ","1.經過、親身遭遇。[例]經歷這次事件，使他深深體會到親情的可貴。\n2.經驗與閱歷。[例]新到任的經理經歷豐富，再困難的事都能迎刃而解。"]],"經濟":[["ㄐㄧㄥ ㄐㄧˋ","1.指人類利用種種財貨，來滿足欲望的一切行為及狀態。通常指一國國民的生產、銷售及分配關係，或指國家、個人的收支狀況。[例]經濟恐慌、經濟建設\n2.節省、不浪費。[例]送禮應講求經濟實惠，價格昂貴的未必是好禮。"]],"經營":[["ㄐㄧㄥ ㄧㄥˊ","1.從事某種事業。[例]這家公司因為經營不善而面臨倒閉的命運。\n2.規劃、安排。[例]他擅於經營自己的人際關係，所以交遊十分廣闊。"]],"經由":[["ㄐㄧㄥ ㄧㄡˊ","通過、經過。[例]本產品經由主管單位檢驗合格，品質無虞。"]],"經絡":[["ㄐㄧㄥ ㄌㄨㄛˋ","中醫上指人體內氣血運行的主幹和分支。即人體內經脈和絡脈的總稱。內連臟腑，外達肢節，灌注全身，無處不到。[例]氣功可疏通經絡、調和血氣，達到保健療病之功效。"]],"經緯":[["ㄐㄧㄥ ㄨㄟˇ","1.編織物品的直線與橫線。[例]織布機上的梭子是用來穿織布匹的經緯。\n\t\n2.指地球上通過南北兩極的經線及與赤道平行的緯線。[例]北迴歸線是地球上一條假想的緯線，位於北緯23.5度。"]],"經過":[["ㄐㄧㄥ ㄍㄨㄛˋ","1.通過、走過。[例]當你經過超市時，可否順便幫我買一瓶醬油？\n2.經由。[例]經過爸媽的分析，我決定先投入職場歷練。\n3.經歷、過程。[例]目擊證人向警方說明車禍的經過。"]],"經驗":[["ㄐㄧㄥ ㄧㄢˋ","1.親自實踐而得的知識或技能。[例]他攀登過無數的高山，是一位經驗豐富的登山嚮導。\n2.經歷體驗。[例]這種事我從沒經驗過，你可不可以教教我？"]],"綠地":[["ㄌㄩˋ ㄉㄧˋ","有草木生長的地面。[例]一到夏天，門前的綠地，不時可見成群的蝴蝶、蜜蜂飛舞其間。"]],"綠籬":[["ㄌㄩˋ ㄌㄧˊ","用草木密植而成的圍籬。[例]爺爺決定在房子的四周栽植扶桑、七里香等作為綠籬。"]],"綠色":[["ㄌㄩˋ ㄙㄜˋ","1.像草和樹葉一般的顏色。[例]學生和上班族應多看遠處的綠色景物，以減輕眼睛過度疲勞所造成的不適。\n2.無汙染的；符合環保要求的。[例]綠色是環保的象徵，現代人講究環保，綠色食品也就大行其道。"]],"綠蔭":[["ㄌㄩˋ ㄧㄣˋ","樹蔭。[例]烈日當空，兩、三個農夫正在濃密的綠蔭下乘涼、休息。"]],"綠藻":[["ㄌㄩˋ ㄗㄠˇ","泛指具有細胞壁，含葉綠體的低等藻類。多產於淡水和潮溼的土壤中，少數生長在海裡。通常呈綠色，形態可分為單細胞型、群體型、絲狀型及膜狀型。如綠球藻、空球藻、水棉等。[例]有些綠藻長在蓄水池或池塘中，會使水產生一股腥味。"]],"綢繆":[["ㄔㄡˊ ㄇㄡˊ","1.親密、纏綿。[例]情意綢繆\n2.修補器物，使之堅固。[例]未雨綢繆"]],"維妙維肖":[["ㄨㄟˊ ㄇㄧㄠˋ ㄨㄟˊ ㄒㄧㄠˋ","模仿得精細巧妙，逼真傳神。[例]他善於模仿名人，尤其是模仿政治人物的舉止，簡直維妙維肖。"]],"維持":[["ㄨㄟˊ ㄔˊ","維護保持。[例]為了維持身體健康，他每天都去晨泳。"]],"維繫":[["ㄨㄟˊ ㄒㄧˋ","維持連繫。[例]他們分隔南北兩地，平日只能靠電話來維繫感情。"]],"維護":[["ㄨㄟˊ ㄏㄨˋ","維持保護。[例]每個國民都應維護公共環境衛生，不亂丟紙屑煙蒂、不亂倒垃圾。"]],"綱要":[["ㄍㄤ ㄧㄠˋ","總綱要旨。[例]寫作論文前應先擬訂大體綱要。"]],"網球":[["ㄨㄤˇ ㄑㄧㄡˊ","1.一種球類運動。在長方形球場中，中央張網為界，由二人單打或四人雙打，兩方分立，各用拍子將碰地一次或在空中的球互擊過網，以使對方無法將球擊回為得分關鍵。先得四分為勝一局，先得六局為勝一盤，男子比賽採五盤三勝制，女子則為三盤兩勝制。　◎\n2.網球運動所使用的球。裡面為橡膠，外面用尼龍或毛織品包裹。比賽用的網球為白色或黃色。[例]他帶了一袋網球到球場練習發球。"]],"網羅":[["ㄨㄤˇ ㄌㄨㄛˊ","搜求、羅致。引申為任用人才。[例]球隊將網羅各方好手，以提升實力。"]],"網路":[["ㄨㄤˇ ㄌㄨˋ","1.由電阻、電感、電容、電晶體等電子元件構成的複雜電路。[例]如果把ＩＣ版放大千倍來看，可以發現其中的網路是十分複雜的。\n2.利用電纜線或現成的電信通訊線路，配合網路卡或數據機，將伺服器與各單獨電腦連接起來，在軟體的運作下，達成資訊傳輸、資料共享等功能。此種系統即稱為「網路」。[例]區域網路、網際網路"]],"綴飾":[["ㄓㄨㄟˋ ㄕˋ","點綴裝飾。[例]這件衣服綴飾了許多亮片，適合在晚宴上穿著。"]],"綺窗":[["ㄑㄧˇ ㄔㄨㄤ","雕飾精美的窗子。[例]來日綺窗前，寒梅著花未？（唐．王維〈雜詩〉三首之二）"]],"綺麗":[["ㄑㄧˇ ㄌㄧˋ","曼妙美麗。[例]影片中那段綺麗的戀史，令觀眾難以忘懷。"]],"綻放":[["ㄓㄢˋ ㄈㄤˋ","開放。[例]春天一到，百花綻放，景色十分迷人。"]],"綻開":[["ㄓㄢˋ ㄎㄞ","1.裂開。[例]這件衣服因為縫得不實，不久就綻開了一條裂縫。\n2.開放、展開。[例]一聽到這個好消息，她的臉上頓時綻開喜悅的笑容。"]],"綿密":[["ㄇㄧㄢˊ ㄇㄧˋ","柔和周密。[例]他的祕書思路綿密，做事謹慎周到，是不可多得的好幫手。"]],"綿延":[["ㄇㄧㄢˊ ㄧㄢˊ","連續延長。[例]中央山脈高峰綿延，位於臺灣中央偏東，颱風時期往往降低了西部的災害。"]],"綿羊":[["ㄇㄧㄢˊ ㄧㄤˊ","動物名。哺乳綱偶蹄目。角較山羊短小，性溫順，毛長而軟，可織呢絨，並可製裘。[例]人類飼養綿羊的目的是為了取用牠的毛、奶和肉。"]],"綿長":[["ㄇㄧㄢˊ ㄔㄤˊ","長久不絕。[例]爺爺的生日聚會，親友們齊聚一堂，高聲祝福他福壽綿長。"]],"緊密":[["ㄐㄧㄣˇ ㄇㄧˋ","1.十分密切，不可分開。[例]緊密聯結、緊密結合\n2.形容多而連續不斷。[例]這次的歐洲之旅，行程緊密，團員們雖獲益良多但疲憊不堪。"]],"緊張":[["ㄐㄧㄣˇ ㄓㄤ","1.急迫或激烈，使人精神緊繃。[例]這場比賽已經進入最後的緊張階段。\n2.情緒惶恐不安。[例]每次考試我都感到十分緊張。"]],"緊繃":[["ㄐㄧㄣˇ ㄅㄥ","1.捆紮得很緊。[例]這件衣服穿在身上十分緊繃，讓我覺得很不舒服。\n2.形容心情緊張或神情嚴肅不自然。[例]他一整天都緊繃著臉，不知道誰惹他了？"]],"緊閉":[["ㄐㄧㄣˇ ㄅㄧˋ","緊密的閉合。[例]緊閉門窗、緊閉眼睛"]],"線條":[["ㄒㄧㄢˋ ㄊㄧㄠˊ","1.用筆繪成的直線、曲線或折線。[例]這張地圖線條清晰，很容易查索。\n2.形容人的身材或物品的輪廓。[例]這部車造型優美，線條流暢，市場反應良好。"]],"緣故":[["ㄩㄢˊ ㄍㄨˋ","事情發生的因由。[例]因為山區大雨的緣故，所以河流顯得特別湍急。"]],"編制":[["ㄅㄧㄢ ㄓˋ","機關團體內對各單位人員數目及職務的配置。[例]行政編制、正式編制、臨時編制"]],"編寫":[["ㄅㄧㄢ ㄒㄧㄝˇ","蒐集資料加以整理或創作。[例]他自行編寫講義，以輔助教學。"]],"編排":[["ㄅㄧㄢ ㄆㄞˊ","1.依照次序排列。[例]編排隊形\n2.報刊、書籍的編輯和排版。[例]這本書的編排很活潑。\n3.戲劇節目的編寫排演。[例]這部戲的情節編排很緊湊。"]],"編撰":[["ㄅㄧㄢ ㄓㄨㄢˋ","編寫撰述。[例]他將長期蒐集的資料編撰成書。"]],"編曲":[["ㄅㄧㄢ ㄑㄩˇ","1.編寫曲譜，以供演唱或演奏。[例]這首詞經過編曲後，更添幾分韻味。\n2.於樂曲、歌曲主旋律之外，另外編寫添加曲調。[例]這首老歌在重新編曲之後，給人耳目一新的感受。"]],"編班":[["ㄅㄧㄢ ㄅㄢ","將學生、士兵等分別編列在各個班級或單位。[例]這所學校採公開抽籤的方式編班。"]],"編織":[["ㄅㄧㄢ ㄓ","1.將線、柳條等細長的東西交錯穿結而形成面狀的東西。[例]老奶奶悠閒的躺在搖椅上編織毛衣。　◎\n2.比喻抽象的想像、規劃。[例]編織美夢、編織未來"]],"編著":[["ㄅㄧㄢ ㄓㄨˋ","編輯著述。[例]他正著手編著歷代音樂家小傳。"]],"編號":[["ㄅㄧㄢ ㄏㄠˋ","1.排列序號。[例]這些試卷編號之後便彌封，以待送入考場。_x000D_\n2.編定的序號。[例]為求公平，試卷上不寫考生姓名，而以編號識別。"]],"編輯":[["ㄅㄧㄢ ㄐㄧˊ","1.蒐集資料，加以鑑別、選擇、分類、整理、排列和組織。[例]這期校刊由他負責編輯。\n2.製作、編輯書報雜誌的人。[例]他在雜誌社當編輯。"]],"緩慢":[["ㄏㄨㄢˇ ㄇㄢˋ","不快、遲緩。[例]行動緩慢"]],"緩緩":[["ㄏㄨㄢˇ ㄏㄨㄢˇ","緩慢、慢慢。[例]國旗緩緩上升，在藍空中飄揚。"]],"緯度":[["ㄨㄟˇ ㄉㄨˋ","一地經線與赤道間的弧度（角距離）。自赤道到南北兩極各分九十度，在北稱為「北緯」，在南的稱為「南緯」。相對於經度而言。[例]地球赤道的緯度為零度。"]],"練兵":[["ㄌㄧㄢˋ ㄅㄧㄥ","訓練軍隊。[例]練兵的重點在練膽、練力、練技，並涵養智、信、仁、勇、嚴等武德。"]],"練字":[["ㄌㄧㄢˋ ㄗˋ","本指練習書法，後泛指練習寫字。[例]他退休後每日練字，以養性怡情。"]],"練習":[["ㄌㄧㄢˋ ㄒㄧˊ","1.反覆作習，使之熟練。[例]學習語言需要不斷練習，才能進步。\n2.為熟練學習內容而設計的作業。[例]數學老師要求同學將練習帶回家演算，加強學習成效。"]],"縈繞":[["ㄧㄥˊ ㄖㄠˋ","纏繞、環繞。[例]聆聽他的演奏後，美妙的樂音，不時在我腦海中縈繞。"]],"縫合":[["ㄈㄥˊ ㄏㄜˊ","1.把布料、皮料等用針線接合起來。[例]最後再把布偶的前後片縫合，就大功告成了。\n2.在外科手術上，醫生用特製的針和線把傷口補合。[例]傷口縫合後不能亂動，以免繃裂。"]],"縫紉":[["ㄈㄥˊ ㄖㄣˋ","指衣服的剪裁、縫合、補綴等工作。[例]縫紉是家事課程之一。"]],"縫製":[["ㄈㄥˊ ㄓˋ","縫紉製造。[例]她的手很巧，善於縫製衣服。"]],"縫隙":[["ㄈㄥˋ ㄒㄧˋ","空隙。[例]冷風從窗戶的縫隙中吹了進來。"]],"縮小":[["ㄙㄨㄛ ㄒㄧㄠˇ","由大變小。[例]純棉的衣物如果用烘乾機來烘乾，通常都會縮小。"]],"縮短":[["ㄙㄨㄛ ㄉㄨㄢˇ","由長變短。[例]親子之間要常接觸、溝通，才能縮短彼此的距離。"]],"縱使":[["ㄗㄨㄥˋ ㄕˇ","即使。[例]她的心意已決，縱使大家都反對，也要去做。"]],"縱容":[["ㄗㄨㄥˋ ㄖㄨㄥˊ","放任而不加約束。[例]孩子從小就要管教，不能太縱容。"]],"縱火":[["ㄗㄨㄥˋ ㄏㄨㄛˇ","放火。[例]警方前日逮捕一名因金錢糾紛而縱火的嫌犯。"]],"縱然":[["ㄗㄨㄥˋ ㄖㄢˊ","即使。[例]縱然只是一點點的捐助，對需要的人來說，倒也不無小補。"]],"縱虎歸山":[["ㄗㄨㄥˋ ㄏㄨˇ ㄍㄨㄟ ㄕㄢ","比喻放走敵人，後患無窮。[例]當初他因一念之仁而縱虎歸山，竟釀成今日如此嚴重的後患。"]],"縱谷":[["ㄗㄨㄥ ㄍㄨˇ","與山脈的軸線平行的河谷。[例]花東縱谷"]],"縱隊":[["ㄗㄨㄥ ㄉㄨㄟˋ","1.縱向的隊形。[例]請排成縱隊依序入場。\n2.一種軍隊的編制單位。[例]他帶領一縱隊到前線偵探敵情。"]],"縷縷":[["ㄌㄩˇ ㄌㄩˇ","1.一縷一縷。[例]離鄉背井的遊子，每逢佳節倍思親，縷縷鄉愁湧上心頭。\n2.接連不絕的樣子。[例]靜坐在山腰的涼亭，只見縷縷山嵐飄過眼前，讓人有置身仙境之感。"]],"總共":[["ㄗㄨㄥˇ ㄍㄨㄥˋ","總括、全部。[例]這套書總共有十二本。"]],"總和":[["ㄗㄨㄥˇ ㄏㄜˊ","所有數量的相加。[例]這個月的支出總和超過一萬元。"]],"總是":[["ㄗㄨㄥˇ ㄕˋ","1.一直都是。[例]他做事總是慢吞吞的。\n2.畢竟、終究。[例]再怎麼說，她總是你妹妹，你要多讓她一點。"]],"總裁":[["ㄗㄨㄥˇ ㄘㄞˊ","某些政黨首領的名稱。銀行或財團亦設總裁。[例]總公司明年度將升他為臺灣地區的總裁。"]],"總計":[["ㄗㄨㄥˇ ㄐㄧˋ","統括計算。[例]這次大會，各界代表總計有一萬餘人出席。"]],"績效":[["ㄐㄧ ㄒㄧㄠˋ","工作的成績、效果。[例]績效顯著、績效不彰"]],"繁多":[["ㄈㄢˊ ㄉㄨㄛ","多種多樣。[例]這家服飾店的衣服樣式新穎，花色繁多。"]],"繁榮":[["ㄈㄢˊ ㄖㄨㄥˊ","興盛發達。[例]由於財經策略運用成功，臺灣經濟日益繁榮。"]],"繁殖":[["ㄈㄢˊ ㄓˊ","繁衍生殖。[例]海鳥多在無人的小島或偏遠的海邊繁殖後代。"]],"繁瑣":[["ㄈㄢˊ ㄙㄨㄛˇ","繁雜瑣碎。[例]這些東西很繁瑣，我們得逐一清查。"]],"繁茂":[["ㄈㄢˊ ㄇㄠˋ","繁密茂盛。[例]這個園子花木繁茂，景致怡人。"]],"繁華":[["ㄈㄢˊ ㄏㄨㄚˊ","1.形容城鎮、街市等富麗而熱鬧的樣子。[例]臺北這個繁華的都市，讓剛從鄉下來的人處處感覺新奇。\n2.形容生活富裕、地位顯赫。[例]自從離開官場，他的生活便由繁華歸於平淡。"]],"織布":[["ㄓ ㄅㄨˋ","以絲、麻、棉、毛等線編製成布匹。[例]古代的婦女大多工於織布。"]],"繚繞":[["ㄌㄧㄠˊ ㄖㄠˋ","環繞、盤旋。[例]雲煙繚繞、歌聲繚繞"]],"繞口令":[["ㄖㄠˋ ㄎㄡˇ ㄌㄧㄥˋ","一種語言遊戲。將漢語中聲母、韻母、聲調容易混同的文字交錯編成句子，使人唸起來有些拗口，說快了則容易發生錯誤。[例]母親曾教我一首繞口令：飛機飛，灰雞灰，飛機飛來灰雞飛。"]],"繞境":[["ㄖㄠˋ ㄐㄧㄥˋ","在一定的區域繞轉行動。多指信眾迎請神像，巡視境內，以淨化驅邪、保祐平安的宗教活動。[例]農曆三月臺灣各地都會舉辦媽祖繞境活動。 △遶境"]],"繞道":[["ㄖㄠˋ ㄉㄠˋ","不走直接的路而改行較迂迴的路。[例]前方修路，請車輛繞道行駛。"]],"繡球":[["ㄒㄧㄡˋ ㄑㄧㄡˊ","用絲綢結成的球狀物。[例]同樂會上，同學們表演了古代富家千金拋繡球招親的戲碼。"]],"繩子":[["ㄕㄥˊ ˙ㄗ","繩索。用兩股以上的麻、絲、草或尼龍絲、金屬絲等絞揉成的長條物。[例]貨車上路前，應把貨物用繩子捆綁固定好。"]],"繩索":[["ㄕㄥˊ ㄙㄨㄛˇ","繩子。[例]碼頭上那些粗大的繩索是用來繫船的船纜。"]],"繪畫":[["ㄏㄨㄟˋ ㄏㄨㄚˋ","一種造型藝術。用筆、刀等工具，及各種顏料，在紙、木板、紡織物或牆壁等的平面上，透過構圖、造型和色彩等表現手法，創造視覺上的形象。依使用材料、技術的不同，可分為壁畫、油畫、版畫、素描等；就題材內容的不同，可分為人物畫、風景畫等。[例]從畫家個展上不難發現作者獨特的繪畫風格。"]],"繪聲繪影":[["ㄏㄨㄟˋ ㄕㄥ ㄏㄨㄟˋ ㄧㄥˇ","形容講述或描摹事物十分細緻入微、生動逼真。[例]這故事經他講述，繪聲繪影，讓聽眾彷彿身歷其境。"]],"繫念":[["ㄒㄧˋ ㄋㄧㄢˋ","掛念。[例]她雖在臺北工作，卻常繫念著家鄉的父母。"]],"繼位":[["ㄐㄧˋ ㄨㄟˋ","繼承王位。[例]漢武帝駕崩後，由昭帝繼位。"]],"繼承":[["ㄐㄧˋ ㄔㄥˊ","1.承繼先人的財產或事業。[例]在父親遽逝之後，他決定回國繼承家業。\n2.法律上指承繼家族相傳的世系、宗嗣與財產。[例]王先生於日前病故留下一大筆遺產，分別由其妻子與兩個兒子共同繼承該筆遺產。"]],"繼續":[["ㄐㄧˋ ㄒㄩˋ","連續而不間斷。[例]暫時領先而能繼續努力的人，才是最後的勝利者。"]],"繽紛":[["ㄅㄧㄣ ㄈㄣ","雜亂而繁盛的樣子。[例]五彩繽紛、落英繽紛"]],"纏繞":[["ㄔㄢˊ ㄖㄠˋ","圍繞束縛。[例]葡萄藤纏繞著竹架逐漸向上攀生。"]],"纏身":[["ㄔㄢˊ ㄕㄣ","纏繞於身，引申有束縛之意。[例]他因為經商失敗而導致債務纏身，生活陷入絕境。"]],"纖纖":[["ㄒㄧㄢ ㄒㄧㄢ","形容細長。[例]纖纖玉手"]],"缺少":[["ㄑㄩㄝ ㄕㄠˇ","短少、欠缺。[例]空氣、水、陽光是生物不可缺少的生存要素。"]],"缺席":[["ㄑㄩㄝ ㄒㄧˊ","該出席而沒到。[例]這次會議因缺席人數過多而流會了。"]],"缺憾":[["ㄑㄩㄝ ㄏㄢˋ","不完美，有令人感到遺憾的地方。[例]人生中的某些缺憾，有時正可激勵人奮發向上，反倒是一件好事呢！"]],"缺陷":[["ㄑㄩㄝ ㄒㄧㄢˋ","缺點、不完善的地方。[例]這幅畫的缺陷在於色彩不夠協調。"]],"罐子":[["ㄍㄨㄢˋ ˙ㄗ","用來裝盛物品的筒狀容器。[例]他總是把媽媽給他的零錢藏在罐子裡。"]],"羊毛":[["ㄧㄤˊ ㄇㄠˊ","羊身上的毛。其纖維呈鱗片狀，具彈性，所製成的衣料保暖性特強且不易皺。[例]美麗諾羊毛、安哥拉羊毛"]],"羊羹":[["ㄧㄤˊ ㄍㄥ","一種用豆沙、麵粉及糖等材料做成的甜食。[例]媽媽準備了親手做的紅豆羊羹，來款待賓客。"]],"美不勝收":[["ㄇㄟˇ ㄅㄨˋ ㄕㄥ ㄕㄡ","形容美好的事物非常多，無法一一收入眼底。[例]這次活動的展覽品，琳琅滿目，美不勝收。"]],"美妙":[["ㄇㄟˇ ㄇㄧㄠˋ","美好巧妙。[例]她有一副美妙的歌喉。"]],"美景":[["ㄇㄟˇ ㄐㄧㄥˇ","1.美好的景色、景象。[例]他以相機捕捉剎那即逝的日出美景。\n2.借指美好的景況。[例]他年輕有為，未來是一片燦爛美景。"]],"美酒":[["ㄇㄟˇ ㄐㄧㄡˇ","醇酒、好酒；泛指一切味道甘醇的酒。[例]法國香檳區以出產葡萄美酒聞名於世。"]],"美食":[["ㄇㄟˇ ㄕˊ","美味的食物。[例]美食當前，不禁令人食指大動。"]],"美麗":[["ㄇㄟˇ ㄌㄧˋ","漂亮、美好；使人看了心生喜悅的。[例]多數人對未來總是充滿著美麗的憧憬。"]],"羞恥":[["ㄒㄧㄡ ㄔˇ","羞愧恥辱。[例]他因自己教子無方而感到十分羞恥。"]],"羞愧":[["ㄒㄧㄡ ㄎㄨㄟˋ","羞恥慚愧。[例]他為自己不禮貌的行為感到羞愧萬分。"]],"羞慚":[["ㄒㄧㄡ ㄘㄢˊ","面含羞而心生慚愧。[例]小華當眾被人指責，滿面羞慚，無言以對。"]],"羞辱":[["ㄒㄧㄡ ㄖㄨˋ","1.恥辱。[例]他在大庭廣眾下被人責罵，因而感到十分羞辱。\n2.侮辱，使受難堪。[例]他當眾羞辱她，讓她下不了臺。"]],"群眾":[["ㄑㄩㄣˊ ㄓㄨㄥˋ","人民大眾。[例]國家的各項公共工程建設都是結合了群眾的金錢、力量才得以完成。"]],"群體":[["ㄑㄩㄣˊ ㄊㄧˇ","由許多同種類或具有共同本質的個體聚集而成的團體。[例]球隊是一個群體，不容許少數分子破壞其中的和諧。"]],"羨慕":[["ㄒㄧㄢˋ ㄇㄨˋ","心中因愛慕而嚮往。[例]由於他辛苦的努力和奮鬥，才有今天令人羨慕的成就。"]],"義不容辭":[["ㄧˋ ㄅㄨˋ ㄖㄨㄥˊ ㄘˊ","道義上不容許推卻。[例]他一向熱心公益，對於義演，當然是義不容辭。"]],"義氣":[["ㄧˋ ㄑㄧˋ","彰顯道義的氣概。[例]他素重義氣，絕不可能出賣朋友。"]],"義賣":[["ㄧˋ ㄇㄞˋ","為了籌措公益費用而舉辦的售物活動。[例]此次義賣所得，將全部捐為賑災之用。"]],"羽毛":[["ㄩˇ ㄇㄠˊ","1.泛指禽鳥身上的毛。具有飛翔、維持體溫、保護身體等作用。[例]孔雀的羽毛色彩豔麗，十分漂亮。\n2.比喻人的聲望或形象。[例]愛惜羽毛"]],"羽翼":[["ㄩˇ ㄧˋ","1.禽鳥的翅膀。[例]當幼鳥的羽翼長成之後，它們就會自己飛行覓食。\n2.盜賊的同黨。[例]警方擴大偵察，將那幫盜賊的羽翼一網打盡。\n3.輔佐之人。[例]備勇而志大，關羽、張飛為之羽翼。（《三國志．卷二十五．魏志．董昭傳》）"]],"翅膀":[["ㄔˋ ㄅㄤˇ","鳥類及昆蟲的翼。[例]企鵝的翅膀雖然無法飛行，但在水中卻有划水的功能。"]],"習俗":[["ㄒㄧˊ ㄙㄨˊ","某地區內的人們長期養成的習慣、風俗。[例]每個民族都有它特有的習俗。"]],"習慣":[["ㄒㄧˊ ㄍㄨㄢˋ","1.逐漸適應。[例]她住在都市裡多年，早已習慣繁忙的生活步調。\n2.長期養成，一時不容易改變的行為模式或地方風尚。[例]飯前洗手，飯後漱口，是一種良好的習慣。"]],"翠綠":[["ㄘㄨㄟˋ ㄌㄩˋ","如翡翠般的青綠色。[例]徜徉在翠綠的山林間，是人生的一大快事。"]],"翡翠":[["ㄈㄟˇ ㄘㄨㄟˋ","1.硬玉中含鉻而呈翠綠色者。主要成分為鈉鋁矽酸鹽，屬單斜晶系，光澤如脂，半透明，可作珍貴的飾品。[例]她有一條珍貴的翡翠項鍊，是丈夫送她的生日禮物。　△翠玉\n2.動物名。鳥綱佛法僧目翠鳥科。為一種獨棲性的水鳥。體形圓胖，尾羽和腳皆短。身上有美麗如翡翠的羽毛，顏色、形狀因種類不同而各有差異。嘴巴粗尖，擅長捕魚、昆蟲等。[例]翡翠這種鳥習慣築巢於樹洞中。"]],"翩翩":[["ㄆㄧㄢ ㄆㄧㄢ","1.形容動作輕盈。[例]蝴蝶在花叢裡翩翩起舞。\n2.形容文采風流、舉止灑脫的樣子。[例]風度翩翩、翩翩公子"]],"翱翔":[["ㄠˊ ㄒㄧㄤˊ","在空中自由自在盤旋高飛。[例]老鷹在空中獨自翱翔，既孤傲又神氣。"]],"翹楚":[["ㄑㄧㄠˊ ㄔㄨˇ","本指荊樹叢中最高拔的樹。比喻特出的人才。語本《詩經．周南．漢廣》。[例]個中翹楚"]],"翹首":[["ㄑㄧㄠˊ ㄕㄡˇ","抬頭。[例]翹首盼望"]],"翻唱":[["ㄈㄢ ㄔㄤˋ","將外國語文的歌曲曲調旋律重新填上本國語文的歌詞來演唱，或重新演唱其他歌星所唱過的歌曲。[例]早期有許多流行歌曲都是從西洋歌曲翻唱過來，因此洋味十足。"]],"翻山越嶺":[["ㄈㄢ ㄕㄢ ㄩㄝˋ ㄌㄧㄥˇ","形容長途跋涉、旅途辛苦。[例]登山隊在翻山越嶺、長途跋涉之後，終於攀登上主峰的山頂。"]],"翻譯":[["ㄈㄢ ㄧˋ","1.將某種語言文字用另外一種語言文字表達出來。[例]在大型國際會議裡，常有同步翻譯的服務。_x000D_\n2.從事翻譯工作的人。[例]請將這封德文信交給翻譯翻成中文。_x000D_\n3.把代表語言文字的符號或數碼用語言文字表達出來。[例]翻譯電報、翻譯密碼_x000D_"]],"翻閱":[["ㄈㄢ ㄩㄝˋ","翻看文件或書籍。[例]閒來無事，便順手拿起一本畫報隨意翻閱。"]],"耀武揚威":[["ㄧㄠˋ ㄨˇ ㄧㄤˊ ㄨㄟ","炫耀武力，誇示威風。形容得意誇張、瞧不起人的樣子。[例]小張仗著家中財勢在此耀武揚威，令人十分厭惡。"]],"耀眼":[["ㄧㄠˋ ㄧㄢˇ","1.光線強烈，使人目眩。[例]耀眼的陽光照射在金黃色的稻穗上，預示了豐收的喜悅。\n2.突出、顯耀。[例]由於不斷努力，他終於成為演藝界裡耀眼的巨星。"]],"老大":[["ㄌㄠˇ ㄉㄚˋ","1.稱兄弟姊妹間排行第一的人。[例]我們家老大出生時重達4000公克。\n2.江湖幫會或團體中尊稱首領。[例]黑社會老大、工商界老大\n3.年紀大。[例]少壯不努力，老大徒傷悲。《樂府詩集．卷三十．相和歌辭五．古辭．長歌行》\n4.很大、非常大。[例]他的臉上有著老大一塊胎記。"]],"老天爺":[["ㄌㄠˇ ㄊㄧㄢ ㄧㄝˊ","1.天上可以主宰人命運的神明。[例]希望老天爺保佑我早日尋回失蹤的女兒。\n2.表示驚嘆時的用語。[例]老天爺！這真是太神奇了！"]],"老套":[["ㄌㄠˇ ㄊㄠˋ","舊有的方法、技倆等。[例]做廣告需要開發新點子，不可一味承襲老套。"]],"老師":[["ㄌㄠˇ ㄕ","對傳授學問或技藝者的尊稱。[例]對於老師的諄諄教誨，同學們應謹記在心。"]],"老翁":[["ㄌㄠˇ ㄨㄥ","老年男子。[例]廟旁的榕樹下，常有老翁聚在一起喝茶小酌，閒聊年輕往事。"]],"老虎":[["ㄌㄠˇ ㄏㄨˇ","→虎1."]],"老闆":[["ㄌㄠˇ ㄅㄢˇ","舊稱商店主人。今泛指工商企業、公司行號的產權所有人。[例]那個老闆正怒聲斥責著做錯事的伙計。　△老板"]],"老鷹":[["ㄌㄠˇ ㄧㄥ","動物名。鷲鷹目鷲鷹科。全身呈褐色，尾形像魚尾，翼大擅飛翔，嘴呈鉤曲狀，眼睛非常銳利，趾有銳利的爪，嘴腳皆強勁有力。捕食魚類、青蛙、鳥類等。通常會將巢穴築於峭壁上或高大的樹上。[例]老鷹會啄食動物的腐屍，是自然界的清道夫。　△鳶"]],"老鼠":[["ㄌㄠˇ ㄕㄨˇ","→鼠"]],"考卷":[["ㄎㄠˇ ㄐㄩㄢˋ","考試所用的卷子。[例]他雖然把整張考卷都寫滿了，但由於答非所問，成績仍然不及格。"]],"考場":[["ㄎㄠˇ ㄔㄤˇ","考試的場所。[例]為因應急救工作的需要，聯招會在各個考場都設置了臨時救護站。"]],"考核":[["ㄎㄠˇ ㄏㄜˊ","考查審核。[例]本產品經衛生單位考核獲評為優良食品，消費者可安心食用。"]],"考試":[["ㄎㄠˇ ㄕˋ","出試題測驗考生學習程度或能力。[例]入學考試、術科考試"]],"考量":[["ㄎㄠˇ ㄌㄧㄤˊ","考慮衡量。[例]此事宜多加考量，不可貿然行動。"]],"考題":[["ㄎㄠˇ ㄊㄧˊ","用來測試的題目。[例]這次月考考題頗為艱深，要取得高分恐怕不太容易。"]],"而且":[["ㄦˊ ㄑㄧㄝˇ","表示平列或更進一層。[例]自獲獎後他便一舉成名，而且還享譽國際。"]],"耍賴":[["ㄕㄨㄚˇ ㄌㄞˋ","賴皮不認帳或蠻橫不講理。[例]事實擺在眼前，你別再耍賴了。"]],"耐勞":[["ㄋㄞˋ ㄌㄠˊ","能忍受勞累。[例]因為他能刻苦耐勞，努力向上，才有今日的成就。"]],"耐心":[["ㄋㄞˋ ㄒㄧㄣ","心情平和而不厭煩、急躁。[例]王老師非常有耐心的解決學生們的問題。"]],"耐用":[["ㄋㄞˋ ㄩㄥˋ","物品可以經久使用。[例]這把刷子的材質很好，十分耐用。"]],"耕田":[["ㄍㄥ ㄊㄧㄢˊ","泛指耕種田地的一切活動。[例]雖然烈日當空，農夫仍然不辭辛苦的在田裡耕田。　◎"]],"耕耘":[["ㄍㄥ ㄩㄣˊ","1.耕田與除草。泛指農田耕作的事情。[例]一番辛苦耕耘後，眼見麥浪層層，真令人高興。\n2.比喻付出精神和勞力。[例]一分耕耘，一分收穫。"]],"耗盡":[["ㄏㄠˋ ㄐㄧㄣˋ","消耗殆盡。[例]他們為了醫治因車禍而癱瘓的兒子，幾已耗盡家產。"]],"耗竭":[["ㄏㄠˋ ㄐㄧㄝˊ","消耗淨盡。[例]他在登山途中遇到惡劣的天候而迷路，最後因體力耗竭而罹難。"]],"耗費":[["ㄏㄠˋ ㄈㄟˋ","消耗浪費。[例]耗費時日、耗費金錢"]],"耳垢":[["ㄦˇ ㄍㄡˋ","外耳道皮脂腺的分泌物所形成的黃色蠟狀垢屑。[例]清除耳垢時要小心，以免弄破耳膜或引起發炎。　△耳蠟、耳脂、耳屎"]],"耳朵":[["ㄦˇ ㄉㄨㄛˇ","人與脊椎動物的耳，俗稱為「耳朵」。[例]蝙蝠能在黑夜中飛行自如，全靠牠最為靈敏的耳朵。　◎"]],"耳目一新":[["ㄦˇ ㄇㄨˋ ㄧ ㄒㄧㄣ","所見所聞和過去完全不同而有一種新奇、清新的感覺。[例]主講人風趣、豐富的演講內容，令全場聽眾耳目一新。"]],"耳膜":[["ㄦˇ ㄇㄛˊ","→鼓膜"]],"耳蝸":[["ㄦˇ ㄍㄨㄚ","內耳中的螺旋形骨管。頂小底大，形似蝸牛外殼，因而得名。管內含有感音裝置，是聽覺的主要部分。　◎"]],"耶誕節":[["ㄧㄝˊ ㄉㄢˋ ㄐㄧㄝˊ","西洋節日之一。為紀念耶穌基督降生的節日。耶穌誕辰，自古傳說不一，西元四世紀時，羅馬人始定十二月二十五日為耶穌誕辰，是歐美重要節慶之一。[例]耶誕節不僅是西方的重要節日，在臺灣也形成一股熱鬧的節慶氣氛。"]],"聆聽":[["ㄌㄧㄥˊ ㄊㄧㄥ","注意聽。[例]她那優美的歌聲吸引了不少人前往聆聽。"]],"聆訊":[["ㄌㄧㄥˊ ㄒㄩㄣˋ","聆聽訊息。[例]法院開庭審理時，警方傳令當事人出庭聆訊。"]],"聆賞":[["ㄌㄧㄥˊ ㄕㄤˇ","聆聽、欣賞。[例]他最大的嗜好，就是在家中靜靜的聆賞音樂。"]],"聊天":[["ㄌㄧㄠˊ ㄊㄧㄢ","閒談。[例]晚飯後，我們全家人常聚在客廳聊天，分享生活趣事。"]],"聒噪":[["ㄍㄨㄚ ㄗㄠˋ","吵鬧不休。[例]每到黃昏，對面林中的小鳥就會聒噪地叫著。 △呱噪"]],"聚集":[["ㄐㄩˋ ㄐㄧˊ","圍聚、集合。[例]廣場上聚集了許多歌迷，前來欣賞這場演唱會。"]],"聞見":[["ㄨㄣˊ ㄐㄧㄢˋ","嗅到氣味。[例]聞見一股焦味兒後，他連忙將瓦斯爐的火關掉。"]],"聯絡":[["ㄌㄧㄢˊ ㄌㄨㄛˋ","連繫。[例]畢業後，班上同學仍常以電話彼此聯絡，維持友誼。"]],"聯絡簿":[["ㄌㄧㄢˊ ㄌㄨㄛˋ ㄅㄨˋ","學校用來提供家長相關的課業訊息，並交換意見、保持聯絡的簿子。[例]爸爸從聯絡簿上獲知弟弟在校表現良好，決定送一套課外讀物給弟弟作為獎勵。"]],"聯繫":[["ㄌㄧㄢˊ ㄒㄧˋ","聯絡維繫。[例]家長應與學校保持聯繫，以了解學生在校的學習情形。"]],"聰敏":[["ㄘㄨㄥ ㄇㄧㄣˇ","聰明、靈敏。[例]那位學生非常聰敏，數學只教一次就能完全了解，並懂得靈活運用。"]],"聰明":[["ㄘㄨㄥ ㄇㄧㄥˊ","1.眼力和耳力敏捷。[例]那位老婆婆雖然年紀很大了，但仍耳目聰明，行動靈活，非常健康。\n2.天資靈敏，理解力強。[例]小華很聰明，但是不夠用功。"]],"聰穎":[["ㄘㄨㄥ ㄧㄥˇ","非常聰明。[例]她既聰穎又用功，難怪成績如此出色。"]],"聲響":[["ㄕㄥ ㄒㄧㄤˇ","聲音。[例]遠處的爆炸傳來巨大的聲響。"]],"職務":[["ㄓˊ ㄨˋ","在職位上所必須擔負的工作及責任。[例]他在雜誌社的職務是校稿。"]],"職掌":[["ㄓˊ ㄓㄤˇ","1.負責掌管。[例]她是班上的總務，職掌班上所有的財務。\n2.職務。[例]他身為社區管理員，維護社區內的安全是他的本分職掌。"]],"職業":[["ㄓˊ ㄧㄝˋ","個人所從事的職務或工作。[例]她的職業是老師，教育英才已有十年的時間了。"]],"職稱":[["ㄓˊ ㄔㄥ","職務名稱。[例]他在公司裡的職稱為副理。"]],"職責":[["ㄓˊ ㄗㄜˊ","職務與責任。[例]維護社會治安是警察的職責。"]],"聽任":[["ㄊㄧㄥˋ ㄖㄣˋ","任憑去做，而不加以約束。[例]只要事情能如期完成，老闆總是聽任我們照自己的意思去做。"]],"聽其自然":[["ㄊㄧㄥˋ ㄑㄧˊ ㄗˋ ㄖㄢˊ","任由人、事、物自然發展，而不加以過問及干涉。[例]這件事既然已經無力挽回，就只有聽其自然！"]],"聽天由命":[["ㄊㄧㄥˋ ㄊㄧㄢ ㄧㄡˊ ㄇㄧㄥˋ","任憑天意及命運自然發展。[例]能做的，都已經做了，咱們就聽天由命吧！"]],"聽筒":[["ㄊㄧㄥ ㄊㄨㄥˇ","1.電話機的受話機。[例]因為忘了把聽筒掛好，所以電話一直打不進來。\n2.→聽診器"]],"聽聞":[["ㄊㄧㄥ ㄨㄣˊ","1.耳聞。[例]他的善心善行，大家早已有所聽聞。\n2.所聽到的事情。[例]駭人聽聞、聳人聽聞"]],"聽話":[["ㄊㄧㄥ ㄏㄨㄚˋ","順從。[例]為人子女的應該好好聽話，不要時常頂撞父母。"]],"聽說":[["ㄊㄧㄥ ㄕㄨㄛ","聽他人所說。[例]這座城門，聽說是清代所遺留下來的古蹟。"]],"聾啞":[["ㄌㄨㄥˊ ㄧㄚˇ","聽覺和說話均有障礙。[例]對於聾啞的孩子，我們必須付出更多的愛心和耐心。"]],"肅清":[["ㄙㄨˋ ㄑㄧㄥ","削平或清除亂紀的人或事物，以整飭綱紀。[例]警方為維護治安，特別成立了肅清流氓的專案行動。"]],"肅立":[["ㄙㄨˋ ㄌㄧˋ","恭敬的站立。[例]唱國歌時，大家應肅立。"]],"肆無忌憚":[["ㄙˋ ㄨˊ ㄐㄧˋ ㄉㄢˋ","任意妄為，毫無顧忌。[例]他仗著是老板的親戚，就如此肆無忌憚，真是令人厭惡。"]],"肉桂":[["ㄖㄡˋ ㄍㄨㄟˋ","植物名。樟科樟屬，常綠喬木。葉長橢圓形，具三條葉脈。夏開淡黃色小花，結紫黑色果。樹皮多脂，氣味辛烈，與種子、根皮、嫩枝等均可作成香料，或磨碎製成桂油，可入藥，具有止痛、健胃、驅寒等療效。[例]肉桂的皮可用作菜餚的調味品。　△木桂、桂樹、菌桂"]],"肌膚":[["ㄐㄧ ㄈㄨ","肌肉與皮膚。[例]她的肌膚光滑柔嫩，看起來很年輕。"]],"肚子":[["ㄉㄨˇ ˙ㄗ","料理食物時稱動物的胃為「肚子」。[例]羊肚子、牛肚子　△肚兒"],["ㄉㄨˋ ˙ㄗ","1.腹部的通稱。[例]他因為吃了不乾淨的東西，現在肚子正疼著呢！\n2.物體中圓而凸起像肚子的部分。[例]這隻酒瓶有個胖胖的肚子，看起來特別可愛。"]],"肚皮":[["ㄉㄨˋ ㄆㄧˊ","1.肚子。[例]我早上起得太晚，來不及吃早餐，只好餓肚皮了。\n2.腹腔最外層的表皮部分。[例]人心隔肚皮"]],"肚臍":[["ㄉㄨˋ ㄑㄧˊ","肚子中間的臍帶脫落處。[例]胎兒的肚臍藉由臍帶與母體的胎盤相連。　△肚臍眼　◎"]],"肝膽相照":[["ㄍㄢ ㄉㄢˇ ㄒㄧㄤ ㄓㄠˋ","比喻赤誠相處。[例]他們兩人一同在戰場上出生入死，是肝膽相照的好友。"]],"股東":[["ㄍㄨˇ ㄉㄨㄥ","出資經營公司，並持有公司股份的人。[例]王先生持有公司40％的股份，可算是本公司的大股東。"]],"股票":[["ㄍㄨˇ ㄆㄧㄠˋ","股份公司發給投資人，用來表示股份並有權取得股息的有價證券。[例]合法的股票交易才能保障投資人的權益。"]],"肢體":[["ㄓ ㄊㄧˇ","身體四肢。[例]他雖然肢體稍有殘缺，但毅力卻比一般人還要堅定。"]],"肥胖":[["ㄈㄟˊ ㄆㄤˋ","因體內脂肪積存過多，以致造成形體粗大的現象。[例]持續的運動，可以避免體型肥胖。"]],"肩膀":[["ㄐㄧㄢ ㄅㄤˇ","頸部下兩臂與身體連接的部分。[例]他肩膀上背著一個袋子，看起來好像很沉重的樣子。　◎"]],"肯定":[["ㄎㄣˇ ㄉㄧㄥˋ","1.承認事物的價值。[例]他的貢獻已受到大家的肯定。\n2.表示同意、贊成。[例]他問我同不同意這個提議，我的回答是肯定的。\n3.明白、確定。[例]從書上的字跡來看，我肯定這本書是他的。"]],"肺炎":[["ㄈㄟˋ ㄧㄢˊ","肺臟發炎的病症。會出現發燒、發冷、咳嗽、咯痰、胸疼及呼吸困難等症狀，常由細菌、病毒等引起。[例]他因患重感冒延遲就醫而引發肺炎。"]],"肺腑":[["ㄈㄟˋ ㄈㄨˇ","借指內心深處。[例]這些話都是出自肺腑，絕無虛言。"]],"肺臟":[["ㄈㄟˋ ㄗㄤˋ","→肺"]],"胃口":[["ㄨㄟˋ ㄎㄡˇ","1.食欲。[例]他的病剛痊癒，所以胃口不是很好。\n2.比喻對某種事物的興趣。[例]這部電影不合我的胃口。"]],"背叛":[["ㄅㄟˋ ㄆㄢˋ","違背、反叛。[例]你怎麼可以背叛我？太令我失望了！"]],"背心":[["ㄅㄟˋ ㄒㄧㄣ","一種蔽護胸背的無袖上衣，可分兩種：一種是貼身的汗衫，一種是配合其他衣物，套穿於外面。　◎◎"]],"背棄":[["ㄅㄟˋ ㄑㄧˋ","違背離棄。[例]在患難中，不可背棄同伴，要攜手共度難關。"]],"背誦":[["ㄅㄟˋ ㄙㄨㄥˋ","熟記文句後能不看文句就能誦讀。[例]老師要同學背誦這篇文章。"]],"背負":[["ㄅㄟ ㄈㄨˋ","1.以背馱負物品。[例]他背負著沉重的行囊，走在路上。\n2.負荷、擔負。[例]我們都背負著傳承固有文化的重責大任。"]],"背部":[["ㄅㄟˋ ㄅㄨˋ","胸部的後面，從後腰以上到頸下的部位。[例]坐、立姿勢不正確會引發背部疼痛。"]],"背面":[["ㄅㄟˋ ㄇㄧㄢˋ","背後、反面。[例]他在那張卡片的背面寫上祝福語。"]],"胎記":[["ㄊㄞ ㄐㄧˋ","出生時即存在於皮膚上的深色印記。[例]他手臂上有一塊橢圓形的胎記，相當醒目。"]],"胡扯":[["ㄏㄨˊ ㄔㄜˇ","瞎說、胡說。[例]他喜歡胡扯，因此常得罪別人。"]],"胡說":[["ㄏㄨˊ ㄕㄨㄛ","毫無根據的亂說話。[例]事關國家機密，不許胡說。"]],"胡說八道":[["ㄏㄨˊ ㄕㄨㄛ ㄅㄚ ㄉㄠˋ","沒有根據的亂說。[例]看他說話時毫無誠意，大概也只是胡說八道吧！"]],"胡鬧":[["ㄏㄨˊ ㄋㄠˋ","無理取鬧。[例]他明知我在忙，還要我陪他去玩，簡直是胡鬧嘛！"]],"胸圍":[["ㄒㄩㄥ ㄨㄟˊ","圍繞胸部位置一圈所量得的尺寸。"]],"胸膛":[["ㄒㄩㄥ ㄊㄤˊ","胸部。[例]挺起胸膛"]],"能力":[["ㄋㄥˊ ㄌㄧˋ","1.本領、才幹。[例]他的辦事能力很強。\n2.合乎法律規定，可以行使權利、履行義務的資格。[例]行為能力"]],"能夠":[["ㄋㄥˊ ㄍㄡˋ","可以、足夠。[例]今天能夠做完的事，不要拖到明天。"]],"能幹":[["ㄋㄥˊ ㄍㄢˋ","才能傑出，辦事能力強。[例]林小姐非常能幹，交給她辦的事，大多能順利解決。"]],"能耐":[["ㄋㄥˊ ㄋㄞˋ","本領、耐力。[例]憑著愈挫愈勇的能耐，最後他終於成功了。"]],"能量":[["ㄋㄥˊ ㄌㄧㄤˋ","1.物體或力場所具有的作功能力。_x000D_\n2.比喻人所能發揮的能力和作用。[例]生命能量、研究能量"]],"脂粉":[["ㄓ ㄈㄣˇ","化妝用的胭脂與香粉。舊時借指婦女。[例]不施脂粉、脂粉氣"]],"脆弱":[["ㄘㄨㄟˋ ㄖㄨㄛˋ","1.不堅固的。[例]屋內梁木年久失修相當脆弱，地震時務必加倍小心。\n2.禁不起打擊的。[例]再堅強的人，也有情感脆弱的一面。"]],"脈搏":[["ㄇㄞˋ ㄅㄛˊ","心臟收縮時，輸出的血液衝擊動脈壁所引起的搏動。"]],"脈絡":[["ㄇㄞˋ ㄌㄨㄛˋ","1.血管的統稱。[例]筋骨脈絡遍布全身。\n2.條理、系統。[例]脈絡分明"]],"脖子":[["ㄅㄛˊ ˙ㄗ","頭與身體接連的部位。[例]昨晚睡覺時不小心扭到脖子了。　△脖　◎"]],"脫口而出":[["ㄊㄨㄛ ㄎㄡˇ ㄦˊ ㄔㄨ","不加思索，隨口說出。[例]許多不當的言論，都是因為脫口而出所造成的。"]],"脫穎而出":[["ㄊㄨㄛ ㄧㄥˇ ㄦˊ ㄔㄨ","顯露才能，超越眾人。[例]他在這次測驗中脫穎而出，名列前茅。"]],"脫落":[["ㄊㄨㄛ ㄌㄨㄛˋ","1.掉落。指從附著的物體上掉下來。[例]毛髮脫落\n2.遺落。[例]字句脫落"]],"脫逃":[["ㄊㄨㄛ ㄊㄠˊ","脫離逃走。[例]臨陣脫逃"]],"脫險":[["ㄊㄨㄛ ㄒㄧㄢˇ","脫離險境。[例]醫生說他的病況穩定，已經脫險了。"]],"脾氣":[["ㄆㄧˊ ㄑㄧˋ","1.人的性情、習性。[例]他的脾氣暴躁，不太容易相處。\n2.怒氣。[例]精心收藏的古董花瓶被孩子打破了，他發了一頓脾氣。"]],"脾臟":[["ㄆㄧˊ ㄗㄤˋ","→脾"]],"腐爛":[["ㄈㄨˇ ㄌㄢˋ","腐壞潰爛。[例]這些水果一直壓在箱底，早就腐爛發霉了。"]],"腐臭":[["ㄈㄨˇ ㄔㄡˋ","腐爛而發出臭味。[例]肉品若不放在冰箱冷凍，容易變壞腐臭。"]],"腐蝕":[["ㄈㄨˇ ㄕˊ","1.物體因酸類、鹼類或鹽類的化學作用，而逐漸毀損、消失。[例]這根鋼條已經生鏽腐蝕，不堪使用。\n2.思想或行為逐漸被惡習汙染而變質。[例]投機風氣猖獗，足以腐蝕人心，降低工作意願。"]],"腕力":[["ㄨㄢˋ ㄌㄧˋ","手腕的力量。[例]羽球運動需要強勁的腕力才能擊出快速的殺球。"]],"腕骨":[["ㄨㄢˋ ㄍㄨˇ","手骨的一部分，在下臂骨及掌骨之間。　◎"]],"腥臊味":[["ㄒㄧㄥ ㄙㄠ ㄨㄟˋ","魚肉所發出刺鼻難聞的臭味。[例]由於停電過久，冰箱裡的魚、肉都發出一股腥臊味。"]],"腦海":[["ㄋㄠˇ ㄏㄞˇ","腦中。[例]回到故鄉，童年往事又清晰的浮現腦海。"]],"腦袋":[["ㄋㄠˇ ㄉㄞˋ","1.頭部。[例]古時伴君如伴虎，稍有疏失就得擔心腦袋會搬家。　△腦袋瓜\n2.記憶、想像、理解、思考等能力。[例]他的腦袋似乎不太靈光，要不然怎會連這點小事都記不住呢？　△腦袋瓜"]],"腦袋瓜":[["ㄋㄠˇ ㄉㄞˋ ㄍㄨㄚ","1.頭部。[例]他走路不小心跌倒，腦袋瓜受了點傷。　△腦袋\n2.記憶、想像、思考等能力。[例]他一整天都在發呆，腦袋瓜不知道在想些什麼。　△腦袋"]],"腦部":[["ㄋㄠˇ ㄅㄨˋ","中樞神經系統的主要部分。位於顱腔內。可分為大腦、中腦、小腦、橋腦、延腦、間腦。[例]人類腦部的每一部位，都有負責控制身體特定功能的職責。"]],"腫瘤":[["ㄓㄨㄥˇ ㄌㄧㄡˊ","因體內某一部分組織細胞長期不正常增殖所形成的疾病。依腫瘤細胞的構造和對人體危害性的大小，可分為良性腫瘤和惡性腫瘤兩種。[例]她不幸罹患甲狀腺腫瘤，現正接受化學治療。　△瘤子"]],"腫脹":[["ㄓㄨㄥˇ ㄓㄤˋ","肌肉或皮膚等組織因發炎、充血或瘀血而使體積變大的現象。[例]扭傷的腳有些腫脹，最好還是給醫生檢查一下。"]],"腮幫子":[["ㄙㄞ ㄅㄤ ˙ㄗ","臉頰。[例]她生氣時總是鼓著腮幫子。"]],"腰圍":[["ㄧㄠ ㄨㄟˊ","圍繞腰部位置一圈所量得的尺寸。"]],"腳趾":[["ㄐㄧㄠˇ ㄓˇ","腳上的趾頭。[例]她因為走了太多路，腳趾上都起了水泡。　◎"]],"腳跟":[["ㄐㄧㄠˇ ㄍㄣ","腳掌的後部。[例]他的腳跟在一次籃球比賽中受到嚴重的挫傷，至今尚未復原。　◎"]],"腳踏車":[["ㄐㄧㄠˇ ㄊㄚˋ ㄔㄜ","一種利用雙腳踩踏板前進的兩輪車。[例]清晨在鄉間的馬路上，可見到許多學生騎腳踏車上學。　△單車、自行車、自由車　◎"]],"腳踝":[["ㄐㄧㄠˇ ㄏㄨㄞˊ","小腿與腳掌間，腳骨兩旁凸起的部位。[例]他因車禍跌傷了腳踝，現在只能拄著枴杖走路。　△腿腕子　◎"]],"腸胃":[["ㄔㄤˊ ㄨㄟˋ","腸和胃。[例]腸胃不好的人，需要特別注意飲食。"]],"腹痛":[["ㄈㄨˋ ㄊㄨㄥˋ","腹部因消化道發炎、胃痙攣及其他器官的疾病所引起的疼痛。[例]他因腹痛而無法工作，只得請假到醫院求診。"]],"腹背受敵":[["ㄈㄨˋ ㄅㄟˋ ㄕㄡˋ ㄉㄧˊ","前後都受到敵人的攻擊。[例]前有埋伏，後有追兵，我方腹背受敵，情勢非常緊急。"]],"腹部":[["ㄈㄨˋ ㄅㄨˋ","動物胸部和骨盤間的部分。由腰椎及肌肉壁構成，內有胃、大腸、小腸、肝、脾及腎等器官。[例]他突然腹部劇痛，家人急忙將他送醫求治。"]],"腿法":[["ㄊㄨㄟˇ ㄈㄚˇ","武術中以腿攻擊對方的技法。[例]注意他攻擊時的腿法，找出弱點來，才能進一步尋求致勝之道。"]],"膀胱":[["ㄆㄤˊ ㄍㄨㄤ","泌尿系統中儲尿的器官。為肌肉與膜質形成的囊，呈卵圓形，位於骨盤腔的前方，腹腔的下方。[例]婦女懷孕後，子宮會壓迫到膀胱，發生頻尿的現象。　△尿胞 　◎◎"]],"膜拜":[["ㄇㄛˊ ㄅㄞˋ","跪伏地上，虔誠敬拜。[例]頂禮膜拜"]],"膽小":[["ㄉㄢˇ ㄒㄧㄠˇ","缺乏勇氣。[例]膽小如鼠"]],"膽怯":[["ㄉㄢˇ ㄑㄩㄝˋ","膽小軟弱。[例]他個性內向，一遇到陌生人就膽怯。"]],"膽敢":[["ㄉㄢˇ ㄍㄢˇ","無所忌憚。[例]那竊賊竟膽敢在光天化日下行竊，真是目無王法了！"]],"膾炙人口":[["ㄎㄨㄞˋ ㄓˋ ㄖㄣˊ ㄎㄡˇ","膾，細切的肉。炙，烤肉。膾、炙都是受人喜好的食物，後以膾炙人口比喻美好的事物受人讚賞。[例]這本小說在五〇年代是一本膾炙人口的書。"]],"臂彎":[["ㄅㄧˋ ㄨㄢ","臂膀彎曲處。[例]小貓慵懶的躺在她的臂彎裡，睡得正香甜呢！"]],"臂章":[["ㄅㄧˋ ㄓㄤ","佩帶在袖子上臂部分，以表示身分、職務的標誌。常見於軍、警、機關、學校等單位的人員。[例]警察人員的臂章上繡的是一隻鴿子，象徵和平。"]],"臂膀":[["ㄅㄧˋ ㄅㄤˇ","胳膊。[例]他是個舉重健將，擁有結實的臂膀。"]],"臉型":[["ㄌㄧㄢˇ ㄒㄧㄥˊ","臉的型態。[例]她的臉型屬於娃娃臉，所以看起來比實際的年齡還年輕。"]],"臉盆":[["ㄌㄧㄢˇ ㄆㄣˊ","洗臉時盛水用的盆子。[例]當過兵的人絕對忘不了「早晨起，床鋪動，拿著臉盆往外衝」的日子。"]],"臉紅":[["ㄌㄧㄢˇ ㄏㄨㄥˊ","受人或事物的刺激而臉色發紅。[例]他一說謊就會臉紅，根本騙不了人。"]],"臉色":[["ㄌㄧㄢˇ ㄙㄜˋ","1.臉上的神情。[例]她還在生氣，到現在都沒給我好臉色看。\n2.氣色。[例]她聽到友人遇難的消息後，臉色蒼白，一時無法接受這個事實。"]],"臉蛋":[["ㄌㄧㄢˇ ㄉㄢˋ","臉頰部分。泛指臉。[例]這位歌星臉蛋迷人，成為歌迷的偶像。"]],"臉部":[["ㄌㄧㄢˇ ㄅㄨˋ","面部。[例]她在劇中雖然扮演啞巴，但生動的臉部表情卻傳神的表達出內在情感。"]],"臉頰":[["ㄌㄧㄢˇ ㄐㄧㄚˊ","臉的兩邊。[例]她一提起傷心的往事，兩行熱淚頓時沿著臉頰流下來。"]],"臉龐":[["ㄌㄧㄢˇ ㄆㄤˊ","面容、臉蛋。[例]我永遠忘不了他領獎時，臉龐上所呈現的驕傲神情。"]],"臍帶":[["ㄑㄧˊ ㄉㄞˋ","連接胎兒與胎盤的帶狀構造，內含臍動脈與臍靜脈。胎兒藉此從母體吸取養分並排出廢物。[例]胎兒出生約一週後，臍帶會自行脫落。"]],"臘肉":[["ㄌㄚˋ ㄖㄡˋ","以鹽或醬醃漬，然後晒乾、風乾或燻乾的肉。[例]在古代農業社會裡，醃製臘肉是年節的一件大事。"]],"臘腸":[["ㄌㄚˋ ㄔㄤˊ","將豬肉泥加上鹽、糖、醬油、五香粉等調味料攪和，再灌入豬腸中，然後風乾而成的食品。[例]寒冬是調製臘腸的最佳時機。"]],"臥室":[["ㄨㄛˋ ㄕˋ","供人睡覺的房間。[例]將臥室的牆壁漆上柔和的顏色，有助於入睡。"]],"臥房":[["ㄨㄛˋ ㄈㄤˊ","供人睡覺的房間。[例]他身體不適，在臥房裡休息。"]],"自個兒":[["ㄗˋ ㄍㄜˇㄦ","自己、己身。[例]一個人必須有責任感，自個兒做的事自個兒負責。"]],"自傳":[["ㄗˋ ㄓㄨㄢˋ","敘述自己生平事蹟的作品。[例]這本自傳的重點是描述作者早年在國外的經歷。"]],"自嘲":[["ㄗˋ ㄔㄠˊ","以言辭嘲笑自己。[例]韓愈〈進學解〉這篇文章有不少自嘲的言辭。"]],"自己":[["ㄗˋ ㄐㄧˇ","本身。[例]他常自己一個人在房裡聽音樂。"]],"自得":[["ㄗˋ ㄉㄜˊ","1.自己感覺得意或舒適。[例]只要談起兒子一手創辦的連鎖企業，他臉上就露出自得的神情。\n2.自己有所領悟、體會。[例]君子無入而不自得。（《禮記．中庸》）"]],"自從":[["ㄗˋ ㄘㄨㄥˊ","從、由。表示時間的起點。[例]自從上次慘遭車禍之後，他再也不敢開快車了。"]],"自怨自艾":[["ㄗˋ ㄩㄢˋ ㄗˋ ㄧˋ","原指悔恨自己所犯的錯誤而加以改正。今則指自我悔恨、責備。[例]問題既然發生了，就應該力謀解決之道；一味自怨自艾是無濟於事的。"]],"自我":[["ㄗˋ ㄨㄛˇ","1.個人自己。[例]自我檢討、自我約束\n2.以自己為中心的觀念。[例]做任何事都得想到別人，不能太自我。"]],"自投羅網":[["ㄗˋ ㄊㄡˊ ㄌㄨㄛˊ ㄨㄤˇ","比喻落入圈套或自取災禍。[例]警方設好圈套，等待凶手自投羅網。"]],"自甘墮落":[["ㄗˋ ㄍㄢ ㄉㄨㄛˋ ㄌㄨㄛˋ","甘願自暴自棄，不求上進。[例]他若再執迷不悟、自甘墮落下去，終會自食惡果。"]],"自由":[["ㄗˋ ㄧㄡˊ","1.依照自己的意志行事，不受外力拘束或限制。[例]自由是幸福的基礎，不自由，即無快樂與幸福可言。\n2.法律上指在法律範圍內的活動，不受別人干涉的權利。[例]言論自由、出版自由"]],"自由自在":[["ㄗˋ ㄧㄡˊ ㄗˋ ㄗㄞˋ","不受任何拘束，隨心所欲，安詳悠閒。[例]這陣子閒來無事，每天看書聽音樂，過得自由自在。"]],"自私自利":[["ㄗˋ ㄙ ㄗˋ ㄌㄧˋ","只圖自己的私利，而不顧及一切。[例]自私自利的人交不到真心朋友。"]],"自給自足":[["ㄗˋ ㄐㄧˇ ㄗˋ ㄗㄨˊ","生產和消費維持平衡，可以獨立營生，不必仰賴他人。[例]農業社會裡，大多數的農家都可以自給自足。"]],"自言自語":[["ㄗˋ ㄧㄢˊ ㄗˋ ㄩˇ","自己對自己說話。[例]只見他高興得手舞足蹈，自言自語，不知有什麼奇思妙想？"]],"自豪":[["ㄗˋ ㄏㄠˊ","為自己感到光榮、驕傲。[例]他對自己的廚藝頗為自豪。"]],"自願":[["ㄗˋ ㄩㄢˋ","自己願意。[例]她自願利用假日到孤兒院為孩子們輔導課業。"]],"臭氣沖天":[["ㄔㄡˋ ㄑㄧˋ ㄔㄨㄥ ㄊㄧㄢ","形容惡臭瀰漫。[例]這地方的垃圾已經一個禮拜未清理了，臭氣沖天，令人作嘔。"]],"臭美":[["ㄔㄡˋ ㄇㄟˇ","譏笑人自誇。[例]你少臭美了，儘往自己臉上貼金。"]],"至今":[["ㄓˋ ㄐㄧㄣ","直到現在。[例]本校創辦至今，已有四十幾年歷史。"]],"至少":[["ㄓˋ ㄕㄠˇ","最少，表示最低的限度。[例]這個遊戲至少需要四個人才能玩。"]],"致使":[["ㄓˋ ㄕˇ","以致。[例]因為延遲送醫，致使他的病情更加惡化。"]],"致函":[["ㄓˋ ㄏㄢˊ","寄發信件。[例]學校將致函每位學生家長，邀請他們參加家長會。"]],"致勝":[["ㄓˋ ㄕㄥˋ","獲得勝利。[例]充分發揮團隊精神，是我隊致勝的主要原因。"]],"致命":[["ㄓˋ ㄇㄧㄥˋ","使喪失生命。[例]這種藥物毒性極強，服食微量，即足以致命，千萬別讓兒童觸及。"]],"致富":[["ㄓˋ ㄈㄨˋ","獲得財富，變得富有。[例]做人要腳踏實地，不要妄想一夜致富。"]],"致意":[["ㄓˋ ㄧˋ","表達思慕、問候、感謝等情意。[例]大樓裡的住戶平常很少往來，見了面頂多點頭致意。"]],"致敬":[["ㄓˋ ㄐㄧㄥˋ","向人敬禮或表示敬意。[例]每位參觀者都向國父銅像行禮致敬。"]],"致歉":[["ㄓˋ ㄑㄧㄢˋ","向人表示歉意。[例]我為昨日的魯莽行為致歉，請您原諒。"]],"致贈":[["ㄓˋ ㄗㄥˋ","贈送、贈與。[例]總統到前線巡視，並致贈加菜金慰勞三軍將士。"]],"臺柱":[["ㄊㄞˊ ㄓㄨˋ","1.支撐戲臺的主要柱子。[例]工作人員搭好臺柱後，馬上著手內部的擺設。\n2.借指戲班中重要的演員或團體中的重要幹部。[例]他是公司的臺柱，這麼一走，公司的業績恐怕會大受影響。"]],"臺灣":[["ㄊㄞˊ ㄨㄢ","1.指臺灣本島，簡稱「臺」。地理位置於亞洲東南部，東濱太平洋，北臨東海，東北與琉球群島隔海相望，南隔巴士海峽與菲律賓相望，西以臺灣海峽與大陸地區福建省相望。\n2.泛指臺灣地區。包括臺灣本島、澎湖群島、金門、馬祖及我國政府統治權所及之其他地區。\n3.臺灣省政府功能業務與組織調整前的簡稱。民國八十七年行政院據憲法增修條文第九條，進行臺灣省政府功能業務與組織調整，將其所轄機關分階段併入中央政府，僅留部分單位維持運作。"]],"舅媽":[["ㄐㄧㄡˋ ㄇㄚ","稱謂。稱母親兄弟的妻子。[例]每次回外婆家，舅媽總是極力款待我們。　△舅母　◎"]],"與人為善":[["ㄩˇ ㄖㄣˊ ㄨㄟˊ ㄕㄢˋ","幫助別人做好事。[例]她處事向來與人為善，因此人緣極好。"]],"與會":[["ㄩˋ ㄏㄨㄟˋ","參加聚會或會議。[例]今晚與會的人士來自各行各業，盛況空前。"]],"與生俱來":[["ㄩˇ ㄕㄥ ㄐㄩˋ ㄌㄞˊ","一生下來就具備的。[例]孟子認為惻隱之心是人類與生俱來的善性。"]],"與眾不同":[["ㄩˇ ㄓㄨㄥˋ ㄅㄨˋ ㄊㄨㄥˊ","獨樹一幟，和一般人不同。[例]他喜歡標新立異，連穿著也與眾不同。"]],"興味盎然":[["ㄒㄧㄥˋ ㄨㄟˋ ㄤˋ ㄖㄢˊ","興趣很高昂的樣子。[例]他興味盎然的看著地上的螞蟻，把自己想像成其中的一員。"]],"興奮":[["ㄒㄧㄥ ㄈㄣˋ","形容精神振奮或情緒激動。[例]一聽到暑假要舉行環島畢業旅行，全班同學都非常興奮。"]],"興建":[["ㄒㄧㄥ ㄐㄧㄢˋ","營建、創建。[例]他準備在市中心投資興建一座摩天大樓。"]],"興旺":[["ㄒㄧㄥ ㄨㄤˋ","繁榮旺盛。[例]這個家族四代同堂，人丁興旺。"]],"興盛":[["ㄒㄧㄥ ㄕㄥˋ","昌隆蓬勃。[例]國民生活水準日益提高，各種休閒旅遊事業也越來越興盛了。"]],"興致":[["ㄒㄧㄥˋ ㄓˋ","高昂愉悅的情致。[例]他今天喝酒的興致不錯，接二連三的找人乾杯。"]],"興辦":[["ㄒㄧㄥ ㄅㄢˋ","創設。[例]這家醫院是由幾位醫師共同興辦的。"]],"興隆":[["ㄒㄧㄥ ㄌㄨㄥˊ","昌盛。[例]他做買賣一向誠實公道，所以生意興隆。"]],"興高采烈":[["ㄒㄧㄥˋ ㄍㄠ ㄘㄞˇ ㄌㄧㄝˋ","形容興致勃勃，情緒熱烈的樣子。語本南朝梁．劉勰《文心雕龍．體性》。[例]同學們正興高采烈的討論著畢業旅行的事。"]],"舉例":[["ㄐㄩˇ ㄌㄧˋ","提出例證。[例]老師在課堂中除了教授理論之外，經常會舉例幫助學生理解。"]],"舉動":[["ㄐㄩˇ ㄉㄨㄥˋ","行為或動作。[例]觀眾席中有人鼓譟，這突如其來的脫序舉動，讓所有歌迷一陣錯愕。"]],"舉手":[["ㄐㄩˇ ㄕㄡˇ","抬高手臂。[例]會議中，大家紛紛舉手發言，表示意見，討論空前熱烈。"]],"舉棋不定":[["ㄐㄩˇ ㄑㄧˊ ㄅㄨˋ ㄉㄧㄥˋ","本指拿著棋子，不能決定下一步怎麼走。比喻猶豫不決，拿不定主意。語出《左傳．襄公二十五年》。[例]他是個優柔寡斷的人，做什麼事都猶豫不決、舉棋不定。"]],"舉辦":[["ㄐㄩˇ ㄅㄢˋ","推動、興辦。[例]本校在這學期一共舉辦了三次教學觀摩會。"]],"舉重":[["ㄐㄩˇ ㄓㄨㄥˋ","一種體育運動。運動員以抓舉、挺舉兩種方式舉起槓鈴，然後以舉起的重量和姿勢是否符合標準判定勝負。[例]舉重冠軍選手經多年練習，肌肉的瞬間爆發力比一般人強。　◎"]],"舊書攤":[["ㄐㄧㄡˋ ㄕㄨ ㄊㄢ","買賣過期的書報雜誌的店鋪或攤子。[例]他閒來無事時喜歡逛逛舊書攤挖寶貝。"]],"舌戰":[["ㄕㄜˊ ㄓㄢˋ","比喻激烈的辯論。[例]辯論雙方實力相當，預料將有一場精彩的舌戰。"]],"舌苔":[["ㄕㄜˊ ㄊㄞ","長在舌面上的滑膩物質。中醫師用來診斷病情。　△舌胎"]],"舌頭":[["ㄕㄜˊ ˙ㄊㄡ","動物口腔中具有攝食、分辨滋味及協助發音、咀嚼功能的器官。[例]這幾天氣溫升高，小狗熱得伸出舌頭。"]],"舒坦":[["ㄕㄨ ㄊㄢˇ","舒暢平和。[例]聽了他的解釋後，內心舒坦多了。"]],"舒暢":[["ㄕㄨ ㄔㄤˋ","舒適暢快。[例]身心舒暢"]],"舒服":[["ㄕㄨ ㄈㄨˊ","身心感到輕鬆愉快。[例]她昨天感冒，身體不舒服。"]],"舒爽":[["ㄕㄨ ㄕㄨㄤˇ","舒服愉快。[例]洗完澡後擦上痱子粉，感覺非常舒爽。"]],"舒適":[["ㄕㄨ ㄕˋ","舒服安適。[例]父母辛苦的工作，是為了使我們的生活更舒適。"]],"舔拭":[["ㄊㄧㄢˇ ㄕˋ","用舌頭揩擦。[例]小狗不斷的舔拭牠的盤子，好像還沒吃飽的樣子。"]],"舞姿":[["ㄨˇ ㄗ","跳舞時的姿態。[例]舞姿曼妙"]],"舞文弄墨":[["ㄨˇ ㄨㄣˊ ㄋㄨㄥˋ ㄇㄛˋ","墨，繩墨、法度。舞文弄墨原指玩弄法條作弊，敗壞法紀。後比喻賣弄筆墨文辭。語本《隋書．卷八十五．王充傳》。[例]這篇作品不僅舞文弄墨，而且冗贅蕪雜，實在乏善可陳。"]],"舞者":[["ㄨˇ ㄓㄜˇ","跳舞的人。[例]只見會場中，歌聲曼妙，舞者婆娑。"]],"舞蹈":[["ㄨˇ ㄉㄠˋ","一種藝術形式。為人體配合音樂或節奏所作的各種姿態，藉著有韻律的動作，表達內心的思想情感，並滿足人類的精神需求。[例]舞蹈是一種表現美感的藝術。"]],"航行":[["ㄏㄤˊ ㄒㄧㄥˊ","船舶或飛機的行進。[例]我們已經在海上航行兩天了，明晚就可以到達目的地。"]],"航道":[["ㄏㄤˊ ㄉㄠˋ","供飛機、船隻行駛的通道。[例]在密集的港口水域，必須劃分航道，以避免船舶互相碰撞。"]],"船票":[["ㄔㄨㄢˊ ㄆㄧㄠˋ","乘船的憑證。[例]春節期間，由高雄開往澎湖的船票將自本月起開始預售。"]],"船艙":[["ㄔㄨㄢˊ ㄘㄤ","船內部可容納人員或貨物的地方。[例]甲板上風大，許多乘客都改到船艙中休息閒談。"]],"船長":[["ㄔㄨㄢˊ ㄓㄤˇ","總理全船事務的人。[例]他從小就夢想能當一名船長，到世界各地航行旅遊。"]],"船隻":[["ㄔㄨㄢˊ ㄓ","船。[例]颱風來襲，出海的船隻紛紛進港避風。"]],"良好":[["ㄌㄧㄤˊ ㄏㄠˇ","很好、極好。[例]由於醫護人員細心的照顧，他手術後復原情況良好。"]],"良言":[["ㄌㄧㄤˊ ㄧㄢˊ","善言，正面有益的話。[例]金玉良言"]],"艱辛":[["ㄐㄧㄢ ㄒㄧㄣ","困難辛苦。[例]備嚐各種艱辛，她終於獨力把孩子撫養長大。"]],"艱鉅":[["ㄐㄧㄢ ㄐㄩˋ","困難繁重。[例]這項艱鉅的工作並非一人之力可以單獨完成的。　△艱巨"]],"色彩":[["ㄙㄜˋ ㄘㄞˇ","1.物體表面所呈現的顏色。[例]這件衣服的色彩非常鮮豔。\n2.思想、行動的傾向或事物的格調。[例]這篇小說富有很濃厚的地方色彩。"]],"艾草":[["ㄞˋ ㄘㄠˇ","→艾"]],"芋泥":[["ㄩˋ ㄋㄧˊ","把芋頭去皮後磨成糊狀，加入糖、豬油等蒸熟而成的食品。[例]這道八寶芋泥甜而不膩，一上桌不久便被大家吃光了。"]],"芒果":[["ㄇㄤˊ ㄍㄨㄛˇ","植物名。漆樹科檬果屬，常綠大喬木。葉呈螺旋排列，開黃色花。果實亦稱為「芒果」，可供食用。[例]夏天是芒果盛產的季節。　△檬果　◎"]],"芝麻":[["ㄓ ㄇㄚˊ","植物名。胡麻科胡麻屬，一年生草本。莖方形。葉長，對生或互生，呈橢圓形或卵形。花單生於葉腋，表面有毛，向側方下垂，呈白色或雜有淡紅色。果實為長橢圓形的蒴角，熟後縱裂。種子小而扁平，有白色及黑色等數種，可供食用或榨油。大多分布於熱帶地區。[例]多食用芝麻，據說可使頭髮變得更加烏黑亮麗。　△胡麻、油麻"]],"芥蒂":[["ㄐㄧㄝˋ ㄉㄧˋ","微小的梗塞物。比喻心裡不舒服或與人有嫌隙。[例]經過老師的調解，他們之間的芥蒂已經消除。"]],"芬芳":[["ㄈㄣ ㄈㄤ","1.香氣。[例]百花競吐芬芳。\n2.形容事物美好。[例]他的人格高尚，德性芬芳，足以為人楷模。"]],"芭樂":[["ㄅㄚ ㄌㄜˋ","番石榴的別名。[例]芭樂汁"]],"芭蕉":[["ㄅㄚ ㄐㄧㄠ","植物名。芭蕉科芭蕉屬，多年生草本。產於亞熱帶地區。葉大，長橢圓形。夏日開淡黃色花。果實亦稱為「芭蕉」，肉質肥大，氣味香甜，與熱帶所產的香蕉形似。[例]芭蕉樣子長得像香蕉，但嚐起來味道更為香甜。　△巴蕉、天芭、甘蕉"]],"芭蕉扇":[["ㄅㄚ ㄐㄧㄠ ㄕㄢˋ","1.指芭蕉葉做成的扇子。也指用蒲葵製成的扇子，因形似芭蕉葉而得名。[例]小販在創意市集的攤位上，展示傳統手工編製的芭蕉扇。_x000D_\n2.《西遊記》中鐵扇公主所用的扇子，相傳可以搧滅烈火。"]],"芭蕾舞":[["ㄅㄚ ㄌㄟˇ ㄨˇ","歐洲古典舞劇的統稱。起源於十五世紀義大利宮廷，為一種典雅且帶戲劇性的舞蹈。強調足尖舞蹈技巧，並以動作表現多種感情。§英ballet[例]今晚國家劇院演出古典芭蕾舞，節目十分精彩。"]],"花圃":[["ㄏㄨㄚ ㄆㄨˇ","種植花草的園圃。[例]每到春天，花圃裡總是百卉爭妍，蝶亂蜂喧。"]],"花園":[["ㄏㄨㄚ ㄩㄢˊ","種有花木的園圃。[例]經過一夜的狂風驟雨，花園裡花朵落了滿地。"]],"花團錦簇":[["ㄏㄨㄚ ㄊㄨㄢˊ ㄐㄧㄣˇ ㄘㄨˋ","形容五彩繽紛、繁華美麗的樣子。[例]今年元宵的花燈展，真是花團錦簇，美不勝收。"]],"花朵":[["ㄏㄨㄚ ㄉㄨㄛˇ","花。[例]公園裡盛開的花朵吸引了大批的遊客。"]],"花瓣":[["ㄏㄨㄚ ㄅㄢˋ","構成花冠的各片。其構造與葉子相似，但細胞中含有各種不同的色素，故有不同的顏色。[例]某些花的花瓣形狀奇特，可以吸引昆蟲前來採蜜傳粉。　◎"]],"花盆":[["ㄏㄨㄚ ㄆㄣˊ","種花的盆子。[例]那個花盆裡種的是玫瑰。　◎"]],"花籃":[["ㄏㄨㄚ ㄌㄢˊ","裝有鮮花或假花的籃子。通常用作表示祝賀的禮物，也用在祭奠。[例]他送了一對花籃給小劉，祝賀他新店開張，大發利市。"]],"花絮":[["ㄏㄨㄚ ㄒㄩˋ","1.某些植物種子上的白色絨毛，可隨風飛散。[例]到了春天，柳樹的花絮隨風飛舞。_x000D_\n2.比喻各種吸引人的零碎新聞。如報紙上的選舉花絮、職棒花絮等。[例]電視臺有時會播出電視劇的幕後花絮，博君一笑。"]],"花苞":[["ㄏㄨㄚ ㄅㄠ","花梗頂端的鱗狀變態葉片，為花的雛型。[例]這株玫瑰已經長出花苞，再過不久就要開放了。　◎"]],"花茶":[["ㄏㄨㄚ ㄔㄚˊ","1.用茉莉、桂花等香花薰製的茶葉。如茉莉花茶、桂花茶等。[例]我喜歡在滿室花茶的茶香中，享受寧靜的下午。　△香片\n2.用晒乾的花所沖泡的茶。如菊花茶。"]],"花蜜":[["ㄏㄨㄚ ㄇㄧˋ","花中分泌的汁液。[例]蝴蝶吸取花蜜為食。"]],"花費":[["ㄏㄨㄚ ㄈㄟˋ","1.消費、耗用。[例]這幅畫是我花費了一番心血，好不容易才完成的作品。\n\t\n2.所消費的錢財。[例]這次旅遊的花費，遠超過我們的預算。"]],"花轎":[["ㄏㄨㄚ ㄐㄧㄠˋ","舊時結婚時新娘所乘坐的轎子。[例]這次的民俗表演中有抬花轎迎娶新娘的項目。"]],"芳名":[["ㄈㄤ ㄇㄧㄥˊ","1.美好的聲譽。[例]芳名遠播\n2.敬稱女性的姓名。[例]請問芳名"]],"苛求":[["ㄎㄜ ㄑㄧㄡˊ","嚴苛而不合理的要求。[例]待人處世應合情合理，不宜太過苛求。"]],"若使":[["ㄖㄨㄛˋ ㄕˇ","倘使、假使。[例]張先生幫小兒補習，若使小兒能考上大學，必定重重酬謝。"]],"苦悶":[["ㄎㄨˇ ㄇㄣˋ","苦惱煩鬱。[例]工作一直沒有突破進展，令他苦悶不已。"]],"苦惱":[["ㄎㄨˇ ㄋㄠˇ","憂愁煩惱。[例]事情並不如你想像中的糟，何必自尋苦惱？"]],"苦澀":[["ㄎㄨˇ ㄙㄜˋ","1.味道又苦又澀。[例]這帖中藥味道苦澀，令人難以下嚥。\n2.形容內心非常痛苦。[例]面對失敗的挫折，她的心中充滿苦澀的滋味。"]],"苦練":[["ㄎㄨˇ ㄌㄧㄢˋ","極力、艱苦的練習。[例]經過一番苦練，他終於說得一口流利的英語。"]],"苦苦哀求":[["ㄎㄨˇ ㄎㄨˇ ㄞ ㄑㄧㄡˊ","再三懇求。[例]禁不住妹妹苦苦哀求，終於徵得爸爸同意，讓她暑假出國遊學。"]],"苦衷":[["ㄎㄨˇ ㄓㄨㄥ","難以啟齒的隱情。[例]他之所以會這麼做，實在有不得已的苦衷。"]],"英文":[["ㄧㄥ ㄨㄣˊ","英國的語言和文字。[例]我們從國中就開始學習英文了。"]],"英雄":[["ㄧㄥ ㄒㄩㄥˊ","才能超群出眾的人。[例]一個真正的英雄不是在逞一時之氣，而是要有理想、有目標。"]],"茁壯":[["ㄓㄨㄛˊ ㄓㄨㄤˋ","成長壯大。[例]今年暑訓班的大專青年，個個都身體茁壯。"]],"茂密":[["ㄇㄠˋ ㄇㄧˋ","旺盛濃密。[例]一進入了山區，迎面而來的就是一片茂密的竹林。"]],"茂盛":[["ㄇㄠˋ ㄕㄥˋ","茂密繁盛。[例]這棵樹枝葉茂盛，結實纍纍。"]],"茅屋":[["ㄇㄠˊ ㄨ","用茅草搭建的房屋。[例]傳統農家社會，茅屋是常見的建物。"]],"茫然":[["ㄇㄤˊ ㄖㄢˊ","1.不知所措的樣子。[例]突然得知這個惡耗，他的腦海中頓時一片茫然，不知如何處理。\n2.悵惘若有所失的樣子。[例]當他知道自己鑄成大錯，頓時茫然自失。"]],"茫茫":[["ㄇㄤˊ ㄇㄤˊ","1.廣大無邊的樣子。[例]茫茫大海、人海茫茫\n2.不明、無法了解的樣子。[例]前途茫茫\n3.目視不明的樣子。[例]他雖然已經視茫茫，髮蒼蒼，卻仍然懷著一顆赤子之心。"]],"茶匙":[["ㄔㄚˊ ㄔˊ","量詞。計算茶匙容裝物的單位。[例]一茶匙鹽、三茶匙醬油"]],"茶園":[["ㄔㄚˊ ㄩㄢˊ","種植茶樹的田園。[例]放眼望去，山坡上一片綠油油的茶園，令人心曠神怡！"]],"茹毛飲血":[["ㄖㄨˊ ㄇㄠˊ ㄧㄣˇ ㄒㄧㄝˇ","指上古或未開化人尚不知用火，連毛帶血生吃獵物。形容上古人類尚不知用火的生活情形。語本《禮記．禮運》。[例]相傳燧人氏教民鑽木取火，結束了原始人類茹毛飲血的生活。"]],"草創":[["ㄘㄠˇ ㄔㄨㄤˋ","剛開始創立、創設。[例]公司正值草創，一切開銷尤須精打細算。"]],"草率":[["ㄘㄠˇ ㄕㄨㄞˋ","做事隨便，不仔細。[例]帳目要一清二楚的列出，不可草率。"]],"草皮":[["ㄘㄠˇ ㄆㄧˊ","帶著微量泥土，可鋪設成草坪的草。[例]保護綠地，請勿踐踏草皮！"]],"草莓":[["ㄘㄠˇ ㄇㄟˊ","植物名。薔薇科草莓屬，多年生草本。全株被絨毛，葉根生叢出，有長柄，著生三片邊緣有缺刻的小葉。花白色，綴成疏聚繖（ㄙㄢˇ）花序。果實亦稱為「草莓」，肉質多汁，味道酸甜。　◎"]],"荊棘":[["ㄐㄧㄥ ㄐㄧˊ","1.叢生而多刺的灌木。[例]登山隊用柴刀劈開擋住去路的荊棘之後，才繼續前進。\n2.比喻困難、險境。[例]即使人生的旅途布滿了荊棘，我們也要勇敢的走下去。"]],"荒涼":[["ㄏㄨㄤ ㄌㄧㄤˊ","荒蕪而冷清的樣子。[例]這個原本非常繁榮的都城，在經過戰火的摧殘之後，已呈現出一片荒涼的景象。"]],"荒漠":[["ㄏㄨㄤ ㄇㄛˋ","1.荒涼而廣闊。[例]非洲地區至今仍有許多荒漠的原野，保持著自然的原貌。\n2.泛指雨量稀少、氣候乾燥、土質貧瘠、溫度變化劇烈、人口密度極低的地區。按地表組成可分為沙漠、岩漠、礫漠等，大都分布於內陸或低緯度地區。一般僅可生長根深葉小或無葉植物，生存其間的動物則具有穴居、夏眠等特性。[例]荒漠占地球陸地面積三分之一以上，而且有逐年擴大之勢。"]],"荒誕":[["ㄏㄨㄤ ㄉㄢˋ","荒唐虛妄。[例]荒誕不經"]],"荷槍實彈":[["ㄏㄜˋ ㄑㄧㄤ ㄕˊ ㄉㄢˋ","持著子彈已上膛的槍。形容高度警戒，準備隨時戰鬥的狀況。[例]為營救被歹徒挾持的人質，警方荷槍實彈，準備伺機攻堅。"]],"荷花":[["ㄏㄜˊ ㄏㄨㄚ","荷所開的花。花型大，有淡紅、淡紫、黃、白等色，單瓣、重瓣皆有。[例]每年七、八月，池塘裡的荷花便吐露著芳香。　◎"]],"荷鋤":[["ㄏㄜˋ ㄔㄨˊ","肩負鋤頭。[例]夕陽西沉，田裡的農夫們牽著水牛，荷鋤回家。"]],"莊稼":[["ㄓㄨㄤ ㄐㄧㄚˋ","農作物的總稱。[例]今年風調雨順，田裡的莊稼收成很好。"]],"莊重":[["ㄓㄨㄤ ㄓㄨㄥˋ","端莊穩重，不輕浮。[例]這場宴會的主持人儀態莊重，溫文儒雅。"]],"莫非":[["ㄇㄛˋ ㄈㄟ","難道。表示揣測或反問。[例]這件事情莫非是你所策劃的？否則你怎麼這麼清楚。"]],"菊壇":[["ㄐㄩˊ ㄊㄢˊ","指戲劇界。名稱起源於唐朝的菊部，為歌舞樂班，皇宮內有宴會時負責表演。[例]今天的國劇公演將集菊壇菁英一同演出。"]],"菊花":[["ㄐㄩˊ ㄏㄨㄚ","菊所開的花。多年生宿根性草花，生頭狀花序，花冠有舌狀、筒狀、絲狀等，品種極多，花色豐富，有紅、黃、白、紫等。[例]菊花晒乾後能製成茶飲，清涼解熱，很受歡迎。　△黃花、九花、日精、延齡客　◎"]],"菜刀":[["ㄘㄞˋ ㄉㄠ","廚房裡專門用來切肉、菜等的刀。[例]那把新買的菜刀，非常鋒利好用。"]],"菜色":[["ㄘㄞˋ ㄙㄜˋ","1.菜餚的式樣。[例]這家餐廳的菜色繁多，任君選擇。\n2.因飢餓而營養不良的臉色。[例]他是剛從災區逃出來的難胞，難怪面有菜色。"]],"菜販":[["ㄘㄞˋ ㄈㄢˋ","販賣蔬菜的人。[例]這位菜販平日生活儉樸，但行善助人總是不落人後。"]],"菠菜":[["ㄅㄛ ㄘㄞˋ","植物名。藜科，二年生草本。根部紅色，葉嫩綠，略呈三角形，有甜味，含有豐富的鐵質，可供作蔬菜食用。[例]炒菠菜時，若能打個蛋，則翠綠中帶銀白，色香味俱全。　△菠稜菜、飛龍菜　◎"]],"菩薩":[["ㄆㄨˊ ㄙㄚˋ","1.佛教上稱證得佛果而普渡眾生的人。僅次於佛而高於羅漢。如文殊菩薩、觀世音菩薩。\n2.泛指神、佛。[例]祈求菩薩保佑全家平安。\n3.稱心懷慈悲、樂善好施的人。[例]他的善行廣被四方，真是位活菩薩。"]],"華麗":[["ㄏㄨㄚˊ ㄌㄧˋ","豪華美麗。[例]他衣飾華麗，大概是有錢人家的子弟。"]],"萬一":[["ㄨㄢˋ ㄧ","1.萬分之一。[例]再多的錢財也無法報答父母恩情於萬一。_x000D_\n2.表示可能性極小。[例]唯恐睡過了頭，我準備了三個鬧鐘以防萬一。_x000D_\n3.表示假設可能性極小的連結詞。[例]安全門若被雜物堵住，萬一發生火災可就慘了！"]],"萬念俱灰":[["ㄨㄢˋ ㄋㄧㄢˋ ㄐㄩˋ ㄏㄨㄟ","所有的念頭、打算都化成了灰。比喻非常失意消極。[例]突遭家破人亡的變故，使他一時萬念俱灰，失去對生命的熱望。"]],"落下":[["ㄌㄠˋ ㄒㄧㄚˋ","剩下、留下。[例]他一生無惡不做，死後只落下一片罵名。"],["ㄌㄨㄛˋ ㄒㄧㄚˋ","降落、掉落。[例]豆大的雨滴自天空紛紛落下，路上的行人不禁加快了腳步。"]],"落伍":[["ㄌㄨㄛˋ ㄨˇ","比喻事物、思想行動跟不上時代潮流。[例]積極進取是避免落伍的不二法門。"]],"落後":[["ㄌㄨㄛˋ ㄏㄡˋ","居他人之後，水準較低。[例]他因身體狀況不佳，常常請假，以致功課進度落後很多。"]],"落腳":[["ㄌㄨㄛˋ ㄐㄧㄠˇ","停留、休息或暫住。[例]今晚我們就先在這家旅館落腳，明天天一亮再繼續趕路。"]],"葉子":[["ㄧㄝˋ ˙ㄗ","植物的葉的通稱。[例]在中國大陸北方，許多植物一到秋天，葉子便開始凋落。"]],"葉片":[["ㄧㄝˋ ㄆㄧㄢˋ","1.葉的扁平部分，有葉肉和葉脈，是植物進行光合作用的主要部分。[例]入秋後，楓樹的葉片漸漸轉紅，美麗極了。\n2.有輪軸的機械中，形狀像葉子的零件。[例]電風扇藉著葉片的轉動使空氣流通而產生風。"]],"葉脈":[["ㄧㄝˋ ㄇㄞˋ","分布於植物葉片上的維管束系統，有主脈、支脈、細脈之別，為強韌纖維所組成。有支持葉片及輸送水分、養料的功能。"]],"葉落歸根":[["ㄧㄝˋ ㄌㄨㄛˋ ㄍㄨㄟ ㄍㄣ","比喻久居異鄉之人不忘本源，終究要返回家鄉。[例]他旅居海外多年，雖已功成名就，但他心中最企盼的還是葉落歸根。"]],"著名":[["ㄓㄨˋ ㄇㄧㄥˊ","名聲響亮。[例]這部電影改編自一本著名的小說。"]],"著急":[["ㄓㄠ ㄐㄧˊ","焦慮、急躁。[例]她不小心將重要的文件遺失了，因而著急得不得了。"]],"著想":[["ㄓㄠˊ ㄒㄧㄤˇ","打算、設想。[例]為了你的健康著想，還是不要抽煙的好！"]],"著涼":[["ㄓㄠ ㄌㄧㄤˊ","受到風寒。[例]最近早晚溫差甚大，要注意添加衣服，才不會著涼。"]],"著火":[["ㄓㄠˊ ㄏㄨㄛˇ","失火，起火燃燒。[例]遠處有一座民宅著火了，正冒著濃濃的黑煙。"]],"著稱":[["ㄓㄨˋ ㄔㄥ","見稱、顯揚於世人。[例]曹雪芹以《紅樓夢》一書著稱於世。"]],"著陸":[["ㄓㄨㄛˊ ㄌㄨˋ","降落地面。[例]飛機著陸時，請繫緊安全帶，以免發生意外。"]],"葫蘆":[["ㄏㄨˊ ㄌㄨˊ","1.→扁蒲\n\t\n2.葫蘆的果實。古人常挖出果實內的瓤，中空後作為貯酒的器具。[例]爸爸將成熟的葫蘆晒乾後剖開挖空，製成水瓢。"]],"蒙羞":[["ㄇㄥˊ ㄒㄧㄡ","遭受羞辱。[例]為人子女者要堂堂正正做人，千萬不可作奸犯科，使父母蒙羞。"]],"蒙蔽":[["ㄇㄥˊ ㄅㄧˋ","欺騙、隱瞞事實的真相。[例]記者報導新聞，不宜蒙蔽實情。"]],"蒙面":[["ㄇㄥˊ ㄇㄧㄢˋ","用布巾、面具之類的東西將臉部遮蓋起來。[例]化妝舞會上，大家都用各式巾帕蒙面。"]],"蒲公英":[["ㄆㄨˊ ㄍㄨㄥ ㄧㄥ","植物名。菊科蒲公英屬，多年生草本。莖短，有乳汁。開黃色舌狀花。瘦果褐色，頂端生白色冠毛，便於散布。嫩葉可作蔬菜，亦可入藥，有苦味。[例]風一吹，蒲公英的種子便隨風飛舞，散布各處。　△苦藥草"]],"蒸發":[["ㄓㄥ ㄈㄚ","液體分子脫離液體表面轉化成氣體的現象。[例]水經過蒸發而成為水氣，空氣中的水氣上升到高空，遇冷凝結而形成雲。"]],"蒼生":[["ㄘㄤ ㄕㄥ","比喻人民、百姓。[例]為官者當以天下蒼生的福祉為己任。"]],"蒼白":[["ㄘㄤ ㄅㄞˊ","形容人的臉色白而微青，沒有血色。[例]她大病初癒，身體虛弱、臉色蒼白。"]],"蒼穹":[["ㄘㄤ ㄑㄩㄥ","上蒼、天空。[例]廣浩的蒼穹，星辰羅列，不知有多少宇宙的神祕蘊涵其間。"]],"蒼翠":[["ㄘㄤ ㄘㄨㄟˋ","深綠色。[例]雨後的山色顯得格外蒼翠。"]],"蒼老":[["ㄘㄤ ㄌㄠˇ","形容聲音或外貌的老態。[例]幾年不見，他看起來蒼老許多。"]],"蓋章":[["ㄍㄞˋ ㄓㄤ","蓋圖章以作為憑證。[例]這份契約書要你親自簽名、蓋章才能生效。"]],"蓓蕾":[["ㄅㄟˋ ㄌㄟˇ","1.含苞未開的花。[例]花園裡含苞待放的蓓蕾，讓人滿心期待。\n2.比喻事情即將成熟，尚未成熟的階段。[例]他們倆愛的蓓蕾，即將開花結果。"]],"蓬勃":[["ㄆㄥˊ ㄅㄛˊ","茂盛繁榮的樣子。[例]蓬勃發展、朝氣蓬勃"]],"蓬鬆":[["ㄆㄥˊ ㄙㄨㄥ","鬆散而不密實。[例]她用了一點髮膠，讓頭髮不再蓬鬆。"]],"蓮蓬":[["ㄌㄧㄢˊ ㄆㄥˊ","蓮花凋謝以後的花托。呈倒圓錐形，內含蓮子，通常一個蓮蓬裡有十數顆蓮子。[例]蓮蓬晒乾後可供藥用，中醫用以化瘀、止痢、止血。"]],"蓮霧":[["ㄌㄧㄢˊ ㄨˋ","植物名。桃金孃科赤楠屬，常綠喬木。葉對生，呈長橢圓形或披針狀長橢圓形，表面暗綠色，裡面黃綠色。花色白。果實亦稱為「蓮霧」，由花托變成，呈扁倒圓椎形，有青綠、粉紅和白色等。一般供觀賞，果、葉、種子可為解熱劑。[例]蓮霧的果實清脆可口，糖分又少，是一種低熱量的水果。　◎"]],"蔓生":[["ㄇㄢˋ ㄕㄥ","藤蔓植物攀附他物成長的特性。[例]後院的牽牛花蔓生在籬笆上，形成一道美麗的花牆。"]],"蔚藍":[["ㄨㄟˋ ㄌㄢˊ","深藍色。[例]從山頂向遠處眺望，蔚藍的天空和大海連成一片。"]],"蔬果":[["ㄕㄨ ㄍㄨㄛˇ","蔬菜和水果。[例]颱風過後，蔬果價格居高不下。"]],"蔬菜":[["ㄕㄨ ㄘㄞˋ","一切可供食用的青菜瓜果。[例]現在正是根莖類蔬菜生產的旺季，價廉物美，消費者可多選購食用。"]],"蕉農":[["ㄐㄧㄠ ㄋㄨㄥˊ","種植香蕉的農家或農人。[例]由於香蕉產量過剩，政府正輔導蕉農轉種其他作物。"]],"蕨類":[["ㄐㄩㄝˊ ㄌㄟˋ","→蕨"]],"蕭蕭":[["ㄒㄧㄠ ㄒㄧㄠ","狀聲詞：(1) 形容馬鳴聲。[例]揮手自茲去，蕭蕭班馬鳴。（唐．李白〈送友人〉詩）　(2) 形容風聲。[例]風蕭蕭兮易水寒，壯士一去兮不復還。（《史記．卷八十六．刺客傳．荊軻傳》）　(3) 形容落葉聲。[例]無邊落木蕭蕭下，不盡長江袞袞來。（唐．杜甫〈登高〉詩）"]],"蕾絲":[["ㄌㄟˇ ㄙ","網狀的裝飾性鏤空織物。可作頭紗、髮飾、花邊、窗簾等。§英lace [例]縫上蕾絲花邊的裙子，穿起來多了一點浪漫氣息。"]],"薄片":[["ㄅㄛˊ ㄆㄧㄢˋ","細薄的東西。[例]薄片餅乾、木板薄片"]],"薔薇":[["ㄑㄧㄤˊ ㄨㄟˊ","植物名。薔薇科薔薇屬，常綠或落葉灌木。枝幹多刺，葉為奇數羽狀複葉，邊緣有鋸齒。花朵為兩性花，有紅、白、黃等色，富有香氣。可作觀賞用，亦可加工製作薔薇油和薔薇露。[例]薔薇的葉片平滑，花小而多，和玫瑰不同，兩者極易區別。　△買笑　◎"]],"藉口":[["ㄐㄧㄝˋ ㄎㄡˇ","假託的理由。[例]他以頭痛為藉口，提早退席。"]],"藉由":[["ㄐㄧㄝˋ ㄧㄡˊ","透過、經由。[例]老師藉由海洋生態的影片，引導學生討論環保議題。"]],"藍色":[["ㄌㄢˊ ㄙㄜˋ","藍的顏色、像晴空的顏色。[例]藍色的天空點綴著幾朵白雲，陽光和煦，天氣真是好啊。"]],"藝術家":[["ㄧˋ ㄕㄨˋ ㄐㄧㄚ","從事藝術工作而有相當成就的人。[例]藝術家對美的執著，往往是創作的原動力。"]],"藤條":[["ㄊㄥˊ ㄊㄧㄠˊ","藤的莖條。有彈性，常被用來作為處罰鞭打的工具。[例]闖禍的孩子，看見父親手上的藤條，個個噤若寒蟬，不敢作聲。"]],"藤椅":[["ㄊㄥˊ ㄧˇ","以藤編製而成的椅子。[例]藤椅輕巧，造型變化多，頗受一般家庭喜愛。"]],"藤蔓":[["ㄊㄥˊ ㄇㄢˋ","藤本植物細而蔓延的莖，末端常捲曲如鬚。[例]那棟白屋子外面爬滿了藤蔓，綠意盎然。"]],"藥丸":[["ㄧㄠˋ ㄨㄢˊ","製成圓粒形的成藥。[例]藥廠通常會將藥物製成藥丸，以方便患者吞食。　△藥丸子"]],"藥劑":[["ㄧㄠˋ ㄐㄧˋ","根據藥方而配製的藥品。[例]醫生問診後，便由藥師調配藥劑讓患者服用。"]],"藥品":[["ㄧㄠˋ ㄆㄧㄣˇ","可以用來防治疾病的物質。[例]這些藥品經檢驗合格，患者可以安心服用。"]],"藥局":[["ㄧㄠˋ ㄐㄩˊ","販賣藥品的商店。[例]街口那家藥局藥品齊全，服務也十分周到。"]],"藩籬":[["ㄈㄢˊ ㄌㄧˊ","1.用木柴、竹子等編成屏蔽的圍牆，引申指用來保護防衛的屏障。[例]四面環海的地理條件成為島國的天然藩籬。_x000D_\n2.範圍、邊界。[例]和善的態度有助於打破人與人之間的藩籬。"]],"蘆筍":[["ㄌㄨˊ ㄙㄨㄣˇ","植物名。多年生宿根性草本。葉呈鱗片狀，濃綠細長，六月開白色小花。多分布於溫帶、亞熱帶及熱帶地區。嫩莖可食用。有白蘆筍、綠蘆筍兩種品種。　◎"]],"蘆葦":[["ㄌㄨˊ ㄨㄟˇ","植物名。禾本科蘆屬，多年生草本。花穗呈紫色，下有白毛，可隨風飛散，將種子傳到遠方。多生長於溪流兩岸或沼澤、溼地等水分充足的地方。莖細緻光澤，可編織蘆簾、蘆蓆等。[例]他用蘆葦的莖稈編成一隻蚱蜢。"]],"蘊含":[["ㄩㄣˋ ㄏㄢˊ","蘊藏包含。[例]張老師這番話蘊含了許多的人生哲理，值得我們深思！"]],"蘋果":[["ㄆㄧㄥˊ ㄍㄨㄛˇ","植物名。薔薇科蘋果屬，落葉小喬木。葉卵形或橢圓形，先端尖或短，邊緣有細銳鋸齒。花淡紅色，萼有細毛。果實亦稱為「蘋果」，近於圓形，黃綠色或紅色，味略酸甜，可供食用，亦可造酒等。[例]李媽媽將蘋果去皮切片，做了一個香甜可口的蘋果派。　△頻果　◎"]],"蘿蔔糕":[["ㄌㄨㄛˊ ㄅㄛˊ ㄍㄠ","用糯米漿加上蘿蔔絲、蝦米等配料蒸製而成的食品。[例]過年時媽媽總會買塊蘿蔔糕，以討個好采頭。"]],"虎背熊腰":[["ㄏㄨˇ ㄅㄟˋ ㄒㄩㄥˊ ㄧㄠ","形容人的體格魁偉健碩。[例]參賽的舉重選手一字排開，各個高大魁梧，虎背熊腰。"]],"虔誠":[["ㄑㄧㄢˊ ㄔㄥˊ","恭敬而真誠。[例]阿姨是位虔誠的基督教徒，每星期都會上教堂做禮拜。"]],"處分":[["ㄔㄨˇ ㄈㄣˋ","處罰、懲治。[例]他因為違反校規而受到了嚴厲的處分。"]],"處理":[["ㄔㄨˇ ㄌㄧˇ","處置、辦理。[例]他處理公事有條不紊，從無疏失。"]],"處置":[["ㄔㄨˇ ㄓˋ","1.處理、措置。[例]這件事經他適當的處置後，終於化險為夷了。\n2.處罰、懲治。[例]等到塵埃落定後，再來處置他也不遲。"]],"處罰":[["ㄔㄨˇ ㄈㄚˊ","懲罰。[例]考試違規的同學，學校一律按校規嚴格處罰。"]],"虛幻":[["ㄒㄩ ㄏㄨㄢˋ","不真實、無法捉摸的。[例]濃霧中的景象看起來虛幻縹緲，有如仙境一般。"]],"虛弱":[["ㄒㄩ ㄖㄨㄛˋ","衰微，沒有力氣的。[例]他從小身體虛弱，時常生病。"]],"虛張聲勢":[["ㄒㄩ ㄓㄤ ㄕㄥ ㄕˋ","誇大聲威氣勢，用以嚇阻或欺騙他人。[例]他雖然膽小如鼠，但有時為了掩飾自己的怯懦，卻往往虛張聲勢，耀武揚威。"]],"虛脫":[["ㄒㄩ ㄊㄨㄛ","1.一種心臟和血液循環突然衰竭的現象。通常因大量失血、脫水或中毒等所引起。主要症狀為脈搏微弱、體溫及血壓下降、冷汗不止、面色蒼白或休克等。[例]他因中暑而虛脫昏倒，被人送醫急救。\n2.指精神不濟，體力透支。[例]連續一個多月來忙碌的工作，使她精疲力竭，近於虛脫。"]],"號令":[["ㄏㄠˋ ㄌㄧㄥˋ","1.號召、命令。[例]號令三軍\n2.傳呼的命令。[例]在他一聲號令之下，大夥合力把裝備抬上卡車。"]],"虧欠":[["ㄎㄨㄟ ㄑㄧㄢˋ","1.對人情有所負欠。[例]為了這件事，我們虧欠了太多的人情。\n2.欠債。[例]他如期還清了所虧欠的債務。"]],"虱目魚":[["ㄕ ㄇㄨˋ ㄩˊ","動物名。鼠鱔目虱目魚科。體呈紡錘形，側扁，背部蒼青色，體側和腹部銀白色。以藻類和浮游生物為食。[例]虱目魚煮湯，味道鮮美，大家喜歡食用。"]],"蚊子":[["ㄨㄣˊ ˙ㄗ","→蚊"]],"蚊帳":[["ㄨㄣˊ ㄓㄤˋ","防蚊子的紗帳。[例]晚上就寢最好掛上蚊帳，以防蚊子叮咬。"]],"蚯蚓":[["ㄑㄧㄡ ㄧㄣˇ","動物名。環節動物門貧毛綱。雌雄同體，體圓而細長，柔軟，有很多環節。沒有眼睛、耳朵，用皮膚呼吸。鑽土成穴，使土壤疏鬆，有益於農事。[例]蚯蚓能夠分解腐土，有利於農作物的成長。　△地龍　◎"]],"蛋糕":[["ㄉㄢˋ ㄍㄠ","用雞蛋、麵粉、糖、香料等和勻烘烤製成的糕點。[例]奶油蛋糕、水果蛋糕"]],"蛛網":[["ㄓㄨ ㄨㄤˇ","蜘蛛所結的網。[例]這間古厝，久無人居，牆角已結下層層蛛網。"]],"蛻變":[["ㄊㄨㄟˋ ㄅㄧㄢˋ","原指昆蟲蛻殼變化的過程，引申為事物的轉變。[例]社會的蛻變極為快速，人們必須隨時調整自己的步伐。"]],"蜂巢":[["ㄈㄥ ㄔㄠˊ","蜜蜂所築的巢。[例]從外觀來看，蜂巢是由一個個六角形的小格子組成的。"]],"蜂擁":[["ㄈㄥ ㄩㄥˇ","像蜂群聚在一起，形容人多而擁擠。[例]蜂擁而來、蜂擁而入"]],"蜂窩":[["ㄈㄥ ㄨㄛ","蜜蜂的窩巢。[例]他不小心觸動蜂窩而引來大群蜜蜂螫咬。"]],"蜂蜜":[["ㄈㄥ ㄇㄧˋ","蜜蜂採取花液所釀成的濃稠蜜汁，可供食用和入藥。[例]檸檬汁再加上一點蜂蜜，酸酸甜甜的，好喝又健康。　△蜂糖"]],"蜘蛛":[["ㄓ ㄓㄨ","動物名。節肢動物門蜘蛛綱蜘蛛目。分頭胸部、腹部，有四對腳，每隻腳都有七個節，節末有爪。眼睛二至四對，便於觀察事物。肛門前有瘤狀突起的紡績器，由此抽絲織網、捕食昆蟲。多數為肉食性。[例]某些蜘蛛雖然有毒，但大部分都不會致人於死。　△蛛蛛、社公　◎◎"]],"蜜蜂":[["ㄇㄧˋ ㄈㄥ","泛指膜翅目蜜蜂科昆蟲。頭部有兩個大複眼和三個單眼，視力強，有一對能感受氣味的觸角。有刺，會螫人。社會性昆蟲，居於蜂巢中，成員分工蜂、蜂王和雄蜂三級。[例]蜂蜜是蜜蜂採集花蜜所釀製而成的。"]],"蜿蜒":[["ㄨㄢ ㄧㄢˊ","形容河流、道路等曲折延伸的樣子。[例]順著這條蜿蜒的小路下去，就可到達河邊。"]],"蝌蚪":[["ㄎㄜ ㄉㄡˇ","蛙或蟾蜍的水生幼體。背為黃褐色或黑色，身體呈橢圓形，有鰓，尾巴大而側扁。大多為草食。成長時先生後肢，再生前肢，尾巴逐漸縮小到不留痕跡，最後變成蛙或蟾蜍。[例]老師要學生飼養蝌蚪，並且加以觀察和記錄它的生長狀態。　△科斗、蝌子、懸針◎"]],"蝦仁":[["ㄒㄧㄚ ㄖㄣˊ","去殼的蝦生肉。[例]媽媽買了一些蝦仁回來，準備做一道老爸最愛吃的蝦仁豆腐。"]],"蝦兵蟹將":[["ㄒㄧㄚ ㄅㄧㄥ ㄒㄧㄝˋ ㄐㄧㄤˋ","神話中海龍王手下的兵將。比喻未經訓練，雜湊而成的小嘍囉。[例]由於滋事分子都是些蝦兵蟹將，政府很快就派遣警力予以驅散。"]],"蝦蟆":[["ㄏㄚˊ ㄇㄚˊ","動物名。兩棲綱無尾目蛙屬。體型類似蟾蜍而較小，色呈暗褐，背有黑點，善跳躍，鳴叫時作「呷呷」聲，常居於沼澤邊。[例]蝦蟆會鳴叫及身上沒有疣，是與癩蝦蟆最大不同之處。　△蛤蟆"]],"蝴蝶":[["ㄏㄨˊ ㄉㄧㄝˊ","動物名。昆蟲綱鱗翅目。頭上有對複眼，二隻單眼，複眼間細長的觸角專司感覺。頭下方的口器，呈曲管狀，可伸長吸食花蜜。腹部有氣孔，供呼吸用。胸部生有三對步行腳，兩對翅膀。生長週期分為卵、幼蟲（毛蟲）、蛹及成蟲四個階段。種類繁多，分布世界各地。[例]蝴蝶有一對美麗的翅膀，是大自然界最美麗的昆蟲。　△蚨（ㄈㄨˊ）蝶、胡蝶　◎"]],"蝴蝶結":[["ㄏㄨˊ ㄉㄧㄝˊ ㄐㄧㄝˊ","形狀像蝴蝶的繩結、領結、衣結等。[例]她今天穿得很漂亮，只可惜裙子的蝴蝶結繫歪了。"]],"蝶式":[["ㄉㄧㄝˊ ㄕˋ","一種游泳姿勢。身體俯臥，肩與水面平行，兩臂同時朝前方揮擺，雙腿動作也須對稱一致。[例]這位游泳選手在蝶式一百公尺的項目中得到冠軍。"]],"蝶蛹":[["ㄉㄧㄝˊ ㄩㄥˇ","蝴蝶由幼蟲轉化為成蟲的一種形態。外有一層保護囊膜，經一段時間後，即轉化成蝴蝶。[例]大部分蝶蛹都有很好的保護色，以防止被肉食性小動物捕食。"]],"蝸牛":[["ㄍㄨㄚ ㄋㄧㄡˊ","動物名。軟體動物門腹足綱。為一種有肺的軟體動物，外殼扁圓。頭有四個觸角，其中一對較長。尖端有眼，用腹足蠕動前進。雌雄同體，對農作物有害。[例]蝸牛走過的地方，會留下一道白色透明的黏液。　△篆愁君、水牛兒　◎"]],"螃蟹":[["ㄆㄤˊ ㄒㄧㄝˋ","動物名。節肢動物門甲殼綱。全身滿布甲殼，足五對，最前一對呈鉗狀，橫行，眼有柄。種類繁多，可分為淡水生的河蟹以及海水生的海蟹二大類。[例]當我們到達沼澤地時，發現滿地螃蟹橫行。　◎"]],"融洽":[["ㄖㄨㄥˊ ㄑㄧㄚˋ","感情和睦。[例]他和室友志同道合，相處非常融洽。"]],"螞蟻":[["ㄇㄚˇ ㄧˇ","泛指節肢動物門昆蟲綱膜翅目蟻科的動物。體小、長形，黑或褐色，觸角長，有一對複眼。行團體社會生活，有蟻后、工蟻、兵蟻之分。[例]老師要我們效法螞蟻勤勞、團結的精神。"]],"螢光":[["ㄧㄥˊ ㄍㄨㄤ","廣義的螢光指某些物體受電磁波或帶電粒子照射，吸收能量而放出電磁輻射的過程及現象。一般指物質吸收高能量輻射，消耗一部分後所放出能量較低的光。[例]螢光原理可以用來製造日光燈、電視機等。"]],"螢光幕":[["ㄧㄥˊ ㄍㄨㄤ ㄇㄨˋ","→螢幕"]],"螢幕":[["ㄧㄥˊ ㄇㄨˋ","包含電子槍、偏向裝備和螢光幕的真空管，為電視、示波器、電腦的顯示部分。[例]看電視不要太靠近螢幕，以保視力健康。　△螢光幕"]],"螢火蟲":[["ㄧㄥˊ ㄏㄨㄛˇ ㄔㄨㄥˊ","動物名。昆蟲綱鞘翅目螢科。夏天生於水邊，能飛，夜間腹部會發出燐光，食害蟲，對農作物很有益處。[例]螢火蟲尾端會發光除具有警戒、照明的作用外，亦是求偶時的訊號。　△丹鳥、火蟲兒　◎"]],"螳臂當車":[["ㄊㄤˊ ㄅㄧˋ ㄉㄤˇ ㄔㄜ","螳螂舉起雙臂，想要阻擋車子。比喻不自量力。語本《莊子．人間世》。[例]面對強大的惡勢力要用智取，如果硬碰硬正面對抗，無異是螳臂當車，必定會失敗。"]],"螺絲":[["ㄌㄨㄛˊ ㄙ","具有螺旋狀溝槽的圓柱體及圓孔。溝槽在外圓面的稱為「外螺絲」或「螺桿」，在內面的稱為「內螺絲」或「螺帽」。[例]這個書架是用螺絲接合而成，拆裝很方便。　△螺旋"]],"蟒蛇":[["ㄇㄤˇ ㄕㄜˊ","1.→蟒"]],"蟬翼":[["ㄔㄢˊ ㄧˋ","蟬的翅膀。常用以比喻極輕極薄的物品。[例]這條紗巾薄如蟬翼，搭配衣服效果一定不錯。"]],"蠻橫":[["ㄇㄢˊ ㄏㄥˋ","不講道理。[例]他的態度非常蠻橫，使得協調的工作無法繼續進行。"]],"血液":[["ㄒㄧㄝˇ ㄧㄝˋ","高等動物血管系統中循環流動的液體。主要由血漿、血球細胞和血小板組成，紅色，有黏性及鹹味。它能運送養分、氧氣給細胞，並輸出二氧化碳等廢物至排泄器官，並且調節體溫，製造抗體以抵抗疾病。[例]醫院血庫中存放各式血型的血液，以備不時之需。"]],"血統":[["ㄒㄧㄝˇ ㄊㄨㄥˇ","由血緣形成的親屬系統。凡屬於同一祖先者為同一血統。[例]她是個混血兒，兼有美國和荷蘭的血統。"]],"行人":[["ㄒㄧㄥˊ ㄖㄣˊ","在路上行走的人。[例]清明時節雨紛紛，路上行人欲斷魂。（唐．杜牧〈清明〉詩）"]],"行列":[["ㄏㄤˊ ㄌㄧㄝˋ","直的稱行，橫的稱列。行列指排列的隊伍。[例]操場上，學生們排成整齊的行列參加升旗典禮。"]],"行善":[["ㄒㄧㄥˊ ㄕㄢˋ","做好事、善事。[例]她有一副菩薩心腸，從不放棄任何行善的機會。"]],"行徑":[["ㄒㄧㄥˊ ㄐㄧㄥˋ","行為、舉動。[例]他那鬼鬼祟祟的行徑，怎能叫人不起疑心？"]],"行李":[["ㄒㄧㄥˊ ㄌㄧˇ","出門時所攜帶的裝備。[例]媽媽每回出遠門，總是帶了大包小包的行李，好像要搬家一樣。"]],"行業":[["ㄏㄤˊ ㄧㄝˋ","職業的類別，亦泛指職業。[例]他從事雕刻這個行業已經三十幾年了。"]],"行為":[["ㄒㄧㄥˊ ㄨㄟˊ","由個人內在的意志控制而具體表現在外的舉止動作。[例]他為自己魯莽的行為而道歉。"]],"行蹤":[["ㄒㄧㄥˊ ㄗㄨㄥ","出現或來去的蹤跡。[例]小王的行蹤飄忽不定，恐怕不容易找到他。"]],"行醫":[["ㄒㄧㄥˊ ㄧ","從事醫療工作。[例]他抱著慈悲為懷的信念行醫救人。"]],"行駛":[["ㄒㄧㄥˊ ㄕˇ","泛指駕駛車、船等交通工具。[例]在高速公路上，車輛禁止行駛路肩。"]],"街景":[["ㄐㄧㄝ ㄐㄧㄥˇ","街道的景觀。[例]掛在行道樹上的燈泡繽紛閃爍，形成一幅浪漫的街景。"]],"街道":[["ㄐㄧㄝ ㄉㄠˋ","供人車通行的道路。[例]為避免妨礙交通，打掃街道的工作總在清晨進行。"]],"衛兵":[["ㄨㄟˋ ㄅㄧㄥ","擔任護衛工作的士兵。[例]軍隊為保營區的安全，日夜都派有衛兵防守。"]],"衛生":[["ㄨㄟˋ ㄕㄥ","1.預防疾病，追求健康的觀念和措施。[例]維護公共衛生，人人有責。\n2.清潔。[例]這家館子以講究衛生聞名。"]],"衝撞":[["ㄔㄨㄥ ㄓㄨㄤˋ","1.衝擊碰撞。[例]他因酒醉駕車，而衝撞上安全島，造成車毀人傷。\n2.冒犯頂撞。[例]他在言語上衝撞了父母，但事後尚能悔悟。"]],"衝擊":[["ㄔㄨㄥ ㄐㄧˊ","1.衝撞碰擊。[例]颱風過境時，浪濤強勁的衝擊著沿岸，景象極為驚險。\n2.打擊、影響。[例]國際油價的大幅波動，產業界受到很大的衝擊。"]],"衝突":[["ㄔㄨㄥ ㄊㄨˊ","因意見不同而起爭執。[例]政治場合中，因彼此訴求不同常會與對方發生衝突。"]],"衝鋒":[["ㄔㄨㄥ ㄈㄥ","突入敵陣衝殺。[例]衝鋒殺敵、衝鋒陷陣"]],"衝鋒陷陣":[["ㄔㄨㄥ ㄈㄥ ㄒㄧㄢˋ ㄓㄣˋ","深入敵方陣地向敵人攻擊。形容英勇作戰。[例]身為主帥的他，經常身先士卒，衝鋒陷陣，以鼓舞士氣。"]],"衡量":[["ㄏㄥˊ ㄌㄧㄤˊ","考慮、斟酌。[例]我們要事先衡量事情的利弊得失，不可貿然行動。"]],"衣服":[["ㄧ ㄈㄨˊ","泛指可以穿著的各種衣裳、服裝。[例]母親將家裡的一些舊衣服捐給孤兒院。"]],"衣著":[["ㄧ ㄓㄨㄛˊ","穿戴的衣、帽等。[例]他經常從顧客的衣著、談吐來推測他們的職業。"]],"衣裳":[["ㄧ ˙ㄕㄤ","衣服。[例]妹妹穿了新衣裳，高高興興的去參加阿姨的婚禮。"]],"衣襟":[["ㄧ ㄐㄧㄣ","衣服的前幅有紐扣開合的部分。[例]公司規定員工上班時要將識別證別在衣襟上，以供辨識。"]],"衣錦還鄉":[["ㄧˋ ㄐㄧㄣˇ ㄏㄨㄢˊ ㄒㄧㄤ","功成名就後榮歸故鄉。[例]他出外奮鬥多年，今日終於衣錦還鄉。"]],"表哥":[["ㄅㄧㄠˇ ㄍㄜ","稱謂。用來稱姑媽、姨媽、舅舅的兒子，且年紀比自己長者。[例]表哥從小就陪我們玩，就好像我們的親哥哥一樣。　△表兄　◎"]],"表妹":[["ㄅㄧㄠˇ ㄇㄟˋ","稱謂。用以稱姑媽、姨媽、舅舅的女兒，且年紀比自己小。[例]叔叔的女兒比我年紀小，該稱她為堂妹，而不是表妹。　◎"]],"表弟":[["ㄅㄧㄠˇ ㄉㄧˋ","稱謂。用來稱呼姑媽、姨媽、舅舅的兒子，且年紀比自己小。[例]表弟和堂弟是不同的，表弟是姑媽、姨媽或舅舅的孩子，而堂弟是叔叔、伯父的孩子。　◎"]],"表徵":[["ㄅㄧㄠˇ ㄓㄥ","事實的表現足以證明某種意義。[例]國民平均所得的高低是國家開發進步程度的表徵。"]],"表情":[["ㄅㄧㄠˇ ㄑㄧㄥˊ","1.由臉部的表現和身體的動作，所表達的喜怒、哀樂、好惡等情感。[例]他臉上流露出興奮的表情。\n2.藉由臉部或肢體動作的變化，表達內心的思想、感情。[例]表情達意"]],"表演":[["ㄅㄧㄠˇ ㄧㄢˇ","1.把情節內容或技藝公開表現出來，供人觀賞或學習。[例]把你最得意的動作表演一下！\n2.把情節或技藝公開表現的方式。[例]飛行表演、魔術表演"]],"表率":[["ㄅㄧㄠˇ ㄕㄨㄞˋ","模範、榜樣。[例]他的孝行足可作為眾人的表率。"]],"表示":[["ㄅㄧㄠˇ ㄕˋ","1.表達顯示。[例]他再三鞠躬，表示感謝。\n2.表達思想感情的言語或動作。[例]對這件事，不知他有何表示？"]],"表達":[["ㄅㄧㄠˇ ㄉㄚˊ","將心中的思想以具體的形式傳遞給別人知道。[例]他的話充分表達了他對國家的愛。"]],"衰弱":[["ㄕㄨㄞ ㄖㄨㄛˋ","不強健或不興盛。[例]他因長期營養不良，身體非常衰弱。"]],"衰微":[["ㄕㄨㄞ ㄨㄟˊ","沒落、不興旺。[例]青銅器大量使用於商周時期，鐵器出現後就逐漸衰微。"]],"衰敗":[["ㄕㄨㄞ ㄅㄞˋ","沒落且敗壞。[例]金礦枯竭後，附近的小鎮也迅速衰敗下來。"]],"衰竭":[["ㄕㄨㄞ ㄐㄧㄝˊ","生理機能耗盡，力量用盡。[例]這個老人因心臟衰竭去世。"]],"衰老":[["ㄕㄨㄞ ㄌㄠˇ","體貌老化，精力耗損。[例]他遭遇重大變故，一夕之間衰老許多。"]],"衰退":[["ㄕㄨㄞ ㄊㄨㄟˋ","逐漸減弱。[例]她患有嚴重的糖尿病，視力逐漸衰退。"]],"衷心":[["ㄓㄨㄥ ㄒㄧㄣ","出自內心。[例]我們衷心祝福她有個美滿的婚姻。"]],"衷曲":[["ㄓㄨㄥ ㄑㄩ","內心的情意。[例]他倆分隔兩地，只能靠信件的往來互訴衷曲。"]],"袋鼠":[["ㄉㄞˋ ㄕㄨˇ","動物名。哺乳綱有袋目袋鼠科。前腿短小，後腿壯碩有力，善於跳躍，尾巴粗大，能平衡身體，雌鼠腹部有育兒的皮囊。以草、穀類、樹葉為食，產於澳洲與塔斯馬尼亞島上。[例]在草原中，袋鼠大多成群結隊的活動。"]],"袍澤":[["ㄆㄠˊ ㄗㄜˊ","本指衣服。今為軍人互稱，表示患難與共。語本《詩經．秦風．無衣》。[例]小李和我是軍中袍澤，我們之間情同手足。"]],"袖口":[["ㄒㄧㄡˋ ㄎㄡˇ","袖子的邊緣。[例]這件衣服穿太久，領口跟袖口都磨破了。"]],"袖手旁觀":[["ㄒㄧㄡˋ ㄕㄡˇ ㄆㄤˊ ㄍㄨㄢ","把手放在袖子裡，在一旁觀看。比喻置身事外，不予過問。[例]朋友有急難，我們應當伸出援手，不可袖手旁觀。"]],"袖珍":[["ㄒㄧㄡˋ ㄓㄣ","形容小型的或小巧的。[例]袖珍本、袖珍字典、袖珍收音機"]],"被動":[["ㄅㄟˋ ㄉㄨㄥˋ","經由外力刺激後才展開行動。[例]凡事要主動些，不可處處被動！"]],"被單":[["ㄅㄟˋ ㄉㄢ","套在被胎外面的一層布。[例]被單要經常換洗，以保持清潔。"]],"被騙":[["ㄅㄟˋ ㄆㄧㄢˋ","遭受欺騙。[例]近來詐騙案件頻傳，千萬要當心別被騙了。"]],"裁判":[["ㄘㄞˊ ㄆㄢˋ","1.依競賽規則，對競賽成績或競賽中所發生的問題作公平的處置或評判。[例]由於裁判失當，參賽的一方憤而退場。\n2.依競賽規則處置競賽中所發生的問題及評斷勝負的人。[例]經過激烈的比賽後，裁判宣布我隊獲勝。　△裁判員\n3.法律上指審判機關依事實和法律，對當事人或訴訟關係人所作的決定。可分為判決及裁定。[例]這場官司法院裁判原告勝訴。"]],"裁員":[["ㄘㄞˊ ㄩㄢˊ","公司、機關為節省經費而緊縮編制或削減閒散不必要的人員。[例]最近經濟不景氣，各公司紛紛裁員。"]],"裁定":[["ㄘㄞˊ ㄉㄧㄥˋ","法院就某事件斷定其是否合法或正當。[例]這件房屋所有權案，法官最後裁定原告勝訴。"]],"裁縫":[["ㄘㄞˊ ㄈㄥˊ","1.對布料的裁剪縫製。[例]她利用空閒時間去學裁縫。\n\t\n2.剪裁及縫製衣服的人。[例]那個裁縫做工細緻、價錢公道，吸引不少顧客。"]],"裁軍":[["ㄘㄞˊ ㄐㄩㄣ","裁減軍隊與軍事裝備。[例]美蘇冷戰結束後雙方協議裁軍，以維護世界和平。"]],"裁量":[["ㄘㄞˊ ㄌㄧㄤˊ","推測度量而定取捨。[例]主管單位經多方裁量，才公布這項方案。"]],"裂痕":[["ㄌㄧㄝˋ ㄏㄣˊ","1.裂縫。[例]這方硯臺已出現裂痕，無法再使用了。\n2.比喻感情上的破裂。[例]他們之間的友誼因誤會而產生了裂痕，想重修舊好恐怕不容易。"]],"裂縫":[["ㄌㄧㄝˋ ㄈㄥˋ","裂開的狹長隙縫。[例]頂樓天花板上有道裂縫，雨天時經常漏水。"]],"裂開":[["ㄌㄧㄝˋ ㄎㄞ","破裂分開。[例]一場強震之後，建築工地的地基竟然裂開了。"]],"裊裊":[["ㄋㄧㄠˇ ㄋㄧㄠˇ","1.縈迴繚繞、搖曳不定的樣子。[例]輕煙裊裊\n2.音調悠揚不絕。[例]餘音裊裊"]],"裙子":[["ㄑㄩㄣˊ ˙ㄗ","一種圍在腰部以下的服裝，古時候男女都穿，後來多為女子服飾。[例]妹妹穿著白色襯衫、碎花布裙子，十分俏麗可愛。　△裙"]],"補充":[["ㄅㄨˇ ㄔㄨㄥ","增補不足之處。[例]補充說明、補充體力"]],"補助":[["ㄅㄨˇ ㄓㄨˋ","貼補、支助。[例]這次旅遊，公司補助一半的費用。"]],"補給":[["ㄅㄨˇ ㄐㄧˇ","供應、補充不足的東西。[例]這座高山雷達站所需要的用品，每個月從山下補給一次。"]],"補綴":[["ㄅㄨˇ ㄓㄨㄟˋ","修補裂縫。[例]孔明有斡旋天地，補綴乾坤之才，是古今第一人。"]],"裝置":[["ㄓㄨㄤ ㄓˋ","1.安裝配置。[例]典禮會場的音效設備已經裝置完畢，隨時可以啟用。_x000D_\n2.具有某種獨立功能的設備或部件。[例]行動裝置、減速裝置"]],"裡面":[["ㄌㄧˇ ㄇㄧㄢˋ","內部。[例]這個衣櫥裡面收的都是他常穿的衣服。"]],"裡頭":[["ㄌㄧˇ ˙ㄊㄡ","內部。[例]屋子裡頭傳出了陣陣歡樂的笑聲。"]],"製作":[["ㄓˋ ㄗㄨㄛˋ","製造、創作。[例]這幅壁報是我們全班同學傾力製作完成的。"]],"製造":[["ㄓˋ ㄗㄠˋ","1.把原料做成成品。[例]這間工廠專門製造腳踏車，產品暢銷國內外。_x000D_\n2.人為地造成某種形勢或結果。[例]製造麻煩、製造驚喜_x000D_"]],"複習":[["ㄈㄨˋ ㄒㄧˊ","溫習已學習過的知識、技能、課程等。[例]他每天晚上都將老師當日所教的內容複習一遍。"]],"複製":[["ㄈㄨˋ ㄓˋ","仿造或翻印原件。[例]複製有專利權的產品是違法的。"]],"複賽":[["ㄈㄨˋ ㄙㄞˋ","競賽中在預賽後、決賽前所進行的比賽。[例]經過初賽的淘汰，能參加複賽的人已經不多了。"]],"複雜":[["ㄈㄨˋ ㄗㄚˊ","多樣而繁雜。[例]他的人際關係很複雜。"]],"褐色":[["ㄏㄜˊ ㄙㄜˋ","介於黃、黑之間的顏色。[例]人類眼珠的顏色繁多，常見的有褐色、綠色和藍色等。"]],"襯托":[["ㄔㄣˋ ㄊㄨㄛ","烘托，使主體明顯。[例]這湖水在山林的襯托之下，更添靈秀之氣。"]],"襲擊":[["ㄒㄧˊ ㄐㄧˊ","趁人沒有防備的時候，突然發動攻擊。[例]他被人自背後襲擊，頭上腫了一個包。"]],"西瓜":[["ㄒㄧ ㄍㄨㄚ","植物名。葫蘆科西瓜屬，一年生草本。莖蔓生多分歧，有卷鬚，常攀緣他物生長。葉形似羽狀複葉。夏季開淡黃色花朵，雌雄同株。果實亦稱為「西瓜」，呈球形或橢圓形，果皮有白綠色的蛇斑，果肉通常為紅色或黃色，水分多，味甜。[例]西瓜是夏天消暑解渴的好水果。　◎"]],"要塞":[["ㄧㄠˋ ㄙㄞˋ","多指軍事或國防上的重要據點。[例]政府打算在這個要塞構築工事，以增強防禦功能。"]],"要挾":[["ㄧㄠ ㄒㄧㄚˊ","有所憑恃而強迫別人服從。[例]別接受他的要挾，諒他也不敢耍手段！"]],"要旨":[["ㄧㄠˋ ㄓˇ","主要的意義。[例]這個故事的要旨在說明友情的可貴。"]],"要求":[["ㄧㄠ ㄑㄧㄡˊ","1.請求、索求。[例]與人相處不可一味的要求對方付出，而自己獨自享受成果。\n2.對方所提出的願望與條件。[例]我無法答應他這個無理的要求。"]],"要緊":[["ㄧㄠˋ ㄐㄧㄣˇ","急切重要。[例]手術過後，要緊的是趕快把身子調養好。"]],"要衝":[["ㄧㄠˋ ㄔㄨㄥ","重要的地方。[例]交通要衝、軍事要衝"]],"要領":[["ㄧㄠˋ ㄌㄧㄥˇ","主旨、綱領。[例]他做事不得要領，難怪老是出錯。"]],"要點":[["ㄧㄠˋ ㄉㄧㄢˇ","1.言詞、書籍等的重要處。[例]看書要能掌握要點，才能事半功倍。\n2.重要的地點。[例]警方已經在各路口要點布署，以防止歹徒逃脫。"]],"覆沒":[["ㄈㄨˋ ㄇㄛˋ","1.翻覆、沉沒。[例]漁船在狂風巨浪中覆沒了。\n2.被消滅。[例]全軍覆沒"]],"覆蓋":[["ㄈㄨˋ ㄍㄞˋ","掩覆遮蓋。[例]大地被白雪覆蓋成一片銀色世界。"]],"見聞":[["ㄐㄧㄢˋ ㄨㄣˊ","眼睛所看見、耳朵所聽到的事物。[例]他把這次旅遊的見聞寫下，在報紙上發表。"]],"見解":[["ㄐㄧㄢˋ ㄐㄧㄝˇ","對事物的理解、看法。[例]對於這個問題，大家的見解頗不一致，無法達成共識。"]],"見證":[["ㄐㄧㄢˋ ㄓㄥˋ","當場目睹而可以作證的人或可以作為證據的物品。[例]事發時他正好路過該處，可為這場車禍見證。"]],"見面":[["ㄐㄧㄢˋ ㄇㄧㄢˋ","會面、碰面。[例]他們夫妻倆因戰亂而分離，再度見面已相隔四十年。"]],"規劃":[["ㄍㄨㄟ ㄏㄨㄚˋ","籌謀策劃。[例]這家建設公司將社區的道路規劃為人車分道，以確保行人的安全。"]],"規勸":[["ㄍㄨㄟ ㄑㄩㄢˋ","以正言勸人改過。[例]輔導老師正在規勸犯錯的學生，希望他們能改過。"]],"規定":[["ㄍㄨㄟ ㄉㄧㄥˋ","1.制定準則。[例]依交通法規規定，年滿十八歲者才可以報考汽機車駕照。\n2.泛稱各種法律或規章的約束。[例]符合規定。"]],"規律":[["ㄍㄨㄟ ㄌㄩˋ","規則、條律。[例]生活要有規律，身體才會健康。"]],"規矩":[["ㄍㄨㄟ ㄐㄩˇ","1.畫圓、畫方的工具。[例]規矩是畫設計圖時不可或缺的工具。\n2.法度、準則。[例]人從小就在父母及老師的教養下學習各種規矩，日後才能適應社會生活。\n3.行為端正老實。[例]他向來規矩，從不惹事生非。"]],"規程":[["ㄍㄨㄟ ㄔㄥˊ","規則章程。[例]經由多次開會討論，本會的規程終於產生了。"]],"規規矩矩":[["ㄍㄨㄟ ㄍㄨㄟ ㄐㄩˇ ㄐㄩˇ","形容行為端正、有條理，合於法度。[例]他做事總是規規矩矩的，所以能得到上司的信任。"]],"覓食":[["ㄇㄧˋ ㄕˊ","尋找食物。[例]許多小鳥吱吱喳喳地在花園裡四處覓食。"]],"視力":[["ㄕˋ ㄌㄧˋ","眼力。常人在一定距離內，眼睛辨識事物的能力。[例]他經常在行駛中的公共汽車上看書，視力會因而受損。"]],"視覺":[["ㄕˋ ㄐㄩㄝˊ","眼睛與物體形像接觸後所生的感覺。是由於眼球網膜上錐狀細胞和柱狀細胞受光波刺激而引起的反應。[例]這幅畫的構圖和用色，突破傳統窠臼，使人的視覺受到強大的震撼。"]],"視訊":[["ㄕˋ ㄒㄩㄣˋ","影像、畫面、聲音所轉化成的電波訊息。[例]現代智慧型大樓使用社區共同天線，既可接收外來視訊，也可播放內設頻道的節目。"]],"親人":[["ㄑㄧㄣ ㄖㄣˊ","關係親近的親屬。[例]他返鄉尋找親人。"]],"親切":[["ㄑㄧㄣ ㄑㄧㄝˋ","和善熱誠。[例]她因為待人親切，所以人緣極佳。"]],"親吻":[["ㄑㄧㄣ ㄨㄣˇ","用嘴脣接觸，表示親密喜愛。[例]她滿心喜悅地親吻懷中的新生兒。"]],"親子":[["ㄑㄧㄣ ㄗˇ","父母和子女的合稱。[例]親子間若能充分溝通，就不至於形成對立，引發衝突。"]],"親密":[["ㄑㄧㄣ ㄇㄧˋ","親近密切。[例]我與兄弟姊妹之間關係十分親密，羨煞旁人。"]],"親屬":[["ㄑㄧㄣ ㄕㄨˇ","因血統、婚姻或收養而與自己有關係的人。如血親、姻親、配偶均屬之。[例]這兩個家庭因締結婚姻而建立了親屬關係。　◎"]],"親情":[["ㄑㄧㄣ ㄑㄧㄥˊ","親人之間的感情。[例]他曾經誤入歧途，但因為親情的力量，使他改過向善。"]],"親愛":[["ㄑㄧㄣ ㄞˋ","關係密切、情感深厚。[例]父親節那天，我特地買了一件襯衫，送給最親愛的父親當禮物。"]],"親朋好友":[["ㄑㄧㄣ ㄆㄥˊ ㄏㄠˇ ㄧㄡˇ","泛指所有的親戚、朋友。[例]本店開張之日，希望各位親朋好友都能光臨指教。"]],"親自":[["ㄑㄧㄣ ㄗˋ","自己、本人。[例]為了成立南部的分公司，經理親自南下籌備策劃。"]],"親近":[["ㄑㄧㄣ ㄐㄧㄣˋ","親善接近。[例]他雖然一副不太好親近的樣子，其實是面惡心善的人。"]],"覺得":[["ㄐㄩㄝˊ ˙ㄉㄜ","感到、認為。[例]我覺得天氣似乎慢慢變冷了。"]],"覺醒":[["ㄐㄩㄝˊ ㄒㄧㄥˇ","醒悟。[例]他過去雖曾一度誤入歧途，但是現在已經覺醒了。"]],"觀察":[["ㄍㄨㄢ ㄔㄚˊ","仔細察看。[例]那個小男孩蹲在牆腳，好奇地觀察螞蟻的活動。"]],"觀測":[["ㄍㄨㄢ ㄘㄜˋ","對事物的觀察與測量。[例]氣象觀測、星象觀測、地形觀測"]],"觀看":[["ㄍㄨㄢ ㄎㄢˋ","觀賞察看。[例]他喜歡到球場觀看比賽，感受現場緊張刺激的氣氛。"]],"觀賞":[["ㄍㄨㄢ ㄕㄤˇ","觀看欣賞。[例]晚會的節目非常精彩，歡迎大家前往觀賞。"]],"角":[["ㄐㄧㄠˇ","1.獸類頭上或鼻前長出的硬質突狀物。[例]牛角、鹿角\n2.幾何學上稱兩直線相交所夾成的空間。[例]直角、鈍角、對頂角\n3.地理學上指陸地向海中突出的部分。[例]岬角、鼻頭角、好望角\n4.角落，物體邊緣相接成角的地方。[例]牆角、桌角、屋角\n5.競爭、較量。[例]口角、角力\n6.樂器名。屬吹管樂器，以動物的角製成，後改用竹、木、銅等材料。有曲形、竹筒等形狀。多用於軍隊中。[例]號角\n7.量詞。計算錢幣的單位。十角等於一元。\n8.→(二)1.之語音"],["ㄐㄩㄝˊ","1.戲劇或電影中的表演人物。[例]角色、主角、丑角\n2.二十八星宿之一。為東方蒼龍七宿的第一宿，有兩顆星。\n3.五音之一。[例]宮商角徵羽"]],"角落":[["ㄐㄧㄠˇ ㄌㄨㄛˋ","1.物體邊緣相接成角的地方。[例]哥哥在閣樓的角落裡，發現了他小時候的溜冰鞋。　◎\n\t\n2.偏僻、不受注意的地方。[例]國家建設必須落實到每個角落，才算是真正的造福全體人民。"]],"解嘲":[["ㄐㄧㄝˇ ㄔㄠˊ","用言語或行動來解釋自己受人嘲笑的事情。[例]因為個子小，他常用短小精悍這句話來自我解嘲。"]],"解散":[["ㄐㄧㄝˇ ㄙㄢˋ","1.以強制力消除已結合的團體。[例]解散國會\n2.一種口令。為疏散群集的人群時所使用。[例]解散後，各班自行帶回。解散！"]],"解決":[["ㄐㄧㄝˇ ㄐㄩㄝˊ","1.疏解紛亂，或處理問題有了結果。[例]他租到了一間公寓，解決了住的問題。\n2.澈底消除。[例]經過一個早上的拔除，終於把田中的雜草解決了。"]],"解渴":[["ㄐㄧㄝˇ ㄎㄜˇ","消除口渴。[例]在激烈的運動後，她習慣喝一大杯白開水解渴。"]],"解答":[["ㄐㄧㄝˇ ㄉㄚˊ","解釋回答。[例]老師對這個問題做了詳細的解答。"]],"解謎":[["ㄐㄧㄝˇ ㄇㄧˊ","解開不明白的或難以理解的事物。[例]有關南美洲印加帝國突然消失的原因，眾說紛紜，仍有待學者來解謎。"]],"解釋":[["ㄐㄧㄝˇ ㄕˋ","1.分析闡明。[例]這篇文章經過他的解釋後，閱讀起來更能體會作者所要表達的意念。\n2.說明某事的原因、理由。[例]為了這誤會，她親自向老師解釋這件事的原由。"]],"解開":[["ㄐㄧㄝˇ ㄎㄞ","打開。[例]她解開歹徒的捆綁，安全脫身。"]],"觸摸":[["ㄔㄨˋ ㄇㄛ","碰觸撫摸。[例]危險物品應禁止小孩觸摸，以避免發生意外。"]],"觸犯":[["ㄔㄨˋ ㄈㄢˋ","干犯、冒犯。[例]他因觸犯校規而被記過。"]],"言簡意賅":[["ㄧㄢˊ ㄐㄧㄢˇ ㄧˋ ㄍㄞ","言辭簡單而要義賅括。[例]先生這幾句話言簡意賅，真是令人佩服。"]],"言行":[["ㄧㄢˊ ㄒㄧㄥˊ","說話和行為。[例]言行一致"]],"言論":[["ㄧㄢˊ ㄌㄨㄣˋ","言談議論。[例]這是他個人的言論，與他所服務的單位無關。"]],"訂婚":[["ㄉㄧㄥˋ ㄏㄨㄣ","在結婚前舉辦的訂定婚約儀式。是民間由來已久的習俗。　△文定"]],"訂定":[["ㄉㄧㄥˋ ㄉㄧㄥˋ","制定。[例]購屋時須訂定契約，將產權交代清楚。"]],"訂正":[["ㄉㄧㄥˋ ㄓㄥˋ","校訂改正。[例]在三校​訂正後，此書便可送交清樣，準備印刷了。"]],"訂閱":[["ㄉㄧㄥˋ ㄩㄝˋ","顧客事先約定定期取得書刊或資訊商品。[例]訂閱雜誌、影音訂閱、服務訂閱"]],"計劃":[["ㄐㄧˋ ㄏㄨㄚˋ","事先研議訂定。[例]這次旅遊，我們計劃先去香港，再到馬來西亞。"]],"計畫":[["ㄐㄧˋ ㄏㄨㄚˋ","事先擬定的具體方案或辦法。[例]這個計畫缺點太多，執行起來必然漏洞百出。"]],"計算":[["ㄐㄧˋ ㄙㄨㄢˋ","1.核算數目。[例]他稍微計算了一下，約有八十個人來參加這個活動。\n2.計劃打算。[例]這個月的零用錢要怎麼花用，你最好先計算一下。\n3.暗中謀劃，對付他人。[例]做人要光明磊落，不要背後計算別人。"]],"計算機":[["ㄐㄧˋ ㄙㄨㄢˋ ㄐㄧ","→電子計算機"]],"計謀":[["ㄐㄧˋ ㄇㄡˊ","計策謀略。[例]我們必須想出一個兩全其美的計謀，才能把敵人打得落花流水。"]],"計較":[["ㄐㄧˋ ㄐㄧㄠˋ","計算、比較。[例]人與人相處當以寬容為貴，不要處處計較。"]],"訊息":[["ㄒㄩㄣˋ ㄒㄧˊ","音訊消息。[例]好久沒有他的訊息，不知他近況如何？"]],"訊號":[["ㄒㄩㄣˋ ㄏㄠˋ","用來指示或聯絡的訊息或信號。[例]海邊的燈塔每到夜晚便會以燈光做為訊號，指引海上航行的船隻。"]],"討論":[["ㄊㄠˇ ㄌㄨㄣˋ","相互探討研究，以尋求結論。[例]這項決議是經過討論、表決後才定案的。"]],"訓練":[["ㄒㄩㄣˋ ㄌㄧㄢˋ","經由有計畫、步驟的指導，並實地操作練習，使受訓者具有某種特長或技能。[例]這隻狗經訓練之後，成為非常優秀的導盲犬。"]],"訓誨":[["ㄒㄩㄣˋ ㄏㄨㄟˋ","訓誡教誨。[例]老師的訓誨讓我受益無窮。"]],"託付":[["ㄊㄨㄛ ㄈㄨˋ","委請交付。[例]他出國旅遊期間，將家中的一切事務託付鄰居，代為看管照顧。"]],"託福":[["ㄊㄨㄛ ㄈㄨˊ","仰賴別人的福庇。是回答他人問話的客氣用語。[例]託福，託福，這一向還好。"]],"記得":[["ㄐㄧˋ ˙ㄉㄜ","存留在腦海中不忘掉。[例]雖然事過多年，但我仍然記得當時的一切景象。"]],"記憶":[["ㄐㄧˋ ㄧˋ","1.指在腦海中存留的一切。[例]那是三十年前的往事，如今記憶已經模糊了。\n2.心理學上指由識記、保持、回憶（或再識）三個基本環節組成的心理歷程。記憶的敏捷性、持久性及準確性因人而異，但均可培養和改變。"]],"記號":[["ㄐㄧˋ ㄏㄠˋ","標記符號。[例]她在需要改動的地方做了記號，以便請裁縫師重新修改。"]],"記載":[["ㄐㄧˋ ㄗㄞˋ","記錄刊載。[例]這篇報導忠實的記載了整個事件的經過。"]],"記錄":[["ㄐㄧˋ ㄌㄨˋ","1.記載登錄。[例]他細心的進行氧化的實驗，並將過程和結果記錄下來。\n2.做記錄的人。[例]下次的會議就由你擔任記錄。　△紀錄"]],"訝異":[["ㄧㄚˋ ㄧˋ","覺得意外，難以相信。[例]他的成績進步神速，真令人訝異！"]],"訪友":[["ㄈㄤˇ ㄧㄡˇ","探望朋友。[例]假日時，他常四處訪友。"]],"訪問":[["ㄈㄤˇ ㄨㄣˋ","拜訪詢問。[例]在訪問以前，先要取得受訪者的同意，並約好時間。"]],"訪談":[["ㄈㄤˇ ㄊㄢˊ","拜訪交談。[例]為了深入了解青少年的問題，我們進行了抽樣對象的訪談。"]],"設備":[["ㄕㄜˋ ㄅㄟˋ","建築或器物的設置、設備。[例]本校不管是在軟體或是硬體方面，設備都很完善。"]],"設施":[["ㄕㄜˋ ㄕ","設備、措施。[例]公共設施、交通設施、軍事設施"]],"設法":[["ㄕㄜˋ ㄈㄚˇ","籌劃、想辦法。[例]你只管努力唸書，學費就由爸爸來設法吧。"]],"設置":[["ㄕㄜˋ ㄓˋ","1.設立。[例]本公司設置了一個新部門，專門從事研發工作。_x000D_\n2.裝置。[例]為加強地區治安，許多超商都設置了巡邏箱。"]],"設計":[["ㄕㄜˋ ㄐㄧˋ","1.預先規劃、製定圖樣。[例]室內設計、景觀設計\n2.設定謀略、算計。[例]原本億萬家產的他，在遭人設計之後，傾家蕩產，身敗名裂。"]],"設身處地":[["ㄕㄜˋ ㄕㄣ ㄔㄨˇ ㄉㄧˋ","假設自己處在與他人相同的境地。比喻為別人著想。[例]凡事能設身處地的為人考慮，就可以避免許多紛爭。"]],"許多":[["ㄒㄩˇ ㄉㄨㄛ","很多。[例]人生的路途上有許多困難，我們要勇於克服。"]],"許願":[["ㄒㄩˇ ㄩㄢˋ","向神明祈福，並承諾於願望實現後將付出某種代價表示酬謝，稱為「許願」。[例]他在廟裡許願，若順利通過考試，將以鮮花素果祭拜答謝。"]],"訴求":[["ㄙㄨˋ ㄑㄧㄡˊ","要求、請求。[例]這次勞工團體代表的訴求重點，在於要求資方改善工作環境及減少加班次數。"]],"診所":[["ㄓㄣˇ ㄙㄨㄛˇ","醫生私人開設，以醫治病人的小型醫院。[例]巷口的牙科診所非常有名，上門求診的人很多。"]],"診斷":[["ㄓㄣˇ ㄉㄨㄢˋ","醫生檢視病患的症狀，以判定病情。[例]經過醫生的診斷後，確定他是得了急性腸胃炎。"]],"註冊":[["ㄓㄨˋ ㄘㄜˋ","向有關機關、團體或學校登記備案。[例]許多青年學子趁著寒暑假四處打工，自己賺取註冊費用。"]],"註定":[["ㄓㄨˋ ㄉㄧㄥˋ","一種宿命思想，以為個人或團體的一切遭遇或變化，上天早已決定，非人力所能更易。[例]樂觀、積極的做人處事態度，註定他以後一定會成功。"]],"註明":[["ㄓㄨˋ ㄇㄧㄥˊ","記載清楚。[例]電器用品的說明書上，清楚註明了使用方法。"]],"註銷":[["ㄓㄨˋ ㄒㄧㄠ","取消登錄的事項。[例]汽、機車報廢時，得先至監理機關辦理註銷牌照。"]],"詐欺":[["ㄓㄚˋ ㄑㄧ","作假欺騙。[例]開立空頭支票是一種詐欺的行為。"]],"詐降":[["ㄓㄚˋ ㄒㄧㄤˊ","假裝投降。[例]如今敵強我弱，是否能先行詐降？"]],"評估":[["ㄆㄧㄥˊ ㄍㄨ","根據預定的標準，衡量事物已有或將有的效果。[例]政府委託相關研究機構，評估填海工程對周遭環境的影響。"]],"評價":[["ㄆㄧㄥˊ ㄐㄧㄚˋ","1.評估人、事、物的優劣。[例]就這兩件作品加以評價，甲作品顯然優於乙作品。\n2.評定的價值。[例]這部小說在文壇上獲得很高的評價。"]],"評斷":[["ㄆㄧㄥˊ ㄉㄨㄢˋ","評議決斷。[例]我們不能因為他一時的失誤，便評斷他的功過。"]],"評語":[["ㄆㄧㄥˊ ㄩˇ","用來評定好壞的語言文字。[例]老師給模範生的評語是「品學兼優」。"]],"評選":[["ㄆㄧㄥˊ ㄒㄩㄢˇ","評定選擇。[例]這本合集一共評選了五位作家共二十篇的散文。"]],"詞語":[["ㄘˊ ㄩˇ","言詞、話語。[例]寫作應盡量避免生僻的詞語。"]],"詢問":[["ㄒㄩㄣˊ ㄨㄣˋ","查問。[例]市政府設有服務臺，供民眾詢問，解答疑難。"]],"試題":[["ㄕˋ ㄊㄧˊ","考試的題目。[例]老師將試題寫在黑板上，要學生依序作答。"]],"詩人":[["ㄕ ㄖㄣˊ","擅長作詩的人。[例]這位詩人的作品一向備受推崇，因此在藝文界頗有盛名。"]],"詩情畫意":[["ㄕ ㄑㄧㄥˊ ㄏㄨㄚˋ ㄧˋ","形容如詩畫般美好浪漫。[例]這一片湖光山色，充滿了詩情畫意。"]],"詩歌":[["ㄕ ㄍㄜ","詩的通稱。古今之詩，或可歌，或不可歌，統稱為「詩歌」。[例]詩歌可以陶冶性靈，豐富人們的精神生活。"]],"詩篇":[["ㄕ ㄆㄧㄢ","詩歌篇章。[例]這本詩集共有三類詩篇，分別為山水、花鳥及人物。"]],"詫異":[["ㄔㄚˋ ㄧˋ","驚奇、訝異。[例]沒預料到他會出現，所以現場的人個個都一臉詫異。"]],"詮釋":[["ㄑㄩㄢˊ ㄕˋ","詳細深入的解釋、闡明。[例]這本書將莊子無為而治的思想，做了最佳詮釋。"]],"詳情":[["ㄒㄧㄤˊ ㄑㄧㄥˊ","詳細的情形。[例]這件事的詳情，很多人都弄不清楚。"]],"詳細":[["ㄒㄧㄤˊ ㄒㄧˋ","完備、仔細。[例]經過詳細的檢查後，醫生終於確定她得了癌症。"]],"詳述":[["ㄒㄧㄤˊ ㄕㄨˋ","詳細敘述。[例]這是一本詳述現代科技發展狀況的好書，很值得一看。"]],"詼諧":[["ㄏㄨㄟ ㄒㄧㄝˊ","言語風趣、幽默的。[例]他詼諧風趣的演講，博得全場聽眾如雷的掌聲。"]],"誇大":[["ㄎㄨㄚ ㄉㄚˋ","言語超過原有的事實。[例]誇大不實"]],"誇張":[["ㄎㄨㄚ ㄓㄤ","1.誇大。[例]張先生誇張的敘述他如何與歹徒搏鬥且毫髮未損的過程。\n2.修辭學上的一種辭格。即用主觀的想像來誇飾所要形容的事物，使其超過事實，以增強所要表達的效果。[例]有些廣告用詞誇張，目的在吸引觀眾的注意。"]],"認為":[["ㄖㄣˋ ㄨㄟˊ","對某一事物經分析思考後所作的判斷。[例]雖然大家都相信他的說詞，但我卻不這麼認為。"]],"認真":[["ㄖㄣˋ ㄓㄣ","1.切實負責而不馬虎隨便。[例]要有好的表現，必須努力用功，認真學習。\n2.當真。[例]他只是開玩笑罷了，你又何必認真呢？"]],"認識":[["ㄖㄣˋ ㄕˋ","1.相識。[例]她倆在學生時代就認識，至今已有十年了。\n2.認得。[例]他在上小學前，已經認識很多字。"]],"認輸":[["ㄖㄣˋ ㄕㄨ","承認失敗。[例]他的好勝心甚強，對任何事都不肯認輸。"]],"認領":[["ㄖㄣˋ ㄌㄧㄥˇ","1.指經由確認後領回。[例]認領失物\n2.法律名詞。非婚生子女經生父認領者，視為婚生子女，其經生父撫育者，視為認領。非婚生子女與其生母之關係視為婚生子女，無須認領。[例]法律規定，經生父撫育或認領之非婚生子女，因繼承而承受之權利及義務，亦與婚生子女同。"]],"誓師":[["ㄕˋ ㄕ","1.軍隊出征前，統帥訓示告誡將士，表示堅決的戰鬥意志。[例]誓師北伐、誓師典禮\n2.泛指群眾集會堅決表示完成某項重要任務的決心。[例]各界婦女團體今天集結舉行拯救雛妓的誓師大會。"]],"誕生":[["ㄉㄢˋ ㄕㄥ","1.出生。[例]每一個新生命的誕生，都是人類的另一個希望。\n2.產生。[例]由於多位科學家的苦心鑽研，這項尖端科技的新產品終於誕生了。"]],"誘惑":[["ㄧㄡˋ ㄏㄨㄛˋ","引誘迷惑。[例]他受不了金錢的誘惑，終於鋌而走險，鑄下大錯。"]],"誘敵":[["ㄧㄡˋ ㄉㄧˊ","引誘敵人。[例]為了解救同伴，他不惜現身誘敵。"]],"誘發":[["ㄧㄡˋ ㄈㄚ","1.誘導啟發。[例]美術課上，老師利用動畫和彩圖誘發學生的學習興趣。\n2.導致發生。[例]不良的社會風氣是誘發犯罪的主因之一。"]],"語文":[["ㄩˇ ㄨㄣˊ","1.語言和文字的合稱。[例]中國的語文源遠流長，值得深入研究。\n2.泛指與語言或文字有關的事項。[例]語文競賽"]],"誠實":[["ㄔㄥˊ ㄕˊ","真實而不虛假。[例]老師常常告訴我們要做一個誠實的小孩。"]],"誠懇":[["ㄔㄥˊ ㄎㄣˇ","真實而懇切。[例]他講話實在、做人誠懇，大家都對他十分信賴。"]],"誣告":[["ㄨ ㄍㄠˋ","偽造、變造證據或妄言指控，意圖使無罪者受到刑事或懲戒的處分。[例]他是誣告，我絕對沒做過這種事。"]],"誤導":[["ㄨˋ ㄉㄠˇ","錯誤的導引。[例]受了他的誤導，我才白白損失了那些錢。"]],"誤差":[["ㄨˋ ㄔㄚ","1.近似值和準確值之間的差數。可以反映實驗、測量等結果的準確程度。[例]絕對誤差、相對誤差\n2.敘述的內容和事實真相之間的差距。[例]據我所知，他說的和事實誤差很大。"]],"誤解":[["ㄨˋ ㄐㄧㄝˇ","1.理解、判斷錯誤。[例]我原本是番好意，想不到他卻誤解了我的意思。_x000D_\n2.不正確的看法、見解。[例]決策單位決定對外公布公司的營運狀況，以消除外界的諸多誤解。"]],"誤點":[["ㄨˋ ㄉㄧㄢˇ","延誤規定的時間。[例]由於火車誤點，使我抵達目的地時已較預定的時間晚了許多。"]],"誦讀":[["ㄙㄨㄥˋ ㄉㄨˊ","朗讀。[例]老師將同學的佳作大聲誦讀，讓大家欣賞。"]],"說明":[["ㄕㄨㄛ ㄇㄧㄥˊ","1.用言語或文字解釋明白。[例]舉淺顯的例子來說明，比較容易了解。\n2.解釋的言語或文字。[例]詳細閱讀了照相機所附的說明，才知道如何操作。"]],"說服":[["ㄕㄨㄟˋ ㄈㄨˊ","以言詞遊說，使人接受其意見。[例]他終於說服眾人，支持這項政策。"]],"說法":[["ㄕㄨㄛ ㄈㄚˇ","1.措辭。[例]同樣是要人家幫你做事情，說法應該婉轉一點。\n2.看法、見解。[例]這種說法太主觀，令人難以接受。\n3.宣講佛法。[例]現身說法"]],"說話":[["ㄕㄨㄛ ㄏㄨㄚˋ","1.發言、講話。[例]她說話時總是輕聲細語，非常溫柔。\n\t\n2.指責、挑剔。[例]這種兩面不討好的事，你做得再好，還是有人會說話。\n\t\n3.國民小學國語科教學項目之一。[例]今天的說話課，老師讓大家上臺作自我介紹。"]],"說謊":[["ㄕㄨㄛ ㄏㄨㄤˇ","說假話騙人。[例]做個誠實的孩子，不要說謊。"]],"課堂":[["ㄎㄜˋ ㄊㄤˊ","教室。泛稱進行教學活動的場所。[例]老師在課堂上播放海洋生物紀錄片，讓同學們對海陸動物的差異性有了更深入地了解。"]],"課文":[["ㄎㄜˋ ㄨㄣˊ","教科書的內容正文。[例]今天的家庭作業是把第三課的課文抄寫一遍。"]],"課本":[["ㄎㄜˋ ㄅㄣˇ","教科書。[例]老師要同學打開課本，準備上課。"]],"課業":[["ㄎㄜˋ ㄧㄝˋ","學業。[例]如何有效調適課業壓力，是自我成長的重要課題。"]],"調侃":[["ㄊㄧㄠˊ ㄎㄢˇ","揶揄、嘲諷、挖苦。[例]他已經很不好意思了，大家就別再調侃他了。"]],"調劑":[["ㄊㄧㄠˊ ㄐㄧˋ","調適、調整。[例]旅行可以調劑身心。"]],"調味":[["ㄊㄧㄠˊ ㄨㄟˋ","調理食物的滋味。[例]他精擅調味，常喜烹煮佳餚。"]],"調和":[["ㄊㄧㄠˊ ㄏㄜˊ","1.烹調五味。[例]廚師善於調和五味，烹飪佳餚。_x000D_\n2.和諧、融洽。[例]這幅水彩畫的顏色相當調和，不愧是大師的名作。_x000D_\n3.協調處理。[例]陰陽調和_x000D_\n4.排解紛爭。[例]他們倆人爭執不休，你還是居中調和調和吧！"]],"調子":[["ㄉㄧㄠˋ ˙ㄗ","1.音調，音樂中表示所用音階高低的程度。如Ｃ大調、Ｄ大調等。\n2.說話時所持有的態度、語氣。[例]他說話的調子相當溫和。"]],"調換":[["ㄉㄧㄠˋ ㄏㄨㄢˋ","更換。[例]調換座位"]],"調整":[["ㄊㄧㄠˊ ㄓㄥˇ","調理整頓人事物的現況。如人事異動、改變習慣，改訂價格等。[例]老師要我們在考前調整睡眠時間，不要繼續熬夜。"]],"調查":[["ㄉㄧㄠˋ ㄔㄚˊ","為了解實況所作的查訪。[例]調查戶口、問卷調查"]],"調皮":[["ㄊㄧㄠˊ ㄆㄧˊ","頑皮淘氣。[例]調皮的孩子並不一定是壞孩子。"]],"調色盤":[["ㄊㄧㄠˊ ㄙㄜˋ ㄆㄢˊ","一種可以調配顏料，使其混合均勻的繪畫器具。[例]他手拿調色盤，將眼前的美景細細繪下。"]],"調解":[["ㄊㄧㄠˊ ㄐㄧㄝˇ","法律上指法院就爭執的事件，勸諭雙方平息爭端，庭外和解，避免訴訟行為。後泛指調停各方意見，平息紛爭。[例]地方公正人士居中調解之後，雙方宿怨終得化解。"]],"調課":[["ㄉㄧㄠˋ ㄎㄜˋ","調換上課時間。[例]王老師因個人的因素常常調課，學生們感到非常不便。"]],"諂媚":[["ㄔㄢˇ ㄇㄟˋ","逢迎巴結。[例]他因為慣於向上司諂媚而遭同事唾棄。"]],"諄諄教誨":[["ㄓㄨㄣ ㄓㄨㄣ ㄐㄧㄠˋ ㄏㄨㄟˋ","懇切耐心的教導。[例]老師的諄諄教誨，使我們獲益良多。"]],"談吐":[["ㄊㄢˊ ㄊㄨˇ","談話時的態度和措詞。[例]她談吐高雅，儀態大方。"]],"談天說地":[["ㄊㄢˊ ㄊㄧㄢ ㄕㄨㄛ ㄉㄧˋ","1.上自天文，下至地理，無所不談。[例]張先生的學問相當淵博，每逢他演講，總是談天說地，旁徵博引，而且妙語如珠，令人讚嘆不已。\n2.比喻漫無邊際的高談闊論。[例]假日時我們全家人喜歡聚在一起談天說地，交換彼此的生活經驗。"]],"談心":[["ㄊㄢˊ ㄒㄧㄣ","談論心事、說內心的話。[例]昨晚與老友重溫舊夢，徹夜促膝談心，就像回到大學時代一樣。"]],"談論":[["ㄊㄢˊ ㄌㄨㄣˋ","言談議論。[例]他器識弘遠，經常談論國家大事。"]],"請假":[["ㄑㄧㄥˇ ㄐㄧㄚˋ","請求休假，指因公務、生病或私事而告假。[例]他染上重感冒，請假一天在家休養。"]],"請問":[["ㄑㄧㄥˇ ㄨㄣˋ","對人有所詢問的敬詞。[例]請問貴姓大名？"]],"請客":[["ㄑㄧㄥˇ ㄎㄜˋ","宴請賓客。[例]大哥決定公證結婚，不請客也不收禮。"]],"請託":[["ㄑㄧㄥˇ ㄊㄨㄛ","以某事相託付。[例]他因家中有事，於是請託同事為他處理手邊未完成的工作。"]],"諒解":[["ㄌㄧㄤˋ ㄐㄧㄝˇ","了解實情而原諒。[例]別人無心的過失，我們應該諒解而不與之計較。"]],"論孟":[["ㄌㄨㄣˊ ㄇㄥˋ","《論語》、《孟子》二書的簡稱。[例]四書除了論孟外，還包括《大學》、《中庸》。"]],"論語":[["ㄌㄨㄣˊ ㄩˇ","書名。孔子應答弟子、時人及弟子相互問答之言，由孔門後學記錄而成的書。原有《魯論》、《齊論》、《古論》三種，《齊論》、《古論》已亡失很久，現在的《論語》就是《魯論》，有二十篇。宋時朱熹合《大學》、《中庸》、《孟子》為四書。[例]有人說讀通半部《論語》可以治天下。"]],"論調":[["ㄌㄨㄣˋ ㄉㄧㄠˋ","討論時所持的理由、意見。[例]對於這件事情的處理方式，大家都持不同的論調，無法取得共識。"]],"諦聽":[["ㄉㄧˋ ㄊㄧㄥ","仔細的聽。[例]清晨諦聽林間的鳥語，是人生的一大樂事。"]],"諧音":[["ㄒㄧㄝˊ ㄧㄣ","字詞的音相同或相近。如生命線的電話是505-9595，其中9595即是「救我！救我！」的諧音。"]],"諷刺":[["ㄈㄥˋ ㄘˋ","以隱微的方式嘲諷譏刺。[例]這部電影旨在諷刺社會的病態。"]],"諸位":[["ㄓㄨ ㄨㄟˋ","各位。[例]諸位好友、諸位同志、在座諸位"]],"諸侯":[["ㄓㄨ ㄏㄡˊ","封建時代列國的國君。[例]苟全性命於亂世，不求聞達於諸侯。（《文選．諸葛亮．出師表》）"]],"諺語":[["ㄧㄢˋ ㄩˇ","民間流傳的俗語。句形簡短、音調和諧。如「聰明一世，糊塗一時」。[例]諺語雖是精簡的句子，但卻是古人長遠累積的智慧。"]],"謀殺":[["ㄇㄡˊ ㄕㄚ","設計殺人。[例]謀殺是偵探小說中常見的情節。"]],"謊言":[["ㄏㄨㄤˇ ㄧㄢˊ","不實在的話。[例]謊言遲早會被拆穿，何不現在就實話實說？"]],"謎團":[["ㄇㄧˊ ㄊㄨㄢˊ","比喻事物隱晦不清，讓人難以明白、理解。[例]這件命案調查至今已近一年，仍是謎團重重。"]],"謎底":[["ㄇㄧˊ ㄉㄧˇ","1.謎語的答案。[例]這個謎語的謎底是一種家庭電器，大家再想一想。\n2.比喻事物的真相。[例]誰將獲得本屆文藝創作新人獎的謎底，將在明天揭曉。"]],"謎語":[["ㄇㄧˊ ㄩˇ","影射事物或文字，供人猜測的隱語。如人在草木中射「茶」、炎黃子孫射「龍的傳人」。"]],"謎題":[["ㄇㄧˊ ㄊㄧˊ","1.謎語的題目。[例]今年的猜謎比賽，將由他負責出謎題。\n2.形容事物難以理解。[例]這個案件是一道難解的謎題，局長已經下令成立專案小組審理。"]],"謙讓":[["ㄑㄧㄢ ㄖㄤˋ","謙虛退讓。[例]他自覺能力不足，所以對這個職位再三謙讓。"]],"講解":[["ㄐㄧㄤˇ ㄐㄧㄝˇ","解說分析。[例]老師針對同學們所提出的問題，一一為大家講解。"]],"講評":[["ㄐㄧㄤˇ ㄆㄧㄥˊ","講解評論。[例]聽完評審的講評之後，他才知道自己演講的優缺點。"]],"謠言":[["ㄧㄠˊ ㄧㄢˊ","虛構不實的傳聞。[例]聰明的人絕不聽信謠言。"]],"謬誤":[["ㄇㄧㄡˋ ㄨˋ","錯誤。[例]這篇文章中的謬誤甚多，請加以修正。"]],"謬論":[["ㄇㄧㄡˋ ㄌㄨㄣˋ","荒唐錯誤的言論。[例]請不要再用這種似是而非的謬論來欺瞞大家了。"]],"謹守":[["ㄐㄧㄣˇ ㄕㄡˇ","謹慎、小心的遵守。[例]謹守訓示、謹守諾言"]],"謹慎":[["ㄐㄧㄣˇ ㄕㄣˋ","仔細慎重。[例]公司決定派個謹慎的老手，負責這批產品品管的查驗工作。"]],"謹言慎行":[["ㄐㄧㄣˇ ㄧㄢˊ ㄕㄣˋ ㄒㄧㄥˊ","指言談小心，行事謹慎。語本《禮記．緇衣》。[例]為人處事要謹言慎行，才能避免招惹不必要的麻煩。"]],"謹記":[["ㄐㄧㄣˇ ㄐㄧˋ","1.恭謹牢記。[例]謹記教訓\n2.恭敬慎重的寫下。[例]他上課很用心，老師所提示的重點，他都一一謹記。"]],"證據":[["ㄓㄥˋ ㄐㄩˋ","證明事實的憑據。[例]沒有證據，千萬不能隨便誣賴人。"]],"證明":[["ㄓㄥˋ ㄇㄧㄥˊ","1.以憑據表明事實。[例]他的身分經證明無誤後，方獲准進場。\n2.可供核驗事實的憑證。[例]保險人可以憑醫院開立的診斷書作為證明，以領取保險給付。"]],"證書":[["ㄓㄥˋ ㄕㄨ","作為證明的文件。[例]畢業證書、結婚證書"]],"譏諷":[["ㄐㄧ ㄈㄥˋ","譏笑諷刺。[例]這篇文章對投機取巧的政客極盡譏諷之能事。"]],"識破":[["ㄕˋ ㄆㄛˋ","識出、看穿。[例]那幾個金光黨才剛施展騙錢的一貫技倆時，就馬上為人所識破。"]],"警備":[["ㄐㄧㄥˇ ㄅㄟˋ","警戒防備。[例]公司現有的人力不足以應付警備工作，必須再增加人手。"]],"警察":[["ㄐㄧㄥˇ ㄔㄚˊ","依法以維持公共秩序、保護社會安寧、促進人民福利為主要任務的人。[例]警察打擊犯罪，保護民眾安全，可說是人民的保母。"]],"警惕":[["ㄐㄧㄥˇ ㄊㄧˋ","對可能發生的情況，心生警覺而加以戒備。[例]學校播放反毒影片，以警惕同學勿受毒品誘惑。"]],"警覺":[["ㄐㄧㄥˇ ㄐㄩㄝˊ","1.對自身的反省、覺悟。[例]他警覺到專業知識的不足，於是決定再繼續進修。\n2.對於危險或情況變化的敏銳感覺。[例]我們對於身旁的陌生人，應隨時提高警覺。"]],"譬喻":[["ㄆㄧˋ ㄩˋ","一種借彼喻此的修辭法。凡二件或二件以上的事物中有類似之點，說話作文時運用有類似點的事物，來比方說明這件事物的方法。可以利用舊經驗引起對新事物的認識。如宋．周敦頤〈愛蓮說〉中「菊，花之隱逸者也。」一句，用「隱逸者」來譬喻「菊」。"]],"譯本":[["ㄧˋ ㄅㄣˇ","將一種語言寫成的書籍翻譯成另一種語言後，所得的版本。[例]這部文學鉅著已有數十種譯本，在世界各國發行。"]],"譯者":[["ㄧˋ ㄓㄜˇ","翻譯文字著作、語言、手語的人。[例]譯者對文字的掌握能力常會影響譯作的水準。"]],"議論":[["ㄧˋ ㄌㄨㄣˋ","1.批評討論。[例]他的霸道作風，引起周遭的議論。\n2.見解、說法。[例]聽了你一番議論，我決定打消去意。"]],"議題":[["ㄧˋ ㄊㄧˊ","會議中討論的題目。[例]主席要求代表就議題發言，不要拖延時間。"]],"護照":[["ㄏㄨˋ ㄓㄠˋ","官員或國民出國時，政府所發給的證件。可證明其國籍身分，請求外國官署保護，並申請准予居留或通行。一般分為外交護照、公務護照和普通護照。[例]本國人士必須持有外交部簽發的護照才能出國旅行。"]],"護理":[["ㄏㄨˋ ㄌㄧˇ","一種醫療保健工作。主要為照顧傷患及預防保健等。[例]護理學校、居家護理"]],"護衛":[["ㄏㄨˋ ㄨㄟˋ","1.保護防衛。[例]這家私人銀行有保全人員二十四小時全天候護衛。\n2.奉派伴隨或保護重要人物的人員或衛隊。[例]身為總統的貼身護衛，凡事都要機警，小心應付。"]],"護駕":[["ㄏㄨˋ ㄐㄧㄚˋ","本指保護皇帝，後亦泛指保護特定對象。[例]從前皇帝出巡時，身旁總要有大批侍衛護駕。"]],"讀書":[["ㄉㄨˊ ㄕㄨ","閱讀書籍。[例]他的嗜好是讀書，所以常逛書店買書。"]],"變化":[["ㄅㄧㄢˋ ㄏㄨㄚˋ","事物的性質或形態有所改變。[例]變化無窮、化學變化"]],"變化多端":[["ㄅㄧㄢˋ ㄏㄨㄚˋ ㄉㄨㄛ ㄉㄨㄢ","變化繁多，難以預測。[例]中國菜的作法真是變化多端，除煎、煮、烤、炸以外，還可清蒸。"]],"變幻莫測":[["ㄅㄧㄢˋ ㄏㄨㄢˋ ㄇㄛˋ ㄘㄜˋ","變化多端，不可預測。[例]武俠小說裡的人物幾乎都有變幻莫測的高強武功。"]],"變成":[["ㄅㄧㄢˋ ㄔㄥˊ","由某一種形態轉換成另一種形態。[例]深秋時節，楓葉變成了紅色。"]],"變故":[["ㄅㄧㄢˋ ㄍㄨˋ","意外發生的災難、事故。[例]他自遭逢這次變故後，變得很憔悴。"]],"變本加厲":[["ㄅㄧㄢˋ ㄅㄣˇ ㄐㄧㄚ ㄌㄧˋ","比喻改變原有的狀況且更加嚴重。語本南朝梁．蕭統〈文選序〉。[例]他不但蹺課，最近更變本加厲，偷錢逃家了。"]],"變遷":[["ㄅㄧㄢˋ ㄑㄧㄢ","事物的變化、改移。[例]世事的變遷常令人有滄海桑田的感覺。"]],"讚不絕口":[["ㄗㄢˋ ㄅㄨˋ ㄐㄩㄝˊ ㄎㄡˇ","口中不停的稱讚。[例]客人們對媽媽烹調的菜餚讚不絕口。"]],"讚嘆":[["ㄗㄢˋ ㄊㄢˋ","讚美、驚嘆。[例]面對尼加拉瀑布的壯麗景觀，我不禁讚嘆大自然的奧妙神奇。"]],"讚揚":[["ㄗㄢˋ ㄧㄤˊ","讚美、宣揚他人的行為或長處。[例]校長讚揚孝行楷模的孝順行止，並希望全校師生能起而效倣。"]],"讚美":[["ㄗㄢˋ ㄇㄟˇ","稱揚別人的長處或美德。[例]老師在全班同學的面前，讚美小明拾金不昧的誠實行為。"]],"讚譽":[["ㄗㄢˋ ㄩˋ","讚美稱譽。[例]這件宋代玉器雕刻令與會的鑑賞專家讚譽不絕。"]],"讚賞":[["ㄗㄢˋ ㄕㄤˇ","欣賞、讚美。[例]這件作品，獲得大部分評審委員的讚賞，而得到比賽的第一名。"]],"谷底":[["ㄍㄨˇ ㄉㄧˇ","1.山谷的底部。[例]谷底有一條清澈的小溪，最適宜人們垂釣、戲水。\n2.比喻事物的底限。[例]由於這次緋聞，使他在政界的聲望跌到谷底。"]],"豁然開朗":[["ㄏㄨㄛˋ ㄖㄢˊ ㄎㄞ ㄌㄤˇ","形容開闊明亮。[例]旭日東昇，天色豁然開朗。"]],"豆子":[["ㄉㄡˋ ˙ㄗ","豆類植物結成的實。[例]小明發現種的豆子發了芽，高興得不得了。"]],"豆漿":[["ㄉㄡˋ ㄐㄧㄤ","黃豆浸軟磨成漿汁後，去渣煮成的流質食品。[例]豆漿搭配燒餅、油條，是許多人喜愛的早餐。　△豆腐漿"]],"豎琴":[["ㄕㄨˋ ㄑㄧㄣˊ","樂器名。大型直立式的撥弦樂器。三角形框內有四十七根弦，底部有踏板，用來調音。　◎"]],"豎立":[["ㄕㄨˋ ㄌㄧˋ","物體垂直地面立起來。[例]那條道路兩旁豎立著許多電線桿。"]],"豐厚":[["ㄈㄥ ㄏㄡˋ","1.豐盛隆厚。[例]收入豐厚、豐厚獎品_x000D_\n2.富裕殷實。[例]子孫豐厚、家道豐厚"]],"豐富":[["ㄈㄥ ㄈㄨˋ","豐裕充足。[例]聽說新同事是個經驗豐富的行銷高手，對新產品的推廣應該不成問題。"]],"豐沛":[["ㄈㄥ ㄆㄟˋ","充足、充沛。[例]今年梅雨季帶來豐沛的雨量，解除了水庫缺水的危機。"]],"豐滿":[["ㄈㄥ ㄇㄢˇ","1.富足、飽滿。[例]行囊豐滿、羽毛豐滿_x000D_\n2.形容體態豐腴勻稱。"]],"豐饒":[["ㄈㄥ ㄖㄠˊ","富足、充裕。[例]物產豐饒"]],"象徵":[["ㄒㄧㄤˋ ㄓㄥ","以有形的事物來表現無形的觀念。即對抽象的觀念、情感等不直接指明，而根據理性的關聯、社會的約定，透過某種意象為媒介，間接加以陳述的表達方式。[例]國旗上的青天白日滿地紅象徵自由平等博愛。"]],"象棋":[["ㄒㄧㄤˋ ㄑㄧˊ","1.一種棋戲。兩人對下，黑棋與紅棋各有將士象或帥仕相等十六顆子，各子走法不同。棋盤由九條直線與十條橫線組成，中間畫有河界。雙方交替走子，以攻死對方的將或帥為勝。[例]下象棋可以激盪腦力，是一種很好的休閒活動。　△象戲\n2.象棋遊戲所使用的棋子。[例]這副象棋被小弟弟弄丟了兩顆棋子。"]],"象牙":[["ㄒㄧㄤˋ ㄧㄚˊ","象上顎的二根巨大門牙。可雕刻加工製成各種裝飾品或器具。[例]象牙煙斗、象牙印章"]],"豪氣":[["ㄏㄠˊ ㄑㄧˋ","豪放的氣概。[例]他行事果斷，豪氣干雲，頗有大將之風。"]],"豪爽":[["ㄏㄠˊ ㄕㄨㄤˇ","意氣豪邁而爽直。[例]他為人豪爽，朋友有難總是有求必應，鼎力相助。"]],"豬圈":[["ㄓㄨ ㄐㄩㄢˋ","1.養豬的地方。[例]豬圈裡養了幾頭豬。_x000D_\n2.比喻髒亂的居所。[例]房間要經常打掃整理，才不會成了豬圈。"]],"貝殼":[["ㄅㄟˋ ㄎㄜˊ","貝類的硬殼。可分真珠層、外殼層及稜柱層三層。一般可供玩賞或製成裝飾品。[例]到海邊撿貝殼是我們最喜歡的課餘活動。"]],"負擔":[["ㄈㄨˋ ㄉㄢ","1.承當、背負。[例]這項重要工作，我可負擔不起。\n2.所承擔的責任。[例]一個人要養育這群小孩，的確是很沉重的負擔。"]],"負荷":[["ㄈㄨˋ ㄏㄜˋ","1.擔任、承受。[例]不勝負荷、負荷重任_x000D_\n2.承載。[例]這輛卡車的負荷量是2噸。"]],"負責":[["ㄈㄨˋ ㄗㄜˊ","擔負責任。[例]他在報社負責編輯工作。"]],"財大氣粗":[["ㄘㄞˊ ㄉㄚˋ ㄑㄧˋ ㄘㄨ","財產富厚而氣質粗野。多指富者倚仗財勢蠻橫囂張。[例]那個暴發戶財大氣粗，說話蠻橫不講理。"]],"財富":[["ㄘㄞˊ ㄈㄨˋ","有價值或能滿足人類所需的物品。[例]他從商多年，累積了不少財富。"]],"財寶":[["ㄘㄞˊ ㄅㄠˇ","錢財珍寶。[例]金銀財寶"]],"財產":[["ㄘㄞˊ ㄔㄢˇ","財物和產業的總稱。[例]他膝下無子，準備死後將所有財產捐贈給慈善機構。"]],"貧富不均":[["ㄆㄧㄣˊ ㄈㄨˋ ㄅㄨˋ ㄐㄩㄣ","窮人和富人所擁有的財物，差距懸殊。[例]貧富不均，是造成社會不安定的原因之一。"]],"貧窮":[["ㄆㄧㄣˊ ㄑㄩㄥˊ","缺少錢財，生活拮据困乏。[例]李老師對於家境貧窮的學生總是特別關心愛護。"]],"貧苦":[["ㄆㄧㄣˊ ㄎㄨˇ","貧窮困苦。[例]這戶人家生活貧苦，亟待善心人士伸出援手。"]],"貧血":[["ㄆㄧㄣˊ ㄒㄧㄝˇ","血液中紅血球的數目不夠，血紅素不足或紅血球不成熟，使血液無法攜帶足夠氧氣的疾病。其症狀有臉色蒼白、容易疲勞、心跳氣短、噁心、頭痛、眩暈等。貧血通常是由於營養不良或食物中缺乏製造紅血球的原料（如鐵和蛋白質）所引起。[例]多攝食含鐵質的食物有助於預防貧血。　△貧血病"]],"貨幣":[["ㄏㄨㄛˋ ㄅㄧˋ","充當一切商品交換時的等值媒介物。為商品的價值代表，可用以購買一切商品。[例]法定貨幣、加密貨幣"]],"貨物":[["ㄏㄨㄛˋ ㄨˋ","泛指各種買賣的商品。[例]在轉運港口，常常可以看到各種貨物的裝卸。"]],"貨色":[["ㄏㄨㄛˋ ㄙㄜˋ","1.商品的種類及質料。[例]貨色齊全_x000D_\n2.比喻人品或思想言論、作品等。多含貶義。[例]這些作品都是抄襲網路貼文的貨色，沒甚麼價值。_x000D_"]],"貨車":[["ㄏㄨㄛˋ ㄔㄜ","四輪以上，以裝載及運送貨物為主的機動汽車。依噸位的大小可分為大貨車、小貨車等。[例]這家公司最近添購了幾輛貨車，想必生意做得不錯。　◎"]],"販售":[["ㄈㄢˋ ㄕㄡˋ","販賣、出售。[例]市場裡販售著各類魚肉、蔬果，可說是應有盡有。"]],"販賣":[["ㄈㄢˋ ㄇㄞˋ","買進貨品後再售出，從中賺取差價。[例]他在夜市設攤販賣飾品，收入頗為可觀。　△販售"]],"貪婪":[["ㄊㄢ ㄌㄢˊ","過度索求而無節制，不知足。[例]貪婪的人，很難有滿足的時候。"]],"貪得無厭":[["ㄊㄢ ㄉㄜˊ ㄨˊ ㄧㄢˋ","貪心不知足。[例]貪得無厭的人怎麼會了解「知足不辱」的義理呢？"]],"貪心":[["ㄊㄢ ㄒㄧㄣ","過分索求而不知足。[例]貪心會使人不辨是非，唯利是圖。"]],"貪欲":[["ㄊㄢ ㄩˋ","過度求索的欲念。[例]節制貪欲，可以使人心清如水。"]],"貪汙":[["ㄊㄢ ㄨ","利用職務上的便利，獲取非法錢財。[例]嚴懲貪汙才能弊絕風清。"]],"貫穿":[["ㄍㄨㄢˋ ㄔㄨㄢ","1.穿透、連貫。[例]這條隧道貫穿了整個山脈，可以想見工程的浩大與艱辛。\n2.學問融會貫通。[例]他的學問貫穿古今中外，深受學子們的尊崇與愛戴。"]],"貫通":[["ㄍㄨㄢˋ ㄊㄨㄥ","1.穿越、溝通。[例]這條幹道貫通整個城市，帶動了經濟的成長與繁榮。_x000D_\n2.全面透澈地領會。[例]讀書貴在能貫通活用，而非一味死記。_x000D_"]],"責任":[["ㄗㄜˊ ㄖㄣˋ","1.本分應做的事。[例]保密防諜是大家的責任。\n2.在道德或法律上，因某種行為的結果，任人評論或處分。[例]由於客戶違約，公司決定訴諸法律，追究責任。"]],"責怪":[["ㄗㄜˊ ㄍㄨㄞˋ","責備怪罪。[例]這件事不全是他的錯，責怪他之前應把事情弄清楚。"]],"責無旁貸":[["ㄗㄜˊ ㄨˊ ㄆㄤˊ ㄉㄞˋ","自己應盡的責任，沒有理由推卸給別人。[例]維護社區整潔，是居民們責無旁貸的事。"]],"責難":[["ㄗㄜˊ ㄋㄢˋ","責備、非難。[例]為了這點無心之過，他飽受同事們的責難。"]],"貴重":[["ㄍㄨㄟˋ ㄓㄨㄥˋ","珍貴重要。[例]貴重物品應該妥善保管，以免遭竊。"]],"貶低":[["ㄅㄧㄢˇ ㄉㄧ","刻意降低對人或事物的評價。[例]不要妄自菲薄，貶低自己。"]],"貶值":[["ㄅㄧㄢˇ ㄓˊ","一國貨幣的對外價值降低。[例]今日匯率市場，美元走俏，臺幣持續小幅貶值。"]],"貶抑":[["ㄅㄧㄢˇ ㄧˋ","給予不好的評價並加以冷落。[例]他雖有才華，卻處處遭人貶抑。"]],"買單":[["ㄇㄞˇ ㄉㄢ","結帳、算帳。[例]本餐廳採自助式，用餐前請先買單。"]],"買菜":[["ㄇㄞˇ ㄘㄞˋ","到市場購買魚、肉、蔬菜、水果等物品。[例]到市場買菜時，應自備購物袋，以減少塑膠製品的使用。"]],"貸款":[["ㄉㄞˋ ㄎㄨㄢˇ","1.指金融機構放款或向金融機構借款。一般要規定利率和償還日期。[例]為了購屋，他向銀行貸款。\n2.借貸的款項。[例]我的貸款數目較大，得要五年才能償清。"]],"費力":[["ㄈㄟˋ ㄌㄧˋ","耗費精力或體力。[例]登上玉山之巔，相當費力，但有征服的成就感。"]],"費勁":[["ㄈㄟˋ ㄐㄧㄥˋ","1.耗費精力。[例]寫文章是很費勁的工作。\n2.形容事情難辦。[例]這事真費勁，到今天還沒辦好。"]],"費心":[["ㄈㄟˋ ㄒㄧㄣ","1.耗用心神。[例]老師費心的為我們批改作文。\n2.請託別人或感謝別人幫忙的客氣話。[例]這件事就請您多費心了。"]],"費用":[["ㄈㄟˋ ㄩㄥˋ","開支、花費的款項。[例]家裡人口多，費用自然就大。"]],"費解":[["ㄈㄟˋ ㄐㄧㄝˇ","費盡心思仍難以了解。[例]此事錯綜複雜，令人費解。"]],"貼切":[["ㄊㄧㄝ ㄑㄧㄝˋ","密合妥當，確切。[例]用「世外桃源」來形容這個僻靜清雅的地方，真是再貼切也不過了。"]],"貼紙":[["ㄊㄧㄝ ㄓˇ","具黏性的紙張。空白的可用做便條紙，而印製有各種圖案的，則有廣告、收藏等用途。[例]小朋友大多喜歡收藏印有卡通人物的貼紙。"]],"賀年":[["ㄏㄜˋ ㄋㄧㄢˊ","慶賀新年。[例]元旦時，親朋好友頻來賀年，家中一片喜氣洋洋。"]],"資優":[["ㄗ ㄧㄡ","資質優異。[例]唯有配合完善的學習環境，才能使資優學童充分發展既有的潛力。"]],"資料":[["ㄗ ㄌㄧㄠˋ","1.可供參考或研究的材料或記錄。[例]取得第一手資料對研究問題具有很大的幫助。\n2.計算機中一切數值、記號和事實的概稱。通常指尚未加以處理者。[例]新版的套裝軟體增加了不少資料處理的功能。"]],"資格":[["ㄗ ㄍㄜˊ","1.從事某種活動或工作，所應具備的條件、身分等。[例]他一一通知符合資格的應徵者前來面試。\n2.從事某種工作或活動的經驗與資歷。[例]他是個資格很老的演員，在演藝界具有舉足輕重的地位。"]],"資源回收":[["ㄗ ㄩㄢˊ ㄏㄨㄟˊ ㄕㄡ","將已淘汰廢棄的物質再回收利用。可減少垃圾量，並可創造新資源。"]],"資質":[["ㄗ ㄓˊ","天賦的材質。[例]資質好再加上肯努力，使他能有出色的表現。"]],"賊頭賊腦":[["ㄗㄟˊ ㄊㄡˊ ㄗㄟˊ ㄋㄠˇ","形容舉動鬼鬼祟祟的樣子。[例]躲在牆邊那個人賊頭賊腦的，我們趕快去通知警衛。"]],"賜予":[["ㄙˋ ㄩˇ","賞賜給。[例]我們擁有的一切，都是上天賜予的，應該好好珍惜。"]],"賞月":[["ㄕㄤˇ ㄩㄝˋ","觀賞月色。[例]每至中秋，全家總會出外賞月，享受一下佳節的氣氛。"]],"賞識":[["ㄕㄤˇ ㄕˋ","認識別人的才能而加以讚賞、器重。[例]李先生才到公司不久即獲得經理的賞識，躍升為課長。"]],"賞賜":[["ㄕㄤˇ ㄙˋ","把財物賜予有功或地位卑幼的人。亦指賜予的財物。[例]古代領兵出征的將領在班師回朝後，大多會獲得豐厚的賞賜。"]],"賠償":[["ㄆㄟˊ ㄔㄤˊ","償還因故而使他人或團體受到的損失。[例]因公共設施不當而受傷，可申請國家賠償。"]],"賣力":[["ㄇㄞˋ ㄌㄧˋ","做事盡力。[例]他工作十分賣力，很受老闆器重。"]],"賣關子":[["ㄇㄞˋ ㄍㄨㄢ ˙ㄗ","在事情關鍵處故意賣弄玄虛，使人急欲探知。[例]嘿！別再賣關子了！趕快說吧！"]],"賦予":[["ㄈㄨˋ ㄩˇ","給與。[例]賦予生命、賦予新意"]],"質問":[["ㄓˊ ㄨㄣˋ","詰問、責問。[例]面對來自各方的質問，他從容不迫的一一解釋。"]],"質料":[["ㄓˊ ㄌㄧㄠˋ","質地、材料。[例]這件衣服的質料不錯，售價一定不低。"]],"質樸":[["ㄓˊ ㄆㄨˊ","樸實無華。[例]他個性質樸憨厚，在班上人緣頗佳。"]],"質疑":[["ㄓˊ ㄧˊ","心中懷疑而向人提出問題。[例]協調會上，民眾對於政府官員的解說，紛紛提出質疑。"]],"質詢":[["ㄓˊ ㄒㄩㄣˊ","民意代表在議會中，向政府官員提出詢問，稱為「質詢」。[例]議員在議會中針對日前市府爆發的弊案，對市長提出質詢。"]],"賺取":[["ㄓㄨㄢˋ ㄑㄩˇ","獲取錢財、利益等。[例]他利用暑假打工，賺取下學年的學費和生活費。"]],"賺錢":[["ㄓㄨㄢˋ ㄑㄧㄢˊ","1.賺取財利。[例]他們一家六口全靠他父親賺錢養家，生活非常清苦。\n2.利潤較高的。[例]婚紗攝影是門賺錢行業。"]],"購物":[["ㄍㄡˋ ㄨˋ","購買物品。[例]假日裡她最喜歡逛街購物。"]],"購買":[["ㄍㄡˋ ㄇㄞˇ","採買。[例]颱風前夕，大家紛紛購買民生用品，以備不時之需。"]],"賽車":[["ㄙㄞˋ ㄔㄜ","1.一種用於長距離競賽的車子。特色為車型輕巧、車身低、速度快。[例]比賽前，檢查賽車的工作是相當重要的。　△跑車\n2.一種體育運動。以人駕車，以車速的快慢決定勝負的運動比賽。駕駛者必須具有極機敏的反應與純熟的駕車技術。[例]賽車是項具有高危險性、刺激性的活動。"]],"贈予":[["ㄗㄥˋ ㄩˇ","贈送、給予。[例]贈予爵位"]],"贈品":[["ㄗㄥˋ ㄆㄧㄣˇ","免費給予的東西。[例]這次的抽獎活動，贈品相當豐富。"]],"贈與":[["ㄗㄥˋ ㄩˇ","贈送、給與。[例]贈與獎金"]],"贈送":[["ㄗㄥˋ ㄙㄨㄥˋ","把物品送給別人。[例]為了吸引顧客，主辦單位決定凡是到場參觀的人即贈送精美禮品。"]],"贈閱":[["ㄗㄥˋ ㄩㄝˋ","將書報或雜誌免費送給他人閱讀。[例]這些雜誌都是免費贈閱的，歡迎大家索取。"]],"贏得":[["ㄧㄥˊ ㄉㄜˊ","博得、獲取。[例]這名網球好手以精湛的球技，輕鬆的贏得冠軍。"]],"赤腳":[["ㄔˋ ㄐㄧㄠˇ","光腳，不穿鞋襪。[例]黃昏的時候，赤腳走在沙灘上，令人心曠神怡。"]],"走動":[["ㄗㄡˇ ㄉㄨㄥˋ","1.活動。[例]別老是坐著，起來走動走動。\n2.往來應酬。[例]他們兩家是世交，平日常常走動。"]],"走廊":[["ㄗㄡˇ ㄌㄤˊ","1.屋簷下可供人往來行走的通道。[例]在走廊上奔跑嬉戲會影響他人的通行。\n2.連接兩個區域的狹長地帶。如甘肅省西北部的河西走廊、中東的加薩走廊。"]],"走路":[["ㄗㄡˇ ㄌㄨˋ","1.徒步行走。[例]我每天都走路上學。\n2.開除、解聘。[例]再不好好做，老闆就要叫人走路了。"]],"走進":[["ㄗㄡˇ ㄐㄧㄣˋ","步行進入。[例]上課鐘一響，老師就走進教室，開始上課。"]],"赴任":[["ㄈㄨˋ ㄖㄣˋ","前往擔任新職。[例]林先生上個月就到省政府赴任了。"]],"起伏":[["ㄑㄧˇ ㄈㄨˊ","1.隆起和低凹。[例]這座山山勢起伏不定，道路崎嶇難行。\n2.興盛與衰落。[例]歷朝國運的盛衰起伏，往往是周而復始，循環不已。"]],"起司":[["ㄑㄧˇ ㄙ","一種從動物乳汁中凝聚出來的食品。§英cheese　△乳酪"]],"起因":[["ㄑㄧˇ ㄧㄣ","事情發生的原因。[例]警方判定電線走火是這次火災的起因。"]],"起床":[["ㄑㄧˇ ㄔㄨㄤˊ","離開床鋪。一般指睡醒後下床。[例]趕快起床，否則上學又要遲到了！"]],"起立":[["ㄑㄧˇ ㄌㄧˋ","起身站立。[例]看見老師走進來，他連忙起立致意。"]],"起跑":[["ㄑㄧˇ ㄆㄠˇ","開始奔跑。[例]這位選手才起跑不久，就一路遙遙領先其他參賽者。"]],"超人":[["ㄔㄠ ㄖㄣˊ","1.具有超越常人能力的人。[例]我又不是超人，那有可能獨自完成這麼艱鉅的工作？\n2.超越一般人。[例]這位大哲學家具有超人的智慧，總能在平凡的事物中洞澈高妙的事理。"]],"超凡入聖":[["ㄔㄠ ㄈㄢˊ ㄖㄨˋ ㄕㄥˋ","超越凡俗，而進入聖賢的境地。指修養達到極致的境界。[例]真正要做到超凡入聖，一塵不染的修養不容易。"]],"超出":[["ㄔㄠ ㄔㄨ","多出、越過。[例]這件事已經超出我的能力範圍，我根本幫不上忙。"]],"超級":[["ㄔㄠ ㄐㄧˊ","超出一般等級。[例]這支球隊是本次比賽中的超級強隊。"]],"超級市場":[["ㄔㄠ ㄐㄧˊ ㄕˋ ㄔㄤˇ","一種現代新興的自助式商店。業者將食品或日用百貨分類、包裝、標價後陳列架上，由顧客自取，再至收銀臺付款。[例]媽媽喜歡到超級市場去選購食物。　◎"]],"超越":[["ㄔㄠ ㄩㄝˋ","1.勝過。[例]他目前的成就，是後人難以超越的。\n2.越過。[例]我們超越許多障礙之後，終於到達了目的地。"]],"超車":[["ㄔㄠ ㄔㄜ","從旁超越同一車道上行駛在前的車輛。[例]這場車禍是由於超車不當而引起的。"]],"超速":[["ㄔㄠ ㄙㄨˋ","行車速度超過規定的限度。[例]十次車禍九次快，超速行駛是造成此次車禍的主因。"]],"超過":[["ㄔㄠ ㄍㄨㄛˋ","1.多於標準或勝過別的事物。[例]今年稻米的總產量已經超過去年了。\n2.過分。[例]他這次做得太超過了，難怪大家都要罵他。"]],"趕快":[["ㄍㄢˇ ㄎㄨㄞˋ","加快速度。[例]現在已經很晚了，我們趕快回家吧！"]],"趕緊":[["ㄍㄢˇ ㄐㄧㄣˇ","掌握時機，從速進行。[例]時間不早了，我們趕緊上路吧！"]],"趕路":[["ㄍㄢˇ ㄌㄨˋ","加快行進速度。[例]我們必須連夜趕路才能按時到達目的地。"]],"足夠":[["ㄗㄨˊ ㄍㄡˋ","充足、不缺乏。[例]他有足夠的能力和經驗，獨自可以完成這件工作。"]],"足球":[["ㄗㄨˊ ㄑㄧㄡˊ","1.一種球類運動。比賽的主要規則為：與賽雙方各派十一名球員出場，運用雙手以外的身體任何部分運球，以將球合法踢入對方球門次數多者為勝。[例]在所有的運動中，他最喜歡足球。　◎_x000D_\n2.足球比賽所使用的球。圓形。周長27至28英寸。開賽前的重量需為14至16盎司。[例]在比賽最後一分鐘時，他一腳將足球踢進球門，為獲得冠軍的關鍵球。"]],"足跡":[["ㄗㄨˊ ㄐㄧ","1.腳踏過的痕跡。[例]沙灘上印下我們相偕走過的足跡。\n2.行蹤所到的地方。[例]他愛好旅行，足跡遍布世界各地。"]],"跆拳道":[["ㄊㄞˊ ㄑㄩㄢˊ ㄉㄠˋ","一種武術運動。著重在腳的動作，以行、阻、閃、攔、截等動作做防衛或攻擊。功力區分為九段八級制。[例]學習跆拳道，不但可以防身，還能鍛鍊體魄。 ◎"]],"跌倒":[["ㄉㄧㄝˊ ㄉㄠˇ","失足而摔倒。[例]跌倒在地"]],"跌跤":[["ㄉㄧㄝˊ ㄐㄧㄠ","1.跌倒摔跤。[例]天雨路滑，小心別跌跤了！\n2.比喻犯錯或受挫折。[例]在人生旅途中不怕跌跤，只怕缺少再站起來的勇氣。"]],"跑步":[["ㄆㄠˇ ㄅㄨˋ","兩腳加快速度前進。[例]他每天早上六點一定在公園跑步。"]],"跑道":[["ㄆㄠˇ ㄉㄠˋ","1.專供比賽使用的道路。[例]賽車跑道、田徑跑道\n2.專供飛機起降時滑行用的道路。[例]這架飛機因機件故障，降落時滑出跑道。"]],"距離":[["ㄐㄩˋ ㄌㄧˊ","1.時間或空間、有形或無形的間隔。[例]溝通可以拉近彼此間的距離。\n2.相隔、相距。[例]他家距離車站很近，上下班通勤十分方便。"]],"跟從":[["ㄍㄣ ㄘㄨㄥˊ","跟隨追從。[例]他總是跟從在我後面。"]],"跟班":[["ㄍㄣ ㄅㄢ","隨從、貼身僕從。[例]每次媽媽逛百貨公司時，姊姊就成了義務跟班。"]],"跟隨":[["ㄍㄣ ㄙㄨㄟˊ","隨從在後。[例]他跟隨父母親一同到國外遊玩。"]],"跨欄":[["ㄎㄨㄚˋ ㄌㄢˊ","一種徑賽運動。在跑道上設置若干個欄架，欄架分高低兩種，參賽者快速奔跑並跳越欄架，以率先奔至終點者為勝。依照跑步的距離，可分為女子100公尺和400公尺，男子110公尺及400公尺等項目。運動員跨欄時，其腿或足未跨過本道欄架上方或故意以手或足撞倒任何欄架者，均取消其比賽資格。　◎"]],"路口":[["ㄌㄨˋ ㄎㄡˇ","兩條或兩條以上的道路交會處。[例]交通警察正在十字路口指揮，以保持交通的順暢。"]],"路徑":[["ㄌㄨˋ ㄐㄧㄥˋ","1.來往經過的道路。[例]為了規劃下星期的校外教學，老師提前探路，尋找理想路徑。\n2.做事的門路、方法。[例]經過多次失敗，他終於找到了成功的路徑。"]],"路燈":[["ㄌㄨˋ ㄉㄥ","設在道路旁的燈，以供夜間照明之用。[例]巷口的路燈，給晚歸的人帶來許多便利。"]],"路程":[["ㄌㄨˋ ㄔㄥˊ","兩地之間的距離。[例]這一趟出門，路程遙遠，一路上要多小心！"]],"路線":[["ㄌㄨˋ ㄒㄧㄢˋ","1.既定的路徑。[例]登山路線、公車路線\n2.比喻途徑、方法。[例]他向來堅持溫和、理性的政治路線，絕對不採激烈抗爭。"]],"路途":[["ㄌㄨˋ ㄊㄨˊ","路程。[例]路途遙遠"]],"路障":[["ㄌㄨˋ ㄓㄤˋ","放置在道路或道路旁，用以阻止車輛或行人通行的障礙物。[例]前方橋上發生嚴重交通事故，警方設置路障，禁止車輛通行。"]],"跳棋":[["ㄊㄧㄠˋ ㄑㄧˊ","一種棋類遊戲。由二至三人在六角星形的棋盤上布棋。每人各據一方，以間隔跳越的方式，先把棋子全部移至對面的一方就獲勝。[例]他是跳棋好手，每次都讓對手輸得心服口服。"]],"跳繩":[["ㄊㄧㄠˋ ㄕㄥˊ","1.一種民俗體育運動。為一種跳越繩子的運動或遊戲。通常是把繩子掄成圓圈，人趁繩子近地時跳過去。有單腳跳、雙腳跳、交叉跳、轉身跳等多種花樣。[例]花式跳繩不僅能訓練靈活的身手，同時也能考驗團隊之間的默契。\n2.繩子兩端附有手柄以便掄動，供人跳躍的繩索。[例]為了長高，他特地買了一條跳繩來勤加運動。"]],"跳舞":[["ㄊㄧㄠˋ ㄨˇ","隨著音樂的節奏舞蹈。[例]幼稚園的小朋友每天唱歌跳舞，好不愉快！"]],"跳躍":[["ㄊㄧㄠˋ ㄩㄝˋ","跳起來。[例]成群的袋鼠在寬闊的草原上跳躍著。"]],"跳高":[["ㄊㄧㄠˋ ㄍㄠ","一種田賽運動。分急行跳高、撐竿跳高及立定跳高三種。現在稱跳高通常指急行跳高。運動員經一段距離助跑加速後，單腳起跳，身體凌越橫竿，橫竿未掉落即屬成功，並繼續提升高度。若同一高度失敗三次，即喪失繼續參加比賽的資格。[例]十分鐘後將進行跳高總決賽，選手請到司令臺前報到。　◎"]],"踏實":[["ㄊㄚˋ ㄕˊ","切實認真。[例]做事要踏實，不可心存僥倖，才能有所成就。"]],"踝骨":[["ㄏㄨㄞˊ ㄍㄨˇ","小腿和腳掌連接處左右兩旁凸起的圓骨。[例]他因為踝骨受傷而行動不便，只好請假在家休養。"]],"踢球":[["ㄊㄧ ㄑㄧㄡˊ","以腳觸擊球。[例]每逢假日，我們一夥人總是在足球場上踢球。"]],"踢腿":[["ㄊㄧ ㄊㄨㄟˇ","抬腿向外踢。[例]他一踢腿，就把門踹開了。"]],"踩踏":[["ㄘㄞˇ ㄊㄚˋ","踐踏。[例]維護公園的景觀，請勿踩踏草坪。"]],"踴躍":[["ㄩㄥˇ ㄩㄝˋ","反應熱烈，樂於從事。[例]這次報名參加登山活動的人十分踴躍。"]],"蹣跚":[["ㄇㄢˊ ㄕㄢ","形容步伐不穩、歪歪斜斜的樣子。[例]老王那蹣跚的身影，總是令人想起他不幸的遭遇。"]],"蹤影":[["ㄗㄨㄥ ㄧㄥˇ","蹤跡與形影。[例]他走得很快，一下子便不見蹤影了。"]],"蹤跡":[["ㄗㄨㄥ ㄐㄧ","足跡、形蹤。[例]警方派出大批人馬協助尋找生還者的蹤跡。"]],"蹦蹦跳跳":[["ㄅㄥˋ ㄅㄥˋ ㄊㄧㄠˋ ㄊㄧㄠˋ","形容跳躍的樣子。[例]這孩子很活潑，成天蹦蹦跳跳的。"]],"躍躍欲試":[["ㄩㄝˋ ㄩㄝˋ ㄩˋ ㄕˋ","心動技癢，急切的想嘗試一下。[例]比賽尚未鳴槍開始，選手們個個躍躍欲試，準備一決高下。"]],"躡手躡腳":[["ㄋㄧㄝˋ ㄕㄡˇ ㄋㄧㄝˋ ㄐㄧㄠˇ","放輕手腳走路、行動小心而不敢聲張的樣子。[例]他回家後躡手躡腳的進到房間，以免吵醒已經入睡的父母。　◎"]],"身分":[["ㄕㄣ ㄈㄣˋ","人的出身、資格或在社會上的地位。[例]身分不明、身分卑微、暴露身分"]],"身影":[["ㄕㄣ ㄧㄥˇ","形體的影像。[例]他的腦海中浮現了外婆的身影。"]],"身懷絕技":[["ㄕㄣ ㄏㄨㄞˊ ㄐㄩㄝˊ ㄐㄧˋ","具有獨特的技藝。[例]這部武俠片的主角，個個都是身懷絕技、功夫了得的武林高手。"]],"身材":[["ㄕㄣ ㄘㄞˊ","體態、體型。[例]身材健美、身材高大、身材苗條"]],"身軀":[["ㄕㄣ ㄑㄩ","身材、身體。[例]身軀高大、身軀肥碩"]],"身體":[["ㄕㄣ ㄊㄧˇ","人的軀體。[例]身體健康、身體殘缺"]],"身高":[["ㄕㄣ ㄍㄠ","身體的高度。[例]他身高一百七十公分，剛好符合錄取標準。"]],"躬親":[["ㄍㄨㄥ ㄑㄧㄣ","親自去做。[例]他不放心把事情交給別人做，只好事事躬親。"]],"躬身":[["ㄍㄨㄥ ㄕㄣ","彎曲身體表示恭敬。[例]聽完將軍的指示後，他躬身應是。"]],"躲藏":[["ㄉㄨㄛˇ ㄘㄤˊ","躲避隱藏。[例]歹徒雖然狡猾的躲藏在山區裡，最後仍為警方所逮捕。"]],"躲避":[["ㄉㄨㄛˇ ㄅㄧˋ","隱藏逃避。[例]他為了躲避記者的採訪，幾天來不曾返家。"]],"躺下":[["ㄊㄤˇ ㄒㄧㄚˋ","身體向後平倒下來。[例]你的病才剛好，不要太過操勞，累了就躺下休息吧！"]],"車主":[["ㄔㄜ ㄓㄨˇ","車子的擁有者。[例]警察查獲這批贓車後，已通知車主們領回。"]],"車廂":[["ㄔㄜ ㄒㄧㄤ","車輛上用來搭載乘客或裝運貨物的車身部分。[例]本列車的所有車廂內全面禁止吸煙。"]],"車牌":[["ㄔㄜ ㄆㄞˊ","汽、機車經登記、檢驗合格後，發給車主掛於車前或車後的長方型號碼牌。[例]車牌就好像是一輛車的身分證。"]],"車票":[["ㄔㄜ ㄆㄧㄠˋ","乘車所需的票券憑證。[例]請各位乘客拿出車票，以便列車長驗票。"]],"車站":[["ㄔㄜ ㄓㄢˋ","可停靠車輛，供客、貨上下的固定地點。[例]火車站、公車站"]],"車頭":[["ㄔㄜ ㄊㄡˊ","1.車輛的前端部分。相對於車尾而言。[例]這場車禍使他車子的車頭全毀。_x000D_\n2.牽引拖車的機械車裝置。[例]貨車車頭_x000D_\n3.→火車頭"]],"軋鋼":[["ㄧㄚˋ ㄍㄤ","將鋼坯壓成一定形狀的鋼材。[例]軋鋼的家具比較耐用。"]],"軌道":[["ㄍㄨㄟˇ ㄉㄠˋ","1.供捷運、火車、高鐵等交通工具行駛的鐵軌。[例]定期維修軌道，才能確保行車安全。\n2.物質運動時所循的路徑。如天體、人造衛星、太空船等運行的路徑。[例]這次發射的人造衛星，已經順利進入軌道運行。　◎"]],"軍人":[["ㄐㄩㄣ ㄖㄣˊ","凡有軍籍的人，不論官兵，均稱為「軍人」。[例]保衛疆土是軍人最重要的職責。"]],"軍服":[["ㄐㄩㄣ ㄈㄨˊ","軍人的制服。[例]三軍健兒穿著整齊的軍服，精神抖擻的參加閱兵大典。"]],"軍機":[["ㄐㄩㄣ ㄐㄧ","1.軍事機密。[例]嚴防軍機洩露才能確保國家及人民的安全。_x000D_\n2.軍用飛機。[例]飛行軍官駕著軍機巡視領空。"]],"軍糧":[["ㄐㄩㄣ ㄌㄧㄤˊ","軍隊的糧食。[例]雙方開始大量儲備軍糧和武器，準備打一場持久戰。"]],"軒昂":[["ㄒㄩㄢ ㄤˊ","意態不凡的樣子。[例]氣宇軒昂、像貌軒昂、動止軒昂"]],"軒輊":[["ㄒㄩㄢ ㄓˋ","軒，車前高起的部分。輊，車後較低的部分。軒輊，比喻高低優劣。[例]不分軒輊"]],"軟木塞":[["ㄖㄨㄢˇ ㄇㄨˋ ㄙㄞ","用栓皮櫟之類的樹皮製成的木塞，可做瓶塞。"]],"軟糖":[["ㄖㄨㄢˇ ㄊㄤˊ","質軟的糖果。[例]水果軟糖、牛奶軟糖"]],"軼事":[["ㄧˋ ㄕˋ","正史上沒有記載的或已散失的零星故事。[例]中國民間流傳著許多有關蘇軾的軼事，頗富趣味。"]],"軼聞":[["ㄧˋ ㄨㄣˊ","不見於正式記載的雜談瑣聞。[例]他說了許多軼聞趣事為她解悶。"]],"較量":[["ㄐㄧㄠˋ ㄌㄧㄤˋ","比較優劣高下。[例]他倆都自認為棋藝高超，即將在這次比賽中較量一番。"]],"載歌載舞":[["ㄗㄞˋ ㄍㄜ ㄗㄞˋ ㄨˇ","邊唱歌，邊跳舞。[例]今晚的晚會節目非常精彩，表演者載歌載舞，觀眾掌聲不斷。"]],"載貨":[["ㄗㄞˋ ㄏㄨㄛˋ","載運貨物。[例]這輛廂型車空間大，用來載貨或全家出遊都很方便。"]],"輔佐":[["ㄈㄨˇ ㄗㄨㄛˇ","輔助、佐助。[例]輔佐朝政"]],"輔助":[["ㄈㄨˇ ㄓㄨˋ","輔佐襄助。[例]輔助教材、輔助功能"]],"輔導":[["ㄈㄨˇ ㄉㄠˇ","輔助引導。[例]行為輔導、生活輔導"]],"輕巧":[["ㄑㄧㄥ ㄑㄧㄠˇ","輕便靈巧。[例]生日時，她送我一個輕巧實用的手提袋。"]],"輕快":[["ㄑㄧㄥ ㄎㄨㄞˋ","1.輕鬆愉快。[例]這首舞曲節奏輕快，令人不自禁的手舞足蹈起來。\n2.輕便快速。[例]這艘船順著風輕快的向前航行。"]],"輕易":[["ㄑㄧㄥ ㄧˋ","1.簡單容易。[例]這不是件輕易的事，大家要先有心理準備。\n2.隨便、任意。[例]受過幾次傷害後，他再也不輕易相信別人了。"]],"輕率":[["ㄑㄧㄥ ㄕㄨㄞˋ","草率不謹慎。[例]他做事輕率，常常出紕漏。"]],"輕盈":[["ㄑㄧㄥ ㄧㄥˊ","1.形容體態纖秀，動作輕快。[例]她隨著音樂輕盈起舞。\n2.輕鬆愉快。[例]遠處傳來一陣輕盈的笑語。"]],"輕而易舉":[["ㄑㄧㄥ ㄦˊ ㄧˋ ㄐㄩˇ","形容簡單容易，不費力。[例]對他而言，這件事輕而易舉，難不倒他的。"]],"輕舟":[["ㄑㄧㄥ ㄓㄡ","輕快的小船。[例]兩岸猿聲啼不住，輕舟已過萬重山。（唐．李白〈早朝發白帝城〉詩）"]],"輕輕":[["ㄑㄧㄥ ㄑㄧㄥ","1.動作細微、小心。[例]母親輕輕拍撫著小嬰兒的背，哄他入睡。_x000D_\n2.程度淺、數量少。[例]他年紀輕輕，卻已經事業有成。"]],"輕飄飄":[["ㄑㄧㄥ ㄆㄧㄠ ㄆㄧㄠ","1.形容輕柔的飄動。[例]那女子一頭烏溜溜的秀髮，輕飄飄的在海風中飄揚。\n2.形容非常輕快舒爽。[例]這些讚美的話捧得他渾身輕飄飄的。"]],"輕鬆":[["ㄑㄧㄥ ㄙㄨㄥ","1.輕快舒適。[例]考完試後，大家的心情頓時輕鬆起來。\n2.放鬆。[例]忙完工作後，我們去看場電影，輕鬆一下。\n3.簡單容易。[例]這個工作很輕鬆，相信他一定可以勝任愉快。"]],"輝映":[["ㄏㄨㄟ ㄧㄥˋ","相互映照。[例]日月潭的山光水色相互輝映，風景十分秀麗。"]],"輝煌":[["ㄏㄨㄟ ㄏㄨㄤˊ","1.光彩耀眼、燦爛奪目。[例]燈火輝煌、金碧輝煌\n2.成就顯著非凡的樣子。[例]戰果輝煌、政績輝煌"]],"輪子":[["ㄌㄨㄣˊ ˙ㄗ","車輪，俗稱為「輪子」。[例]這輛車子的輪子陷到爛泥裡，動彈不得。"]],"輪廓":[["ㄌㄨㄣˊ ㄎㄨㄛˋ","1.構成圖形、物體的外緣或主要線條。[例]在朦朧的燈光下，她臉蛋的輪廓顯得分外柔美。\n2.大概。[例]經由警方漏夜偵查，這次火災起火的原因已逐漸現出輪廓。"]],"輪流":[["ㄌㄨㄣˊ ㄌㄧㄡˊ","依次更替。[例]我們決定輪流洗碗，一起分擔家事。"]],"輪胎":[["ㄌㄨㄣˊ ㄊㄞ","安裝在車輛等交通工具車輪外圍的橡膠製品，可減緩車輛行駛間的震動。[例]這輛車的輪胎已經快磨平了，最好趕快換裝新的。　◎"]],"輪船":[["ㄌㄨㄣˊ ㄔㄨㄢˊ","泛稱藉機械力推進的船舶。早期汽船未使用螺旋槳推進器，以輪葉式推進器推動，故稱為「輪船」。[例]輪船的甲板上，擠滿觀看日出的乘客。"]],"輸贏":[["ㄕㄨ ㄧㄥˊ","勝敗。[例]他們下了三盤棋，仍然未見輸贏。"]],"輾轉":[["ㄓㄢˇ ㄓㄨㄢˇ","1.間接的。[例]這個消息是輾轉從別人那裡聽來的，不知是否真確？\n2.翻來覆去。[例]王太太因先生深夜未歸而輾轉難眠。"]],"轉交":[["ㄓㄨㄢˇ ㄐㄧㄠ","轉送遞交。[例]他託我把這本書轉交給你。"]],"轉動":[["ㄓㄨㄢˇ ㄉㄨㄥˋ","1.旋轉扭動物體。[例]轉動門把、轉動開關\n2.身體部位自主活動。[例]轉動眼球、轉動頭部\n3.繞著中心點運轉。[例]直升機的螺旋槳才剛轉動，他就頭暈了。"]],"轉告":[["ㄓㄨㄢˇ ㄍㄠˋ","輾轉傳達。[例]他託我轉告你，他臨時有事不能來了。"]],"轉圈":[["ㄓㄨㄢˋ ㄑㄩㄢ","繞著中心點旋轉。[例]這段舞蹈有許多轉圈的動作，難度較高。"]],"轉彎":[["ㄓㄨㄢˇ ㄨㄢ","順著彎曲的路線轉向。[例]在下個路口轉彎，你就會看到郵局了。"]],"轉變":[["ㄓㄨㄢˇ ㄅㄧㄢˋ","改變。[例]經過這次教訓，他的想法轉變許多。"]],"轉身":[["ㄓㄨㄢˇ ㄕㄣ","回轉身軀。[例]他把事情交代完畢後，一轉身就離開學校了。"]],"轉載":[["ㄓㄨㄢˇ ㄗㄞˋ","輾轉刊載。[例]若欲轉載此文，須先徵得作者同意。"]],"轉達":[["ㄓㄨㄢˇ ㄉㄚˊ","代為通知傳達。[例]您請放心，我一定把您的意思轉達給他。"]],"轉頭":[["ㄓㄨㄢˇ ㄊㄡˊ","回頭、調頭。[例]那小偷一看到警察來了，轉頭就跑。"]],"轟炸":[["ㄏㄨㄥ ㄓㄚˋ","1.選定目標後，自飛機上投擲炸彈進行攻擊的行動。[例]二次大戰末期，聯軍以原子彈轟炸日本廣島，結束了戰爭。\n2.持續不斷的進行干擾。[例]疲勞轟炸"]],"轟隆":[["ㄏㄨㄥ ㄌㄨㄥˊ","狀聲詞。形容打雷、爆炸、機器運轉等發出的巨大聲響。[例]工人用火藥炸開山壁，發出轟隆巨響。"]],"辛勞":[["ㄒㄧㄣ ㄌㄠˊ","辛苦勞累。[例]爸爸辛勞的工作，為的是把我們教養成人。"]],"辛勤":[["ㄒㄧㄣ ㄑㄧㄣˊ","辛苦勤勞。[例]要先辛勤的耕耘，才會有豐碩的收穫。"]],"辛苦":[["ㄒㄧㄣ ㄎㄨˇ","1.勞累困苦。[例]農夫在烈日下辛苦耕種，汗水都浸溼了衣服。\n2.請人做事的客氣話。[例]我的腳受傷無法出門辦事，辛苦你走一趟吧！\n3.見面時慰問的話。[例]你辛苦了，趕緊歇會兒吧！"]],"辣椒":[["ㄌㄚˋ ㄐㄧㄠ","植物名。茄科辣椒屬，一年或多年生草本。葉卵狀披針形、先端尖、有長柄。夏日，葉腋開花，花冠五裂，白色。果實大多呈細長形，也有心臟形、燈籠形等。　△番椒"]],"辦事":[["ㄅㄢˋ ㄕˋ","處理事情、料理事務。[例]我今天出差到花蓮辦事。"]],"辦妥":[["ㄅㄢˋ ㄊㄨㄛˇ","將事情料理妥當。[例]不要擔心！我一定會把你託付的事辦妥。"]],"辦法":[["ㄅㄢˋ ㄈㄚˇ","1.處理事務或解決問題的方法。[例]我已經想到解決這場糾紛的辦法了。\n2.規章的一種。指對某一特定事項，規定它的辦理方法，以臻完善。如人民團體選舉罷免辦法、道路交通事故處理辦法。"]],"辦理":[["ㄅㄢˋ ㄌㄧˇ","把事務加以處理。[例]上級規定的事項，我們都遵照辦理了。"]],"辨別":[["ㄅㄧㄢˋ ㄅㄧㄝˊ","判別、分別。[例]辨別是非"]],"辨析":[["ㄅㄧㄢˋ ㄒㄧ","辨別分析。[例]他的辨析能力強，表達能力卻不足。"]],"辨認":[["ㄅㄧㄢˋ ㄖㄣˋ","分辨識別。[例]辨認失物"]],"辨識":[["ㄅㄧㄢˋ ㄕˋ","辨認識別。[例]他的字跡潦草難以辨識。"]],"辭不達意":[["ㄘˊ ㄅㄨˋ ㄉㄚˊ ㄧˋ","所用的言詞無法確切表達心意。[例]他太緊張，說起話來辭不達意。"]],"辭別":[["ㄘˊ ㄅㄧㄝˊ","辭行、告別。[例]他跟我們辭別後，就坐上汽車往機場去了。"]],"辮子":[["ㄅㄧㄢˋ ˙ㄗ","用線狀物或頭髮編成的長條。[例]她把頭髮紮成一條長辮子。"]],"辯解":[["ㄅㄧㄢˋ ㄐㄧㄝˇ","解釋事實或理由。[例]他認為清者自清，所以面對別人的指責，他從不辯解。"]],"辯論":[["ㄅㄧㄢˋ ㄌㄨㄣˋ","各持不同的意見主張相互論爭。[例]他的思想敏捷，口才犀利，與人辯論，無往不利。"]],"辯護":[["ㄅㄧㄢˋ ㄏㄨˋ","1.法律上指辯護人為保護當事人的利益及權利，防禦不法或不當的指控，在口頭或文字上所做的辯白。[例]為了打贏這場官司，他請了一位名律師替他辯護。\n2.提出理由、事實來加以袒護。[例]為了怕他被罵，我費心的替他辯護。"]],"農作物":[["ㄋㄨㄥˊ ㄗㄨㄛˋ ㄨˋ","栽種在農田的植物。如糧食作物、園藝作物等。[例]長江流域的農作物以糧食作物為主。"]],"農地":[["ㄋㄨㄥˊ ㄉㄧˋ","專門用來耕種的土地。[例]這塊農地的面積很大，除了種稻外，還可種些雜糧或蔬菜。"]],"農夫":[["ㄋㄨㄥˊ ㄈㄨ","從事農業的人。[例]這些蔬菜都是農夫在田裡流汗的成果，我們不應該浪費。"]],"農會":[["ㄋㄨㄥˊ ㄏㄨㄟˋ","一種農民團體。以保障農民權益，增進農民技能，促進農業現代化，改善農民生活，發展農村經濟為目的。[例]此地的農會經常舉辦說明會來告訴農民最新的耕種知識。"]],"農田":[["ㄋㄨㄥˊ ㄊㄧㄢˊ","可供耕種的田地。[例]本村的農田以種植稻米為主。"]],"農舍":[["ㄋㄨㄥˊ ㄕㄜˋ","農村的房舍。[例]從這兒望下去，溪水蜿蜒在碧綠的田間，一幢幢的農舍，炊煙裊裊，景緻真是美極了。"]],"迅速":[["ㄒㄩㄣˋ ㄙㄨˋ","速度很快。[例]他眼明手快，動作迅速，一上公車就找到了座位。"]],"迎刃而解":[["ㄧㄥˊ ㄖㄣˋ ㄦˊ ㄐㄧㄝˇ","比喻事情很容易處理。[例]一旦困難迎刃而解，學習興趣自然就會與日俱增。"]],"迎接":[["ㄧㄥˊ ㄐㄧㄝ","向前接待。[例]只要我們外出返家，小狗總是搖尾巴迎接我們。"]],"近海":[["ㄐㄧㄣˋ ㄏㄞˇ","臨近陸地的海域。[例]他在近海處開發漁業養殖場，專門養殖高經濟的魚、貝類。"]],"近視":[["ㄐㄧㄣˋ ㄕˋ","1.醫學上指眼球的前後徑過長，使得與視軸平行進入眼中的光線焦點落於視網膜之前，造成視覺影像的模糊，而患者必須靠近物體才能看得清楚。患者可以配戴凹透鏡矯正。[例]他看電視的距離過近，時間過長，以致小小年紀就已患了近視。\n2.比喻眼光短淺。[例]短見近視之人，貪圖眼前利益，很難有大成就。"]],"近視眼":[["ㄐㄧㄣˋ ㄕˋ ㄧㄢˇ","→近視1."]],"返璞歸真":[["ㄈㄢˇ ㄆㄨˊ ㄍㄨㄟ ㄓㄣ","除去外在的一切牽絆，回復淳樸原始的自然本性。[例]在爾虞我詐的環境中處久了，大家都嚮往返璞歸真的生活。"]],"迫不及待":[["ㄆㄛˋ ㄅㄨˋ ㄐㄧˊ ㄉㄞˋ","比喻情況或時間急切，不能再等。[例]為了知道選舉結果，大家迫不及待的打開電視觀看選情報導。"]],"迫在眉睫":[["ㄆㄛˋ ㄗㄞˋ ㄇㄟˊ ㄐㄧㄝˊ","形容事情急迫。[例]這事已迫在眉睫，你怎麼還不趕快進行？"]],"迭起":[["ㄉㄧㄝˊ ㄑㄧˇ","一次又一次的出現。[例]高潮迭起"]],"迴廊":[["ㄏㄨㄟˊ ㄌㄤˊ","曲折蜿蜒的走廊。[例]小橋流水和亭閣迴廊，是中國式庭園的特色。"]],"迴旋":[["ㄏㄨㄟˊ ㄒㄩㄢˊ","旋轉、盤旋。[例]獵鷹自高空迴旋而下，撲向一隻驚慌逃竄的野兔。"]],"迴盪":[["ㄏㄨㄟˊ ㄉㄤˋ","迴旋飄浮。[例]她嘹亮的歌聲在空曠的教室中迴盪。"]],"迷失":[["ㄇㄧˊ ㄕ","迷惑而無法分辨、失去理智。[例]迷失方向、迷失本性"]],"迷宮":[["ㄇㄧˊ ㄍㄨㄥ","1.一種出路拐彎抹角，令人撲朔迷離，難辨方向與出口的建築物。[例]這個遊樂場的迷宮很複雜，一旦進去之後，就不太容易走出來。\n2.比喻令人混淆而無法釐清的態勢。[例]這個企劃案實在過於繁瑣，使我好像陷入迷宮一般茫無頭緒。"]],"迷戀":[["ㄇㄧˊ ㄌㄧㄢˋ","愛好人或事物，進而入迷難捨。[例]像他這種完全不在乎他人感受的傲慢男子，實在不值得你迷戀。"]],"迷濛":[["ㄇㄧˊ ㄇㄥˊ","形容景物朦朧不清。[例]細雨霏霏，景物迷濛。"]],"迷糊":[["ㄇㄧˊ ㄏㄨˊ","心神恍惚、不夠警醒。[例]這個人很迷糊，經常丟三落四的。"]],"追加":[["ㄓㄨㄟ ㄐㄧㄚ","法律上指將以後事件，附加於以前的事件。如條約有追加條約，預算有追加預算等。[例]這件工程的造價因為評估的錯誤而短缺經費，所以後來又追加了不少預算。"]],"追問":[["ㄓㄨㄟ ㄨㄣˋ","追究、盤問。[例]這件事情的發展我已經交代得很清楚，請別再追問了。"]],"追尋":[["ㄓㄨㄟ ㄒㄩㄣˊ","1.追求尋找。[例]我努力追尋自己的理想，從不向現實妥協。\n2.回憶往事。[例]過去甜蜜的往事，只能在記憶裡追尋了。"]],"追念":[["ㄓㄨㄟ ㄋㄧㄢˋ","回想往事。[例]大夥聚在一起追念童年往事，談笑間不免流露出歲月無情的感慨。"]],"追思":[["ㄓㄨㄟ ㄙ","追想懷念。[例]他捨身救人的英勇事蹟，留給後人無限的追思。"]],"追捕":[["ㄓㄨㄟ ㄅㄨˇ","追逐、捕捉。[例]警方出動大批的人馬追捕脫逃的犯人。"]],"追根究柢":[["ㄓㄨㄟ ㄍㄣ ㄐㄧㄡˋ ㄉㄧˇ","追查探究事物的根本。[例]他就是那個脾氣，什麼事都喜歡追根究柢。"]],"追趕":[["ㄓㄨㄟ ㄍㄢˇ","快速趕上。[例]獵犬一發現獵物，就忙著向前追趕。"]],"追蹤":[["ㄓㄨㄟ ㄗㄨㄥ","1.探查人、物的行跡。[例]為了能取得獨家新聞，記者不分晝夜追蹤這位國際巨星。\n2.做持續性的觀察。[例]醫生認為他的病還須作進一步的追蹤，才能確定是否完全治癒。"]],"追隨":[["ㄓㄨㄟ ㄙㄨㄟˊ","1.跟從、尾隨。[例]我悄悄追隨在他後面，看他到底在搞什麼把戲。\n2.仿效前人。[例]他立志追隨父親的義行，將一生奉獻給慈善事業。"]],"退步":[["ㄊㄨㄟˋ ㄅㄨˋ","1.腳步向後退。[例]小心！你再一個退步便要陷入坑洞裡了。\n2.落後。[例]他因為貪玩，成績退步很多。\n3.後退的餘地。[例]凡事先想好退步，遇到阻礙就不會有進退兩難的困擾了。"]],"退燒":[["ㄊㄨㄟˋ ㄕㄠ","1.發燒的體溫回復到正常範圍。[例]服用藥物之後，孩子逐漸退燒，病情也慢慢好轉。_x000D_\n2.狂熱的情緒降低。[例]他凡事都只是三分鐘熱度，就連對流行音樂的狂熱，也很快就退燒了。"]],"退讓":[["ㄊㄨㄟˋ ㄖㄤˋ","謙退遜讓。[例]每當遇到與人衝突時，她總是以退讓的方式化解紛爭。"]],"退避三舍":[["ㄊㄨㄟˋ ㄅㄧˋ ㄙㄢ ㄕㄜˋ","舍，古代行軍時每三十里就停下來休息；三舍指九十里。退避三舍指為避免正面衝突或因害怕而主動讓步逃避，不與對方相抗。語出《左傳．僖公二十三年》。[例]那位老師因為面貌嚴肅，上課時又嚴厲，許多學生看見他都退避三舍，唯恐被他叫住訓話。"]],"送禮":[["ㄙㄨㄥˋ ㄌㄧˇ","以財物禮品餽贈他人。[例]每逢年節，他總會親自到長輩家中送禮。"]],"逃生":[["ㄊㄠˊ ㄕㄥ","逃離危險環境以求生存。[例]這棟大廈突然著火，住戶們紛紛在慌亂中逃生。"]],"逃脫":[["ㄊㄠˊ ㄊㄨㄛ","逃離擺脫。[例]雖然警政單位布署了大量的人力，但還是被狡猾的歹徒逃脫了。"]],"逃走":[["ㄊㄠˊ ㄗㄡˇ","逃跑。[例]等警察趕到現場時，小偷早已聞風逃走了。"]],"逃跑":[["ㄊㄠˊ ㄆㄠˇ","逃亡、逃走。[例]車禍發生之後，肇事者竟駕車逃跑，棄傷患於不顧，真是泯滅天良。"]],"逃避":[["ㄊㄠˊ ㄅㄧˋ","閃躲而不敢面對事實。[例]若只是一味逃避現實而不去解決問題，這和駝鳥有什麼兩樣？"]],"逆風":[["ㄋㄧˋ ㄈㄥ","迎面對著風。[例]逆風前進"]],"逍遙":[["ㄒㄧㄠ ㄧㄠˊ","自由自在、無拘無束。[例]逍遙自在"]],"透明":[["ㄊㄡˋ ㄇㄧㄥˊ","光線可以穿過，通澈明亮。[例]房間採用透明玻璃窗，可以清楚的看到窗外的景色。"]],"透過":[["ㄊㄡˋ ㄍㄨㄛˋ","1.穿過。[例]筆墨透過紙背。\n2.經由、通過。[例]透過職業介紹所，她找到一份合適的工作。"]],"透露":[["ㄊㄡˋ ㄌㄨˋ","顯露。[例]軍方以保密為由，拒絕透露此次演習內容。"]],"逐夢":[["ㄓㄨˊ ㄇㄥˋ","追求夢想。[例]逐夢若是停留在口頭上，那終究只能是白日夢。"]],"逐漸":[["ㄓㄨˊ ㄐㄧㄢˋ","隨時間遷移而漸生變化。[例]隨著年紀的增長，他的視力也逐漸衰退。"]],"途中":[["ㄊㄨˊ ㄓㄨㄥ","路上，路途之間。[例]妹妹在回家途中遺失了鑰匙和錢包。"]],"途徑":[["ㄊㄨˊ ㄐㄧㄥˋ","1.路徑、道路。[例]這條路是本鄉對外聯絡的唯一途徑。\n2.方法、門道。[例]研究學問要懂得途徑，才能事半功倍。"]],"逗留":[["ㄉㄡˋ ㄌㄧㄡˊ","停留不前。[例]小朋友放學後不要在路上逗留，以免發生危險！"]],"逗趣":[["ㄉㄡˋ ㄑㄩˋ","有趣的、引人發笑的。[例]小丑逗趣的動作，惹得大家哈哈大笑！"]],"這些":[["ㄓㄜˋ ㄒㄧㄝ","這部分。[例]這些東西是她在折扣期間買的。"]],"這個":[["ㄓㄜˋ ˙ㄍㄜ","1.這一個。[例]這個消息有必要讓同仁們都知道。\n2.表示猶豫、思索的口頭語，無義。[例]這個……我實在不知道要如何解釋才好。"]],"這樣":[["ㄓㄜˋ ㄧㄤˋ","這般、如此。[例]這樣豐盛的大餐，不禁令人垂涎三尺。"]],"這般":[["ㄓㄜˋ ㄅㄢ","這樣、如此。[例]他自甘墮落，如今落得這般田地還能怪誰？"]],"這裡":[["ㄓㄜˋ ㄌㄧˇ","1.這個地方。[例]這裡環境清幽，很適合病人靜養。\n2.這個段落、程度。[例]故事就說到這裡暫時告一段落，欲知後情，下回分解。"]],"這麼":[["ㄓㄜˋ ˙ㄇㄜ","如此、這樣。[例]天氣這麼好，應該到郊外走走。"]],"通報":[["ㄊㄨㄥ ㄅㄠˋ","1.通知、傳達。[例]他未經通報，就魯莽闖入，立刻被門口的警衛攔阻下來。\n2.機關內將某事通告全體同仁時使用的文件。[例]這份通報請傳閱之後，貼在公告欄上。　△通告"]],"通宵":[["ㄊㄨㄥ ㄒㄧㄠ","從夜晚到天明。[例]他為了企劃案而挑燈夜戰，通宵未眠。"]],"通暢":[["ㄊㄨㄥ ㄔㄤˋ","通順沒有阻礙的。[例]這篇文章結構嚴謹，文字通暢，頗能顯現作者的功力。"]],"通曉":[["ㄊㄨㄥ ㄒㄧㄠˇ","精通明白。[例]她自幼通曉音律，不到十歲，便能吹奏十數種樂器，實在令人佩服。"]],"通知":[["ㄊㄨㄥ ㄓ","1.傳達訊息使他人知曉。[例]這家公司發出信函通知初試合格的應徵者前來面試。\n2.機關對內部單位或平行機構，所發出之洽辦或告知事情的文書。[例]開會通知已經發出去了。"]],"通訊":[["ㄊㄨㄥ ㄒㄩㄣˋ","信件、訊息或信號的傳遞。[例]颱風過後，電話的通訊不良，常有雜音干擾。"]],"通訊錄":[["ㄊㄨㄥ ㄒㄩㄣˋ ㄌㄨˋ","機關或團體所編印的成員通訊住址的冊子。[例]大部分的機關學校每年都會重新印製當年度的通訊錄給全體同仁。"]],"通通":[["ㄊㄨㄥ ㄊㄨㄥ","全部、所有的。[例]主辦單位提供了豐富的獎品，讓參與活動的民眾通通有獎。"]],"通過":[["ㄊㄨㄥ ㄍㄨㄛˋ","1.經過或穿越特定區域。[例]這條路太窄了，大型車輛根本無法通過。\n2.議案經多數表決贊成而成立。[例]此案在議會已表決通過。"]],"逛逛":[["ㄍㄨㄤˋ ㄍㄨㄤˋ","隨意走動。[例]爸爸常在假日時，帶我們去逛逛書店或看看電影。"]],"逝去":[["ㄕˋ ㄑㄩˋ","1.消失。[例]青春一旦逝去即不復返，怎能不好好把握。_x000D_\n2.死亡。[例]他終於體會到必須好好地活下去，才對得起逝去的父母。"]],"速度":[["ㄙㄨˋ ㄉㄨˋ","1.事物進行過程的快慢程度。[例]駕車經過市區，應減緩行車速度。\n2.物理學上指物體運動所行路程與所經時間的比率，含有方向及大小二義。[例]物理學上速度的量值就等於速率，速度的方向即為物體運動軌跡的切線方向。"]],"速率":[["ㄙㄨˋ ㄌㄩˋ","物理學上指物體運動的速度，僅有大小而沒有方向性。[例]以距離除以時間，可以求出物體運動的速率。"]],"造型":[["ㄗㄠˋ ㄒㄧㄥˊ","創造、設計的型態。[例]這座檯燈的造型很特別。"]],"造謠":[["ㄗㄠˋ ㄧㄠˊ","捏造不實的言辭。[例]他到處造謠生事，弄得人心惶惶，是非不明。"]],"連杯酒":[["ㄌㄧㄢˊ ㄅㄟ ㄐㄧㄡˇ","「連杯」據傳源自排灣族，以整塊木材刻成並排兩只的杯體。「連杯酒」就是用連杯所盛裝的酒，兩人合飲，用以表示愛情或友好。"]],"連篇":[["ㄌㄧㄢˊ ㄆㄧㄢ","1.一篇接著一篇。[例]連篇累牘\n2.全篇、整篇。[例]錯字連篇"]],"連綿":[["ㄌㄧㄢˊ ㄇㄧㄢˊ","連續不斷。[例]近日陰雨連綿，東西都快發霉了。"]],"連線":[["ㄌㄧㄢˊ ㄒㄧㄢˋ","1.數學上指點與點間的連結線。[例]等邊三角形的三條連線必須相等。　△連接線\n2.電子資料傳輸中，一種以處理透過通信線路交互傳送資料的操作模式。[例]現在我們透過電腦連線，來看看股市行情。\n3.將獨立的離線狀態轉成可相互傳輸的狀態。[例]現在讓我們把這兩部電腦連線，以便傳送資料。"]],"連號":[["ㄌㄧㄢˊ ㄏㄠˋ","1.號數相連。[例]這場音樂會，我買了二張連號的入場券。\n2.稱兩家以上屬於同一企業經營的商店。[例]這幾家連號商店，全是他祖父留下來的。\n3.某些外文常用的標點符號，通常用來連接複合字。如英文的radio-telescope（無線電望遠鏡）、 father-in-law（岳父）。　△連字號"]],"連詞":[["ㄌㄧㄢˊ ㄘˊ","文法上用來連接兩個或兩個以上的詞、語或句，以表示其相互關聯的詞。如「與」、「而且」、「但是」等。　△連接詞"]],"連通橋":[["ㄌㄧㄢˊ ㄊㄨㄥ ㄑㄧㄠˊ","連繫兩地或多地交通的橋梁。[例]這裡的商業大樓間設有多座連通橋，行人往來十分安全且便利。"]],"週刊":[["ㄓㄡ ㄎㄢ","每星期出版一次的刊物。[例]漫畫週刊、電視週刊、商業週刊"]],"週期":[["ㄓㄡ ㄑㄧˊ","1.物體回復到原狀態所需的時間。[例]公轉週期、自轉週期\n2.按原子序順序排列，所得性質相似的化學元素系列。[例]經由週期表，我們可以清楚看出化學元素的週期。"]],"進攻":[["ㄐㄧㄣˋ ㄍㄨㄥ","向前攻擊。[例]這座城堡戒備森嚴，要從外進攻並不容易。"]],"進步":[["ㄐㄧㄣˋ ㄅㄨˋ","逐漸往好的方面進展。[例]交通工具的進步，使得城市與城市之間的距離越來越小。"]],"進行":[["ㄐㄧㄣˋ ㄒㄧㄥˊ","1.前進、向前行進。[例]連續假期，國道部分路段車多壅塞，車輛進行速度緩慢。\n2.事情依照次序向前推動、辦理。[例]我們這個工作小組正在進行古蹟修復的工作。"]],"進諫":[["ㄐㄧㄣˋ ㄐㄧㄢˋ","以直言規勸。多用於下對上。[例]冒死進諫"]],"進階":[["ㄐㄧㄣˋ ㄐㄧㄝ","升到較高的層級。[例]這些進階課程，適合語文程度較好的學生。"]],"逼真":[["ㄅㄧ ㄓㄣ","近於真實，酷似原物。[例]他男扮女裝演得維妙維肖，逼真極了！"]],"逼迫":[["ㄅㄧ ㄆㄛˋ","催逼、強迫。[例]不要逼迫他做不願意做的事。"]],"遇上":[["ㄩˋ ㄕㄤˋ","碰到。[例]他從銀行出來的時候，不巧被債主遇上了，逼著他還錢。"]],"遇到":[["ㄩˋ ㄉㄠˋ","碰到。[例]昨天下班後，我在回家途中遇到了一位舊同事。"]],"遊客":[["ㄧㄡˊ ㄎㄜˋ","前往遊覽的人。[例]陽明山花季期間，每天都是遊客如織。"]],"遊戲":[["ㄧㄡˊ ㄒㄧˋ","1.玩耍。[例]公園裡有一群小孩在遊戲。\n2.娛樂活動。[例]記得幼年時最喜歡玩扮家家酒的遊戲。"]],"遊玩":[["ㄧㄡˊ ㄨㄢˊ","遊戲玩耍。[例]社區的公園裡有遊樂設施可供小朋友遊玩。"]],"遊艇":[["ㄧㄡˊ ㄊㄧㄥˇ","供人運動或遊樂的小艇。[例]每逢假日，他喜歡和幾個朋友乘遊艇到外海垂釣。　◎"]],"遊覽":[["ㄧㄡˊ ㄌㄢˇ","遊歷參觀。[例]此處風光明媚，來此遊覽的旅客絡繹不絕。"]],"遊說":[["ㄧㄡˊ ㄕㄨㄟˋ","以言語說動他人，使聽從自己的主張。[例]戰國時代的縱橫家以遊說見長。"]],"運動":[["ㄩㄣˋ ㄉㄨㄥˋ","1.物體處於非靜止的狀態或改變位置的現象。[例]直線運動、平面運動、等加速運動_x000D_\n2.活動筋骨，使血脈暢通，以增進身體健康。[例]天天運動，有益身心健康。_x000D_\n3.社會中有目的、有組織而規模較大的群眾活動。[例]女權運動、五四運動_x000D_\n4.遊說他人或四處奔走以求達到某種目的。[例]他們到處運動，為保護自然環境而請命。"]],"運動會":[["ㄩㄣˋ ㄉㄨㄥˋ ㄏㄨㄟˋ","體育運動競賽的集會。[例]奧林匹克運動會"]],"運用":[["ㄩㄣˋ ㄩㄥˋ","使用、應用。[例]每個人都應充分運用自己的智能去迎接人生所有的挑戰。"]],"運行":[["ㄩㄣˋ ㄒㄧㄥˊ","循一定軌跡周而復始的轉動或前進。[例]地球繞太陽運行一周需要一年的時間。"]],"遍地":[["ㄅㄧㄢˋ ㄉㄧˋ","到處、處處。[例]放眼望去，遍地繁花似錦。"]],"遍布":[["ㄅㄧㄢˋ ㄅㄨˋ","分布各處。[例]山谷裡遍布著各種奇形怪狀的石頭。"]],"過來":[["ㄍㄨㄛˋ ㄌㄞˊ","1.由他處到此處。[例]請你過來幫我整理一下東西。\n2.表示回到原來的狀態。[例]經過一天一夜的昏迷，他終於在今天早晨醒過來了。"]],"過年":[["ㄍㄨㄛˋ ㄋㄧㄢˊ","由舊的一年過渡到新的一年，通常指渡過除夕。[例]我最喜歡過年時那種熱鬧的氣氛了。"]],"過敏":[["ㄍㄨㄛˋ ㄇㄧㄣˇ","1.人體對環境中某些物質反應特別敏感而產生不適的現象。[例]藥物過敏、花粉過敏\n2.對事情過分敏感。[例]他一向神經過敏，別人的一句閒話就會使他煩惱半天。"]],"過濾":[["ㄍㄨㄛˋ ㄌㄩˋ","1.用過濾器把液體或氣體裡的殘渣或雜質除去。[例]老師用濾網將溶液加以過濾。　◎\n2.篩選、揀選。[例]警方將可能涉案的對象過濾後，只剩三個人較可疑。"]],"過程":[["ㄍㄨㄛˋ ㄔㄥˊ","事物連續變化或進行間所經過的歷程。[例]任何大事業的成功，總有一段艱苦奮鬥的過程。"]],"過錯":[["ㄍㄨㄛˋ ㄘㄨㄛˋ","過失、錯誤。[例]他到底犯了什麼過錯，惹得你如此氣憤？"]],"道歉":[["ㄉㄠˋ ㄑㄧㄢˋ","向人表示歉意。[例]他為自己的莽撞行為向她道歉，希望得到她的原諒。"]],"道聽塗說":[["ㄉㄠˋ ㄊㄧㄥ ㄊㄨˊ ㄕㄨㄛ","形容沒有經過證實、缺乏根據的話。語本《論語．陽貨》。[例]謠言止於智者，這種道聽塗說的話，何必相信？"]],"道觀":[["ㄉㄠˋ ㄍㄨㄢˋ","道士修道的場所，或道士供奉神祇的廟宇。[例]蘇州的玄妙觀，原來是一所有名的道觀。"]],"道路":[["ㄉㄠˋ ㄌㄨˋ","地面上供人車通行的路。[例]任意停車易導致道路阻塞，影響交通的通暢。"]],"違反":[["ㄨㄟˊ ㄈㄢˇ","違背、不遵守。[例]小明違反校規，因此被記小過一次。"]],"違建":[["ㄨㄟˊ ㄐㄧㄢˋ","違反建築法規定而擅自建造的建築物。[例]警方正加強取締違建，以維護公共安全。"]],"違法":[["ㄨㄟˊ ㄈㄚˇ","不守法，違背法律的規定。[例]挪用公款是違法的行為。"]],"違背":[["ㄨㄟˊ ㄅㄟˋ","違反、不遵守。[例]他因違背長官的命令而遭處分。"]],"違逆":[["ㄨㄟˊ ㄋㄧˋ","違背忤逆。[例]他違逆長上，做出了令父母傷心的事。"]],"遙不可及":[["ㄧㄠˊ ㄅㄨˋ ㄎㄜˇ ㄐㄧˊ","距離遙遠無法到達或形容沒有希望。[例]科技的日新月異，使得人類探索宇宙的夢想不再是遙不可及了。"]],"遙遠":[["ㄧㄠˊ ㄩㄢˇ","形容時、空的距離很長遠。[例]唐三藏一行人不畏艱難，到遙遠的西方取經。"]],"遛狗":[["ㄌㄧㄡˋ ㄍㄡˇ","帶狗散步，使其舒活筋骨。[例]黃昏時，公園裡到處是遛狗的人。　△蹓狗"]],"遞增":[["ㄉㄧˋ ㄗㄥ","順次增加。[例]受到學生人數遞增的影響，學校正計劃擴建教室及添購教學設備。"]],"遞補":[["ㄉㄧˋ ㄅㄨˇ","順次補缺。[例]本會的理事出缺了，由票數最高的候補理事遞補。"]],"遠房":[["ㄩㄢˇ ㄈㄤˊ","宗族關係比較疏遠的親戚。[例]他是我遠房表親，難得見面。　△遠親"]],"遠眺":[["ㄩㄢˇ ㄊㄧㄠˋ","眺望遠處。[例]每逢假日，他喜歡到陽明山登高遠眺。"]],"遠行":[["ㄩㄢˇ ㄒㄧㄥˊ","出遠門。[例]這次遠行讓他體驗到了思鄉的情懷。"]],"遠親":[["ㄩㄢˇ ㄑㄧㄣ","1.住在遠方的親戚。[例]她是我們在南部的遠親，因為北上求學暫時寄住在我家。\n2.血統關係較疏遠的親戚。[例]在我們老家，左鄰右舍彼此之間往往是同宗的遠親。"]],"遠赴":[["ㄩㄢˇ ㄈㄨˋ","大老遠的前往某地。[例]姊姊決定遠赴英國求學。"]],"遠足":[["ㄩㄢˇ ㄗㄨˊ","行程較適中的徒步郊遊。[例]老師明天將帶我們到郊外遠足。"]],"遨遊":[["ㄠˊ ㄧㄡˊ","逍遙自在的遊歷玩賞。[例]人類羨慕小鳥自由的在天空中遨遊，於是有了飛機的發明。"]],"適合":[["ㄕˋ ㄏㄜˊ","配合得恰到好處。[例]這本書適合十歲以下的孩子閱讀。"]],"適宜":[["ㄕˋ ㄧˊ","恰當合宜。[例]秋天的氣候清爽，很適宜全家出遊。"]],"適量":[["ㄕˋ ㄌㄧㄤˋ","數量恰當。[例]適量的飲食和運動，是保持健康的不二法門。"]],"遭受":[["ㄗㄠ ㄕㄡˋ","碰到、受到。[例]他雖遭受多次失敗，卻始終積極進取，毫不氣餒。"]],"遭殃":[["ㄗㄠ ㄧㄤ","遭遇災禍。[例]政客爭權奪利，則百姓莫不遭殃。"]],"遭逢":[["ㄗㄠ ㄈㄥˊ","碰上、遇著。[例]南宋末年，許多志士遭逢國族淪亡之鉅變，莫不投筆從戎，力圖興復。"]],"遭遇":[["ㄗㄠ ㄩˋ","1.遭逢、遇上。[例]他出國旅遊時遭遇了不少奇妙有趣，可驚可愕的事。\n2.遇到的事情。[例]她一生坎坷的遭遇，令人十分同情。"]],"遮掩":[["ㄓㄜ ㄧㄢˇ","1.遮蔽、掩蓋。[例]這段路在茂密的行道樹遮掩之下，成了有名的林蔭大道。_x000D_\n2.掩飾、隱瞞。[例]這件事已水落石出，真相大白，毋須再為他遮掩了。"]],"遮擋":[["ㄓㄜ ㄉㄤˇ","掩蔽阻擋。[例]戴太陽眼鏡是為了遮擋烈日下的強光。"]],"遮蓋":[["ㄓㄜ ㄍㄞˋ","1.遮擋掩蔽。[例]鳥兒在屋簷的遮蓋下，躲開了一場暴風雨。_x000D_\n2.隱瞞、掩飾。[例]紙包不住火，真相是遮蓋不住的。"]],"遮蔽":[["ㄓㄜ ㄅㄧˋ","掩蔽、阻擋。[例]烏雲遮蔽了太陽，天空一片灰濛濛的，好像快下雨了。"]],"遮陽":[["ㄓㄜ ㄧㄤˊ","阻擋陽光的照射。[例]外頭烈日高照，出門別忘了戴頂帽子遮陽。"]],"遲到":[["ㄔˊ ㄉㄠˋ","到達的時間超過了既定的時限。[例]遲到早退是不好的行為。"]],"遲暮":[["ㄔˊ ㄇㄨˋ","1.天快黑的時候。[例]當我們到達目的地的時候，已是遲暮時分。\n2.比喻晚年、年老。[例]沒想到再度踏上這塊土地時，你我二人都已步入遲暮之年。"]],"遲緩":[["ㄔˊ ㄏㄨㄢˇ","緩慢、速度不快。[例]由於排隊購票的人非常多，因而隊伍前進的速度顯得相當遲緩。"]],"遲鈍":[["ㄔˊ ㄉㄨㄣˋ","反應不靈敏。[例]腦筋遲鈍是可以後天努力來彌補的。"]],"遵守":[["ㄗㄨㄣ ㄕㄡˇ","謹守、服從。[例]現代國民應遵守交通規則。"]],"遵照":[["ㄗㄨㄣ ㄓㄠˋ","遵奉依照。[例]對於此事，我們一切遵照上級的指示來辦理。"]],"選拔":[["ㄒㄩㄢˇ ㄅㄚˊ","挑選優秀、適合的人選。[例]他在這次歌唱選拔大賽中表現優異，從眾多參賽者中脫穎而出。"]],"選擇":[["ㄒㄩㄢˇ ㄗㄜˊ","挑選、擇取。[例]這兩種廠牌的車各有優缺點，令人難以選擇。"]],"選派":[["ㄒㄩㄢˇ ㄆㄞˋ","選擇合適的人員，派遣前去辦事或負責某項任務。[例]他是本校選派出來，參加全縣國語文競賽的代表。"]],"選配":[["ㄒㄩㄢˇ ㄆㄟˋ","挑選搭配。[例]他是位著名的室內設計師，對於家具的選配更是別具慧眼。"]],"遺址":[["ㄧˊ ㄓˇ","古代人類活動的地方。由此挖掘出來的古物和化石可供考古學家研究人類發展的歷史。如周口店遺址、半坡遺址等。"]],"遺失":[["ㄧˊ ㄕ","丟失。[例]身分證、金融卡都得隨身攜帶，以免遺失。"]],"遺忘":[["ㄧˊ ㄨㄤˋ","忘記。[例]這個神祕的部落隱居在幽深的山林裡，早已被世人遺忘。"]],"遺憾":[["ㄧˊ ㄏㄢˋ","事情的本身或發展令人感到憾恨或不滿意。[例]膝下無子是他終身的遺憾。"]],"遺留":[["ㄧˊ ㄌㄧㄡˊ","留下。[例]祖父去世時遺留了不少書畫古董。"]],"遼闊":[["ㄌㄧㄠˊ ㄎㄨㄛˋ","遼遠廣闊。[例]置身在遼闊的大草原上，不禁感覺到自己的渺小。"]],"避免":[["ㄅㄧˋ ㄇㄧㄢˇ","設法免除。[例]平常要多注意消防安全，以避免火災的發生。"]],"避暑":[["ㄅㄧˋ ㄕㄨˇ","遷居到清涼的地方，以避開暑氣。[例]父親每年夏天都會帶我們到鄉下的別墅避暑。"]],"避諱":[["ㄅㄧˋ ㄏㄨㄟˋ","1.舊時為了表示尊敬，在言語或書寫時，不直接稱呼君主、祖宗或尊長的名號，而改以缺筆、缺字、換字、改音等各種方式，稱為「避諱」。[例]今天一般人替小孩取名字時，仍有避諱的習慣，如不使用與長輩名字相同的字。\n2.避免觸犯忌諱。[例]他們毫不避諱的高談闊論，簡直目中無人。"]],"避難":[["ㄅㄧˋ ㄋㄢˋ","逃避災難或迫害。[例]森林大火蔓延迅速，動物們紛紛四散避難。"]],"邀約":[["ㄧㄠ ㄩㄝ","邀請、約請。[例]星期日的義賣活動，請各位同學邀約家人、朋友來共襄盛舉。"]],"還好":[["ㄏㄞˊ ㄏㄠˇ","1.尚可，過得去。[例]聽說他不喜歡這本書的封面，我倒覺得還好。\n2.幸好。有僥倖或慶幸的意味。[例]還好司機及時煞車，否則後果真是不堪設想。"]],"還是":[["ㄏㄞˊ ㄕˋ","1.仍然、依舊。[例]你愛抽菸的老毛病怎麼還是改不掉呢？_x000D_\n2.或者、或是。[例]不管是男孩還是女孩，都是父母的心肝寶貝。_x000D_\n3.表示希望。含有這麼做比較好的意思。[例]路途那麼遙遠，你還是早點兒出門吧！_x000D_\n4.也是。有強調的意思。[例]他不僅是老師，還是一位發明家。"]],"還有":[["ㄏㄞˊ ㄧㄡˇ","尚有，另外有。[例]飯後甜點除了蛋糕之外，還有果汁和布丁。"]],"還錢":[["ㄏㄨㄢˊ ㄑㄧㄢˊ","償還所積欠的金錢。[例]你必須依借據上約定的時間準時還錢。"]],"邊界":[["ㄅㄧㄢ ㄐㄧㄝˋ","1.國家領土的疆域界線，國與國間相鄰的界線。[例]再向北走，就接近邊界了。\n2.球賽範圍的邊線界限。[例]球被打出邊界，是個界外球。"]],"邊疆":[["ㄅㄧㄢ ㄐㄧㄤ","邊境附近的區域。[例]邊疆民族"]],"邊際":[["ㄅㄧㄢ ㄐㄧˋ","1.界限、盡頭。[例]汪洋大海，漫無邊際。\n2.頭緒、端倪。[例]不著邊際"]],"邋遢":[["ㄌㄚ ㄊㄚˋ","不整潔。[例]他真是邋遢，身上那套西裝居然已經連穿三個月沒洗了。"]],"邏輯":[["ㄌㄨㄛˊ ㄐㄧˊ","1.研究關於推理思考之原理、法則的學問。§英logic[例]希臘的亞里斯多德是邏輯科學的創始者。　△理則學\n2.道理、法則。[例]他的供詞前後矛盾，不合邏輯。"]],"那天":[["ㄋㄚˋ ㄊㄧㄢ","指所提及的某日。[例]參加面試那天，我特別穿了件新衣服。"]],"那裡":[["ㄋㄚˇ ㄌㄧˇ","1.何處、何方。[例]我好像在那裡看過你。_x000D_\n2.如何、怎麼。[例]他才剛來臺北，那裡摸得清東西南北？_x000D_\n3.表示客套的謙詞。[例]那裡，那裡，您過獎了。"],["ㄋㄚˋ ㄌㄧˇ","彼處。[例]一大堆人聚在那裡，不知發生什麼事了？"]],"那麼":[["ㄋㄚˋ ˙ㄇㄜ","如此、那樣子。[例]天色突然變得那麼昏暗，恐怕是要下雨了。"]],"邪惡":[["ㄒㄧㄝˊ ㄜˋ","奸邪凶惡。[例]人們相信正義的力量終究會戰勝邪惡。"]],"郊外":[["ㄐㄧㄠ ㄨㄞˋ","環繞城市外面的地方。[例]每逢風和日麗的假日，我們一家人便到郊外踏青。"]],"郊遊":[["ㄐㄧㄠ ㄧㄡˊ","到郊外的名勝或風景區遊覽。[例]我們全家預定明天到陽明山郊遊。"]],"郎君":[["ㄌㄤˊ ㄐㄩㄣ","古時妻子對丈夫的稱呼。後亦指丈夫。[例]在婚禮上，大家都恭喜她覓得如意郎君。"]],"部下":[["ㄅㄨˋ ㄒㄧㄚˋ","軍隊或團體裡被統率的人。[例]他為人公正嚴明，所有部下對他都敬畏三分。"]],"部分":[["ㄅㄨˋ ㄈㄣˋ","全體中的局部、某些個體。[例]訂約時只需付部分貨款就可以了。"]],"部屬":[["ㄅㄨˋ ㄕㄨˇ","軍隊或團體裡被統率的人。[例]身為部屬就應該服從長官的領導。"]],"部落":[["ㄅㄨˋ ㄌㄨㄛˋ","族群聚居而形成的小單位。在臺灣，通常指​​​​原住民​​​族​​​​的聚落或社區。[例]部落文化、原始部落"]],"部門":[["ㄅㄨˋ ㄇㄣˊ","專指機關中分別擔任不同職務的單位。[例]你在電視公司的哪個部門工作？"]],"郵差":[["ㄧㄡˊ ㄔㄞ","受僱於郵局，負責收送信件的人。[例]經過幾次的試投，郵差終於把這封寫錯地址的信件送到收信人手上。　△郵務士"]],"郵票":[["ㄧㄡˊ ㄆㄧㄠˋ","黏貼在信件上，作為已繳納郵資的憑證。多為印花紙片。[例]這枚獨特的郵票是在網路上搜尋買到的。"]],"郵筒":[["ㄧㄡˊ ㄊㄨㄥˇ","郵局設立供人投寄郵件的筒子。[例]目前國內的郵筒分為紅色和綠色兩種。"]],"郵箱":[["ㄧㄡˊ ㄒㄧㄤ","1.私人住宅門前或向郵局租用的收信箱。　△信箱_x000D_\n2.郵局設立供人投寄郵件的箱子。"]],"郵資":[["ㄧㄡˊ ㄗ","寄送信件、包裹等所支付的費用。[例]他寄書給國外的朋友，花了不少郵資。"]],"都市":[["ㄉㄨ ㄕˋ","人口密度較高、工商交通發達的地區。居民的職業多元化，以農、林、漁、牧業以外的職業為主，並設有正式的行政組織，以維持較高水準的公共建設和服務。"]],"鄉村":[["ㄒㄧㄤ ㄘㄨㄣ","人口的分布較城市分散，而且居民以從事農業為主的地區。"]],"鄰國":[["ㄌㄧㄣˊ ㄍㄨㄛˊ","國界互相接壤或鄰近的國家。[例]鄰國之間應該和睦相處，共同維持區域間的和平穩定。"]],"鄰居":[["ㄌㄧㄣˊ ㄐㄩ","住處相近的人家。[例]隔壁林家是我們相處多年的好鄰居。"]],"鄰近":[["ㄌㄧㄣˊ ㄐㄧㄣˋ","接近、附近。[例]我住在很理想的文教區，鄰近有好幾所學校。"]],"配合":[["ㄆㄟˋ ㄏㄜˊ","搭配。[例]大家在工作上要互相配合、體諒，才不致出現意氣之爭。"]],"配戴":[["ㄆㄟˋ ㄉㄞˋ","搭配佩戴。[例]這件禮服要配戴項鍊才會更加出色。"]],"配飾":[["ㄆㄟˋ ㄕˋ","搭配用的飾品。[例]這套服裝之所以能賣得好價錢，都得歸功於精巧的配飾。"]],"酒吧":[["ㄐㄧㄡˇ ㄅㄚ","吧，指放酒的櫃臺。酒吧為一般設有吧檯的酒店的通稱，主要是供應酒類飲料，也出售簡單的食物。§英bar [例]鋼琴酒吧"]],"酒鬼":[["ㄐㄧㄡˇ ㄍㄨㄟˇ","稱嗜酒貪杯的人。含蔑視責罵之意。[例]他事業失敗後，終日借酒澆愁成了個酒鬼，毫無一點鬥志。"]],"酣睡":[["ㄏㄢ ㄕㄨㄟˋ","熟睡。[例]連日的熬夜，使他一躺在床上就酣睡起來。"]],"酣醉":[["ㄏㄢ ㄗㄨㄟˋ","飲酒大醉。[例]新郎官已被眾賀客灌得酣醉了。"]],"酬勞":[["ㄔㄡˊ ㄌㄠˊ","1.答謝、酬謝。[例]為了酬勞他這次的大力相助，我決定請他一次客。\n2.給予出力人的報酬。[例]這份工作酬勞優渥，因此有不少人競爭。"]],"酸楚":[["ㄙㄨㄢ ㄔㄨˇ","辛酸悲苦。[例]為了生活，她只好打起精神，將一切酸楚埋在心底。"]],"酸甜苦辣":[["ㄙㄨㄢ ㄊㄧㄢˊ ㄎㄨˇ ㄌㄚˋ","各種味道。比喻生活中如意、失意等種種遭遇。[例]人生中充滿了酸甜苦辣，如何自處，全在一念之間！"]],"醃漬":[["ㄧㄢ ㄗˋ","用鹽、糖、醬或各種佐料浸泡食物的調理方法。[例]有些蔬菜、水果經過醃漬後，風味更佳。"]],"醃製":[["ㄧㄢ ㄓˋ","以醃漬方法所製成。[例]媽媽醃製的醬瓜非常好吃。"]],"醉心":[["ㄗㄨㄟˋ ㄒㄧㄣ","喜愛到沉醉迷戀的地步。[例]她醉心於藝術創作，已到了廢寢忘食的地步。"]],"醉生夢死":[["ㄗㄨㄟˋ ㄕㄥ ㄇㄥˋ ㄙˇ","像在醉夢中那樣昏昏沉沉過日子。形容人缺乏目標，糊裡糊塗的活著。[例]國家面臨存亡危急之秋，國人豈可醉生夢死，不知警惕？"]],"醍醐灌頂":[["ㄊㄧˊ ㄏㄨˊ ㄍㄨㄢˋ ㄉㄧㄥˇ","1.比喻灌輸智慧，使人得到啟發，澈底醒悟。[例]他的一席話猶如醍醐灌頂，令人茅塞頓開。\n2.比喻令人感到清爽舒暢。[例]夏天在日晒後沖個冷水澡，有如醍醐灌頂，令人精神一振。"]],"醒悟":[["ㄒㄧㄥˇ ㄨˋ","清醒領悟。[例]經過老師一番開導，他才醒悟過來。"]],"醜惡":[["ㄔㄡˇ ㄜˋ","醜陋惡劣。[例]紙永遠包不住火，他醜惡的行為終於被揭發出來了。"]],"醜態":[["ㄔㄡˇ ㄊㄞˋ","不雅觀、有失身分體面的行為。[例]他那種尖酸刻薄的醜態，令人厭惡。"]],"醫生":[["ㄧ ㄕㄥ","經政府相關單位核可，替人治病的人。[例]醫生替他做了一次健康檢查，結果情形相當良好。"]],"醫療":[["ㄧ ㄌㄧㄠˊ","醫治療養。[例]經過多日悉心的醫療，她的病日漸痊癒了。"]],"醫術":[["ㄧ ㄕㄨˋ","治病的技術。[例]醫術高明"]],"醫護":[["ㄧ ㄏㄨˋ","醫療護理。[例]由於醫護人員細心的醫治照顧，他的身體很快就康復了。"]],"醫院":[["ㄧ ㄩㄢˋ","診治或看護病人的機構。[例]身體有了病痛，最好立刻上醫院去看醫生。"]],"醬料":[["ㄐㄧㄤˋ ㄌㄧㄠˋ","用來醃漬食材或增加食物風味的佐料。多呈糊狀或液態。[例]外婆自製的獨門醬料是我難以忘懷的童年記憶。"]],"醬汁":[["ㄐㄧㄤˋ ㄓ","用來佐味的糊狀或液態調味料。[例]灑滿醬汁的紅燒魚香味四溢，令人食指大動。"]],"醬油":[["ㄐㄧㄤˋ ㄧㄡˊ","用大豆、小麥加鹽水發酵釀製成的調味品。[例]醬油是烹飪食物常用的調味料。"]],"醬菜":[["ㄐㄧㄤˋ ㄘㄞˋ","泛指用醬或醬油等醃漬的各種菜蔬。如醬瓜、醬茄等。[例]奶奶醃漬的醬菜既可口又下飯。"]],"釋放":[["ㄕˋ ㄈㄤˋ","1.恢復被拘禁者或服刑者的人身自由。[例]無罪釋放、釋放人質\n2.發散、發出。[例]原子核反應所釋放的能量可供發電。"]],"釋疑":[["ㄕˋ ㄧˊ","解除心中的疑慮、難題。[例]醫院有一群熱心的義工，時常為病人及其家屬解困釋疑。"]],"釋義":[["ㄕˋ ㄧˋ","解釋語詞意思的文字。[例]老師說課文中重要字詞的釋義要記熟。"]],"里民":[["ㄌㄧˇ ㄇㄧㄣˊ","居住或設籍在同一里的居民。[例]這次大掃除由於里民的分工合作，環境整理得非常整潔。"]],"里程":[["ㄌㄧˇ ㄔㄥˊ","1.路程。[例]這趟探親的里程相當遙遠，事前要準備周全，以防突發狀況發生。\n2.汽機車里程表所顯示行走的公里數。[例]這輛中古車才跑了一萬多公里，里程少，可考慮購買。\n3.發展過程、階段。[例]結婚是兩個人同心邁向人生里程的開始。"]],"重傷":[["ㄓㄨㄥˋ ㄕㄤ","受的傷相當嚴重。[例]昨天高速公路發生重大交通事故，結果造成三人死亡、八人重傷。"]],"重播":[["ㄔㄨㄥˊ ㄅㄛˋ","再一次播放電視、廣播的節目或畫面。[例]應觀眾要求，電視臺將於今日晚間重播此劇集。"]],"重擔":[["ㄓㄨㄥˋ ㄉㄢˋ","比喻繁重的責任。[例]他小小年紀就背負家計的重擔，遭遇實在令人同情。"]],"重新":[["ㄔㄨㄥˊ ㄒㄧㄣ","從頭開始、再一次。[例]重新做人、重新出發、重新布置"]],"重疊":[["ㄔㄨㄥˊ ㄉㄧㄝˊ","層層相疊。[例]交錯重疊、山川重疊"]],"重複":[["ㄔㄨㄥˊ ㄈㄨˋ","事物反覆相同。[例]這一小節的動作重複做兩次後，再換動作。"]],"重要":[["ㄓㄨㄥˋ ㄧㄠˋ","重大而且緊要。[例]父親常常告誡我們，功名利祿固然可喜，卻不如修心養性來得重要。"]],"重視":[["ㄓㄨㄥˋ ㄕˋ","特別注意、看重。[例]近來校園暴力層出不窮，再度喚起大家對校園安全的重視。"]],"重逢":[["ㄔㄨㄥˊ ㄈㄥˊ","再度相逢。[例]久別重逢、異地重逢"]],"重量":[["ㄓㄨㄥˋ ㄌㄧㄤˋ","物理學上稱物體所受地球引力的大小。[例]這桶水的重量剛好是十公斤。"]],"重點":[["ㄓㄨㄥˋ ㄉㄧㄢˇ","重心、要點。[例]檢肅流氓、查緝黑槍是今年春安演習的工作重點。"]],"野外":[["ㄧㄝˇ ㄨㄞˋ","離市區較遠的地方。[例]春天來了，許多人紛紛到野外去踏青。"]],"野獸":[["ㄧㄝˇ ㄕㄡˋ","生長在山野間，沒有經過人工飼養、繁殖的獸類。[例]由於人類的大肆獵捕，許多野獸已瀕臨絕種。"]],"野蠻":[["ㄧㄝˇ ㄇㄢˊ","1.未開化的。[例]野蠻民族\n2.蠻橫而不講理。[例]虧他還受過高等教育，怎麼會有如此野蠻的行為？"]],"量詞":[["ㄌㄧㄤˋ ㄘˊ","表示事物或動作的單位詞，如表示事物單位的個、塊等，與表示動作單位的次、回、趟、遍等。"]],"釐定":[["ㄌㄧˊ ㄉㄧㄥˋ","整理訂定。[例]釐定疆界"]],"釐清":[["ㄌㄧˊ ㄑㄧㄥ","整理劃清。[例]釐清字義、釐清頭緒、釐清界限"]],"釐米":[["ㄌㄧˊ ㄇㄧˇ","量詞。計算長度的單位。公制一釐米等於一米的百分之一。今作「厘米」。　△公分"]],"金字塔":[["ㄐㄧㄣ ㄗˋ ㄊㄚˇ","古代埃及國王的墳墓。用石塊砌成，為底面四方形、側面三角形的角錐塔，因為它的形狀像中文的「金」字，所以譯做「金字塔」。為世界七大奇景之一。[例]金字塔和人面獅身像是埃及著名的景觀。　◎"]],"金屬":[["ㄐㄧㄣ ㄕㄨˇ","黃金及其他能導電及導熱的物質。如金、銀、銅、鐵等。[例]金屬材料、金屬製品"]],"金碧輝煌":[["ㄐㄧㄣ ㄅㄧˋ ㄏㄨㄟ ㄏㄨㄤˊ","形容建築物十分華麗光彩。[例]這座仿古的宮殿裝飾得金碧輝煌，十分耀眼。"]],"金融":[["ㄐㄧㄣ ㄖㄨㄥˊ","金錢在市面流通的狀態。包括貨幣的發行、流通和回籠，貸款的發放和收回，款項的提存，匯兌的往來等經濟活動。[例]金融機構、金融交易"]],"金魚":[["ㄐㄧㄣ ㄩˊ","動物名。硬骨魚綱鯉目鯉科。為鯽魚的變種，由鯽魚經不斷的人工選種、配種與淘汰而成。體形略呈圓球狀，凸眼，鱗片有金光，顏色鮮豔，鰭大，尾作三分或四分，可供觀賞。[例]爸爸在春節前特地買了一對金魚養在水箱中，以添增過年的喜氣。　△文魚　◎"]],"金黃色":[["ㄐㄧㄣ ㄏㄨㄤˊ ㄙㄜˋ","有黃金般色澤的顏色。[例]果園裡結滿了金黃色的橘子。"]],"釘書機":[["ㄉㄧㄥˋ ㄕㄨ ㄐㄧ","用釘書針將紙張裝訂成冊的機器。[例]他用釘書機將這些廢紙釘在一起，當作計算紙。◎"]],"釘鞋":[["ㄉㄧㄥ ㄒㄧㄝˊ","鞋底裝置有釘子的鞋，有兩種：一種是用在爬高山、峭壁或冰雪時用，不致滑跌；一在賽跑時用，鞋釘插進跑道，以增加跑步衝力。[例]大會規定，凡參加賽跑的選手一律要穿著釘鞋出賽。"]],"針筒":[["ㄓㄣ ㄊㄨㄥˇ","西醫注射器裝藥液的部分。筒上有以ＣＣ為單位的刻度表以表示其容量，筒中有推壓器，前部裝有針頭，用來注射藥液。[例]針筒以玻璃或塑膠製成。"]],"針鋒相對":[["ㄓㄣ ㄈㄥ ㄒㄧㄤ ㄉㄨㄟˋ","比喻雙方的行為、言辭等尖銳對立。[例]他們的教育理念不同，所以一談到教育問題就針鋒相對，互不相讓。"]],"釣魚":[["ㄉㄧㄠˋ ㄩˊ","用餌誘魚上鉤。[例]閒暇無事時，他喜歡一個人到海邊釣魚。"]],"鈔票":[["ㄔㄠ ㄆㄧㄠˋ","紙幣。[例]媽媽從皮包裡取出一疊鈔票來付款。"]],"鈴鐺":[["ㄌㄧㄥˊ ㄉㄤ","用金屬所製成的球形中空器具。底部有一開口，內置金屬丸或小石，搖動時會發出清脆的響聲。[例]商店門上常會掛著一串鈴鐺，顧客進來時便能馬上知道。"]],"鈴鼓":[["ㄌㄧㄥˊ ㄍㄨˇ","樂器名。屬於打擊樂器。在圓形木框的一面，蒙上羊皮或驢皮等，木框的周圍嵌繫著銅、鐵製成的小鐃鈸，藉著敲打皮面、磨擦或搖動木框而帶動鐃鈸，發出輕快而熱鬧的聲響。多用於歌唱、舞蹈伴奏或器樂合奏等。[例]音樂課時老師指導我們練習鈴鼓，一手平拿鈴鼓，一手用掌緣輕敲跟搖晃，不管摩擦、旋轉、震動，都會發出聲音，同學們都興致勃勃。　◎"]],"鉅細靡遺":[["ㄐㄩˋ ㄒㄧˋ ㄇㄧˇ ㄧˊ","無論大小地方都不會遺漏。比喻做事很仔細。[例]目擊者在警局，向辦案人員鉅細靡遺地描述整起車禍的經過。"]],"鉛球":[["ㄑㄧㄢ ㄑㄧㄡˊ","1.一種田賽運動。運動員以手托住鉛球，由肩上用力的推出，以推擲最遠的人獲勝。與鐵餅、標槍合稱為「三鐵」。[例]他是區運男子鉛球比賽的紀錄保持人。　◎\n2.鉛球運動所使用的器具。球形，以鐵或銅為外殼，中間灌鉛。[例]體育老師交代我在上課前先到器材室借鉛球，以便同學練習。"]],"鉛筆":[["ㄑㄧㄢ ㄅㄧˇ","將石墨粉和黏土製成的筆心，嵌入圓條形的木管或其他質料的筆管中，所做成的書寫工具。[例]鉛筆書寫方便，擦拭容易，非常適合小朋友使用。"]],"銀河":[["ㄧㄣˊ ㄏㄜˊ","天空聯亙如帶的星群。[例]天空中的銀河及數不清的星星，將夜晚妝點得更加迷人。　△天河、天漢、星河、銀漢、雲漢"]],"銀色":[["ㄧㄣˊ ㄙㄜˋ","像銀子般發亮的白色。[例]白雪皚皚，我們置身在一片銀色大地之中。"]],"銀行":[["ㄧㄣˊ ㄏㄤˊ","一種金融機構。以存款、放款、匯兌為主要業務，或兼事票券經理、紙幣兌換、代理國庫之出納等業務。[例]每個月的水費、電費、電話費等，可委託銀行代為繳納。"]],"銅板":[["ㄊㄨㄥˊ ㄅㄢˇ","1.銅製的錢幣。今多泛稱硬幣。[例]他從小就有儲蓄的習慣，撲滿裡裝滿了銅板。_x000D_\n2.演唱快書時，用來打拍子的半月形銅片。[例]只見那個說書的，手裡敲著銅板，演說著岳飛精忠報國的故事。"]],"銅牌":[["ㄊㄨㄥˊ ㄆㄞˊ","1.銅質的牌子。經常用來製成各種形狀的獎牌，上面刻字，可作獎品或紀念品，便於保存陳列。[例]櫃上放置的銅牌，正代表他過去的光榮事蹟。\n2.比賽中的第三名。競賽時，通常頒發銅質的紀念牌給獲得第三名者，故以銅牌稱第三名。[例]他獲得短跑比賽的銅牌，因此雀躍不已。"]],"銅鑼":[["ㄊㄨㄥˊ ㄌㄨㄛˊ","樂器名。屬於打擊樂器。由青銅製成，鑼面呈圓盤形，中央微鼓起。演奏時用槌敲擊鑼面中心點，可因力道強弱，而表現出不同的音響效果。[例]迎神賽會的隊伍上，有人敲銅鑼，有人扮神表演，好不熱鬧。"]],"銜接":[["ㄒㄧㄢˊ ㄐㄧㄝ","互相連接。[例]這座橋梁銜接本鎮與外地的交通。"]],"銳不可當":[["ㄖㄨㄟˋ ㄅㄨˋ ㄎㄜˇ ㄉㄤˇ","氣勢威猛，不可抵擋。[例]革命軍的攻勢銳不可當，全國各地的志士紛紛響應。"]],"銳利":[["ㄖㄨㄟˋ ㄌㄧˋ","1.刀鋒尖銳鋒利。[例]這把刀非常銳利，使用時務必小心。\n2.比喻目光、言論或文筆很尖銳。[例]她看人的眼光很銳利，使人不敢注視。"]],"銳減":[["ㄖㄨㄟˋ ㄐㄧㄢˇ","急劇、大量的減少。[例]因為風雨來襲，逛街的人潮銳減，商家的生意也很冷清。"]],"銷售":[["ㄒㄧㄠ ㄕㄡˋ","出售、販賣。[例]這臺錄放影機功能佳，價錢又低，銷售情況一路領先。"]],"銷售一空":[["ㄒㄧㄠ ㄕㄡˋ ㄧ ㄎㄨㄥ","賣得精光。形容貨品的售出情況良好。[例]本公司新推出的掌上型電動玩具，甫一上市，立即銷售一空。"]],"鋁箔":[["ㄌㄩˇ ㄅㄛˊ","以鋁製成的薄片。具有耐熱、抗腐蝕的特性，常用作食品的內包裝。[例]拜科技昌明之賜，鋁箔包裝大大地延長了食物保存的期限。"]],"鋁罐":[["ㄌㄩˇ ㄍㄨㄢˋ","取代以往鐵罐的一種無菌產品包裝。具有質輕、抗腐性、抗壓力強等特點。[例]食用鋁罐食物後，記得要做資源回收，切勿隨手丟棄。"]],"鋒芒":[["ㄈㄥ ㄇㄤˊ","比喻人的銳氣與才華。[例]他才華洋溢，初入職場就展露鋒芒，引起眾人矚目。"]],"鋪位":[["ㄆㄨˋ ㄨㄟˋ","床位。[例]這房間才有十個鋪位，要睡十五個人，是嫌擠了些。"]],"鋪排":[["ㄆㄨ ㄆㄞˊ","布置、安排。[例]只要他一出馬，大小事情都鋪排得條理井然。"]],"鋪設":[["ㄆㄨ ㄕㄜˋ","鋪陳設置。[例]鋪設鐵軌、鋪設管線"]],"鋪路":[["ㄆㄨ ㄌㄨˋ","1.鋪設道路。[例]造橋鋪路\n2.為求事情順利進行，先打通關節或預做安排。[例]他這次參選市議員，是為將來競選市長鋪路。"]],"鋪陳":[["ㄆㄨ ㄔㄣˊ","1.布置、擺設。[例]鋪陳酒器\n2.詳細陳述。[例]鋪陳事理"]],"鋸齒":[["ㄐㄩˋ ㄔˇ","1.鋸子的尖齒。[例]這把鋸子的鋸齒不平，使用起來很不順手。\n2.像鋸子一般的銳齒。[例]薄荷的葉緣呈鋸齒狀，用手揉捏一下，會有一股香氣。"]],"鋼琴":[["ㄍㄤ ㄑㄧㄣˊ","樂器名。屬鍵盤樂器。形狀像風琴，體積較大，內裝有許多鋼絲弦和包絨氈的木錘，手指按動鍵盤時，牽動鍵盤下的小木錘敲打鋼絲弦而發出聲音。十八世紀中葉以後廣泛流行。[例]她從小就學會彈鋼琴，有很深厚的音樂素養。　◎"]],"鋼筆":[["ㄍㄤ ㄅㄧˇ","金屬筆尖，並有貯存墨水裝置的筆。[例]這次月考的成績進步許多，爸爸送我一枝鋼筆作為鼓勵。"]],"鋼筋":[["ㄍㄤ ㄐㄧㄣ","鋼料經鍛鍊後滾壓製成的鋼條。是一種能夠承受拉力的優良建材，被普遍用於營建工程。由斷面形狀可分成圓形及方形；表面形狀可分為光面、竹節及螺紋鋼筋。[例]與土造屋舍比起來，鋼筋水泥建造的房子較經得起地震的晃動。　△鋼條"]],"鋼索":[["ㄍㄤ ㄙㄨㄛˇ","絞合鋼絲成股，再合數股絞成的繩索。[例]鋼索吊橋"]],"鋼鐵":[["ㄍㄤ ㄊㄧㄝˇ","1.鋼的統稱。[例]這臺機器是用鋼鐵做的，所以特別耐用。\n2.比喻極為堅實、強大。[例]鋼鐵陣容、鋼鐵部隊"]],"錄影":[["ㄌㄨˋ ㄧㄥˇ","透過機械操作，將影像或各種視訊記錄於磁帶上。"]],"錄音":[["ㄌㄨˋ ㄧㄣ","透過機械、光學或電磁等方式，將聲音記錄在唱片、錄音帶、膠片等媒介物上。[例]這段電臺專訪是錄音製作的，並非現場直播。"]],"錙銖必較":[["ㄗ ㄓㄨ ㄅㄧˋ ㄐㄧㄠˋ","斤斤計較。[例]凡事錙銖必較，只會徒增困擾。"]],"錢包":[["ㄑㄧㄢˊ ㄅㄠ","裝錢的袋子。[例]上公車時，應將自己的錢包保管好，以免被小偷扒走。"]],"錢幣":[["ㄑㄧㄢˊ ㄅㄧˋ","錢。多指金屬貨幣。[例]他收藏了許多古代的錢幣。"]],"錦囊":[["ㄐㄧㄣˇ ㄋㄤˊ","用錦緞製成的袋子。古人用來珍藏詩稿或機密、貴重的物品。[例]錦囊佳製"]],"錦旗":[["ㄐㄧㄣˇ ㄑㄧˊ","用錦緞製成的旗幟。多作為獎品或表示謝意的紀念品。[例]這一屆全校運動大會，本班一共獲得五面錦旗。"]],"錯字":[["ㄘㄨㄛˋ ㄗˋ","字形錯誤或誤用的字。[例]老師將文章內的錯字圈出，並要同學們訂正。"]],"錯愕":[["ㄘㄨㄛˋ ㄜˋ","因事出倉促、震驚而不知所措。[例]他在得知自己落選的一剎那，頓時錯愕不已，呆立良久後才驚醒過來。"]],"錯誤":[["ㄘㄨㄛˋ ㄨˋ","不對、不正確。[例]勇於改正自己的錯誤才能從失敗中站起來。"]],"鍋爐":[["ㄍㄨㄛ ㄌㄨˊ","1.由鋼板製成，包含裝水容器和燒火裝置的密閉容器。容器內裝水，經燃料燃燒後產生高溫高壓的水蒸汽，用來產生動力。[例]阿里山的蒸汽小火車，使用直立式鍋爐作為推進的動力。　△蒸汽發生器_x000D_\n2.用來燒熱水的器具。 [例]站在吧檯後的我，被鍋爐裡不斷冒出的熱氣薰得受不了。"]],"鍋蓋":[["ㄍㄨㄛ ㄍㄞˋ","覆蓋鍋口的蓋子。[例]烹煮食物時蓋上鍋蓋較快熟透。"]],"鍋鏟":[["ㄍㄨㄛ ㄔㄢˇ","烹飪時用以翻動、攪拌菜餚的鏟子。[例]廚房裡，媽媽正揮動鍋鏟準備晚餐。　◎"]],"鍛造":[["ㄉㄨㄢˋ ㄗㄠˋ","將高溫或常溫的金屬，用錘擊或壓床加壓的方式，使金屬物件具有一定的形狀和尺寸，並改變它的物理性質的加工法。[例]這塊鋼鐵經過鍛造後，變成了一把鋒利的菜刀。"]],"鍛鍊":[["ㄉㄨㄢˋ ㄌㄧㄢˋ","1.冶煉金屬使其更加精純。[例]金屬經過冶燒鍛鍊後會更加精純。_x000D_\n2.磨鍊。[例]鍛鍊體魄、鍛鍊身心"]],"鍥而不捨":[["ㄑㄧㄝˋ ㄦˊ ㄅㄨˋ ㄕㄜˇ","比喻有恆心、毅力，堅持到底。[例]經警方鍥而不捨的追查，真凶終於找出了。"]],"鍵盤":[["ㄐㄧㄢˋ ㄆㄢˊ","1.鋼琴、風琴上排列著黑白鍵的部分。如鋼琴鍵盤、風琴鍵盤。[例]她的琴藝高超，只見手指在鍵盤上靈活的躍動，美妙的音樂就流瀉而出。\n2.電腦或打字機上排列著字鍵的部分。如電腦鍵盤、打字機鍵盤。[例]熟練打字的他，打字時幾乎不用看鍵盤，文書輸入速度很快。"]],"鎂光燈":[["ㄇㄟˇ ㄍㄨㄤ ㄉㄥ","照相時，用來加強光度的照明設備。[例]大明星一現身，鎂光燈就閃個不停。"]],"鎖匙":[["ㄙㄨㄛˇ ˙ㄕ","開鎖的工具。[例]出門時記得帶鎖匙，以免回家望門興嘆。　△鑰匙"]],"鎖鏈":[["ㄙㄨㄛˇ ㄌㄧㄢˋ","用鐵環連接成串用以鎖住物品的鏈形物。[例]她用鎖鏈把機車鎖住，以防被偷。"]],"鎮壓":[["ㄓㄣˋ ㄧㄚ","1.以武力禁止暴亂。[例]鎮壓暴民\n2.疊壓。[例]他用重物鎮壓翻捲的書皮，希望能使它恢復平順。"]],"鎮守":[["ㄓㄣˋ ㄕㄡˇ","鎮壓駐守。[例]明朝以吳三桂鎮守山海關，不料卻埋下引清兵入關的禍端。"]],"鎮靜":[["ㄓㄣˋ ㄐㄧㄥˋ","穩定沉著，從容不迫。[例]遇到突發事故時，要保持鎮靜，才能臨機應變。"]],"鏗鏘":[["ㄎㄥ ㄑㄧㄤ","1.狀聲詞。形容金屬或琴瑟的清脆聲音。[例]琴聲鏗鏘\n2.形容聲音清脆響亮。[例]他的演說鏗鏘有力，在場來賓都鼓掌叫好。"]],"鏟子":[["ㄔㄢˇ ˙ㄗ","1.供鏟除與撮取用的鐵器。[例]她拿著鏟子鬆土，以使植物長得更好。　◎\n2.烹飪用的鏟形鐵器。[例]她用鏟子在熱鍋裡撥弄幾下，一盤青菜就炒好了。"]],"鏟除":[["ㄔㄢˇ ㄔㄨˊ","除去、清除。[例]農夫辛勤的在田裡播種施肥，鏟除野草。"]],"鏡子":[["ㄐㄧㄥˋ ˙ㄗ","具有光滑的平面，能照見形象的器具。古代用銅合金鑄成的厚圓片磨成，現在用平面玻璃背面鍍硝酸銀、水銀或鍍鋁做成。[例]他一不小心把那面鏡子打破了。　△鏡兒"]],"鏡片":[["ㄐㄧㄥˋ ㄆㄧㄢˋ","光學儀器或用具上的透明鏡。[例]近視眼要戴凹透鏡的鏡片，才能矯正視力。"]],"鏡頭":[["ㄐㄧㄥˋ ㄊㄡˊ","1.照相機、攝影機或放映機上，由透鏡組成的光學裝置。[例]攝影師在拍團體照前，要求大家將目光看向鏡頭。\n2.攝影機拍照時所攝取的畫面、情景。[例]特寫鏡頭、悲慘鏡頭"]],"鐮刀":[["ㄌㄧㄢˊ ㄉㄠ","用於收割農作物和割除雜草的器具。[例]過去每到秋天，就可以看見田裡滿是揮動鐮刀收割稻子的農夫。　◎◎"]],"鐵欄杆":[["ㄊㄧㄝˇ ㄌㄢˊ ㄍㄢ","用鐵條做成的欄杆，通常鐵條會漆上一層油漆以防止生鏽。[例]公園裡的池塘四周用鐵欄杆圍著，以防止遊客不小心跌落。"]],"鐵罐":[["ㄊㄧㄝˇ ㄍㄨㄢˋ","鐵製的罐子。[例]小朋友們經常將空的鐵罐當成足球般，踢來踢去。"]],"鐵鎚":[["ㄊㄧㄝˇ ㄔㄨㄟˊ","鐵製的鎚子。[例]用鐵鎚釘釘子，也要有技術，才不會釘歪了。"]],"鑑別":[["ㄐㄧㄢˋ ㄅㄧㄝˊ","審察辨別事物的真假好壞。[例]她是位鑑別波斯古物的專家，在國際上享有極高的聲譽。"]],"鑑賞":[["ㄐㄧㄢˋ ㄕㄤˇ","鑑定賞玩。[例]他鑑賞古代書畫的能力，受到同行一致的肯定。　△鑒賞"]],"鑰匙":[["ㄧㄠˋ ˙ㄕ","開鎖的器物。[例]小明出門時忘記帶鑰匙，只好站在門外等媽媽回來。　△鎖匙"]],"鑽孔":[["ㄗㄨㄢ ㄎㄨㄥˇ","穿孔。[例]工人用電鑽鑽孔，準備安裝新的機器。"]],"鑽牛角尖":[["ㄗㄨㄢ ㄋㄧㄡˊ ㄐㄧㄠˇ ㄐㄧㄢ","比喻人固執而不知變通，費力的研究無用或無法解決的問題。[例]凡事要想開點，不要鑽牛角尖。"]],"鑽研":[["ㄗㄨㄢ ㄧㄢˊ","深入研究。[例]她不斷鑽研繪畫技巧，因此畫風日益高明。"]],"長大":[["ㄓㄤˇ ㄉㄚˋ","成長壯大。[例]在過度呵護中長大的孩子，往往缺乏獨立性。"]],"長子":[["ㄓㄤˇ ㄗˇ","排行最大的兒子。[例]他們夫婦兩人都與長子同住。"]],"長相":[["ㄓㄤˇ ㄒㄧㄤˋ","相貌、面容。[例]他的長相顯得很憨厚，心地一定也很善良。"]],"長短":[["ㄔㄤˊ ㄉㄨㄢˇ","1.長度。[例]這件裙子長短適中，不用再修改了。\n2.意外的變故。[例]做人子女要愛護自己的身體，若是有個長短，會令父母擔心。\n3.是非、善惡。[例]隨便說人長短是不道德的行為。"]],"長程":[["ㄔㄤˊ ㄔㄥˊ","路程長遠。[例]他計劃到歐洲作一次長程旅行。"]],"長袍":[["ㄔㄤˊ ㄆㄠˊ","長及腳踝的連身棉袍或夾袍。[例]他穿起長袍來，別有一番典雅的氣質。 ◎"]],"長跑":[["ㄔㄤˊ ㄆㄠˇ","長距離的跑步。[例]她不但奪得本屆五千公尺長跑比賽的冠軍，更破了全國紀錄。"]],"長進":[["ㄓㄤˇ ㄐㄧㄣˋ","成長進步。[例]他上了國中後，漸有長進，讓父母親感到非常欣慰。"]],"長頸鹿":[["ㄔㄤˊ ㄐㄧㄥˇ ㄌㄨˋ","動物名。哺乳綱偶蹄目長頸鹿科。原產於非洲撒哈拉以南的大部分地區。形略似鹿，腿和頸部甚長，視覺和聽覺都很好，毛淺黃色，有淺棕褐色斑點。群居，生活在平原和開闊的灌木地區，以金合歡屬植物的葉為食。步距長，跑得很快，性情馴順。[例]長頸鹿是地球上最高的動物。　◎"]],"門市":[["ㄇㄣˊ ㄕˋ","零售或展示公司貨品的店面。[例]這家成衣公司的門市生意很好。"]],"門框":[["ㄇㄣˊ ㄎㄨㄤ","門兩旁的木柱，用來安裝門扇。[例]過年時，爸爸都會貼一副新春聯在門框上。"]],"門檻":[["ㄇㄣˊ ㄎㄢˇ","1.門框下邊緊貼地面的橫木。[例]這座廟的門檻很高，不容易跨過去。\n2.比喻限制的標準。[例]公司招募新進人員的門檻極高，不容易被錄取。"]],"門牌":[["ㄇㄣˊ ㄆㄞˊ","固定在屋舍正門，標明地址的牌子。[例]郵差按照門牌號碼挨戶把信件投入信箱。"]],"門牙":[["ㄇㄣˊ ㄧㄚˊ","位於牙床中央，犬齒以內的牙齒，上下各有四枚。[例]他騎機車不小心摔倒，跌斷了兩顆門牙。　△門齒　◎"]],"門票":[["ㄇㄣˊ ㄆㄧㄠˋ","入場券。[例]他不惜漏夜排隊購買舞蹈公演的門票。"]],"門禁":[["ㄇㄣˊ ㄐㄧㄣˋ","門口的出入限制。[例]兵工廠門禁森嚴。"]],"門窗":[["ㄇㄣˊ ㄔㄨㄤ","門和窗戶。[例]打開門窗，讓室內空氣流通。"]],"門簾":[["ㄇㄣˊ ㄌㄧㄢˊ","門上掛的簾子。[例]他掀開門簾，大步跨進房裡。"]],"門縫":[["ㄇㄣˊ ㄈㄥˋ","門板上或門板與門框之間的縫隙。[例]陣陣寒風從門縫鑽入，冷得讓人直打哆嗦。"]],"閃光":[["ㄕㄢˇ ㄍㄨㄤ","忽然一現或搖動不定的亮光。[例]一道閃光，劃破了黑夜的寂靜。"]],"閃耀":[["ㄕㄢˇ ㄧㄠˋ","光亮耀眼。[例]清晨，金黃色的陽光在海面上閃耀著。"]],"閃躲":[["ㄕㄢˇ ㄉㄨㄛˇ","避開、躲避。[例]他為了閃躲車子，不小心跌倒。"]],"閉上":[["ㄅㄧˋ ㄕㄤˋ","關閉合上。[例]閱讀一段時間後，須閉上眼睛休息，以維護視力。"]],"開創":[["ㄎㄞ ㄔㄨㄤˋ","創建、創立。[例]我們要憑著自己的雙手，開創美好的明天。"]],"開動":[["ㄎㄞ ㄉㄨㄥˋ","開始進行、運轉。[例]只要機器能順利開動，這批貨物應可如期交付買主。"]],"開卷有益":[["ㄎㄞ ㄐㄩㄢˋ ㄧㄡˇ ㄧˋ","打開書本閱讀，即能獲得好處。[例]俗話說：「開卷有益。」我們平日應勤讀好書，變化氣質。"]],"開啟":[["ㄎㄞ ㄑㄧˇ","1.打開。[例]這把鎖生鏽了，很難開啟。\n2.開創。[例]雷射技術的應用，為近代醫學發展開啟了新紀元。"]],"開始":[["ㄎㄞ ㄕˇ","1.從頭起、從某一點起。[例]公司的營運才剛開始，往後還需要全體同仁共同努力！\n2.著手進行。[例]這部長篇歷史小說才剛開始動筆，短時間內恐怕無法完成。\n3.開頭、最初的階段。[例]新工作的開始總是會遇到挫折，若能虛心學習，通常困難會迎刃而解。"]],"開導":[["ㄎㄞ ㄉㄠˇ","啟發、疏導，使明白道理。[例]經過師長的開導後，他已能坦然面對感情失敗的挫折。"]],"開幕":[["ㄎㄞ ㄇㄨˋ","1.戲劇或節目開演時拉開戲臺前的布幕。[例]戲一開幕，觀眾就被演員精湛的演技所吸引。\n2.比喻事情的開始。[例]這家商店開幕時備有精美紀念品贈送顧客。"]],"開庭":[["ㄎㄞ ㄊㄧㄥˊ","係指於訴訟程序中審判長，受命推事或受託推事，檢察官會合當事人及其他訴訟關係人於一定場所進行的訴訟行為。[例]這件案子將於今日在高等法院開庭審理。"]],"開心":[["ㄎㄞ ㄒㄧㄣ","快樂、高興。[例]看見學生學有所成，是每位老師最開心的事。"]],"開拓":[["ㄎㄞ ㄊㄨㄛˋ","開發、拓展。[例]這次我們到海外開拓市場，對公司的前途影響很大，希望大家盡力而為。"]],"開挖":[["ㄎㄞ ㄨㄚ","動工挖掘。[例]為整治下水道，工人近日將在各處路面開挖動工。"]],"開朗":[["ㄎㄞ ㄌㄤˇ","1.明亮、開闊。[例]一眨眼之間，太陽已升上山頭，天色豁然開朗。\n2.豁達、樂觀。[例]他生性積極開朗，必能勇敢面對失敗的打擊，你就別太過擔心了。"]],"開獎":[["ㄎㄞ ㄐㄧㄤˇ","揭曉中獎號碼或中獎人。[例]每逢獎券開獎之日，許多人都熱切盼望能中大獎。"]],"開端":[["ㄎㄞ ㄉㄨㄢ","開始、起始。[例]七七事變是中日戰爭的開端。"]],"開罐器":[["ㄎㄞ ㄍㄨㄢˋ ㄑㄧˋ","用來開啟罐頭的工具。[例]他用開罐器打開一罐鳳梨請大家品嘗。　◎"]],"開胃":[["ㄎㄞ ㄨㄟˋ","增進食慾。[例]泡菜可以開胃，具有增進食慾的功效。"]],"開釋":[["ㄎㄞ ㄕˋ","釋放。[例]經過多方調查之後，檢方確定他是受到誣告，因此判他無罪開釋。"]],"開銷":[["ㄎㄞ ㄒㄧㄠ","花費，支付費用。[例]她習慣將每日的開銷逐項記錄，以了解每月支出的狀況。"]],"開鑼":[["ㄎㄞ ㄌㄨㄛˊ","1.戲劇開演前敲打鑼鼓，表示即將開演，以吸引觀眾前往欣賞。[例]這個劇團享譽國際，還沒開鑼，排隊等著進場看戲的人已綿延幾百公尺。\n2.代指事情的開始。[例]今年藝術季已經開鑼了，大家將可欣賞到一系列戲劇、音樂等精彩演出。"]],"開闊":[["ㄎㄞ ㄎㄨㄛˋ","寬廣平坦而無障礙。[例]遠眺開闊的海洋，胸襟自然就舒坦起來。"]],"開闢":[["ㄎㄞ ㄆㄧˋ","開拓、創立。[例]由於旅遊風氣日盛，各航空公司競相開闢新航線。"]],"開頭":[["ㄎㄞ ㄊㄡˊ","開始。[例]萬事開頭難，只要妳能堅毅沉著，處理得當，以後就會漸入佳境了。"]],"閒散":[["ㄒㄧㄢˊ ㄙㄢˇ","清閒少事。[例]他的生活一向很閒散，讓勞碌的我羨慕不已。"]],"閒暇":[["ㄒㄧㄢˊ ㄒㄧㄚˊ","沒有事的時候。[例]他常利用閒暇到美術館參觀畫展。"]],"閒置":[["ㄒㄧㄢˊ ㄓˋ","閒放在一旁。[例]他近來忙於交際應酬，圖書筆硯因而閒置生塵。"]],"閒逛":[["ㄒㄧㄢˊ ㄍㄨㄤˋ","漫無目的的隨意走走。[例]放學時趕快回家，不要到處閒逛。"]],"閒適":[["ㄒㄧㄢˊ ㄕˋ","悠閒安適。[例]他退休之後就隱居鄉下，過著閒適的生活。"]],"間斷":[["ㄐㄧㄢˋ ㄉㄨㄢˋ","中斷而不連續。[例]每天早上天未亮就起床的習慣，三十年來從未間斷過。"]],"間隔":[["ㄐㄧㄢˋ ㄍㄜˊ","事物在時間或空間上的距離。[例]這一排路樹每棵間隔十公尺。"]],"間隙":[["ㄐㄧㄢˋ ㄒㄧˋ","空隙。[例]這兩塊木頭接合得極緊密，幾乎一點間隙也沒有。"]],"間雜":[["ㄐㄧㄢˋ ㄗㄚˊ","錯雜。[例]花園裡，五顏六色的花朵相間雜，煞是好看。"]],"閣樓":[["ㄍㄜˊ ㄌㄡˊ","建築於屋內的夾層矮樓。[例]她將閣樓闢為儲藏室，收放一些不常用的家具。"]],"閱兵":[["ㄩㄝˋ ㄅㄧㄥ","檢閱軍隊。[例]閱兵是展現軍力、驗收部隊訓練成果的最佳途徑。"]],"閱歷":[["ㄩㄝˋ ㄌㄧˋ","經歷、經驗。[例]他在商場上閱歷豐富，這項業務交給他做準沒錯。"]],"閱覽":[["ㄩㄝˋ ㄌㄢˇ","觀看、閱讀。[例]圖書館裡有許多書籍、期刊可供閱覽。"]],"閱讀":[["ㄩㄝˋ ㄉㄨˊ","閱覽誦讀。[例]他有每日晨間閱讀書報的習慣。"]],"闔上":[["ㄏㄜˊㄕㄤˋ","閉上、合攏起來。[例]他闔上雙眼，細細聆聽山林間的蟲鳴鳥叫。"]],"闔府":[["ㄏㄜˊ ㄈㄨˇ","尊稱別人的全家人。[例]闔府光臨"]],"闖禍":[["ㄔㄨㄤˇ ㄏㄨㄛˋ","肇事生非，惹起禍端。[例]他每次闖禍後就逃之夭夭，完全沒有負責任的態度。"]],"闖進":[["ㄔㄨㄤˇ ㄐㄧㄣˋ","1.未經允許就擅自進入。[例]為了防範小偷闖進屋內行竊，屋主特別加裝了兩道門鎖。_x000D_\n2.通過關卡，挺進到比賽的下一階段。[例]闖進會內賽、闖進季後賽、闖進總決賽"]],"闖關":[["ㄔㄨㄤˇ ㄍㄨㄢ","通過關口、考驗。[例]這項遊戲共有十六個人闖關，只有六個人成功。"]],"關係":[["ㄍㄨㄢ ㄒㄧˋ","1.人事物間的關連情形。[例]親密關係、親子關係、主從關係\n2.對相關事物的影響、牽涉。[例]這件事關係重大，我們一定要小心處理。\n3.泛指原因、條件等。[例]由於強烈颱風來襲的關係，今天各級學校都停課一天。"]],"關懷":[["ㄍㄨㄢ ㄏㄨㄞˊ","關心、牽掛。[例]人人互相關懷，彼此體諒，世界將變得更美好。"]],"關燈":[["ㄍㄨㄢ ㄉㄥ","熄燈，關上電燈。[例]為了節約能源，請隨手關燈！"]],"關聯":[["ㄍㄨㄢ ㄌㄧㄢˊ","關係連屬。[例]警方找出多條有關聯的線索，順利偵破這件命案。"]],"關鍵":[["ㄍㄨㄢ ㄐㄧㄢˋ","門閂。事物最重要的部分。[例]命案現場的打火機是破案的關鍵，警方憑著上面的指紋將凶手繩之以法。"]],"關門":[["ㄍㄨㄢ ㄇㄣˊ","1.把門關上。[例]冷氣開放中，請隨手關門！\n2.指商業機構倒閉。[例]那家公司因為經營不善，早已關門了。"]],"闢謠":[["ㄆㄧˋ ㄧㄠˊ","澄清謠言，說明事情的真相。[例]這件事鬧得滿城風雨，他不得不出面闢謠。"]],"防備":[["ㄈㄤˊ ㄅㄟˋ","提防戒備。[例]最近小偷猖獗，我們要多加防備。"]],"防塵":[["ㄈㄤˊ ㄔㄣˊ","防止灰塵。[例]紗窗不但可以防蚊，更兼具有防塵的功效。"]],"防守":[["ㄈㄤˊ ㄕㄡˇ","防護守衛。[例]這裡是戰地前線，防守十分森嚴。"]],"防止":[["ㄈㄤˊ ㄓˇ","預先防備遏止。[例]防止火災，人人有責。"]],"防潮":[["ㄈㄤˊ ㄔㄠˊ","1.防止潮溼。[例]為了防潮，他特地在箱子裡放了些乾燥劑。\n2.防止潮水入侵。[例]築堤可以防潮。"]],"防衛":[["ㄈㄤˊ ㄨㄟˋ","防護和保衛。[例]軍事禁地防衛森嚴，閒人莫入。"]],"防震":[["ㄈㄤˊ ㄓㄣˋ","防備建築物、機器、儀表等免因震動而受損。[例]臺灣位於太平洋地震帶上，防震的措施尤為重要。"]],"阻撓":[["ㄗㄨˇ ㄋㄠˊ","故意妨礙、阻攔。[例]他們受到現實環境的阻撓而無法結為連理。"]],"阻擋":[["ㄗㄨˇ ㄉㄤˇ","阻止、抵擋。[例]任何困難都阻擋不了他繼續上進求學的決心。"]],"阻斷":[["ㄗㄨˇ ㄉㄨㄢˋ","因阻礙而中斷。[例]一場暴風雨沖毀道路，阻斷了村裡對外的交通。"]],"阻止":[["ㄗㄨˇ ㄓˇ","阻攔、制止。[例]小弟在家中玩火，幸好被母親及時阻止。"]],"阻礙":[["ㄗㄨˇ ㄞˋ","阻擋、妨礙。[例]前面的車子拋錨阻礙了交通，造成大塞車。"]],"阻隔":[["ㄗㄨˇ ㄍㄜˊ","阻礙隔絕。[例]空間的距離雖然阻隔了他們見面的機會，但彼此的感情並不曾稍減。"]],"阿姨":[["ㄚ ㄧˊ","稱謂：(1) 用以稱母親的姊妹。[例]阿姨與姨丈常送我一些衣服玩具。　△姨媽　(2) 通稱與母親年紀差不多的女子。[例]阿姨！請問兒童讀物擺在那邊？"]],"阿婆":[["ㄚ ㄆㄛˊ","1.對年長婦人的通稱。 [例]市場賣菜的阿婆，經常天未亮就準備好做生意了。_x000D_\n2.指祖母。"]],"陀螺":[["ㄊㄨㄛˊ ㄌㄨㄛˊ","一種木頭製的圓錐形玩具。下端有鐵尖，圍繞上繩子後，急甩出去，落地後就能在地上直立旋轉。[例]王先生是玩大陀螺的能手，每次表演，總吸引大批人潮圍觀。　◎"]],"附和":[["ㄈㄨˋ ㄏㄜˋ","依隨他人意見應和之。[例]大家與他所見略同，於是紛紛附和他的提議。"]],"附屬":[["ㄈㄨˋ ㄕㄨˇ","依附隸屬。[例]附屬中學"]],"附添":[["ㄈㄨˋ ㄊㄧㄢ","附帶添加。[例]這桌酒席，主菜之外，附添兩道甜點。"]],"附設":[["ㄈㄨˋ ㄕㄜˋ","附帶設置。[例]本工廠附設托兒所，照顧員工子女，使其無後顧之憂。"]],"附贈":[["ㄈㄨˋ ㄗㄥˋ","附帶贈送。[例]這組碗盤是購買冷氣機所附贈的。"]],"附近":[["ㄈㄨˋ ㄐㄧㄣˋ","距離不遠的地方。[例]媽媽要我到附近的雜貨店買醬油。"]],"陌生":[["ㄇㄛˋ ㄕㄥ","不認識或不熟悉的。[例]這個人看起來很陌生，一定不是本地人。"]],"陌生人":[["ㄇㄛˋ ㄕㄥ ㄖㄣˊ","不認識或不熟悉的人。[例]小張為人熱心，即使是陌生人找他幫忙，也從不拒絕。"]],"降伏":[["ㄒㄧㄤˊ ㄈㄨˊ","制伏、使馴服。[例]他費了好大的工夫，才把那匹野馬降伏。"]],"降低":[["ㄐㄧㄤˋ ㄉㄧ","下降。[例]氣溫降低、水位降低"]],"降價":[["ㄐㄧㄤˋ ㄐㄧㄚˋ","降低價格。[例]每年換季期間，百貨服飾業都會大打折扣，降價促銷。"]],"降服":[["ㄐㄧㄤˋ ㄈㄨˊ","古代指喪服降低一等為「降服」。如子女為父母服三年之喪，若已過繼給他人或出嫁，則對於親生父母只服一年之喪，即屬「降服」。[例]雖然自幼過繼給別人當義子，但在親生父母過世時，仍應回家行降服之禮。"],["ㄒㄧㄤˊ ㄈㄨˊ","1.投降、屈服。[例]他們精湛的舞技，讓前來踢館的幾支隊伍無不降服。\n2.制服、使服從。[例]精忠報國的岳飛，精通兵法，用兵如神，曾多次降服頑敵。"]],"降溫":[["ㄐㄧㄤˋ ㄨㄣ","1.降低溫度。[例]這種食品是在真空狀態下，以急速降溫殺菌的處理方式包裝而成，請消費者安心食用。\n2.使事情和緩、平穩下來。[例]由於他的調解，才使得這場衝突得以降溫，沒有造成傷害。\n3.比喻事物發展的程度降低或減緩。[例]腸病毒通常出現在四月，在五、六月達到高峰，到了七、八月以後逐漸降溫。"]],"降級":[["ㄐㄧㄤˋ ㄐㄧˊ","由較高的等級降到較低的等級。[例]他因所承辦的事務頻出狀況，而遭降級處分。"]],"降臨":[["ㄐㄧㄤˋ ㄌㄧㄣˊ","來到、來臨。[例]這個小生命的降臨，為家裡帶來了無限的歡樂。"]],"降落":[["ㄐㄧㄤˋ ㄌㄨㄛˋ","落下、下降。[例]飛機在天上盤旋了幾圈後，安全的降落在跑道上。"]],"限制":[["ㄒㄧㄢˋ ㄓˋ","1.在一定的範圍之內，不許超過。[例]他因涉嫌這起命案，被警方限制出境。\n2.一定的界限、範圍。[例]糖尿病患者每天對於糖分的攝取應有一定的限制，才不致增加腎臟的負荷。"]],"限期":[["ㄒㄧㄢˋ ㄑㄧˊ","1.限定日期，不許超過。[例]限期改善、限期完工\n2.所限定的日期。[例]本館所出借的圖書，若超過限期歸還，將處以罰金。"]],"陡峭":[["ㄉㄡˇ ㄑㄧㄠˋ","高峻且坡度大。[例]山勢陡峭"]],"院子":[["ㄩㄢˋ ˙ㄗ","庭院。[例]夏夜時，我們全家人喜歡在院子裡乘涼、聊天。"]],"陣容":[["ㄓㄣˋ ㄖㄨㄥˊ","隊伍的外觀氣勢，或成員配置的情形。[例]陣容浩大、陣容堅強"]],"陣營":[["ㄓㄣˋ ㄧㄥˊ","因共同的目標或利益而聯合起來的團體。[例]我們要結合大眾的力量，擴大環保陣營。"]],"陣痛":[["ㄓㄣˋ ㄊㄨㄥˋ","有時發作有時停止，斷斷續續的疼痛。多指產婦分娩過程中，因子宮規則收縮所造成的一陣一陣的疼痛。[例]那名產婦經過劇烈的陣痛後，順利產下一名白胖的嬰兒。"]],"陣陣":[["ㄓㄣˋ ㄓㄣˋ","時有時無，斷斷續續的。[例]花園裡的百花盛開，陣陣花香撲鼻而來。"]],"除夕":[["ㄔㄨˊ ㄒㄧˋ","農曆十二月最後一天的夜晚。也泛指一年的最後一天。[例]除夕是全家團圓吃年夜飯的日子。"]],"除非":[["ㄔㄨˊ ㄈㄟ","表示唯一的條件。即只有、唯有的意思。[例]若要人不知，除非己莫為。"]],"陪伴":[["ㄆㄟˊ ㄅㄢˋ","相陪作伴。[例]當我生病時，母親都一直陪伴在我身旁。"]],"陪同":[["ㄆㄟˊ ㄊㄨㄥˊ","陪伴、伴同。[例]他常在假日陪同母親到市場買菜。"]],"陰森森":[["ㄧㄣ ㄙㄣ ㄙㄣ","幽黯的樣子。[例]這片陰森森的叢林，即使是大白天，走過去，還是挺嚇人的！"]],"陰霾":[["ㄧㄣ ㄇㄞˊ","1.形容天氣陰沉、晦暗。[例]新聞報導今天將出現大太陽，可望遠離連日來陰霾的天氣。_x000D_\n2.比喻陰鬱不快的神色。[例]他一接獲捷報，頓掃多日來臉上的層層陰霾。"]],"陳列":[["ㄔㄣˊ ㄌㄧㄝˋ","擺出供人觀賞。[例]從博物館所陳列的展品中，可一窺古代文字的演變。"]],"陳設":[["ㄔㄣˊ ㄕㄜˋ","1.陳列、擺設。[例]小坪數的住家最好陳設簡單，以免顯得過於凌亂。\n2.陳列的物品。[例]他平日深居簡出，屋內的一切陳設也十分簡樸。"]],"陳述":[["ㄔㄣˊ ㄕㄨˋ","敘述、說明。[例]醫生依據病人陳述的症狀來診斷病情。"]],"陵墓":[["ㄌㄧㄥˊ ㄇㄨˋ","帝王或諸侯的墳墓。[例]古代帝王的陵墓大多成了今日觀光的賣點。"]],"陵寢":[["ㄌㄧㄥˊ ㄑㄧㄣˇ","古代帝王的墳墓。今亦用以尊稱國家領袖的墓地。[例]慈湖陵寢"]],"陶器":[["ㄊㄠˊ ㄑㄧˋ","用陶土燒製的器物。坯質不透明，具吸水性，焙燒溫度較瓷器低，質地較瓷器粗糙，可塗上不同的顏色或彩色花紋。[例]陶器的形制、花紋等特徵常是考古學上重要斷代依據。"]],"陶醉":[["ㄊㄠˊ ㄗㄨㄟˋ","為某種事物或境界而沉迷如醉。[例]我們趁著花季到陽明山去踏青，不知不覺的陶醉在明媚的春光裡。"]],"陷入":[["ㄒㄧㄢˋ ㄖㄨˋ","進入某一種狀況中。[例]陷入絕境、陷入沉思"]],"陷阱":[["ㄒㄧㄢˋ ㄐㄧㄥˇ","1.為捉捕野獸而掘的坑穴。[例]為保育稀有野生動物，不可任意挖掘陷阱加以捕殺。\n2.害人的計謀。[例]這人心術不正，小心掉入他的陷阱中。"]],"陸橋":[["ㄌㄨˋ ㄑㄧㄠˊ","1.架設在道路上空，供行人穿越道路的橋梁。[例]行人穿越馬路應走陸橋或地下道。　△人行天橋\n2.在各個地質年代中，連結大陸地塊的地峽。通過地峽，動植物乃得以擴大分布至新的地區。[例]巴拿馬地峽是連接北美、南美的重要陸橋。"]],"陽傘":[["ㄧㄤˊ ㄙㄢˇ","用來遮避陽光的傘。[例]夏天出門撐把陽傘，可避免陽光直接照射皮膚，而受到傷害。　△旱傘"]],"陽光":[["ㄧㄤˊ ㄍㄨㄤ","太陽的光線。[例]陽光充足、陽光燦爛"]],"陽臺":[["ㄧㄤˊ ㄊㄞˊ","樓面中無牆壁遮蔽的空間。周圍多設有防護的欄杆或矮牆，可在此遠眺、乘涼或曝晒衣物。[例]媽媽在陽臺上種了許多盆花樹，美化住家環境。"]],"隊伍":[["ㄉㄨㄟˋ ㄨˇ","1.排列成行的人群。[例]遊行隊伍\n2.團體、組織。[例]他因有感於生態環境遭到嚴重破壞，而矢志加入環保隊伍。"]],"階層":[["ㄐㄧㄝ ㄘㄥˊ","整體事物中，依不同的特性所劃分的層次，在同一層次中，其個體大多具有某種共通性。[例]中上階層"]],"隔壁":[["ㄍㄜˊ ㄅㄧˋ","旁邊、相鄰的屋舍或人家。[例]他家的隔壁就是超商，買東西很方便。"]],"隔天":[["ㄍㄜˊ ㄊㄧㄢ","第二天。[例]他下午才趕回家鄉投票，隔天一早又要馬上回公司上班。"]],"隔板":[["ㄍㄜˊ ㄅㄢˇ","用來間隔空間的夾板。[例]她們決定拆掉房屋內的隔板，增加室內的使用空間。"]],"隕石":[["ㄩㄣˇ ㄕˊ","在太空中飄浮或穿過氣層而墜落至其他星球的石塊或金屬物體。[例]墜落在地球的隕石，小者如塵埃，大者其撞擊力可在地表上造成巨大的坑洞。"]],"隕落":[["ㄩㄣˇ ㄌㄨㄛˋ","1.從高空掉落。[例]流星劃過天際，不知隕落何方。\n2.比喻死亡。[例]這位影壇巨星的隕落，帶給影迷莫大的悲傷懷念。"]],"際遇":[["ㄐㄧˋ ㄩˋ","遭遇，多指碰到好的機會。[例]他得到上司賞識，而大展長才，際遇真是不錯。"]],"障礙":[["ㄓㄤˋ ㄞˋ","阻礙。也指阻擋通行的東西。[例]網路科技讓我們突破空間障礙，得以隨時隨地和全世界的人互動溝通。"]],"隧道":[["ㄙㄨㄟˋ ㄉㄠˋ","貫穿山脈、海峽、河道或地下，供行人、車輛等通行的通道。[例]這條隧道貫通兩地交通，從此人車不必再繞山而行。"]],"隨即":[["ㄙㄨㄟˊ ㄐㄧˊ","馬上、緊接著。[例]對本產品若有疑問，歡迎來電，本公司將隨即作進一步說明。"]],"隨和":[["ㄙㄨㄟˊ ㄏㄜˊ","性情溫和，容易相處。[例]她的個性隨和，同學們都喜歡接近她。"]],"隨從":[["ㄙㄨㄟˊ ㄗㄨㄥˋ","跟隨的人。[例]古代的權貴出門總是帶著一群隨從。"],["ㄙㄨㄟˊ ㄘㄨㄥˊ","跟隨、跟從。[例]我們隨從導遊，到處參觀。"]],"隨時":[["ㄙㄨㄟˊ ㄕˊ","1.不論何時。[例]只要你需要，隨時都可以找我來幫忙。_x000D_\n2.順應時代的情勢。[例]社會變遷快速，法令應隨時順變，以符合民眾需求。"]],"隨機應變":[["ㄙㄨㄟˊ ㄐㄧ ㄧㄥˋ ㄅㄧㄢˋ","臨事能跟著情況的改變而採取靈活的處置。[例]做事要懂得隨機應變，才能圓滿通達。"]],"隨身":[["ㄙㄨㄟˊ ㄕㄣ","帶在身上。[例]她隨身掛著母親從廟裡求來的平安符。"]],"隨遇而安":[["ㄙㄨㄟˊ ㄩˋ ㄦˊ ㄢ","能安於所處的環境。[例]智者處逆境而能隨遇而安。"]],"險惡":[["ㄒㄧㄢˇ ㄜˋ","凶險可怕。[例]山勢險惡、人心險惡、處境險惡"]],"隱含":[["ㄧㄣˇ ㄏㄢˊ","暗藏、不直接呈現。[例]在他成功的背後，其實隱含了許多努力奮鬥的艱辛。"]],"隱喻":[["ㄧㄣˇ ㄩˋ","一種以兩物之間的相似性來作間接暗示的比喻的修辭法。相對於明喻而言。隱喻可使讀者發揮想像力。如徐志摩〈偶然〉中「我是天空裡的一片雲，偶爾投影在你的波心。」將自己當作是飄忽不定的雲，藉以比喻人事的偶然與不經意。"]],"隱形":[["ㄧㄣˇ ㄒㄧㄥˊ","隱藏形體。[例]魔術師將自己身軀隱形的單元，是這場表演的壓軸。"]],"隱惡揚善":[["ㄧㄣˇ ㄜˋ ㄧㄤˊ ㄕㄢˋ","隱藏他人的過失，宣揚他人的善行。語本《禮記．中庸》。[例]他為人厚道，待人處事總是隱惡揚善，深得眾人的敬佩。"]],"隱瞞":[["ㄧㄣˇ ㄇㄢˊ","瞞住，不讓別人知道。[例]他不隱瞞自己的過錯，表現出勇於負責的態度。"]],"隱約":[["ㄧㄣˇ ㄩㄝ","不清楚、不明顯的樣子。[例]雖然四周瀰漫著濃霧，但遠處的燈火仍隱約可見。"]],"隱蔽":[["ㄧㄣˇ ㄅㄧˋ","隱藏、遮掩。[例]玩捉迷藏時，小朋友總是費心的利用各種可以隱蔽的地方把自己藏起來。"]],"隱隱":[["ㄧㄣˇ ㄧㄣˇ","不清楚、不明顯的樣子。[例]昨晚不小心被刀子割到的傷口，今天仍然隱隱作痛。"]],"隸屬":[["ㄌㄧˋ ㄕㄨˇ","從屬，受管轄。[例]中央研究院是直接隸屬於總統府的學術機構。"]],"隻身":[["ㄓ ㄕㄣ","單身、獨自一人。[例]這個警察智勇雙全，常常隻身擒獲歹徒，令人激賞。"]],"雀屏中選":[["ㄑㄩㄝˋ ㄆㄧㄥˊ ㄓㄨㄥˋ ㄒㄩㄢˇ","比喻被選中為女婿。典出《舊唐書．卷五一．后妃列傳上．高祖太穆皇后竇氏》。[例]王先生的才華獲得佳人青睞，使他雀屏中選，成為張董事長的乘龍快婿。"]],"雀斑":[["ㄑㄩㄝˋ ㄅㄢ","因日晒或遺傳等所引起的局部色素沉澱，呈現於人體皮膚上的褐色細點。"]],"雀躍":[["ㄑㄩㄝˋ ㄩㄝˋ","形容高興得像雀鳥般跳躍。[例]他得知高中榜首後，雀躍萬分。"]],"雄渾":[["ㄒㄩㄥˊ ㄏㄨㄣˊ","雄壯渾厚。[例]岳飛的〈滿江紅〉，詞句雄渾，豪氣萬千。"]],"雅致":[["ㄧㄚˇ ㄓˋ","1.風雅的意興。[例]既然大家有這個雅致，就結伴同遊吧！\n\t\n2.高雅、秀逸。大多指風景或顏色、裝飾等。[例]這房間雖無貴重的擺設，卻布置得十分雅致。"]],"集中":[["ㄐㄧˊ ㄓㄨㄥ","集合、匯聚在一起。[例]市政府將流動攤販集中於特定地點，以便管理。"]],"集合":[["ㄐㄧˊ ㄏㄜˊ","聚在一起。[例]十分鐘後請同學們到操場集合，校長有事要對大家宣布。"]],"雋才":[["ㄐㄩㄣˋ ㄘㄞˊ","才能出眾的人。[例]這所學校秉持著因材施教的理念，培養出各種雋才。"]],"雋永":[["ㄐㄩㄢˋ ㄩㄥˇ","意義深長而耐人尋味。[例]他的詩作頗負盛名，短詩尤以清新雋永見稱。"]],"雕像":[["ㄉㄧㄠ ㄒㄧㄤˋ","以人物為題材的雕刻作品，通常以銅、大理石、木材為材料。[例]這尊雕像真是栩栩如生，極為傳神。"]],"雕塑":[["ㄉㄧㄠ ㄙㄨˋ","1.雕刻塑造。[例]這尊石膏像雕塑得栩栩如生，十分逼真。_x000D_\n2.雕刻塑造成的藝術作品。[例]公園裡的雕塑出於大師手筆，極具藝術價值。"]],"雕梁畫棟":[["ㄉㄧㄠ ㄌㄧㄤˊ ㄏㄨㄚˋ ㄉㄨㄥˋ","梁上雕刻，棟上彩繪，形容建築物富麗堂皇。[例]有些寺廟，雕梁畫棟，極具古代建築特色。"]],"雖然":[["ㄙㄨㄟ ㄖㄢˊ","縱然、即使。[例]雖然這件工作很辛苦，但對年輕人來說是一個很好的磨鍊。"]],"雙倍":[["ㄕㄨㄤ ㄅㄟˋ","兩倍。[例]他以雙倍的價錢買下拍賣的骨董。"]],"雙數":[["ㄕㄨㄤ ㄕㄨˋ","偶數。如 2、 4、 6、 8、10。"]],"雙方":[["ㄕㄨㄤ ㄈㄤ","相對待的兩方。[例]勞資雙方、買賣雙方、檢警雙方"]],"雙胞胎":[["ㄕㄨㄤ ㄅㄠ ㄊㄞ","1.自一母體同一次產下的兩個胎兒。有同卵雙胞胎及異卵雙胞胎之分別。[例]他們是雙胞胎兄弟，身材和性情都很類似。　△孿生子、孿子、雙生子\n2.比喻非常相似的人、事、物。[例]這兩件案子的手法如出一轍，簡真是雙胞胎。"]],"雙脣":[["ㄕㄨㄤ ㄔㄨㄣˊ","上、下嘴脣。[例]他凍得雙脣發紫，全身顫抖。"]],"雙腳":[["ㄕㄨㄤ ㄐㄧㄠˇ","兩隻腳。[例]他的雙腳靈活而有力。"]],"雙面":[["ㄕㄨㄤ ㄇㄧㄢˋ","泛指人、事、物的正反兩面。[例]雙面人、雙面膠帶、雙面間諜"]],"雛形":[["ㄔㄨˊ ㄒㄧㄥˊ","事物初步發展的規模、形態。[例]這個構想僅初具雛形，具體內容有待進一步研議。"]],"雛菊":[["ㄔㄨˊ ㄐㄩˊ","植物名。菊科雛菊屬，多年生草本。植株矮小，莖甚短，葉呈倒卵形，花色繁多，花朵嬌小，性耐寒，極易繁殖。適合栽培於花盆、花壇，可當觀賞植物。　◎"]],"雜亂":[["ㄗㄚˊ ㄌㄨㄢˋ","混雜凌亂的樣子。[例]他日夜繁忙，疏於打理家務，屋內雜亂不堪。"]],"雜燴":[["ㄗㄚˊ ㄏㄨㄟˋ","1.以各種菜餚燴製的菜。[例]這道大雜燴內容豐富，味道也不錯。\n2.比喻雜亂拼湊而成的事物。[例]這篇散文純屬雜燴，毫無章法可言。"]],"雜草叢生":[["ㄗㄚˊ ㄘㄠˇ ㄘㄨㄥˊ ㄕㄥ","野草生長得很多。[例]後院荒廢已久，處處雜草叢生。"]],"雜誌":[["ㄗㄚˊ ㄓˋ","含有多類文章，定期出版的刊物。[例]圖書室內放有多種雜誌，可供讀者自由翻閱。"]],"雜質":[["ㄗㄚˊ ㄓˊ","不屬於該物的成分。[例]未經過濾的水，含有許多雜質，飲用後可能對身體有害。"]],"雞冠":[["ㄐㄧ ㄍㄨㄢ","雞頭上高起的肉冠。[例]公雞與母雞最大的分別便是公雞有一比母雞高起豐厚的雞冠。◎"]],"雞毛蒜皮":[["ㄐㄧ ㄇㄠˊ ㄙㄨㄢˋ ㄆㄧˊ","比喻沒有價值、不重要的小事。[例]他們夫妻倆常為了一些雞毛蒜皮的小事吵架。"]],"離島":[["ㄌㄧˊ ㄉㄠˇ","不與附近大陸塊相連的島嶼。[例]澎湖周圍的離島風光，景色怡人，遊客絡繹不絕。"]],"離群索居":[["ㄌㄧˊ ㄑㄩㄣˊ ㄙㄨㄛˇ ㄐㄩ","離開群體，獨自生活。[例]他個性孤僻，長年過著離群索居的生活。"]],"離鄉背井":[["ㄌㄧˊ ㄒㄧㄤ ㄅㄟˋ ㄐㄧㄥˇ","離開故鄉，在外地生活。[例]逢年過節，離鄉背井的遊子總是格外思念親人。"]],"離開":[["ㄌㄧˊ ㄎㄞ","與人、物或地方分開。[例]魚一離開水，很快就會死亡。"]],"難以言喻":[["ㄋㄢˊ ㄧˇ ㄧㄢˊ ㄩˋ","無法以言語形容。[例]他經過三年的努力，終於考上理想中的學校，興奮之情難以言喻。"]],"難保":[["ㄋㄢˊ ㄅㄠˇ","不敢斷定、不能保證。[例]你再這樣開快車，難保那一天不會出事。"]],"難受":[["ㄋㄢˊ ㄕㄡˋ","傷心難過。[例]聽到同學車禍身亡的不幸消息，她的心裡十分難受。"]],"難堪":[["ㄋㄢˊ ㄎㄢ","1.難以忍受。[例]你說這麼多讓他難堪的話，難怪他會拂袖而去。\n2.尷尬、受窘。[例]他一回頭，我才知道認錯了人，真難堪！"]],"難得":[["ㄋㄢˊ ㄉㄜˊ","1.不易獲得。[例]難得易失\n2.可貴。表示值得珍惜。[例]闊別多年之後，還能齊聚一堂，真是難得。"]],"難看":[["ㄋㄢˊ ㄎㄢˋ","1.不好看、醜陋。[例]這部電影儘是些打打殺殺的場面，真難看！\n2.不光彩、不名譽。[例]他上學期因為貪玩而耽誤了功課，成績單上布滿紅字，實在難看。"]],"難聽":[["ㄋㄢˊ ㄊㄧㄥ","1.不好聽、不悅耳。[例]他唱歌五音不全的，真是難聽！\n2.不光榮、不體面。[例]這種不名譽的事情說出去多難聽啊！"]],"難言之隱":[["ㄋㄢˊ ㄧㄢˊ ㄓ ㄧㄣˇ","藏在內心深處難以說出口的事情。[例]這件事的處理方式不像你一貫的作風，是不是有什麼難言之隱？"]],"難過":[["ㄋㄢˊ ㄍㄨㄛˋ","1.不容易度過。[例]年關將近，他卻失業，這個年恐怕會很難過了。\n2.傷心、難受。[例]親人逝世，他心裡非常難過。"]],"難道":[["ㄋㄢˊ ㄉㄠˋ","加強反問語氣的副詞，即莫非的意思。[例]我分析了這麼多的道理，難道你一句都沒有聽進去嗎？"]],"難關":[["ㄋㄢˊ ㄍㄨㄢ","不易度過的關頭或具有決定性的重要時期。[例]這次多虧員工同心協力，公司才得以度過難關，避免了倒閉的噩運。"]],"難題":[["ㄋㄢˊ ㄊㄧˊ","不容易解決的問題。[例]他做事一向不計較成敗得失，面對再大的難題也絕不退縮。"]],"雨傘":[["ㄩˇ ㄙㄢˇ","遮雨用的傘。多用油紙、油布或塑膠布料等製成。[例]梅雨季節期間，出門時最好隨身攜帶雨傘。"]],"雨後春筍":[["ㄩˇ ㄏㄡˋ ㄔㄨㄣ ㄙㄨㄣˇ","春天下過雨後，竹筍長得又快又多。比喻事物在某一時期大量湧現、迅速發展。[例]最近這幾年，高樓大廈如雨後春筍般地聳立在街頭。"]],"雨水":[["ㄩˇ ㄕㄨㄟˇ","1.二十四節氣之一。在國曆二月十九或二十日。[例]每年在雨水之後，降雨量會增加。\n2.雨。[例]今年的雨水豐沛，所以農作物的收成也特別好。　△雨水兒"]],"雨衣":[["ㄩˇ ㄧ","遮雨的外衣。[例]雨衣應挑選鮮明的顏色，以利辨識，並進而維護交通安全。"]],"雪上加霜":[["ㄒㄩㄝˇ ㄕㄤˋ ㄐㄧㄚ ㄕㄨㄤ","比喻禍患接踵而至，使傷害加重。語本《景德傳燈錄．卷八．大陽和尚》。[例]他的事業垮了，健康又出了問題，真是雪上加霜。"]],"雪亮":[["ㄒㄩㄝˇ ㄌㄧㄤˋ","雪般明亮。[例]選民的眼睛是雪亮的，譁眾取寵的候選人終會被鄙棄。"]],"雪人":[["ㄒㄩㄝˇ ㄖㄣˊ","1.用雪堆成的人形。[例]雪停後，一群孩子在院子裡堆雪人玩。\n2.二十世紀有很多探險家，在歐亞兩洲海拔五千公尺以上終年積雪的高山探險，見到行走很快，類似人猿的龐然怪物，稱為「雪人」。[例]雪人的存在與否，至今仍是個謎。"]],"雪橇":[["ㄒㄩㄝˇ ㄑㄧㄠ","1.利用長條形平滑板塊在雪地上滑行的無輪交通工具。古代多由狗或鹿等動物拉動，現有以機械帶動的。[例]據說，聖誕老公公在聖誕夜會駕著雪橇挨家挨戶分送禮物。　△冰橇、雪車　◎_x000D_\n2.一種運動競技項目。用木製雪橇，在人工或天然滑道上較量滑走的速度。_x000D_\n3.雪橇運動所使用的器材。以木製或玻璃纖維等材料製成。"]],"雪白":[["ㄒㄩㄝˇ ㄅㄞˊ","潔白如雪的顏色。[例]新娘子一身雪白的婚紗，象徵著純潔高貴的氣質。"]],"雪花":[["ㄒㄩㄝˇ ㄏㄨㄚ","1.從空中飄落的雪片。因雪片多呈六角形，如花一般，故稱為「雪花」。[例]一眼望去，除了雪花滿天飛舞，杳無人跡。\n2.指電視訊號變弱時，在圖像上出現如下雪般的白色斑點。[例]電視螢幕上若出現雪花，看起來令人很難受。"]],"雪茄":[["ㄒㄩㄝˇ ㄐㄧㄚ","一種將菸葉捲成長條形的煙葉製品。§英cigar[例]他習慣在飯後抽一根雪茄。"]],"雲層":[["ㄩㄣˊ ㄘㄥˊ","雲由水氣層層相疊而成，故稱為「雲層」，氣象學上亦因高低不同而有不同的名稱。[例]看今天天色昏暗且雲層很厚，恐怕會下雨吧！"]],"雲朵":[["ㄩㄣˊ ㄉㄨㄛˇ","呈團狀或塊狀的雲。[例]天上的雲朵聚散不定，變化萬千。"]],"雲霄":[["ㄩㄣˊ ㄒㄧㄠ","雲層之上，指極高的天空或天際。[例]響徹雲霄"]],"零件":[["ㄌㄧㄥˊ ㄐㄧㄢˋ","泛指各種機械設備的基本組成單位。[例]這部機器只要換些零件，就可以重新啟動了。"]],"零散":[["ㄌㄧㄥˊ ㄙㄢˇ","零碎而不成整體。[例]他常利用零散的時間背英文單字。"]],"零星":[["ㄌㄧㄥˊ ㄒㄧㄥ","零碎不成整數。[例]媽媽將零星的布料縫成一塊桌布。"]],"零用錢":[["ㄌㄧㄥˊ ㄩㄥˋ ㄑㄧㄢˊ","零碎花用的錢。[例]他習慣將每個月剩下的零用錢存在銀行。"]],"零碎":[["ㄌㄧㄥˊ ㄙㄨㄟˋ","零星細碎、不完整。[例]她常利用零碎的布塊縫製抹布。"]],"零錢":[["ㄌㄧㄥˊ ㄑㄧㄢˊ","面值小，不成整數的錢。通常指硬幣。[例]他習慣將手邊的零錢投到撲滿裡。"]],"雷同":[["ㄌㄟˊ ㄊㄨㄥˊ","本指雷聲一發萬物同時響應後。今用於人或事物間有相同之處。[例]現今電視節目內容大多雷同，了無新意，看來乏味。"]],"雷射":[["ㄌㄟˊ ㄕㄜˋ","一種以晶體、氣體、半導體的物質為介質，使光波在介質內來回反射，引起連鎖反應，放射出強化光束的裝置。可作測量、傳送、切割、焊接、打孔等工作。多用於工業、軍事和醫療手術上。§英laser [例]他的鼻病經雷射治療後根除了。　△鐳射"]],"雷池":[["ㄌㄟˊ ㄔˊ","雷池本是一條河流名稱，後用以表示某一範圍、界限。語出《晉書．卷七三．列傳．庾亮》。[例]這場足球比賽，在守門員的嚴密防守下，雙方都難越雷池一步，最後以和局收場。"]],"雷鳴":[["ㄌㄟˊ ㄇㄧㄥˊ","1.雷聲。[例]寧靜的夜裡突然傳來一陣雷鳴，把大家都嚇了一跳。\n2.形容聲音大如雷聲。[例]他那雷鳴般的鼾聲，使我一夜不能安眠。"]],"電影院":[["ㄉㄧㄢˋ ㄧㄥˇ ㄩㄢˋ","公開放映電影以供人欣賞的營利娛樂場所。[例]去電影院觀賞電影，和在家中看錄影帶有不同的視覺效果。　△影院"]],"電梯":[["ㄉㄧㄢˋ ㄊㄧ","用電力作為動力來源的升降機。[例]大樓發生火災時，絕對不可乘坐電梯，以免斷電時無法逃生。"]],"電燈":[["ㄉㄧㄢˋ ㄉㄥ","藉電流流經電阻體而發光，以用來照明的電器。如弧光燈、白熱燈、螢光燈等。[例]電燈的亮度不夠，容易損傷眼睛的視力。"]],"電線桿":[["ㄉㄧㄢˋ ㄒㄧㄢˋ ㄍㄢˇ","架設電線的桿子。通常以水泥或木頭製成。[例]此地的市內電線均埋設於地下，電線桿四處林立的現象已不復見。　△電桿、電線杆"]],"電腦":[["ㄉㄧㄢˋ ㄋㄠˇ","一種能接受資料並按照人為指示的方法處理，產生有效結果的裝置。通常由輸出入設備、中央處理器、主記憶體、算術和邏輯單元等五大部門組成。[例]在現代的社會中，電腦能迅速幫助我們處理事情。　△電子計算機　◎"]],"電話":[["ㄉㄧㄢˋ ㄏㄨㄚˋ","利用電的作用使兩地互相通話、傳達溝通的工具。其原理在將聲波轉換成電的強弱信號，傳至他處，再還原成聲波。設備包括主機、按鍵、話筒等部分。[例]利用電話拜年，可免去人車擁擠的困擾。　△電話機　◎"]],"電話亭":[["ㄉㄧㄢˋ ㄏㄨㄚˋ ㄊㄧㄥˊ","裝在公共場所供人使用電話的設施。通常分割成獨立的小空間，內裝電話。[例]在電話亭內打電話，可以免於外界的干擾。"]],"電鋸":[["ㄉㄧㄢˋ ㄐㄩˋ","以電傳動的鋸子。通常用於砍伐切割巨木。[例]使用電鋸伐木，將可節省許多人力。　◎"]],"電鑽":[["ㄉㄧㄢˋ ㄗㄨㄢˋ","電動的鑽孔機。[例]他用電鑽在牆上鑽孔，方便釘掛物品。　◎"]],"需求":[["ㄒㄩ ㄑㄧㄡˊ","有所需要、欲求的。[例]父母不能只是滿足孩子們物質上的需求，也要顧及其精神上的需要。"]],"需要":[["ㄒㄩ ㄧㄠˋ","應該要有的或必須要有的。[例]出門在外，最需要朋友的幫助。"]],"震動":[["ㄓㄣˋ ㄉㄨㄥˋ","1.物體受了外力影響而搖動。[例]地震時的劇烈震動，使得家具都倒了下來。\n2.內心受到重大的刺激而被撼動。[例]內閣倒臺，股市崩盤，都是足以震動人心的壞消息。"]],"震央":[["ㄓㄣˋ ㄧㄤ","從震源垂直延伸到地面上的一點，即震源投影到地面上的一點。一般以經緯度表示其位置。在此地區內，震動強度最大，破壞力也最強。[例]這次地震的震央在花蓮的外海。"]],"震怒":[["ㄓㄣˋ ㄋㄨˋ","大怒。[例]這次嚴重的疏失，使得上級大為震怒。"]],"震撼":[["ㄓㄣˋ ㄏㄢˋ","震動搖撼。[例]這項技術上的重大突破，對於業界造成了很大的震撼。"]],"震驚":[["ㄓㄣˋ ㄐㄧㄥ","1.使大吃一驚。[例]震驚全世界\n2.大吃一驚。[例]聽到飛機失事的消息，大家都非常震驚。"]],"霎時":[["ㄕㄚˋ ㄕˊ","指極短的時間。[例]一陣雷響後，霎時就下起傾盆大雨。"]],"露出":[["ㄌㄡˋ ㄔㄨ","顯現。[例]他露出猶豫的臉色，不知道該不該答應對方的要求。"]],"露出馬腳":[["ㄌㄡˋ ㄔㄨ ㄇㄚˇ ㄐㄧㄠˇ","暴露出真相或漏洞。[例]經過警方鍥而不捨的追查，歹徒終於露出馬腳而被逮捕歸案。"]],"露天":[["ㄌㄨˋ ㄊㄧㄢ","在室外，沒有遮蔽的。[例]露天音樂會"]],"露宿":[["ㄌㄨˋ ㄙㄨˋ","在室外過夜或露天睡覺。[例]露宿街頭"]],"露水":[["ㄌㄨˋ ㄕㄨㄟˇ","1.靠近地面的水蒸氣，遇冷而凝結成的小水滴。[例]清晨的草地上沾滿了露水。\n2.露水一經陽光曝晒，隨即蒸發，借喻短暫或偶然存在的關係。[例]露水夫妻、露水姻緣"]],"露營":[["ㄌㄨˋ ㄧㄥˊ","一種在野外搭帳蓬或簡便草屋為臨時居所的露宿活動。[例]野外露營應該隨時注意氣候變化，以免發生意外。"]],"露珠":[["ㄌㄨˋ ㄓㄨ","凝結如珠的露水。[例]清晨時，樹梢、葉間沾滿了一顆顆晶瑩的露珠。"]],"露臉":[["ㄌㄡˋ ㄌㄧㄢˇ","1.現身。[例]嫌犯一露臉，警方馬上趕往逮捕。\n2.比喻光榮、很有面子。[例]他這次在國際會議上發表論文，博得很多的掌聲，真是露臉極了。"]],"露面":[["ㄌㄡˋ ㄇㄧㄢˋ","出面、出現。[例]他的個性內向，所以很少在公共場合露面。"]],"霸主":[["ㄅㄚˋ ㄓㄨˇ","1.春秋時代指勢力最大，能夠號令天下的諸侯。[例]齊桓公是春秋時代第一位霸主。\n2.在某一方面稱雄的人或集團。[例]美國向來是國際籃壇的霸主。"]],"霸占":[["ㄅㄚˋ ㄓㄢˋ","強力占有。[例]許多商家霸占騎樓，造成行人諸多不便。"]],"霸道":[["ㄅㄚˋ ㄉㄠˋ","1.不顧仁義，而以武力、權勢、嚴刑統治的政策。[例]從歷史來看，行王道的時代，必然興盛；行霸道的時代，很快滅亡。_x000D_\n2.蠻橫不講理。[例]父母太過溺愛，容易養成小孩霸道的個性。"]],"靈感":[["ㄌㄧㄥˊ ㄍㄢˇ","思考活動中，忽然出現且超越平時思考層面的想法。[例]作文不能只靠靈感，要多方面充實生活經驗和修辭技巧，才會進步。"]],"靈敏":[["ㄌㄧㄥˊ ㄇㄧㄣˇ","靈活敏捷。[例]他的身手矯健，反應靈敏，在各種比賽中常有傑出的表現。"]],"靈機一動":[["ㄌㄧㄥˊ ㄐㄧ ㄧ ㄉㄨㄥˋ","突來的巧思或領悟。[例]他靈機一動，想出了一個巧妙的方法，順利解決問題。"]],"靈驗":[["ㄌㄧㄥˊ ㄧㄢˋ","1.預言的應驗。[例]他深諳人類心理，凡有預言，大都靈驗。\n2.具有神奇的功效。[例]用檸檬去除冰箱的異味，十分靈驗。"]],"靈魂":[["ㄌㄧㄥˊ ㄏㄨㄣˊ","1.人死後的鬼魂。[例]靈魂出竅\n2.心靈、精神。[例]有智慧的人，靈魂深處便有光。\n3.中樞的、主要的。[例]他是班上的靈魂人物。"]],"青春痘":[["ㄑㄧㄥ ㄔㄨㄣ ㄉㄡˋ","由於皮脂腺分泌過於旺盛，皮膚毛囊角質異化，造成細菌增生，使毛細孔堵塞而於皮膚產生隆起的疙瘩。常發生於青春期。　△痤瘡、粉刺"]],"青澀":[["ㄑㄧㄥ ㄙㄜˋ","1.果實生澀未成熟。[例]這些李子還未成熟，嚐起來十分青澀。\n2.形容人稚嫩、不成熟。[例]看著相片中青澀的笑容，彷彿重拾當年的流金歲月。"]],"青苔":[["ㄑㄧㄥ ㄊㄞˊ","青色的苔蘚。[例]山中潮溼陰冷，石階上布滿了青苔。"]],"青草":[["ㄑㄧㄥ ㄘㄠˇ","青綠色的草。[例]小弟在長滿青草的地上打滾，享受親近大自然的樂趣。"]],"青菜":[["ㄑㄧㄥ ㄘㄞˋ","泛指蔬菜。[例]你光吃肉不吃青菜的偏食習慣，是會影響健康的。"]],"青蛙":[["ㄑㄧㄥ ㄨㄚ","動物名。兩棲類無尾目。頭部寬扁、闊嘴、大眼。腹部呈灰白色。皮膚會分泌黏液，所以表皮光滑溼潤。足有蹼，善於跳躍、游泳。多生活在水邊，常於夜間活動。雄蛙鳴聲響亮。為一種變溫動物，因此需要冬眠。[例]蝌蚪長大後，就會變成青蛙。　◎"]],"青銅":[["ㄑㄧㄥ ㄊㄨㄥˊ","以銅及錫為主要成分的合金。青灰色或灰黃色，硬度大，耐磨，抗蝕性良好，可製成武器、飾品、銅像及各種機械零件。在人類文明發展史上占有重要的地位。其成分比例因不同的需要而異，也可以在合金中加入其他金屬成分，如鋁青銅、錳青銅、磷青銅、矽青銅等。[例]商、周時代的酒器、禮器、兵器等，大多是以青銅製成的。"]],"靜悄悄":[["ㄐㄧㄥˋ ㄑㄧㄠˇ ㄑㄧㄠˇ","形容寂靜無聲。[例]放學後，校園四周靜悄悄的，白天的喧嘩嬉鬧聲消逝得無影無蹤。"]],"靜止":[["ㄐㄧㄥˋ ㄓˇ","休止不動。[例]他一直坐在那裡靜止不動，已有好長一段時間了。"]],"靜脈":[["ㄐㄧㄥˋ ㄇㄞˋ","將血液從身體各部位送回心臟的血管。管中血液中的含氧量較動脈少，負責將濁血送回心臟以待清潔，但是肺靜脈等除外。其循環方向和功用皆與動脈相反。[例]他由於長時間站立工作，導致腿部靜脈嚴重曲張。"]],"靜謐":[["ㄐㄧㄥˋ ㄇㄧˋ","安靜。[例]凌晨的植物園十分靜謐。"]],"非常":[["ㄈㄟ ㄔㄤˊ","特別的、不尋常的。[例]他是個非常傑出的電視演員。"]],"靠攏":[["ㄎㄠˋ ㄌㄨㄥˇ","靠近、聚攏。[例]做完體操後，兩旁的隊伍向中央靠攏，方便教練講解比賽規則。"]],"靠近":[["ㄎㄠˋ ㄐㄧㄣˋ","接近、貼近。[例]施工路段危險，閒雜人等請勿靠近。"]],"靡爛":[["ㄇㄧˊ ㄌㄢˋ","爛到不可收拾。今多用於指生活腐化，不圖進取。[例]生活靡爛"]],"面具":[["ㄇㄧㄢˋ ㄐㄩˋ","1.遮護臉部或用來偽裝的面罩。[例]這一隊訓練精良的特戰部隊隊員，個個戴著防毒面具執行此次任務。\n2.比喻偽裝的面貌。[例]有些人戴著慈祥的面具，卻壞事做盡。"]],"面無血色":[["ㄇㄧㄢˋ ㄨˊ ㄒㄧㄝˇ ㄙㄜˋ","形容因受驚嚇或生病而臉色發白的樣子。[例]他方才騎車，差一點出車禍，嚇得面無血色。"]],"面積":[["ㄇㄧㄢˋ ㄐㄧ","地面、物體表面或平面圖形的大小。[例]這間房子面積雖然不大，適當的隔間及擺設，還顯得優雅合用。"]],"面貌":[["ㄇㄧㄢˋ ㄇㄠˋ","1.相貌、面容。[例]他結交朋友非常注重對方的品格，從不在意面貌的美醜。_x000D_\n2.比喻事物所呈現的景象、狀態。[例]都市化以後，整個社會面貌和從前大不相同。"]],"面面相覷":[["ㄇㄧㄢˋ ㄇㄧㄢˋ ㄒㄧㄤ ㄑㄩˋ","互相對視不知所措，形容驚懼或詫異的樣子。[例]聽到這個不幸的消息，大家都面面相覷，悄然無語。"]],"面頰":[["ㄇㄧㄢˋ ㄐㄧㄚˊ","臉頰、兩腮。[例]她在面頰上塗抹一點腮紅，藉以遮掩蒼白的臉色。　◎"]],"鞋子":[["ㄒㄧㄝˊ ˙ㄗ","穿在腳上，用來保護足部，便於行走的穿著物。由皮革、布帛、膠皮等材料製成，種類式樣繁多。[例]鞋子必須合腳，才不會對腳造成傷害。"]],"鞏固":[["ㄍㄨㄥˇ ㄍㄨˋ","1.加強力量使其更加堅固牢靠。[例]國軍大量添購新式武器，藉以鞏固國防。\n2.堅固不易動搖的。[例]此篇論文的發表，使他在學術界的地位更加鞏固。"]],"鞠躬":[["ㄐㄩˊ ㄍㄨㄥ","彎腰行禮。[例]她深深一鞠躬，向鼎力支持的選民致上最大的謝意。　◎"]],"鞭炮":[["ㄅㄧㄢ ㄆㄠˋ","編連成串的炮竹。[例]每到除夕夜，鞭炮聲即此起彼落。"]],"音效":[["ㄧㄣ ㄒㄧㄠˋ","在廣播或影視節目中，配合節目內容所呈現的聲音效果。通常以現成的唱片或錄音帶播放，或由現場製作各種音響，以代替某種真實或象徵的聲音，用來烘托整體氣氛。[例]早期電子音樂尚未出現時，廣播戲劇的音效都是利用各種道具由工作人員配製而成。"]],"音樂":[["ㄧㄣ ㄩㄝˋ","由旋律、節奏、和聲等合成，用以傳達思想、感情的樂音。[例]古典音樂、流行音樂、搖滾音樂"]],"音樂盒":[["ㄧㄣ ㄩㄝˋ ㄏㄜˊ","一種會發出音樂的小盒子。在小盒內有可以旋轉的圓筒裝置。將圓筒扭緊再鬆開，或利用發條原理，使圓筒上的針彈在梳子形的金屬板上而發出的音樂。[例]這個有新郎新娘共舞並奏著結婚進行曲的音樂盒，是結婚時好友送的。"]],"音符":[["ㄧㄣ ㄈㄨˊ","五線譜上用來表示樂音長短、高低的符號。有全音符、二分音符、四分音符、八分音符、十六分音符等。又有附點音符，時間較原音符長一半。[例]認識音符是學樂理的首要步驟。"]],"音訊":[["ㄧㄣ ㄒㄩㄣˋ","消息。[例]音訊杳然、音訊全無、互通音訊"]],"音階":[["ㄧㄣ ㄐㄧㄝ","以一音為基音，將其他音依高低次序排列而成的一組音列，稱為「音階」。[例]以Ｃ音為主音所形成的Ｃ大調音階，是近代音樂的基礎音階。"]],"音響":[["ㄧㄣ ㄒㄧㄤˇ","通稱無線電收音機、電唱機等收放音的電子設備。[例]床頭音響、立體音響"]],"韻律":[["ㄩㄣˋ ㄌㄩˋ","詩歌或音樂的旋律節奏。[例]這首歌歌聲悠揚，韻律和諧，聽起來十分悅耳。"]],"響亮":[["ㄒㄧㄤˇ ㄌㄧㄤˋ","聲音宏大清高。[例]她的歌聲高亢響亮，聽來令人精神振奮不已。"]],"響徹雲霄":[["ㄒㄧㄤˇ ㄔㄜˋ ㄩㄣˊ ㄒㄧㄠ","形容聲音非常響亮。[例]廟會上人潮聚集，敲鑼打鼓聲，響徹雲霄。"]],"響應":[["ㄒㄧㄤˇ ㄧㄥˋ","指附和某種主張或行動。[例]這一次賑災活動，各界紛紛響應。"]],"頂呱呱":[["ㄉㄧㄥˇ ㄍㄨㄚ ㄍㄨㄚ","最好的、極佳的。[例]他在學校的表現是數一數二，頂呱呱的。"]],"頂天立地":[["ㄉㄧㄥˇ ㄊㄧㄢ ㄌㄧˋ ㄉㄧˋ","形容人處事光明磊落，氣勢豪邁。[例]他為人正直，是個頂天立地的男子漢。"]],"頂峰":[["ㄉㄧㄥˇ ㄈㄥ","山的頂端、最高處。[例]經過數小時的努力，他終於攀上頂峰。"]],"頂撞":[["ㄉㄧㄥˇ ㄓㄨㄤˋ","回嘴，出言不遜。[例]為人子女不應任意頂撞父母，對父母不敬。"]],"頂端":[["ㄉㄧㄥˇ ㄉㄨㄢ","最上部、頂點。[例]塔的頂端裝有一支避雷針。"]],"頃刻":[["ㄑㄧㄥˇ ㄎㄜˋ","形容極短的時間。[例]頃刻之間，整座屋子已陷入火海。"]],"項目":[["ㄒㄧㄤˋ ㄇㄨˋ","事物分類的條目。[例]這次的體育競賽包括田徑、球類、游泳等項目。"]],"項鍊":[["ㄒㄧㄤˋ ㄌㄧㄢˋ","掛在脖子上裝飾用的鍊子。[例]這條項鍊是他們倆的定情物。"]],"順便":[["ㄕㄨㄣˋ ㄅㄧㄢˋ","趁著做某事之便，另外兼做別的事。[例]我利用到臺南出差的機會，順便探望親友。"]],"順利":[["ㄕㄨㄣˋ ㄌㄧˋ","事情未遭阻礙而完成。[例]到目前為止，整個計畫進行得非常順利。"]],"順從":[["ㄕㄨㄣˋ ㄘㄨㄥˊ","順服、遵從。[例]他順從父母的意思，申請調到家鄉的小學教書。"]],"順暢":[["ㄕㄨㄣˋ ㄔㄤˋ","順利通暢，沒有阻礙。[例]在高速公路夜間行車十分順暢。"]],"預感":[["ㄩˋ ㄍㄢˇ","知道有事將要發生的感覺。[例]我有不祥的預感，他可能出事了。"]],"預留":[["ㄩˋ ㄌㄧㄡˊ","事先保留。[例]媽媽知道他今天會較晚回家，已先幫他預留飯菜。"]],"預約":[["ㄩˋ ㄩㄝ","事先約定。[例]那家醫院將於下月起，開放電話預約掛號的服務。"]],"預見":[["ㄩˋ ㄐㄧㄢˋ","事先可以預料得到。[例]他一向勤勉奮發，出人頭地是可以預見的。"]],"預訂":[["ㄩˋ ㄉㄧㄥˋ","事先訂定。[例]大會已預訂餐盒，供與會者午餐食用。"]],"預防":[["ㄩˋ ㄈㄤˊ","事前防範。[例]預防重於治療。"]],"頑皮":[["ㄨㄢˊ ㄆㄧˊ","淘氣，不聽教誨。[例]這個孩子居然把小狗的毛剪光，真是太頑皮了。"]],"頒獎":[["ㄅㄢ ㄐㄧㄤˇ","發給獎品、獎金或獎狀等。[例]他有如此卓越的貢獻，實在值得頒獎鼓勵。"]],"頒發":[["ㄅㄢ ㄈㄚ","發給、授予。[例]政府將頒發給好人好事代表每人一只獎章。"]],"頓時":[["ㄉㄨㄣˋ ㄕˊ","立時、即刻。[例]他聽到這個不幸的消息，頓時昏倒。"]],"領先":[["ㄌㄧㄥˇ ㄒㄧㄢ","居前，處於優勢的地位。[例]這場棒球賽，中華隊一路領先，終場以三比零獲勝。"]],"領受":[["ㄌㄧㄥˇ ㄕㄡˋ","接受。[例]災民懷著感激的心情領受各界的愛心捐款。"]],"領土":[["ㄌㄧㄥˇ ㄊㄨˇ","國家構成要素之一。指國家所統轄的土地，為國家行使主權的範圍，包括陸地、領水、領海及領空。依據國際法，他國不得任意侵犯。[例]一旦國家受到侵犯，全國上下必誓死保衛領土。"]],"領域":[["ㄌㄧㄥˇ ㄩˋ","1.國家主權所及的區域。包括陸、海、空三方面。[例]依據國際公法規定，各國的領域都享有不被侵犯權。\n2.事物的範圍。[例]思想領域、生活領域、學術領域"]],"領帶":[["ㄌㄧㄥˇ ㄉㄞˋ","穿著西服時，繫在襯衫衣領上用來裝飾的長條布塊。[例]這條領帶的顏色剛好可以搭配你這套新西裝。"]],"領悟":[["ㄌㄧㄥˇ ㄨˋ","了解、明白。[例]你可以從這個小故事領悟出深刻的道理嗎？"]],"領獎":[["ㄌㄧㄥˇ ㄐㄧㄤˇ","接受獎勵或獎品。[例]上臺領獎的同學，臉上都露出喜悅的神情。"]],"領袖":[["ㄌㄧㄥˇ ㄒㄧㄡˋ","本指衣服的領子和袖子。後指國家或團體的領導人。[例]他是我們詩社的領袖，不但作品傑出，而且很有領導才能。"]],"頭巾":[["ㄊㄡˊ ㄐㄧㄣ","裹頭的布。[例]姊姊織了一條頭巾送給奶奶，作為祝壽的禮物。"]],"頭暈":[["ㄊㄡˊ ㄩㄣ","頭昏。[例]頭暈是高血壓的主要症狀。"]],"頭暈目眩":[["ㄊㄡˊ ㄩㄣ ㄇㄨˋ ㄒㄩㄢˋ","頭腦昏沉，視覺模糊。[例]每日校對這些密密麻麻的文字，真令人頭暈目眩。"]],"頭痛":[["ㄊㄡˊ ㄊㄨㄥˋ","1.頭腦內部組織受刺激或傷害而引起的頭部疼痛。[例]她經常熬夜工作，因此頭痛一直無法根治。\n2.煩惱或厭煩。[例]老師一直為他不按時交作業而頭痛不已。"]],"頭皮":[["ㄊㄡˊ ㄆㄧˊ","頭部的皮膚。[例]常按摩頭皮，能促進頭皮血液循環，加快頭髮生長速度。"]],"頭盔":[["ㄊㄡˊ ㄎㄨㄟ","保護頭部以預防受傷的帽子。[例]進入工地，戴上頭盔，可以減少頭部被掉落物體砸傷的危險。"]],"頭腦":[["ㄊㄡˊ ㄋㄠˇ","1.頭顱。[例]丈二金剛──摸不著頭腦。\n2.腦筋、智力。[例]他的頭腦很好，考試經常名列前茅。\n3.頭緒、條理。[例]這個人傻裡傻氣，說起話來，沒個頭腦。\n4.首領、主腦人物。[例]這件集體搶劫的案件，因為頭腦的落網而宣告破案。"]],"頭部":[["ㄊㄡˊ ㄅㄨˋ","1.頭的部位。[例]他在車禍中撞傷了頭部，醫生要他住院幾天，以便觀察有無腦震盪現象。\n2.股票術語。指股價上漲至某價位時，受阻於某種原因而下滑，此價位區稱為「頭部」。"]],"頭銜":[["ㄊㄡˊ ㄒㄧㄢˊ","職位、官位的名稱。[例]他身兼數職，所以名片上印滿了各種頭銜。"]],"頭頂":[["ㄊㄡˊ ㄉㄧㄥˇ","頭的最上部。[例]他靠著身體的平衡，可以將籃球放在頭頂而不掉下來。"]],"頭髮":[["ㄊㄡˊ ㄈㄚˇ","頭上的毛髮。[例]她有一頭健康亮麗的頭髮，真是令人羨慕。　◎"]],"頹喪":[["ㄊㄨㄟˊ ㄙㄤˋ","消極喪氣的樣子。[例]失敗了可以東山再起，大可不必如此頹喪！"]],"頹然":[["ㄊㄨㄟˊ ㄖㄢˊ","無力欲倒的樣子。[例]神色頹然"]],"顆粒":[["ㄎㄜ ㄌㄧˋ","體積小而呈粒狀的物體。[例]這是一杯含有果肉顆粒的柳橙汁。"]],"題材":[["ㄊㄧˊ ㄘㄞˊ","文學或藝術作品中，為表現主題而選用的素材。[例]她文思細膩，觀察敏銳，生活中的點點滴滴，都成為她寫作的題材。"]],"題目":[["ㄊㄧˊ ㄇㄨˋ","1.文章詩篇或演講等的標名。[例]作文題目\n2.考試時要求應試人作答的問題。[例]這次期末考的題目難易適中，頗能測出考生的程度。"]],"額頭":[["ㄜˊ ˙ㄊㄡ","眉上髮下的部分。[例]農夫在豔陽下辛勤工作，不斷的用手抹去額頭上的汗水。"]],"顏料":[["ㄧㄢˊ ㄌㄧㄠˋ","繪畫、油漆時用來著色的材料。[例]他用明亮的顏料，將牆壁油漆得煥然一新。"]],"顏色":[["ㄧㄢˊ ㄙㄜˋ","1.色彩。[例]美麗的彩虹一共有七種顏色。\n2.厲害的手段。[例]給他一點顏色看看。\n3.面容、臉色。[例]她的顏色和順，非常有親切感。\n4.姿色。[例]她長得明眸皓齒，頗有幾分顏色。"]],"願意":[["ㄩㄢˋ ㄧˋ","同意、樂意。[例]這次的義演活動，許多藝人願意共襄盛舉。"]],"顛倒":[["ㄉㄧㄢ ㄉㄠˇ","1.上下前後與原本或應有的位置相反。[例]他把前後順序弄顛倒了，趕快重新排好才是。\n2.心神離亂。[例]他受了嚴重刺激，整天思緒顛倒、神情恍惚。"]],"顛簸":[["ㄉㄧㄢ ㄅㄛˇ","起伏搖晃。[例]行經這條崎嶇不平的山路，車子顛簸得特別厲害。"]],"類別":[["ㄌㄟˋ ㄅㄧㄝˊ","1.按照種類來區別。[例]這箱貨品如果按性質來分可以類別為二。\n2.種類。[例]這家公司推出的產品共有五大類別。"]],"顧全大局":[["ㄍㄨˋ ㄑㄩㄢˊ ㄉㄚˋ ㄐㄩˊ","考量事物的整體性利益。[例]他為了顧全大局，不得不暫時放棄自己的理想。"]],"顧慮":[["ㄍㄨˋ ㄌㄩˋ","顧忌、憂慮。[例]確立奮鬥目標後，即當放手去做，不必顧慮太多！"]],"顫動":[["ㄓㄢˋ ㄉㄨㄥˋ","顫抖、振動。[例]早上發生有感地震，門窗玻璃顫動不已。"]],"顫慄":[["ㄓㄢˋ ㄌㄧˋ","身體因恐懼、寒冷或激動而抖動。[例]那部恐怖電影情節詭異，畫面血腥，從頭到尾令人顫慄不已。"]],"顫抖":[["ㄓㄢˋ ㄉㄡˇ","身體抖動。[例]氣溫突然下降，衣服單薄，令人不由得顫抖起來。"]],"顯著":[["ㄒㄧㄢˇ ㄓㄨˋ","非常明白、明顯。[例]在父母悉心照顧下，他的病情有顯著的進步。"]],"顯露":[["ㄒㄧㄢˇ ㄌㄨˋ","明白的表露出來。[例]聽到這件好消息，父親的臉上顯露出愉快的笑容。"]],"風乾":[["ㄈㄥ ㄍㄢ","具有水分的物品，被風吹乾。[例]新鮮鳳梨去皮切片風乾後，即成滋味絕美的果乾。"]],"風俗":[["ㄈㄥ ㄙㄨˊ","風尚習俗。[例]每個民族都有他們特殊的風俗民情。"]],"風吹雨打":[["ㄈㄥ ㄔㄨㄟ ㄩˇ ㄉㄚˇ","1.遭受風雨的吹拂打擊。[例]經過一夜的風吹雨打，院子裡滿地殘葉。\n2.比喻遭受挫折、打擊。[例]大家要禁得起風吹雨打，不管未來會經歷多少挫折，我們都不能放棄！"]],"風塵僕僕":[["ㄈㄥ ㄔㄣˊ ㄆㄨˊ ㄆㄨˊ","形容旅途勞累。[例]他風塵僕僕的從美國趕回來，就是為了和分別已久的親人一起過年。"]],"風扇":[["ㄈㄥ ㄕㄢˋ","夏日袪暑的器具，藉電力轉動扇葉生風。[例]夏日裡在家吹著風扇，喝著冰水，是多麼舒暢的事。　△電扇、電風扇"]],"風景":[["ㄈㄥ ㄐㄧㄥˇ","風光景物。[例]臺灣南投的日月潭風景優美，是著名的旅遊勝地。"]],"風沙":[["ㄈㄥ ㄕㄚ","被風揚起的沙土。[例]卡車快速的駛過沙地，揚起了漫天風沙。"]],"風箏":[["ㄈㄥ ㄓㄥ","一種玩具。通常以竹片為骨架，糊以紙、布等，用長線繫綁，可乘風飛升。[例]王伯伯不但是放風箏的高手，更是製作風箏的巧匠。"]],"風車":[["ㄈㄥ ㄔㄜ","1.藉風力轉動輪翼或風扇以產生動力的器具。[例]風車是荷蘭極具代表性的景觀。_x000D_\n2.一種藉風力吹動紙輪的玩具。[例]看著窗邊的紙風車被風吹得咕嚕咕嚕轉，他開心地笑了。"]],"風采":[["ㄈㄥ ㄘㄞˇ","風姿神采。[例]知名藝人一出現，那翩翩風采激起觀眾一片讚嘆聲。"]],"風雨無阻":[["ㄈㄥ ㄩˇ ㄨˊ ㄗㄨˇ","不論發生何種情況，心意或行動依舊不變。[例]他每天接送父親到醫院做復健治療，風雨無阻，數年如一日。"]],"風雲際會":[["ㄈㄥ ㄩㄣˊ ㄐㄧˋ ㄏㄨㄟˋ","古人認為風從虎，雲從龍，借以比喻人才。風雲際會，比喻人才得遇明君，為時所用，如風與虎、雲與龍得以相會一般。[例]英雄不怕出身低，有朝一日風雲際會，必能出人頭地！"]],"颱風":[["ㄊㄞˊ ㄈㄥ","發生在西太平洋上由強烈熱帶性低氣壓或熱帶氣旋所引起的暴風，其強度達到一定標準時即為颱風。颱風依其強度分為三級。中心最大風速每秒17.2至32.6公尺者，稱為「輕度颱風」；每秒32.7至50.9公尺者，稱為「中度颱風」；每秒51公尺以上者，稱為「強烈颱風」。[例]事先做好防颱準備，才能將颱風帶來的災害減至最低。"]],"颱風眼":[["ㄊㄞˊ ㄈㄥ ㄧㄢˇ","颱風的中心。風力微弱，天氣良好，此區域近乎圓形，直徑自4哩至40哩不等，通常約為12至25哩。在颱風進行過程中，颱風眼的形式與大小常會改變。[例]在颱風眼籠罩的地區，通常無風也無雨。"]],"颳風":[["ㄍㄨㄚ ㄈㄥ","起風、吹風。[例]若遇到颳風下雨，最好取消登山活動。"]],"飄搖":[["ㄆㄧㄠ ㄧㄠˊ","1.隨風飄動。[例]窗外那棵老榕樹，在風雨中飄搖不定。\n2.動盪不安。[例]國家正處在風雨飄搖中，全民當團結一致。"]],"飄浮":[["ㄆㄧㄠ ㄈㄨˊ","在風中飄蕩浮流。[例]風箏在空中飄浮，爭奇鬥勝。"]],"飛奔":[["ㄈㄟ ㄅㄣ","急速奔跑。[例]他一看到新奇有趣的東西，馬上飛奔過去看個仔細。"]],"飛揚":[["ㄈㄟ ㄧㄤˊ","高舉飄揚。[例]廣場上成列的國旗在空中飛揚，十分壯觀美麗。"]],"飛梭":[["ㄈㄟ ㄙㄨㄛ","飛快運動的梭子。[例]歲月流逝如飛梭，青春少年一轉眼已白髮蒼蒼。"]],"飛機":[["ㄈㄟ ㄐㄧ","一種利用動力推進而飛行的工具。具有機身、機翼和發動機等三大部分。可供載客、運輸等。[例]飛機是美國的萊特兄弟所發明的。　◎"]],"飛瀑":[["ㄈㄟ ㄆㄨˋ","自高處急速沖瀉而下的瀑布。[例]這座森林有小橋和飛瀑，景色非常怡人。"]],"飛盤":[["ㄈㄟ ㄆㄢˊ","1.一種休閒運動。可一人獨玩或多人共玩，玩時投擲圓形的盤狀物，使它旋轉並向前平飛。西元1940年，由美國人摩理森所發明，因玩法簡單，廣為大眾接受，成為流行的運動。    \n2.飛盤運動所使用的器材。為圓形的盤狀物，多為塑膠製品。[例]假日的公園裡，常有許多小朋友丟擲飛盤玩耍。　◎"]],"飛簷走壁":[["ㄈㄟ ㄧㄢˊ ㄗㄡˇ ㄅㄧˋ","能在屋簷牆壁行走如飛。形容身手矯健、武技高超。[例]武俠小說中的人物，大多具有飛簷走壁的功夫。"]],"飛翔":[["ㄈㄟ ㄒㄧㄤˊ","在空中飛旋。[例]在海邊，常見成群的海鷗飛翔著。"]],"飛行員":[["ㄈㄟ ㄒㄧㄥˊ ㄩㄢˊ","駕駛飛航機器的人。[例]他的父親是個經驗豐富的飛行員。"]],"飛躍":[["ㄈㄟ ㄩㄝˋ","1.形容動作快速。[例]她跑起來像一隻飛躍的羚羊。\n2.比喻事物有快速而突破性的進展。[例]近年來，臺灣的經濟有飛躍的進步。"]],"飛逝":[["ㄈㄟ ㄕˋ","快速消逝。[例]時光飛逝，昔日的小女孩如今已成為亭亭玉立的淑女了。"]],"食宿":[["ㄕˊ ㄙㄨˋ","飲食和住宿。[例]他到歐洲旅遊，食宿都請旅行社代為安排。"]],"食材":[["ㄕˊ ㄘㄞˊ","食物的原始材料。[例]為了推廣當地食材，小農市集特別舉辦美食比賽。"]],"食物":[["ㄕˊ ㄨˋ","一切可供飲食的東西。[例]他不喜歡吃辛辣的食物。"]],"食物鏈":[["ㄕˊ ㄨˋ ㄌㄧㄢˋ","1.不同種類的生物間，由於食性關係而形成食物鏈。如青蛙吃蜻蜓，蛇吃青蛙，老鷹捕食蛇。\n2.在生物界由於不同階層的攝食關係，可將生物分成生產者（如行光合作用的植物）、消費者（各級動物）及分解者（細菌等）；其間關係呈鏈狀相接。"]],"食糧":[["ㄕˊ ㄌㄧㄤˊ","泛指一切米穀及食物。[例]農業生產技術不斷改良進步，食糧短缺的情事已鮮有所聞。"]],"飢渴":[["ㄐㄧ ㄎㄜˇ","1.飢餓和口渴。[例]連日來的飢渴，已使他呈現昏迷狀態。\n2.比喻急切的盼望。[例]小弟對著玩具店中的玩具露出飢渴的眼光。"]],"飢餓":[["ㄐㄧ ㄜˋ","腹空急欲得食的感覺。[例]經過一整天的長途跋涉，真教人飢餓難捱。"]],"飯廳":[["ㄈㄢˋ ㄊㄧㄥ","家庭或公私機構中專供用餐的地方。[例]晚上大家聚在飯廳吃飯，談天說地，其樂融融。"]],"飯桌":[["ㄈㄢˋ ㄓㄨㄛ","吃飯用的桌子。[例]吃完飯後，要把飯桌收拾乾淨。"]],"飲料":[["ㄧㄣˇ ㄌㄧㄠˋ","經過加工製造供人飲用的液體。如汽水、果汁、酒等。[例]飲料是酒席上不可或缺的東西。"]],"飲水":[["ㄧㄣˇ ㄕㄨㄟˇ","1.喝水。[例]牧場的主人，正趕著牛群到河邊飲水。\n2.供飲用的水。[例]大樓應定期清洗水塔，以確保住戶飲水的安全。"]],"飲泣":[["ㄧㄣˇ ㄑㄧˋ","悲哀到了極點，以致哭不出聲音來。[例]她細述與家人離散的情形，不禁嗚咽飲泣。"]],"飲食":[["ㄧㄣˇ ㄕˊ","1.吃喝。[例]飲食起居正常，才能擁有健康的身體。\n2.泛指各種吃喝的食物。[例]糖尿病患者的飲食需要特別注意控制糖分的含量。"]],"飲鴆止渴":[["ㄧㄣˇ ㄓㄣˋ ㄓˇ ㄎㄜˇ","比喻只求解救眼前困難，而不顧將來的大禍患。[例]吸食毒品來解癮，無異是飲鴆止渴的自殺行為。"]],"飼養":[["ㄙˋ ㄧㄤˇ","餵養。[例]她飼養了一隻很可愛的小狗。"]],"飽滿":[["ㄅㄠˇ ㄇㄢˇ","充足、豐富。[例]精神飽滿、肌肉飽滿"]],"飽足":[["ㄅㄠˇ ㄗㄨˊ","吃飽喝足，由衷滿意。[例]本餐廳奉行少鹽、少油的理念，讓顧客飽足而無負擔。"]],"養分":[["ㄧㄤˇ ㄈㄣˋ","富有營養的成分。[例]樹根的功用，在吸收泥土中的水分與養分。"]],"養子":[["ㄧㄤˇ ㄗˇ","1.養育子女。[例]養子不教誰之過？\n2.稱謂。用以稱被人收養的男子。[例]由於太太不能生育，他們夫妻倆便收了一個養子，以延續香火。"]],"養料":[["ㄧㄤˇ ㄌㄧㄠˋ","泛指富有營養的東西。[例]適量的養料對植物的生長很有幫助。"]],"養母":[["ㄧㄤˇ ㄇㄨˇ","稱謂。用以稱非親生而具收養關係的母親。[例]他小時與父母失散後，即由養母撫養長大。　△義母"]],"養活":[["ㄧㄤˇ ㄏㄨㄛˊ","贍養、撫養。[例]他獨力一人要養活一家人，其負擔之重可想而知。"]],"養病":[["ㄧㄤˇ ㄅㄧㄥˋ","調理病況，使病體康復。[例]在他養病期間，醫師建議他多攝取高蛋白的食物。"]],"養育":[["ㄧㄤˇ ㄩˋ","撫養教育。[例]父母的養育之恩，比天高，比海深。"]],"餐具":[["ㄘㄢ ㄐㄩˋ","餐飲時所使用的器具。[例]為了環保，我們應減少使用免洗餐具。"]],"餐廳":[["ㄘㄢ ㄊㄧㄥ","泛稱用餐的場所。[例]這家餐廳的菜色不錯，非常美味可口。"]],"餐桌":[["ㄘㄢ ㄓㄨㄛ","吃飯用的桌子。[例]餐桌上擺滿了豐盛的菜餚，令人垂涎三尺。　◎"]],"餐盒":[["ㄘㄢ ㄏㄜˊ","盛裝飯菜的盒子。[例]餐盒用畢後要置於垃圾筒中，不可隨地亂丟。"]],"餐館":[["ㄘㄢ ㄍㄨㄢˇ","供人用餐的飲食店。[例]今天家裡不開伙，大家決定去餐館用餐。"]],"餘暇":[["ㄩˊ ㄒㄧㄚˊ","空閒的時間。[例]他利用工作餘暇閱讀書刊，不斷充實自己。"]],"餘暉":[["ㄩˊ ㄏㄨㄟ","夕照。[例]落日的餘暉將天空映照得滿天霞紅。"]],"餘裕":[["ㄩˊ ㄩˋ","充裕而有餘。[例]養成儲蓄的習慣，才能在日常支出外留有餘裕，應付緊急的狀況。"]],"餵食":[["ㄨㄟˋ ㄕˊ","拿食物餵給嬰幼兒或動物吃。[例]幼兒應以牛奶或稀飯餵食比較合適。"]],"餵養":[["ㄨㄟˋ ㄧㄤˇ","給予嬰幼兒或牲畜食物吃，並撫養、照顧使其成長。[例]餵養小動物和餵養寶寶一樣，都需要愛心與耐心。"]],"饑荒":[["ㄐㄧ ㄏㄨㄤ","五穀不生、果類不熟。[例]非洲地區土地貧瘠，氣候不良，因此常鬧饑荒。"]],"饒命":[["ㄖㄠˊ ㄇㄧㄥˋ","赦命免死。[例]這種殺人凶徒豈能饒命？但國有國法，我們還是得將他送交警察去處理。"]],"饒恕":[["ㄖㄠˊ ㄕㄨˋ","原諒、寬恕。[例]這種喪盡天良的行徑，是任何人都無法饒恕的！"]],"首先":[["ㄕㄡˇ ㄒㄧㄢ","最先、最初。[例]會議一開始，首先由主席致辭。"]],"首創":[["ㄕㄡˇ ㄔㄨㄤˋ","最先開創。[例]全國首創、首創惡例"]],"首都":[["ㄕㄡˇ ㄉㄨ","中央政府的所在地。[例]倫敦是英國的首都。"]],"香味":[["ㄒㄧㄤ ㄨㄟˋ","芳香的氣味。[例]廚房裡飄來陣陣滷肉的香味。"]],"香蕉":[["ㄒㄧㄤ ㄐㄧㄠ","植物名。芭蕉科芭蕉屬，多年生草本。莖短，葉長而寬，夏秋間自偽莖抽出大花軸，上部為雄花，下部為雌花，花色淡黃。果實為長形，稍彎，味香甜，亦稱為「香蕉」。[例]高雄旗山所產的香蕉味道甜美，十分著名。　◎"]],"馬路":[["ㄇㄚˇ ㄌㄨˋ","寬闊平坦可行車馬的道路。現在泛指供人、車行走的道路。[例]馬路如虎口，行人要小心。"]],"馬車":[["ㄇㄚˇ ㄔㄜ","用馬來拉動行駛的車子。[例]只見魔杖一指，南瓜就變成了一輛裝飾華麗的四輪馬車。◎"]],"馬鈴薯":[["ㄇㄚˇ ㄌㄧㄥˊ ㄕㄨˇ","植物名。茄科茄屬，多年生草本。原產於南美智利。羽狀複葉，夏日開白色或淡紫色花。地下塊莖亦稱為「馬鈴薯」，形圓如馬鈴，含豐富澱粉，味甘美，歐美人以為主要食物，我國多用作蔬菜佐食。[例]專家警告說長了芽眼的馬鈴薯含有毒素，不可食用。　△山藥蛋、洋芋　◎"]],"駐守":[["ㄓㄨˋ ㄕㄡˇ","駐紮防守。[例]他們奉命駐守海防要地，嚴防走私、偷渡。"]],"駐足":[["ㄓㄨˋ ㄗㄨˊ","停下腳步。[例]電影公司在大街上拍外景，吸引了許多行人駐足圍觀。"]],"駕崩":[["ㄐㄧㄚˋ ㄅㄥ","古時尊稱天子死亡。[例]古代帝王駕崩，全國舉喪。"]],"駕照":[["ㄐㄧㄚˋ ㄓㄠˋ","駕駛汽機車的許可憑證。由駕駛人向公路監理機關申請登記，經考試合格後發給。[例]他終於通過考試，拿到駕照了。"]],"駕車":[["ㄐㄧㄚˋ ㄔㄜ","本指用牲口拉車。現泛指開車。[例]閒來無事，他喜歡駕車到處兜風。"]],"駕輕就熟":[["ㄐㄧㄚˋ ㄑㄧㄥ ㄐㄧㄡˋ ㄕㄡˊ","駕著輕車走熟路。比喻對事情很熟悉，做起來得心應手。[例]這事他早有經驗，做起來自然駕輕就熟，十分順當。"]],"駕駛":[["ㄐㄧㄚˋ ㄕˇ","1.操控車船、飛機等交通工具。[例]他花了兩個月的時間才學會駕駛汽車。\n2.操控車船或飛機的人。[例]這位汽車駕駛已有十幾年的經驗，技術非常純熟。"]],"駕鶴西歸":[["ㄐㄧㄚˋ ㄏㄜˋ ㄒㄧ ㄍㄨㄟ","比喻人死。多用於輓辭。[例]靈堂裡掛著一幅駕鶴西歸的輓聯。"]],"駱駝":[["ㄌㄨㄛˋ ㄊㄨㄛˊ","動物名。哺乳綱偶蹄目駱駝科。原產於北非、阿拉伯、伊朗、中亞和西班牙等地。身形高大，背上有駝峰，分為單峰和雙峰兩種。雙重眼瞼，可擋風沙。腳下有肉墊，適於行走沙漠。能反芻，有高度耐飢渴的能力。可供騎乘及載貨，是沙漠中的主要負重動物。[例]駱駝的胃裡有可儲水的小泡泡，所以牠可以好幾天不喝水。　△沙漠之舟　◎"]],"騎樓":[["ㄑㄧˊ ㄌㄡˊ","一種外廊式建築設計。將建築物一樓臨近街道部分建成走廊，走廊上方為二樓樓層，宛如二樓「騎」在一樓上，故稱為「騎樓」。[例]騎樓的設計為行人提供了遮風避雨的功能。"]],"騙局":[["ㄆㄧㄢˋ ㄐㄩˊ","為騙取別人財物而設計的圈套。[例]他一手設計的騙局，終究逃不過警方的法眼而被偵破。"]],"騰出":[["ㄊㄥˊ ㄔㄨ","讓出、空出時間或空間。[例]把這些東西挪一下，就可騰出空間放那桌子了。"]],"騰雲駕霧":[["ㄊㄥˊ ㄩㄣˊ ㄐㄧㄚˋ ㄨˋ","1.傳說、小說中指利用法術，在空中飛行。[例]齊天大聖騰雲駕霧地來去，咻的一聲就不見了！_x000D_\n2.比喻奔馳疾速。[例]只見他猛踩油門，車子箭般射出，一路上如騰雲駕霧般，嚇得我心臟都快跳出來了。"]],"驅使":[["ㄑㄩ ㄕˇ","策動、促使。[例]貧窮驅使他奮發向上、努力唸書。"]],"驅策":[["ㄑㄩ ㄘㄜˋ","驅動、鞭策。[例]求知的欲望驅策他不斷的讀書學習。"]],"驅逐":[["ㄑㄩ ㄓㄨˊ","驅趕逐走。[例]他因持用假護照闖關而被海關人員驅逐出境。"]],"驕傲":[["ㄐㄧㄠ ㄠˋ","1.傲慢自大。[例]他因驕傲輕敵而輸掉這場比賽。_x000D_\n2.自豪。也指感到自豪的人或事物。[例]這項馳名中外的傳統手工藝一直是當地居民的驕傲。"]],"驕寵":[["ㄐㄧㄠ ㄔㄨㄥˇ","極受寵愛。[例]小妹是家中倍受父母驕寵的么女。"]],"驕橫":[["ㄐㄧㄠ ㄏㄥˋ","傲慢蠻橫。[例]在老師耐心的開導之下，原本驕橫無禮的學生漸漸走回正軌。"]],"驕縱":[["ㄐㄧㄠ ㄗㄨㄥˋ","傲慢任性。[例]過度溺愛小孩，容易養成其驕縱的性格。"]],"驕陽":[["ㄐㄧㄠ ㄧㄤˊ","強烈的陽光。[例]運動員在驕陽下揮汗練習，希望能在這次國際比賽中為國爭光。"]],"驚呼":[["ㄐㄧㄥ ㄏㄨ","因驚奇或害怕而大叫。[例]人遇到危險時總會本能的驚呼救命。"]],"驚喜":[["ㄐㄧㄥ ㄒㄧˇ","驚奇歡喜。[例]大家聽到哥哥中了統一發票特獎的消息都感到非常驚喜。"]],"驚嘆":[["ㄐㄧㄥ ㄊㄢˋ","1.驚奇讚嘆。[例]魔術師精湛的技巧令觀眾驚嘆不已。_x000D_\n2.驚訝感嘆。[例]幼時玩伴多年後重聚，看著彼此模樣，不禁驚嘆怎麼老得這麼快。"]],"驚嚇":[["ㄐㄧㄥ ㄒㄧㄚˋ","驚懼害怕。[例]小明因驚嚇過度而說不出話來。"]],"驚奇":[["ㄐㄧㄥ ㄑㄧˊ","驚訝、感到奇怪。[例]魔術師出神入化的手法，帶給觀眾無限驚奇。"]],"驚愕":[["ㄐㄧㄥ ㄜˋ","因驚訝而愣住。[例]他聽到雙親猝死的消息之後先是驚愕，隨後便嚎啕大哭起來。"]],"驚訝":[["ㄐㄧㄥ ㄧㄚˋ","驚奇訝異。[例]媽媽一聽到自己中了頭獎，一時驚訝得說不出話來。"]],"驚險":[["ㄐㄧㄥ ㄒㄧㄢˇ","危急而令人緊張。[例]驚險畫面、驚險鏡頭"]],"驢子":[["ㄌㄩˊ ˙ㄗ","→驢"]],"驪歌":[["ㄌㄧˊ ㄍㄜ","離別時所唱的歌。[例]每當驪歌聲起，校園裡就充滿了離別的愁緒。"]],"骨折":[["ㄍㄨˇ ㄓㄜˊ","骨骼因外傷或本身的病變，發生斷裂、破碎或有裂紋的現象。[例]他因車禍而導致嚴重骨折，經醫生診治後已無生命危險了。"]],"骨架":[["ㄍㄨˇ ㄐㄧㄚˋ","1.支撐物體的架構。[例]這棟大樓是用鋼筋骨架建造的，堅固耐震。\n2.人的體格形態。[例]他的骨架高䠷，穿什麼衣服都好看。"]],"骸骨":[["ㄏㄞˊ ㄍㄨˇ","骨的通稱。一般指屍骨。[例]飛機不幸失事，罹難者的家屬，望著一堆堆難以辨識的骸骨，不禁悲從中來。"]],"體力":[["ㄊㄧˇ ㄌㄧˋ","身體具有的力氣。[例]運動可以增強體力，促進身體健康。"]],"體壇":[["ㄊㄧˇ ㄊㄢˊ","體育界。[例]體壇新秀、體壇盛事"]],"體操":[["ㄊㄧˇ ㄘㄠ","鍛鍊身體的人為運動。廣義的體操，泛指依種種規則來操練身體的運動，以強身為目的。狹義的體操，指一種運動項目，以比賽獲勝為目的，所以也稱為「競技體操」。[例]每天早上，爸爸都會在院子裡做體操，以鍛鍊身體。"]],"體會":[["ㄊㄧˇ ㄏㄨㄟˋ","親身體驗和領會。[例]人們總是到了自己養育子女時，才能體會為人父母的辛勞。"]],"體積":[["ㄊㄧˇ ㄐㄧ","指物體全部在空間所占據的大小。單位是長度的立方數，如立方公尺、立方公分。[例]這架鋼琴的體積太過龐大，占了客廳一半的空間。"]],"體育":[["ㄊㄧˇ ㄩˋ","以鍛鍊體能、增進健康為主的訓練教育。如賽跑、體操、球類運動等。"]],"體裁":[["ㄊㄧˇ ㄘㄞˊ","1.作品的布局、架構。[例]這篇文章的文字洗鍊，體裁細密，確實值得細細品味。\n2.文學的類別。依作品所表現的結構與性質上之差異而加以區分，如詩、散文、小說、戲劇、報導文學等。[例]這本書以小說體裁寫盡當前社會的各種病態。"]],"體諒":[["ㄊㄧˇ ㄌㄧㄤˋ","設身處地為人著想，並給予諒解。[例]他居然做出這種傷天害理的事，實在令人無法體諒。"]],"體重":[["ㄊㄧˇ ㄓㄨㄥˋ","身體的重量。[例]過胖的人要注意飲食，控制體重。"]],"體驗":[["ㄊㄧˇ ㄧㄢˋ","親身體會、感受。[例]暑假時我們打算到鄉下小住幾天，體驗一下農家生活。"]],"高亢":[["ㄍㄠ ㄎㄤˋ","態度高傲亢直或聲調、情緒高昂激動。[例]歌聲高亢、情緒高亢、性格高亢"]],"高山":[["ㄍㄠ ㄕㄢ","高聳的山。[例]攀登高山應做好周全的準備。"]],"高攀":[["ㄍㄠ ㄆㄢ","跟身分地位比自己高的人結交朋友或結為姻親。[例]對方家大業大，這樁親事我們是高攀不起的。"]],"高潮":[["ㄍㄠ ㄔㄠˊ","1.潮汐漲退當中，水位到達最高的狀態。[例]這片沿海區域地層逐年下陷，每逢高潮總被淹沒。_x000D_\n2.比喻事情發展過程中最緊張熱烈的部分。[例]報上的連載小說，每天總是在高潮處收筆，真是吊人胃口。_x000D_\n3.指性交過程最興奮的階段。"]],"高空":[["ㄍㄠ ㄎㄨㄥ","與地面相距高遠的空中。[例]高空跳傘、高空飛行"]],"高級":[["ㄍㄠ ㄐㄧˊ","1.層級或位階較高的。[例]高級將領、高級代數_x000D_\n2.品質或價位較高的。[例]高級禮盒、高級化妝品"]],"高聳":[["ㄍㄠ ㄙㄨㄥˇ","直立突出。[例]這一座新建的大廈高聳入雲，極為壯觀。"]],"高興":[["ㄍㄠ ㄒㄧㄥˋ","1.開心、愉快、興奮。[例]這次旅行，大家都玩得很高興。_x000D_\n2.喜歡、樂意。[例]他既然高興這樣做，就讓他去做吧！"]],"高談闊論":[["ㄍㄠ ㄊㄢˊ ㄎㄨㄛˋ ㄌㄨㄣˋ","1.言談見解高妙，內容廣博。[例]春秋時代，孟子高談闊論，主張人性本善。_x000D_\n2.大發議論，放言談論。[例]候選人儘可高談闊論，但選民可要仔細評估政見的可行性。"]],"高高低低":[["ㄍㄠ ㄍㄠ ㄉㄧ ㄉㄧ","有高有低、起伏不定。[例]會場裡擺滿了高高低低的花卉盆栽，十分引人注目。"]],"高麗":[["ㄍㄠ ㄌㄧˊ","隋唐時代的古國名，位於今朝鮮半島。　△句驪、朝鮮"]],"髮型":[["ㄈㄚˇ ㄒㄧㄥˊ","頭髮經設計、修剪後所表現的款式。[例]她換了一個髮型，讓人一時認不出來。"]],"髮夾":[["ㄈㄚˇ ㄐㄧㄚˊ","用來固定頭髮的夾子。有美觀及使頭髮齊整的作用。[例]為了怕遮住視線，她將額前的瀏海用髮夾夾住。　◎"]],"髮絲":[["ㄈㄚˇ ㄙ","頭髮。[例]有人把髮絲比喻作三千煩惱絲，還真有幾分道理。"]],"髮辮":[["ㄈㄚˇ ㄅㄧㄢˋ","將頭髮交互纏繞編成的辮子。[例]她把長髮結成髮辮，辮稍綁上蝴蝶結，顯得俏麗可愛。"]],"鬆軟":[["ㄙㄨㄥ ㄖㄨㄢˇ","鬆散不結實。[例]鬆軟的米飯，吃起來很順口。"]],"鬍子":[["ㄏㄨˊ ˙ㄗ","鬍鬚。[例]他蓄著八字形的鬍子，風格獨特。"]],"鬍鬚":[["ㄏㄨˊ ㄒㄩ","長在下巴和面頰上的毛。[例]外公年紀已大，不但頭髮斑白，就連鬍鬚都白了。"]],"鬚眉":[["ㄒㄩ ㄇㄟˊ","本指鬍鬚和眉毛。後借指成年男子。[例]花木蘭代父從軍，英勇不讓鬚眉。"]],"鬥志":[["ㄉㄡˋ ㄓˋ","奮發進取的意志。[例]鬥志昂揚"]],"鬥氣":[["ㄉㄡˋ ㄑㄧˋ","賭氣或故意使對方生氣。[例]不要為一點小事與朋友鬥氣，傷了彼此間的感情。"]],"鬧哄哄":[["ㄋㄠˋ ㄏㄨㄥ ㄏㄨㄥ","喧擾吵鬧。[例]老師才離開沒多久，教室內就已經鬧哄哄了。"]],"鬱金香":[["ㄩˋ ㄐㄧㄣ ㄒㄧㄤ","植物名。百合科山慈姑屬，多生年草本。原產於小亞細亞。葉接莖下部互生，呈廣披針形或橢圓狀披針形，葉緣略向內捲。花似倒鐘形，亦稱為「鬱金香」，花瓣六片，有單瓣也有重瓣，很容易產生變種。原種為白色紅緣，另有赤、黃、白、紫等色。主供觀賞。[例]鬱金香是荷蘭花卉出口的大宗。"]],"鬼主意":[["ㄍㄨㄟˇ ㄓㄨˇ ㄧˋ","1.奸狡陰險的計謀。[例]你要小心他的鬼主意，否則到時吃虧的是你。\n2.巧妙出奇的意見。[例]這孩子鬼主意特別多，你可叫他幫你想想辦法。"]],"鬼影幢幢":[["ㄍㄨㄟˇ ㄧㄥˇ ㄔㄨㄤˊ ㄔㄨㄤˊ","鬼影搖曳。形容陰森恐怖的樣子。[例]這座廢墟夜裡總是鬼影幢幢。"]],"鬼把戲":[["ㄍㄨㄟˇ ㄅㄚˇ ㄒㄧˋ","陰險或暗中捉弄人的詭計。[例]這套騙人的鬼把戲，我早就看透了。"]],"鬼斧神工":[["ㄍㄨㄟˇ ㄈㄨˇ ㄕㄣˊ ㄍㄨㄥ","鬼神的斧斤、工夫。形容景觀奇特或技藝精巧，像是鬼神所造。[例]這件雕塑被評審們一致推崇為鬼斧神工之作。"]],"鬼混":[["ㄍㄨㄟˇ ㄏㄨㄣˋ","不做正事，糊塗度時。[例]趕快回房間準備明天的考試，不要在那兒鬼混！"]],"鬼畫符":[["ㄍㄨㄟˇ ㄏㄨㄚˋ ㄈㄨˊ","譏人字跡潦草或繪畫拙劣。[例]寫毛筆字時要細心，不能隨便鬼畫符。"]],"鬼計多端":[["ㄍㄨㄟˇ ㄐㄧˋ ㄉㄨㄛ ㄉㄨㄢ","鬼點子或壞主意很多。[例]他這人一向鬼計多端，小心別上了他的當。"]],"鬼靈精":[["ㄍㄨㄟˇ ㄌㄧㄥˊ ㄐㄧㄥ","形容聰明靈巧的人。[例]她常有一些與眾不同的小點子，真是一個鬼靈精。"]],"鬼魂":[["ㄍㄨㄟˇ ㄏㄨㄣˊ","人死後的魂魄。[例]傳說人死後鬼魂在第七天會回家探視。"]],"魁梧":[["ㄎㄨㄟˊ ㄨˊ","形容體型高大壯碩。[例]他的身材魁梧，又受過武術訓練，最適合當保全人員。"]],"魂牽夢縈":[["ㄏㄨㄣˊ ㄑㄧㄢ ㄇㄥˋ ㄧㄥˊ","縈，旋繞。魂牽夢縈形容十分掛念、思念的樣子。[例]在外飄泊多年，今天他終於回到魂牽夢縈的故鄉。"]],"魅力":[["ㄇㄟˋ ㄌㄧˋ","吸引人的力量。[例]他很有魅力，使人不自覺地想親近他。"]],"魔法":[["ㄇㄛˊ ㄈㄚˇ","具有神祕色彩的法術。[例]相傳巫師具有治病、驅邪的魔法。"]],"魔王":[["ㄇㄛˊ ㄨㄤˊ","1.佛家指天魔中的王，為妨害人修道行善的鬼類。[例]在佛教的說法中，有大修行的人才會遭到魔王的侵擾。\n2.比喻極端殘酷，沒有人性的人。[例]殺人魔王"]],"魔術":[["ㄇㄛˊ ㄕㄨˋ","利用各種道具，以祕密且快速的手法，做出超乎常理的表演。[例]他空手變出活鯉魚的魔術，博得滿堂喝采。"]],"魚兒":[["ㄩˊㄦ","魚。[例]河川沒有汙染，魚兒才能悠游自在的在水中生活。"]],"魚塭":[["ㄩˊ ㄨㄣ","在海邊平地上，挖掘出來引水養殖魚類的池塘。[例]嘉南沿海地區闢有不少養殖虱目魚的魚塭。"]],"魚池":[["ㄩˊ ㄔˊ","為養魚而挖鑿的池沼。[例]釣魚的風行，使得不少業者開放魚池供人垂釣。"]],"魚網":[["ㄩˊ ㄨㄤˇ","捕魚的網。[例]魚網要經常修補，捕魚時才能發揮功用。"]],"魚缸":[["ㄩˊ ㄍㄤ","養魚的容器。[例]他定期清洗魚缸，讓金魚有良好的生活環境。"]],"魚苗":[["ㄩˊ ㄇㄧㄠˊ","剛由魚卵孵化成的魚仔。[例]寒流來襲前，養殖戶已做好防寒工作保護魚苗。"]],"魚蝦":[["ㄩˊ ㄒㄧㄚ","魚和蝦。泛指各種水產。[例]湖中的魚蝦是當地居民重要的食物來源。"]],"魚販":[["ㄩˊ ㄈㄢˋ","販賣魚貨的人。[例]魚販將客人選好的魚剖腹去鱗，作初步的處理。"]],"魯莽":[["ㄌㄨˇ ㄇㄤˇ","粗心、冒失。[例]他行事魯莽，還請多包涵。"]],"鮮明":[["ㄒㄧㄢ ㄇㄧㄥˊ","1.色彩鮮豔耀眼。[例]這件衣服色彩鮮明，非常搶眼。\n2.清楚、明確。[例]童年時學騎腳踏車的經驗，至今仍記憶鮮明。"]],"鮮花":[["ㄒㄧㄢ ㄏㄨㄚ","新鮮的花。[例]她帶著一束鮮花到醫院探望病中的好友。"]],"鮮血":[["ㄒㄧㄢ ㄒㄧㄝˇ","剛從身上流出的鮮紅血液。[例]他不小心割傷了手，鮮血直流。"]],"鮮豔":[["ㄒㄧㄢ ㄧㄢˋ","鮮明亮麗。[例]今晚姊姊穿著鮮豔的衣服參加畢業舞會。"]],"鯉魚":[["ㄌㄧˇ ㄩˊ","→鯉"]],"鯊魚":[["ㄕㄚ ㄩˊ","→鯊"]],"鯨豚":[["ㄐㄧㄥ ㄊㄨㄣˊ","鯨與海豚的合稱，同屬脊椎動物門哺乳綱鯨目。[例]趁著好天氣出海，遊客看到鯨豚的美麗身影，驚喜連連。"]],"鯨魚":[["ㄐㄧㄥ ㄩˊ","→鯨"]],"鱗次櫛比":[["ㄌㄧㄣˊ ㄘˋ ㄐㄧㄝˊ ㄅㄧˋ","像魚鱗和梳齒那樣相次排列。形容建築物排列的密集。[例]在現代化的都市中，建物往往鱗次櫛比。"]],"鳥巢":[["ㄋㄧㄠˇ ㄔㄠˊ","鳥窩。[例]每個鳥巢都是小鳥用嘴巴一點一滴築起來的。"]],"鳥瞰":[["ㄋㄧㄠˇ ㄎㄢˋ","1.從高處俯視低處。[例]站在陽明山上鳥瞰臺北市，所有的建築物和街道就像模型般小巧可愛。\n\t\n2.概略觀察事實情況。"]],"鳳凰木":[["ㄈㄥˋ ㄏㄨㄤˊ ㄇㄨˋ","植物名。蘇木科鳳凰木屬，落葉中喬木。二回羽狀複葉，花序繖（ㄙㄢˇ）房狀，夏季盛開，花瓣五片，焰紅色，雄蕊十枚，莢果扁平、木質。主供觀賞，為極佳的行道樹及庭園樹，木材亦可供為薪炭之用。"]],"鳳蝶":[["ㄈㄥˋ ㄉㄧㄝˊ","動物名。節肢動物昆蟲綱鱗翅目鳳蝶科。體長寸許，翅甚大，後翅突出如尾狀。以柑橘類等樹的葉子為食。[例]闊尾鳳蝶是臺灣最名貴的蝴蝶，可說是我國的國蝶。　◎"]],"鳴笛":[["ㄇㄧㄥˊ ㄉㄧˊ","使哨子或類似的發聲器發出聲響。[例]待裁判鳴笛之後，這場籃球比賽正式開始。"]],"鴉雀無聲":[["ㄧㄚ ㄑㄩㄝˋ ㄨˊ ㄕㄥ","形容非常寂靜。[例]老師一走進教室後，全班同學立刻鴉雀無聲。"]],"鴨子":[["ㄧㄚ ˙ㄗ","→鴨"]],"鴨蛋":[["ㄧㄚ ㄉㄢˋ","1.鴨所產的卵。[例]市面上鴨蛋的主要來源為菜鴨。　△鴨子兒\n2.因鴨蛋的形狀像阿拉伯數字的0，故用以比喻零分。[例]他上一次數學考了鴨蛋，自此努力用功，果然大有進步。"]],"鴿子":[["ㄍㄜ ˙ㄗ","→鴿"]],"鷸蚌相爭":[["ㄩˋ ㄅㄤˋ ㄒㄧㄤ ㄓㄥ","比喻兩相爭執必會造成兩敗俱傷，而讓第三者獲利的局面。典出《戰國策．燕策二》。[例]鷸蚌相爭，漁翁得利。"]],"鷹架":[["ㄧㄥ ㄐㄧㄚˋ","建築物及結構物建造進行中，為便於施工人員通行、搬運、立足等的架構。常以竹材、鋼材等構成。[例]他不慎從工地的鷹架上跌落，受了重傷。"]],"鸚鵡":[["ㄧㄥ ㄨˇ","動物名。鳥綱鸚鵡目。體長約三十公分，嘴大而短，上嘴鉤曲覆下嘴，舌肥厚，善模仿人語。羽毛顏色鮮豔。棲於熱帶森林或巖洞樹穴中。[例]鸚鵡會模仿各種聲音，包括人類的語言，但卻不了解話中的意義。　△能言鳥　◎"]],"鹹菜":[["ㄒㄧㄢˊ ㄘㄞˋ","鹽漬或醬漬的蔬果。[例]媽媽醃漬了一罈鹹菜，風味絕佳。"]],"鹹魚":[["ㄒㄧㄢˊ ㄩˊ","用鹽醃漬過的魚或指晒乾的海魚。[例]媽媽煎了一塊鹹魚，讓我帶便當。"]],"麥芽糖":[["ㄇㄞˋ ㄧㄚˊ ㄊㄤˊ","穀物胚芽中的澱粉酶把澱粉分解製成糖，這種糖稱為「麥芽糖」。是一種有機化合物，為兩分子葡萄糖組成的雙醣類。易溶於水，甜味不及蔗糖，主要用於食品工業上，可作滋養劑，及製造糖果、酒精。[例]糖葫蘆外面裹著一層麥芽糖，甜甜的，是小孩子喜歡的零食。"]],"麵包":[["ㄇㄧㄢˋ ㄅㄠ","於麵粉中加水、酵母等調勻，捏成麵糰，待發酵後烘烤而成的食品。[例]母親每早都會為我準備兩個麵包當早餐。"]],"麵團":[["ㄇㄧㄢˋ ㄊㄨㄢˊ","麵粉加入液體揉成的塊狀物。[例]師傅用各色的麵團捏製出造型可愛的動物麵包。"]],"麵條":[["ㄇㄧㄢˋ ㄊㄧㄠˊ","麵粉製成的條狀食品。[例]媽媽說要等水煮開了才能下麵條。"]],"麵粉":[["ㄇㄧㄢˋ ㄈㄣˇ","用小麥磨製而成的粉。[例]麵粉經加水、發酵等加工處理可以做成多種食品。"]],"麻煩":[["ㄇㄚˊ ㄈㄢˊ","1.煩瑣、費事。[例]這件糾紛處理起來非常麻煩。\n2.令人煩心困擾的事。[例]他常在外胡作非為，給家裡添了不少麻煩。\n3.使人費心或增加負擔。常用於請人幫忙的客套話。[例]這件事就麻煩你了。"]],"麻繩":[["ㄇㄚˊ ㄕㄥˊ","細麻搓製成的繩索。[例]麻繩經過潤溼後，更具韌性。　△麻繩子"]],"麻醉":[["ㄇㄚˊ ㄗㄨㄟˋ","1.醫學上為便於施行外科手術，或其他劇痛的處置，利用藥物使人局部性或全身性暫時喪失感覺的方法。[例]全身麻醉、半身麻醉、局部麻醉\n2.比喻利用某種方式，使人沉迷不思振作。[例]他最近經常藉酒來麻醉自己。"]],"麻醉劑":[["ㄇㄚˊ ㄗㄨㄟˋ ㄐㄧˋ","1.能令人暫時失去知覺的藥劑。[例]手術時麻醉劑的施用，須由專科醫生負責。　△麻藥\n2.比喻能使人忘記傷痛、不如意的事物。[例]他以忙碌來作為忘記傷痛的麻醉劑。"]],"麻雀":[["ㄇㄚˊ ㄑㄩㄝˋ","1.動物名。雀形目。圓頭，短尾，栗褐色，身上雜有黑褐色斑點，翅膀短小，善於跳躍，以穀粒和昆蟲為主要食物。[例]在田裡常見農人用稻草人嚇走麻雀。　△老家子、老家賊、家雀　◎\n2.一種骨牌遊戲。共一百四十四張牌，其中有八張花牌。四人玩，供消遣或賭博用。　△麻將牌"]],"黃昏":[["ㄏㄨㄤˊ ㄏㄨㄣ","太陽將落，天快黑的時候。[例]夏天黃昏時，爸爸喜歡在榕樹下乘涼。"]],"黃澄澄":[["ㄏㄨㄤˊ ㄔㄥˊ ㄔㄥˊ","形容顏色金黃鮮明。[例]休耕期間，原本綠油油的稻浪都成了黃澄澄的油菜花海。"]],"黃牛":[["ㄏㄨㄤˊ ㄋㄧㄡˊ","1.動物名。哺乳綱偶蹄目。為農業社會裡的主要農耕動物，因其毛多呈黃色，故稱為「黃牛」。[例]在農田犁地未機械化之前，黃牛是農村主要的勞役動物。\n2.一種專門在車站或戲院等處搶先買票，再以高價售出而從中獲利的人。[例]警方大力掃蕩黃牛，以維護消費者的權利。\n3.替人賄賂關說以謀取利益的人。[例]司法黃牛\n4.爽約、失約。[例]今晚說好請我吃飯，可別黃牛喔！"]],"黃色":[["ㄏㄨㄤˊ ㄙㄜˋ","1.像金子或向日葵的顏色。[例]她穿了一件黃色的碎花洋裝，顯得非常耀眼奪目。_x000D_\n2.指與色情有關的。[例]黃色笑話、黃色書刊"]],"黎明":[["ㄌㄧˊ ㄇㄧㄥˊ","天快亮的時候。[例]他每天黎明時分便到附近的公園運動健身。"]],"黏土":[["ㄋㄧㄢˊ ㄊㄨˇ","具塑性與黏性的土壤，由細粒的礦物所組成。依成分的不同，可用於燒製磚、瓦、陶瓷器，或其他工業製品。[例]他常用黏土捏製一些小玩意兒，作為家中的擺設。"]],"黏稠":[["ㄋㄧㄢˊ ㄔㄡˊ","濃稠有黏性的。[例]柏油燒熔之後變成黏稠的液體。"]],"黏答答":[["ㄋㄧㄢˊ ㄉㄚ ㄉㄚ","形容溼溼黏黏的樣子。[例]下了一場大雨，屋外的泥地黏答答的，很不好走。"]],"黑板":[["ㄏㄟ ㄅㄢˇ","以木頭製成，可以在上面用粉筆書寫、圖繪的板子。通常為黑色或綠色，多用於教學。[例]老師在黑板上寫下課文的結構分析表，以便同學作筆記。"]],"黑漆漆":[["ㄏㄟ ㄑㄧ ㄑㄧ","非常黑暗的樣子。[例]停電的夜晚，到處黑漆漆一片，什麼也看不見。"]],"黑色":[["ㄏㄟ ㄙㄜˋ","1.像煤或墨般深暗的顏色。_x000D_\n2.比喻恐怖的情境。[例]這部靈異電影是齣黑色喜劇片，在恐怖中點綴著幽默，很耐人尋味。"]],"默契":[["ㄇㄛˋ ㄑㄧˋ","不經語言傳達而彼此心意暗合。[例]他們倆很有默契，不約而同的穿同樣的衣服。"]],"默許":[["ㄇㄛˋ ㄒㄩˇ","內心表示同意。[例]他雖然口中不說，心中其實早已默許。"]],"默認":[["ㄇㄛˋ ㄖㄣˋ","內心認可，而不表示出來。[例]他雖然不回答，但並不表示默認。"]],"默默":[["ㄇㄛˋ ㄇㄛˋ","沉靜不說話。[例]默默不語、默默無言"]],"黝黑":[["ㄧㄡˇ ㄏㄟ","深黑或青黑。[例]喜歡游泳的他，皮膚經常是黝黑的。"]],"點券":[["ㄉㄧㄢˇ ㄑㄩㄢˋ","商家為促銷商品或提供折扣優惠時，附贈給顧客的兌換憑證，累積一定點數後，即可兌換商品或獎品。[例]這家商店推出購物附贈點券，並可累計兌換的優惠活動，以吸引顧客。"]],"點名":[["ㄉㄧㄢˇ ㄇㄧㄥˊ","1.按名冊一一點喚查對。[例]這位老師很嚴格，每次上課前一定點名。\n2.指名。[例]長官為了要測試他的能力，點名要他做這件事。"]],"點子":[["ㄉㄧㄢˇ ˙ㄗ","計謀、主意。[例]小張的腦筋靈活，時常替人出點子！"]],"點滴":[["ㄉㄧㄢˇ ㄉㄧ","1.形容零星微小。[例]成功是由血汗與努力點滴匯聚而成的。\n2.俗稱醫療時，靜脈注射的藥劑。如葡萄糖、生理食鹽水等。[例]護士正在替病人打點滴。"]],"點燃":[["ㄉㄧㄢˇ ㄖㄢˊ","引火使其燃燒。[例]選手代表手持火把，點燃聖火，運動會便由此揭開序幕。"]],"點綴":[["ㄉㄧㄢˇ ㄓㄨㄟˋ","襯托裝飾。[例]閃爍的星光將夜空點綴得萬般迷人。"]],"黯淡":[["ㄢˋ ㄉㄢˋ","1.陳舊、灰暗、不明亮的樣子。[例]今晚月亮被部分烏雲遮住了，月光有些黯淡。\n2.形容景象悲慘。[例]前途黯淡"]],"黯然失色":[["ㄢˋ ㄖㄢˊ ㄕ ㄙㄜˋ","黯淡而失去光彩。[例]那幅畫色彩風格強烈，技法純熟，令其他參賽作品黯然失色。"]],"鼎邊趖":[["ㄉㄧㄥˇ ㄅㄧㄢ ㄙㄨㄛ","一種臺灣小吃。先在大鍋中煮湯，待鍋邊燒熱後抹油，將在來米漿沿著鍋邊淋下，熟透後鏟入或自動脫落湯中，再加上蔥、薑、金針、香菇、魷魚等配料煮成。"]],"鼓勵":[["ㄍㄨˇ ㄌㄧˋ","鼓舞、激勵。[例]大學畢業後，父親鼓勵我繼續出國深造。"]],"鼓噪":[["ㄍㄨˇ ㄗㄠˋ","1.古代出戰時擊鼓吶喊，用以擴張聲勢。[例]軍隊鼓噪而進，以增加士氣。\n2.眾人一起發出呼喊喧鬧的聲音。[例]會場裡因大家的鼓噪，而顯得吵雜不已。"]],"鼓譟":[["ㄍㄨˇ ㄗㄠˋ","眾人一起發出呼喊喧鬧的聲音。[例]在友人的鼓譟下，他上臺獻唱一曲。"]],"鼻子":[["ㄅㄧˊ ˙ㄗ","動物的呼吸器官之一，內有黏膜及嗅神經，亦為嗅覺器官。[例]他將鼻子湊上去聞了聞，說：「這花好香啊！」　△鼻　◎"]],"鼻涕":[["ㄅㄧˊ ㄊㄧˋ","鼻腔內分泌的黏液。[例]瞧你都這麼大了，還為這種事哭得一把鼻涕一把眼淚的。"]],"鼻祖":[["ㄅㄧˊ ㄗㄨˇ","始祖、創始人。[例]他可說是國內研究遺傳工程學的鼻祖。"]],"齒輪":[["ㄔˇ ㄌㄨㄣˊ","周緣呈齒狀排列的輪狀物，一齒輪的轉動，可因齒的囓合，帶動另一齒輪的轉動，而節省動力。[例]由於齒輪可以節省動力，所以被廣泛運用在各種機械上。"]],"齒頰留香":[["ㄔˇ ㄐㄧㄚˊ ㄌㄧㄡˊ ㄒㄧㄤ","形容食物味道鮮美，令人回味無窮。[例]張家的牛肉麵湯頭道地，只喝一口便覺齒頰留香。"]],"齜牙咧嘴":[["ㄗ ㄧㄚˊ ㄌㄧㄝˇ ㄗㄨㄟˇ","1.張嘴露牙。形容凶狠的樣子。[例]看他齜牙咧嘴，瞠目一喝，把那娃兒嚇哭了。\n2.形容因痛苦或驚恐而面部扭曲變形。[例]不小心絆了一腳，痛得他齜牙咧嘴的。"]],"龍困淺灘":[["ㄌㄨㄥˊ ㄎㄨㄣˋ ㄑㄧㄢˇ ㄊㄢ","比喻有才華的人處在困厄的環境，無法施展才能。[例]想當年他在商場上叱吒風雲，如今卻落得在一家小公司當職員，豈不是龍困淺灘，虎落平陽啊！"]],"龍舟":[["ㄌㄨㄥˊ ㄓㄡ","刻飾成龍形的船。多在端午節用來舉行划船競速比賽。[例]端午節吃粽子、划龍舟的習俗，是為了紀念愛國詩人屈原。"]],"龍鬚":[["ㄌㄨㄥˊ ㄒㄩ","植物名。燈心草科燈心草屬，多年生草本。種植於水田中，夏開綠色小花，莖似燈心草，可織席。[例]龍鬚雖與燈心草相似，但莖幹較為短小。　△龍鬚草、石龍芻、蓑草"]],"龐然":[["ㄆㄤˊ ㄖㄢˊ","體形巨大的樣子。[例]龐然大物"]],"龜甲":[["ㄍㄨㄟ ㄐㄧㄚˇ","龜的甲殼。古人用來占卜，晒乾後亦可作藥品，稱為「龜版」。[例]刻在龜甲、獸骨上的甲骨文，是研究中國早期歷史的珍貴史料。　△龜骨、龜殼"]]};
